P.entries["npc:merissa-stilwell"] = {n="梅里萨·斯蒂维尔",s="梅里萨·斯蒂维尔是一位居住在艾尔文森林北郡修道院的年轻人类城镇居民。她站在修道院附近，微笑着迎接并在北郡山谷受训的新手提供帮助。",h="梅里萨·斯蒂维尔是一位居住在艾尔文森林北郡修道院的年轻人类城镇居民。她站在修道院附近，微笑着迎接并在北郡山谷受训的新手提供帮助。",kw={"艾尔文","梅里萨","北郡","斯蒂维尔"},ang={["faction:Alliance"]="对于那些即将离开北郡封闭修道院的联盟新兵来说，梅里萨代表了在迪菲亚兄弟会的威胁接踵而至之前，艾尔文森林那份温暖的好客之情。"},sec={{t="北郡的迎宾面孔",b="梅里萨·斯蒂维尔站在北郡修道院，迎接来到北郡山谷的新兵。对于漫游至此的新手，她会提供简单的待客之道以及休息和定位方面的实用建议。她与王国中著名的工匠和家园守护者——例如铁匠乔丹·斯迪威尔和西部荒野的保卫者达芙妮·斯迪威尔——有着相同的姓氏，但在王国日益紧张的局势下，她依然保持着宁静的平民面貌。"}},faq={{q="梅里萨·斯蒂维尔是谁？",a="梅里萨是一位生活在艾尔文森林北郡修道院的友善人类居民，她为抵达那里的旅者提供建议和热情的欢迎。",al={"梅里萨·斯蒂维尔","梅里萨是谁","北郡的斯蒂维尔女孩"}},{q="我在哪里可以找到梅里萨·斯蒂维尔？",a="她位于艾尔文森林北郡山谷的北郡修道院。",al={"梅里萨·斯蒂维尔位置","梅里萨在哪里","寻找梅里萨"}},{q="梅里萨与王国里的其他斯蒂维尔家族成员有关系吗？",a="虽然她与铁匠乔丹·斯迪威尔和西部荒野的达芙妮·斯迪威尔等知名人物有着相同的姓氏，但她安静地生活在北郡修道院，负责迎接旅者，而不是与迪菲亚兄弟会作战或锻造刀剑。",al={"斯蒂维尔家族","达芙妮·斯迪威尔亲属","乔丹·斯迪威尔亲属"}},{q="梅里萨·斯蒂维尔提供任务吗？",a="不提供。她没有给旅者安排任何任务；她只是迎接那些路过北郡的新人。",al={"梅里萨的任务","梅里萨·斯蒂维尔任务"}}},fx={a071eba0={q="梅里萨·斯蒂维尔属于哪一方？",a="梅里萨·斯蒂维尔是大联盟和暴风王国的忠诚臣民。她平静地居住在北郡修道院，欢迎来到山谷的旅人和新兵。",al={"梅里萨·斯蒂维尔的阵营","梅里萨·斯蒂维尔是联盟成员吗"}},["57a6fac4"]={q="梅里萨·斯蒂维尔为什么在北郡？",a="梅里萨每天都在北郡修道院一带活动。和王国里许多普通人一样，她在艾尔文森林安家，并欢迎来到山谷的新来者。",al={"梅里萨·斯蒂维尔为什么在这里","梅里萨在北郡做什么"}}},fp="16,219,30.449.0,24.144.0,34.74.0,57.222.0,39.106.0"}
P.entries["npc:merrin-rockweaver"] = {n="麦琳·石纹",s="麦琳·石纹是一名代表铁炉堡探险者协会在湿地进行研究的矮人。在维尔加挖掘场遭到迅猛龙群肆虐并失陷后，她与勘察员维尔加一同在俯瞰挖掘场的一处山脊上避难。",h="麦琳·石纹是一名代表铁炉堡探险者协会在湿地进行研究的矮人。在维尔加挖掘场遭到迅猛龙群肆虐并失陷后，她与勘察员维尔加一同在俯瞰挖掘场的一处山脊上避难。",kw={"探险者协会","麦琳·石纹","迅猛龙","挖掘任务","湿地","维尔加挖掘场","维尔加的撤离点"},ang={["faction:Alliance"]="麦琳代表了铁炉堡在湿地的学术力量，确保她的研究成果安全有助于维持联盟在这片荒野沼泽中脆弱的立足点。",["race:Dwarf"]="对于矮人冒险者来说，帮助麦琳不仅是国家遗产的问题，更是为了保护探险者协会冒着生命危险发掘出的宝贵泰坦圣物和历史记录。"},sec={{t="挖掘导致的流离失所",b="麦琳·石纹代表铁炉堡探险者协会前往湿地，旨在发掘埋藏在泥沼之下的古代泰坦秘密。当他们挖掘出的大型骨骼引来了迅猛龙后，这次探险以灾难告终。凶猛的史前野兽蜂拥而至，占领了挖掘壕沟，迫使麦琳和幸存的队员抛弃了设备、笔记和研究进度。她现在和少数幸存者一起被困在俯瞰着被占领遗迹的一处悬崖上。"},{t="拯救行动",b="被困在悬崖上，幸存者们拒绝让这次探险彻底失败。当奥莫尔·铁衣策划向这些野兽复仇，而勘察员维尔加试图找回遗留在迅猛龙盘踞的壕沟里的石板碎片时，麦琳的心思却转向了她的丈夫塔瑞尔，他已经几周没有收到她的消息了。她指望侦察兵隆布雷德派来寻找队伍的人能把他们的困境传达给他。"}},faq={{q="谁是麦琳·石纹？",a="麦琳·石纹是一名隶属于铁炉堡探险者协会的矮人考古学家。在迅猛龙占领挖掘场之前，她一直驻扎在湿地的维尔加挖掘场。",al={"麦琳·石纹背景故事","麦琳是谁","湿地 矮人 麦琳"}},{q="她为什么被困在挖掘场上方？",a="被队员们发现的大型骨骼吸引而来的杂色迅猛龙淹没了下方的挖掘场，许多人因此丧生。当麦琳和勘察员维尔加逃往附近悬崖时，奥莫尔·铁衣保护了他们，现在他们仍被困在那里。",al={"为什么麦琳在撤离点","维尔加的撤离点 麦琳","她的营地发生了什么"}},{q="麦琳需要什么帮助？",a="麦琳需要有人带一封信给她的丈夫塔瑞尔，向他解释这场灾难。自从她的信件停止寄出以来，他一直担忧不已。",al={"麦琳的任务","麦琳·石纹的职责","挖掘任务背景故事"}},{q="探险队试图寻找什么？",a="像大多数探险者协会的行动一样，湿地挖掘任务旨在发掘与矮人祖先以及隐藏在整个卡兹莫丹各处的神秘泰坦圣物相关的古代文物。",al={"他们在挖什么","挖掘场目的"}}},fx={["86a5e24a"]={q="麦琳·石纹属于哪一方？",a="麦琳·石纹坚定地支持铁炉堡矮人和联盟。她是一位活跃的勘测员，也是探险者协会的成员，效忠于从铁炉堡出发、前往卡兹莫丹各地探寻矮人古老起源的学者和发掘者。",al={"麦琳·石纹的阵营","麦琳·石纹的归属","麦琳效忠于谁"}},f33c6ea8={q="麦琳·石纹与谁有关联？",a="麦琳在湿地的发掘现场协助勘察员维尔加的远征队。奥莫尔·铁衣则帮助他们抵御营地周围的迅猛龙。",al={"麦琳·石纹的人脉","麦琳·石纹的同伴","麦琳与谁共事"}}},fp="17,250,20.459.0,23.426.0,25.195.0,38.234.0,32.152.0,39.192.0"}
P.entries["npc:miles-welsh"] = {n="麦尔斯·威尔什",s="麦尔斯·威尔什是一名被遗忘者牧师训练师，居住在雷霆崖下方的预见之池深处。他为穿梭于牛头人主城的牧师们提供精神指导和暗影训练。",h="麦尔斯·威尔什是一名被遗忘者牧师训练师，居住在雷霆崖下方的预见之池深处。他为穿梭于牛头人主城的牧师们提供精神指导和暗影训练。",kw={"噬灵瘟疫","被遗忘者","麦尔斯·威尔什","预见之池","牧师训练师","灵魂高地","雷霆崖"},ang={["class:Priest"]="对于穿行在卡利姆多的牧师来说，麦尔斯·威尔什是部落中部领地内为数不多可以学习新法术和进阶精神训练的地方之一。",["race:Undead"]="在这座充满泥土气息和阳光普照的牛头人主城里，麦尔斯提供了一张来自洛丹伦的、令人熟悉且冰冷的面孔。"},sec={{t="洞穴中的阴影",b="麦尔斯·威尔什远离了洛丹伦废墟那片遭受瘟疫蹂躏的土地，在雷霆崖下方潮湿且充满灵气的预见之池安了家。作为一名被遗忘者牧师，他指导着那些引导神圣与暗影能量的旅者。他身处莫高雷的心脏地带，反映了被遗忘者与部落之间那脆弱的外交纽带，他与牛头人神秘学家和萨满祭司共享这一圣地，同时引导着学徒们掌握暗影与信仰的技艺。"}},faq={{q="麦尔斯·威尔什是谁？",a="麦尔斯·威尔什是一名亡灵牧师训练师，驻扎在雷霆崖下的预见之池，协助部落牧师进行训练和专业训练。",al={"麦尔斯·威尔什的角色","谁是麦尔斯·威尔什","麦尔斯·威尔什牧师训练师"}},{q="我在哪里可以找到麦尔斯·威尔什？",a="他位于预见之池，这是雷霆崖灵魂高地下方的一个地下洞穴系统，通过台地上的一个洞穴入口可以进入。",al={"麦尔斯·威尔什位置","麦尔斯·威尔什在哪里","如何找到麦尔斯·威尔什"}},{q="为什么雷霆崖会有亡灵牧师训练师？",a="被遗忘者和牛头人是部落内的盟友。牛头人，特别是玛加萨·野性图腾，主张接纳被遗忘者加入部落，这使得像麦尔斯·威尔什这样的使节和训练师能够在莫高雷提供他们的服务。",al={"为什么被遗忘者会在雷霆崖","牛头人城市里的亡灵牧师"}},{q="他教授什么能力？",a="麦尔斯·威尔什教授通用牧师法术，并协助寻求专业种族教学的被遗忘者和巨魔学徒，例如“虚弱之触”或“暗影守卫”。",al={"雷霆崖牧师法术","麦尔斯·威尔什教授什么"}}},fx={c3aae6f3={q="麦尔斯·威尔什属于哪一方？",a="麦尔斯·威尔什支持被遗忘者和整个部落。牛头人遵循以大地母亲为核心、截然不同的灵性之道；麦尔斯则住在他们台地下方，与他们结盟，为寻求此道的部落旅人传授祭司之道。",al={"麦尔斯·威尔什的阵营","麦尔斯·威尔什属于部落还是联盟","麦尔斯·威尔什效忠于谁"}},["9239b409"]={q="麦尔斯·威尔什想要什么？",a="麦尔斯·威尔什担任来访雷霆崖的其他牧师的导师。在隐秘的预见之池深处，他向踏上暗影与信仰之路的人分享自己的戒律与黑暗法术，确保部落的信徒即使远离洛丹伦，也能得到指引。",al={"麦尔斯·威尔什做什么","麦尔斯·威尔什的职责","麦尔斯·威尔什的目标"}},["03472250"]={q="麦尔斯·威尔什与谁有关联？",a="麦尔斯·威尔什与幽暗城的被遗忘者关系密切。他现身雷霆崖，与被遗忘者使者和旅人并肩而行；凯恩·血蹄的族人和希尔瓦娜斯·风行者的追随者刚刚缔结盟约，他们因此获准进入牛头人的都城。",al={"麦尔斯·威尔什的盟友","麦尔斯·威尔什为谁效力","麦尔斯·威尔什的人脉"}}},fp="11,200,23.469.0,19.166.0,29.154.0,49.236.0,29.160.0"}
P.entries["npc:milli-featherwhistle"] = {n="米利·羽哨",s="米利·羽哨是一位精通机械陆行鸟制造的侏儒工程师，驻扎在丹莫罗的钢架补给站。在诺莫瑞根陷落后，她一丝不苟地手工打造并维护着深受族人青睐的机械坐骑。她将自己珍视的机械作品出售给其他侏儒，以及诺莫瑞根流亡者值得信赖的盟友。",h="米利·羽哨是一位精通机械陆行鸟制造的侏儒工程师，驻扎在丹莫罗的钢架补给站。在诺莫瑞根陷落后，她一丝不苟地手工打造并维护着深受族人青睐的机械坐骑。她将自己珍视的机械作品出售给其他侏儒，以及诺莫瑞根流亡者值得信赖的盟友。",kw={"丹莫罗","诺莫瑞根","卡拉诺斯","机械陆行鸟","mekkatorque","米利·羽哨","坐骑商人","钢架补给站"},ang={["faction:Alliance"]="赢得了诺莫瑞根流亡者极高敬意的联盟英雄，可以寻找米利来驾驭艾泽拉斯最迅捷的机械坐骑之一。",["profession:Engineering"]="米的机械陆行鸟代表了大型侏儒动力技术的巅峰，结合了陀螺仪平衡装置和高扭矩机械腿。",["race:Gnome"]="米利·羽哨是你们种族的首要坐骑工程师，即使在流亡地底家园的情况下，她依然传承着大工匠Mekkatorque的技术天赋。"},sec={{t="机械陆行鸟大师",b="米利·羽哨在卡拉诺斯以东的钢架补给站顶着刺骨的寒风工作，负责为诺莫瑞根的流离失所的民众供应机械坐骑。与矮人和暗夜精灵偏爱的生物坐骑不同，米利的每一件库存都是亲手制造的，她亲自校准齿轮、活塞和平衡陀螺仪，以确保每一只机械鸟都能在丹莫罗的冰雪山崖上以最佳效率运行。"},{t="大工匠的遗产",b="米利工作室里的每一个框架和弹簧，都源自大工匠Gelbin Mekkatorque最初起草的蓝图。虽然米利多年来融入了现代性能改进——简化了底盘重量并优化了排气孔——但她始终忠实地遵循大工匠的基础设计方案。她的机械奇迹证明了即便身处流亡之中，侏儒的技术雄心依然丝毫未损。"}},faq={{q="米利·羽哨是谁？",a="米利·羽哨是诺莫瑞根侏儒主要的机械陆行鸟培育师和工程师。她驻扎在丹莫罗的钢架补给站，手工制造并向符合条件的骑手出售机械陆行鸟。",al={"米利·羽哨","米利是谁","机械陆行鸟商人"}},{q="我在哪里可以找到米利·羽哨？",a="她位于钢架补给站，这是一个工程哨站，从丹莫罗的卡拉诺斯镇沿路向东走一小段路即可到达。",al={"米利的位置","米利·羽哨在哪里","寻找米利"}},{q="谁有权向她购买坐骑？",a="默认情况下，只有侏儒冒险者拥有直接购买她作品的权限和天赋。其他联盟种族的成员必须在诺莫瑞根流亡者中赢得极高的声望并达到崇拜，她才会放心地将机械陆行鸟交给他们。",al={"我可以购买机械陆行鸟吗","机械陆行鸟要求","谁可以骑机械陆行鸟"}},{q="机械陆行鸟是如何制造的？",a="米利·羽哨亲自制造每一只机械陆行鸟，她的制造基础是大工匠Gelbin Mekkatorque所起草的标志性蓝图，同时融入了定制的引擎和平衡增强组件。",al={"机械陆行鸟是如何制造的","谁制造机械陆行鸟","机械陆行鸟起源"}},{q="她提供哪些种类的坐骑？",a="她提供多种校准过的型号，从标准的未涂装、蓝色、绿色和红色框架，到经过精细调校的白色、绿色和黄色涂装的高速变体。",al={"米利的坐骑颜色","机械陆行鸟型号","米利出售什么坐骑"}},{q="她为什么在钢架补给站的雪地里工作？",a="在放射性灾难和穴居人入侵导致侏儒被迫离开诺莫瑞根后，难民们四散而去。钢架补给站成为了卡拉诺斯外的一个天然集散中心，用于与矮人工程师并肩进行车辆测试和机械维护。",al={"为什么米利在丹莫罗","为什么是钢架补给站"}}},fx={["2267a2b3"]={q="米利·羽哨属于哪一方？",a="米利·羽哨忠于诺莫瑞根和大联盟。她与矮人工匠一同在钢架补给站工作，为侏儒同胞以及赢得诺莫瑞根流亡者完全信任的联盟勇士提供机械陆行鸟。",al={"米利·羽哨的阵营","米利·羽哨效忠于谁","米利是联盟成员吗"}},f07f7c95={q="米利·羽哨想要什么？",a="米利希望在丹莫罗打造并维护最出色的机械陆行鸟。她以大工匠梅卡托克的原始设计图为基础，不断改进机械陆行鸟的工程设计，让侏儒旅人和可靠盟友随时都能获得性能可靠的机械坐骑。",al={"米利·羽哨做什么","米利·羽哨的目标","米利想做什么"}}},fp="20,342,25.441.0,21.432.0,28.220.0,38.147.0,43.262.0,29.206.0,36.178.0,57.271.0"}
P.entries["npc:milton-sheaf"] = {n="米尔顿·西弗",s="米尔顿·西弗是位于暴风城内的Royal Library的首席图书管理员。他致力于保护王国的历史，负责监管王国收藏的古代典籍和历史编年史。他经常招募联盟的旅行者去寻回丢失的卷册、追踪散落的记录，并修复被遗忘的手稿。",h="米尔顿·西弗是位于暴风城内的Royal Library的首席图书管理员。他致力于保护王国的历史，负责监管王国收藏的古代典籍和历史编年史。他经常招募联盟的旅行者去寻回丢失的卷册、追踪散落的记录，并修复被遗忘的手稿。",kw={"书籍","历史","图书管理员","米尔顿·西弗","royal library","stormwind keep","典籍"},ang={["faction:Alliance"]="作为王国首屈一指的图书管理员，米尔顿·西弗致力于保护人类王国和更广泛的联盟所记录下来的遗产。",["race:Human"]="米尔顿守护着数百年的人类历史，保护着在暴风城陷落与重建中幸存下来的编年史。"},sec={{t="暴风城历史的守护者",b="米尔顿·西弗隐身于暴风城内Royal Library宁静的大厅中，照料着王国的集体记忆。当楼上的宫廷里充斥着政治斗争、贵族争吵和军事忧虑时，西弗却专注于文字的保存。他认为维护联盟和东部王国的准确历史是一项神圣的职责，尤其是在这个充满战争、失去和动荡的时代。"},{t="寻回失落的典籍",b="保存图书馆的藏书需要不断的努力。书籍会遭受磨损，而珍贵的记录往往散落在王国各地的僧侣档案馆、偏远的前哨站或被遗忘的废墟中。米尔顿经常派遣冒险者前往各处——从北郡修道院到遥远的北方定居点南海镇——去取回放错位置的卷册，调查古代文献，并确保珍稀的手稿能安全地回到城堡的书架上。"}},faq={{q="谁是米尔顿·西弗？",a="米尔顿·西弗是一位人类学者，也是位于暴风城内暴风城的Royal Library的首席保管员。他管理着王国的藏书和编年史。",al={"谁是米尔顿·西弗","米尔顿·西弗的角色","暴风城图书管理员"}},{q="我在哪里可以找到米尔顿·西弗？",a="你可以在暴风城的Royal Library侧翼找到米尔顿·西弗，它就位于主宫殿走廊旁边。",al={"米尔顿·西弗的位置","米尔顿·西弗在哪里","暴风城图书馆位置"}},{q="为什么米尔顿·西弗需要冒险者？",a="米尔顿经常依赖旅行中的联盟冒险者来追踪历史手稿、更换破损的书籍，并与王国各地的学者和牧师协调，以扩充Royal Library的档案。",al={"米尔顿·西弗的任务","米尔顿想要什么","为什么发布任务"}},{q="米尔顿·西弗会与王国里的其他学者交流吗？",a="是的。他与僧侣档案管理员和宗教学者保持着联系，包括北郡山谷的帕克斯顿修士，共同保存神圣的教义和历史记录。",al={"米尔顿与北郡","米尔顿与帕克斯顿修士","米尔顿的人脉"}}},fx={["440d1fb9"]={q="米尔顿·西弗属于哪一方？",a="米尔顿·西弗效力于暴风王国和联盟。他驻守在暴风城要塞内，直接为王室档案馆工作，编目历史资料并为王国的学者和领导者保存知识。",al={"米尔顿·西弗的阵营","米尔顿·西弗效忠于谁","米尔顿·西弗属于联盟吗"}},["1fad6188"]={q="米尔顿·西弗为什么在暴风城要塞？",a="米尔顿负责Royal Library的管理与维护。他照料王国中大量的卷轴、典籍和历史记录，确保艾泽拉斯历史的重要记载得到妥善保护，并能供宫廷查阅。",al={"米尔顿·西弗为什么在royal library","米尔顿·西弗在此处的职责","米尔顿为什么在暴风城"}}},fp="12,335,36.437.0,21.461.0,20.184.0,30.119.0,39.214.0,62.171.0"}
P.entries["npc:miner-johnson"] = {n="矿工约翰森",s="矿工约翰森是一名深藏不露、经验丰富的矿工，效力于死亡矿井深处的迪菲亚潜行者。他躲在普通劳工身旁的一处侧室中，这位危险的探矿者负责监督重型机械所在区域之前的挖掘工作。由于他在地下隧道中行踪不定，冒险者们只是偶尔才能遇到他。",h="矿工约翰森是一名深藏不露、经验丰富的矿工，效力于死亡矿井深处的迪菲亚潜行者。他躲在普通劳工身旁的一处侧室中，这位危险的探矿者负责监督重型机械所在区域之前的挖掘工作。由于他在地下隧道中行踪不定，冒险者们只是偶尔才能遇到他。",kw={"凹室","死亡矿井","迪菲亚","精英","矿工约翰森","月溪镇","稀有","伐木机","西部荒野"},ang={["faction:Alliance"]="击倒约翰森会中断流入月溪镇下方迪菲亚战争机器的稳定可冶炼矿石流。",["profession:Mining"]="对于探矿者来说，约翰森代表了地下劳作中粗犷、无法无天的一面，他用鲜血和十字镐守卫着西部荒野深处丰富的矿藏。"},sec={{t="深渊中的稀有面孔",b="虽然有数百名劳工在死亡矿井的地下矿脉中挖掘，为艾德温·范克里夫的隐秘要塞提供补给，但矿工约翰森在其中显得格外强大。他潜伏在Mast Room笨重的伐木机之前左侧的一处阴影凹室中，比普通劳工要强硬和激进得多。他那不可预测的出现让他成为了穿越迪菲亚隧道探险者们的传奇目标。"},{t="为迪菲亚战争机器提供燃料",b="迪菲亚潜行者在月溪镇下方的秘密行动需要大量的原矿来锻造武器、加固矿井并组装机械装置。像约翰森这样的矿工为这些金属提供了背后的劳动力，在西部荒野地下的丰富矿脉中辛勤挖掘。任何闯入约翰森工作区的人都会很快发现，他以致命的热情捍卫着他的挖掘场。"}},faq={{q="矿工约翰森是谁？",a="矿工约翰森是一名效力于迪菲亚潜行者的稀有精英人类矿工。他在死亡矿井深处工作，位于地精伐木机之前，与其他劳工待在一起的侧室中。",al={"矿工约翰森背景故事","矿工约翰森是谁","死亡矿井矿工约翰森"}},{q="矿工约翰森究竟在哪里？",a="他可以在死亡矿井的上层矿道中找到，在到达斯尼德和他的伐木机所在的房间之前。留意左侧一个小型的挖掘凹室，那里有一群矿工正在积极地挖掘岩石。",al={"矿工约翰森位置","矿工约翰森在哪里","如何找到矿工约翰森"}},{q="为什么矿工约翰森并不总是出现在那里？",a="矿工约翰森是一个稀有刷新怪，这意味着他只有在探险队进入死亡矿井时偶尔才会出现。大多数穿过矿井的队伍只会发现一个普通的矿工取代了他的位置。",al={"矿工约翰森不刷新","矿工约翰森是稀有怪吗","矿工约翰森刷新率"}},{q="矿工约翰森与任何任务有关吗？",a="矿工约翰森与任何正式的赏金任务无关。对于有幸发现他正在矿脉上工作的地下城探险小队来说，他仅仅是一个机会性的遭遇战。",al={"矿工约翰森任务","矿工约翰森有任务吗"}},{q="矿工约翰森在死亡矿井中扮演什么角色？",a="他是一名经验丰富的工头或挖掘大师，帮助迪菲亚潜行者开采贵金属、石材和资源，这些都是建造他们庞大的地下基地和隐藏的战争机器所必需的。",al={"矿工约翰森做什么","矿工约翰森角色"}},{q="与其他矿工相比，矿工约翰森很危险吗？",a="是的。虽然死亡矿井中随处可见的标准挖掘工相对脆弱，但矿工约翰森是一名精英战斗人员，拥有显著更高的生命力和攻击力，需要一支协调良好的队伍才能安全地击败他。",al={"矿工约翰森有多难打","矿工约翰森是精英吗"}}},fx={c0432457={q="矿工约翰森为什么会在死亡矿井？",a="他在矿道旁的一处小凹室里工作，就在碎木机前方，为迪菲亚潜行者挖掘金矿和铁矿。和普通劳工一样，他也为艾德温·范克里夫的秘密计划提供所需的原材料。",al={"矿工约翰森为什么在这里","矿工约翰森为什么在死亡矿井","是什么让矿工约翰森来到这里"}},["3a6e6cc9"]={q="矿工约翰森属于哪一方？",a="他支持迪菲亚潜行者及其劳工。他与其他工人一同在死亡矿井深处劳作，认同艾德温·范克里夫的起义；任何闯入他们地下据点的入侵者，都会遭到他挥镐迎击。",al={"矿工约翰森的阵营","矿工约翰森为谁效力","矿工约翰森是迪菲亚潜行者成员吗"}}},fp="13,379,23.446.0,30.398.0,21.192.0,39.225.0,37.202.0,35.170.0,46.198.0,52.221.0"}
P.entries["npc:minor-manifestation-of-earth"] = {n="大地之魂",s="大地之魂是束缚在莫高雷和杜隆塔尔圣石上的局部元素之灵。肉眼无法观测到它们，只有喝下神圣的大地图腾药剂的萨满学徒才能看见它们。大地之魂会提供雕刻第一个大地图腾所需的粗石英。",h="大地之魂是束缚在莫高雷和杜隆塔尔圣石上的局部元素之灵。肉眼无法观测到它们，只有喝下神圣的大地图腾药剂的萨满学徒才能看见它们。大地之魂会提供雕刻第一个大地图腾所需的粗石英。",kw={"call of earth","大地图腾药剂","大地图腾","科多石","大地之魂","粗石英","灵魂石地"},ang={["class:Shaman"]="每一位年轻的部落萨满都必须在大地图腾药剂的影响下与大地之魂沟通，以获得他们的第一个图腾。",["race:Tauren"]="牛头人青年横跨莫高雷向东前往科多石，寻求与这种灵体的沟通，作为他们祖先灵性试炼的一部分。"},sec={{t="大地之语",b="大地之灵栖息在泥土和岩石之下的每一个角落，但与它们交流需要进行庄重的仪式。在莫高雷的科多石和杜隆塔尔的灵魂石地等神圣地标，大地之魂徘徊在不可见的领域中，周围环绕着更小的元素存在。只有喝下了萨满导师酿造的仪式药剂——大地图腾药剂的学徒，才能揭开物质世界与元素之间的面纱。一旦得到认可，大地之魂便会传授大地的祝福，并给予一块粗石英，从而为萨满学徒提供制作大地图腾所需的精神焦点。"}},faq={{q="为什么我看不见大地之魂？",a="这种灵体存在于元素位面，肉眼无法看见。你必须喝下萨满训练师提供的大地图腾药剂，进入改变后的感知状态，才能感知并与元素之灵对话。",al={"无法看见灵体","大地之灵在哪里","大地之魂不可见"}},{q="在哪里可以找到这些大地之灵？",a="它们出现在莫高雷草海平原的科多石，以及杜隆塔尔干旱峡谷的灵魂石地。这两个地点都是年轻牛头人、兽人和巨魔萨满的传统试炼场。",al={"大地之魂位置","去哪里找大地之魂"}},{q="在这个仪式中，灵体的目的是什么？",a="这种灵体负责考验并正式认可学徒与大地元素的联系。在与萨满对话后，它会赐予一块粗石英，学徒需将其带回给萨满训练师以制作大地图腾。",al={"灵体有什么作用","任务目标"}},{q="它周围那些较小的生物是什么？",a="环绕在核心灵体周围的是更小的大地之灵。它们是被吸引到圣地的大地元素的微小回响，仅仅作为自然沟通的一部分存在，无法与其进行直接互动。",al={"较小的灵体","周围的小型大地元素"}}},fx={["40387732"]={q="大地之魂是谁？",a="大地之魂是一种被召唤而来的土元素之灵，在莫高雷的科多石、杜隆塔尔的灵魂石地等圣地受到敬奉。普通人无法看见它，只有饮用大地灵契等仪式药剂、拓展了灵性觉知的萨满才能发现它。",al={"大地之魂是什么","大地之魂是谁","大地之魂的背景"}},f34b34da={q="大地之魂站在哪一边？",a="它既不效忠部落，也不效忠联盟。作为元素的化身，它维护自然世界的平衡，并回应那些展现出与大地沟通所需的敬意和灵性清明的入门者的祈求。",al={"大地之魂属于哪个阵营","大地之魂友好吗","大地之魂站在哪一边"}},["95a7d1ef"]={q="大地之魂想要什么？",a="它渴望与踏上萨满之道的人沟通。饮用大地灵契的入门者前来时，它会考验对方的决心，并赐予一块粗石英，作为其第一个图腾的基石。",al={"大地之魂想要什么","大地之魂的愿望","大地之魂在寻求什么"}},["17161102"]={q="大地之魂为什么会在这里？",a="它驻留在元素力量汇聚的圣地，例如莫高雷的科多石和杜隆塔尔的灵魂石地，作为连接生灵之地与正在接受大地的召唤的萨满候选者的桥梁。",al={"大地之魂为什么在科多石","大地之魂为什么在这里","大地之灵为什么在这里"}}},fp="28,291,18.638.0,49.247.0,39.198.0,45.234.0,46.221.0"}
P.entries["npc:minor-manifestation-of-water"] = {n="水之魂",s="水之魂是一种元素之灵，栖息在银松森林海岸的北流海岸边。对于寻求与水元素沟通并掌控水元素的部落萨满祭司来说，它是试炼中至关重要的一环。在求教于这个宁静的灵魂之前，初学者必须先净化它那被腐蚀的对立面。",h="水之魂是一种元素之灵，栖息在银松森林海岸的北流海岸边。对于寻求与水元素沟通并掌控水元素的部落萨满祭司来说，它是试炼中至关重要的一环。在求教于这个宁静的灵魂之前，初学者必须先净化它那被腐蚀的对立面。",kw={"call of water","元素","水之魂","北流海岸","萨满祭司任务","银松森林","水之图腾"},ang={["class:Shaman"]="清除此元素上的腐蚀并接受其祝福，是调和潮汐并铸造水之图腾的最后里程碑。",["faction:Horde"]="巨魔、兽人和牛头人萨满祭司不远万里从卡利姆多来到洛丹伦的海岸，只为与此灵魂沟通。"},sec={{t="西潮之灵",b="Lurking along the mist-shrouded shores of North Tide's Run, west of the Sepulcher in Silverpine Forest, the Minor Manifestation of Water represents an essential rite of passage for developing shamans. Water elementals embody life, renewal, and fluidity, but they can easily fall victim to malevolent blight. An initiate must face and defeat a corrupted manifestation of this elemental before the pure Minor Manifestation of Water can reveal itself. Once cleansed, the spirit offers guidance to shamans completing their sacred journey to fashion a Water Totem."}},faq={{q="我在哪里可以找到水之魂？",a="水之魂出现在北流海岸，即银松森林西海岸，瑟伯切尔的正西方。",al={"水之魂位置","水之魂在哪里","北流海岸元素"}},{q="为什么我刚靠近时它是敌对的？",a="萨满祭司必须先召唤并消灭受腐蚀的水之魂。只有在击败了腐蚀的幻象后，宁静的化身才会显现并与你交谈。",al={"受腐蚀的化身","为什么水之魂是敌对的","化身攻击我"}},{q="什么任务涉及此元素？",a="此灵魂是萨满祭司任务线“Call of Water”中的关键接触点，萨满祭司最终通过该任务获得施放水之图腾的能力。",al={"call of water任务","银松森林水之图腾任务","这是什么任务"}},{q="非萨满祭司可以与此灵魂互动吗？",a="水之魂存在的意义就是为了指引完成灵性试炼的萨满祭司。其他冒险者几乎没有与它互动的理由。",al={"这是萨满祭司专属吗","谁可以和化身对话","谁会与水之魂交谈"}}},fx={["8e58f5e5"]={q="水之魂是谁？",a="水之魂是由元素之水召唤而来的灵体，用来考验并指引有志成为萨满的人。净化腐化之后，这个元素灵体便成为水之自然流动与智慧的媒介，帮助那些学习聆听元素召唤的人。",al={"水之魂是谁","水之魂是什么","这个元素灵体是谁"}},c7703042={q="水之魂站在哪一边？",a="这个灵体既不属于部落，也不属于联盟。它维护元素本身的平衡，回应寻求与水沟通的萨满的召唤，并检验祈求者是否拥有运用其力量所需的意志与纯净心灵。",al={"水之魂属于哪个阵营","水之魂效忠谁","水之魂属于部落吗"}},["9e575f56"]={q="水之魂想要什么？",a="这个灵体会考验所有寻求掌握水之力量的萨满。在分享纯净精华、赐予祝福之前，它要求你证明自己有能力战胜腐化势力。",al={"水之魂的目标","水之魂渴望什么","水之魂的目的"}},["05f89621"]={q="水之魂为什么会在这里？",a="水之魂会被水之力量汇聚之处吸引，在那里等待响应水之召唤的萨满举行仪式。它现身的目的，正是与在元素导师指引下来到此处的人沟通。",al={"水之魂为什么在这里","水之魂出现在此处的原因"}}},fp="28,323,29.559.0,50.134.0,51.182.0,35.152.0,42.167.0"}
P.entries["npc:misha"] = {n="米沙",s="米沙是部落勇士雷克萨的忠实棕熊伙伴。她忠诚地陪伴着这位半食人兽王漫步在卡利姆多。",h="米沙是部落勇士雷克萨的忠实棕熊伙伴。她忠诚地陪伴着这位半食人兽王漫步在卡利姆多。",kw={"熊","兽王","凄凉之地","菲拉斯","米沙","雷克萨","石爪"},ang={["class:Hunter"]="对于猎人来说，米沙代表了动物伙伴的终极理想：那是一种通过相互尊重而非仅仅通过支配所建立的、牢不可破的终生伙伴关系。",["faction:Horde"]="米沙曾与雷克萨并肩作战，在塞拉摩岛为年轻的部落争取到了自由，并赢得了杜隆塔尔各地老兵的默默尊敬。"},sec={{t="不离不弃的羁绊",b="米沙是一头棕熊，她陪伴在四处游荡的雷克萨身边。雷克萨是一位比起人类更信任野兽的孤独灵魂。他们共同建立了一种坚韧且相互保护的伙伴关系，历经了无数荒野的磨难与血腥的战斗。"},{t="杜隆塔尔的守护者",b="米沙绝不仅仅是一只驯服的宠物，她是一位身经百战的勇士。她曾与雷克萨并肩作战，在塞拉摩岛对抗海军上将戴林·普罗德摩尔的残酷冲突中，帮助确保了年轻部落的生存。在非战斗状态下，她敏锐的感官和力量是雷克萨意志的延伸。"},{t="卡利姆多的荒野",b="目前，行走在石爪山脉、凄凉之地和菲拉斯漫长道路上的旅人们，或许能看到米沙静静地跟随在雷克萨身侧。虽然她凶猛无比，足以撕碎任何胆敢威胁他们的掠食者，但她依然是雷克萨在那个充满不信任的世界中坚定不移的支柱。"}},faq={{q="米沙是谁？",a="米沙是一头凶猛的棕熊，也是部落勇士雷克萨终生的伙伴。她跟随雷克萨漫步在卡利姆多中部的荒野中。",al={"雷克萨的熊","雷克萨身边的熊是谁","熊米沙"}},{q="现在可以在哪里找到米沙？",a="米沙在石爪山脉、凄凉之地和菲拉斯的漫长巡逻路径上游荡，忠实地陪伴着雷克萨进行无尽的旅程。",al={"米沙位置","米沙在哪里","寻找米沙"}},{q="米沙参与了杜隆塔尔的建立吗？",a="是的。在第三次大战争之后，米沙陪伴雷克萨在塞拉摩岛与海军上将戴林·普罗德摩尔的军队作战，以保卫年轻的部落。",al={"米沙 塞拉摩","米沙是否与戴林战斗过","米沙 第三次大战争"}},{q="米沙对联盟玩家有敌意吗？",a="有的。作为部落勇士的伙伴，米沙会拼死保卫雷克萨，并攻击任何靠得太近的联盟入侵者。",al={"联盟可以攻击米沙吗","米沙有攻击性吗"}},{q="为什么雷克萨更喜欢米沙这样的野兽，而不是人？",a="由于对类人种族的欺诈和战争感到幻灭，雷克萨选择了荒野的孤独。他认为野兽直率而诚实，并在米沙身上找到了一个绝无背叛可能的伙伴。",al={"为什么雷克萨饲养野兽","雷克萨的熊伙伴"}}},fp="5,140,16.243.0,19.303.0,17.310.0,13.157.0,35.154.0,47.164.0,37.141.0,51.194.0"}
P.entries["npc:misha-tor-kren"] = {n="米莎·托克伦",s="米莎·托克伦是一位居住在杜隆塔尔西部、雷霆山东南部的托克雷农场的兽人母亲。她因失踪的儿子克隆而忧心忡忡，不得不向过往的旅行者寻求帮助，希望能探明他的下落。",h="米莎·托克伦是一位居住在杜隆塔尔西部、雷霆山东南部的托克雷农场的兽人母亲。她因失踪的儿子克隆而忧心忡忡，不得不向过往的旅行者寻求帮助，希望能探明他的下落。",kw={"鳄鱼","克隆","迷失却未被遗忘","米沙","米莎·托克伦","怒水河","雷霆山","托克雷农场"},ang={["class:Hunter"]="米莎儿子的命运表明，在猎人真正掌握荒野生存技巧之前，低估河流中的掠食者是极其危险的。",["race:Orc"]="克隆渴望证明自己作为战士对抗杜隆塔尔野生生物的鲁莽行为，是一个关于年轻气盛所付出的惨重代价的沉痛教训。"},sec={{t="母亲的守望",b="米莎·托克伦躲在雷霆山边缘的一处隐蔽角落，独自经营着她的农场，承受着为人父母最深切的恐惧。她的儿子克隆前往西部的怒水河猎杀鳄鱼以证明自己的实力，却一去不回。由于杜隆塔尔边境的威胁让兽人哨塔人手吃紧，米莎只能独自等待儿子的消息，绝望地渴望有人能去河岸边寻找她儿子的踪迹。"},{t="残酷的信物",b="怒水河对年轻的猎人从不留情。在泥泞的河岸边搜寻的人们最终会发现，克隆成为了这条河里凶猛鳄鱼的猎物。找回他遗留的护身符是米莎唯一能得到的慰藉——这也是对年轻兽人在卡利姆多严酷荒野中为了证明自己的力量所面临的残酷考验的沉痛提醒。"}},faq={{q="米莎·托克伦是谁？",a="米莎·托克伦是一位住在杜隆塔尔西部、雷霆山东南部托克雷农场的兽人定居者。",al={"米莎·托克伦","米莎是谁","托克雷农场主"}},{q="她的儿子克隆去了哪里？",a="克隆向西前往怒水河猎杀河鳄，渴望证明自己是一名合格的猎人，但他没能回家。",al={"克隆在哪里","克隆发生了什么事","米莎的儿子"}},{q="寻找克隆会发生什么？",a="米莎会派遣冒险者沿着河流寻找克隆。他的失踪让她倍感沉重，她需要有人去调查那片区域。",al={"克隆死了吗","寻找克隆","迷失却未被遗忘"}},{q="她和雷克萨的熊米莎有关系吗？",a="没有。虽然她们都叫米莎，但她是一位住在杜隆塔尔的兽人农民，与雷克萨那头忠诚的熊同伴完全是两回事。",al={"熊米莎","雷克萨的熊米莎","她是那头熊吗"}}},fx={["971252e3"]={q="米莎·托克伦站在哪一边？",a="米莎·托克伦是部落的忠诚成员，在杜隆塔尔过着朴素的兽人拓荒者生活。她住在托克雷农场，在贫瘠的红土地上劳作；遇到危急时刻，她会依靠部落的旅人和当地的勇士帮助家人渡过难关。",al={"米莎·托克伦的阵营","米莎·托克伦效忠谁","米莎·托克伦属于部落吗"}},b9e15925={q="米莎·托克伦想要什么？",a="米莎迫切地想找到失踪的儿子克隆。这个年轻的兽人在怒水河危险的河岸附近狩猎时失踪了。她恳求路过的冒险者搜寻河水，查明他的下落，并带回任何能说明他命运的线索。",al={"米莎想要什么","米莎·托克伦的目标","米莎为什么需要帮助"}},["8e838196"]={q="米莎·托克伦与谁关系密切？",a="米莎与家人关系深厚，其中最重要的是她那失踪的儿子克隆。她打理着雷霆山东南方的托克雷农庄，一家人的生计全靠在杜隆塔尔的荒野中艰难求生。",al={"米莎·托克伦的家人","米莎和谁有亲属关系","米莎·托克伦的儿子"}}},fp="14,221,16.444.0,12.345.1,22.124.0,26.140.0,36.147.1,38.130.0"}
P.entries["npc:mitsuwa"] = {n="米苏瓦",s="米苏瓦是一名驻扎在灰谷雾气缭绕的海岸边，佐拉姆加前哨站的暗矛巨魔。由于他的族人遭到了埋伏，他深感不安，于是招募部落的勇士去为死者复仇并夺回被窃走的灵魂符咒。",h="米苏瓦是一名驻扎在灰谷雾气缭绕的海岸边，佐拉姆加前哨站的暗矛巨魔。由于他的族人遭到了埋伏，他深感不安，于是招募部落的勇士去为死者复仇并夺回被窃走的灵魂符咒。",kw={"灰谷","暗矛","熊怪","玛鲁凯","米苏瓦","蓟皮","巨魔","巨魔符咒","佐拉姆加"},ang={["faction:Horde"]="佐拉姆加前哨站是一处孤立且饱受围困的驻地；援助米苏瓦可以加强部落在卡利姆多西海岸应对野兽和联盟侦察兵时的危险处境。",["race:Troll"]="米苏瓦的战斗号召触动了暗矛冒险者内心深处的情感，因为从粗野的熊怪劫掠者手中收回神圣的祖先符咒，能让被谋杀的兄弟姐妹灵魂得到安宁。"},sec={{t="为死去的族人复仇",b="米苏瓦身处佐拉姆海岸偏远的佐拉姆加前哨站，与他的同伴玛鲁凯一起为部落效力。当一群前往该营地的巨魔在途中遭到灰谷北部好战的蓟皮熊怪伏击并被屠杀时，米苏瓦认为这是极其严重的侮辱。在责任感和怒火的驱使下，他指引有能力的战士前往蓟皮熊怪的巢穴夺回被窃走的巨魔符咒，以确保他族人的灵魂得到安息，并从野兽手中收回这些神圣的物品。"}},faq={{q="米苏瓦是谁？",a="米苏瓦是一名暗矛丛林巨魔，居住在灰谷西北部的佐拉姆加前哨站。他和同伴玛鲁凯一起守护着这个边境哨所，并负责协调对地区敌对势力的报复行动。",al={"米苏瓦","米苏瓦是谁","米苏瓦背景故事"}},{q="那些前往佐拉姆加的巨魔发生了什么事？",a="一群穿越灰谷前往佐拉姆加前哨站支援或访问的巨魔，遭到了当地蓟皮熊怪的伏击并被屠杀，遇难者的随身财物被洗劫一空。",al={"灰谷死去的巨魔","蓟皮熊怪袭击巨魔"}},{q="为什么巨魔符咒对米苏瓦如此重要？",a="这些符咒对暗矛部族具有重要的精神和文化意义。在一场残酷的屠杀后，任由神圣的遗物留在蓟皮熊怪手中，是对死者灵魂极大的不敬。",al={"为什么需要巨魔符咒","巨魔符咒任务原因"}},{q="符咒在哪里？",a="符咒被蓟皮熊怪带回了他们的村庄和肮脏的巢穴，那里位于灰谷北部，佐拉姆海岸的东面。",al={"巨魔符咒在哪里","蓟皮村位置"}}},fx={["24ae2c07"]={q="米苏瓦站在哪一边？",a="米苏瓦效忠部落，和族人住在灰谷海岸边的佐拉姆加前哨站。他与其他部落旅人密切合作，并希望部落的冒险者为阵亡的同伴报仇。",al={"米苏瓦的阵营","米苏瓦属于部落吗","米苏瓦效忠谁"}},ec72a5f0={q="米苏瓦想要什么？",a="米苏瓦想为一群在前往佐拉姆加前哨站途中遭到屠杀的同族巨魔讨回公道。凶悍的蓟皮熊怪伏击了这些旅人，还偷走了他们神圣的巨魔护符。米苏瓦希望从那些野兽手中夺回被盗的传家宝。",al={"米苏瓦的目标","米苏瓦需要什么","米苏瓦的任务"}},b936450a={q="米苏瓦为什么会在佐拉姆加前哨站？",a="米苏瓦驻守在佐拉姆加前哨站，这是灰谷西岸一处偏远的部落营地。他从这里监视周边荒野，并照看那些冒险穿越熊怪和暗夜精灵领地的旅人。",al={"米苏瓦为什么在佐拉姆加","米苏瓦在灰谷的目的","米苏瓦为什么在这里"}}},fp="7,235,23.547.0,15.220.0,51.214.0,49.215.0,29.141.0"}
P.entries["npc:monte-gazlowe"] = {n="Monte Gazlowe",s="加兹鲁维是一位务实的哥布林工程师兼监工，他建立了棘齿城这座港口小镇并担任城主。在协助部落完成杜隆塔尔和奥格瑞玛的建设工作并担任首席工程师后，他利用自己丰厚的报酬，为热砂港建立了一个繁荣且中立的贸易中心。",h="加兹鲁维是一位务实的哥布林工程师兼监工，他建立了棘齿城这座港口小镇并担任城主。在协助部落完成杜隆塔尔和奥格瑞玛的建设工作并担任首席工程师后，他利用自己丰厚的报酬，为热砂港建立了一个繁荣且中立的贸易中心。",kw={"贫瘠之地","杜隆塔尔","海盗","加兹鲁维","蒙特","奥格瑞玛","普兹克","棘齿城","热砂港"},ang={["faction:Alliance"]="加兹鲁维不在乎谁坐在暴风城的王座上，也不在乎你从东部王国带来了什么争端；只要你的金币是真的，且你的刀剑保持入鞘，棘齿城就欢迎你。",["faction:Horde"]="虽然他像任何优秀的哥布林一样精打细算，但在第三次战争尘埃落定后，加兹鲁维一直都是萨尔坚定的盟友，他曾协助挖掘了你们首都的地基。",["profession:Engineering"]="加兹鲁维是卡利姆多顶尖的哥布林工程学大师之一，从城市供水系统到沙漠赛道的高速赛车，一切都由他统筹协调。",["race:Orc"]="兽人们在奥格瑞玛能拥有淡水供应，直接归功于加兹鲁维麾下的工兵，至今他仍会在杜隆塔尔驻扎哥布林技师以协助重型建设工作。"},sec={{t="棘齿城的幕后主使",b="在为新部落的工程建设赚取了一大笔报酬后，加兹鲁维直接投资开发了这片贫瘠的海岸，建立了棘齿城港口。他在热砂港的旗号下运作，将这座码头小镇经营成了一个绝对中立的港口，在这里，部落、联盟和独立商人们可以自由交易——前提是他们必须收好武器，并带上足够的钱袋。"},{t="部落的工程师",b="第三次战争结束后，大酋长萨尔聘请加兹鲁维担任杜隆塔尔的首席工程师，以解决这座新兴兽人首都所面临的关键基础设施难题。加兹鲁维承接了为奥格瑞玛寻找淡水供应这一危险任务，他挖掘了大量的隧道，却意外闯入了地下的狗头人巢穴。在流浪的兽王雷克萨的及时协助下，加兹鲁维成功炸毁并封闭了洞穴，完成了任务。他依然是萨尔最看重的承包商和朋友，甚至还派出了自己的工头雷兹拉克，继续协助兽人在杜隆塔尔各地的建设工作。"},{t="商旅海岸的麻烦",b="尽管棘齿城的生意利润丰厚，但加兹鲁维仍不断受到海上竞争和盗窃活动的困扰。南海海盗在附近的商旅海岸建立了营地，拦截运往棘齿城的货物，并抢劫从矿石原材料到加兹鲁维定制的靴子等一切物资。为了保护自己的收益，这位港口老板经常雇佣过往的佣兵，不论阵营，去清理海盗营地、找回被盗货物，并解决码头捣乱分子的麻烦。"}},faq={{q="加兹鲁维是谁？",a="加兹鲁维是哥布林老板兼棘齿城监工，棘齿城是贫瘠之地海岸线上的主要贸易港口。在建立棘齿城作为热砂港旗下的开放中立港口之前，他曾担任奥格瑞玛建设工作的首席工程师，并由此发迹。",al={"蒙特·加兹鲁维是谁","加兹鲁维背景故事","棘齿城老板"}},{q="加兹鲁维效忠于部落还是联盟？",a="从官方层面来看，加兹鲁维是完全中立的，他以热砂港的名义运营棘齿城，并向联盟和部落的旅行者开放码头。然而，他和萨尔大酋长之间有着深厚的个人友谊和长期的合作历史，他曾亲自参与设计了杜隆塔尔定居点的关键部分。",al={"加兹鲁维是否属于部落","棘齿城是中立的吗","加兹鲁维阵营"}},{q="加兹鲁维在杜隆塔尔建造了什么？",a="在杜隆塔尔建设期间，大酋长萨尔聘请加兹鲁维担任首席工程师。加兹鲁维负责监督隧道挖掘工作，以寻找奥格瑞玛的地下储水库。当矿工们意外惊动了一群充满敌意的狗头人时，加兹鲁维雇佣了雷克萨来帮助工兵封堵隧道。",al={"加兹鲁维奥格瑞玛","加兹鲁维萨尔","加兹鲁维供水系统"}},{q="为什么加兹鲁维要在棘齿城雇佣冒险者？",a="加兹鲁维经常需要私人武力来对付南海海盗，这些海盗在商旅海岸安营扎寨，经常劫掠运往棘齿城码头的货物。他花钱雇佣赏金猎人去消灭海盗、找回被盗的货物清单，以及寻回遗失的货物。",al={"加兹鲁维任务","棘齿城南海海盗","加兹鲁维的麻烦"}},{q="加兹鲁维与沙漠赛道有什么关系？",a="加兹鲁维是一位热衷于工程学和速度的人。他资助了在千针石林的闪光平原上与侏儒竞速的哥布林车队，曾协助他们建造赛车，并尝试寻找原型燃料调节器。",al={"加兹鲁维闪光平原","加兹鲁维千针石林","加兹鲁维赛车"}}},fx={cabfa558={q="加兹鲁维为什么会在棘齿城？",a="加兹鲁维帮助萨尔建造奥格瑞玛，赚得一大笔财富后，便将利润投入到棘齿城的创立中。棘齿城位于怒水河入海口、贫瘠之地海岸，是热砂港在卡利姆多首屈一指的中立贸易港口，使他得以掌管海上贸易、地区工程项目以及遍布大陆的丰厚合约。",al={"加兹鲁维为什么来到棘齿城","加兹鲁维为什么在这里","加兹鲁维在棘齿城的目的"}},["0afdf6f5"]={q="加兹鲁维的主要盟友和商业伙伴是谁？",a="加兹鲁维与大酋长萨尔和部落关系密切，杜隆塔尔建造之初他曾担任部落的首席工程师。在热砂港内部，他与藏宝海湾的大财主里维加兹往来。他还赞助了闪光平原沙漠赛道上的地精赛车队。",al={"加兹鲁维的盟友","加兹鲁维和谁关系密切","加兹鲁维的人脉关系","加兹鲁维的合作伙伴"}}},fp="13,298,25.387.0,22.613.0,29.508.0,15.275.0,46.298.0,34.309.0,45.286.0,51.236.0"}
P.entries["npc:moon-priestess-amara"] = {n="哨兵阿玛拉·夜行者",s="哨兵阿玛拉·夜行者是一位暗夜精灵女祭司，驻扎在泰达希尔的多兰纳尔西侧的主干道上。她在忠诚的女猎手护卫簇拥下，守护着连接巨树中心地带与首都达纳苏斯的林间小径。",h="哨兵阿玛拉·夜行者是一位暗夜精灵女祭司，驻扎在泰达希尔的多兰纳尔西侧的主干道上。她在忠诚的女猎手护卫簇拥下，守护着连接巨树中心地带与首都达纳苏斯的林间小径。",kw={"阿玛拉·夜行者","多兰纳尔","艾兰娜瑞","哨兵阿玛拉·夜行者","内玛伊","泰达希尔","通往达纳苏斯之路","雅莉乌拉"},ang={["class:Priest"]="作为The Sisterhood of Elune的一员，阿玛拉祭司体现了暗夜精灵对月亮女神的虔诚，为从幽影谷出发的年轻侍僧们提供牧养和精神引导。",["race:NightElf"]="阿玛拉标志着你离开多兰纳尔旅途中的一个重要里程碑，她提供的指引和任务将引领你进入伟大的城市达纳苏斯。"},sec={{t="巨树之道的守护者",b="哨兵阿玛拉·夜行者驻扎在多兰纳尔以西的一处安静路边哨所，她不仅代表了The Sisterhood of Elune的精神权威，也展现了保障泰达希尔道路安全所需的务实警惕。她与两名女猎手同伴——内玛伊和雅莉乌拉——共同巡逻和守望。对于向西行进的旅者而言，阿玛拉就像一位指路明灯，引导冒险者沿着道路前往达纳苏斯，并指引那些内心沉重的旅人去寻找救赎之路。"}},faq={{q="哨兵阿玛拉·夜行者是谁？",a="哨兵阿玛拉·夜行者，在哨兵职责中也被称为阿玛拉·夜行者，是泰达希尔多兰纳尔和达纳苏斯之间道路上的一位The Sisterhood of Elune祭司。她负责监督过往旅人的安全与精神健康。",al={"阿玛拉是谁","阿玛拉祭司","哨兵阿玛拉·夜行者"}},{q="我在哪里可以找到哨兵阿玛拉·夜行者？",a="她位于泰达希尔多兰纳尔以西的铺设路面上，站在两名哨兵女猎手身旁守望。",al={"阿玛拉在哪里","阿玛拉位置","阿玛拉祭司地图"}},{q="和她站在一起的女猎手是谁？",a="她由女猎手内玛伊和女猎手雅莉乌拉护卫并陪伴，这两位暗夜精灵哨兵协助她保护这条通道免受野兽和敌对腐化的侵害。",al={"阿玛拉的同伴","内玛伊和雅莉乌拉","阿玛拉的守卫"}}},fx={["3d569ab2"]={q="哨兵阿玛拉·夜行者站在哪一边？",a="哨兵阿玛拉·夜行者侍奉艾露恩的祭司，并效忠联盟，守护着泰达希尔的圣树枝。在哨兵同伴的陪伴下，她致力于引导旅人，并保护卡多雷的故土，使其免受威胁宁静森林的腐化侵扰。",al={"阿玛拉的阵营","阿玛拉效忠哪一方","阿玛拉侍奉谁"}},["75dde252"]={q="哨兵阿玛拉·夜行者为什么驻守在这里？",a="阿玛拉驻守在多兰纳尔以西的主路旁，保护前往达纳苏斯的旅人。泰达希尔的道路正日益遭受腐化野兽和潜伏的木爪树人的袭击，因此她的存在对于确保林间道路安全至关重要。",al={"阿玛拉为什么在这里","阿玛拉驻守此处的目的","月之女祭司阿玛拉为什么在路边"}},["74974fcb"]={q="哨兵阿玛拉·夜行者想要什么？",a="她希望有能力的冒险者帮助守卫通往首都达纳苏斯的道路。阿玛拉让旅人消灭那些在世界之树的枝叶下骚扰西行者的邪恶钉刺熊怪和凶猛森林生物。",al={"阿玛拉需要什么","阿玛拉的任务动机","阿玛拉为什么让你执行任务"}}},fp="20,252,25.480.0,28.270.0,38.122.0,41.174.0"}
P.entries["npc:mor-rogal"] = {n="摩罗加尔",s="摩罗加尔是一位居住在石爪山脉烈日石居的牛头人。他担任着向导和顾问，为那些在崎岖的岩层地下深处寻求荣耀与冒险的旅人们提供指引。",h="摩罗加尔是一位居住在石爪山脉烈日石居的牛头人。他担任着向导和顾问，为那些在崎岖的岩层地下深处寻求荣耀与冒险的旅人们提供指引。",kw={"滚岩峡谷","土灵苏醒","摩罗加尔","石爪山脉","烈日石居","牛头人"},ang={["faction:Horde"]="对于抵达烈日石居避难所的旅人来说，摩罗加尔提供了关于定居点边界外岩层中潜伏威胁的关键情报。",["race:Tauren"]="摩罗加尔体现了牛头人对体魄与精神试炼的尊重，他将卡利姆多的深层石穴视为证明自身价值的圣地。"},sec={{t="岩层守望者",b="摩罗加尔栖身于烈日石居的避难所中，对贯穿石爪山脉的深邃裂隙和洞穴有着浓厚的兴趣。他深知这片区域蜿蜒的地下通道既蕴藏着巨大的财富，也潜伏着致命的危险，因此他会指引勇敢的部落旅者去调查滚岩峡谷等充满麻烦的区域。对摩罗加尔而言，深入这些险恶之地不仅关乎生存，更是对那些追寻荣耀、听从内心召唤者的精神试炼。"}},faq={{q="摩罗加尔是谁？",a="摩罗加尔是一位居住在石爪山脉烈日石居的牛头人任务发布者。他充当当地向导的角色，敦促部落冒险者在布满崎岖山脉的危险洞穴和峡谷中磨练自己的意志。",al={"摩罗加尔","摩罗加尔是谁","摩罗加尔背景故事"}},{q="我在哪里能找到摩罗加尔？",a="他伫立在烈日石居，这是隐藏在石爪山脉中部峰峦间的主要部落据点。",al={"摩罗加尔位置","摩罗加尔在哪里","摩罗加尔地点"}},{q="摩罗加尔提供什么任务？",a="摩罗加尔招募有能力的勇士深入滚岩峡谷的洞穴，那里的狗头人正在疯狂挖掘共鸣水晶，并要求勇士们击杀戈格洛克，一个被狗头人挖出来的、正在沉睡的土灵。",al={"摩罗加尔任务","摩罗加尔想要什么"}},{q="为什么摩罗加尔专注于洞穴和峡谷？",a="摩罗加尔认为石爪山脉险峻的地下洞穴不仅是真正的冒险之地，更是精神意志的试炼场，为那些愿意拿生命去冒险的人提供荣耀与财富。",al={"为什么是洞穴","摩罗加尔洞穴"}}},fx={["9b06cf83"]={q="摩罗加尔效忠于哪一方？",a="摩罗加尔与部落及其他牛头人并肩。他驻扎在石爪山脉高处偏僻的部落哨站烈日石居，为维护部落在该地区利益的冒险者提供指引并分派任务。",al={"摩罗加尔阵营","摩罗加尔属于部落还是联盟","摩罗加尔效忠哪一方"}},["27de9984"]={q="摩罗加尔想要什么？",a="摩罗加尔正在寻找愿意冒险深入石爪山脉险峻洞穴和峡谷的勇士。他指引侦察兵前往滚岩峡谷等敌对之地，鼓励胆识过人的勇士迎战地下潜藏的土元素威胁，以换取荣誉与财富。",al={"摩罗加尔的目标","摩罗加尔在做什么","摩罗加尔任务的目的"}}},fp="9,204,20.521.0,17.246.0,27.130.0,32.208.1,46.188.0"}
P.entries["npc:morgan-pestle"] = {n="摩根·匹斯特",s="摩根·匹斯特是一位人类炼金师和店主，在暴风城的Trade District经营着匹斯特药剂店。他与身处闪金镇的兄弟威廉·匹斯特密切合作，负责首都的物资供应和炼金研究工作。",h="摩根·匹斯特是一位人类炼金师和店主，在暴风城的Trade District经营着匹斯特药剂店。他与身处闪金镇的兄弟威廉·匹斯特密切合作，负责首都的物资供应和炼金研究工作。",kw={"炼金师","摩根·匹斯特","匹斯特药剂店","寄往暴风城的货物","暴风城","trade district","威廉·匹斯特"},ang={["faction:Alliance"]="对于从艾尔文森林抵达暴风城的联盟冒险者来说，摩根的商店是满足实用炼金需求和本地城市货物配送的重要站点。",["profession:Herbalism"]="摩根非常依赖在艾尔文森林及更远地区采集的新鲜原料来供应他位于Trade District的药剂店。"},sec={{t="城市药剂师",b="摩根·匹斯特在暴风城Trade District繁忙的街道旁经营着匹斯特药剂店，为城市居民和过往旅人提供炼金商品、试剂和实用的药方。他的兄弟威廉在闪金镇的Lion's Pride Inn经营着一家作坊，而摩根则将家族生意扎根于王国首都的中心地带，负责接收来自农村腹地的货物，例如他兄弟寄来的蜡烛。"}},faq={{q="我在哪里可以找到摩根·匹斯特？",a="摩根·匹斯特位于暴风城Trade District的匹斯特药剂店里。",al={"摩根·匹斯特位置","摩根·匹斯特在哪里","暴风城匹斯特药剂店"}},{q="摩根·匹斯特和威廉·匹斯特是什么关系？",a="摩根·匹斯特和威廉·匹斯特是兄弟。他们都是艾尔文森林的炼金师，摩根负责经营他们在暴风城的商店，而威廉则在闪金镇工作。",al={"威廉·匹斯特兄弟","威廉和摩根是否有亲属关系","匹斯特兄弟"}},{q="他在艾尔文森林的任务中扮演什么角色？",a="摩根是他的兄弟威廉从闪金镇向北发往他们店里（匹斯特药剂店）的蜡烛货物接收人，他会为送货的信使支付丰厚的报酬。",al={"寄往暴风城的货物摩根","摩根·匹斯特任务"}}},fx={["2e5b0856"]={q="摩根·匹斯特是谁？",a="摩根·匹斯特是一名人类炼金师兼店主，在暴风城贸易区经营生意。他拥有并经营匹斯特药剂店，为城中居民提供试剂、药剂和各种炼金混合物。",al={"摩根·匹斯特是谁","摩根·匹斯特的背景","匹斯特是谁"}},ae642a6d={q="摩根·匹斯特效忠于哪一方？",a="摩根·匹斯特是联盟的忠诚公民。他在暴风城贸易区中心地带经营生意，为当地居民和整个王国提供支持。",al={"摩根·匹斯特的阵营","摩根·匹斯特是联盟成员吗","摩根·匹斯特效忠哪一方"}},["2ef8a55a"]={q="摩根·匹斯特为什么在这里？",a="摩根·匹斯特住在暴风城，负责经营自己的店铺匹斯特药剂店。他在熙攘的贸易区店面里出售药水和小饰品，并接收在闪金镇工作的兄弟威廉寄来的货物。",al={"摩根·匹斯特为什么在暴风城","摩根·匹斯特与贸易区"}}},fp="13,242,19.451.0,31.100.0,47.156.0,40.181.0"}
P.entries["npc:morgan-the-collector"] = {n="收货人莫根",s="收货人莫根是迪菲亚潜行者的高层特工，负责监督该兄弟会在整个艾尔文森林的勒索和搜刮活动。他盘踞在被占领的布莱克威尔南瓜田，在闪金镇卫兵的眼皮底下指挥当地的盗窃勾当。",h="收货人莫根是迪菲亚潜行者的高层特工，负责监督该兄弟会在整个艾尔文森林的勒索和搜刮活动。他盘踞在被占领的布莱克威尔南瓜田，在闪金镇卫兵的眼皮底下指挥当地的盗窃勾当。",kw={"布莱克威尔","兄弟会","迪菲亚","杜汉","搜捕","莫根","南瓜田","印戒","收货人"},ang={["class:Rogue"]="莫根展示了有组织的犯罪纪律是如何将散兵游勇般的盗贼变成一个有能力资助叛乱的功能性地下组织的。",["race:Human"]="击败莫根是对那些将暴风城宁静的农场变成坚固的强盗巢穴的叛徒的反击。"},sec={{t="艾尔文的什一税",b="莫根凭借代表迪菲亚潜行者从艾尔文森林的矿洞中搜刮金币而获得了这个绰号。虽然普通的强盗在道路上骚扰过往旅人，但莫根指挥的是有组织的敲诈勒索，并收集赃款和物资，将其进一步输送到兄弟会的网络中。他将总部设在布莱克威尔南瓜田的农舍内，周围环绕着包括苏瑞娜·卡莱登和厄兰·德鲁杰摩尔在内的忠诚打手。"},{t="过去的印戒",b="莫根的行动并非简单的街头犯罪；他佩戴着一枚独特的印戒，象征着他的权力。对于闪金镇的调查人员来说，这枚戒指提供了确凿证据，将恐吓腹地的蒙面盗贼与曾经重建了暴风城的、现已蒙羞的石匠工会联系了起来。找回他的戒指能揭开究竟是谁在指挥森林中那些强盗的谜团。"}},faq={{q="谁是收货人莫根？",a="他是迪菲亚潜行者的一名军官，负责收集从艾尔文森林的矿洞中掠夺的金币，并协调该地区的强盗活动。",al={"谁是莫根","莫根背景故事","艾尔文森林的收货人"}},{q="莫根在哪里？",a="他将赃物囤积在位于艾尔文森林东部的布莱克威尔南瓜田的废弃农舍内。",al={"莫根的位置","收货人莫根在哪里","布莱克威尔南瓜田农舍"}},{q="为什么暴风城要追捕他？",a="治安官杜汉和地方当局希望除掉莫根，以切断迪菲亚在艾尔文的领导层，并找回关于是谁在组织乡村起义的证据。",al={"为什么要杀莫根","搜捕目标"}},{q="他携带的戒指有什么特别之处？",a="莫根携带一枚印戒，这枚戒指可以作为当局调查他在艾尔文森林活动的证据。",al={"收货人的戒指","收货人印戒","莫根的戒指背景"}}},fx={["8321821e"]={q="收货人莫根效忠于哪一方？",a="收货人莫根是迪菲亚潜行者的坚定成员。他并非普通的拦路劫匪，而是这个犯罪组织中的一名军官，直接与暴风王国为敌，并在艾尔文森林腹地策划迪菲亚潜行者的活动。",al={"收货人莫根的阵营","莫根属于什么阵营","莫根是迪菲亚潜行者吗"}},["5f1d52ce"]={q="收货人莫根想要什么？",a="莫根是艾尔文森林各处迪菲亚潜行者行动的首领，人称“收货人”。他意在为迪菲亚潜行者的起义搜集财富、资源和影响力，并在南瓜田建立一处坚固据点，就在暴风城卫兵的眼皮底下。",al={"莫根想做什么","收货人莫根的目标","收货人莫根的动机"}},["2a29f808"]={q="收货人莫根为什么在艾尔文森林？",a="莫根在布莱克威尔南瓜田扎下脚跟，亲自指挥迪菲亚潜行者在当地的行动。他与副手苏雷娜·卡雷东和埃兰·德鲁吉穆尔一起藏身农舍，严密协调遍布该地区的强盗。",al={"莫根为什么在布莱克威尔南瓜田","是什么把莫根带到这里"}},ceb85f69={q="收货人莫根与谁有关联？",a="他的印戒成为调查困扰艾尔文森林的歹徒及其关联势力时的一项证据。",al={"莫根与谁共事","收货人莫根的同伙","莫根与石匠"}}},fp="20,262,19.448.0,20.411.1,28.155.0,22.123.0,29.156.0,42.119.1"}
P.entries["npc:morin-cloudstalker"] = {n="摩林·云行者",s="摩林·云行者是一名牛头人斥候，在莫高雷从血蹄村通往贫瘠之地的路上进行巡视。他守望着这片平原，监视当地的贸易路线，并调查威胁牛头人旅行者安全的入侵威胁。",h="摩林·云行者是一名牛头人斥候，在莫高雷从血蹄村通往贫瘠之地的路上进行巡视。他守望着这片平原，监视当地的贸易路线，并调查威胁牛头人旅行者安全的入侵威胁。",kw={"血蹄村","大门","摩林·云行者","莫高雷","被破坏的货车","监工菲兹斯普罗克特","荆棘谷地精"},ang={["faction:Horde"]="摩林为部落勇士们提供了一个早期机会，让他们能够保护新结盟的牛头人的补给和神圣土地。",["race:Tauren"]="对于从血蹄村出发旅行的牛头人来说，摩林代表了对家园的警惕守卫，抵御着投机的强盗和企业的亵渎者。"},sec={{t="南部小径的守望者",b="摩林·云行者驻扎在通往贫瘠之地的蜿蜒土路旁，既是斥候也是穿行于莫高雷的旅行者的守护者。这里的草原通常十分平静，但随着贸易路线的开通和领地的变动，机会主义者和强盗已经逼近了牛头人家园的核心地带。"},{t="调查货车",b="摩林的斥候最近在石牛湖北岸袭击并烧毁了一辆荆棘谷地精的货车。当人们在烧毁的马车附近发现地精拾荒者时，他派遣冒险者去检查幸存的补给板条箱，了解荆棘谷地精究竟在运输什么。"},{t="防御荆棘谷地精",b="除了普通的强盗，摩林还对荆棘谷地精在莫高雷建立工业据点深感担忧。他指挥路过的部落冒险者打击其伐木和采矿前哨站，针对诸如监工菲兹斯普罗克特之类的关键领导者，以制止威胁这片圣洁平原的环境破坏行为。"}},faq={{q="我在哪里可以找到摩林·云行者？",a="摩林·云行者站在莫高雷血蹄村东面的土路上，位于通往贫瘠之地的道路旁。",al={"摩林位置","摩林在哪里","摩林·云行者地图"}},{q="摩林在莫高雷扮演什么角色？",a="他是一名警惕的牛头人斥候，负责监视莫高雷南部的通行状况，并组织防御力量打击强盗和企业入侵者。",al={"摩林·云行者是谁","摩林的角色"}},{q="摩林为什么要调查那辆被毁的货车？",a="摩林的斥候在石牛湖附近袭击并烧毁了一辆荆棘谷地精的货车。当在残骸附近发现地精拾荒者时，他请求冒险者去检查幸存的补给板条箱，以了解荆棘谷地精在运输什么。",al={"被破坏的货车任务","货车遇袭莫高雷"}},{q="摩林为什么要阻止荆棘谷地精？",a="荆棘谷地精正利用机械和滥砍滥伐掠夺莫高雷的自然资源。摩林试图通过消灭包括监工菲兹斯普罗克特在内的监督者，来破坏他们的破坏性企业。",al={"莫高雷的荆棘谷地精","为什么要击杀菲兹斯普罗克特"}},{q="摩林向谁汇报？",a="摩林代表血蹄村的长老和酋长，以及整个莫高雷更广泛的牛头人领导层开展行动。",al={"摩林的效忠对象","谁派遣了摩林"}},{q="摩林会向联盟玩家提供任务吗？",a="不会。摩林是一个完全忠于部落的NPC，只会与部落冒险者互动。",al={"联盟能否与摩林交谈","摩林的阵营"}}},fx={["2ee6eb23"]={q="摩林·云行者是谁？",a="摩林·云行者是一名牛头人侦察兵，负责守护莫高雷。他驻守在从血蹄村向东通往贫瘠之地的道路旁，密切留意潜入牛头人祖地的威胁，并派遣有能力的部落冒险者保护平原，抵御掠夺者和剥削者。",al={"摩林·云行者是谁","摩林是谁","摩林的背景"}},b362fb80={q="摩林·云行者效忠于哪一方？",a="摩林坚定效忠雷霆崖和部落。他守护着牛头人族群的核心领地，只为愿意捍卫莫高雷脆弱和平的部落旅者提供指引并交付任务。",al={"摩林·云行者的阵营","摩林属于联盟还是部落","摩林是部落成员吗"}},["7047ff15"]={q="摩林·云行者想要什么？",a="摩林希望保护莫高雷的道路和自然资源。他派冒险者搜寻侦察兵烧毁的风险投资公司商队，并制止风险投资公司的破坏性行动，尤其要求停止主管菲兹斯普罗克特在山丘上的掠夺性采矿。",al={"摩林想要什么","摩林的目标","摩林的任务"}},["9ad7af70"]={q="摩林·云行者为什么驻扎在这里？",a="摩林驻扎在血蹄村以东的道路旁，负责守望莫高雷的交通。这处重要路口让他能够监视往来商队，并拦截风险投资公司这类侵入者，避免他们抵达血蹄村。",al={"摩林为什么在这里","摩林为什么在路边","摩林驻地的原因"}}},fp="18,266,29.343.0,25.268.0,29.346.1,36.128.0,32.152.0,46.232.0,48.212.0,25.124.0,44.94.0"}
P.entries["npc:motega-firemane"] = {n="莫特加·火鬃",s="莫特加·火鬃是一位驻扎在千针石林的白沙岗哨的牛头人学者。他致力于记录峡谷中危险的野生生物，但他的研究却被一个复仇心切的翼蛇之灵以及他那位年轻助手鲁莽的冒险行为所打断。",h="莫特加·火鬃是一位驻扎在千针石林的白沙岗哨的牛头人学者。他致力于记录峡谷中危险的野生生物，但他的研究却被一个复仇心切的翼蛇之灵以及他那位年轻助手鲁莽的冒险行为所打断。",kw={"阿里卡拉","凯恩·血蹄","卡纳提·灰云","玛加萨·野性图腾","莫特加·火鬃","波卡·雨山","千针石林","白沙岗哨"},ang={["class:Hunter"]="猎人们与莫特加有着共同的兴趣，莫特加依靠熟练的追踪者来采集峡谷植物、追踪风巢的飞龙，以及跟踪强大的阿里卡拉之灵。",["faction:Horde"]="莫特加代表了部落向卡利姆多荒野地区的扩张，他维持着一个不稳定的研究岗哨，同时保护大酋长凯恩·血蹄免受灵体威胁。",["race:Tauren"]="通过对自然的崇敬和对凯恩·血蹄的尽忠职守，莫特加体现了牛头人研究大地之母造物的准则，同时也致力于保护部落免受古老灵体的侵害。"},sec={{t="峡谷学者",b="第三次战争结束四年后，莫特加·火鬃前往南方的千针石林，观察并记录在这些高耸平顶山之间幸存的奇特野兽。莫特加带着他年轻的助手波卡·雨山（波卡的父亲起初很不情愿让他离开莫高雷）一同前往，并在白沙岗哨与卡纳提·灰云一起建立了营地。虽然他最初的使命是安静地进行自然观察，但峡谷底部严酷的危险却不断要求他采取更具武力的方式来生存。"},{t="阿里卡拉之怒",b="当乱风岗传来消息称，阿里卡拉——一只凶猛而传奇的翼蛇之灵——已经回到峡谷，意图向凯恩·血蹄复仇时，莫特加平静的研究被打乱了。对于这种生物为何会对大酋长怀恨在心，莫特加感到困惑，但他为了保护部落果断采取了行动。他指示侦察兵收集峡谷盆地的火岩龙舌兰，并将它们带到雷霆崖长者高地的玛加萨·野性图腾处，将其附魔成神圣的火岩粉。猎人们利用这种准备物召唤并击杀了蛇灵，并将它的兽皮带回白沙岗哨，作为凯恩安全无虞的证明。"},{t="白沙守护者",b="阿里卡拉并不是唯一威胁莫特加在白沙岗哨驻扎的危险。当地的加拉克半人马不断试探营地，甚至策划了针对卡纳提·灰云及其追随者的暗杀阴谋。更糟糕的是，年轻的波卡离开了营火的保护，消失在飞龙出没的风巢高地。尽管对这个年轻勇士的轻率感到沮丧，但当部落的旅行者将这个年轻人活着带回来时，莫特加感到无比宽慰。"}},faq={{q="莫特加·火鬃是谁？",a="莫特加·火鬃是一位驻扎在千针石林的白沙岗哨的牛头人研究员。他来到峡谷是为了与同族的勇士们以及他的助手波卡·雨山一起研究当地的野生生物。",al={"莫特加·火鬃背景故事","谁是莫特加","白沙岗哨莫特加"}},{q="在哪里可以找到莫特加·火鬃？",a="他位于千针石林的一个小型部落营地——白沙岗哨，该营地位于该区域西北部的道路旁，靠近伊索克营地。",al={"莫特加位置","莫特加·火鬃在哪里","莫特加·火鬃地图"}},{q="为什么莫特加会担心阿里卡拉？",a="阿里卡拉是一个出现在千针石林并以凯恩·血蹄为目标的复仇蛇灵。尽管莫特加对这个灵体为何会对大酋长怀有怨恨感到不解，但他严肃对待这一威胁，并指示猎人召唤并消灭这种生物。",al={"谁是阿里卡拉","为什么要杀阿里卡拉","阿里卡拉凯恩"}},{q="玛加萨·野性图腾在莫特加的计划中扮演什么角色？",a="莫特加委托冒险者采集火岩龙舌兰，并将它们带到雷霆崖长者高地的玛加萨·野性图腾处。玛加萨利用她的萨满知识将植物附魔成能够召唤难以捉摸的阿里卡拉的神圣粉末。",al={"玛加萨火岩粉","莫特加与玛加萨","神圣之火任务背景"}},{q="莫特加的同伴波卡发生了什么事？",a="波卡·雨山误入了危险的飞龙栖息地风巢并迷路了。莫特加对这个年轻人的命运感到焦虑，考虑到波卡的父亲当初是多么不情愿让他踏上这段旅程，但旅行者最终成功地将他护送回了白沙岗哨。",al={"波卡·雨山","失踪的牛头人风巢","归乡任务"}},{q="白沙岗哨还面临哪些危险？",a="除了游荡的灵体和掠食者，营地还不断受到附近加拉克半人马的威胁，他们策划伏击，并谋划对卡纳提·灰云以及驻扎在岗哨的其他牛头人进行暗杀。",al={"白沙岗哨威胁","白沙岗哨的半人马","加拉克半人马阴谋"}}},fx={ca68f68f={q="莫特加·火鬃效忠于哪一方？",a="莫特加·火鬃效忠于牛头人和部落。他与卡纳提·灰云一同驻扎在白沙岗哨，与部落旅者密切合作，并维护凯恩·血蹄及雷霆崖旗下各部族的利益。",al={"莫特加·火鬃的阵营","莫特加·火鬃属于部落还是联盟","莫特加是部落成员吗"}},["8b7dc2d8"]={q="莫特加·火鬃想要什么？",a="莫特加主要致力于研究千针石林独特的野生动物，同时照看年轻的同伴波卡·雨山。不过，凡是威胁雷霆崖的事都会立刻成为优先事项。得知复仇心切的风蛇阿利卡拉后，他想召唤并消灭这头野兽，以免它危及凯恩·血蹄。",al={"莫特加想要什么","莫特加·火鬃的目标","莫特加想做什么"}},["12cba981"]={q="莫特加·火鬃为什么在这里？",a="莫特加深入千针石林，观察并研究峡谷谷底及周边台地的奇异野兽。白沙岗哨是他的研究营地，不过当地麻烦——从同伴失踪到凶险的神话巨蛇——常常让他不得不放下学术研究。",al={"莫特加为什么在千针石林","是什么让莫特加来到白沙岗哨","莫特加·火鬃的目的"}}},fp="15,267,22.511.0,20.632.1,22.483.1,23.204.0,35.140.0,38.275.1,56.248.1,44.276.1,45.212.0"}
P.entries["npc:mountaineer-barleybrew"] = {n="巡山人维拉特·麦酒",s="巡山人维拉特·麦酒是驻守在丹莫罗南门哨岗的一名铁炉堡巡山人。他守卫着通往东部洛克莫丹的山口，依靠烈性矮人佳酿在严寒中保持警惕。",h="巡山人维拉特·麦酒是驻守在丹莫罗南门哨岗的一名铁炉堡巡山人。他守卫着通往东部洛克莫丹的山口，依靠烈性矮人佳酿在严寒中保持警惕。",kw={"麦酒","丹莫罗","巡山人","微光烈酒","南门哨岗","维拉特"},ang={["race:Dwarf"]="对于矮人来说，麦酒氏族体现了边境职责与烈性提神饮品之间的重要平衡，正是这种平衡保障了卡兹莫丹的安全。"},sec={{t="东部山口的守望",b="巡山人维拉特·麦酒驻扎在守卫着通往洛克莫丹雪道的南门哨岗，是铁炉堡边境守卫的一员。像许多在丹莫罗凛冽寒风中服役的巡山人一样，他十分赞赏精良矮人酒水的提神功效。作为著名的麦酒氏族的一员，他负责确保强效的微光烈酒能够运送到那些在漫长的山口值守期间需要温暖和体力的同僚手中。"}},faq={{q="我能在哪里找到巡山人维拉特·麦酒？",a="巡山人维拉特·麦酒驻扎在南门哨岗，这是一座守卫着丹莫罗和洛克莫丹之间东部山口的矮人防御工事。",al={"麦酒位置","巡山人维拉特·麦酒在哪里","麦酒npc"}},{q="他在南门哨岗的职责是什么？",a="他担任山地哨兵以保卫道路，并协助协调物资补给，包括为驻守在各个山口的巡山人同僚提供微光烈酒。",al={"麦酒的目的","麦酒做什么"}},{q="他和其他的麦酒族人有亲属关系吗？",a="是的。他的兄弟是酿酒师雷杰德·麦酒，此外他可能还与马勒斯·麦酒、马尔金·麦酒和尤鲁斯·麦酒有亲戚关系。",al={"麦酒家族","尤鲁斯·麦酒亲属"}}},fx={["583559ff"]={q="巡山人维拉特·麦酒是谁？",a="巡山人维拉特·麦酒是一名矮人哨兵，驻守在丹莫罗东部边境。他和铁炉堡的所有巡山人一样，时刻警惕威胁山路的野兽、穴居人和霜鬃巨魔袭击者；在履行严谨的边境职责之余，也保留着矮人对美酒的独特热爱。",al={"巡山人维拉特·麦酒是谁","麦酒是谁","巡山人维拉特·麦酒的背景"}},["399d0350"]={q="巡山人维拉特·麦酒效忠于哪一方？",a="他是铁炉堡坚定不移的士兵，忠于联盟。他听从铜须氏族和国王麦格尼的命令，确保王国各地旅客和重要山道的安全。",al={"巡山人维拉特·麦酒的阵营","麦酒效忠于谁","麦酒是联盟成员吗"}},fc186c57={q="巡山人维拉特·麦酒想要什么？",a="除了确保道路不受入侵者威胁，巡山人维拉特·麦酒也喜欢喝上一口醇厚的美酒，好抵御刺骨的山间寒风。他需要过路旅客在他的驻地与附近盟友之间传递消息和物资，其中包括一壶烈性的微光烈酒。",al={"麦酒想要什么","维拉特·麦酒需要什么","麦酒在找什么"}},b2269341={q="巡山人维拉特·麦酒为什么在这里？",a="他驻守在南门哨岗的山道上，守卫连接丹莫罗和洛克莫丹的重要通路。高山隘口常有游荡的野兽和凶悍的穴居人战团出没，因此需要纪律严明的巡山人守住关隘。",al={"麦酒为什么在南门","巡山人维拉特·麦酒为什么驻扎在这里","麦酒驻扎在此的原因"}}},fp="22,232,27.499.0,40.145.0,39.165.0,39.118.0"}
P.entries["npc:mountaineer-kadrell"] = {n="巡山人卡德雷尔",s="巡山人卡德雷尔是一位坚毅的矮人哨兵，驻扎在塞尔萨玛的烈酒旅店对面。作为洛克莫丹巡山人中的重要联络官，他负责协调该地区的侦察、物资补给和边境防御工作。",h="巡山人卡德雷尔是一位坚毅的矮人哨兵，驻扎在塞尔萨玛的烈酒旅店对面。作为洛克莫丹巡山人中的重要联络官，他负责协调该地区的侦察、物资补给和边境防御工作。",kw={"卡德雷尔","洛克莫丹","巡山人","罗克加","卡尔·雷矛","烈酒旅店","塞尔萨玛"},ang={["faction:Alliance"]="卡德雷尔依赖路过塞尔萨玛的联盟旅行者来传递信息，并向苦于应对区域威胁的偏远巡山人前哨站伸出援手。",["race:Dwarf"]="作为著名的巡山人军团的一员，卡德雷尔代表着前线警戒力量，保卫着铁炉堡的东部领土免受荒野危险的侵扰。"},sec={{t="塞尔萨玛的哨兵",b="巡山人卡德雷尔在热闹的塞尔萨玛定居点担任警戒工作，是洛克莫丹矮人防御力量的中坚。尽管山谷边缘的前哨站面临着穴居人、豺狼人和当地野兽的持续威胁，卡德雷尔始终驻守在镇中心，负责组织增援、传达命令，并评估从巡逻斥候那里传回的战地报告。"},{t="保持联络畅通",b="卡德雷尔的职责通常包括保持塞尔萨玛与偏远前线阵地之间的联络。无论是与巡山人卡尔·雷矛进行协调，还是派遣冒险者去向巡山人罗克加等哨兵汇报，卡德雷尔都能确保守卫山口的孤立前哨站获得关键的物资、增援和防御情报。"}},faq={{q="在哪里可以找到巡山人卡德雷尔？",a="卡德雷尔驻扎在洛克莫丹连绵起伏的群山之中的塞尔萨玛镇，就在烈酒旅店马路对面。",al={"卡德雷尔位置","卡德雷尔在哪里","寻找卡德雷尔"}},{q="卡德雷尔在洛克莫丹扮演什么角色？",a="他是矮人巡山人的一员，负责在塞尔萨玛当地领导层与散布在该地区的偏远岗哨之间进行联络，协调巡逻、补给和边境报告。",al={"卡德雷尔做什么","卡德雷尔的目标","卡德雷尔的工作"}},{q="为什么其他巡山人要派信使去找卡德雷尔？",a="由于他在塞尔萨玛旅店和主要干道旁的核心位置，卡德雷尔成为了战地通讯的枢纽，确保来自远方斥候的紧急报告能够传达给定居点的防御网络。",al={"向卡德雷尔汇报","为什么要向卡德雷尔汇报"}},{q="卡德雷尔与谁进行协调？",a="卡德雷尔经常与前线的其他巡山人共事，包括巡山人卡尔·雷矛和巡山人罗克加，处理侦察更新并分配针对当地威胁的防御任务。",al={"卡德雷尔的联系人","卡德雷尔认识谁"}}},fx={fc9aa592={q="巡山人卡德雷尔是谁？",a="巡山人卡德雷尔是一名驻扎在塞尔萨玛的矮人守卫。作为巡山人组织的一员，这支队伍专职守卫铁炉堡的领土，他协助保卫洛克莫丹地区，组织当地侦察行动，并确保补给线和哨站安全。",al={"卡德雷尔是谁","巡山人卡德雷尔","卡德雷尔的身份"}},["24c7e32d"]={q="巡山人卡德雷尔效忠于哪一方？",a="卡德雷尔坚定地支持铁炉堡王国和联盟。他奉国王麦格尼·铜须之命，与其他巡山人、城镇卫兵及当地矮人并肩作战，守住卡兹莫丹的边境，抵御日益逼近的威胁。",al={"卡德雷尔的阵营","卡德雷尔是联盟的吗","卡德雷尔的效忠对象"}},["3819644d"]={q="巡山人卡德雷尔想要什么？",a="卡德雷尔想要确保塞尔萨玛及洛克莫丹周边荒野的安全。当地兵力捉襟见肘，他正在寻找能干的旅人，协助清剿污染西部山麓的隧道穴居人、四处游荡的豺狼人群，以及其他威胁道路和外围卫兵站的害兽。",al={"卡德雷尔想要什么","卡德雷尔的目标","卡德雷尔的任务目标"}},["56ea1ebe"]={q="巡山人卡德雷尔为什么在塞尔萨玛？",a="卡德雷尔驻扎在烈酒旅店正对面，作为塞尔萨玛的中央联络点。塞尔萨玛是洛克莫丹的主要枢纽，他留在这里便能接收偏远卫兵哨站的报告，并派遣旅人前往最需要援助的地方。",al={"卡德雷尔为什么在塞尔萨玛","卡德雷尔为什么在这里","卡德雷尔的驻地"}},f9923f59={q="巡山人卡德雷尔与谁有联系？",a="卡德雷尔与巡逻山谷的铁炉堡巡山人网络联系密切，其中包括巡山人卡尔·雷矛和巡山人罗克加。他与洛克莫丹各哨站的侦察兵协调，将情报和援军调往承受压力的边境哨站。",al={"卡德雷尔的人脉关系","卡德雷尔与谁共事","卡德雷尔的关系"}}},fp="19,256,23.378.0,22.362.0,39.143.0,37.208.0,50.221.0,33.192.0"}
P.entries["npc:mountaineer-stormpike"] = {n="巡山人卡尔·雷矛",s="巡山人卡尔·雷矛是铁炉堡的一名巡山人，驻守在洛克莫丹北部的奥加兹岗哨。他监视着通往湿地的山口，不知疲倦地工作，以确保重要的补给路线免受穴居人和狗头人的威胁。作为雷矛氏族的一员，他有着崇高的荣誉感，他忠于铁炉堡，并致力于保卫矮人的领土。",h="巡山人卡尔·雷矛是铁炉堡的一名巡山人，驻守在洛克莫丹北部的奥加兹岗哨。他监视着通往湿地的山口，不知疲倦地工作，以确保重要的补给路线免受穴居人和狗头人的威胁。作为雷矛氏族的一员，他有着崇高的荣誉感，他忠于铁炉堡，并致力于保...",kw={"奥加兹","丹","狗头人","洛克","莫丹","巡山人","岗哨","雷矛","湿地"},ang={["faction:Alliance"]="奥加兹岗哨连接着铁炉堡和湿地米奈希尔港的关键陆路通道，雷矛的警惕对于联盟的后勤保障至关重要。",["race:Dwarf"]="对于一名铁炉堡的矮人来说，帮助像雷矛这样的巡山人伙伴，是保护卡兹莫丹内陆边境免受害虫侵扰的一项光荣职责。"},sec={{t="奥加兹岗哨的守卫者",b="奥加兹岗哨坐落在洛克莫丹的北界，是通往险恶的湿地前的一个关键检查点。巡山人卡尔·雷矛就驻守在这里，身处岩石嶙峋的群山与持续不断的野外威胁之中。他的主要职责是维护通讯线路，并确保通过丹奥加兹的旅行者和补给车队的道路畅通。"},{t="应对当地威胁",b="洛克莫丹的北部地区饱受各种害虫的困扰，从侵扰附近挖掘点的狗头人到地下的穴居人，不一而足。雷矛经常招募路过的冒险者来消除这些威胁，特别是那些潜入银泉矿洞并用肮脏的爪子偷走矿工联盟储存的矮人工具的狗头人。"}},faq={{q="在哪里可以找到巡山人卡尔·雷矛？",a="他驻守在奥加兹岗哨，位于洛克莫丹北部，就在那条向北通往丹奥加兹山口并延伸至湿地的山路上。",al={"雷矛位置","雷矛在哪里","巡山人雷矛坐标"}},{q="巡山人卡尔·雷矛是谁？",a="他是来自著名的雷矛氏族的铁炉堡巡山人。他担任岗哨哨兵和侦察兵，负责保卫洛克莫丹的北部山口，抵御周围的野外威胁。",al={"谁是雷矛","巡山人雷矛背景故事","谁是巡山人雷矛"}},{q="他在奥加兹岗哨面对什么样的威胁？",a="这个岗哨经常面临穴居人入侵和在山坡及采石场滋扰的狗头人的麻烦。雷矛致力于消除这些威胁，以便信使和商队能够安全通过。",al={"奥加兹岗哨的危险","什么在攻击奥加兹岗哨","洛克莫丹北部的威胁"}},{q="奥加兹岗哨的目的是什么？",a="奥加兹岗哨作为铁炉堡的一个前哨站，负责监视洛克莫丹与丹奥加兹险峻隧道之间的边界。它是巡逻边境并确保贸易道路畅通的巡山人们的中转站。",al={"什么是奥加兹岗哨","奥加兹岗哨背景故事","奥加兹岗哨的用途"}},{q="他和奥特兰克山谷的雷矛卫队有关系吗？",a="他拥有著名的雷矛氏族的姓氏，这是一个在铁炉堡以骁勇的战士和勘探者而闻名的矮人家族，尽管他目前的命令使他被部署在洛克莫丹的隘口沿线。",al={"奥特兰克雷矛","雷矛氏族渊源","他是雷矛卫队的一员吗"}},{q="巡山人卡尔·雷矛会给冒险者布置什么任务？",a="他指示冒险者从狗头人出没的银泉矿洞中找回矿工联盟的装备，并将他定制新盾牌的订单送到暴风城的矮人护甲大师弗伦·长须手中。",al={"雷矛任务","巡山人雷矛的任务","肮脏的爪子任务"}}},fx={["21d9c7b3"]={q="巡山人卡尔·雷矛效忠于哪一方？",a="巡山人卡尔·雷矛对铁炉堡和铜须氏族忠心耿耿，是一名自豪的矮人巡山人。他奉国王麦格尼·铜须之命守卫山口，坚定地支持联盟，并对黑铁氏族深怀戒心。",al={"巡山人卡尔·雷矛的阵营","巡山人卡尔·雷矛为谁效力","卡尔·雷矛的效忠对象"}},["1b65a761"]={q="巡山人卡尔·雷矛想要什么？",a="卡尔·雷矛驻扎在崎岖的北方道路沿线，想要保护山口免受穴居人、狗头人及其他从山丘上涌来的威胁。他需要可靠的信使和能干的战士来运送物资、清除侵扰的害兽，并维持奥加兹岗哨与洛克莫丹其他地区之间的联络。",al={"卡尔·雷矛想要什么","卡尔·雷矛的目标","巡山人卡尔·雷矛的职责"}},["60d9a34d"]={q="巡山人卡尔·雷矛为什么在奥加兹岗哨？",a="奥加兹岗哨守卫着连接洛克莫丹与湿地的重要北方路线。卡尔·雷矛驻守于此，负责监视山口、协调巡逻，并确保物资和报告能在散布各处的山地哨站与铁炉堡更广泛的防御网络之间安全传递。",al={"巡山人卡尔·雷矛为什么在这里","卡尔·雷矛为什么在奥加兹岗哨","卡尔·雷矛驻扎此地的原因"}}},fp="21,362,25.379.0,29.350.0,39.151.0,29.207.0,48.204.0,32.221.0,55.217.0,58.211.0"}
P.entries["npc:mountaineer-thalos"] = {n="巡山人萨鲁斯",s="巡山人萨鲁斯是驻守在寒脊山小径寒脊山谷一侧入口的矮人哨兵。他负责守卫这条路线，并警告旅行者关于隧道内突发的穴居人侵扰。携带来自山谷的紧急报告的冒险者依靠他来指引前往卡拉诺斯的安全道路。",h="巡山人萨鲁斯是驻守在寒脊山小径寒脊山谷一侧入口的矮人哨兵。他负责守卫这条路线，并警告旅行者关于隧道内突发的穴居人侵扰。携带来自山谷的紧急报告的冒险者依靠他来指引前往卡拉诺斯的安全道路。",kw={"寒脊山小径","寒脊山谷","丹莫罗","铁炉堡巡山人","卡拉诺斯","巡山人萨鲁斯","森内尔·白须","穴居人"},ang={["faction:Alliance"]="萨鲁斯在连接山谷防御力量与铁炉堡中央指挥部的关键山间通道上维持着通讯。",["race:Dwarf"]="对于离开家园摇篮的年轻矮人来说，萨鲁斯是一个严肃的提醒：穴居人的威胁不仅仅是训练演习，而是一场紧逼铁炉堡大门的围攻。",["race:Gnome"]="从诺莫瑞根难民避难所向外旅行的侏儒会发现萨鲁斯守卫在通往卡拉诺斯和铁炉堡的主要陆路路线上。"},sec={{t="寒脊山小径的守护者",b="巡山人萨鲁斯伫立在寒脊山谷与丹莫罗深处岩壁相接的雪域边境，作为离开矮人训练场的旅行者的第一道防线。寒脊山小径已经成为一个险恶的咽喉要道，被从地下深处钻出来的敌对穴居人占领。萨鲁斯在寒风中守望，警告未做好准备的人折返，并评估那些坚韧的信使是否有勇气杀出重围前往更广阔的王国。"},{t="信使检查点",b="当格瑞林·白须完成关于寒脊山谷内霜鬃巨魔动向的报告后，携带报告前往卡拉诺斯交给其兄弟森内尔·白须的信使会被告知在进入隧道前与巡山人萨鲁斯交谈。在确认冒险者有能力通过这充满威胁的通道后，萨鲁斯会指引他们继续前往卡拉诺斯，那里的地区指挥官负责协调丹莫罗的防御。他警惕的守望确保了重要的情报能够抵达铁炉堡的军事领导人手中，而不是遗失在风雪之中。"}},faq={{q="巡山人萨鲁斯是谁？",a="巡山人萨鲁斯是一名驻守在寒脊山小径南侧入口处的铁炉堡巡山人。他的哨位守卫着寒脊山谷与丹莫罗广阔地带之间的边界。",al={"萨鲁斯背景故事","谁是萨鲁斯","巡山人萨鲁斯"}},{q="为什么巡山人萨鲁斯要警告旅行者离开？",a="一群凶残的石颚穴居人侵占了寒脊山小径。萨鲁斯警告平民和新手战士不要尝试穿越，只允许有能力的信使和久经沙场的战士进入。",al={"为什么小径封闭","小径中的穴居人","寒脊山小径的危险"}},{q="巡山人萨鲁斯将冒险者指引向何处？",a="在审阅了来自寒脊山谷的紧急实地报告后，萨鲁斯指引旅行者穿过山径前往卡拉诺斯，那是通往铁炉堡路上最近的定居点。",al={"见到萨鲁斯后去哪里","萨鲁斯的指引方向","下一个城镇"}},{q="萨鲁斯从森内尔·白须那里收到了什么报告？",a="他并没有从森内尔本人那里收到报告。经过萨鲁斯的是格瑞林·白须关于寒脊山谷内霜鬃巨魔威胁的陈述，由前往卡拉诺斯寻找格瑞林的兄弟森内尔的信使携带。萨鲁斯向信使警告了穴居人的威胁，并让他们穿过隧道继续前进。",al={"森内尔的报告","森内尔的快报","萨鲁斯阅读的内容"}},{q="巡山人萨鲁斯属于哪个阵营？",a="萨鲁斯是铁炉堡巡山人的一名宣誓成员，这是一群坚韧的边境游侠，负责为联盟巡逻丹莫罗的边界、隧道和风雪覆盖的山路。",al={"萨鲁斯的阵营","萨鲁斯是铁炉堡人吗","巡山人与联盟"}},{q="不与萨鲁斯交谈，寒脊山小径就无法通过吗？",a="对任何敢于走进其中的人来说，这条小径在物理上是畅通的，但与萨鲁斯交谈能确保冒险者将重要的侦察情报送到卡拉诺斯，并了解前方潜藏的危险。",al={"需要与萨鲁斯交谈吗","绕过萨鲁斯"}}},fx={["37207617"]={q="巡山人萨鲁斯想要什么？",a="巡山人萨鲁斯想要通过警告旅人避开险恶的寒脊山小径来保护他们。隧道已被敌对的穴居人占据，对没有准备的人来说十分危险。遇到有紧急事务的冒险者时，他会提醒他们谨慎穿过隧道，并将格瑞林·白须的报告安全送到卡拉诺斯的弟弟森内尔·白须手中。",al={"萨鲁斯想要什么","萨鲁斯的目标","巡山人萨鲁斯的职责"}},ae07b8df={q="巡山人萨鲁斯与谁有联系？",a="萨鲁斯是铁炉堡巡山人的哨兵，守卫着离开寒脊山谷的通道。携带格瑞林·白须关于霜鬃巨魔的报告、准备送给格瑞林的弟弟——卡拉诺斯的森内尔·白须——的信使，在冒险闯入穴居人横行的隧道前，都会被派去与萨鲁斯交谈。",al={"萨鲁斯的盟友","萨鲁斯与谁共事","萨鲁斯与森内尔·白须"}}},fp="18,308,26.499.0,22.529.0,26.194.0,49.215.0,47.175.0,54.285.0,47.186.0,56.191.0"}
P.entries["npc:mr-smite"] = {n="重拳先生",s="重拳先生是迪菲亚潜行者位于死亡矿井深处旗舰上服役的一位气势威严的牛头人大副。作为绿皮队长麾下的一位武器大师，他以铁腕纪律镇守着通往那艘隐藏巨舰的码头。面对他的入侵者必须小心应对他不断切换的武器库和他那摧枯拉朽的物理力量。",h="重拳先生是迪菲亚潜行者位于死亡矿井深处旗舰上服役的一位气势威严的牛头人大副。作为绿皮队长麾下的一位武器大师，他以铁腕纪律镇守着通往那艘隐藏巨舰的码头。面对他的入侵者必须小心应对他不断切换的武器库和他那摧枯拉朽的物理力量。",kw={"绿皮队长","死亡矿井","大副","铁甲湾","重拳先生","重拳之锤","重拳之剑","牛头人海盗","盗贼之剑"},ang={["class:Warrior"]="重拳先生展现了非凡的武术素养，能够无缝切换敏捷的单手攻击、双持斧击以及威力巨大的双手战锤重击。",["faction:Alliance"]="重拳先生是联盟特工突袭舷梯以接近绿皮队长和艾德温·范克里夫的主要障碍。",["race:Tauren"]="对于任何来自莫高雷的旅行者来说，看到一个牛头人同胞在东部王国的海上亡命徒中担任凶残的大副，实在是一种令人不安的景象。"},sec={{t="海湾大副",b="重拳先生镇守在铁甲湾的码头上，担任地精绿皮队长的大副。虽然迪菲亚潜行者主要由流离失所的人类和与之结盟的地精工匠组成，但重拳先生却是一个引人注目的异类：一个远离卡利姆多大草原、久经沙场的牛头人猛将。他受命在吵闹的海盗船员中维持严苛的秩序，确保艾德温·范克里夫那艘秘密无畏舰的装备工作能够顺利进行。"},{t="致命的武器大师",b="重拳先生不仅仅是一个粗鲁的打手；他还是一个富有表演天赋且技艺全面的武器大师。他喜欢戏弄那些所谓的英雄，故意拖延战斗，给对手带来虚假的希望。当被逼入绝境时，他会发动震撼大地的一击，将敌人击晕，同时在旁边的武器箱里翻找新的装备。他以轻盈的单手剑开始战斗，随后会切换成双持劈砍斧，最后在彻底被激怒时会拿出他那巨大的双手战锤。"}},faq={{q="为什么一个牛头人会在西部荒野与人类强盗合作？",a="虽然绝大多数牛头人都与他们的部落盟友居住在卡利姆多，但偶尔也会有流浪的雇佣兵和游侠来到东部王国。重拳先生作为绿皮队长的大副为迪菲亚潜行者效力，在无畏舰准备出海期间维持着海湾内船员的秩序。",al={"为什么牛头人会在死亡矿井","重拳先生背景故事","牛头人海盗"}},{q="重拳先生的上司是谁？",a="重拳先生直接听命于绿皮队长，那位停泊在铁甲湾的海盗船的地精船长。在他们之上，整个阴谋的幕后黑手是迪菲亚潜行者的首领，艾德温·范克里夫。",al={"重拳先生的老板是谁","重拳先生为谁工作"}},{q="重拳先生在战斗中使用什么武器？",a="重拳先生在战斗开始时使用盗贼之剑。随着战斗局势对他不利，他会撤退到武器箱旁装备上一对重拳之剑，在被逼到极限时，他最终会掏出重拳之锤。",al={"重拳先生的武器","重拳先生从箱子里拿出什么"}},{q="在哪里可以找到重拳先生？",a="重拳先生站在铁甲湾的木质栈桥上，那里是死亡矿井内的最后一处洞穴，他守护着通往巨大的迪菲亚无畏舰的舷梯。",al={"重拳先生的位置","重拳先生在哪里"}},{q="重拳先生是独自作战吗？",a="重拳先生在身旁隐藏了两名潜行的迪菲亚潜行者，随时准备伏击任何沿着码头向船只推进的不速之客。",al={"重拳先生的随从","重拳先生的保镖"}},{q="是什么让重拳先生在近战中如此危险？",a="他标志性的牛头人战争践踏会在木制码头上引发冲击波，将整队的冒险者击晕，让他有足够的时间从储物箱里更换武器，并用更沉重的装备重新发动攻击。",al={"重拳先生的昏迷","重拳先生的战争践踏"}}},fx={ecfcf591={q="重拳先生是谁？",a="重拳先生是一名实力强悍的牛头人武器大师，担任死亡矿井深处隐藏的巨型战舰上的大副。他直接听命于绿皮队长，指挥迪菲亚潜行者的码头防御，并以铁腕手段和一库致命武器管束手下的恶棍。",al={"重拳是谁","重拳先生的身份","重拳先生是什么人"}},["8cad5068"]={q="重拳先生效忠于哪一方？",a="尽管是牛头人，重拳先生既不效忠部落，也不效忠他在卡利姆多的同族。他坚定地站在艾德温·范克里夫的迪菲亚潜行者一方，是他们的地精海军指挥官绿皮队长的副手。",al={"重拳先生的阵营","重拳为谁效力","重拳是部落成员还是迪菲亚潜行者"}},["1c026e95"]={q="重拳先生为何声名显赫或令人畏惧？",a="重拳先生以蛮横的体格和难以捉摸的战斗技巧令人畏惧。他恶名昭彰，喜欢戏弄受害者，让他们以为自己占了上风，再用震天一跺将他们击晕，接着从箱子里取出越来越致命的武器，彻底解决他们。",al={"重拳先生为何令人畏惧","重拳先生的名声","重拳为何出名"}}},fp="9,349,22.480.0,21.512.0,55.298.0,28.219.0,49.205.0,29.166.0,27.133.0,52.214.0"}
P.entries["npc:mull-thunderhorn"] = {n="穆尔·雷角",s="穆尔·雷角是一位居住在莫高雷血蹄村的牛头人长者。他深深地信奉大地母亲与土地的平衡，守护着散布在平原各处的圣水井。由于外部的剥削者威胁着该地区赖以生存的水源，穆尔引导着年轻的牛头人完成净化祖先之泉所需的仪式。",h="穆尔·雷角是一位居住在莫高雷血蹄村的牛头人长者。他深深地信奉大地母亲与土地的平衡，守护着散布在平原各处的圣水井。由于外部的剥削者威胁着该地区赖以生存的水源，穆尔引导着年轻的牛头人完成净化祖先之泉所需的仪式。",kw={"血蹄村","莫高雷","穆尔·雷角","毒水","雷角图腾","荆棘谷地精","水井","狂鬃净化","冬蹄净化"},ang={["class:Druid"]="德鲁伊们同样认同穆尔的紧迫感，他们亲眼见证了被污染的水井是如何毒害莫高雷野生动物的平衡的。",["class:Shaman"]="萨满们会理解穆尔对元素和谐的依赖，因为他的净化图腾利用了祖先之灵来修复那些因机械贪婪而破碎的水域。",["faction:Horde"]="穆尔的抗争凸显了部落与荆棘谷地精这类未经协调、肆意剥削的组织之间的摩擦，这些组织在未获得许可的情况下掠夺卡利姆多的财富。",["race:Tauren"]="对于牛头人而言，穆尔·雷角代表了部族记忆和祖先职责，引导着年轻的勇士们保护圣地平原免受贪婪的外来入侵者侵害。"},sec={{t="圣水守护者",b="穆尔·雷角伫立在血蹄村中，肩负着莫高雷精神福祉的重担。各个游牧部族在凯恩·血蹄大酋长的号召下聚集起来，建立了一个永久的家园，然而他们的土地却已受到贪婪和鲁莽扩张的围困。穆尔成为了从纳拉其营地走出的年轻勇士们的精神支柱，召唤他们去捍卫祖先留下的宝贵资源。"},{t="被污染的水井与荆棘谷地精",b="穆尔面临的首要危机是莫高雷水源突发的污染，受影响的水井包括冬蹄水井、雷角水井和狂鬃水井。这种恶劣的污染源自荆棘谷地精，这是一个肆无忌惮的商业组织，他们在周边的山丘上进行采掘活动，并将毒素倾倒进当地的地下水层。穆尔指导年轻的牛头人制作特定的净化图腾，并在污染蔓延到土地和野生动物之前，在每一口祖先水井进行净化仪式。"}},faq={{q="穆尔·雷角是谁？",a="穆尔·雷角是莫高雷血蹄村的一位牛头人任务发布者。他担任当地圣水井的守护者，提供仪式和祭礼以保持大地及其水源免受外界污染。",al={"穆尔·雷角背景故事","穆尔是谁","血蹄村穆尔"}},{q="为什么穆尔·雷角对水井感到担忧？",a="这些祖先水井——如冬蹄水井、雷角水井和狂鬃水井——是莫高雷部族和野生动物的生命之源。附近的侵入性作业用有害的径流和污染物玷污了这些神圣的泉水，威胁到了平原的自然平衡。",al={"为什么水井被下毒","莫高雷水井","冬蹄水井污染"}},{q="是谁在污染莫高雷的水井？",a="污染是由荆棘谷地精造成的，这是一个鲁莽的地精企业，在莫高雷边缘建立工业采矿和伐木据点。他们的行动对神圣的景观毫无尊重，将工业毒素排入了当地的地下水层。",al={"谁污染了水源","莫高雷的荆棘谷地精","谁玷污了水井"}},{q="为什么穆尔的净化任务只涉及牛头人？",a="水井与牛头人部族的起源血脉——包括雷角氏族、冬蹄氏族和狂鬃氏族——有着深刻的祖先和精神联系。净化水井被视为成熟的牛头人的一项神圣成人礼和文化职责。",al={"牛头人专属任务","为什么只有牛头人","穆尔·雷角要求"}},{q="水井是如何净化的？",a="穆尔指示旅行者收集经过特别神圣化的图腾，这些图腾中灌注了来自大地的祭品，例如莫高雷野兽的爪、趾和牙齿。一旦神圣化完成，这些图腾会被直接带到被玷污的水井处，引导精神净化之力冲刷掉那些不自然的毒素。",al={"如何净化水井","净化图腾","清洁水源"}},{q="什么是幻象仪式？",a="幻象仪式是年轻牛头人为了与祖先和动物之灵沟通而进行的一项基础精神旅程。初试者会被派往血蹄村的扎尔曼·双月处，作为大地母亲仪式的一部分来接受这次幻象考验。",al={"幻象仪式任务","什么是幻象仪式"}}},fx={["7b9ffdeb"]={q="穆尔·雷角效忠于哪一方？",a="穆尔忠心地支持自己的族人和部落，心系居住在莫高雷的各个部族。作为血蹄村备受尊敬的一员，他守望着祖先留下的平原，并响应精神的召唤，保护族人及其圣地免遭外界腐化。",al={"穆尔·雷角的阵营","穆尔是部落成员吗","穆尔为谁效力"}},be00c091={q="穆尔·雷角想要什么？",a="穆尔想要恢复并净化莫高雷的圣泉，包括冬蹄泉、雷角泉和蛮鬃泉。他正在寻找值得信赖的牛头人，制作传统图腾并施行至关重要的净化仪式，以消除威胁这片土地命脉的邪恶污染。",al={"穆尔想要什么","穆尔·雷角的目标","穆尔为什么需要帮助"}}},fp="16,359,29.438.0,37.540.1,24.237.0,54.293.0,44.271.0,54.266.0,33.307.0,27.268.0"}
P.entries["npc:mupsi-shacklefridd"] = {n="穆普斯·沙克菲德",s="穆普斯·沙克菲德是一位驻扎在贫瘠之地棘齿城外围的地精。她是那些希望改善与热砂财阀紧张关系的旅行者的当地联络人。",h="穆普斯·沙克菲德是一位驻扎在贫瘠之地棘齿城外围的地精。她是那些希望改善与热砂财阀紧张关系的旅行者的当地联络人。",kw={"贫瘠之地","地精","穆普斯","棘齿城","声望","沙克菲德","热砂"},sec={{t="棘齿城外围",b="穆普斯·沙克菲德在贫瘠之地尘土飞扬的沿海道路上，就在棘齿城外活动。这座港口城镇附近的生活总是很繁忙，热砂财阀的卫兵在四周巡逻，商人们来来往往。对于那些在地精面前声望不佳的旅行者，只要他们愿意提供财阀所要求的物资和劳动力，穆普斯就能为他们提供一条重归于好的途径。"}},faq={{q="穆普斯·沙克菲德是谁？",a="她是一位驻扎在贫瘠之地棘齿城定居点外围的地精，专门协助那些寻求恢复热砂财阀声望的旅行者。",al={"穆普斯","穆普斯是谁","棘齿城穆普斯"}},{q="我在哪里可以找到她？",a="穆普斯位于贫瘠之地的棘齿城外，距离主城镇很近，往来的港口卫兵和巡逻队偶尔会经过她所在的地方。",al={"穆普斯位置","穆普斯·沙克菲德在哪里","寻找穆普斯"}},{q="为什么人们要找穆普斯·沙克菲德交谈？",a="那些惹恼了热砂财阀的旅行者——通常是因为与地精发生冲突或偏袒海盗——可以通过向穆普斯捐赠物资来修复他们的声望。",al={"棘齿城修复旧痕","棘齿城声望上交","穆普斯任务"}}},fx={["8798c45f"]={q="穆普斯·沙克菲德效忠于哪一方？",a="穆普斯·沙克菲德归属热砂港，在棘齿城港务机构的管辖下行事。和城中大多数地精一样，她对联盟和部落都保持商业上的中立，优先考虑贸易、物资和金币，而非政治纷争。",al={"穆普斯·沙克菲德的阵营","穆普斯为谁效力","穆普斯·沙克菲德保持中立吗"}},a81ff16f={q="穆普斯·沙克菲德想要什么？",a="穆普斯正在为许多在与血帆海盗交锋时受伤的水手寻求帮助。她提供机会，让人们通过带来制作绷带的亚麻布和装药剂的空瓶，赢得热砂港的好感，修复与其紧张的关系。",al={"穆普斯想要什么","穆普斯·沙克菲德的动机","为什么要帮助穆普斯"}},["8b7e7b21"]={q="穆普斯·沙克菲德为什么驻扎在棘齿城外？",a="她驻扎在棘齿城郊外，负责为接近繁忙港口的旅人提供联络和后勤服务。她在中央码头外围活动，可以拦下需要交易物资或修复与热砂港关系的商人、流亡者和冒险者。",al={"穆普斯为什么在这里","穆普斯·沙克菲德驻扎此地的原因","穆普斯为什么在棘齿城外"}}},fp="18,219,27.406.0,26.165.0,21.158.0,45.185.0"}
P.entries["npc:mutanus-the-devourer"] = {n="吞噬者穆坦努斯",s="吞噬者穆坦努斯是一个直接从翡翠梦魇中显现出的可怖苍白鱼人。它潜伏在沉睡的德鲁伊纳拉雷克斯心灵深处最阴暗的角落，每当有人试图打破梦魇对哀嚎洞穴的控制时，它就会出现并将闯入者吞噬。击败这个扭曲的畸变体是解救纳拉雷克斯，使其从痛苦的沉睡中苏醒的最后一步。",h="吞噬者穆坦努斯是一个直接从翡翠梦魇中显现出的可怖苍白鱼人。它潜伏在沉睡的德鲁伊纳拉雷克斯心灵深处最阴暗的角落，每当有人试图打破梦魇对哀嚎洞穴的控制时，它就会出现并将闯入者吞噬。击败这个扭曲的畸变体是解救纳拉雷克斯，使其从...",kw={"白化鱼人","贫瘠之地","深渊之戒","吞噬者","翡翠梦魇","鱼人","穆坦努斯","纳拉雷克斯","哀嚎洞穴"},ang={["class:Druid"]="穆坦努斯代表了在没有保护措施的情况下过深钻研翡翠梦境所带来的恐怖危险，因为一位德鲁伊同胞的心灵被腐蚀完全吞噬了。",["faction:Horde"]="部落绝不能允许穆坦努斯和梦魇腐蚀贫瘠之地的核心，威胁到维持杜隆塔尔和莫高雷生存的重要绿洲水源。",["race:NightElf"]="对于卡多雷来说，穆坦努斯是一场活生生的悲剧，体现了纳拉雷克斯治愈贫瘠之地的崇高抱负是如何扭曲成一场可怕的梦魇的。"},sec={{t="织梦者最深处的恐惧",b="当暗夜精灵德鲁伊纳拉雷克斯试图利用贫瘠之地地下的泉水，通过将它们与翡翠梦境连接来恢复这片荒芜之地的生机时，一种被称为翡翠梦魇的古老腐蚀入侵了他的思想。纳拉雷克斯被困在痛苦的幻象中，他潜意识里的恐惧化为了实体。这种腐蚀将那个梦魇塑造成了一个巨大的白化鱼人的形状。"},{t="清醒的梦魇",b="穆坦努斯被寄生在纳拉雷克斯意识中的黑暗力量派往清醒的世界，任务是确保这位德鲁伊永远无法醒来。当纳拉雷克斯的追随者进行仪式唤醒他们的导师时，穆坦努斯便打破了梦境与现实的界限。只要穆坦努斯不倒下，纳拉雷克斯就将永远是他自己那被腐蚀的想象力的囚徒。"}},faq={{q="什么是吞噬者穆坦努斯？",a="吞噬者穆坦努斯是一个诞生于翡翠梦魇的巨大苍白鱼人状畸变体。他并非艾泽拉斯的普通居民，而是一个从沉睡的德鲁伊纳拉雷克斯那受腐蚀的心灵中召唤至现实的活梦魇。",al={"谁是穆坦努斯","穆坦努斯是什么生物","穆坦努斯是鱼人吗"}},{q="为什么穆坦努斯看起来像个巨大的鱼人？",a="穆坦努斯是纳拉雷克斯梦魇的显现，腐蚀赋予了它巨大白化鱼人的外形。梦魇为何选择这种形态尚不得而知。",al={"为什么是鱼人","为什么穆坦努斯是鱼人","纳拉雷克斯鱼人恐惧"}},{q="为什么穆坦努斯会在仪式结束时出现？",a="腐蚀翡翠梦境的黑暗存在命令穆坦努斯阻止任何人打破纳拉雷克斯的沉睡。当纳拉雷克斯的追随者开始唤醒仪式时，穆坦努斯便穿越到现实的洞穴中，吞噬那些救援者。",al={"穆坦努斯何时刷新","为什么要召唤穆坦努斯","纳拉雷克斯仪式首领"}},{q="穆坦努斯来自哪里？",a="穆坦努斯源自翡翠梦魇，那是困住纳拉雷克斯的腐蚀领域。",al={"穆坦努斯的起源","穆坦努斯来自梦魇吗","翡翠梦魇穆坦努斯"}},{q="击败穆坦努斯能救出纳拉雷克斯吗？",a="能。一旦穆坦努斯被击杀，梦魇对纳拉雷克斯心灵的直接控制就会破碎，使得他的追随者能够成功唤醒这位德鲁伊，并打破洞穴中的黑暗昏迷状态。",al={"纳拉雷克斯获救了吗","穆坦努斯死后会发生什么","唤醒纳拉雷克斯"}},{q="为什么穆坦努斯免疫暗影魔法？",a="穆坦努斯是由黑暗梦魇能量编织而成的畸变体，这使他天生对那些能伤害普通野兽的死灵和暗影法术具有抗性。",al={"穆坦努斯暗影免疫","暗影法术穆坦努斯","穆坦努斯免疫暗影吗"}}},fx={["1d17d2ec"]={q="吞噬者穆坦努斯效忠于哪一方？",a="穆坦努斯听命于某种侵染翡翠梦境、将纳拉雷克斯困在噩梦中的黑暗腐化力量。他并非随心行事，也不是为贫瘠之地的本土野兽效力，而是服从噩梦本身的意志，被派往清醒世界，只为确保这名德鲁伊继续沉睡并遭受腐化。",al={"谁控制着穆坦努斯","穆坦努斯的阵营","穆坦努斯的效忠对象"}},["93f250d8"]={q="吞噬者穆坦努斯想要什么？",a="穆坦努斯存在的目的，就是阻止任何唤醒纳拉雷克斯的尝试。他要吞噬任何试图将沉睡的德鲁伊从噩梦掌控中解救出来的人，确保纳拉雷克斯无力反抗，让黑暗腐化继续在哀嚎洞穴中蔓延。",al={"穆坦努斯的目标","穆坦努斯为什么战斗","穆坦努斯想要做什么"}},c0fe9c52={q="吞噬者穆坦努斯与谁有关？",a="吞噬者穆坦努斯与暗夜精灵德鲁伊纳拉雷克斯有直接关联。他并非贫瘠之地自然诞生的野兽，而是纳拉雷克斯遭到腐化的心灵深处最黑暗角落所化为的实体，体现了这位德鲁伊潜意识中的恐惧，如同扭曲的噩梦降临于现实世界。",al={"穆坦努斯与纳拉雷克斯的关联","穆坦努斯和纳拉雷克斯的关系","穆坦努斯与谁有关"}}},fp="20,358,22.414.0,20.344.1,29.236.0,42.164.0,49.236.0,29.93.0,34.184.1,38.158.0"}
P.entries["npc:mux-manascrambler"] = {n="穆克斯·玛纳斯卡波",s="穆克斯·玛纳斯卡波是一位古怪的地精工程师，居住在加基森的沙漠前哨站。与许多专注于爆炸物或采矿设备的同行不同，穆克斯对超自然和神秘能量有着独特的痴迷。",h="穆克斯·玛纳斯卡波是一位古怪的地精工程师，居住在加基森的沙漠前哨站。与许多专注于爆炸物或采矿设备的同行不同，穆克斯对超自然和神秘能量有着独特的痴迷。",kw={"灵质","加基森","幽灵","地精工程师","玛纳斯卡波","穆克斯","塔纳利斯"},ang={["profession:Engineering"]="穆克斯在地精修补匠中是个异类，他应用机械齿轮和动力电池来捕获和提取无形的超自然力量，而不是仅仅把东西炸飞。"},sec={{t="未见之物的修补匠",b="穆克斯·玛纳斯卡波藏在加基森中心的一栋建筑里，位置在Driz Plunkbow和他那叮当作响的屠夫机器人（Butcherbots）身后。虽然热砂港主要从事石油、枪支和废料贸易，但穆克斯将其聪明才智集中在更深奥的领域：灵魂和超自然异常的境界。他利用自己的技术敏锐度设计出奇特的装置，能够探测、提取并与幽灵残骸进行交互，将粗糙的地精工艺与死者隐形的世界连接起来。"}},faq={{q="我在哪里可以找到穆克斯·玛纳斯卡波？",a="穆克斯居住在塔纳利斯北部的加基森。你可以在这座沙漠贸易中心中心附近的一栋建筑里找到他，他就位于Driz Plunkbow和切割肉块的屠夫机器人身后。",al={"穆克斯位置","穆克斯在哪里","穆克斯·玛纳斯卡波地图"}},{q="穆克斯从事什么样的工作？",a="穆克斯是一位痴迷于灵魂和隐形力量的工程师。他构建的不是标准的爆破或运输装置，而是能够揭示灵魂、提取灵质并利用奥术超自然力量的专业装置。",al={"穆克斯工作","穆克斯卖什么","穆克斯研究"}},{q="穆克斯属于某个阵营吗？",a="穆克斯隶属于在加基森运营的热砂港。作为一名独立的地精行动者，他保持着严格的商业中立，并愿意帮助部落或联盟的冒险者。",al={"穆克斯是部落吗","穆克斯是中立吗","穆克斯联盟"}}},fp="17,249,24.504.0,35.208.0,30.236.0,29.215.0"}
P.entries["npc:mydrannul"] = {n="迈德兰努尔",s="迈德兰努尔是一名暗夜精灵杂货商，驻守在达纳苏斯的战士区。他为首都的哨兵、士兵和游客提供服务，确保基础补给品、弹药和粮草随时供应。",h="迈德兰努尔是一名暗夜精灵杂货商，驻守在达纳苏斯的战士区。他为首都的哨兵、士兵和游客提供服务，确保基础补给品、弹药和粮草随时供应。",kw={"弹药","达纳苏斯","杂货","迈德兰努尔","泰达希尔","商人","战士区"},ang={["faction:Alliance"]="抵达泰达希尔的联盟旅行者可以信赖像战士区的迈德兰努尔这样的商人，以获取基本的背包、弹药和野外口粮。",["race:NightElf"]="对于在达纳苏斯训练的暗夜精灵来说，迈德兰努尔提供必要的日常装备和箭矢，以确保哨兵们获得充分的补给。"},sec={{t="战士区的补给品",b="迈德兰努尔位于战士区的军事亭和训练场之中，为达纳苏斯的保卫者和旅行冒险者提供必要的装备。他出售在野外生活中所需的实用日常用品：弓箭手和枪手的弹药、投掷刃、打火石、袋子以及简单的口粮。通过经营他在这个城市军事区的摊位，他确保了正在泰达希尔准备执行任务的哨兵和学员不会缺少基本的日用品。"}},faq={{q="在哪里可以找到迈德兰努尔？",a="迈德兰努尔位于战士区，即达纳苏斯位于泰达希尔树冠上的东南部军事区。",al={"迈德兰努尔位置","迈德兰努尔在哪里","迈德兰努尔地图"}},{q="迈德兰努尔出售什么商品？",a="他是一名杂货商，库存有容器、简单的口粮、饮料以及打火石和火绒等野外制作工具，同时也出售投掷武器和箭矢、子弹等弹药。",al={"迈德兰努尔商品","迈德兰努尔卖什么","迈德兰努尔商人物品"}},{q="迈德兰努尔提供任务吗？",a="是的。除了出售补给品，迈德兰努尔还会指引冒险者去找他的朋友内萨·影歌（Nessa Shadowsong），这是一位在鲁瑟兰村的钓鱼商，她需要有人把一个包裹送到黑海岸（Darkshore）。",al={"迈德兰努尔任务","迈德兰努尔的任务"}}},fx={cca0dfd1={q="迈德兰努尔是谁？",a="迈德兰努尔是一名居住在达纳苏斯的暗夜精灵商人，在战士区经营生意。他为这座暗夜精灵首都供应日常必需品、补给和弹药，是一名杂货商，为旅行者、本地居民和士兵提供服务。",al={"迈德兰努尔是谁","迈德兰努尔的身份","迈德兰努尔与达纳苏斯"}},["34e3a734"]={q="迈德兰努尔支持哪一方？",a="迈德兰努尔坚定效忠于达纳苏斯和联盟。作为一名居住在他们神圣世界之树中心地带的暗夜精灵，他乐于为自己的同胞以及途经这座城市的联盟冒险者效劳。",al={"迈德兰努尔的阵营","迈德兰努尔的效忠对象","迈德兰努尔属于联盟吗"}},["6cf1b6fe"]={q="迈德兰努尔为什么在这里？",a="迈德兰努尔驻扎在达纳苏斯的战士区，在此经营商店，为准备巡逻或远行的人提供装备。他的存在确保防卫者和旅人能在城市训练场附近轻松获得所需补给。",al={"迈德兰努尔为什么在这里","迈德兰努尔在达纳苏斯的职责","迈德兰努尔在这里做什么"}},a5485425={q="迈德兰努尔想要什么？",a="迈德兰努尔追求诚信经营，为达纳苏斯愿意与他交易的人提供可靠的日用品、食物和弹药。",al={"迈德兰努尔想要什么","迈德兰努尔的目标","迈德兰努尔的动机"}}},fp="9,224,33.502.0,29.134.0,31.190.0,32.172.0"}
P.entries["npc:nalpak"] = {n="纳尔帕克",s="纳尔帕克是一位牛头人德鲁伊学徒，负责监视贫瘠之地中危机四伏的哀嚎洞穴。他驻扎在俯瞰洞穴入口的一处高处岩洞中，征召路过的冒险者协助遏制那些扭曲了地下生态系统的梦魇。",h="纳尔帕克是一位牛头人德鲁伊学徒，负责监视贫瘠之地中危机四伏的哀嚎洞穴。他驻扎在俯瞰洞穴入口的一处高处岩洞中，征召路过的冒险者协助遏制那些扭曲了地下生态系统的梦魇。",kw={"贫瘠之地德鲁伊","变异鳞片","纳拉雷克斯的学徒","纳尔帕克","纳拉雷克斯","牛头人","哀嚎洞穴"},ang={["class:Druid"]="对于其他德鲁伊来说，纳尔帕克是一个严酷的警示，提醒着当黑暗根植于本应是复苏仪式的梦境中时，接触翡翠梦境是多么危险。",["race:Tauren"]="纳尔帕克代表了牛头人致力于治愈卡利姆多干涸土地的信念，即使在做梦者遭遇灾难时，他也拒绝放弃这项使命。"},sec={{t="洞穴之上的守望者",b="纳尔帕克栖身于哀嚎洞穴入口正上方一处隐秘的岩洞中，始终效忠于纳拉雷克斯的愿景。当他的导师深陷下方被腐蚀的沉睡中无法自拔时，纳尔帕克致力于遏制不断蔓延的腐化。他请求冒险者收集变异鳞片以用作皮革。"}},faq={{q="纳尔帕克在哪里？",a="纳尔帕克位于贫瘠之地中部，哀嚎洞穴入口正上方的一处高处岩洞中。",al={"纳尔帕克位置","纳尔帕克在哪里","寻找纳尔帕克"}},{q="纳尔帕克是谁？",a="他是一位牛头人德鲁伊，也是纳拉雷克斯的学徒之一，任务是监视哀嚎洞穴中不断涌出的扭曲生物，而他的导师则试图通过翡翠梦境来复苏贫瘠之地。",al={"纳尔帕克是谁","纳尔帕克背景故事"}},{q="为什么纳尔帕克需要变异鳞片？",a="纳尔帕克想要研究那些侵扰哀嚎洞穴的变异生物的鳞片。尽管这些生物邪恶，但他认为它们那不同寻常的鳞片可以在制皮中发挥作用。",al={"为什么需要变异鳞片","变异鳞片任务"}},{q="纳尔帕克与纳拉雷克斯是什么关系？",a="纳尔帕克是德鲁伊纳拉雷克斯忠实的学徒和追随者，作为被派来协助实现复苏贫瘠之地泉水这一宏伟目标的学徒之一。",al={"纳尔帕克是纳拉雷克斯的学徒吗","纳尔帕克和纳拉雷克斯"}}},fx={a6c930b7={q="纳尔帕克支持哪一方？",a="纳尔帕克是纳拉雷克斯的门徒，为那些寻求治愈贫瘠之地的德鲁伊效力。他是一名牛头人，欢迎进入洞穴助其一臂之力的人，但他最效忠的仍是纳拉雷克斯的愿景，以及恢复遭到腐化的地下泉水。",al={"纳尔帕克的阵营","纳尔帕克为谁效力","纳尔帕克属于部落吗"}},ddc6c0b5={q="纳尔帕克为什么在哀嚎洞穴？",a="纳尔帕克与纳拉雷克斯及其他门徒一同来到哀嚎洞穴，试图将翡翠梦境的力量引入干旱的贫瘠之地。仪式惨遭失败后，他留守在洞穴入口附近，招募冒险者收集遭到腐化的材料，并对付洞穴中的扭曲野兽。",al={"纳尔帕克为什么在这里","纳尔帕克在哀嚎洞穴的缘由","是什么让纳尔帕克来到这里"}}},fp="6,259,25.309.0,24.154.0,14.216.0,35.190.0,41.173.0"}
P.entries["npc:nara-meideros"] = {n="娜拉·梅德隆",s="娜拉·梅德隆是一位驻守在暴风城公园那片宁静绿地中的暗夜精灵女祭司。作为一名新手导师，她在人类首都传授艾露恩的教义。",h="娜拉·梅德隆是一位驻守在暴风城公园那片宁静绿地中的暗夜精灵女祭司。作为一名新手导师，她在人类首都传授艾露恩的教义。",kw={"艾露恩","娜拉·梅德隆","暗夜精灵祭司","祭司训练师","暴风城","公园"},ang={["class:Priest"]="对于游历东部王国的暗夜精灵祭司而言，娜拉提供重要的种族虔诚指导和教诲，而无需他们长途跋涉返回卡利姆多。",["race:NightElf"]="远离灰谷和泰达希尔的森林，娜拉·梅德隆和公园在人类首都繁华的石墙内提供了一片令人慰藉的家园碎片。"},sec={{t="暴风城的女祭司",b="虽然大多数艾露恩的女祭司都留在卡利姆多泰达希尔的枝叶下，但娜拉·梅德隆却居住在无尽之海彼岸的暴风城。她位于公园——一个由到访的暗夜精灵德鲁伊和祭司精心照料的避风港——指导年轻的求道者遵循神圣虔诚之道。在Cathedral Square与信仰圣光的人类修行者一道，娜拉为居住在东部王国或到访此地的暗夜精灵提供了一条与月亮女神之恩典的熟悉纽带。"}},faq={{q="我在哪里可以找到娜拉·梅德隆？",a="娜拉·梅德隆位于暴风城的公园区，周围环绕着月亮井和参天大树，这些景象让暗夜精灵旅行者倍感亲切。",al={"娜拉·梅德隆位置","娜拉·梅德隆在哪里","公园祭司训练师"}},{q="娜拉·梅德隆担任什么职责？",a="她是一位祭司训练师，协助新手和成长中的祭司，并指引人类祭司前往Cathedral of Light学习诸如绝望祷言之类的虔诚法术。",al={"娜拉的工作","娜拉·梅德隆的目的","娜拉·梅德隆是谁"}},{q="为什么会有暗夜精灵女祭司住在暴风城？",a="随着达纳苏斯的暗夜精灵与大联盟之间的联系日益紧密，暗夜精灵特使、德鲁伊和祭司们在公园保持着活跃，以帮助他们的族人并弘扬他们的精神传统。",al={"她为什么在暴风城","暴风城的暗夜精灵"}}},fx={["07f550b7"]={q="娜拉·梅德隆是谁？",a="娜拉·梅德隆是一名侍奉艾露恩姐妹会的暗夜精灵月之女祭司。她被派驻在远离故土的地方，与联盟的凡人盟友为伍，引导虔诚的侍僧学习本族的信仰传统和神圣教义。",al={"娜拉·梅德隆是谁","娜拉是谁","娜拉·梅德隆的背景"}},["6f64ae70"]={q="娜拉·梅德隆支持哪一方？",a="她完全效忠于卡多雷和联盟，作为暗夜精灵信仰的使者，为寻求与神圣圣光沟通并希望领悟艾露恩教诲的牧师提供指引。",al={"娜拉·梅德隆的阵营","娜拉·梅德隆为谁效力","娜拉·梅德隆属于联盟吗"}}},fp="13,205,24.491.0,31.148.0,35.176.0,51.220.0"}
P.entries["npc:narain-soothfancy"] = {n="纳瑞安",s="纳瑞安是一位古怪的侏儒，住在塔纳利斯热砂港北边的一间偏僻海滩小屋里。虽然他大肆宣扬自己是一位能预知未来的占卜大师，但认识他的人都认为，与他真正的工程学天赋相比，他的灵能天赋纯属无稽之谈。",h="纳瑞安是一位古怪的侏儒，住在塔纳利斯热砂港北边的一间偏僻海滩小屋里。虽然他大肆宣扬自己是一位能预知未来的占卜大师，但认识他的人都认为，与他真正的工程学天赋相比，他的灵能天赋纯属无稽之谈。",kw={"艾索雷葛斯","工程师","纳瑞安","占卜师","热砂港","塔纳利斯"},ang={["profession:Engineering"]="工程学玩家会发现纳瑞安那些天马行空的装置非常引人入胜，即使他更愿意假装这些机械成就是所谓的神秘预言。",["race:Gnome"]="纳瑞安是侏儒天才古怪一面的典型代表，将卓越的科技问题解决能力与离奇、偏执的爱好结合在了一起。"},sec={{t="灵能愿景与工程实践",b="纳瑞安住在塔纳利斯东海岸，热砂港北边，这位退休的工程师摇身一变，自称为占卜大师。他经常通过把未拆封的信封贴在额头上，或是对他人的来意做出极其离谱的猜测来接待访客，比如询问他们是否是为了寻找传说中的灰烬使者而来。尽管他喜欢装腔作势，但纳瑞安确实拥有深厚的技术知识。即使是像蓝龙艾索雷葛斯这样的上古存在也指出，虽然纳瑞安是个蹩脚的灵能者，但他无疑是一位天才的工程师。附近放着一本名为《傻瓜占卜指南》的手册。"},{t="海岸坠机",b="在定居热砂港之前，纳瑞安在遥远南方的天涯海滩遭遇了一次灾难性的飞行器坠毁事故。多亏了意外的营救，他才在事故中幸存下来。然而，由于他那古怪的个性和奇怪的执念，他一直孤居于荒漠海岸，摆弄着与奥术相关的技术，并向路过的每一个人兜售那些不可靠的预言。"}},faq={{q="纳瑞安是谁？",a="纳瑞安是一位住在塔纳利斯热砂港北边的退休侏儒工程师。他宣称自己是一位占卜大师，尽管他的预言以不准而闻名。",al={"纳瑞安背景故事","纳瑞安是谁","塔纳利斯的灵能侏儒"}},{q="纳瑞安真的是灵能者吗？",a="不。像巨龙艾索雷葛斯这样强大的熟人都公开称他为糟糕的灵能者。他真正的天赋在于精湛的工程学和机械制作，尽管他总是表演性地尝试读心。",al={"纳瑞安能预知未来吗","纳瑞安是灵能者吗","纳瑞安占卜师"}},{q="他身边那本《傻瓜占卜指南》是什么书？",a="这是放在纳瑞安小屋里的一本与专业技能相关的手册。纳瑞安会将寻找此类知识的旅行者指引向这本书。",al={"傻瓜占卜指南","纳瑞安专业技能书"}},{q="纳瑞安是怎么认识艾索雷葛斯的？",a="纳瑞安是漫游在艾萨拉的蓝龙艾索雷葛斯的一位老相识。尽管纳瑞安装腔作势，但巨龙对他无与伦比的工程和制造能力表示尊重。",al={"纳瑞安与艾索雷葛斯","蓝龙与纳瑞安"}}},fp="17,315,37.654.0,17.384.0,25.187.0,29.209.0,54.138.0,30.187.0"}
P.entries["npc:naralex"] = {n="纳拉雷克斯",s="纳拉雷克斯是一位暗夜精灵德鲁伊，他曾试图利用翡翠梦境的力量，将干涸的贫瘠之地恢复为郁郁葱葱的森林。然而，他的沉睡却被一场黑暗的梦魇所侵袭，扭曲了地底的哀嚎洞穴，并将他的追随者变成了剧毒的魔物。",h="纳拉雷克斯是一位暗夜精灵德鲁伊，他曾试图利用翡翠梦境的力量，将干涸的贫瘠之地恢复为郁郁葱葱的森林。然而，他的沉睡却被一场黑暗的梦魇所侵袭，扭曲了地底的哀嚎洞穴，并将他的追随者变成了剧毒的魔物。",kw={"塞纳里奥议会","变异","纳拉雷克斯的门徒","尖牙德鲁伊","翡翠梦境","翡翠梦魇","纳拉雷克斯","贫瘠之地","哀嚎洞穴"},ang={["class:Druid"]="纳拉雷克斯的事迹对德鲁伊们来说是一个严峻的警示：盲目干预原始的自然状态，或在没有足够谨慎的情况下过度深入翡翠梦境，可能会导致自然界的灾难性扭曲。",["faction:Horde"]="一位暗夜精灵失败的神秘学实验污染了贫瘠之地的核心，迫使来自十字路口的部落军队不得不应对从洞穴中涌出的狂暴野兽。",["race:NightElf"]="虽然纳拉雷克斯曾试图治愈卡利姆多，但他深入部落领地的肆意妄为不仅给塞纳里奥议会带来了耻辱，还孕育出了奸诈的尖牙德鲁伊。",["race:Tauren"]="贫瘠之地地底被扭曲的水流，对维持莫高雷各部落和草原生计的绿洲池塘及野生动物构成了直接威胁。"},sec={{t="绿色的愿景",b="在大分裂发生很久之前，被烈日炙烤的贫瘠之地平原曾是一片生机勃勃的森林。纳拉雷克斯将这种生态的丧失视为一场悲剧，于是带领一群忠诚的门徒来到贫瘠之地，试图扭转干旱。在热带草原的深处，他发现了一个复杂的地底泉水和喷涌的间歇泉网络，并以岩石中呜咽的风声和蒸汽为名，将其称为哀嚎洞穴。他坚信，只要进入深层冥想，并将翡翠梦境的原始能量引导至这些地底水域，那充满生命力的水流便能到达地表，使整片荒原重新焕发生机。"},{t="醒着的梦魇",b="纳拉雷克斯在洞穴深处进入了深层冥想，但当他的意识接触到翡翠梦境领域的那一刻，他崇高的计划便宣告破灭。他没有找到自然界平静的源泉，反而被一种恶毒的、不断侵蚀的腐化——翡翠梦魇——困住了心神。这种溃烂的腐化攫住了这位沉睡德鲁伊的身体，将他变成了一个开放的管道，黑暗能量通过他不断涌入现实世界。纯净的泉水变得污浊，长出了变异的真菌花朵，并将洞穴内的原生野兽扭曲成了饥饿的变异恐怖生物。"},{t="堕落的门徒",b="梦魇并没有就此止步。纳拉雷克斯自己的门徒在导师冥想中泄露出的心灵反噬影响下彻底疯狂，背离了塞纳里奥议会的传统。他们抛弃了对平衡的敬畏，化身为蛇形，自称为尖牙德鲁伊。他们坚信这种扭曲的生长必须在整个卡利姆多蔓延，于是现在守卫着纳拉雷克斯沉睡的躯体，确保他永远无法醒来，只剩下少数忠诚的门徒在寻找勇士，试图打破这一梦魇。"}},faq={{q="纳拉雷克斯是谁？",a="纳拉雷克斯是塞纳里奥议会的一位暗夜精灵德鲁伊。他曾带领一支探险队进入哀嚎洞穴，目标是利用翡翠梦境的力量，将干旱的贫瘠之地恢复为大分裂前郁郁葱葱的森林。",al={"纳拉雷克斯背景故事","沉睡的精灵是谁","哀嚎洞穴的沉睡者"}},{q="为什么纳拉雷克斯在哀嚎洞穴内沉睡？",a="他进入了冥想状态，试图将翡翠梦境的能量直接引导至贫瘠之地底下的蓄水层。然而，一场势不可挡的梦魇攫住了他的心神，使他陷入了无法靠自身醒来的狂热沉睡中。",al={"纳拉雷克斯为何沉睡","纳拉雷克斯在做什么","纳拉雷克斯的冥想"}},{q="是什么创造了尖牙德鲁伊？",a="他们原本是纳拉雷克斯忠诚的门徒。当翡翠梦魇腐化了纳拉雷克斯与梦境的联系时，外泄的恶意使他的追随者陷入了疯狂。他们背弃了塞纳里奥议会，拥抱了毒蛇图腾，现在守护着他的沉睡，以使腐化继续蔓延。",al={"尖牙德鲁伊的起源","尖牙德鲁伊是谁","纳拉雷克斯的门徒"}},{q="是什么导致了哀嚎洞穴的变异？",a="纳拉雷克斯沉睡的躯体成了翡翠梦魇的一个开放通道。污秽的梦境能量直接渗入地底河流系统，将洞穴中的植物、鳄鱼、迅猛龙和毒蛇扭曲成了极具攻击性的变异生物。",al={"哀嚎洞穴为何腐化","变异野兽的起源","哀嚎洞穴的真菌"}},{q="纳拉雷克斯能被唤醒吗？",a="能，但在外界的帮助下。纳拉雷克斯的一名忠诚门徒正在寻求冒险者的帮助，让他们进入洞穴深处，击杀扭曲的尖牙德鲁伊，并举行仪式以打破梦魇对纳拉雷克斯心神的控制。",al={"如何拯救纳拉雷克斯","唤醒纳拉雷克斯","纳拉雷克斯任务"}},{q="为什么纳拉雷克斯想要改变贫瘠之地？",a="纳拉雷克斯了解到，在大分裂将卡利姆多撕裂之前，贫瘠之地曾是一片繁茂的森林。他将这里当前的干旱状况视为一道生态伤口，并希望恢复其古老的葱郁树冠。",al={"为什么要重建贫瘠之地的植被","纳拉雷克斯在贫瘠之地的目标","为什么要选择贫瘠之地"}}},fx={ec55d9d1={q="纳拉雷克斯支持哪一方？",a="纳拉雷克斯属于塞纳里奥议会，因此对联盟和部落都保持中立。他效忠于自然的平衡，而非卡利姆多的政治纷争。遗憾的是，他被困的心灵已彻底失控，沉睡的躯体由扭曲的昔日侍僧守护，他们会攻击任何闯入者。",al={"纳拉雷克斯属于联盟还是部落","纳拉雷克斯的阵营","纳拉雷克斯为谁效力"}},["4a5a8c9e"]={q="纳拉雷克斯与谁有关？",a="纳拉雷克斯是一名德高望重的塞纳里奥议会暗夜精灵德鲁伊，曾带领一队忠诚的门徒来到贫瘠之地。他的大多数追随者都屈服于笼罩其心灵的黑暗噩梦，变成了凶猛的尖牙德鲁伊。仍有少数人忠于他，例如守在入口上方洞穴中的纳尔帕克和厄布鲁，以及在洞穴内部等候的纳拉雷克斯的门徒。",al={"纳拉雷克斯的盟友","纳拉雷克斯的门徒","纳拉雷克斯的追随者有哪些"}}},fp="7,277,17.656.0,20.602.0,16.544.1,15.231.0,49.256.0,36.285.0,42.245.0,24.215.1,43.216.0"}
P.entries["npc:nat-pagle"] = {n="纳特·帕格",s="纳特·帕格被公认为艾泽拉斯最著名的钓鱼大师，尽管他声称自己钓鱼只是为了找个借口畅饮一番。他在尘泥沼泽的一个隐秘小湾安了家，并在那里指导那些证明了自己的耐心的联盟与部落精英垂钓者。",h="纳特·帕格被公认为艾泽拉斯最著名的钓鱼大师，尽管他声称自己钓鱼只是为了找个借口畅饮一番。他在尘泥沼泽的一个隐秘小湾安了家，并在那里指导那些证明了自己的耐心的联盟与部落精英垂钓者。",kw={"工匠钓鱼","尘泥沼泽","加兹兰卡","格瑞姆努尔·石顶","鲁玛克","纳特·帕格","帕格","帕格的荒野"},ang={["faction:Alliance"]="像铁炉堡的格瑞姆努尔·石顶这样的矮人钓鱼大师对纳特推崇备至，他们会将资深的联盟渔夫送到尘泥沼泽，以学习钓鱼这门手艺的最终秘诀。",["faction:Horde"]="鲁玛克，奥格瑞玛荣誉谷的钓鱼训练师，将纳特·帕格视为挚友，并将有前途的部落渔夫送往南方接受他的指导。"},sec={{t="钓鱼大师",b="尽管他的名字在已知世界中就是钓鱼大师的代名词，但纳特·帕格对自己的手艺却表现得十分随意。他垂钓了几十年，却常常承认自己对这项运动本身并没有多少崇敬，甚至有一句名言：钓鱼只不过是让他能坐下来畅饮一番的绝佳借口。尽管态度粗鲁而漫不经心，但纳特对水生生物和钓鱼艺术的了解比任何在世之人都深，甚至还会向专业人士授权提供他所推崇的渔具。"},{t="沼泽隐士",b="帕格在尘泥沼泽东海岸的一小块陆地上扎营，远离了东部王国那些喧闹的酒馆。他保持着强烈的独立性，对派系政治毫无兴趣，无论是从铁炉堡的格瑞姆努尔·石顶那儿送来的联盟旅人，还是经由奥格瑞玛的鲁玛克指引而来的部落求学者，他都一视同仁。对纳特而言，任何愿意为了稀有品种而踏遍世界角落的人，都有资格上一堂真正的钓鱼课。"},{t="古老的传说与海怪",b="帕格曾经涉足险境，包括一次前往祖尔格拉布遗迹的探险，在那里，他把他最喜欢的卷尺和渔具盒丢在了多头蛇怪物加兹兰卡出没的水域附近。"}},faq={{q="纳特·帕格是谁？",a="纳特·帕格是艾泽拉斯最著名的渔夫。在垂钓了几十年后，他现在在尘泥沼泽的海岸边过着宁静的生活，指导那些水平已经超越了普通训练师的资深垂钓者。",al={"谁是纳特","纳特·帕格背景故事","谁是那个钓鱼的人"}},{q="在哪里可以找到纳特·帕格？",a="他住在卡利姆多的尘泥沼泽东海岸的一小块陆地上，位于塞拉摩岛的西南方。",al={"纳特·帕格在哪里","纳特·帕格位置","寻找纳特·帕格"}},{q="如果纳特·帕格说他不喜欢钓鱼，为什么还要钓鱼呢？",a="帕格坦诚地承认，他把钓鱼主要视为一个体面且不受干扰的借口，可以坐在水边一连几个小时地畅饮。",al={"纳特喜欢钓鱼吗","纳特为什么钓鱼","纳特·帕格喝酒"}},{q="纳特·帕格会训练部落成员吗？",a="会的。纳特对派系纷争完全持中立态度。当部落垂钓者的技能达到普通训练师的上限时，他们会被他的朋友，奥格瑞玛的鲁玛克直接引荐给他。",al={"纳特只给联盟提供服务吗","部落纳特·帕格","部落能和纳特对话吗"}},{q="纳特·帕格与祖尔格拉布有什么联系？",a="纳特曾经在古老的巨魔城市祖尔格拉布钓过鱼，并将他的渔具盒和珍贵的卷尺留在了栖息着巨型多头蛇加兹兰卡的水域附近。",al={"祖尔格拉布里的纳特","纳特·帕格的渔具盒","纳特·帕格祖尔格拉布"}}},fp="9,298,17.480.0,18.473.0,26.212.0,17.202.0,29.115.0,50.156.0,42.172.0,49.169.0"}
P.entries["npc:natalia-mar-alith"] = {n="Natalia Mar'alith",s="娜塔莉亚·玛尔利斯（Natalia Mar'alith）是一位暗夜精灵牧师，也是塞纳里奥议会的研究员。她在雷戈虫巢深处的其拉虫群巢穴中失踪了。在前往虫巢进行探险之前，她曾随她的丈夫指挥官玛尔利斯一同踏入希利苏斯的荒野。",h="娜塔莉亚·玛尔利斯（Natalia Mar'alith）是一位暗夜精灵牧师，也是塞纳里奥议会的研究员。她在雷戈虫巢深处的其拉虫群巢穴中失踪了。在前往虫巢进行探险之前，她曾随她的丈夫指挥官玛尔利斯一同踏入希利苏斯的荒野。",kw={"brann bronzebeard","塞纳里奥要塞","雷戈虫巢","深入疯狂之口","玛尔利斯","娜塔莉亚","希利苏斯"},ang={["faction:Alliance"]="在铜须营地的鲁特加尔·雕石和弗兰卡尔·石桥与重走布莱恩探险之路的联盟探险者分享了她堕落的残酷细节。",["race:NightElf"]="娜塔莉亚悲剧性的堕落是对卡多雷的一个沉痛提醒，即便是他们最虔诚的牧师，也极易受到埋藏在希利苏斯沙土之下的古老恐怖的影响。"},sec={{t="悲剧的堕落",b="当塞纳里奥议会在塞纳里奥要塞建立前哨站以监视苏醒的沙土时，娜塔莉亚随她的丈夫指挥官玛尔利斯一起进入了这片荒野。为了揭开希利德虫群和古代其拉废墟复苏背后的谜团，她加入了一支由著名的探险家布莱恩·铜须（Brann Bronzebeard）率领的探险队，同行的还有矮人研究员鲁特加尔·雕石（Rutgar Glyphshaper）和弗兰卡尔·石桥（Frankal Stonebridge）。"},{t="雷戈虫巢的水晶",b="探险队追踪着奇异的能量波动进入了雷戈虫巢的南端。在虫巢深处，他们发现了一块刻有古老其拉铭文的巨大水晶。受到水晶低语共鸣的吸引，娜塔莉亚凑近去仔细研究那些标记。其中的黑暗魔法瞬间压垮了她的心智，击碎了她的理智，并将她的意志束缚给了克苏恩。她的矮人同伴将她带回了塞纳里奥要塞，德鲁伊们唤醒了她，但几周后她却像着了魔一样冲回了他们的营地，要求回到虫巢，最终只能被迫与她战斗。她现在已成了那位虫巢恐怖主宰的狂热守卫。"},{t="指挥官的痛苦",b="在塞纳里奥要塞，指挥官玛尔利斯绝望地抱持着一种希望，认为他的妻子还有救，拒绝接受她心智已彻底破碎的事实。然而，任何敢于闯入雷戈虫巢的人会发现，那里并没有一个等待营救的俘虏，而是一个被上古之神的恶意所扭曲、挥舞着神圣牧师魔法的疯狂仆从。"}},faq={{q="谁是娜塔莉亚·玛尔利斯？",a="娜塔莉亚·玛尔利斯是一位塞纳里奥议会的暗夜精灵牧师，也是指挥官玛尔利斯的妻子。她加入了布莱恩·铜须前往雷戈虫巢的侦察探险队，以研究希利德虫群的复苏，在那里她成了古老黑暗魔法的受害者。",al={"娜塔莉亚·玛尔利斯","娜塔莉亚是谁","指挥官玛尔利斯的妻子"}},{q="我能在哪里找到娜塔莉亚·玛尔利斯？",a="她位于希利苏斯南部雷戈虫巢的虫道深处，矗立在一块散发着光芒、刻满铭文的水晶前守望。",al={"娜塔莉亚的位置","娜塔莉亚在哪里","雷戈虫巢的牧师"}},{q="为什么娜塔莉亚会对冒险者产生敌意？",a="在检查一块其拉水晶时，娜塔莉亚被上古之神克苏恩的低语彻底腐化，心智也随之崩溃。她现在狂热地保护着水晶，抵御任何进入虫巢的人。",al={"为什么娜塔莉亚攻击我","为什么娜塔莉亚疯了","娜塔莉亚被洗脑"}},{q="娜塔莉亚失踪时和谁在一起？",a="她与布莱恩·铜须、鲁特加尔·雕石和弗兰卡尔·石桥一同进入了雷戈虫巢。鲁特加尔和弗兰卡尔在这次磨难中幸存下来，并撤退到了希利苏斯南部的铜须营地，讲述了那段经历。",al={"娜塔莉亚探险队","谁和娜塔莉亚在一起","布莱恩和娜塔莉亚"}},{q="为什么她在战斗中如此危险？",a="娜塔莉亚保留了她强大的牧师能力，能不断地用精神尖啸驱散攻击者，并通过消耗极小的强效治疗术恢复自身力量，这使得如果不持续进行打断，她将非常难以被击败。",al={"娜塔莉亚战斗","如何击败娜塔莉亚","娜塔莉亚治疗"}}},fp="17,280,16.427.0,25.634.1,23.333.1,25.255.1,35.139.0,38.198.1,43.219.0,34.232.0"}
P.entries["npc:nathanos-blightcaller"] = {n="纳萨诺斯·凋零者",s="纳萨诺斯·凋零者，曾名纳萨诺斯·玛瑞斯，如今作为Sylvanas Windrunner女王的致命拥护者，驻守在东瘟疫之地的废墟家园中。生前，他是奎尔萨拉斯首位且唯一的人类游侠领主；死后，他一边训练被遗忘者猎人，一边守卫着东部边境，对所有靠近者都怀有刻骨的蔑视。",h="纳萨诺斯·凋零者，曾名纳萨诺斯·玛瑞斯，如今作为Sylvanas...",kw={"凋零者","远行者","猎人训练师","玛瑞斯","玛瑞斯农场","纳萨诺斯","瘟疫之地","sylvanas windrunner"},ang={["class:Hunter"]="纳萨诺斯是被遗忘者中职位最高的猎人训练师，他将奎尔萨拉斯严苛而传奇的远行者射箭技巧传授给了洛丹伦的亡灵。",["faction:Alliance"]="看到一位洛丹伦的功勋英雄和著名的远行者在被遗忘者的旗帜下作战，这对暴风城来说不仅是极大的侮辱，更是致命的战术难题。",["faction:Horde"]="纳萨诺斯为部落在瘟疫之地的行动提供关键的战术指导和猎人训练，尽管他对访客的态度尖酸刻薄。",["race:Undead"]="作为黑暗女王的拥护者，纳萨诺斯体现了被遗忘者那种苦涩的韧性，尽管他对同僚的无能几乎没有耐心。"},sec={{t="唯一的人类远行者",b="在第三次战争前，纳萨诺斯·玛瑞斯是一位来自洛丹伦乡村地区、极具天赋的神射手和战术天才。在奎尔萨拉斯高等精灵的训练下，他与Sylvanas Windrunner关系密切，并成为了唯一一位获得游侠领主这一崇高头衔的人类。他的家一直是他位于洛丹伦的家族庄园——玛瑞斯农场。"},{t="陨落与重生",b="当阿尔萨斯王子和天灾军团在斯坦索姆大清洗后横扫洛丹伦时，瘟疫吞噬了这个王国。纳萨诺斯在庄园进行了绝望的抵抗，但最终死于恐怖的憎恶——吞咽者拉姆斯登之手。作为一名毫无心智的亡灵奴仆被复活后，他在被瘟疫侵蚀的土地上徘徊，以巫妖王之名进行杀戮。在Sylvanas Windrunner打破了天灾军团的精神控制并在幽暗城建立了被遗忘者后，她找到了他（正如他冥冥中所预感的那样），将他的意识从巫妖王的意志中解放出来，使他重新以战术天才和赤诚忠心侍奉于她身侧。"},{t="女妖之王的拥护者",b="纳萨诺斯采用“凋零者”这一称号，并在破败的玛瑞斯农场定居下来。他担任Sylvanas Windrunner的拥护者、猎人训练师以及在充满争端的东瘟疫之地的区域情报主管，并有邪恶的瘟疫犬护卫。联盟情报机构对他依然存活一事感到极为震惊；伯瓦尔·弗塔根公爵认为，像纳萨诺斯这样水准的战术大师领导亡灵军队是对人类生存的极大威胁，因此派遣突击部队试图刺杀这位堕落的游侠领主。"}},faq={{q="纳萨诺斯·凋零者是谁？",a="纳萨诺斯·凋零者曾是纳萨诺斯·玛瑞斯，一位著名的人类神射手，也是唯一被奎尔萨拉斯授予游侠领主称号的非精灵族成员。在第三次战争中死亡并复活后，Sylvanas Windrunner将他的思想从天灾军团的控制中解放了出来。他现在于东瘟疫之地的祖宅中担任她的拥护者和猎人训练师。",al={"纳萨诺斯是谁","纳萨诺斯背景故事","玛瑞斯农场的人是谁"}},{q="为什么纳萨诺斯会在玛瑞斯农场？",a="玛瑞斯农场是纳萨诺斯生前的家，也是他在保卫洛丹伦时牺牲的地方。成为亡灵后，他选择回到这片废墟，将其改造成一个前哨站，用于训练被遗忘者猎人并监视联盟和天灾军团的动向。",al={"纳萨诺斯在哪里","为什么纳萨诺斯在瘟疫之地","玛瑞斯农场 纳萨诺斯"}},{q="纳萨诺斯是如何变成亡灵的？",a="纳萨诺斯在第三次战争期间于家中被天灾军团的憎恶吞咽者拉姆斯登杀死。他作为巫妖王忠诚而毫无心智的奴仆复活，直到Sylvanas Windrunner找到他并解放了他的思想，让他得以加入被遗忘者。",al={"纳萨诺斯怎么死的","谁杀了纳萨诺斯","纳萨诺斯之死"}},{q="为什么联盟想要杀他？",a="暴风城的联盟高层发现，纳萨诺斯·玛瑞斯——联盟最伟大的军事头脑和战术天才之一——并没有彻底消亡，而是加入了被遗忘者。由于认为他的战术造诣是巨大的危险，伯瓦尔·弗塔根公爵下令将其铲除。",al={"为什么要杀纳萨诺斯","联盟任务 纳萨诺斯","必须恢复秩序"}},{q="他与Sylvanas Windrunner的关系如何？",a="纳萨诺斯生前与Sylvanas Windrunner关系密切，那时奎尔萨拉斯的精灵们将他奉为唯一的人类游侠领主，而现在他是她的拥护者。成为亡灵后，他对女妖之王的忠诚依然绝对且坚定不移。",al={"sylvanas windrunner与纳萨诺斯","sylvanas windrunner爱纳萨诺斯吗","纳萨诺斯 sylvanas windrunner 罗曼史"}},{q="站在他身边的猎犬是什么？",a="它们是纳萨诺斯亲自训练的凶残瘟疫犬。它们被留在身边守卫玛瑞斯农场的废墟，会攻击任何愚蠢到闯入他领地的入侵者。",al={"纳萨诺斯的狗","玛瑞斯农场的猎犬","凋零者的宠物"}}},fp="21,344,25.354.0,20.606.0,29.515.1,29.329.0,36.251.0,34.244.0,39.301.0,39.214.0,37.188.0"}
P.entries["npc:nida"] = {n="希拉里",s="希拉里是一个居住在赤脊山湖畔镇的年轻人类女孩。在将父亲送给她的珍贵礼物掉进湖里后，她心烦意乱，终日坐在镇上的码头边哭泣。",h="希拉里是一个居住在赤脊山湖畔镇的年轻人类女孩。在将父亲送给她的珍贵礼物掉进湖里后，她心烦意乱，终日坐在镇上的码头边哭泣。",kw={"孩童","希拉里","止水湖","湖畔镇","项链","赤脊山","肖恩"},ang={["faction:Alliance"]="即使在赤脊山正遭受重大区域危机的时刻，帮助希拉里也为湖畔镇忧心忡忡的居民们找回了一丝温暖与纯真。"},sec={{t="孩子丢失的纪念品",b="在豺狼人入侵和黑石兽人战帮不断逼近湖畔镇的威胁下，镇上的孩子们依然面临着日常的烦恼。希拉里不慎将父亲送给她的项链掉进了止水湖浑浊的湖水中。因为害怕父亲生气，这个伤心的女孩泪流满面地守在码头边，希望有勇敢的人能潜入湖中帮她找回项链。"}},faq={{q="希拉里是谁？",a="希拉里是一个居住在赤脊山湖畔镇的年轻人类孩童，经常能看到她在码头附近哭泣徘徊。",al={"希拉里是谁","希拉里 湖畔镇","哭泣的女孩 湖畔镇"}},{q="希拉里为什么在哭？",a="希拉里弄丢了父亲买给她的珍贵项链。项链滑落到了止水湖中，她非常担心父亲发现后会责备她。",al={"她为什么哭","希拉里为什么难过","希拉里哭声"}},{q="谁在帮她寻找项链？",a="她的玩伴肖恩注意到了她的痛苦，并请求过往的冒险者潜入止水湖中，帮她捞回沉入水底的项链。",al={"谁帮助希拉里","希拉里的朋友","谁给予希拉里的任务"}},{q="丢失的项链在哪里？",a="项链沉在止水湖的水面之下，就在希拉里掉落它时的码头附近。",al={"希拉里的项链在哪里","止水湖项链位置"}}},fx={["7ae322dc"]={q="希拉里支持哪一方？",a="希拉里是一名年幼的人类女孩，在湖畔镇安然生活，受到联盟的保护。她不参与政治或军旅事务，只是在止水湖畔与当地居民一起度过童年。",al={"尼达的阵营","尼达属于联盟吗","尼达支持哪一方"}},["3c3e0c86"]={q="希拉里为什么在湖畔镇？",a="湖畔镇是希拉里的家。她和家人住在湖边的定居点，平日里与儿时好友肖恩在码头和湖岸边玩耍。",al={"尼达为什么在这里","尼达为什么在湖畔镇","尼达在这里做什么"}}},fp="6,221,23.444.0,14.126.0,21.185.0,44.137.0,35.114.0"}
P.entries["npc:nikova-raskol"] = {n="尼科瓦·拉斯克",s="尼科瓦·拉斯克是一位上了年纪的人类平民，经常在暴风城的Old Town鹅卵石街道上漫步。由于她的孙子惨遭迪菲亚潜行者杀害，她深陷悲痛之中，并寻求对关押在监狱里的暴乱罪犯执行正义。",h="尼科瓦·拉斯克是一位上了年纪的人类平民，经常在暴风城的Old Town鹅卵石街道上漫步。由于她的孙子惨遭迪菲亚潜行者杀害，她深陷悲痛之中，并寻求对关押在监狱里的暴乱罪犯执行正义。",kw={"迪菲亚头巾","麦克","尼科瓦·拉斯克","old town","监狱","暴风城","鲜血的颜色"},ang={["faction:Alliance"]="对于造访暴风城的联盟勇士来说，帮助尼科瓦提醒着人们，保卫王国意味着要保护那些家庭因内乱而破碎的普通平民。"},sec={{t="祖母的哀痛",b="尼科瓦漫步在Old Town，背负着近期遭受的毁灭性个人悲剧。她深爱的孙子麦克被迪菲亚潜行者的强盗所杀害。当王国在政治层面上应对叛乱时，尼科瓦的遭遇体现了迪菲亚潜行者无法无天的暴行给普通公民带来的沉重代价。"},{t="监狱中的复仇",b="尽管许多制造混乱的罪犯已被逮捕并投入监狱，但随着一场激烈的囚犯叛乱占领了监狱设施，监狱的铁栏杆已无法给她带来慰藉。由于守卫无法恢复秩序，尼科瓦感到十分沮丧，她转而向那些即将进入监狱的勇敢冒险者寻求帮助，请求他们收集红色的迪菲亚头巾，以作为她的孙子的杀手最终受到惩罚的证据。"}},faq={{q="尼科瓦·拉斯克是谁？",a="尼科瓦·拉斯克是暴风城的一位年长居民，经常在Old Town的椭圆形道路上漫步。她正在哀悼被迪菲亚暴徒谋杀的孙子麦克。",al={"尼科瓦是谁","尼科瓦·拉斯克的作用","尼科瓦·拉斯克的背景故事"}},{q="她的孙子麦克发生了什么事？",a="麦克年仅十四岁。当军队奔赴前线时，他拿起武器，成为了监狱的一名守卫，负责看守关押在那里的迪菲亚成员。在指责囚犯撕碎羊毛毯制作帮派头巾后，他被囚犯从背后刺杀。",al={"麦克是谁","麦克发生了什么","麦克是怎么死的"}},{q="她为什么想要从监狱里带回红色头巾？",a="红色头巾是迪菲亚潜行者的标志。尼科瓦要求进入叛乱监狱的战士带回这些颈巾，以证明那些夺走无辜生命的罪犯已经受到了应有的惩罚。",al={"鲜血的颜色","为什么是红色头巾","迪菲亚头巾"}},{q="在哪里可以找到尼科瓦·拉斯克？",a="尼科瓦沿着Old Town的主干道不停地走动，距离暴风城的Pig and Whistle Tavern和训练场不远。",al={"尼科瓦在哪里","尼科瓦的位置","尼科瓦·拉斯克的行进路线"}}},fx={dc3813b4={q="尼科瓦·拉斯克支持哪一方？",a="尼科瓦·拉斯克坚定地支持暴风城和联盟。作为一名住在首都中心地带的老妇人，她的仇恨全都指向迪菲亚潜行者，她认为是他们杀害了自己的家人。",al={"尼科瓦属于联盟吗","尼科瓦·拉斯克的阵营","尼科瓦支持哪一方"}},cb2616e5={q="尼科瓦·拉斯克为什么在Old Town？",a="尼科瓦在Old Town的石板街道上徘徊，因为暴风城是她的家。悲痛和对正义的渴望令她在城中踱步，寻找有能力的英雄，好向藏身于街道之下的犯罪阴谋者复仇。",al={"尼科瓦为什么在这里","尼科瓦·拉斯克为什么在暴风城","尼科瓦·拉斯克为什么在old town"}}},fp="13,262,21.350.0,25.419.0,21.155.0,34.250.0,49.246.0,33.154.0"}
P.entries["npc:nissa-firestone"] = {n="尼莎·火石",s="尼莎·火石是一位矮人医师，驻扎在铁炉堡Great Forge上方喧嚣之处。她担任野战急救导师，教导旅行者和士兵如何包扎伤口和处理创伤。",h="尼莎·火石是一位矮人医师，驻扎在铁炉堡Great Forge上方喧嚣之处。她担任野战急救导师，教导旅行者和士兵如何包扎伤口和处理创伤。",kw={"联盟创伤","绷带","急救","great forge","治疗者","ironforge physician","尼莎·火石"},ang={["faction:Alliance"]="任何途经卡兹莫丹的联盟冒险者，若想在不需要神圣或奥术魔法的情况下获得基本的生存技能，都离不开像尼莎这样的训练师。",["race:Dwarf"]="对于那些从与石腭怪或冰霜巨魔的冲突中归来的矮人来说，尼莎代表了铁炉堡医疗传统中务实、干练的作风。"},sec={{t="铁砧之上的治疗者",b="在Great Forge叮当作响的金属声和灼热的气浪中，尼莎·火石在Ironforge Physician商店的楼上从事医疗工作。虽然矮人战士以坚韧着称，但即便是坚硬如石的皮肤也会被刀剑和利爪割裂。尼莎确保那些前往丹莫罗雪原或更远地方的人知道如何通过基本的绷带和战地敷料来让自己和盟友活下去。"},{t="分流与高级创伤",b="对于那些已经掌握了布料和棉纱基础知识的战地医护人员，尼莎会适时地指出学生何时已经超出了她的诊所所能教授的范畴。当从业者达到了她所能传授的极限时，她会指引他们前往偏远哨所寻找专业的伤员分流军官，将技术娴熟的治疗者引导至联盟伤员最多的地方。"}},faq={{q="尼莎·火石是谁？",a="尼莎·火石是一位矮人急救训练师，在位于Great Forge南侧边缘的Ironforge Physician商店工作。",al={"尼莎·火石是谁","尼莎·火石的角色","铁炉堡急救训练师"}},{q="我在哪里可以找到尼莎·火石？",a="她可以在Ironforge Physician商店的楼上找到，该商店坐落在铁炉堡Great Forge环区的南侧边缘。",al={"尼莎·火石的位置","尼莎在哪里","ironforge physician位置"}},{q="尼莎·火石教授什么？",a="她向联盟的冒险者教授急救艺术，传授制作绷带和解毒剂的技巧，以治疗在野外受到的伤害。",al={"尼莎教什么","铁炉堡急救","在铁炉堡学习绷带"}},{q="尼莎能教大师级的伤员分流吗？",a="不能。一旦医护人员达到高级熟练度，尼莎就会通过“联盟创伤”任务指引他们去别处，将他们派往驻扎在活跃战区附近的经验丰富的战地外科医生那里。",al={"联盟创伤任务","铁炉堡急救大师","急救225以上"}}},fx={f16b91f7={q="尼莎·火石支持哪一方？",a="尼莎·火石坚定地支持铁炉堡和联盟。她驻扎在首都高处，运用自己的医术，通过战地包扎和创伤护理，努力让铁炉堡的防卫者和联盟旅人活下来。",al={"尼莎·火石的阵营","尼莎属于联盟吗","尼莎为谁效力"}},bc93403c={q="尼莎·火石为什么在铁炉堡？",a="尼莎在Great Forge上方的铁炉堡医师商店工作。她身处矮人首都的中心，既能照料城中的病患和伤者，也能训练冒险的战地医护人员，让他们在奔赴战场前学会包扎伤口、止住出血。",al={"尼莎为什么在这里","尼莎·火石为什么在这个位置","是什么让尼莎来到铁炉堡"}},["2ef2db38"]={q="尼莎·火石想要什么？",a="作为一名医师和训练师，尼莎的首要目标是确保联盟战士知道如何在战地救治自己。当有前途的医护人员学有所成、超出她的指导能力后，她会指引他们去找能教授战时检伤分类的高级战地外科医师。",al={"尼莎想要什么","尼莎·火石的目标","尼莎·火石的动机"}}},fp="15,214,25.427.0,26.329.0,23.148.0,33.138.0,32.156.0,36.184.0"}
P.entries["npc:nogg"] = {n="诺格",s="诺格是一位地精工程师，在奥格瑞玛的Valley of Honor中拥有一间工作室。他为部落提供修理专长和专门的工艺，尤其擅长分析从诺莫瑞根深处回收的奇异机械残骸。",h="诺格是一位地精工程师，在奥格瑞玛的Valley of Honor中拥有一间工作室。他为部落提供修理专长和专门的工艺，尤其擅长分析从诺莫瑞根深处回收的奇异机械残骸。",kw={"诺莫瑞根","地精工程师","机械商店","诺格","奥格瑞玛","戒指归还"},ang={["faction:Horde"]="对于从东部王国的危险行动中归来的部落勇士来说，诺格弥合了粗糙残骸与精密校准的战斗装备之间的差距。",["profession:Engineering"]="其他工程师经常在Valley of Honor的诺格工作室停留，购买零件，谈论业务，并惊叹地精之手改造复杂的侏儒科技是多么容易。"},sec={{t="诺格的工作室",b="诺格的独立工程工作室坐落在奥格瑞玛的Valley of Honor中，为冒险者和工匠们提供服务。尽管周围的城市主要依赖传统的兽人钢铁和蛮力，但诺格提供了只有地精才能带来的专业机械技巧。他对外国的装置和科技保持着浓厚的兴趣，乐于研究从联盟领土或地下废墟中带回的奇特饰品和机械怪异物件。"},{t="侏儒小玩意和残骸",b="诺格对从没落的侏儒首都诺莫瑞根回收的物品特别感兴趣。当部落特工从海对岸的辐射金库中取回复杂的戒指或技术残余时，诺格是杜隆塔尔为数不多能够拆解、破译并为部落改造这些奇异发条装置的专家之一。"}},faq={{q="我在哪里可以找到诺格？",a="诺格位于奥格瑞玛的Valley of Honor，他在那里经营着自己的工程工作室。",al={"诺格位置","哪里有诺格","诺格的机械商店"}},{q="诺格与诺莫瑞根有什么联系？",a="当部落冒险者冒险进入卡兹莫丹的诺莫瑞根辐射隧道时，他们可以回收复杂的技术饰品。诺格是奥格瑞玛当地的专家，负责检查和重置这些外来的侏儒戒指。",al={"诺格与诺莫瑞根","诺格戒指","戒指归还"}},{q="诺格属于部落吗？",a="诺格是一位在奥格瑞玛内直接运营的独立地精工匠，积极为部落冒险者服务，并为他们的战争努力贡献自己的技术。",al={"诺格属于部落吗","诺格阵营"}},{q="诺格可以改造或重铸戒指吗？",a="可以。如果冒险者带着从诺莫瑞根通过火花机获取的戒指来找他，并希望获得不同的附魔或机械属性，诺格知道如何拆卸和重建该物品，以更好地满足他们的需求。",al={"重做戒指","修改诺莫瑞根戒指"}}},fx={["0ba8fca5"]={q="诺格为什么在奥格瑞玛？",a="诺格在奥格瑞玛的荣誉谷经营生意。这座繁华的首都为他带来源源不断的顾客、原材料，以及愿意承接危险差事的冒险佣兵。他的机械工坊依靠部落对工程学专长的持续需求而兴旺。",al={"诺格为什么在这里","诺格为什么在奥格瑞玛","诺格所在位置的原因"}},["81166680"]={q="诺格是谁？",a="诺格是一名精明能干的地精工程师，在奥格瑞玛荣誉谷经营诺格的机械店。与许多居住在部落首都的地精一样，他为机械爱好者和冒险者提供机械服务，对新奇装置和回收来的科技物品保持敏锐的商业眼光和务实态度。",al={"诺格是谁","诺格的背景","诺格的身份"}},c0d235dc={q="诺格想要什么？",a="诺格想要创新的工程零件、稀奇的机械造物和有利可图的机会。他感兴趣的事包括检查冒险者捡回来的精巧戒指，以及留意诺莫瑞根等地的冲突所引发的科技混乱，例如机械争斗，以此为自己的店铺拓展生意。",al={"诺格想要什么","诺格的目标","诺格任务的目的"}}},fp="4,248,15.481.0,27.354.0,22.100.0,40.235.0,26.163.0,32.217.0"}
P.entries["npc:nori-pridedrift"] = {n="诺里斯·激流",s="诺里斯·激流是一位富有进取心的矮人，他在白雪皑皑的寒脊山谷里兜售热气腾腾的“滚烫晨酿”。他冒着严寒为瑟瑟发抖的山地探险者们提供清晨提神饮品，并经常招募身手敏捷的新手在饮品冷却前负责送货，以此维持生计。",h="诺里斯·激流是一位富有进取心的矮人，他在白雪皑皑的寒脊山谷里兜售热气腾腾的“滚烫晨酿”。他冒着严寒为瑟瑟发抖的山地探险者们提供清晨提神饮品，并经常招募身手敏捷的新手在饮品冷却前负责送货，以此维持生计。",kw={"酿造","寒脊山谷","丹莫罗","矮人","晨酿马克杯","诺里斯·激流","滚烫晨酿"},ang={["profession:Cooking"]="丹莫罗的烹饪冒险家们都很赞赏诺里斯的执着，他即便在冰天雪地里也坚持为顾客奉上热气腾腾的特色饮品。",["race:Dwarf"]="每个矮人都明白在严寒天气里喝上一杯烈饮是多么大的慰藉，因此诺里斯那热气腾腾的晨酿在山地岗哨里总是备受欢迎。"},sec={{t="雪中的热饮",b="寒脊山谷的生活环境艰苦且寒冷刺骨，没什么比来上一杯“滚烫晨酿”更能驱散寒意了。诺里斯·激流通过在冰天雪地中酿造并分发这种类似热咖啡的清晨饮品谋生。由于这种饮品必须趁热饮用才能品出真味，所以配送是一场与天气的赛跑。诺里斯经常招募动作麻利的快递员，在山间的冷空气夺走饮品的热量之前，将新鲜的酿造品送到冻得直哆嗦的哨兵手中。除了饮品本身，他供应的坚固马克杯也同样重要，他要求送货员必须及时归还这些数量有限的杯子。"}},faq={{q="诺里斯·激流是谁？",a="诺里斯·激流是一位驻扎在寒脊山谷、富有进取心的矮人小贩。他酿造并出售“滚烫晨酿”，这是一种类似热咖啡的滚烫饮料，能让当地的守卫和矿工保持温暖。",al={"诺里斯是谁","诺里斯·激流背景故事","滚烫晨酿小贩"}},{q="什么是“滚烫晨酿”？",a="“滚烫晨酿”是诺里斯·激流酿造的一种特色热饮。它类似于滚烫的咖啡或辛辣的晨间麦酒，深受山谷当地人的喜爱，是驱散丹莫罗严寒的不二之选。",al={"滚烫晨酿","诺里斯卖什么饮料","晨酿"}},{q="为什么配送如此紧急？",a="这种饮品之所以受欢迎，全在于它那滚烫的热度。在寒脊山谷零度以下的山风中，杯子里的饮品散热很快，这迫使诺里斯的送货员必须飞奔着赶往那些焦急等待的顾客那里。",al={"为什么要紧急配送","晨酿配送任务","为什么饮料会变冷"}},{q="为什么诺里斯这么在意马克杯的归还？",a="诺里斯在山谷里的饮具供应有限。如果顾客带着他的马克杯四处游荡或者不小心在雪堆里摔碎了它们，他的晨间生意很快就会陷入停滞。",al={"为什么要归还马克杯","诺里斯的马克杯","归还马克杯"}}},fx={ddac60d5={q="诺里斯·激流支持哪一方？",a="诺里坚定地支持铁炉堡的矮人和联盟。他是寒脊山谷一名独立的本地商人，为守卫并居住在山谷中的山地巡逻兵、受训者和居民提供服务。",al={"诺里斯·激流的阵营","诺里为谁工作","诺里斯·激流与联盟"}},["26ccfe8e"]={q="诺里斯·激流想要什么？",a="诺里想在寒脊山谷经营一家盈利的酿酒生意。他最关心的是确保招牌滚烫的晨曦麦酒趁热送到口渴的顾客手中，并让每只空杯都回到他的库存里。",al={"诺里斯·激流的目标","诺里想要什么","诺里的动机"}},["10ad6fd1"]={q="诺里斯·激流为什么在这里？",a="诺里在寒脊山谷四处走动，因为口渴的顾客都在这里。严酷冰冷的山地气候让他滚烫的晨间饮品尤其受当地卫兵和受训者欢迎，也为他带来了稳定的生意。",al={"诺里为什么在寒脊山谷","诺里为什么在这里","诺里斯·激流的位置"}}},fp="15,301,26.649.0,23.186.0,26.211.0,29.207.0,48.181.0"}
P.entries["npc:novice-elreth"] = {n="新兵艾尔雷斯",s="新兵艾尔雷斯是一位驻扎在丧钟镇教堂内的被遗忘者亡灵。当新复生的亡灵觉醒开始他们的第二人生时，她会指引他们去对抗徘徊在附近墓地中毫无理智的天灾军团，并处理瘟疫留下的悲剧残局。",h="新兵艾尔雷斯是一位驻扎在丧钟镇教堂内的被遗忘者亡灵。当新复生的亡灵觉醒开始他们的第二人生时，她会指引他们去对抗徘徊在附近墓地中毫无理智的天灾军团，并处理瘟疫留下的悲剧残局。",kw={"教堂","教会","丧钟镇","被遗忘者","玛拉的遗愿","新兵艾尔雷斯","受诅者","提瑞斯法林地"},ang={["class:Priest"]="站在洛丹伦曾经的神圣土地上，艾尔雷斯体现了从圣洁崇拜到残酷亡灵必然性之间那冷酷而务实的转变。",["race:Undead"]="对于那些刚从坟墓中爬出来的新鲜被遗忘者，新兵艾尔雷斯提供了迈向生存的第一步实际行动，将冷酷的仇恨聚焦于盲目的天灾军团之上。"},sec={{t="受诅者教堂的向导",b="在丧钟镇那座饱受亵渎的教堂里，新兵艾尔雷斯帮助那些刚刚苏醒、还在为自己恐怖的觉醒而挣扎的亡灵。被遗忘者们不能沉溺于绝望或天灾军团那盲目的饥饿感中，必须迅速组织起来保卫他们的领地。艾尔雷斯为新获自由的灵魂提供早期的任务，指引他们去收集南边狼群和蝙蝠的爪子与翅膀，并处理洛丹伦悲剧沦陷后的遗留问题，包括她的朋友玛拉·菲普斯的悲伤，玛拉被她自己的丈夫塞缪尔杀害，而塞缪尔已经加入了毫无理智的天灾军团。"}},faq={{q="新兵艾尔雷斯在哪里？",a="新兵艾尔雷斯站在丧钟镇的教堂内，那是提瑞斯法林地里一个荒废的村庄，也是新造的被遗忘者苏醒的地方。",al={"艾尔雷斯位置","艾尔雷斯在哪里","新兵艾尔雷斯教堂"}},{q="新兵艾尔雷斯在丧钟镇扮演什么角色？",a="她担任新复生的被遗忘者的当地向导和任务主管。她发布重要的早期指令，教导这些新鲜的亡灵打击在村庄墓地游荡的盲目天灾军团。",al={"艾尔雷斯做什么","艾尔雷斯角色","新兵艾尔雷斯目的"}},{q="新兵艾尔雷斯提供哪些任务？",a="她指派诸如“受诅者”之类的任务，向冒险者索要拾荒者的爪子和夜幕蝙蝠的翅膀；以及“玛拉的遗愿”，要求他们击败盲目的塞缪尔·菲普斯，并将他的遗骸埋葬在他妻子玛拉的坟墓旁。",al={"新兵艾尔雷斯任务","艾尔雷斯任务指引"}},{q="她为什么被称为“新兵”？",a="考虑到她在教堂的位置和她的头衔，艾尔雷斯是被遗忘者宗教或公民阶层中的入门者，在被遗忘者教团的阴影下，学习管理提瑞斯法新复生亡灵的黑暗实务。",al={"为什么叫新兵","新兵称号含义","艾尔雷斯是牧师吗"}}},fx={["04e44638"]={q="新兵艾尔雷斯是谁？",a="新兵艾尔雷斯是一名亡灵侍从，驻守在丧钟镇那座遭亵渎的教堂内。作为协助新近苏醒的被遗忘者的早期看护者之一，她帮助新复生的灵魂面对残酷的亡灵现实，并将他们纳入黑暗女王麾下效力。",al={"新兵艾尔雷斯是谁","新兵艾尔雷斯的背景","关于新兵艾尔雷斯"}},["36f54bd8"]={q="新兵艾尔雷斯支持哪一方？",a="她完全效忠于被遗忘者和希尔瓦娜斯·风行者女王。她在丧钟镇工作，直接支持幽暗城巩固提瑞斯法林地的行动，负责评估并指引新复生者。",al={"新兵艾尔雷斯的阵营","新兵艾尔雷斯效忠于谁","新兵艾尔雷斯的忠诚对象"}},d753a6ea={q="新兵艾尔雷斯想要什么？",a="艾尔雷斯希望确保新获自由的亡灵了解自己的处境，直面坟墓中的真相，并在被遗忘者中找到自己的目标。她考验新复生者的决心，并指引有能力的人去见当地领袖，协助战争。",al={"艾尔雷斯想要什么","新兵艾尔雷斯的目标","艾尔雷斯为什么发布任务"}},a4872bf3={q="新兵艾尔雷斯为什么在丧钟镇？",a="被遗忘者在丧钟镇发掘并复活新的尸体，让他们加入自己的队伍。艾尔雷斯留在礼拜堂照料这些刚刚苏醒、茫然无措的灵魂，确保他们不会陷入绝望，也不会背叛新的同胞。",al={"艾尔雷斯为什么在丧钟镇","新兵艾尔雷斯为什么在教堂里"}}},fp="13,270,35.594.0,31.128.0,43.193.0,37.220.0,27.234.0"}
P.entries["npc:oben-rageclaw"] = {n="奥本·怒爪",s="奥本·怒爪是一个暗夜精灵德鲁伊不安的灵魂，徘徊在泰达希尔班奈希尔兽穴腐化深处。当他的灵魂被困在兽穴中游荡时，他沉睡的肉身已经落入了邪恶熊怪魔法的控制之下。",h="奥本·怒爪是一个暗夜精灵德鲁伊不安的灵魂，徘徊在泰达希尔班奈希尔兽穴腐化深处。当他的灵魂被困在兽穴中游荡时，他沉睡的肉身已经落入了邪恶熊怪魔法的控制之下。",kw={"班奈希尔兽穴","利爪德鲁伊","翡翠梦境","棘皮熊怪","奥本·怒爪","泰达希尔","沉睡的德鲁伊"},ang={["class:Druid"]="奥本的命运是一个令人痛苦的提醒，当神圣的兽穴失去防卫时，德鲁伊在与翡翠梦境进行入定沟通时的脆弱性。",["race:NightElf"]="棘皮熊怪对奥本·怒爪的亵渎展示了腐化对泰达希尔当地居民和神圣避难所的侵蚀有多深。"},sec={{t="亵渎沉睡",b="像许多利爪德鲁伊一样，奥本·怒爪退隐到班奈希尔兽穴的地下圣所中，以与自然沟通并漫游翡翠梦境。然而，当当地的棘皮熊怪堕落并占领了兽穴时，奥本在入定中完全没有防备。堕落的棘皮萨满并没有直接杀害他，而是利用黑暗仪式控制了他处于昏迷状态的凡人躯体，致使他离体的灵魂作为痛苦的鬼魂徘徊，无法超生，也无法苏醒。"},{t="斩断宿体",b="由于无法从萨满的控制下夺回自己的肉身，奥本只能寄希望于穿过危险隧道的旅人来结束他的折磨。只有找到并摧毁他被操纵的物理躯体，才能切断他与凡世的羁绊。一旦他被劫持的躯壳被消灭，奥本痛苦的鬼魂终于能从地下的阴霾中解脱出来，在翡翠梦境中获得永恒的安息。"}},faq={{q="谁是奥本·怒爪？",a="奥本·怒爪是一名暗夜精灵利爪德鲁伊。在被堕落的熊怪将其灵魂从肉身中强行剥离后，他的鬼魂一直徘徊在泰达希尔的班奈希尔兽穴中。",al={"奥本是谁","奥本·怒爪背景故事","兽穴里的灵魂"}},{q="为什么奥本·怒爪会变成鬼魂？",a="当奥本在深沉的德鲁伊入定中与翡翠梦境沟通时，棘皮熊怪萨满潜入了兽穴，并对他的身体施加了邪恶的魔法，控制了他的躯体，并将他的灵魂困在外面，使其成为一个幽灵。",al={"为什么奥本死了","奥本是怎么死的","为什么奥本是鬼魂"}},{q="奥本的物理躯体在哪里？",a="他的物理躯体躺在班奈希尔兽穴蜿蜒的走廊深处，受到腐化了兽穴的棘皮萨满的守卫和操控。",al={"找到奥本的身体","奥本的身体在哪里","沉睡的德鲁伊位置"}},{q="当奥本的躯体被摧毁后会发生什么？",a="摧毁他被傀儡般的躯体打破了棘皮萨满对他的黑暗控制，使他的灵魂得以安详地离开泰达希尔，永远在翡翠梦境中安息。",al={"奥本的命运","奥本的灵魂会怎样","拯救奥本"}}},fx={["9c749c17"]={q="奥本·怒爪支持哪一方？",a="奥本·怒爪与暗夜精灵和塞纳里奥议会站在一边。虽然一名堕落的瘤背萨满目前正在兽穴深处操控他沉睡的肉身，但奥本真正的灵魂依然忠于自己的族人，并向路过的冒险者求助，希望终结自己的苦难。",al={"奥本·怒爪友好吗","奥本·怒爪的阵营","奥本效忠于谁"}},["98315864"]={q="奥本·怒爪想要什么？",a="奥本渴望摆脱将他的灵魂束缚在班奈希尔兽穴的邪异力量。由于邪恶的瘤背魔法控制了他的肉身，他请求你摧毁他被腐化的躯体，让他不安的灵魂终于能在翡翠梦境中安息。",al={"奥本想要什么","奥本·怒爪的目标","奥本·怒爪的动机"}}},fp="13,260,20.516.0,19.384.1,21.166.0,29.225.0,30.155.0,44.169.1"}
P.entries["npc:oggleflint"] = {n="奥格弗林特",s="奥格弗林特是居住在奥格瑞玛正下方怒焰裂谷火山深处的穴居人部落酋长。他的穴居人正从布满熔岩的隧道向地表爬行，他盘踞在洞穴入口附近，指挥着一群野蛮的穴居人，对上方的部落主城构成了直接威胁。",h="奥格弗林特是居住在奥格瑞玛正下方怒焰裂谷火山深处的穴居人部落酋长。他的穴居人正从布满熔岩的隧道向地表爬行，他盘踞在洞穴入口附近，指挥着一群野蛮的穴居人，对上方的部落主城构成了直接威胁。",kw={"奥格弗林特","奥格瑞玛","怒焰裂谷","灼热之刃","穴居人"},ang={["class:Warrior"]="面对奥格弗林特意味着要对抗一个完全依靠纯粹肌肉力量和原始狂暴，而不是盔甲或纪律的强力蛮汉。",["faction:Horde"]="奥格弗林特的穴居人生活在萨尔的堡垒正下方，代表着杜隆塔尔心脏地带一个狂野且不可预知的安全风险。",["race:Orc"]="对于正在通过武装试炼证明自己实力的年轻兽人来说，击杀潜伏在精神谷下方的这位酋长是考验其战斗纪律的早期试炼。"},sec={{t="深渊酋长",b="奥格弗林特和他的穴居人从奥格瑞玛深处炽热的隧道爬出，进入了怒焰裂谷。他们残暴且极具领地意识，在熔岩岩石中开辟了一片原始领地。尽管穴居人几乎没有什么先进文明可言，但奥格弗林特凭借纯粹的蛮力对族群保持着绝对的统治。"},{t="使者之死",b="当恐怖图腾氏族长玛加萨·野性图腾派遣外交官进入裂谷试图与穴居人讲和时，穴居人反戈一击杀死了他们。其中一名使者玛尔·恐怖图腾的尸体就躺在奥格弗林特监视下的洞穴中。这位穴居人酋长现在守在洞穴入口附近，袭击任何进入黑暗深处的闯入者。"},{t="奥格瑞玛下方的威胁",b="在萨尔的主城正下方有穴居人存在，这是部落无法容忍的隐患。奥格弗林特的部落正不断向地表逼近，由于其极度不稳定，如果放任不管，它们随时可能涌入精神谷和暗影裂口。"}},faq={{q="奥格弗林特是谁？",a="奥格弗林特是一位强大的穴居人酋长，统领着居住在奥格瑞玛城下怒焰裂谷中的穴居人族群。",al={"奥格弗林特","奥格弗林特是谁","怒焰裂谷穴居人首领"}},{q="在哪里可以找到奥格弗林特？",a="他位于怒焰裂谷的上层洞穴中，距离入口隧道不远，他的族群占据了最靠近地表的隧道。",al={"奥格弗林特在哪里","奥格弗林特位置","寻找奥格弗林特"}},{q="为什么穴居人会出现在怒焰裂谷？",a="穴居人天生居住在地下深处的火山网络中。奥格弗林特的族群一直从奥格瑞玛下方布满熔岩的深处隧道向地表移动。",al={"为什么奥格瑞玛下方有穴居人","怒焰裂谷穴居人背景故事"}},{q="为什么奥格弗林特对部落充满敌意？",a="穴居人天生就是极具领地意识且暴力成性的野兽。奥格弗林特和他的追随者不断向地表推进，对部落的隧道和上方的城市构成了迫在眉睫的危险。",al={"为什么要杀奥格弗林特","为什么要与奥格弗林特战斗"}},{q="奥格弗林特与灼热之刃的关系如何？",a="他们共享这片裂谷，但这并不意味着他们是盟友：奥格弗林特的穴居人占据着靠近入口的隧道，而灼热之刃的邪教徒则在更深处的洞穴中活动。",al={"灼热之刃与奥格弗林特","穴居人与邪教有关吗"}}},fx={b435b0f8={q="奥格弗林特支持哪一方？",a="奥格弗林特只为自己和他的穴居人同胞而战。他不效忠部落、联盟，也不效忠同样潜伏在深渊中的火刃氏族；他的穴居人会攻击任何进入黑暗深处的部落守卫。",al={"奥格弗林特的阵营","奥格弗林特属于联盟还是部落","奥格弗林特效忠于谁"}},e0483c37={q="奥格弗林特想要什么？",a="奥格弗林特想守住自己的隧道。他的穴居人正从充满熔岩的深处向地表推进，会杀死任何进入深渊的外来者，甚至包括前来求和的使者。",al={"奥格弗林特的目标","怒焰裂谷的穴居人想要什么","奥格弗林特的目的"}}},fp="10,341,21.339.0,15.333.0,28.253.0,18.116.0,30.141.0,37.189.0,39.187.0,57.170.0"}
P.entries["npc:ogtinc"] = {n="奥汀克",s="奥汀克是一位独立的熊怪猎人，栖身于艾萨拉高耸的山脊上，俯瞰着下方的埃达拉斯废墟。为了维护自然平衡，他与自己的部落分道扬镳，并成为了塞纳里奥议会值得信赖的盟友与导师。那些寻求挑战卡利姆多最凶猛野兽的资深猎人，经常会寻求他的指导。",h="奥汀克是一位独立的熊怪猎人，栖身于艾萨拉高耸的山脊上，俯瞰着下方的埃达拉斯废墟。为了维护自然平衡，他与自己的部落分道扬镳，并成为了塞纳里奥议会值得信赖的盟友与导师。那些寻求挑战卡利姆多最凶猛野兽的资深猎人，经常会寻求他的...",kw={"艾萨拉","塞纳里奥","埃达拉斯","熊怪","猎人","奥汀克","木喉"},ang={["class:Druid"]="作为塞纳里奥议会坚定的合作伙伴，奥汀克代表了未受腐蚀的熊怪的野性智慧与德鲁伊的自然守护之间的一座难得的桥梁。",["class:Hunter"]="奥汀克为资深猎人提供了深度的精神与实践试炼，在对抗卡利姆多最致命生物的过程中考验他们的射击技巧与生存技能。"},sec={{t="与众不同的熊怪",b="尽管卡利姆多的大多数熊怪依然深受部落束缚，或者在第三次战争后沦为了腐蚀的牺牲品，但奥汀克选择了一条独特的道路。他远离同族，将自己的弓箭技艺和生存知识奉献给了塞纳里奥议会。他在木喉要塞东南方的一处高地上扎营，警惕地守护着艾萨拉这片古老而破碎的土地。"},{t="狩猎大师",b="奥汀克对卡利姆多荒野的深刻了解在资深追踪者中享有盛誉。他会考验那些磨练了自身技艺的猎人，派遣他们去收集稀有的战利品，例如快足野兽的鹿角、海浪冲击下海蛇的鳞片，以及绿龙的身体部位。通过这些试炼，他教导人们真正的狩猎应当尊重自然世界并维护平衡，而非盲目地杀戮。"}},faq={{q="奥汀克是谁？",a="奥汀克是一位造诣深厚的熊怪猎人，驻扎在艾萨拉的悬崖之上。与他那些避世或堕落的同胞不同，他离开了自己的祖传部落，将自己的追踪技巧与智慧贡献给了塞纳里奥议会的德鲁伊。",al={"奥汀克是谁","奥汀克背景故事","艾萨拉的熊怪"}},{q="在哪里可以找到奥汀克？",a="他位于艾萨拉，栖身于一处俯瞰古老埃达拉斯废墟的悬崖营地中，就在木喉要塞的东南方。",al={"奥汀克在哪里","奥汀克位置","如何找到奥汀克"}},{q="奥汀克为什么要离开他的部落？",a="奥汀克离开族人是为了专门协助塞纳里奥议会保护自然。虽然他确切的部落出身并未说明，但他清醒的头脑与平和的举止，与卡利姆多北部其他受到腐蚀的部落形成了鲜明对比。",al={"奥汀克为何离开","奥汀克部落","奥汀克属于木喉吗"}},{q="奥汀克在猎人中扮演什么角色？",a="奥汀克是那些达到训练巅峰的资深猎人的大师级导师。他指派他们追踪卡利姆多各地凶猛的野兽——从迅捷的快足野兽到绿龙军团的后裔——以证明他们对荒野的掌控力。",al={"奥汀克猎人任务","猎人训练师奥汀克","为什么拜访奥汀克"}},{q="奥汀克隶属于木喉要塞吗？",a="虽然他在木喉要塞附近扎营，但奥汀克是独立行动的，直接与塞纳里奥议会合作。无论旅行者与木喉熊怪部落的关系如何，只要他们以和平方式接近，他都会表现得非常友善。",al={"奥汀克 木喉要塞","木喉要塞声望 奥汀克","奥汀克友善吗"}},{q="奥汀克为什么要守护埃达拉斯废墟？",a="他位于废墟上方高处的有利位置，可以毫无阻碍地观察下方不安宁的荒野，那里的娜迦、元素生物以及残留的魔法回响都在威胁着沿海森林脆弱的平衡。",al={"奥汀克为什么在艾萨拉","埃达拉斯 奥汀克","奥汀克悬崖"}}},fp="6,350,15.381.0,18.456.0,14.243.0,26.137.0,31.267.0,39.257.0,41.231.0,49.209.0"}
P.entries["npc:ogunaro-wolfrunner"] = {n="奥古纳罗",s="奥古纳罗是部落在奥格瑞玛首屈一指的狼群饲养员和犬舍管理员，驻扎在荣誉谷的猎人大厅旁。他照料着那些被精心挑选出来的凶猛座狼，这些座狼肩负着载送兽人勇士及其可靠盟友奔赴战场的使命。对于那些寻求与杜隆塔尔的顶级掠食者建立羁绊的经验丰富的骑手来说，奥古纳罗就是他们必须要找的大师。",h="奥古纳罗是部落在奥格瑞玛首屈一指的狼群饲养员和犬舍管理员，驻扎在荣誉谷的猎人大厅旁。他照料着那些被精心挑选出来的凶猛座狼，这些座狼肩负着载送兽人勇士及其可靠盟友奔赴战场的使命。对于那些寻求与杜隆塔尔的顶级掠食者建立羁绊的...",kw={"恐狼","奥古纳罗","奥格瑞玛坐骑","森林狼","valley of honor","狼坐骑"},ang={["faction:Horde"]="巨魔、牛头人和被遗忘者必须向奥格瑞玛证明他们的奉献精神和荣誉，奥古纳罗才会将座狼坐骑托付给他们。",["race:Orc"]="对于兽人来说，骑狼是一种可以追溯到德拉诺氏族的祖传传统；奥古纳罗正是这种神圣军事羁绊的守护者。"},sec={{t="狼群大师",b="奥古纳罗位于荣誉谷的猎人大厅附近，负责监督奥格瑞玛战狼的繁育与驯化。兽人与狼之间的羁绊可以追溯到德拉诺平原和杜隆塔尔崎岖荒野的数代之前，这代表了一种基于相互尊重的伙伴关系，而不仅仅是驯化。奥古纳罗确保只有最强壮、最凶猛的野兽——从恐狼到敏捷的森林潜行者——才会交给那些已经向大酋长证明了自己力量与价值的勇士。"}},faq={{q="奥古纳罗是谁？",a="奥古纳罗是部落的主要座狼饲养员和坐骑商人，位于奥格瑞玛荣誉谷的猎人大厅外。",al={"奥古纳罗","奥格瑞玛狼坐骑商人","兽人坐骑商人"}},{q="任何人都可以从他那里购买座狼吗？",a="根据传统，兽人在接受适当训练后即可自由获得座狼。非兽人的部落成员必须在获得奥格瑞玛的崇拜声望并赢得其最大信任后，奥古纳罗才会出售他的珍贵野兽。",al={"非兽人可以买狼吗","狼坐骑声望要求"}},{q="他提供哪些种类的座狼？",a="奥古纳罗饲养着各种久经沙场的坐骑，包括黑色、棕色、恐狼和森林狼，以及适合战争老兵的迅捷装甲品种。",al={"狼坐骑种类","奥古纳罗出售的狼"}}},fx={["37d9a7a8"]={q="奥古纳罗支持哪一方？",a="奥古纳罗完全效忠于部落和奥格瑞玛城。他在荣誉谷照料部落珍贵的坐骑狼，为自己的兽人同胞以及那些赢得奥格瑞玛深厚信任和崇高敬意的人提供坐骑。",al={"奥古纳罗的阵营","奥古纳罗效忠于谁","奥古纳罗属于部落还是联盟"}},c9c48f43={q="奥古纳罗为什么在荣誉谷？",a="奥古纳罗住在奥格瑞玛的荣誉谷，就在猎手大厅外。这里是部落最强悍的战士和猎人的训练与集结之地，自然适合为久经考验的勇士照料、繁育并提供强健的战狼。",al={"奥古纳罗为什么在奥格瑞玛","奥古纳罗的位置","奥古纳罗为什么在这里"}},c3908665={q="奥古纳罗想要什么？",a="奥古纳罗专心培育并提供强壮可靠的狼，供部落勇士使用。他只希望兽人族标志性的坐骑能找到称职的骑手，懂得如何善待它们，并在战斗中驾驭它们。",al={"奥古纳罗想要什么","奥古纳罗的目标","奥古纳罗·狼奔的动机"}}},fp="18,331,18.525.0,26.142.0,36.212.0,37.167.0"}
P.entries["npc:old-murk-eye"] = {n="老瞎眼",s="老瞎眼是一只臭名昭著、久经沙场的鱼人，徘徊在西部荒野的南部海岸线。它在同类中备受尊崇，令沿海的水手闻风丧胆，对于任何在西部荒野灯塔附近徘徊的人来说，它都是一个致命的威胁。",h="老瞎眼是一只臭名昭著、久经沙场的鱼人，徘徊在西部荒野的南部海岸线。它在同类中备受尊崇，令沿海的水手闻风丧胆，对于任何在西部荒野灯塔附近徘徊的人来说，它都是一个致命的威胁。",kw={"葛瑞森船长","海岸威胁","老瞎眼","鱼人","西部荒野","西部荒野灯塔"},ang={["faction:Alliance"]="对于清理西部荒野的联盟冒险者来说，消灭老瞎眼意味着除掉了一个臭名昭著的掠食者，它总是捕食搁浅的旅行者和船员。"},sec={{t="海岸线的恐怖",b="虽然鱼人在西部荒野的海岸边很常见，但老瞎眼与那些低级的拾荒者不同。这只饱经风霜的野兽比它的族群更强壮、更具攻击性，它在西部荒野灯塔周围的浪潮中徘徊。它长期存在，给当地的水手带来了太多的痛苦，以至于幽灵葛瑞森船长想要除掉它，并悬赏这只生物的完美鳞片，以此打破它对浅滩的控制。"}},faq={{q="老瞎眼在哪里徘徊？",a="它巡逻在西部荒野西南部沙滩和浅水区，就在西部荒野灯塔附近的海岸线上。",al={"老瞎眼位置","哪里可以找到老瞎眼","老瞎眼在哪里"}},{q="为什么葛瑞森船长想要老瞎眼死？",a="葛瑞森船长认为老瞎眼是对沿海水域持续不断的威胁。为了遏制海滩上的暴力行为，他悬赏了这只传奇鱼人，要求用鳞片作为完成任务的证明。",al={"葛瑞森 老瞎眼","为什么要杀老瞎眼"}},{q="老瞎眼和普通的鱼人有什么不同吗？",a="是的。它比周围的海岸奔行者和踏潮者走卒明显更强壮、更耐打、更具攻击性，是当地海岸族群中的部落勇士。",al={"老瞎眼有多厉害","老瞎眼是精英吗"}}},fx={["0038f035"]={q="老瞎眼是谁？",a="老瞎眼是一只恶名昭彰、身强体壮的鱼人，在西部荒野的海岸线上巡游，活动范围靠近西部荒野灯塔。当地人和水手都视他为海岸上的祸患；在同类中，他格外强悍狡猾，持续威胁着所有在西部海岸行走的人。",al={"瞎眼是谁","老瞎眼是谁","老瞎眼的背景"}},["295d9e5f"]={q="老瞎眼支持哪一方？",a="老瞎眼只为自己和岸边的鱼人同伴而战。他不效忠任何王国、公会或阵营，认为会呼吸空气的陆地居民都是侵犯领地的入侵者，必须赶走或杀死。",al={"瞎眼的阵营","瞎眼为谁工作","瞎眼是联盟成员吗"}},["48ac0465"]={q="老瞎眼为什么在西部荒野？",a="老瞎眼把西部荒野灯塔周围的沿海水域和岩石海滩视为自己的猎场。与世隔绝的海岸鱼产丰饶，也是他袭击毫无防备的旅人，或劫掠在崎岖海岸触礁的水手的据点。",al={"瞎眼为什么在这里","老瞎眼为什么在西部荒野","瞎眼的位置和背景"}},["5afdb8dc"]={q="老瞎眼为什么出名或令人畏惧？",a="老瞎眼在水手和当地人中声名狼藉，是西部荒野海岸线上出了名的威胁。他比普通的沿海鱼人更强悍、更具攻击性，在无数次冲突中幸存下来，并不断威胁靠近灯塔海岸的人，直到葛瑞森船长这样的灵魂为他悬赏。",al={"瞎眼为什么令人畏惧","老瞎眼为什么恶名昭彰","瞎眼的传说"}}},fp="12,229,23.451.0,31.127.0,48.203.0,48.184.0"}
P.entries["npc:old-serra-kis"] = {n="瑟拉吉斯",s="瑟拉吉斯是一头古老而巨大的巨兽，栖息在黑暗深渊水下的地下水域中。这头庞大的野兽隐藏在遗迹下方被水淹没的洞穴里，对于任何试图寻找它的人来说都是致命的。",h="瑟拉吉斯是一头古老而巨大的巨兽，栖息在黑暗深渊水下的地下水域中。这头庞大的野兽隐藏在遗迹下方被水淹没的洞穴里，对于任何试图寻找它的人来说都是致命的。",kw={"黑暗深渊","forgotten pool","moonshrine sanctum","瑟拉吉斯","巨兽","暮光之锤","水下首领"},ang={["class:Druid"]="对于荒野德鲁伊来说，在潜入无光水潭对抗这头史前掠食者时，水栖形态是必不可少的。",["class:Shaman"]="通过与元素进行精神交流而获得的“水下呼吸”法术，可以确保你的同伴在与这头远古巨兽搏斗时不会溺水。",["class:Warlock"]="术士赋予“水下呼吸”的能力，将原本致命、缺氧的地下伏击变成了一场可应对的战斗。"},sec={{t="深渊中未被征服者",b="暮光之锤在沉没的Moonshrine Ruins安营扎寨，但在Moonshrine Sanctum下方的暗水中隐藏着更古老、更野蛮的事物。瑟拉吉斯是这处沉没的神庙中最大的巨兽，它潜伏在Forgotten Pool里，那是一处位于遗迹下方、鲜有人会去寻找的被水淹没的洞穴。"},{t="隐藏的威胁",b="要找到瑟拉吉斯，必须深入神庙地面下方，潜入遗迹之下的被淹没的洞穴中。由于没有空气积存点，洞穴本身和里面的野兽一样致命。那些将它逼入绝境的人会发现，瑟拉吉斯拥有极其不自然的暗影汲取复原力，它在浑浊的黑暗中一边吸取攻击者的生命来维持自己的活力。"}},faq={{q="瑟拉吉斯是什么生物？",a="瑟拉吉斯是一头巨大而古老的巨兽——这是一种长颈水生爬行动物，原产于艾泽拉斯的湖泊和沿海水域。",al={"什么是瑟拉吉斯","瑟拉吉斯是九头蛇吗","瑟拉吉斯生物类型"}},{q="为什么暮光之锤没有杀死它？",a="没有记录显示该邪教曾猎杀过它。瑟拉吉斯潜伏在Forgotten Pool中，这是一处位于遗迹下方、被水淹没且没有空气的洞穴，对于任何潜入其中追寻它的人来说都是致命的。",al={"为什么瑟拉吉斯还活着","暮光之锤与瑟拉吉斯"}},{q="瑟拉吉斯位于何处？",a="它潜伏在黑暗深渊内Moonshrine Sanctum周围水域下方的一处水下洞穴中。游泳者必须潜入遗迹下方的一处无空气水潭才能遇到它。",al={"如何找到瑟拉吉斯","瑟拉吉斯位置","瑟拉吉斯在哪里"}},{q="为什么与它战斗很危险？",a="除了必须在完全没有天然空气积存的水下进行战斗外，瑟拉吉斯还会在战斗中从所有附近的敌人身上汲取暗影能量来治愈自己的伤口。",al={"瑟拉吉斯技能","如何击败瑟拉吉斯"}},{q="瑟拉吉斯为暮光之锤效力吗？",a="不。与其他被邪教腐蚀或训练的野兽不同，瑟拉吉斯仍然是一头完全未被驯服的野生掠食者，守护着它的地下巢穴。",al={"瑟拉吉斯是邪教徒的宠物吗","谁控制着瑟拉吉斯"}},{q="与瑟拉吉斯战斗时可以呼吸吗？",a="它封闭的洞穴顶部没有空气积存点，迫使水下战斗者必须要么管理好自己的呼吸，要么使用魔法水下呼吸辅助，或者将野兽风筝到开阔水域。",al={"溺水瑟拉吉斯","瑟拉吉斯水下呼吸"}}},fx={fc1a5d36={q="瑟拉吉斯为什么令人畏惧？",a="瑟拉吉斯是黑暗深渊中体型最大的裂肢龙，藏身于月神殿废墟下方一处被水淹没的洞穴中，那里没有空气可供呼吸。他会吸取与自己战斗者的生命来治愈伤口，因此任何潜水追击他的人都将面对致命的敌手。",al={"瑟拉吉斯的名声","瑟拉吉斯为什么出名","为什么害怕瑟拉吉斯"}}},fp="13,212,25.302.0,15.368.0,39.130.0,42.189.0,31.183.0,34.166.0,43.147.0,49.181.0"}
P.entries["npc:onyxia"] = {n="奥妮克希亚",s="奥妮克希亚是黑龙军团的育母，也是Deathwing阴险狡诈的女儿。她潜伏在尘泥沼泽深处的巢穴中，在照料她不断壮大的龙蛋的同时，也指挥着她那邪恶的黑龙军团，试图统治凡人国度。",h="奥妮克希亚是黑龙军团的育母，也是Deathwing阴险狡诈的女儿。她潜伏在尘泥沼泽深处的巢穴中，在照料她不断壮大的龙蛋的同时，也指挥着她那邪恶的黑龙军团，试图统治凡人国度。",kw={"安度因·乌瑞恩国王","黑龙军团","bolvar fordragon","deathwing","奈法利安","奥妮克希亚","暴风城"},sec={{t="朝堂之上的育母",b="当她的兄弟奈法利安在黑石塔集结大军时，奥妮克希亚则通过诡计追逐权力。她伪装成女伯爵卡特拉娜·普瑞斯托，钻营进入了暴风城贵族权力的核心。通过以贵族议会信任的顾问身份自居，她系统性地削弱了王国的军事力量，蓄意扣留了本应派往西部荒野、赤脊山和燃烧平原前哨站的士兵与资源，使凡人国度变得毫无防备。"},{t="毁灭的建筑师",b="在普瑞斯托女伯爵那虚伪的笑容背后，隐藏着一位掠食者的主谋。随着瓦里安国王在前往塞拉摩参加和平峰会的途中失踪，普瑞斯托对年幼的安度因小国王施加了深远的影响，并控制了伯瓦尔·弗塔根公爵，让暴风城的王座岌岌可危。"}},faq={{q="女伯爵卡特拉娜·普瑞斯托是谁？",a="女伯爵卡特拉娜·普瑞斯托是一位暴风城的贵族女性，也是朝中深受信任的顾问。在瓦里安国王失踪后，她站在Stormwind Keep里小国王安度因和伯瓦尔·弗塔根公爵的身侧，她的建议在贵族议会中具有举足轻重的影响力。",al={"普瑞斯托身份","谁是普瑞斯托","卡特拉娜·普瑞斯托真实身份"}},{q="奥妮克希亚为何针对暴风城？",a="奥妮克希亚旨在让暴风城王国臣服于黑龙军团的统治之下，瓦解其军事力量，并协助她的兄弟奈法利安统治该地区。",al={"奥妮克希亚的目标","为何攻击暴风城","普瑞斯托动机"}},{q="奥妮克希亚住在哪里？",a="奥妮克希亚的家位于尘泥沼泽湿地中的地下巢穴，她在那里照料着黑龙军团的后代。",al={"奥妮克希亚在哪里","奥妮克希亚位置","奥妮克希亚巢穴位置"}},{q="她与奈法利安和Deathwing有什么关系？",a="奥妮克希亚是守护巨龙Deathwing的女儿。她也是奈法利安的妹妹，与他密切合作以恢复黑龙军团在艾泽拉斯的统治地位。",al={"奥妮克希亚兄弟","奥妮克希亚父亲","奥妮克希亚家族"}}},fx={fd0ec0c3={q="奥妮克希亚站在哪一方？",a="奥妮克希亚只效忠于黑龙军团，奉行家族的黑暗谋划。她与兄长奈法利安关系密切，共同致力于重建腐化的黑龙军团并奴役凡人种族。她不效忠于联盟或部落；凡人的王国不过是供她操纵、削弱并摧毁的对象，以确保黑龙称霸。",al={"奥妮克希亚所属阵营","奥妮克希亚效忠于谁","奥妮克希亚的阵营","奥妮克希亚属于联盟还是部落"}},d77da3f3={q="奥妮克希亚想要什么？",a="奥妮克希亚企图让暴风城王国受黑龙军团摆布。她暗中削弱其军队，使其疆域毫无防备，好让自己的龙裔和兄长奈法利安的军队得以崛起，无人能挡。",al={"奥妮克希亚想要什么","奥妮克希亚的目标","奥妮克希亚的动机","奥妮克希亚的计划是什么"}},ba62a202={q="奥妮克希亚为何如此令人畏惧？",a="作为Deathwing之女、黑龙军团的育母，奥妮克希亚既拥有强大的力量，也诡计多端。尽管与成年巨龙相比，她的体型相对较小，但她出击迅捷如电，喷吐的烈焰片刻之间便能熔化铁器。再加上她擅长在凡人之间散布欺骗与谎言，足以对艾泽拉斯构成生死存亡的威胁。",al={"奥妮克希亚为何令人畏惧","奥妮克希亚强大吗","奥妮克希亚的名声"}}},fp="6,267,28.488.1,17.294.2,28.254.2,33.170.2,23.138.2,49.178.0"}
P.entries["npc:orendil-broadleaf"] = {n="奥雷迪尔·阔叶",s="奥雷迪尔·阔叶是一位技艺精湛的暗夜精灵草药师兼治疗师，驻扎在灰谷西部的迈斯特拉岗哨。他以对森林植物群的渊博知识而闻名，并调制各种关键的药剂，挽救了这片饱受困扰的林地中许多年轻的生命。",h="奥雷迪尔·阔叶是一位技艺精湛的暗夜精灵草药师兼治疗师，驻扎在灰谷西部的迈斯特拉岗哨。他以对森林植物群的渊博知识而闻名，并调制各种关键的药剂，挽救了这片饱受困扰的林地中许多年轻的生命。",kw={"灰谷","阿斯特兰纳","巴斯兰的头发","迈斯特拉岗哨","奥雷迪尔·阔叶","奥雷迪尔的药剂","蕾拉·白月"},ang={["profession:Herbalism"]="奥雷迪尔展示了区域植物学在拯救生命方面的重要性，依靠像巴斯兰的头发这样的稀有植物在野外调制强效解毒剂。",["race:NightElf"]="对于保卫灰谷的暗夜精灵来说，奥雷迪尔是一位至关重要的生命守护者，他温和的药剂甚至能救治垂死的儿童。"},sec={{t="林边治疗师",b="奥雷迪尔·阔叶驻扎在灰谷西界边界的迈斯特拉岗哨，作为一名高超的治疗师照料着病患。由于他精通当地草药与康复工艺，他常依靠路过的旅行者收集稀有的自然试剂。即使紧张局势和冲突不断侵蚀着森林，他依然孜孜不倦地专注于保护族人并抚慰他们的伤痛。"},{t="与疾病赛跑",b="最重要的是，奥雷迪尔在拯救阿斯特兰纳一名患病儿童蕾拉·白月（Relara Whitemoon）的绝望行动中发挥了核心作用。通过对森林植物学的仔细研究——包括巴斯兰的头发——他调制出了足以遏制致命疾病的强效药剂，证明了草药掌握在抵御灰谷阴霾时依然是一道至关重要的护盾。"}},faq={{q="谁是奥雷迪尔·阔叶？",a="奥雷迪尔·阔叶是一位住在灰谷西部迈斯特拉岗哨的暗夜精灵草药师和治疗师。他在草药与治疗方面的造诣远近闻名。",al={"奥雷迪尔·阔叶","谁是奥雷迪尔","奥雷迪尔 灰谷"}},{q="在哪里可以找到奥雷迪尔·阔叶？",a="他位于迈斯特拉岗哨，这是一处位于灰谷西部主路旁、靠近黑海岸边界的暗夜精灵前哨站。",al={"奥雷迪尔·阔叶位置","寻找奥雷迪尔","奥雷迪尔在哪里"}},{q="奥雷迪尔试图治愈什么？",a="奥雷迪尔正在配制一种治疗药水来拯救居住在阿斯特兰纳的患病暗夜精灵儿童蕾拉·白月，他使用了从灰谷荒野中采集的稀有草药。",al={"奥雷迪尔 治疗","奥雷迪尔在治愈谁","蕾拉·白月 治疗"}}},fx={c4fe2e8b={q="奥雷迪尔·阔叶站在哪一方？",a="奥雷迪尔·阔叶坚定地与联盟和达纳苏斯的暗夜精灵站在一起。他驻守在迈斯特拉岗哨，与哨兵并肩抵御部落对灰谷的侵扰，并照料同族的伤病。",al={"奥雷迪尔·阔叶所属阵营","奥雷迪尔·阔叶是联盟成员吗","奥雷迪尔·阔叶效忠于谁"}},["5dbbc739"]={q="奥雷迪尔·阔叶想要什么？",a="奥雷迪尔·阔叶致力于救治病患和伤者，同时守护森林。他最关心的是为阿斯特兰纳一名病弱的暗夜精灵女孩Relara Whitemoon调制救命药剂，并依靠外来的旅行者采集救她所需的稀有草药。",al={"奥雷迪尔·阔叶想要什么","奥雷迪尔·阔叶的目标","奥雷迪尔·阔叶的动机"}},["9af45c4c"]={q="奥雷迪尔·阔叶为何在这里？",a="奥雷迪尔留在迈斯特拉岗哨，作为一名尽职的草药师和治疗者守卫灰谷西部边境。他在那里照料同族的病痛，并依靠路过的旅行者采集药剂所需的稀有草药。",al={"奥雷迪尔·阔叶为何在迈斯特拉岗哨","奥雷迪尔为何在灰谷","奥雷迪尔·阔叶在这里做什么"}},["7beb4a99"]={q="奥雷迪尔·阔叶与谁有联系？",a="奥雷迪尔·阔叶与守卫迈斯特拉岗哨的哨兵并肩作战，并与阿斯特兰纳的皮尔图拉斯·怀特姆恩密切合作，保护皮尔图拉斯年幼的女儿Relara。",al={"奥雷迪尔·阔叶的人际关系","奥雷迪尔·阔叶与谁共事","奥雷迪尔·阔叶的学徒"}}},fp="17,235,27.408.0,23.358.1,25.148.0,37.135.0,31.174.0"}
P.entries["npc:orenthil-whisperwind"] = {n="奥雷希尔·语风",s="奥雷希尔·语风是一位居住在泰达希尔的暗夜精灵，在幽影谷的枝叶下可以找到他。",h="奥雷希尔·语风是一位居住在泰达希尔的暗夜精灵，在幽影谷的枝叶下可以找到他。",kw={"奥雷希尔","幽影谷","泰达希尔","语风"},sec={{t="泰达希尔的友善面孔",b="奥雷希尔·语风居住在泰达希尔树冠下的幽影谷，与那里的暗夜精灵为伴。关于他的个人历史鲜有记载。"}},faq={{q="奥雷希尔·语风是谁？",a="他是一位居住在泰达希尔幽影谷的暗夜精灵。他是迎接踏入世界之树枝叶冒险者的引路人。",al={"奥雷希尔","奥雷希尔·语风信息","这个精灵是谁"}},{q="我在哪里可以找到奥雷希尔·语风？",a="奥雷希尔居住在幽影谷，那是泰达希尔内暗夜精灵的初始定居点。",al={"奥雷希尔位置","奥雷希尔在哪里","奥雷希尔地图"}}},fx={["38b36176"]={q="奥雷希尔·语风站在哪一方？",a="奥雷希尔坚定地站在达纳苏斯的暗夜精灵和更广大的联盟一边。他居住在泰达希尔的树枝间，与同族为伴，并迎接前来帮助族人的新旅客。",al={"奥雷希尔·语风所属阵营","奥雷希尔是联盟成员吗","奥雷希尔效忠于谁"}},["71428597"]={q="奥雷希尔·语风为何在这里？",a="奥雷希尔居住在泰达希尔的幽影谷。关于他为何在那里定居，没有留下记录。",al={"奥雷希尔·语风的目的","奥雷希尔为何在多兰纳尔","奥雷希尔在做什么"}}},fp="20,105,29.146.0,28.147.0,38.84.0"}
P.entries["npc:orgnil-soulscar"] = {n="奥戈尼尔·魂痕",s="奥戈尼尔·魂痕是一位驻扎在杜隆塔尔中部剃刀岭的兽人调查员。他担任一种非正式的治安官，负责协调防御和情报工作，以应对对这个新生的国家内部产生的威胁。他主要关心的是隐藏在杜隆塔尔峡谷中的火刃氏族邪教所投下的阴影。",h="奥戈尼尔·魂痕是一位驻扎在杜隆塔尔中部剃刀岭的兽人调查员。他担任一种非正式的治安官，负责协调防御和情报工作，以应对对这个新生的国家内部产生的威胁。他主要关心的是隐藏在杜隆塔尔峡谷中的火刃氏族邪教所投下的阴影。",kw={"火刃氏族","杜隆塔尔","玛戈兹","奥戈尼尔·魂痕","剃刀岭","暗影议会","骷髅石"},ang={["class:Warlock"]="术士在奥戈尼尔面前必须小心行事，因为他的全部重心就是猎杀和根除杜隆塔尔境内不受约束的恶魔腐化。",["faction:Horde"]="奥戈尼尔确保在部落向外建设新国家的同时，其中心地带不会被内部的邪教徒从内部掏空。",["race:Orc"]="对于年轻的兽人来说，奥戈尼尔代表了对抗曾经奴役过各氏族的恶魔污染的前线，提醒新兵们保持警惕以维护他们新家园的纯洁。"},sec={{t="剃刀岭守望者",b="奥戈尼尔·魂痕驻扎在剃刀岭，肩负着追踪杜隆塔尔境内颠覆活动和阴险威胁的严峻责任。当步兵巡逻队向外关注联盟的据点和半人马突袭队时，奥戈尼尔则专注于内部滋生的腐化。他收集来自该地区侦察兵的报告，拼凑出仪式腐化和非法集会的证据。"},{t="猎杀暗影议会的余党",b="奥戈尼尔的主要工作重点是秘密复苏的火刃氏族邪教，他们的术士隐藏在像骷髅石这样的洞穴中。深知邪能魔法在过去几代人中给兽人种族带来的毁灭性打击，奥戈尼尔绝不允许恶魔崇拜在奥格瑞玛附近再次扎根。他指挥受信任的新兵打击邪教徒，收集仪式护身符，并与像玛戈兹这样的当地隐士和萨满商议，以了解正在作祟的黑暗魔法。"}},faq={{q="奥戈尼尔·魂痕是谁？",a="奥戈尼尔·魂痕是一位驻扎在剃刀岭的兽人官员，担任杜隆塔尔防御工作的调查员和协调员。他指挥勇士和侦察兵对抗威胁新定居兽人领地的隐蔽危险。",al={"奥戈尼尔是谁","奥戈尼尔·魂痕背景故事","剃刀岭任务发布者"}},{q="奥戈尼尔最担心什么威胁？",a="奥戈尼尔致力于根除火刃氏族邪教。他认为他们在杜隆塔尔隐蔽洞穴中的存在及其腐蚀性的邪能魔法，是对萨尔为部落设想的新起点所构成的致命威胁。",al={"奥戈尼尔想要什么","奥戈尼尔的敌人","奥戈尼尔对抗谁"}},{q="为什么奥戈尼尔要把旅行者送去见玛戈兹？",a="玛戈兹是一位居住在剃刀岭北部的博学隐士，他了解火刃氏族的黑暗迹象和仪式。奥戈尼尔指示侦察兵去找玛戈兹，以破译邪教的动向并揭开正在酝酿的魔法腐化。",al={"为什么找玛戈兹","奥戈尼尔和玛戈兹","玛戈兹对奥戈尼尔的意义"}},{q="在哪里可以找到奥戈尼尔·魂痕？",a="奥戈尼尔驻扎在剃刀岭定居点的户外，靠近杜隆塔尔的中央路口。",al={"奥戈尼尔位置","奥戈尼尔在哪里","寻找奥戈尼尔·魂痕"}},{q="杜隆塔尔的火刃氏族是什么？",a="火刃氏族是一个听命于恶魔主人和暗影议会的邪恶邪教。他们躲藏在像骷髅石和尘风洞穴这样的深谷中，试图毒害杜隆塔尔的野生动物，并诱惑年轻的兽人重回恶魔的奴役。",al={"杜隆塔尔的火刃氏族","火刃氏族邪教","火刃氏族是什么人"}},{q="奥戈尼尔是直接为萨尔工作吗？",a="奥戈尼尔作为以剃刀岭为中心的区域防御体系的一部分开展工作，执行大酋长保护杜隆塔尔免受煽动和恶魔影响的使命。",al={"奥戈尼尔与萨尔","奥戈尼尔是大酋长的卫兵吗"}}},fx={["68dd86eb"]={q="奥戈尼尔·魂痕站在哪一方？",a="奥戈尼尔完全效忠于部落，并致力于保卫杜隆塔尔。他驻守在剃刀岭，负责维护当地秩序与安全，全力保护年轻的兽人聚居地免受潜伏在峡谷阴影中的火刃氏族教徒等隐秘内部威胁。",al={"奥戈尼尔·魂痕所属阵营","奥戈尼尔效忠于谁","奥戈尼尔的效忠对象"}},["07ede484"]={q="奥戈尼尔·魂痕想要什么？",a="奥戈尼尔想要铲除杜隆塔尔境内火刃氏族的阴影。他需要可靠的邪教徒活动情报，因此派遣能干的冒险者击杀他们的术士、夺回被盗的护符，并向Margoz等当地隐士请教，以查明蔓延大地的恶魔腐化。",al={"奥戈尼尔想要什么","奥戈尼尔的目标","奥戈尼尔的目的"}},["9d37257b"]={q="奥戈尼尔·魂痕为何在剃刀岭？",a="剃刀岭是奥格瑞玛以外杜隆塔尔的防务与后勤中心。奥戈尼尔驻守于此，负责调查并保护当地，正好可以监视干燥山谷中的可疑动静，并动员旅行者对付步步逼近的邪教徒和被污染的野兽。",al={"奥戈尼尔为何在剃刀岭","奥戈尼尔在剃刀岭的职责","奥戈尼尔为何在这里"}},["05bd4129"]={q="奥戈尼尔·魂痕与谁有联系？",a="奥戈尼尔与当地的部落守卫一起对抗火刃氏族，并指引冒险者去找住在剃刀岭东北方的Margoz。",al={"奥戈尼尔的盟友","奥戈尼尔的人际关系","奥戈尼尔与谁共事"}}},fp="15,308,21.388.0,37.458.1,23.216.0,41.210.0,41.233.0,35.101.0,37.240.1,37.175.0"}
P.entries["npc:orgrim-doomhammer"] = {n="Orgrim Doomhammer",s="Orgrim Doomhammer曾是第二次战争期间旧部落的至高大酋长，被后人铭记为历史上最伟大的兽人战士之一。尽管他在阿拉希高地解放收容所时牺牲，但他的精神在奥格瑞玛城中得以长存，也通过萨尔——这位继承了他强大的战锤和黑色板甲的继任者——延续至今。",h="Orgrim...",kw={"黑手","黑石","毁灭之锤","落锤镇","orgrim","奥格瑞玛","萨尔","大酋长"},ang={["faction:Alliance"]="对于联盟来说，Orgrim Doomhammer仍然是第二次战争期间东部王国险些覆灭的沉痛象征，他在黑石塔战败前屠戮了无数英雄。",["race:Orc"]="兽人们尊崇Orgrim Doomhammer，将他视为带领族人摆脱麻木和奴役的解放者，他选择了荣誉而非恶魔的统治。"},sec={{t="大酋长的崛起",b="Orgrim Doomhammer最初是黑石氏族酋长黑手的副官，他拒绝了古尔丹提供的恶魔之血，尽管他将这份疑虑隐藏在对黑手的忠诚之下。在第一次战争临近结束时，出于对暗影议会背信弃义以及谋杀他童年挚友杜隆坦的愤恨，Orgrim Doomhammer在荣誉决斗中杀死了黑手。在继任大酋长后，他无情地清洗了古尔丹的术士，并在第二次战争中率领部落横扫了东部王国。尽管他是一位拥有毁灭性战略眼光的统帅，将人类王国推向了灭亡的边缘，但最终因为古尔丹的背叛导致部队分裂，他在黑石塔外战败被俘。"},{t="陨落与传承",b="Orgrim Doomhammer从人类的囚笼中逃脱后，一直隐姓埋名，直到他遇见了杜隆坦的孤子萨尔。在这位年轻萨满愿景的激励下，Orgrim Doomhammer集结了残存的兽人氏族，冲击收容所并解放了他们的人民。在阿拉希高地某处营地的一场激战中，这位大酋长被人从背后用长矛刺中。在弥留之际，他将自己的黑色板甲、传家宝武器——毁灭之锤——以及大酋长的头衔传给了萨尔。为了纪念他，那座被解放的前哨站被更名为落锤镇，而在杜隆塔尔新建的首都则被命名为奥格瑞玛。"}},faq={{q="Orgrim Doomhammer是谁？",a="他是黑石氏族的酋长，也是在第二次战争中指挥部落的大酋长。多年后从人类囚笼中逃脱，他与萨尔并肩作战解放了被囚禁的族人，直到在阿拉希高地牺牲。",al={"毁灭之锤是谁","orgrim doomhammer背景","大酋长毁灭之锤是谁"}},{q="Orgrim Doomhammer是如何牺牲的？",a="Orgrim Doomhammer在突袭阿拉希高地的一处人类收容所时，被一名骑士从背后用长矛刺中身亡。萨尔继承了他的衣钵，而那场胜利的地点被命名为落锤镇，以纪念他的牺牲。",al={"orgrim doomhammer之死","毁灭之锤是怎么死的","谁杀了毁灭之锤"}},{q="为什么部落的首都会被命名为奥格瑞玛？",a="萨尔以他导师兼前任大酋长的名字命名了这座位于杜隆塔尔的要塞城市。Orgrim Doomhammer看出了萨尔身上的潜力并指定他为新任大酋长，确保了部落将在荣誉而非恶魔腐化的基础上重建。",al={"为什么叫奥格瑞玛","奥格瑞玛命名","以orgrim命名的城市"}},{q="Orgrim Doomhammer喝过恶魔之血吗？",a="没有。Orgrim Doomhammer抵御了恶魔之血的诱惑，同时将他的疑虑隐藏在对黑手的忠诚之下，这使他保持了清醒，并最终从内部摧毁了古尔丹的暗影议会。",al={"毁灭之锤喝过血吗","orgrim被腐化了吗","orgrim恶魔之血"}}},fp="17,342,20.674.0,15.625.0,26.251.0,30.231.0,41.218.0,33.197.0"}
P.entries["npc:ormak-grimshot"] = {n="奥玛克",s="奥玛克是一位经验丰富的兽人猎人训练师，常驻于奥格瑞玛的Valley of Honor中的猎人大厅。他与忠诚的狼Grimfang形影不离，指导年轻的部落猎人学习追踪术、射击技巧以及与野兽建立羁绊的方法。",h="奥玛克是一位经验丰富的兽人猎人训练师，常驻于奥格瑞玛的Valley of Honor中的猎人大厅。他与忠诚的狼Grimfang形影不离，指导年轻的部落猎人学习追踪术、射击技巧以及与野兽建立羁绊的方法。",kw={"野兽训练","grimfang","猎人训练师","猎人大厅","奥格瑞玛","奥玛克","valley of honor"},ang={["class:Hunter"]="奥玛克是部落猎人的重要导师，引导他们履行驯服和照料忠诚动物伙伴的职责。",["race:Orc"]="奥玛克体现了经典的兽人生存技能，展现了兽人如何与狼和当地的掠食者并肩作战来保卫杜隆塔尔。"},sec={{t="狩猎大师",b="奥玛克常驻于Valley of Honor的猎人大厅，他是部落追踪者和射手武技指导的基石。与他的同伴狼Grimfang一起，奥玛克传授在卡利姆多严酷荒野中生存所需的基础纪律。对于从杜隆塔尔试炼归来的兽人和巨魔猎人，他提供关于驯服和指挥野兽这门神圣艺术的重要指导，确保每位猎人都能与他们的动物伙伴建立持久的羁绊。"}},faq={{q="奥玛克是谁？",a="奥玛克是一位常驻于奥格瑞玛的Valley of Honor的资深兽人猎人训练师。他教授部落的新手猎人远程战斗和野兽控制方面的高级技能。",al={"谁是奥玛克","奥玛克背景故事","奥玛克猎人训练师"}},{q="我能在哪里找到奥玛克？",a="奥玛克位于奥格瑞玛东部Valley of Honor里的猎人大厅内。他站在他的宠物狼Grimfang旁边。",al={"奥玛克位置","奥玛克在哪里","找到奥玛克"}},{q="他身边的狼是谁？",a="他身边的狼是Grimfang，奥玛克忠诚的动物伙伴，这展现了一位熟练的猎人与他们的宠物之间紧密的纽带。",al={"奥玛克的狼","grimfang","奥玛克的宠物"}},{q="他对新手猎人起什么作用？",a="当新手兽人和巨魔猎人在杜隆塔尔完成基础试炼后，奥玛克会指导他们如何训练、喂养和管理他们刚驯服的野兽。",al={"奥格瑞玛猎人宠物任务","奥玛克驯服任务","training the beast 奥玛克"}}},fx={["84e77df7"]={q="奥玛克站在哪一方？",a="奥玛克全心效忠于部落，并致力于保卫杜隆塔尔。他身处荣誉谷的训练师队伍之中，忠于酋长萨尔建立的新国家，也忠于守护其边境的猎人们。",al={"奥玛克所属阵营","奥玛克属于部落还是联盟","奥玛克效忠于谁"}},dac02825={q="奥玛克想要什么？",a="奥玛克希望确保部落的猎人纪律严明、技艺精湛，成为能够在荒野中生存的神射手。他与自己的宠物狼Grimfang并肩行动，致力于磨练优秀斥候的本领，并通过严苛的考验检验他们的应变能力。",al={"奥玛克的目标","奥玛克需要什么","奥玛克·格里姆肖特的目的"}},["88908d62"]={q="奥玛克·奥玛克为何在荣誉谷？",a="奥玛克驻守在奥格瑞玛的荣誉谷，于猎人大厅训练神射手。他身处部落的军事中心，经验丰富的斥候和年轻的学徒都会来此向他学习驯兽和野外生存之道。",al={"奥玛克为何在这里","奥玛克·格里姆肖特为何在此地","奥玛克为何在奥格瑞玛"}}},fp="14,255,18.508.0,22.169.0,32.134.0,27.133.0,39.149.0"}
P.entries["npc:ormer-ironbraid"] = {n="奥莫尔·铁衣",s="奥莫尔·铁衣是一位驻扎在湿地南部的维尔加挖掘场的矮人考古学家。他团队的历史研究因遭到一群贪婪迅猛龙的袭击而被迫中断。奥莫尔正在寻找充满冒险精神的盟友，帮助他清除这些野兽，并为那些被迫离开挖掘场的矿工报仇。",h="奥莫尔·铁衣是一位驻扎在湿地南部的维尔加挖掘场的矮人考古学家。他团队的历史研究因遭到一群贪婪迅猛龙的袭击而被迫中断。奥莫尔正在寻找充满冒险精神的盟友，帮助他清除这些野兽，并为那些被迫离开挖掘场的矿工报仇。",kw={"矮人","挖掘","探险者协会","铁衣","奥莫尔","迅猛龙","湿地","维尔加"},ang={["class:Hunter"]="猎人们会发现奥莫尔的要求非常熟悉，这正好能让他们运用追踪和杀戮野兽的本领，去挑战卡兹莫丹最凶猛的一些迅猛龙。",["faction:Alliance"]="协助奥莫尔不仅能确保湿地南部道路的安全，也能助力铁炉堡至关重要的考古事业。",["race:Dwarf"]="奥莫尔体现了矮人坚韧不拔的精神——绝不向一群长大了的蜥蜴拱手让出祖先的土地。"},sec={{t="挖掘受阻",b="奥莫尔·铁衣来到湿地，是矮人挖掘泰坦遗物和探寻维尔加挖掘场古代历史工作的一部分。不幸的是，在发掘古代石刻时，他们不仅发掘出了文物，还引来了——或者说激怒了——成群凶猛的湿地迅猛龙。奥莫尔现在无心整理古代陶器和石板，每天只能看着这些野兽在废墟中徘徊，心中对这些打断了他们工作的生物充满了愤恨。"},{t="利爪之仇",b="奥莫尔拒绝放弃挖掘工作，但他单枪匹马没有足够的力量清理挖掘场。他将挫败感化作系统性的灭绝行动，雇佣路过的旅行者去猎杀体型越来越大、也越来越凶猛的迅猛龙。对奥莫尔来说，夺回挖掘场不仅仅是为了文物，更是为了矮人的尊严，以及向当地野生生物复仇的私人恩怨。"}},faq={{q="奥莫尔·铁衣是谁？",a="奥莫尔·铁衣是一位负责监督湿地维尔加挖掘场工作的矮人研究员。他代表探险者协会在沼泽中发掘古代遗迹。",al={"谁是奥莫尔","奥莫尔·铁衣","奥莫尔 湿地"}},{q="我能在哪里找到奥莫尔·铁衣？",a="他站在维尔加挖掘场上方的眺望台上，该地点位于湿地南部的悬崖边，就在通往洛克莫丹的主路以东。",al={"奥莫尔 位置","奥莫尔在哪里","寻找奥莫尔·铁衣"}},{q="为什么奥莫尔这么讨厌迅猛龙？",a="当地的迅猛龙群占领了挖掘场，赶走了矮人矿工，使所有的考古工作陷入停滞。奥莫尔将这次干扰视为对他个人的侮辱，并誓要进行全面报复。",al={"为什么是迅猛龙","奥莫尔 迅猛龙","奥莫尔的复仇 背景"}},{q="什么是维尔加挖掘场？",a="这是一个由铁炉堡矮人建立的考古挖掘场，旨在发掘湿地地下的古老泰坦和土灵遗迹。然而，极具攻击性的野生生物将这里变成了一个危险的战场。",al={"维尔加挖掘场","这是什么挖掘场","湿地 挖掘场"}},{q="奥莫尔提供什么任务？",a="奥莫尔提供名为“奥莫尔的复仇”的三阶段任务链，要求冒险者在挖掘场中猎杀体型渐大的迅猛龙。",al={"奥莫尔 任务","挖掘大地","奥莫尔的复仇 任务"}},{q="奥莫尔是探险者协会的成员吗？",a="是的。和卡兹莫丹各地挖掘古代遗迹的许多矮人一样，奥莫尔代表铁炉堡进行考古工作，致力于揭开他们种族的泰坦遗产。",al={"奥莫尔 探险者协会","奥莫尔是考古学家吗"}}},fx={["97454981"]={q="奥莫尔·铁衣站在哪一方？",a="奥莫尔是铁炉堡忠诚的矮人，支持联盟以及在卡兹莫丹各地开展的矮人远征。尽管他眼下的首要任务是在湿地的荒野中求生并守住挖掘场，但他始终坚定地与同族和联盟站在一起。",al={"奥莫尔所属阵营","奥莫尔是联盟成员吗","奥莫尔·铁衣的效忠对象"}},f4da8dc2={q="奥莫尔·铁衣想要什么？",a="奥莫尔只想彻底消灭肆虐维尔加挖掘场的凶猛迅猛龙。这些野兽冲进远征队的挖掘场，赶走了挖掘者。他想向这些野兽复仇，让挖掘场得以收复。",al={"奥莫尔的目标","奥莫尔想要什么","奥莫尔为何复仇"}},["60616fd2"]={q="奥莫尔·铁衣为何在湿地？",a="奥莫尔作为矮人考古远征队的一员来到湿地，队伍驻扎在维尔加挖掘场。然而，他没能安然发掘古代宝藏，反而在当地迅猛龙涌入挖掘场后陷入了残酷的求生之战。",al={"奥莫尔为何在挖掘场","奥莫尔·铁衣在湿地的目的","奥莫尔为何在这里"}}},fp="15,310,14.448.0,24.396.0,23.200.0,33.175.0,36.196.0,34.205.0,29.135.0,47.184.0"}
P.entries["npc:orokk-omosh"] = {n="奥罗克·沃姆什",s="奥罗克·沃姆什是一位年迈的兽人铁匠，驻扎在奥格瑞玛的Valley of Honor。作为传说中铁匠家族的最后一位继承人，他正在部落中寻找有价值的学徒，希望在家族的锻造秘法失传之前将其传承下去。",h="奥罗克·沃姆什是一位年迈的兽人铁匠，驻扎在奥格瑞玛的Valley of Honor。作为传说中铁匠家族的最后一位继承人，他正在部落中寻找有价值的学徒，希望在家族的锻造秘法失传之前将其传承下去。",kw={"野蛮战装","锻造","欢庆之舞","沃姆什","兽人铁匠","奥格瑞玛","奥罗克·沃姆什","valley of honor"},ang={["faction:Horde"]="奥罗克的奉献确保了传统的兽人板甲和锁甲技术得以保留，从而加强了保卫初创部落的战士们的力量。",["profession:Blacksmithing"]="对于有志向的部落锻甲师来说，奥罗克·沃姆什是一位至关重要的导师，他提供专门的图纸和训练，以确保他祖传的手艺能够延续下去。"},sec={{t="血脉的终章",b="站在Valley of Honor轰鸣的熔炉旁，奥罗克·沃姆什肩负着沉重的重担：他是古老的沃姆什家族最后一位铁匠。由于没有后代可以继承他的手艺，奥罗克不愿让家族千辛万苦磨练出的技术随着他一同消亡。相反，他邀请有能力的部落铁匠接受严苛的金属加工试炼，承诺将沃姆什锻甲术的崇高秘密传授给那些证明了自己奉献精神的人。"},{t="熔炉之魂",b="尽管面临血脉断绝的严酷现实，奥罗克在同行中却以他在见到真正的大师级技艺时表现出的热烈欢呼而闻名。完成他的锻造试炼不仅能获得专门的锻甲图纸，往往还会引来著名的“沃姆什欢庆之舞”，这是一种在奥格瑞玛大厅中回响的对传统锻造技艺的欢乐庆典。"}},faq={{q="奥罗克·沃姆什是谁？",a="奥罗克·沃姆什是一位居住在奥格瑞玛Valley of Honor的兽人铁匠大师。他是沃姆什铁匠血脉中最后一位幸存者，整日都在寻找有前途的学徒来继承他家族的冶金知识。",al={"谁是奥罗克","奥罗克·沃姆什背景故事","奥格瑞玛兽人铁匠"}},{q="在哪里可以找到奥罗克·沃姆什？",a="你可以在位于奥格瑞玛东北部的Valley of Honor的打铁炉和铁砧旁找到奥罗克·沃姆什。",al={"奥罗克·沃姆什位置","奥罗克在哪里","找到奥罗克·沃姆什"}},{q="为什么奥罗克·沃姆什要向外人传授家族秘密？",a="奥罗克没有自己的后代来继承家族的手艺。为了不让世代相传的兽人锻甲技术失传，他选择了将技术传授给任何能够达到他高标准要求的熟练部落铁匠。",al={"为什么奥罗克会发布任务","沃姆什的传承","为什么要教铁匠"}},{q="什么是“沃姆什欢庆之舞”？",a="这是一种充满活力的庆祝舞蹈，每当工匠成功证明了自己的价值并掌握了他家族的锻造技艺时，奥罗克就会跳起这种舞。它既是他个人的认可标志，也是对这项工艺的真挚致敬。",al={"欢庆之舞","沃姆什之舞","沃姆什的喜悦"}}},fx={df415c30={q="奥罗克·沃姆什站在哪一方？",a="奥罗克·沃姆什效忠于萨尔的部落。他在奥格瑞玛繁华的中心地带工作，乐于将血脉传承的精湛技艺和古老冶金传统传授给有潜力的部落铁匠。",al={"奥罗克·沃姆什所属阵营","奥罗克·沃姆什效忠于谁","奥罗克·沃姆什是部落成员吗"}},["1085ff21"]={q="奥罗克·沃姆什想要什么？",a="作为古老兽人铁匠世家的最后一位在世成员，且没有自己的子女，奥罗克最渴望的是传承家族的遗产。他正在寻找有能力的铁匠，希望他们值得掌握并传承沃姆什家族的铠甲锻造技艺，以免这些技艺永远失传。",al={"奥罗克·沃姆什想要什么","奥罗克·沃姆什的目标","奥罗克为什么寻找铁匠"}},["5e3af98e"]={q="奥罗克·沃姆什为什么在奥格瑞玛？",a="奥罗克定居在奥格瑞玛的Valley of Honor，那里聚集着部落最优秀的战士、斗士和工匠。对于他希望能传承祖传手艺的强大匠人和尽职的护甲师而言，这里自然是汇聚之地。",al={"奥罗克·沃姆什为什么在奥格瑞玛","奥罗克·沃姆什在此处的原因"}}},fp="11,246,20.450.0,23.384.0,19.252.0,31.134.0,57.237.0,33.233.0"}
P.entries["npc:orphan-matron-battlewail"] = {n="孤儿监护员巴特维尔",s="孤儿监护员巴特维尔负责管理位于奥格瑞玛Valley of Honor的部落孤儿院。她与另一位照料者托萨米娜一起，庇护并抚养着那些在连绵战火中失去家人的兽人幼童。",h="孤儿监护员巴特维尔负责管理位于奥格瑞玛Valley of Honor的部落孤儿院。她与另一位照料者托萨米娜一起，庇护并抚养着那些在连绵战火中失去家人的兽人幼童。",kw={"巴特维尔","儿童周","奥格瑞玛","孤儿监护员巴特维尔","孤儿院","托萨米娜","valley of honor","部落守护者"},ang={["faction:Horde"]="巴特维尔通过为那些在残酷战争现实中幸存下来的孩子们提供指导和庇护，守护着部落的未来。",["race:Orc"]="对于那些努力在杜隆塔尔建立永恒家园的兽人来说，巴特维尔的孤儿院是一座警示丰碑，提醒着他们的人民所承受的牺牲。"},sec={{t="部落之子的照料者",b="战争对艾泽拉斯造成了持续的创伤，而年轻的奥格瑞玛之都正是这些代价的见证者。孤儿监护员巴特维尔悉心照料着那些因暴力而失去亲人的孩子们，确保下一代的部落成员能够得到保护、庇护和培养。巴特维尔在Valley of Honor与托萨米娜并肩工作，并向往来的冒险者敞开孤儿院的大门，特别是在像儿童周这样的节日庆典期间，旅行者们会被邀请来担任这些年轻人的导师。"}},faq={{q="孤儿监护员巴特维尔是谁？",a="她是一位负责管理奥格瑞玛孤儿院的兽人女性，致力于庇护和抚养那些父母在战斗中牺牲的孩子们。",al={"巴特维尔职责","巴特维尔是谁","监护员巴特维尔"}},{q="她在奥格瑞玛的什么地方？",a="巴特维尔和她的同伴托萨米娜在位于奥格瑞玛东部的Valley of Honor照料着孩子们。",al={"巴特维尔位置","孤儿院在哪里","寻找巴特维尔"}},{q="在儿童周期间她扮演什么角色？",a="在儿童周节日期间，巴特维尔会组织导师活动，派遣愿意伸出援手的勇士们带着一名孤儿去领略部落的奇迹与传统。",al={"儿童周巴特维尔","部落守护者","孤儿任务"}},{q="谁在孤儿院协助巴特维尔？",a="托萨米娜与巴特维尔共同生活和工作，协助照看并保护托付给她们的孩子们。",al={"托萨米娜","孤儿监护员助手"}}},fx={["5bd84e8a"]={q="孤儿监护员巴特维尔效忠哪一方？",a="巴特维尔监护员坚定地效忠部落。她以奥格瑞玛为据点，一生致力于抚养阵亡部落战士的子女，确保他们健康成长，得到保护，并为族人的传承感到自豪。",al={"巴特维尔的阵营","巴特维尔是部落吗"}},c46a64f6={q="孤儿监护员巴特维尔想要什么？",a="她的首要目标是确保自己照料的孤儿们安全、安康并得到妥善抚养。尤其是在儿童周期间，她会寻找可靠的冒险者，带孩子们走进外面的世界，让他们见识奥格瑞玛城墙之外的生活。",al={"巴特维尔的目标","孤儿监护员想要什么"}},["8b214374"]={q="孤儿监护员巴特维尔为什么在这里？",a="巴特维尔和同伴托萨米娜一起管理奥格瑞玛Valley of Honor的孤儿院。卡利姆多各地持续不断的冲突让许多兽人孩子失去父母，因此，她慈悲而坚毅的守护对这座城市至关重要。",al={"巴特维尔为什么在奥格瑞玛","巴特维尔为什么在这里"}}},fp="24,224,30.498.0,32.145.0,36.133.0,40.191.0,40.115.0"}
P.entries["npc:orphan-matron-nightingale"] = {n="孤儿监护员奈丁加尔",s="孤儿监护员奈丁加尔负责管理位于Cathedral Square的暴风城孤儿院。她与谢琳监护员一起照顾那些因困扰王国的无休止冲突而失去家人的孩子们。在儿童周期间，她也会招募值得信赖的联盟冒险者来指导并激励她照顾的孩子们。",h="孤儿监护员奈丁加尔负责管理位于Cathedral Square的暴风城孤儿院。她与谢琳监护员一起照顾那些因困扰王国的无休止冲突而失去家人的孩子们。在儿童周期间，她也会招募值得信赖的联盟冒险者来指导并激励她照顾的孩子们。",kw={"cathedral square","儿童周","谢琳监护员","奈丁加尔","孤儿监护员奈丁加尔","暴风城","暴风城孤儿院"},ang={["class:Priest"]="奈丁加尔驻扎在Cathedral of Light外，她的使命体现了圣光教会的牧师们努力秉持的同情心与服务美德。",["faction:Alliance"]="对于联盟勇士而言，奈丁加尔时刻提醒着人们战争带来的无声、日常的代价，以及保护王国未来一代的责任。"},sec={{t="流离失所者的守护者",b="孤儿监护员奈丁加尔伫立在Cathedral of Light东南方的孤儿院外，照料着暴风城中最脆弱的幸存者。近期的战争、豺狼人暴乱以及迪菲亚潜行者的崛起，导致许多孩子无家可归或失去双亲。奈丁加尔和她的同事谢琳监护员在圣光教会的注视下，为这些年轻人提供住所、基本照料和指导。"},{t="儿童周赞助人",b="奈丁加尔监护员相信希望与食物和住所同样重要，因此她组织了暴风城的儿童周庆典。在此期间，她直接请求联盟英雄陪同孤儿游历艾泽拉斯。通过让这些孩子与著名的勇士结伴，她希望以此树立他们的自信，让他们更广阔地了解城墙外的世界，并提醒他们从未被遗忘。"}},faq={{q="孤儿监护员奈丁加尔在哪里？",a="她就站在暴风城孤儿院的入口外，该处位于Cathedral of Light东南方的Cathedral Square。",al={"奈丁加尔监护员的位置","暴风城孤儿院位置","奈丁加尔在哪里"}},{q="为什么暴风城里有这么多孤儿？",a="该王国经历了毁灭性的战争，包括第三次战争，以及与迪菲亚潜行者、兽人残党和附近领地敌对野兽的持续冲突。许多城市居民和边境农夫不幸遇难，留下了无处可去的孩子们。",al={"为什么会有孤儿","暴风城孤儿的由来","这些孩子是谁"}},{q="什么是儿童周？",a="儿童周是由奈丁加尔监护员在暴风城组织的年度活动。联盟冒险者受邀担任孤儿的监护人和向导，带领他们踏上旅程，去见证广阔世界中的奇迹与英雄。",al={"暴风城儿童周","什么是儿童周","孤儿活动"}},{q="谁协助奈丁加尔监护员管理孤儿院？",a="谢琳监护员与奈丁加尔一起在孤儿院内外工作，帮助抚养、喂养并收容她们所照顾的孩子们。",al={"其他孤儿监护员","谁管理孤儿院","谢琳监护员"}}},fx={["9dba66e4"]={q="孤儿监护员奈丁加尔是谁？",a="孤儿监护员奈丁加尔是一位富有同情心的看护者，与谢琳监护员共同管理暴风城孤儿院。她位于Cathedral Square中心，日复一日地庇护和照料那些因威胁王国的连绵战乱与艰难困苦而失去家人的孩子。",al={"奈丁加尔监护员是谁","孤儿监护员奈丁加尔的背景","谁管理暴风城孤儿院"}},e8925ab2={q="孤儿监护员奈丁加尔效忠哪一方？",a="她完全忠于大联盟和暴风城人民。她的职责让她在Cathedral of Light的庇护下工作，不辞辛劳地帮助王国中最脆弱的年轻居民，并依靠联盟英雄丰富孩子们的生活。",al={"奈丁加尔的阵营","奈丁加尔是联盟吗","奈丁加尔监护员的效忠对象"}},["1cac5069"]={q="孤儿监护员奈丁加尔想要什么？",a="她最关心的是自己看护的孤儿们能否安康、快乐地成长。她希望在动荡时期为他们提供一个安全的避风港；即使在儿童周期间，她也会请经验丰富的旅行者带孩子们出行，给他们希望，并让他们一窥城墙外的广阔世界。",al={"奈丁加尔监护员的目标","奈丁加尔想要什么","奈丁加尔的职责"}},e192fa2f={q="孤儿监护员奈丁加尔为什么在这里？",a="她待在Cathedral Square孤儿院台阶外，照看自己负责的孩子并迎接来访者。她从这座城市繁华而神圣的一隅安排孤儿院的日常事务，并寻求愿意帮助孩子们的善心冒险者。",al={"奈丁加尔监护员为什么在cathedral square","奈丁加尔为什么在孤儿院外","奈丁加尔在此处的原因"}}},fp="25,325,25.443.0,22.433.0,45.142.0,43.280.0,24.241.0,47.143.0"}
P.entries["npc:osric-strang"] = {n="奥斯瑞克·斯图恩",s="奥斯瑞克·斯图恩是一位资深的护甲商人，经营着位于暴风城Old Town的“有限防御”商店。他专营重型锁甲和板甲，为联盟的守卫者和途径首都的疲惫旅人们提供坚固的装备和盾牌。",h="奥斯瑞克·斯图恩是一位资深的护甲商人，经营着位于暴风城Old Town的“有限防御”商店。他专营重型锁甲和板甲，为联盟的守卫者和途径首都的疲惫旅人们提供坚固的装备和盾牌。",kw={"邓加·长酒","重型护甲","有限防御","old town","奥斯瑞克·斯图恩","盾牌","暴风城商人"},ang={["class:Warrior"]="奥斯瑞克·斯图恩提供可靠的锁甲、鳞甲、板甲和盾牌，是造访Old Town的战士们获取早期可靠重型防御装备的来源之一。",["faction:Alliance"]="作为暴风城的忠实居民，奥斯瑞克不仅为王国的守卫者装备武装，还协助维护着暴风城与边远定居点之间补给线的信使们。"},sec={{t="“有限防御”店主",b="奥斯瑞克·斯图恩在Old Town饱经风霜的街道一隅经营着“有限防御”，这家店主要为需要重型护甲和盾牌的前线战士提供服务。虽然他的商品适合普通士兵和四处游历的冒险者，但他同时也经常协助那些从西部荒野的哨兵岭等周边定居点来到首都的信使，为他们提供联络点。"}},faq={{q="奥斯瑞克·斯图恩卖什么？",a="奥斯瑞克出售各种重型防护护甲，从强化锁甲、抛光鳞甲到坚固的板甲套装，以及圆盾和塔盾应有尽有。",al={"奥斯瑞克出售物品","奥斯瑞克·斯图恩卖什么","有限防御商品"}},{q="我在哪里可以找到奥斯瑞克·斯图恩？",a="他位于暴风城南部区域附近的Old Town，就在那里的“有限防御”护甲店内。",al={"奥斯瑞克位置","奥斯瑞克·斯图恩在哪里","有限防御位置"}},{q="为什么任务会让我去找奥斯瑞克·斯图恩？",a="负责在王国各地递送货物的信使（例如通过狮鹫管理员从西部荒野运送货物的人），经常会被指引到Old Town的奥斯瑞克店里来完成交付并接收回信。",al={"为什么要找奥斯瑞克","奥斯瑞克·斯图恩任务","交给奥斯瑞克的货物"}}},fx={a4d8c3b8={q="奥斯瑞克·斯图恩是谁？",a="奥斯瑞克·斯图恩是一名护甲商，在暴风城热闹的Old Town经营着一家名为Limited Immunity的商店。他靠为冒险者和城防卫兵提供厚重的锁甲、板甲和坚固的盾牌谋生。",al={"奥斯瑞克是谁","奥斯瑞克·斯图恩的背景","奥斯瑞克·斯图恩的经历"}},["66b236b5"]={q="奥斯瑞克·斯图恩效忠哪一方？",a="奥斯瑞克·斯图恩是暴风王国的忠诚公民，坚定地站在联盟一方，骄傲地为守卫王国的人们提供防护装备。",al={"奥斯瑞克·斯图恩的阵营","奥斯瑞克·斯图恩效忠哪方","奥斯瑞克是联盟吗"}},["9aee9a9e"]={q="奥斯瑞克·斯图恩为什么在暴风城？",a="奥斯瑞克·斯图恩在Old Town中心经营Limited Immunity。这个城区以经验丰富的战士、工匠和军械库闻名。暴风城为他带来了源源不断的招募兵员、旅行者和守卫者，他们都在寻找可靠的重型护甲。",al={"奥斯瑞克·斯图恩为什么在这里","奥斯瑞克·斯图恩的商店","奥斯瑞克·斯图恩与limited immunity"}}},fp="12,257,30.385.0,28.157.0,30.107.0,41.205.0"}
P.entries["npc:overlord-mok-morokk"] = {n="莫格穆洛克大王",s="莫格穆洛克大王是石槌食人魔中野蛮的首领，坐镇在尘泥沼泽的蕨墙村。他最初因力量出众被雷克萨委以重任，如今却变成了一位残暴又懦弱的统治者，拒绝保护自己的族人对抗黑龙军团。",h="莫格穆洛克大王是石槌食人魔中野蛮的首领，坐镇在尘泥沼泽的蕨墙村。他最初因力量出众被雷克萨委以重任，如今却变成了一位残暴又懦弱的统治者，拒绝保护自己的族人对抗黑龙军团。",kw={"蕨墙村","德拉兹辛比","尘泥沼泽","莫格穆洛克","食人魔","大王","雷克萨","石槌"},ang={["class:Warrior"]="莫格穆洛克是那种缺乏荣誉感或勇气、仅凭蛮力的典型案例，这证明了纯粹的暴力是多么容易退化为懦弱与暴政。",["faction:Horde"]="自从雷克萨的战役以来，石槌食人魔就是效忠于部落的宝贵盟友，但莫格穆洛克无能而懦弱的领导，使蕨墙村面临着彻底陷入危机的风险。"},sec={{t="沼泽中的暴君",b="当雷克萨击败了前任首领科尔加，并带领石槌氏族保卫杜隆塔尔时，他将指挥权留给了莫格穆洛克，因为他看中了其纯粹的武力潜能。但这份信任错付了。莫格穆洛克很快沉溺于绝对权力带来的腐化影响，他通过恐吓和放纵来统治，而非通过管理。他不关心族人，只是一味索取不应得的贡品，终日窝在蕨墙村里，欺凌任何质疑他命令的人。"},{t="蕨墙村的懦夫",b="当黑龙军团降临石槌村的祖地，屠杀了许多食人魔并将幸存者驱赶至蕨墙村的淤泥地时，莫格穆洛克的领导威信彻底瓦解。莫格穆洛克不仅没有组织反击以夺回领地或为死者复仇，反而禁止任何人采取行动，在巨龙的怒火面前畏缩不前。他的顾问们（如食人魔术士德拉兹辛比）对此心怀不满，他们正悄悄寻找愿意挑战这位大王可耻统治的外部勇士。"}},faq={{q="莫格穆洛克大王是谁？",a="莫格穆洛克是石槌食人魔的首领，目前居住在尘泥沼泽的蕨墙村。他是由雷克萨指定的领导者，但很快就堕落成了一个自私且贪婪的暴君。",al={"谁是莫格穆洛克","蕨墙村首领","石槌食人魔头目"}},{q="莫格穆洛克是如何成为石槌氏族首领的？",a="在杜隆塔尔建立期间，部落勇士雷克萨击败了该氏族的前任首领并接管了石槌氏族。当雷克萨离开去荒野中流浪时，由于莫格穆洛克拥有强大的蛮力，他任命其为大王。",al={"莫格穆洛克如何掌权","雷克萨选择了莫格穆洛克","他为何是首领"}},{q="石槌食人魔为什么会在蕨墙村？",a="石槌食人魔最初居住在石槌村，但黑龙袭击并夷平了他们的定居点。幸存者们向北逃入沼泽，建立了蕨墙村作为避难的前哨站。",al={"食人魔为何迁往蕨墙村","石槌村发生了什么","黑龙袭击食人魔"}},{q="莫格穆洛克为什么不与黑龙军团作战？",a="尽管莫格穆洛克体型庞大且名声凶猛，但他非常惧怕巨龙。他没有领导反击以夺回氏族的祖地，而是整天在蕨墙村无所事事，囤积贡品，无视族人的呼声。",al={"莫格穆洛克为何不对抗巨龙","莫格穆洛克是个懦夫吗","收复石槌村"}},{q="其他石槌食人魔尊敬莫格穆洛克吗？",a="氏族成员对他懒惰、懦弱和欺凌他人的行为感到越来越不满。他的顾问们很担心在莫格穆洛克的统治下，石槌氏族的未来将会如何。",al={"食人魔喜欢莫格穆洛克吗","德拉兹辛比与莫格穆洛克","石槌氏族起义"}}},fp="19,280,21.497.0,25.495.1,27.205.0,55.258.0,51.209.0,50.250.0,48.148.1"}
P.entries["npc:overlord-ramtusk"] = {n="主宰拉姆塔斯",s="主宰拉姆塔斯是一位魁梧的野猪人督军，统领着剃刀沼泽深处的战士。他高呼着胜利与阿迦玛甘之名，身先士卒地率领他的精英卫队冲锋陷阵。击败他将彻底摧毁剃刀沼泽守军的武力中枢。",h="主宰拉姆塔斯是一位魁梧的野猪人督军，统领着剃刀沼泽深处的战士。他高呼着胜利与阿迦玛甘之名，身先士卒地率领他的精英卫队冲锋陷阵。击败他将彻底摧毁剃刀沼泽守军的武力中枢。",kw={"贫瘠之地","死亡之颅","主宰拉姆塔斯","野猪人","拉姆塔斯","剃刀沼泽"},ang={["class:Warrior"]="拉姆塔斯代表着纯粹、野蛮的武力老兵，他依靠雷霆万钧的打击和指挥战吼，而非萨满的地理魔法或荆棘魔法。",["race:Orc"]="自从杜隆塔尔和贫瘠之地的哨所建立以来，野猪人就一直在积极袭击部落的定居点。摧毁拉姆塔斯的军事指挥权有助于保障南贫瘠之地的安全。",["race:Tauren"]="几代以来，贫瘠之地的游牧部落一直与剃刀沼泽的野猪人进行着激烈的冲突；击败他可以告慰阵亡的勇士。"},sec={{t="沼泽督军",b="主宰拉姆塔斯坐镇在剃刀沼泽——这处位于南贫瘠之地的野猪人要塞——的棘刺迷宫深处，指挥着这里的一切。他作战时会向野猪半神阿迦玛甘发出战吼，以不可动摇的权威统治着沼泽中的战士。"},{t="沼泽指挥官",b="在剃刀沼泽盘根错节的荆棘中，拉姆塔斯指挥着野猪人战士。作为他们的督军，他在保卫部落圣地的鬃毛战士中维持着铁腕纪律。拉姆塔斯在精英射手的簇拥下，如同前线的狂战士一般冲锋陷阵，他那振奋人心的战吼和能瞬间击溃敌方防线的震地重击令人胆寒。"}},faq={{q="主宰拉姆塔斯是谁？",a="主宰拉姆塔斯是一位统领剃刀沼泽深处战士的野猪人督军。他是一位体格魁梧、气势逼人的战士，作战时会高呼着为了胜利和阿迦玛甘的口号。",al={"拉姆塔斯是谁","拉姆塔斯背景故事","主宰拉姆塔斯"}},{q="主宰拉姆塔斯在哪里？",a="他坐镇于南贫瘠之地南端的剃刀沼泽的棘刺核心，指挥着他的精英卫队。",al={"拉姆塔斯位置","拉姆塔斯在哪","主宰拉姆塔斯地图"}},{q="拉姆塔斯过去与哪些敌人交战过？",a="没有关于他过去战役的记录。在剃刀沼泽中，他身先士卒，率领精英卫队，高呼着胜利与阿迦玛甘之名，迎战任何闯入荆棘丛的入侵者。",al={"拉姆塔斯的敌人","谁留给拉姆塔斯伤疤","拉姆塔斯的战斗历史"}},{q="拉姆塔斯属于哪个部族？",a="他是剃刀沼泽的野猪人之一，他们占据了南贫瘠之地内长满荆棘的要塞剃刀沼泽，并崇拜着野猪半神阿迦玛甘。",al={"拉姆塔斯的派系","拉姆塔斯的部族","拉姆塔斯是什么野猪人部族"}},{q="为什么冒险者要针对拉姆塔斯？",a="作为统领剃刀沼泽战士的督军，拉姆塔斯的死将重创野猪人的军事指挥链，使其防御阵线陷入彻底的混乱。",al={"为什么要杀拉姆塔斯","消灭他们任务","拉姆塔斯的悬赏"}},{q="拉姆塔斯如何战斗？",a="拉姆塔斯是一位久经沙场的传统战士，擅长利用挫志怒吼来激励部下，用毁灭性的震荡波击晕敌人，并与身旁的精英远程卫队协同作战。",al={"拉姆塔斯的战术","拉姆塔斯的战斗风格","拉姆塔斯的能力"}}},fx={["26eecf20"]={q="主宰拉姆塔斯效忠哪一方？",a="主宰拉姆塔斯是剃刀沼泽野猪人的一名军阀。他效命于盘踞在荆棘迷宫中的部族，率领战士守卫祖传的荆棘丛，并指挥他们攻击侵入领地的外来者。",al={"拉姆塔斯效命于谁","拉姆塔斯的阵营","拉姆塔斯效忠哪方"}},a2bf0d01={q="主宰拉姆塔斯为什么在剃刀沼泽？",a="拉姆塔斯负责统领剃刀沼泽的防务和军事秩序。作为剃刀沼泽战士的主宰，他从荆棘丛深处指挥部队，协调族中战士守护剃刀沼泽的核心区域，抵御入侵之敌。",al={"拉姆塔斯为什么在这里","拉姆塔斯在剃刀沼泽做什么","拉姆塔斯的职责"}},b0113e9e={q="主宰拉姆塔斯为何令人畏惧？",a="主宰拉姆塔斯是一名体型庞大的野猪人军阀，常率领精锐护卫冲锋陷阵，高呼胜利与阿迦玛甘之名。他凭借势大力沉的攻击和振奋人心的战吼统领剃刀沼泽的战士，让所有胆敢挑战他的人心生恐惧。",al={"拉姆塔斯为何令人畏惧","拉姆塔斯有多强","拉姆塔斯的名声"}}},fp="16,260,20.253.0,22.370.0,24.185.0,36.120.0,44.176.0,34.146.0,39.173.0,23.192.0"}
P.entries["npc:ozzie-togglevolt"] = {n="奥齐·电环",s="奥齐·电环是一位侏儒工程师，也是诺莫瑞根沦陷的幸存者，目前在丹莫罗的雪村卡拉诺斯开展工作。饱受族人遭遇的悲剧所折磨，他与搭档拉兹·滑链并肩工作，致力于为受到辐射的麻风侏儒研究治疗方法。",h="奥齐·电环是一位侏儒工程师，也是诺莫瑞根沦陷的幸存者，目前在丹莫罗的雪村卡拉诺斯开展工作。饱受族人遭遇的悲剧所折磨，他与搭档拉兹·滑链并肩工作，致力于为受到辐射的麻风侏儒研究治疗方法。",kw={"丹莫罗","诺恩","诺莫瑞根","卡拉诺斯","麻风侏儒","奥齐","辐射","拉兹","滑链","电环"},ang={["faction:Alliance"]="奥齐驻扎在铁炉堡外的卡拉诺斯，在协助旅行者的同时，也维持着联盟在丹莫罗寒冷群山中的立足点。",["profession:Engineering"]="奥齐展示了侏儒工艺在反复试验中的现实，在这种工艺下，装置在战斗中可能会产生剧烈的反作用，但也可能在生化去污方面取得巧妙的突破。",["race:Gnome"]="对于侏儒冒险者来说，奥齐代表了诺莫瑞根幸存者的悲伤与决心，他们拒绝放弃那些受辐射的族人，任由其自生自灭。"},sec={{t="深处逃生",b="当灾难降临时，奥齐·电环正身处诺莫瑞根的地底奇迹之中。为了阻挡穴居怪的入侵，有毒的辐射尘埃在走廊中四处弥漫，当时奥齐正站在他的侏儒同伴诺恩身边。突如其来的放射性喷发直接击中了诺恩，在奥齐眼前永远地改变了他。虽然奥齐活着逃到了地面，并抵达了丹莫罗的避风港，但那场灾难的可怕记忆却始终挥之不去。"},{t="卡拉诺斯工作室",b="如今定居在卡拉诺斯，奥齐每天都与拉兹·滑链一起进行修理和发明工作。他们主要的科技和科学研究工作始终有着极其私人的目标：寻找一种方法来逆转家园沦陷后可怕的诱变辐射，并治愈那些受苦的麻风侏儒。"}},faq={{q="奥齐·电环是谁？",a="奥齐·电环是一位居住在丹莫罗卡拉诺斯的侏儒工程师。他从诺莫瑞根的放射性灾难中逃生，现在致力于利用他的技术专长，为受到折磨的同胞寻找解药。",al={"奥齐是谁","奥齐·电环背景故事","卡拉诺斯侏儒奥齐"}},{q="奥齐试图治愈什么？",a="奥齐和他的同事拉兹·滑链正在研究一种方法，来净化那些导致他们许多族人变成陷入疯狂的麻风侏儒的有毒辐射。",al={"奥齐在研究什么","奥齐麻风侏儒解药","麻风侏儒解药"}},{q="诺恩对奥齐来说是谁？",a="当毒气泄露时，诺恩正与奥齐一同身处诺莫瑞根。奥齐亲眼目睹了一道放射性射线直接击中了诺恩，这一悲剧促使奥齐执着于逆转这种污染。",al={"奥齐与诺恩","诺恩发生了什么","诺恩是谁"}},{q="谁在卡拉诺斯与奥齐一起工作？",a="奥齐与拉兹·滑链一起工作。他们一同在卡拉诺斯进行修理发明，研制药剂并收集受污染的野外样本，以分析放射性尘埃。",al={"奥齐的搭档","拉兹是谁","拉兹·滑链"}},{q="奥齐提供哪些任务？",a="奥齐招募在丹莫罗的旅行者收集诺莫瑞根周围的辐射残渣和组件，任务包括“灾后余生”、“诺莫甘药剂”和“唯一的解药就是更多的绿光”。",al={"奥齐的任务","电环的任务","奥齐提供什么任务"}}},fx={["86f7524c"]={q="奥齐·电环效忠哪一方？",a="奥齐坚定地支持诺莫瑞根流亡者和联盟。和许多从诺莫瑞根惨烈陷落中幸存的人一样，他在丹莫罗的矮人中避难，一心用自己的智慧和技能帮助流离失所的侏儒同胞。",al={"奥齐·电环的阵营","奥齐·电环属于联盟还是部落","奥齐·电环效命于谁"}},["3c84fab0"]={q="奥齐·电环为什么在丹莫罗？",a="诺莫瑞根遭受悲惨污染后，奥齐逃到了卡拉诺斯。他躲过了导致许多同胞遭受腐化的致命辐射，随后与其他机械师一起开店，在离污染影响区足够近的地方建立了安全据点，以便研究辐射后果并帮助幸存者。",al={"奥齐·电环为什么在卡拉诺斯","奥齐为什么在这里","奥齐·电环在此处的原因"}}},fp="16,295,20.460.0,21.283.0,24.216.0,29.170.0,23.212.0,38.179.0,29.196.0"}
P.entries["npc:pao-ka-swiftmountain"] = {n="波卡·雨山",s="波卡·雨山是一位年轻的牛头人自然学家，受困于千针石林的风巢，周围尽是凶猛的翼手龙。在莫特加·火鬃的指引下，他一路南下。然而，他那年少轻狂的好奇心让他付出了代价，在过于靠近一处巢穴后，他被逼入了悬崖绝境。",h="波卡·雨山是一位年轻的牛头人自然学家，受困于千针石林的风巢，周围尽是凶猛的翼手龙。在莫特加·火鬃的指引下，他一路南下。然而，他那年少轻狂的好奇心让他付出了代价，在过于靠近一处巢穴后，他被逼入了悬崖绝境。",kw={"风巢","回家","莫特加·火鬃","波卡·雨山","千针石林","白沙岗哨","翼手龙"},ang={["faction:Horde"]="波卡代表了探索卡利姆多的下一代牛头人学者；确保他的安全有助于维持与白沙岗哨长者们之间的紧密联系。",["race:Tauren"]="翼手龙被牛头人视为盟友和忠诚的坐骑，深受敬重，因此波卡这种缺乏计划的入侵行为不仅危险，而且令人尴尬。"},sec={{t="困境中的自然学家",b="波卡随莫特加·火鬃一起来到了千针石林的峡谷地带，渴望对峡谷中危险的野兽进行编目和研究。他的父亲本不想让他踏上如此危险的旅程，而波卡最近的这次意外证明了这种担心并非多余。年轻的学者被栖息在风巢的壮丽翼手龙所吸引，他悄悄溜到了一根孤零零的牛头人图腾后方的山路。不出所料，领地意识极强的野兽对他这种入侵行为感到愤怒，将他驱赶到悬崖深处，使他陷入了惊恐与困境，无法绕过那些俯冲的掠食者回到白沙岗哨。"}},faq={{q="波卡·雨山是谁？",a="波卡是一位年轻的牛头人学者，他随莫特加·火鬃前往千针石林研究当地的野生动物，却因翼手龙的领地意识而被困在风巢。",al={"波卡是谁","波卡·雨山","风巢的牛头人是谁"}},{q="波卡·雨山在哪里？",a="他被困在千针石林的风巢顶端。要找到他，必须先找到悬崖边上一根高耸的牛头人图腾，图腾后面有一条狭窄的小径可以通往山坡上的翼手龙栖息地。",al={"波卡在哪里","风巢路线","如何找到波卡"}},{q="他为什么躲在风巢？",a="他对翼手龙的着迷使他过于靠近它们的巢穴。愤怒的野兽将他驱赶开并切断了他的退路，迫使他躲藏了数日。",al={"波卡为何被困","翼手龙为何攻击波卡"}},{q="在他逃脱后会发生什么？",a="在被护送出巢穴地带后，波卡会逃回白沙岗哨找莫特加·火鬃，并绝望地祈求导师不要将这次愚蠢的错误告诉他的父亲。",al={"回家任务的结果","波卡成功回去了吗"}}},fx={["3733bdd0"]={q="波卡·雨山效忠哪一方？",a="波卡属于部落。他是一名年轻的牛头人博学者，在族中长老的指引下进入峡谷，并依靠部落勇士帮助自己应对千针石林的危险。",al={"波卡·雨山的阵营","波卡是部落吗","波卡·雨山属于哪一方"}},ca840f79={q="波卡·雨山想要什么？",a="波卡想要有人护送他安全离开风巢，回到白沙岗哨，免受导师的责罚。他满怀热情地爬上峭壁，想要研究野生双足飞龙；但惊扰巢穴后，他被追得躲藏起来，如今只想保住性命逃出去，并避免蒙羞地被送回父亲身边。",al={"波卡的目标","波卡想要什么","波卡·雨山的动机"}},["29fbd111"]={q="波卡·雨山与谁有关联？",a="波卡师从白沙岗哨的莫特加·火鬃。莫特加说服了波卡那位犹豫不决的父亲，让他同意孩子外出荒野研究当地野兽。波卡害怕让莫特加失望，也害怕自己无法完成远征，从而证明保护欲强烈的父亲是对的。",al={"波卡·雨山的人际关系","波卡认识谁","波卡的导师"}}},fp="20,303,23.650.0,28.172.0,40.202.0,30.169.0,39.178.1"}
P.entries["npc:parqual-fintallas"] = {n="帕科瓦·芬塔拉斯",s="帕科瓦·芬塔拉斯是一位被遗忘者学者，也是前洛丹伦的人类历史学家，目前居住在幽暗城的Apothecarium。尽管亡灵生活的环境阴森恐怖，他仍保持着礼貌的举止和对古代知识的热情，经常帮助前来咨询他深厚历史造诣的旅行者。",h="帕科瓦·芬塔拉斯是一位被遗忘者学者，也是前洛丹伦的人类历史学家，目前居住在幽暗城的Apothecarium。尽管亡灵生活的环境阴森恐怖，他仍保持着礼貌的举止和对古代知识的热情，经常帮助前来咨询他深厚历史造诣的旅行者。",kw={"apothecarium","芬塔拉斯","历史学家","洛丹伦","帕科瓦","学者","博学试炼","幽暗城"},ang={["faction:Horde"]="当部落冒险者面对心智而非刀剑的考验时，帕科瓦会提供揭开艾泽拉斯古代真相所需的深厚历史智慧。",["race:Undead"]="帕科瓦是一个难得的提醒，让人想起洛丹伦王国曾经的知识底蕴；在Apothecarium的荒凉之中，他静静地坚守着学术和文明的交流。"},sec={{t="失落洛丹伦的学者",b="在生前，帕科瓦是一位受人尊敬的洛丹伦人类学者，对这个王国的一切了如指掌，沉浸在历史文献之中。当亡灵天灾降临时，帕科瓦是众多被杀害并复活的公民之一，但最终在Sylvanas Windrunner的领导下挣脱了控制。虽然被遗忘者大都信奉冷酷的实用主义并背离了他们曾经的生活，但帕科瓦依然保留着他的学术热情和优雅举止，继续寻求启迪，尽管这种启迪与生前有所不同。"},{t="古代知识的守护者",b="帕科瓦居住在幽暗城Apothecarium里沸腾的药剂缸和炼金术士之间。尽管环境令人毛骨悚然，他仍然是关于艾泽拉斯历史的无价知识源泉。当冒险者进行严苛的智力考验（例如难以捉摸的“博学试炼”）时，他们会被指引去找帕科瓦，帕科瓦会让他们去血色修道院的图书馆找一本书，然后向他们提出一个自己的问题。"}},faq={{q="我在哪里可以找到帕科瓦·芬塔拉斯？",a="帕科瓦·芬塔拉斯位于幽暗城的Apothecarium内，幽暗城是被遗忘者的主城，位于洛丹伦废墟之下。",al={"帕科瓦·芬塔拉斯位置","帕科瓦在哪里","帕科瓦 幽暗城"}},{q="帕科瓦·芬塔拉斯以什么闻名？",a="帕科瓦生前是一位成就卓著的历史学家，几乎了解关于洛丹伦王国的一切。即使在成为亡灵后，他依然是学术界的权威，帮助冒险者寻找晦涩的历史文献和古代知识。",al={"帕科瓦是谁","帕科瓦做什么","帕科瓦·芬塔拉斯背景故事"}},{q="为什么帕科瓦会参与博学试炼？",a="博学试炼要求冒险者既要展示力量，也要展示知识。由于他的学术背景，帕科瓦设置了其中一项考验：他让冒险者去血色修道院寻找《亡灵的起源》这本书，然后就此向他们提问。",al={"帕科瓦 博学试炼","博学试炼 幽暗城","帕科瓦·芬塔拉斯任务"}},{q="帕科瓦和大多数被遗忘者一样怀有敌意吗？",a="在日常交谈中他很友好，并表示有人花时间与他交谈是件多么美好的事。但他会对那些声称通过了布劳格·幽魂考验的人保持高度怀疑，并且对血色十字军只有蔑视。",al={"帕科瓦友好吗","帕科瓦性格"}}},fx={["8cab13a3"]={q="帕科瓦·芬塔拉斯是谁？",a="帕科瓦·芬塔拉斯曾是一位声名卓著的人类历史学家，对洛丹伦王国的一切了如指掌。他被瘟疫侵袭，死后化为亡灵，如今居住在幽暗城的Apothecarium，与被遗忘者为伍。尽管身为亡灵，他仍对历史知识、典籍和静心治学怀有深厚热情。",al={"帕科瓦是谁","帕科瓦·芬塔拉斯","芬塔拉斯是谁"}},d8934933={q="帕科瓦·芬塔拉斯效忠于哪一方？",a="帕科瓦支持被遗忘者和部落，平静地居住在幽暗城。与许多心怀怨恨的同族不同，他对旅行者几乎没有敌意，也乐于与寻求知识的部落旅人分享自己的历史专长。",al={"帕科瓦为谁效力","帕科瓦的阵营","帕科瓦是部落的吗"}},["5af35229"]={q="帕科瓦·芬塔拉斯想要什么？",a="帕科瓦希望保存洛丹伦的历史，并在亡灵之身继续治学；对他而言，知识远比力量重要。前来寻求失落记录和历史智慧的人，他都会欣然相助，不过他会先让他们去血色修道院找回《亡灵的起源》等珍贵书籍。",al={"帕科瓦想要什么","帕科瓦·芬塔拉斯的目标","帕科瓦的动机"}},["03c3b7bf"]={q="帕科瓦·芬塔拉斯为什么在Apothecarium？",a="帕科瓦以幽暗城的Apothecarium为家，周围都是研究者和学者。尽管身处阴暗的炼金术研究之中，他仍利用城中僻静的角落研究并保存历史记录，为探寻失落知识的人提供帮助。",al={"帕科瓦为什么在这里","帕科瓦为什么在幽暗城","帕科瓦在apothecarium做什么"}}},fp="17,331,25.518.0,22.428.0,35.155.0,36.257.0,44.273.0,57.259.0"}
P.entries["npc:pelturas-whitemoon"] = {n="皮尔图拉斯·怀特姆恩",s="皮尔图拉斯·怀特姆恩是一位居住在阿斯特兰纳的暗夜精灵父亲，他年幼的女儿蕾拉拉患上了一种可怕的、具有腐蚀性的疾病。为了拯救女儿，他急切地与当地的草药师奥雷迪尔·阔叶以及路过的联盟勇士密切合作，从周围的荒野中收集神圣的药剂。他为了治愈蕾拉拉而展开的旅程，带领着冒险者们深入了灰谷一些最古老的神圣树林和废墟之中。",h="皮尔图拉斯·怀特姆恩是一位居住在阿斯特兰纳的暗夜精灵父亲，他年幼的女儿蕾拉拉患上了一种可怕的、具有腐蚀性的疾病。为了拯救女儿，他急切地与当地的草药师奥雷迪尔·阔叶以及路过的联盟勇士密切合作，从周围的荒野中收集神圣的药剂。...",kw={"灰谷","阿斯特兰纳","月神之泪","坠星湖","月光石","奥雷迪尔·阔叶","皮尔图拉斯","蕾拉拉","星尘废墟","怀特姆恩"},ang={["class:Priest"]="致力于艾露恩的净化仪式和圣洁试剂，展现了艾露恩姐妹会为暗夜精灵文化所带来的治愈力量与神圣敬意。",["faction:Alliance"]="帮助皮尔图拉斯拯救他的女儿，加强了联盟对保卫和援助卡利姆多卡多雷定居点的承诺。",["profession:Herbalism"]="蕾拉拉所需要的天然汤剂、敷剂和植物酊剂系列，突显了卡多雷医学与草药知识之间的深厚联系。",["race:NightElf"]="皮尔图拉斯的挣扎反映了当古老的林地遭受腐蚀和地区冲突的侵害时，普通卡多雷家庭的脆弱性。"},sec={{t="阿斯特兰纳的一位父亲的困境",b="皮尔图拉斯·怀特姆恩居住在阿斯特兰纳宁静的枝叶间，过着典型的森林居住者卡多雷那样的宁静生活。他过去常带着年幼的女儿蕾拉拉去坠星湖周围收集闪烁的月光石。然而，当蕾拉拉患上一种神秘的重病后，他平静的世界瞬间崩塌，陷入了狂乱的绝望之中。阿斯特兰纳在多条战线上都遭受着围困，但对皮尔图拉斯来说，在这片大森林里，没有什么比拯救他的孩子更重要了。"},{t="古老的疗法与受腐蚀的树林",b="普通的草药疗法无法缓解蕾拉拉的病情，这促使皮尔图拉斯向草药师奥雷迪尔·阔叶求助。治疗这种顽疾需要与这片土地和月之女神相关的稀有神圣试剂，包括一枚月神之泪以及来自古老卡多雷遗迹的闪烁星尘，以降低她灼热的体温。每一步都只能勉强从死神手中抢回一线生机，这凸显出蔓延在灰谷土壤和水域中的腐蚀已经开始深深影响当地居民。"},{t="坠星湖",b="为了全面恢复蕾拉拉的活力，皮尔图拉斯从坠星湖的影棘神谕者那里寻找一枚月光石。坠星湖曾经是父女俩平静地收集石头的安宁之地，但由于受到腐蚀的沼泽野兽的暴力侵扰，这里变得危机四伏。皮尔图拉斯将找回的月光石研磨成恢复活力的药茶，终于打破了持续的虚弱状态，让蕾拉拉恢复了健康。"}},faq={{q="皮尔图拉斯·怀特姆恩是谁？",a="皮尔图拉斯·怀特姆恩是一位居住在灰谷中部阿斯特兰纳的暗夜精灵。他最著名的事迹是请求过往的联盟旅行者协助收集神圣的材料，以治愈他病重的女儿蕾拉拉。",al={"皮尔图拉斯","皮尔图拉斯·怀特姆恩是谁","皮尔图拉斯 阿斯特兰纳"}},{q="他的女儿蕾拉拉得了什么病？",a="蕾拉拉患上了一种突发的、恶性的疾病，导致严重的发烧和极度虚弱。这种疾病似乎与蔓延在灰谷荒野中的非自然腐蚀有关，普通的药物对它无效，必须使用神圣的试剂才能净化。",al={"蕾拉拉疾病","为什么蕾拉拉生病","蕾拉拉病情"}},{q="是谁帮助皮尔图拉斯治疗这种疾病？",a="皮尔图拉斯寻求了奥雷迪尔·阔叶的建议，他是一位博学的当地暗夜精灵，负责开具传统的卡多雷药方，包括净化石和草药敷剂。",al={"皮尔图拉斯 草药师","谁帮助蕾拉拉","奥雷迪尔·阔叶 皮尔图拉斯"}},{q="治愈蕾拉拉需要什么试剂？",a="拯救蕾拉拉需要一系列的治疗过程：首先是奥雷迪尔提供的草药汤剂，接着是净化的月神之泪，来自古老遗迹的磨碎星尘以打破她灼热的发烧，最后是来自坠星湖的、冲泡成茶的月光石，以恢复她的元气。",al={"治疗试剂 皮尔图拉斯","蕾拉拉治疗成分","什么能治愈蕾拉拉"}},{q="为什么坠星湖对皮尔图拉斯很重要？",a="坠星湖曾是皮尔图拉斯和蕾拉拉一起收集月光石的地方。最近，湖泊被敌对的影棘沼泽野兽占据，迫使皮尔图拉斯请求冒险者找回他女儿康复所需的月光石。",al={"坠星湖 皮尔图拉斯","月光石 坠星湖"}},{q="皮尔图拉斯是塞纳里奥议会或哨兵部队的成员吗？",a="不，皮尔图拉斯是阿斯特兰纳的一名普通平民居民，代表了居住在灰谷并遭受森林日益增长的危险所威胁的普通卡多雷家庭。",al={"皮尔图拉斯是哨兵吗","皮尔图拉斯 阵营身份"}}},fx={["6580d64d"]={q="皮尔图拉斯·怀特姆恩效忠于哪一方？",a="皮尔图拉斯忠于达纳苏斯的暗夜精灵，坚定地支持联盟。他住在阿斯特兰纳，依靠其他卡多雷的保护；在家人危难之际，任何愿意伸出援手的联盟旅人都会受到他的欢迎。",al={"皮尔图拉斯·怀特姆恩的阵营","皮尔图拉斯是联盟的吗","皮尔图拉斯效忠哪一方"}},["806ac345"]={q="皮尔图拉斯·怀特姆恩想要什么？",a="皮尔图拉斯最想做的，就是救治他心爱的女儿蕾拉拉，让她摆脱那种神秘疾病。他急切地搜集强效的疗愈材料——从圣洁的泪水到古老的星尘——希望调制出药剂，彻底退去她的热病，让她恢复活力。",al={"皮尔图拉斯想要什么","皮尔图拉斯·怀特姆恩的目标","皮尔图拉斯想做什么"}},["8d08bbb7"]={q="皮尔图拉斯·怀特姆恩为什么在阿斯特兰纳？",a="皮尔图拉斯以阿斯特兰纳为家，这里是灰谷暗夜精灵聚居地的中心。过去，他曾和女儿一起漫步于附近的森林和坠星湖等湖岸，如今为了照料病情日益恶化的女儿，他只能留在镇中寻求安全。",al={"皮尔图拉斯为什么在阿斯特兰纳","皮尔图拉斯为什么在这里","皮尔图拉斯住在哪里"}},["3f413488"]={q="皮尔图拉斯·怀特姆恩与谁关系密切？",a="皮尔图拉斯的生活围绕着年幼的女儿蕾拉拉展开，他正不懈地保护她。为了治好女儿，他与当地擅长药疗的暗夜精灵奥雷迪尔·阔叶密切合作，后者为他指引可能的疗法。",al={"皮尔图拉斯·怀特姆恩的家人","皮尔图拉斯和谁有亲缘关系","皮尔图拉斯的女儿"}}},fp="18,409,30.472.0,34.481.1,15.414.1,26.217.0,40.252.0,38.173.0,40.257.0,47.274.0,61.174.0"}
P.entries["npc:pilot-bellowfiz"] = {n="驾驶员贝隆·风箱",s="驾驶员贝隆·风箱，常被亲切地称为“费兹”，是一位驻扎在丹莫罗钢架补给站的矮人驾驶员。作为铁炉堡攻城旅的一员，他负责维护并部署矮人的重型战争机器，特别是他自己的攻城坦克——“喷气蒸汽号”。",h="驾驶员贝隆·风箱，常被亲切地称为“费兹”，是一位驻扎在丹莫罗钢架补给站的矮人驾驶员。作为铁炉堡攻城旅的一员，他负责维护并部署矮人的重型战争机器，特别是他自己的攻城坦克——“喷气蒸汽号”。",kw={"贝隆·风箱","丹莫罗","费兹","喷气蒸汽号","驾驶员贝隆·风箱","驾驶员迪恩·石轮","攻城旅","钢架补给站"},ang={["profession:Engineering"]="对于矮人和侏儒技师来说，贝隆·风箱代表了实用现场工程学的巅峰——即在寒冷的山区气候中保持高功率攻城坦克的正常运转。",["race:Dwarf"]="贝隆·风箱体现了铁炉堡机械化旅的骄傲，展示了捍卫卡兹莫丹所需的工程实力和重型火力。"},sec={{t="喷气蒸汽号的大师",b="驾驶员贝隆·风箱驻扎在铁炉堡繁华大厅外的钢架补给站，他是矮人军队机械骨干的代表。他驾驶着那台名为“喷气蒸汽号”的强力攻城坦克，每天的时间都花在调试零件、采购重要配件以及保持车辆的战斗状态上。他与战友驾驶员迪恩·石轮经常讨论车辆设计、装甲板和发动机输出等问题，确保王国山脉的机械火力在整个卡兹莫丹保持无可匹敌的优势。"}},faq={{q="驾驶员贝隆·风箱是谁？",a="驾驶员贝隆·风箱是在铁炉堡攻城旅服役的一名矮人飞行员。他位于丹莫罗的钢架补给站，维护并操纵重型攻城坦克以保卫卡兹莫丹。",al={"驾驶员贝隆·风箱","费兹","费兹是谁"}},{q="贝隆·风箱驾驶什么机器？",a="他驾驶着一辆名为“喷气蒸汽号”的矮人攻城坦克。在执行长期的攻城旅任务前，他会储备一个月的物资，例如野猪肉和熊皮，并随身携带雷杰德·麦酒酿造的“永恒光辉”，将其投入熔炉以获得瞬间的爆发力。",al={"贝隆·风箱的坦克","喷气蒸汽号","贝隆·风箱驾驶哪种攻城坦克"}},{q="在什么地方可以找到驾驶员贝隆·风箱？",a="你可以在丹莫罗卡拉诺斯东边路下的工程和补给场——钢架补给站的雪地里找到他。",al={"贝隆·风箱的位置","驾驶员贝隆·风箱在哪里","寻找贝隆·风箱"}},{q="他和驾驶员迪恩·石轮一起做什么？",a="贝隆·风箱和驾驶员迪恩·石轮是攻城旅的同僚。在不照看车辆时，两人经常打趣并辩论关于攻城坦克设计、装甲和机械结构的细节。",al={"石轮和贝隆·风箱","贝隆·风箱的对话"}}},fx={["8ff6759c"]={q="驾驶员贝隆·风箱效忠于哪一方？",a="贝隆·风箱是铁炉堡王国和大联盟的一员，在铁炉堡攻城旅中担任驾驶员。他坚定地效忠国王麦格尼·铜须和矮人防卫部队，守护着丹莫罗。",al={"驾驶员贝隆·风箱的阵营","贝隆·风箱为谁效力","贝隆·风箱是联盟的吗"}},["292f21ec"]={q="驾驶员贝隆·风箱想要什么？",a="贝隆·风箱的首要任务是让他的攻城坦克“Jetsteam”随时做好战斗准备并保持燃料充足。他需要旅人帮忙搜集物资，以应对攻城旅的长期任务：野猪肉当食物，熊皮当铺盖，再带上一桶雷杰德·麦酒的永恒之光，既能让他暖和些，也能给“Jetsteam”的炉膛添一把劲。",al={"贝隆·风箱需要什么","驾驶员贝隆·风箱的目标","贝隆·风箱为什么需要补给"}},["53346562"]={q="驾驶员贝隆·风箱为什么在钢架补给站？",a="钢架补给站是铁炉堡重型装甲车辆的集结地和试车场。贝隆驻扎在这里，与其他技师和驾驶员一起调校、测试并补充攻城引擎的物资，然后再出发前往雪原。",al={"贝隆·风箱为什么在钢架补给站","驾驶员贝隆·风箱为什么在丹莫罗","贝隆·风箱在丹莫罗的职责"}}},fp="15,281,22.539.0,23.194.0,34.257.0,35.144.0,37.204.0"}
P.entries["npc:pilot-hammerfoot"] = {n="驾驶员塞克·锤足",s="驾驶员塞克·锤足是铁炉堡工程旅的一名矮人攻城机驾驶员，驻扎在连接丹莫罗和洛克莫丹的山隘附近。他担心一位在山中失踪的飞行员同伴，因此寻求冒险者去寻找他的朋友。他的存在凸显了矮人在高耸的阿尔卑斯山脊上所面临的危险。",h="驾驶员塞克·锤足是铁炉堡工程旅的一名矮人攻城机驾驶员，驻扎在连接丹莫罗和洛克莫丹的山隘附近。他担心一位在山中失踪的飞行员同伴，因此寻求冒险者去寻找他的朋友。他的存在凸显了矮人在高耸的阿尔卑斯山脊上所面临的危险。",kw={"丹莫罗","铁炉堡","洛克莫丹","曼格爪","莫里","北门哨岗","驾驶员塞克·锤足","穴居人"},ang={["faction:Alliance"]="协助锤足可以确保连接丹莫罗和洛克莫丹的主要公路上那些关键侦察哨岗的安全。",["race:Dwarf"]="锤足体现了铁炉堡登山者那种激烈的同志情谊，他绝不会让死去的兄弟被谋杀而得不到伸张。"},sec={{t="山中之眼",b="铁炉堡的攻城机是其工程旅的骄傲，但驾驶它们穿越崎岖的山地地形风险极大。驾驶员塞克·锤足驻扎在俯瞰丹莫罗和洛克莫丹边界的北门哨岗，负责看守飞行员们的引擎并监视山隘。当一名飞行员失踪时，迅速找到他成了当务之急，尤其是附近的山丘上还潜伏着凶猛的野兽。"},{t="为战友复仇",b="锤足与另一位攻城机驾驶员莫里·希尔德尔夫是挚友。两人在搜寻稀有矿石时，希尔德尔夫的攻城机在一座陡峭的山坡上损毁，随后他独自步行前往。在得知希尔德尔夫被巨型冰爪熊“曼格爪”袭击致死后，锤足的任务从常规的边境巡逻转变为个人的复仇，他要求对杀害他朋友的野兽进行报复。"}},faq={{q="驾驶员塞克·锤足是谁？",a="驾驶员塞克·锤足是服务于铁炉堡的一名矮人攻城机驾驶员。他驻扎在连接丹莫罗和洛克莫丹的山隘旁的北门哨岗，看守着该地区的边界和他的飞行员同伴们。",al={"锤足背景故事","锤足是谁","驾驶员塞克·锤足信息"}},{q="在哪里可以找到驾驶员塞克·锤足？",a="他位于北门哨岗，该哨岗坐落在守护丹莫罗和洛克莫丹之间隧道山口的山区公路上。",al={"锤足位置","驾驶员塞克·锤足在哪里","锤足在哪里"}},{q="锤足的搭档，飞行员希尔德尔夫发生了什么事？",a="飞行员莫里·希尔德尔夫在寻找稀有矿石时，他的攻城机在一座陡峭的山坡上损毁，随后他选择了步行前往。锤足一直没有收到他的消息，因此请求旅行者前去调查。",al={"莫里命运","莫里发生了什么","莫里之死"}},{q="为什么锤足会担心他的搭档？",a="锤足和莫里·希尔德尔夫是好朋友，也是工程旅的飞行员同伴。希尔德尔夫在危险的山区地形中失踪，锤足需要有人去查明发生了什么事。",al={"为什么飞行员要复仇","为什么要为莫里复仇","曼格爪宿怨"}}},fx={["9955f46b"]={q="驾驶员塞克·锤足效忠于哪一方？",a="驾驶员塞克·锤足是忠于铁炉堡的矮人，为联盟效力。他驻扎在守卫丹莫罗与洛克莫丹之间隘口的哨岗，负责为山地巡逻队提供补给，并清除当地山道上逼近的威胁。",al={"锤足的阵营","驾驶员塞克·锤足为谁效力","锤足是联盟的吗"}},["4a134edc"]={q="驾驶员塞克·锤足为什么驻扎在这里？",a="锤足在丹莫罗与洛克莫丹之间隘口附近的北门哨岗守卫攻城引擎。他和莫里·希尔德维尔来到山丘寻找稀有矿石，但希尔德维尔的引擎发生故障后便徒步继续前行，至今没有回来。",al={"锤足为什么在这里","锤足的哨岗","驾驶员塞克·锤足为什么在哨岗"}}},fp="16,337,21.428.0,18.424.1,24.215.0,36.132.0,54.179.0,44.192.0"}
P.entries["npc:pilot-longbeard"] = {n="飞行员比罗·长须",s="飞行员比罗·长须是铁炉堡攻城小队的一名矮人攻城机驾驶员，驻扎在铁炉堡Military Ward内的Hall of Arms。尽管身处这座山城，他仍与远在闪光平原从事活动的侏儒技师及其他赛车爱好者保持着密切联系。",h="飞行员比罗·长须是铁炉堡攻城小队的一名矮人攻城机驾驶员，驻扎在铁炉堡Military Ward内的Hall of Arms。尽管身处这座山城，他仍与远在闪光平原从事活动的侏儒技师及其他赛车爱好者保持着密切联系。",kw={"brassbolts","hall of arms","铁炉堡","military ward","飞行员比罗·长须","闪光平原","千针石林"},ang={["profession:Engineering"]="作为一名与侏儒技师有联系的攻城机驾驶员，长须非常欣赏保持机械运转和赛车所需的机械独创性。",["race:Dwarf"]="飞行员比罗·长须体现了矮人的冒险精神，他将传统的铁炉堡军事服务与攻城机和侏儒机械的刺激感联系在了一起。"},sec={{t="攻城小队的飞行员",b="飞行员比罗·长须位于铁炉堡Military Ward的军事陈列和武器铁匠之间，代表了卡兹莫丹引以为傲的攻城机部队。虽然职责将他留在要塞城市内，但长须总是密切关注着大陆各地技工的创新和消息，包括在卡利姆多盐滩上进行修补工作的Brassbolts兄弟。"},{t="跨越大陆的联系",b="长须是那些前往南方的卡利姆多探险的旅行者的联络点。他经常将有前途的新兵和信使指引向千针石林的闪光平原，在那里，侏儒发明家正与他们的地精竞争对手一道，不断突破机械的极限。"}},faq={{q="我在哪里可以找到飞行员比罗·长须？",a="他位于铁炉堡Military Ward的Hall of Arms内，站在训练师和军事陈列附近。",al={"飞行员比罗·长须位置","长须在铁炉堡的哪里","如何找到飞行员比罗·长须"}},{q="飞行员比罗·长须的职责是什么？",a="飞行员比罗·长须是一位任务发布者，他引导联盟的冒险者前往海外进行冒险，尤其是将旅行者与他身处千针石里的朋友Brassbolts兄弟联系起来。",al={"长须做什么","飞行员比罗·长须任务","为什么要找长须"}},{q="Brassbolts兄弟与长须是什么关系？",a="他们是长须在闪光平原共事的侏儒技师，因为对工程学和实验性机械的共同热情而结缘。",al={"brassbolts联系","长须为什么认识brassbolts","长须与闪光平原"}},{q="飞行员比罗·长须与弗伦·长须有亲戚关系吗？",a="他们都拥有铁炉堡显赫的长须氏族名，这表明他们是族人，尽管飞行员比罗·长须专注于攻城机和工程学联络，而不是锻造。",al={"弗伦·长须兄弟","长须家族矮人","他和弗伦有关系吗"}}},fx={e17c59b9={q="飞行员比罗·长须效忠于哪一方？",a="飞行员比罗·长须坚定地支持铁炉堡的矮人和联盟。他是铁炉堡攻城旅的飞行员，驻扎在铁炉堡军事区的Hall of Arms。他以攻城旅的攻城引擎为荣，也会帮助联盟各地的朋友和同行飞行员。",al={"飞行员比罗·长须的阵营","飞行员比罗·长须是联盟的吗","长须效忠哪一方"}},["97d29847"]={q="飞行员比罗·长须想要什么？",a="飞行员比罗·长须想帮助朋友和同行飞行员，不过职责让他必须留在铁炉堡。他会让旅人把攻城引擎头盔送给他的朋友黄铜螺栓兄弟——他们的火箭赛车驾驶员总是在闪光平原坠毁——也会请人帮驾驶员迪恩·石轮寻找一种稀有矿石。",al={"飞行员比罗·长须的目标","长须需要什么","飞行员比罗·长须的任务"}},["5f9eba76"]={q="飞行员比罗·长须为什么在这里？",a="作为铁炉堡攻城旅的飞行员，长须驻扎在铁炉堡军事区内的Hall of Arms。他的职责让他留在城中，因此需要旅人把援助送给远方的朋友，例如黄铜螺栓兄弟和他们的侏儒赛车队。",al={"飞行员比罗·长须为什么在铁炉堡","长须在军事区的原因","长须为什么在这里"}}},fp="15,300,28.385.0,29.278.0,33.122.0,31.191.0,45.159.0,46.181.0"}
P.entries["npc:pilot-stonegear"] = {n="驾驶员迪恩·石轮",s="驾驶员迪恩·石轮，绰号“石头”，是一名铁炉堡攻城小队的矮人技师兼驾驶员，驻扎在钢架补给站。他操作着名为Trollplow的强力攻城机，并为了提升其性能和装甲而不懈努力。穿行于丹莫罗的冒险者经常帮助他寻找稀有材料，以使他的战争机器时刻准备战斗。",h="驾驶员迪恩·石轮，绰号“石头”，是一名铁炉堡攻城小队的矮人技师兼驾驶员，驻扎在钢架补给站。他操作着名为Trollplow的强力攻城机，并为了提升其性能和装甲而不懈努力。穿行于丹莫罗的冒险者经常帮助他寻找稀有材料，以使他的...",kw={"丹莫罗","铁炉堡攻城小队","驾驶员贝隆·风箱","驾驶员塞克·锤足","驾驶员迪恩·石轮","攻城机","钢架补给站","迪恩·石轮","trollplow"},ang={["profession:Engineering"]="工程师们会赞赏迪恩·石轮对Trollplow进行野战改装的执着，他在致命的战斗性能与驾驶员的人体工程学之间取得了平衡。",["profession:Mining"]="矿工们提供迪恩·石轮锻造加固装甲和弹药所必需的原始矿石和不稳定的地下矿藏。",["race:Dwarf"]="迪恩·石轮是矮人对重型钢铁、轰鸣引擎以及用巨大的铁履带碾碎山地敌人的热爱的典范。",["race:Gnome"]="与攻城小队一起工作的侏儒们在迪恩·石轮身上找到了知音，他总是热衷于摆弄实验性设计并优化输出。"},sec={{t="Trollplow的主人",b="驾驶员迪恩·石轮驻扎在钢架补给站那轰鸣的锅炉和叮当响的履带之间，作为攻城小队的一名驾驶员，为铁炉堡服务并引以为傲。他的骄傲是Trollplow，这是一种专为突破敌军防线而建造的重型攻城坦克。迪恩·石轮对他的机器非常重视——他知道在激烈的战斗中，驾驶员的生命完全取决于齿轮、钢板和蒸汽压力的稳固性。他不断寻求优化Trollplow的作战效率，同时改善其狭窄驾驶舱的日常舒适度。"},{t="机械改装与冶金技术",b="像补给站里的许多矮人和侏儒技工一样，迪恩·石轮很少对出厂规格感到满足。他经常利用休息时间与驾驶员贝隆·风箱等战友争论工程图纸。无论是追寻异域矿石的传闻，还是搜寻用于强化装甲和弹药的挥发性矿物，迪恩·石轮都依靠热心的新兵前往丹莫罗的雪地荒野和危险洞穴进行补给搜集。"}},faq={{q="驾驶员迪恩·石轮是谁？",a="驾驶员迪恩·石轮，常被称为“石头”，是一名铁炉堡矮人，也是铁炉堡攻城小队的成员。他驻扎在丹莫罗的钢架补给站，负责维护和操作他的攻城机Trollplow。",al={"驾驶员迪恩·石轮背景故事","迪恩·石轮是谁","驾驶员石头"}},{q="驾驶员迪恩·石轮在哪里？",a="迪恩·石轮位于丹莫罗卡拉诺斯外面的钢架补给站，周围环绕着攻城坦克、备用零件和他的飞行员同伴们。",al={"驾驶员迪恩·石轮位置","迪恩·石轮在哪","寻找迪恩·石轮"}},{q="什么是Trollplow？",a="Trollplow是驾驶员迪恩·石轮的个人攻城机。他不断努力升级其机械可靠性、装甲板和内部舒适度，以使其能在残酷的前线战斗需求中幸存下来。",al={"什么是trollplow","trollplow坦克","迪恩·石轮的坦克"}},{q="迪恩·石轮需要冒险者做什么？",a="迪恩·石轮招募旅行者去侦察附近的威胁并收集稀有矿物——例如火岩矿石——以帮助升级和维护攻城小队的重型战争机器。",al={"驾驶员迪恩·石轮的任务","为什么迪恩·石轮有任务","迪恩·石轮的搜寻"}},{q="驾驶员迪恩·石轮与谁共事？",a="他与驾驶员贝隆·风箱和驾驶员塞克·锤足等其他驾驶员一同在铁炉堡攻城小队服役，并经常在补给站与驾驶员贝隆·风箱探讨机械升级和机器设计。",al={"迪恩·石轮的朋友","攻城小队驾驶员","贝隆·风箱与迪恩·石轮"}},{q="什么是铁炉堡攻城小队？",a="铁炉堡攻城小队是矮人军队的机械化装甲师。他们操作蒸汽坦克、攻城机和重型火炮，为保卫丹莫罗提供装甲支援，并在整个卡兹莫丹展示铁炉堡的军事力量。",al={"铁炉堡攻城小队","攻城小队背景故事","矮人坦克小队"}}},fx={["6ae24a1f"]={q="驾驶员迪恩·石轮效忠于哪一方？",a="驾驶员迪恩·石轮是铁炉堡攻城旅中尽职的驾驶员，为铁炉堡和联盟效力。他驻扎在钢架补给站，一心效忠矮人王国，守卫丹莫罗的雪岭，并确保城中的重型战争机器调试妥当，以应对任何威胁族人的敌人。",al={"驾驶员迪恩·石轮的阵营","石轮效忠哪一方","驾驶员迪恩·石轮为谁效力"}},["5e3743ba"]={q="驾驶员迪恩·石轮为什么在钢架补给站？",a="石轮驻扎在钢架补给站，负责测试、维护并改进他的攻城引擎“巨魔犁”。他与攻城旅的其他驾驶员一起利用补给站的工坊监督维修，交流引擎机械方面的心得，并寻找提升机器野外耐用性的稀有矿石和矿物。",al={"石轮为什么在丹莫罗","驾驶员迪恩·石轮为什么在这里","石轮和钢架补给站"}}},fp="15,364,23.524.0,24.454.0,23.221.0,33.138.0,22.211.0,41.175.0,35.202.0,36.252.0"}
P.entries["npc:pixel"] = {n="皮克希尔",s="皮克希尔是一位进取心极强的地精信使，以灰谷的碎木岗哨为基地。她靠在危险地区运送重型货物为生，比如为当地部落部队运送战歌锯条——但她绝不会在没有得到应有报酬的情况下交付任何货物。",h="皮克希尔是一位进取心极强的地精信使，以灰谷的碎木岗哨为基地。她靠在危险地区运送重型货物为生，比如为当地部落部队运送战歌锯条——但她绝不会在没有得到应有报酬的情况下交付任何货物。",kw={"灰谷","信使","地精","皮克希尔","萨特的角","碎木岗哨","战歌锯条"},ang={["faction:Horde"]="对于那些为在灰谷建立立足点而战的部落勇士来说，皮克希尔提供了战歌氏族迫切需要的工业硬件，以维持他们的伐木机械运转。"},sec={{t="幽暗森林的生意",b="尽管碎木岗哨是部落在灰谷危机四伏的森林中建立的一座堡垒，但皮克希尔始终专注于自己的利润。作为一名愿意将货物运往交战区的独立信使，她为战歌氏族的伐木事业提供了重要的后勤保障。然而，秉承地精的传统，契约和金钱才是她合作的前提。在客户付款之前，她绝不交付货物；对于那批锯条，她要求对方提供一把致命的短枪，以便在旅途中保护自己。她总是对机会保持警觉，同时也花钱雇佣路过的冒险者收集萨特的角，因为这些东西在棘齿城非常抢手。"}},faq={{q="皮克希尔是谁？",a="皮克希尔是一位驻扎在灰谷东部碎木岗哨的自由地精信使。她以在危险地带运送货物为生，目前正负责一批对当地战歌伐木活动至关重要的锯条。",al={"这个地精是谁","皮克希尔背景故事","碎木岗哨地精"}},{q="为什么皮克希尔不立即交出锯条？",a="像所有精明的地精一样，皮克希尔严格遵循商业原则行事。尽管部落在灰谷的处境十分紧迫，但在没有得到相应的报酬或贸易货物来抵扣费用之前，她拒绝交付那批锯条。",al={"为什么皮克希尔要求付款","战歌锯条运输","锯条任务"}},{q="她为什么要萨特的角？",a="萨特的角在棘齿城需求量很大，而那是皮克希尔的下一站。她自己无法匹敌夜道谷、萨提纳尔和萨维亚的萨特，因此她花钱雇佣冒险者为她收集角，以便转手卖出。",al={"为什么需要萨特的角","皮克希尔与萨特","碎木岗哨萨特任务"}},{q="皮克希尔是部落的正式成员吗？",a="由于与战歌伐木行动签订了利润丰厚的合同，皮克希尔与碎木岗哨的部落往来密切，但她主要的忠诚对象是贸易、利润以及履行她的交付协议。",al={"皮克希尔是部落吗","皮克希尔阵营","皮克希尔是中立的吗"}}},fx={c8b7be1d={q="皮克希尔为什么在灰谷？",a="皮克希尔是一名精明能干的地精信使，靠在卡利姆多及更远的地方运送货物谋生。她深入灰谷这片纷争不断的森林，将一批重要的战歌锯条直接送到了部落哨站碎木岗哨。",al={"皮克希尔为什么在这里","皮克希尔为什么在碎木岗哨","皮克希尔与灰谷"}},["37ebabcf"]={q="皮克希尔为谁工作？",a="皮克希尔以自由送货专员的身份独立经营，并未宣誓效忠任何单一阵营。她目前的生意与战歌氏族和驻扎在碎木岗哨的部队有关，为他们在森林中的伐木工作提供所需的工业机械。",al={"皮克希尔与谁有关联","皮克希尔的雇主","皮克希尔的关系"}}},fp="5,298,26.642.0,13.235.0,53.220.0,30.207.0,42.207.0"}
P.entries["npc:piznik"] = {n="匹兹尼克",s="匹兹尼克是一名心怀不满的地精勘探员，他躲在石爪山脉的狂风矿洞深处。他曾经是当地荆棘谷地精行动中的一名高级监工，却被冷酷无情的格伦佐·扳手哨排挤出局。现在，怀恨在心的匹兹尼克秘密搜集情报，意图破坏他曾经工作的地方。",h="匹兹尼克是一名心怀不满的地精勘探员，他躲在石爪山脉的狂风矿洞深处。他曾经是当地荆棘谷地精行动中的一名高级监工，却被冷酷无情的格伦佐·扳手哨排挤出局。现在，怀恨在心的匹兹尼克秘密搜集情报，意图破坏他曾经工作的地方。",kw={"格伦佐·扳手哨","匹兹尼克","石爪山脉","荆棘谷地精","狂风峭壁","狂风矿洞","齐兹·菲兹克斯"},ang={["profession:Mining"]="穿行在狂风矿洞的矿工们会与匹兹尼克不期而遇，他是企业贪婪之下组织阶级跌落速度有多快的一个鲜活例证。"},sec={{t="失宠",b="在格伦佐·扳手哨夺取狂风峭壁的最高指挥权之前，匹兹尼克在整个行动中拥有令人艳羡的二把手头衔。然而，荆棘谷地精的企业重组是无情的。格伦佐全面掌权后，匹兹尼克发现自己被推到一边，并被贬谪到了狂风矿洞阴暗的深处。匹兹尼克并没有默默接受降职，而是潜伏在地下等待时机，密切监视矿洞内的一举一动，并暗中策划着对那位将他降职的老板进行报复。"},{t="企业间谍",b="匹兹尼克的无声反抗通过与齐兹·菲兹克斯结盟而变得具有实际意义。齐兹·菲兹克斯也是一名驻扎在外面、同样被格伦佐排挤的行动人员。作为齐兹的内应，匹兹尼克尽可能地搜集关于格伦佐计划的情报。通过走私出一份格伦佐下令大量开采的神秘金绿色矿石样本并将其送往齐兹手中，匹兹尼克努力从阴影中破坏荆棘谷地精的伐木和采矿工作，确保格伦佐那充满野心的领导地位面临持续且痛苦的挫折。"}},faq={{q="在哪里可以找到匹兹尼克？",a="匹兹尼克躲在狂风矿洞内，这是一个开凿在石爪山脉狂风峭壁山坡上的洞穴群。你会发现他深入隧道之中，周围是荆棘谷地精的工人们。",al={"匹兹尼克位置","匹兹尼克在哪里","寻找石爪山脉的匹兹尼克"}},{q="匹兹尼克对格伦佐·扳手哨有什么不满？",a="匹兹尼克曾经是狂风峭壁的二号人物。当格伦佐·扳手哨全面接管伐木和采矿项目时，他将匹兹尼克降职了，这让这位前主管感到愤恨，并渴望看到格伦佐身败名裂。",al={"为什么匹兹尼克痛恨格伦佐","匹兹尼克和格伦佐的恩怨"}},{q="匹兹尼克在齐兹·菲兹克斯的计划中起到什么作用？",a="齐兹·菲兹克斯被格伦佐直接解雇了，而匹兹尼克仅仅是被降职。匹兹尼克利用他在狂风矿洞深处保留的权限充当线人，收集关于格伦佐计划的消息，并将格伦佐下令开采的神秘矿石样本运送给齐兹。",al={"匹兹尼克和齐兹","匹兹尼克与谁合作"}},{q="匹兹尼克还忠于荆棘谷地精吗？",a="仅仅名义上而已。虽然他仍然身穿荆棘谷地精雇员的外衣以便留在矿洞内，但匹兹尼克真正的效忠对象完全是他自己的利益和他破坏格伦佐的渴望。",al={"匹兹尼克是荆棘谷地精吗","匹兹尼克派系"}}},fx={["73f53239"]={q="匹兹尼克是谁？",a="匹兹尼克是一名地精特工，藏身于石爪山脉深处的狂风矿洞中。他曾是荆棘谷地精在狂风峭壁一带行动的二把手，地位显赫、颇有影响力，直到格伦佐·扳哨抵达并夺取控制权，逐步剥夺了他的职位。",al={"匹兹尼克是谁","匹兹尼克的背景故事","匹兹尼克的来历"}},["04ccaf91"]={q="匹兹尼克想要什么？",a="匹兹尼克想报复格伦佐·扳哨，因其毁掉了他在荆棘谷地精中的地位；他也想赚上一笔。在被格伦佐解雇的前老板兹兹·菲兹克斯请求下，他留在矿洞里打探格伦佐的计划，并偷偷带出一份格伦佐下令大量开采的金绿色矿石样本，让兹兹的新雇主进行研究。",al={"匹兹尼克想要什么","匹兹尼克的目标","匹兹尼克的动机"}},e9de2964={q="匹兹尼克为什么在狂风矿洞？",a="格伦佐·扳哨夺取荆棘谷地精当地产业的控制权后，便把匹兹尼克派到狂风矿洞工作。匹兹尼克应兹兹·菲兹克斯的请求留在矿道中，充当内部线人，暗中收集情报，不让行动中的其他人察觉。",al={"匹兹尼克为什么在这里","匹兹尼克为什么在狂风矿洞","匹兹尼克在此的原因"}}},fp="6,315,17.529.0,19.532.1,24.212.0,54.240.0,44.276.0,45.201.0"}
P.entries["npc:pozzik"] = {n="普兹克",s="普兹克是一位受人尊敬的地精技师兼赛车手，驻扎在千针石林闪光平原上的沙漠赛道。他曾是安德麦最受推崇的工程师之一，如今他将自己的技术天赋投入到制造实验性火箭车的事业中，并试图在他与侏儒对手之间那场关于工程学霸权的终极辩论中一决胜负。",h="普兹克是一位受人尊敬的地精技师兼赛车手，驻扎在千针石林闪光平原上的沙漠赛道。他曾是安德麦最受推崇的工程师之一，如今他将自己的技术天赋投入到制造实验性火箭车的事业中，并试图在他与侏儒对手之间那场关于工程学霸权的终极辩论中一...",kw={"菲兹尔·铜栓","沙漠赛道","普兹克","火箭车","闪光平原","千针石林","技师","安德麦"},ang={["profession:Engineering"]="对于任何倾向的工程师——无论是地精还是侏儒——普兹克都代表了高风险、高速度应用机械学的巅峰。",["race:Gnome"]="造访赛道的侏儒会在普兹克身上找到他们最喜欢的对手：一位吵闹的地精工程师，坚信野蛮的推力胜过精致的精度。"},sec={{t="安德麦的大师",b="在隐退到千针石林那严酷的盐碱平原之前，普兹克在地精中享有传奇般的声望。作为安德麦最受推崇的技师之一，他的技术专长涵盖了复杂的内燃机、推进装置以及危险的底盘结构。然而，普兹克并没有安于舒适的隐居生活，而是将他精湛的机械造诣带到了沙漠中，将高速机械的性能推向了极限。"},{t="盐碱平原上的决斗",b="在沙漠赛道，普兹克与他长期的侏儒对手菲兹尔·铜栓联手。尽管地精炸药与侏儒精密校准之间有着历史悠久的对抗，但两人还是携手合作，在干涸的湖床上建造了广阔的赛道。他们各自组建了对立的赛车队，通过测试原型火箭车来一决高下，最终证明究竟哪种种族的工程哲学才是赛道上的霸主。理所当然，普兹克一直在寻找足智多谋的冒险者，希望能为他的设计获取零件并减轻重量。"}},faq={{q="普兹克是谁？",a="普兹克是一位来自安德麦的老牌地精技师，目前在千针石林的沙漠赛道领导着火箭赛车竞赛的一方。",al={"普兹克","普兹克是谁","普兹克背景故事"}},{q="普兹克为什么在千针石林？",a="在结束了安德麦的正式工作后，普兹克来到闪光平原，在广阔且一望无际的盐碱地上建造并驾驶实验性火箭车。",al={"普兹克为什么在这里","普兹克闪光平原"}},{q="他和菲兹尔·铜栓是什么关系？",a="菲兹尔·铜栓是普兹克长期的侏儒竞争对手和赛道联合创始人。尽管他们并肩工作以维护沙漠赛道，但他们不断竞争以证明地精工程学优于侏儒工艺。",al={"普兹克和菲兹尔","普兹克侏儒对手"}},{q="普兹克是为部落还是联盟工作？",a="普兹克完全中立，在赛道上以独立地精企业家的身份工作。他愿意与联盟和部落的旅行者进行交易并提供任务。",al={"普兹克是中立的吗","普兹克阵营"}},{q="普兹克目前在进行什么样的项目？",a="普兹克沉迷于榨取火箭车更多的速度。他开发多引擎赛车底盘，收集稀有的轻质矿石，并派遣探险者去寻找废弃的零件和组件。",al={"普兹克任务","普兹克建造什么"}}},fx={["186dfe38"]={q="普兹克为何出名？",a="在闪光平原定居之前，普兹克就以安德麦最受尊敬的技工之一而闻名。他传奇般的工程技艺也延续到了他的火箭赛车设计中；他研发出强劲的双引擎赛车，革新了这项运动。",al={"普兹克为何出名","普兹克出名吗","普兹克为何广为人知"}}},fp="6,347,21.446.0,26.542.0,14.157.0,38.167.0,48.234.0,47.172.0,53.199.0"}
P.entries["npc:priestess-a-moora"] = {n="女祭司艾茉拉",s="女祭司艾茉拉是一位虔诚的暗夜精灵，侍奉着月神，居住在达纳苏斯的Temple of the Moon中。她在泰兰德·语风大祭司的教团指导下工作，负责精神净化仪式以及与艾露恩的交流。在泰达希尔探险的旅行者，当涉及到神圣的祭品和树枝间神秘的野生生物时，常常会被指引去向她寻求帮助。",h="女祭司艾茉拉是一位虔诚的暗夜精灵，侍奉着月神，居住在达纳苏斯的Temple of the...",kw={"艾茉拉","达纳苏斯","艾露恩","女祭司","萨斯拉","月神之泪","泰达希尔","temple of the moon"},ang={["class:Priest"]="在Temple of the Moon的大厅中行走的牧师们可以从艾茉拉身上看到虔诚奉献的典范，她连接了神殿仪式与城门外的自然世界之间的鸿沟。",["faction:Alliance"]="女祭司艾茉拉协助在达纳苏斯神圣中心探险的联盟旅行者，向他们介绍The Sisterhood of Elune的神圣习俗。",["race:NightElf"]="对于暗夜精灵而言，女祭司艾茉拉代表了艾露恩崇拜的永恒传统，将泰达希尔年轻的树枝与他们民族古老的精神遗产紧密联系在一起。"},sec={{t="艾露恩的仆人",b="在Temple of the Moon宁静的大理石殿堂内，女祭司艾茉拉每日都在沉思与侍奉中度过。作为一名受戒的艾露恩女祭司，她协助照料达纳苏斯的精神需求，并守护着千百年来流传下来的细腻仪式。虽然The Sisterhood of Elune的大部分成员负责军事防御或外交事务，但艾茉拉专注于传统的虔诚活动以及与泰达希尔自然之灵有关的神圣事务。"},{t="月神之泪",b="艾茉拉与萨斯拉夫人的悲惨命运紧密相连。萨斯拉夫人曾是一只深受艾露恩喜爱的巨型蜘蛛，其银色的露水因其治疗能力而被保存在神殿中。当萨斯拉陷入疯狂时，艾茉拉派遣年轻的冒险者前往泰达希尔北部的涌泉湖附近，结束她的痛苦并带回她的银色丝囊。将丝囊供奉在神殿的喷泉处，便成为了献给艾露恩的祭品，从而让萨斯拉得以在平静中重生。"}},faq={{q="我在哪里可以找到女祭司艾茉拉？",a="女祭司艾茉拉位于达纳苏斯的Temple of the Moon内，这座首府城市坐落在泰达希尔的树冠之上。她站在侍奉艾露恩祭坛的女祭司们中间。",al={"艾茉拉位置","女祭司艾茉拉在哪里","艾茉拉 达纳苏斯"}},{q="女祭司艾茉拉在达纳苏斯担任什么角色？",a="她是The Sisterhood of Elune的一员，负责监督特定的宗教仪式和神圣的祭品。她担任任务发布者和向导，引导那些寻求在泰达希尔执行古老净化与祭祀仪式的旅行者。",al={"艾茉拉的职责","女祭司艾茉拉的目的"}},{q="女祭司艾茉拉提供什么任务？",a="她提供“月神之泪”任务链，派遣冒险者前往涌泉湖附近杀死陷入疯狂的蜘蛛萨斯拉夫人，然后将她的银色丝囊作为祭品在神殿的喷泉处供奉。",al={"艾茉拉的任务","女祭司艾茉拉任务线"}},{q="女祭司艾茉拉与Temple of the Moon有什么关系？",a="她是Temple of the Moon的一名活跃侍从，该殿堂是由泰兰德·语风大祭司统治的暗夜精灵文化的精神中心。艾茉拉促进了在神殿屋檐下进行的精神指导和仪式职责。",al={"艾茉拉是神殿女祭司吗","艾露恩姐妹会 艾茉拉"}},{q="萨斯拉是谁，为什么艾茉拉会提到她？",a="萨斯拉夫人是一只曾经深受艾露恩喜爱的巨型蜘蛛，栖息在泰达希尔北部边界的涌泉湖附近。她已经陷入疯狂，因此艾茉拉请求冒险者结束她的痛苦，并将她的丝囊献给艾露恩，好让她能在平静中重生。",al={"萨斯拉 祭品","萨斯拉是谁"}},{q="艾茉拉属于联盟吗？",a="是的。作为驻扎在首府达纳苏斯的一名暗夜精灵女祭司，她完全隶属于联盟，不会为部落成员提供任何援助或任务。",al={"艾茉拉属于联盟吗","部落可以和艾茉拉对话吗"}}},fx={["05fd0978"]={q="女祭司艾茉拉是谁？",a="女祭司艾茉拉是一名虔诚的暗夜精灵，是艾露恩的侍奉者，驻守在达纳苏斯宏伟的Temple of the Moon中。作为神殿中尽心侍奉的女祭司之一，她为族人的精神需求提供祈祷、劝导与指引，承蒙月之女神的恩泽。",al={"女祭司艾茉拉是谁","艾茉拉是谁","女祭司艾茉拉的背景故事"}},["4daa0bfc"]={q="女祭司艾茉拉想要什么？",a="女祭司艾茉拉致力于维护Temple of the Moon的神圣仪式与圣洁。她寻求值得信赖的冒险者协助处理信仰与仪式相关的事务，请你帮忙准备月之泪等神圣供品，以此向艾露恩致敬，并维系神殿的圣礼。",al={"女祭司艾茉拉的目标","艾茉拉想要什么","艾茉拉的动机"}},e929c23e={q="女祭司艾茉拉为什么在达纳苏斯？",a="艾茉拉居住在Temple of the Moon，因为它是暗夜精灵族人敬奉艾露恩的中心。她照料圣所的日常祈祷，协助高阶女祭司泰兰德·语风的祭司团，并确保首都的精神和谐不受玷污。",al={"艾茉拉为什么在达纳苏斯","女祭司艾茉拉与temple of the moon","艾茉拉为什么在这里"}}},fp="17,418,18.455.0,17.456.0,35.187.0,46.232.0,41.205.0,59.238.0,50.268.0,36.181.0"}
P.entries["npc:priestess-alathea"] = {n="女祭司阿兰希雅",s="女祭司阿兰希雅是一位暗夜精灵牧师训练师，居住在达纳苏斯Temple of the Moon宁静的大厅中。她致力于侍奉月神，指导新晋成员学习神圣技艺以及艾露恩所赐予的种族祝福。她的教诲帮助kaldorei修行者将心智调整为防御性的祈祷和星辰魔法。",h="女祭司阿兰希雅是一位暗夜精灵牧师训练师，居住在达纳苏斯Temple of the...",kw={"阿兰希雅","达纳苏斯","艾露恩","elune's grace","牧师训练师","女祭司阿兰希雅","stars of elune","temple of the moon"},ang={["class:Priest"]="女祭司阿兰希雅是访问达纳苏斯的联盟牧师的重要联络人，她提供等级提升服务，并引导kaldorei信徒掌握他们独特的星辰力量。",["faction:Alliance"]="阿兰希雅向所有学习神职技艺并游历至此的联盟成员开放Temple of the Moon的教义。",["race:NightElf"]="作为达纳苏斯中心的女祭司，阿兰希雅代表了保护了kaldorei数千年的The Sisterhood of Elune那鲜活的精神传统。"},sec={{t="在Temple of the Moon中的虔诚",b="女祭司阿兰希雅站在达纳苏斯最宏伟的圣殿那高耸的银色穹顶之下，作为导师和精神向导为The Sisterhood of Elune服务。当暗夜精灵新手们走出幽影谷那宁静的树荫时，他们会被指引前往Temple of the Moon，以加深他们与女神的盟约。阿兰希雅在女祭司们中指引着那些致力于治疗、守护和Holy Light的人，向他们传授神圣的知识。"},{t="白女士的祝福",b="与那些严格遵循人类和矮人传统的Holy Light牧师不同，kaldorei牧师直接汲取艾露恩的恩典。阿兰希雅在测试和授予暗夜精灵量身定制的祝福（如Stars of Elune和Elune's Grace）方面扮演着关键角色。通过她的指导，信徒们学会了如何将星光编织成敏捷与防御之盾，以在卡利姆多日益增长的危险中生存下来。"}},faq={{q="谁是女祭司阿兰希雅？",a="女祭司阿兰希雅是一位kaldorei牧师训练师，驻扎在达纳苏斯的Temple of the Moon内，负责训练初出茅庐的牧师，并引导暗夜精灵信徒完成他们的神圣试炼。",al={"谁是阿兰希雅","阿兰希雅 达纳苏斯","阿兰希雅 牧师训练师"}},{q="她教授哪些技能？",a="她提供标准的牧师法术训练，以及针对暗夜精灵种族特长的特定试炼，包括Starshards和Elune's Grace，这些技能引导着月神直接的力量与庇护。",al={"阿兰希雅 技能","阿兰希雅 法术","达纳苏斯 牧师法术"}},{q="我在哪里可以找到女祭司阿兰希雅？",a="她居住在达纳苏斯南部的Temple of the Moon底楼，周围环绕着圣殿内发光的池水和其他女祭司。",al={"阿兰希雅在哪里","阿兰希雅 位置"}},{q="为什么暗夜精灵牧师要专门拜访她？",a="当kaldorei牧师在训练中取得进展时，泰达希尔各地的新手导师会将他们送到阿兰希雅那里，以进行精神仪式——例如Stars of Elune和Elune's Grace——这标志着他们成为女神的成熟侍奉者。",al={"牧师任务 阿兰希雅","stars of elune任务"}},{q="她是否训练暗夜精灵以外的种族？",a="是的。虽然人类和矮人牧师属于Church of the Holy Light，但任何访问达纳苏斯的联盟牧师都可以从她那里学习通用法术，尽管她只为暗夜精灵进行kaldorei特有的种族试炼。",al={"人类可以找阿兰希雅训练吗","阿兰希雅 矮人牧师"}},{q="她的信仰与人类和矮人牧师有何不同？",a="当暴风城和铁炉堡的牧师祈求环境中弥漫的Holy Light哲学时，阿兰希雅和她的姐妹们尊崇艾露恩为一位活生生的神祇，运用星光和月光结界，以及治愈魔法。",al={"艾露恩与圣光","暗夜精灵牧师背景"}}},fx={d359d229={q="女祭司阿兰希雅支持哪一方？",a="女祭司阿兰希雅坚定地支持The Sisterhood of Elune、暗夜精灵族人与联盟。她在神圣的Temple of the Moon侍奉高阶女祭司泰兰德·语风，全心奉献于艾露恩，并引导虔诚的暗夜精灵。",al={"女祭司阿兰希雅的阵营","阿兰希雅与联盟","阿兰希雅侍奉谁"}},["58a787d3"]={q="女祭司阿兰希雅为什么在Temple of the Moon？",a="阿兰希雅居住在达纳苏斯，负责训练和指导初出茅庐的暗夜精灵牧师。作为驻守在首都宏伟圣所中的艾露恩虔诚侍奉者，她教导见习者如何将月之女神的祝福融入守护祷言与星火战技之中。",al={"女祭司阿兰希雅为什么在这里","阿兰希雅在达纳苏斯的位置","阿兰希雅在这里做什么"}},f062e3c8={q="女祭司阿兰希雅想要什么？",a="阿兰希雅致力于培养暗夜精灵新晋教徒的虔诚信仰，加强他们与艾露恩的联系。她希望年轻牧师将月之女神的智慧、恩泽与战斗之光带遍卡利姆多，守护他们的祖地。",al={"阿兰希雅的目标","阿兰希雅在寻求什么","女祭司阿兰希雅的职责"}},a22ea658={q="女祭司阿兰希雅与谁有联系？",a="她与The Sisterhood of Elune关系密切，并在高阶女祭司泰兰德·语风麾下效力。她驻守在达纳苏斯的资深女祭司之中，与Temple of the Moon各处的其他侍僧协调训练事宜。",al={"女祭司阿兰希雅的人际关系","阿兰希雅的关系","阿兰希雅与谁共事"}}},fp="17,336,34.465.0,27.429.0,25.201.0,30.198.0,35.165.0,48.240.0,44.226.0,57.212.0"}
P.entries["npc:priestess-anetta"] = {n="女牧师安妮塔",s="女牧师安妮塔是一位驻守在北郡修道院内的人类圣职者。作为北郡兄弟会的一员，她负责指导初来乍到的牧师进行他们的第一次圣礼。",h="女牧师安妮塔是一位驻守在北郡修道院内的人类圣职者。作为北郡兄弟会的一员，她负责指导初来乍到的牧师进行他们的第一次圣礼。",kw={"安妮塔","北郡兄弟会","艾尔文森林","圣光","图书馆侧厅","北郡修道院","牧师训练师","女牧师安妮塔"},ang={["class:Priest"]="对于在北郡开启冒险的年轻人类牧师来说，女牧师安妮塔是你最初的导师，她会确认你神圣的使命，并教会你如何直接与圣光沟通。",["faction:Alliance"]="安妮塔代表了联盟持久的精神核心，她正在培养年轻的牧师，准备好支援那些保卫北郡山谷的人们。"},sec={{t="信徒的看护者",b="你可以在北郡修道院安静的图书馆侧厅的一楼找到女牧师安妮塔。在迪菲亚强盗和狗头人威胁山谷的局势下，她作为北郡兄弟会稳定人心的支柱，提醒着每一位过客不要背弃圣光，因为那也许就是某一天能拯救他们的唯一希望。"},{t="指导新手牧师",b="在修道院内，安妮塔是人类新手牧师的主要导师。带着神圣信件前来报到的新手会寻找她，学习信仰的基础：引导圣言来治愈伤口，以及释放惩击之光来驱逐邪恶。在她的教导下，年轻的侍僧们准备好将圣光带出北郡那与世隔绝的围墙之外。"}},faq={{q="女牧师安妮塔是谁？",a="女牧师安妮塔是一位隶属于北郡兄弟会的人类牧师训练师和治疗者。她居住在北郡修道院一楼的图书馆侧厅，在那里教导新手牧师。",al={"安妮塔是谁","女牧师安妮塔背景故事","女牧师安妮塔北郡"}},{q="我可以在哪里找到女牧师安妮塔？",a="她位于艾尔文森林北部的北郡修道院内。从修道院前门进入，走到主大厅，然后看向图书馆侧厅的一楼。",al={"女牧师安妮塔在哪里","安妮塔位置","寻找安妮塔"}},{q="她在修道院的防御中扮演什么角色？",a="当暴风城的元帅和新兵们奋力从迪菲亚强盗和狗头人手中夺回山谷时，安妮塔负责训练其中的牧师，教导他们用圣光治愈并保护自己的战友。",al={"安妮塔做什么","安妮塔的角色"}},{q="她提供什么样的训练？",a="安妮塔向年轻的牧师传授入门级的圣职法术和祷言，教导他们以圣光之名进行治疗和惩击敌人的基础知识。",al={"安妮塔能教我法术吗","安妮塔牧师法术"}}},fx={d2501181={q="女牧师安妮塔支持哪一方？",a="女牧师安妮塔坚定地支持暴风王国、圣光以及北郡兄弟会。她在北郡修道院供职，协助王国的守卫者，并守护这处宁静的圣所，使其免受周边威胁侵扰。",al={"安妮塔的阵营","安妮塔侍奉谁","女牧师安妮塔效忠于谁"}},bbb44d1e={q="女牧师安妮塔想要什么？",a="女牧师安妮塔想要培养新一代圣光的使用者。她肩负引导年轻牧师修习信仰、教导他们运用圣光治疗他人并保护他人的基础知识。",al={"安妮塔的目标","安妮塔想做什么","安妮塔的目的"}},["00624d11"]={q="女牧师安妮塔为什么在这里？",a="女牧师安妮塔是北郡兄弟会的正式神职人员，居于北郡修道院。她驻守在修道院的图书馆区域，向响应暴风城召唤的见习者传授圣光的基础知识。",al={"安妮塔为什么在北郡","安妮塔在这里的职责","女牧师安妮塔为什么在修道院"}},["1b4a2e6e"]={q="女牧师安妮塔与谁有联系？",a="安妮塔是北郡兄弟会的虔诚成员，与修道院的神职人员和卫兵并肩共事。她以神圣誓言和训练职责为纽带，紧密效忠于圣光教会，并致力于守卫暴风城。",al={"安妮塔的人际关系","安妮塔隶属于谁","安妮塔的阵营关系"}}},fp="16,198,22.352.0,22.369.0,24.204.0,34.179.0,47.201.0,29.171.0"}
P.entries["npc:priestess-josetta"] = {n="女牧师洁塞塔",s="女牧师洁塞塔是一位人类牧师训练师，驻扎在闪金镇的Lion's Pride Inn二楼。她致力于引导圣光的初学者完成他们在北郡修道院的初步试炼，并指导年轻牧师学习信仰、虔诚以及实际的教导工作。",h="女牧师洁塞塔是一位人类牧师训练师，驻扎在闪金镇的Lion's Pride Inn二楼。她致力于引导圣光的初学者完成他们在北郡修道院的初步试炼，并指导年轻牧师学习信仰、虔诚以及实际的教导工作。",kw={"绝望祷言","艾尔文森林","闪金镇","圣光","洁塞塔","lion's pride inn","牧师训练师","女牧师洁塞塔"},ang={["class:Priest"]="洁塞塔是年轻牧师离开北郡修道院后的重要早期导师，提供核心法术训练以及关于将治疗誓言付诸实际服务的指导。",["faction:Alliance"]="洁塞塔加强了联盟在艾尔文森林的中坚力量，确保当地守卫拥有守护这片中心地带所需的精神和治疗支持。",["race:Human"]="人类牧师会在洁塞塔的建议中找到熟悉的圣光教会教义，她帮助他们开始接触祖先的祈祷传统。"},sec={{t="闪金镇的一盏明灯",b="许多立下神圣誓言的人都在宏伟的大教堂或隐修的修道院中度日，而女牧师洁塞塔则直接在艾尔文森林的平民中传道。在熙熙攘攘的Lion's Pride Inn楼上，她那简朴的房间里，她时刻关怀着旅行者、守卫和当地劳动者的心灵健康，以此证明服务于圣光需要亲临那些心灵需要慰藉的地方。"},{t="指引年轻的侍僧",b="对于在北郡修道院完成了初步学业的牧师新秀来说，洁塞塔扮演着至关重要的角色。她向他们传授自身使命的实际现实，派遣他们前往周边的乡村去救助受伤的守卫并安慰受苦的人。通过这些任务，她强调牧师的职责不仅仅是学习祷言，还要积极引导圣光去修补这个破碎的世界。"},{t="一种安静的遗憾",b="尽管保持着坚定的虔诚，洁塞塔对她一生所做的选择仍带着一丝留恋。年轻时，她缺乏勇气踏上更广阔的道路去探索艾泽拉斯，而是选择了熟悉之地的安稳。虽然对自己在闪金镇的神圣服务感到满足，但她经常鼓励那些跨入她门槛的年轻学徒要比她更勇敢，将他们的信仰带往遥远的边疆。"}},faq={{q="在哪里可以找到女牧师洁塞塔？",a="女牧师洁塞塔住在闪金镇的Lion's Pride Inn二楼，位于楼上中央房间，与米歇尔·贝尔在一起。",al={"洁塞塔位置","女牧师洁塞塔在哪里","闪金镇牧师训练师位置"}},{q="女牧师洁塞塔担任什么角色？",a="她是联盟的牧师训练师，在新手牧师从北郡修道院出发闯荡时，指导他们学习神圣法术、戒律以及他们神圣使命的责任。",al={"洁塞塔做什么","女牧师洁塞塔职责"}},{q="为什么洁塞塔在旅店工作而不是教堂？",a="闪金镇没有独立的礼拜堂，所以Lion's Pride Inn充当了城镇中心的角色。驻扎在楼上使得洁塞塔能够直接照料疲惫的旅行者、受伤的城镇守卫和当地居民。",al={"为什么在旅店","为什么在lion's pride inn"}},{q="洁塞塔与学徒分享了什么个人遗憾？",a="她承认自己年轻时从未鼓起勇气离开家乡去周游世界，她鼓励年轻的冒险者去探索艾尔文森林边界之外的世界。",al={"洁塞塔背景故事","洁塞塔旅行遗憾"}},{q="洁塞塔会给新牧师指派什么样的职责？",a="洁塞塔指导侍僧们去照料野外的受伤守卫，教导他们如何用治疗祷言治愈伤口，并强调必须将圣光直接带给那些需要帮助的人。",al={"洁塞塔任务","圣光之衣任务"}},{q="洁塞塔会教授种族牧师法术吗？",a="是的，作为艾尔文森林的一位人类女牧师，她向人类牧师介绍他们种族所偏爱的特殊祷言，例如绝望祷言。",al={"绝望祷言训练师","人类牧师法术"}}},fx={["41d8cc17"]={q="女牧师洁塞塔支持哪一方？",a="女牧师洁塞塔坚定地支持圣光、教会与联盟。她在闪金镇以暴风城的名义行事，致力于指导王国中有志成为牧师的人，确保他们恪守圣誓，为族人与盟友效力。",al={"女牧师洁塞塔的阵营","女牧师洁塞塔属于联盟吗","洁塞塔侍奉谁"}},["165cad46"]={q="女牧师洁塞塔想要什么？",a="女牧师洁塞塔希望培养新一代圣职者的虔诚与自律。她私下里常为年轻时没有勇气漫游艾泽拉斯而遗憾，但她将心力投入到引导你和其他见习者身上，帮助伤者，并将圣光的力量带到闪金镇以外的地方。",al={"洁塞塔的目标是什么","女牧师洁塞塔想要什么","洁塞塔的动机"}}},fp="17,270,21.418.0,22.429.0,14.412.0,35.146.0,39.184.0,59.220.0,55.182.0,55.197.0,40.139.0"}
P.entries["npc:prospector-ironband"] = {n="勘察员基恩萨·铁环",s="勘察员基恩萨·铁环是一位诚实勤恳的矮人测量员，负责监管洛克莫丹东南部的一处考古挖掘场。他在矮人探险者协会的旗帜下工作，一心想要揭开埋藏在卡兹莫丹地底的土灵遗产。尽管面临种种挫折和当地凶猛生物的威胁，铁环仍致力于定期将挖掘进展报告和出土文物送回铁炉堡。",h="勘察员基恩萨·铁环是一位诚实勤恳的矮人测量员，负责监管洛克莫丹东南部的一处考古挖掘场。他在矮人探险者协会的旗帜下工作，一心想要揭开埋藏在卡兹莫丹地底的土灵遗产。尽管面临种种挫折和当地凶猛生物的威胁，铁环仍致力于定期将挖掘...",kw={"阿格蒙德","基恩萨·铁环","挖掘进展报告","挖掘场","探险者协会","铁环","洛克莫丹","勘察员","保护货物"},ang={["faction:Alliance"]="保持铁环挖掘场的补给和防御，有助于确保洛克莫丹东南部地区免受穴居人入侵，并为联盟保存珍贵的文物。",["profession:Mining"]="铁环的挖掘工作使用任何矿工都熟悉的标准镐头和挖沟技术，依靠敏锐的观察力来识别岩石中加工过的石头和被掩埋的岩层。",["race:Dwarf"]="勘察员基恩萨·铁环工作在麦格尼国王推动理解矮人祖先事业的最前线，这使得他的挖掘工作对于每一位铁炉堡的子民来说，都是一件深具文化自豪感的事情。"},sec={{t="挖掘过去",b="基恩萨·铁环领导着位于洛克莫丹东南部群山之中的铁环挖掘场。像探险者协会中的许多实地研究员一样，铁环坚信卡兹莫丹的土壤中隐藏着关于矮人种族起源的重要真相。他的营地不懈地挖掘沟渠、筛查碎石，搜寻古代遗物、石板和土灵制品。尽管挖掘埋藏历史的进程缓慢，但铁环的决心从未动摇，而且他总是渴望招募能干的冒险者来保护他的行动。"},{t="边境困扰",b="在崎岖的荒野中进行挖掘工作从来都不平静。挖掘场不断受到当地穴居人和野生生物的骚扰，威胁到了挖掘工作所需的补给线和设备。文物和珍贵的测量设备总是面临着在被检查前被盗走或损毁的风险。铁环依靠往来的联盟旅人来保护货物运输，抵御敌对掠夺者，并调查在邻近荒地失踪的协会联络员。"}},faq={{q="谁是勘察员基恩萨·铁环？",a="勘察员基恩萨·铁环是一位尽职尽责的矮人测量员，正在洛克莫丹东南部领导一处考古挖掘工作。他代表矮人探险者协会行事，协调实地挖掘工作，以找回失落的泰坦和土灵历史遗物。",al={"铁环传说","谁是基恩萨·铁环","勘察员基恩萨·铁环"}},{q="我可以在哪里找到勘察员基恩萨·铁环？",a="他驻扎在铁环挖掘场，该地点位于洛克莫丹东南部群山中，就在通往南部边界的主路以东。",al={"铁环位置","铁环在哪里","铁环挖掘场位置"}},{q="探险者协会在这里挖掘什么？",a="探险者协会在整个卡兹莫丹挖掘古老的石质遗迹，以拼凑出矮人人民的起源，并揭示泰坦留下的文物。",al={"为什么铁环在挖掘","他们在挖掘什么","铁环挖掘目标"}},{q="为什么铁环需要冒险者来保护货物？",a="挖掘工作严重依赖从塞尔萨玛运往洛克莫丹的爆盐粉和补给品。早先的一批粉末从未抵达，黑铁矮人威胁着路上的搬运工，而当地的穴居人则在骚扰营地本身。",al={"保护货物传说","为什么防御物资","铁环补给"}},{q="阿格蒙德是谁，为什么铁环要打听他？",a="阿格蒙德是另一位矮人测量员，他前往更南方的地区侦察挖掘地点。当与他失去联系后，铁环便招募旅人前往荒地以确定他的下落。",al={"寻找阿格蒙德","谁是阿格蒙德","阿格蒙德的命运"}},{q="勘察员基恩萨·铁环与巴丁·铁环有亲戚关系吗？",a="他们有着相同的姓氏，并且都与边境矮人行动密切相关，这暗示了他们之间存在亲缘关系，尽管基恩萨一心只关注考古业务和协会报告。",al={"巴丁·铁环亲戚","铁环家族","基恩萨与巴丁"}}},fx={["8f75b961"]={q="勘察员基恩萨·铁环支持哪一方？",a="铁环通过矮人探险者协会为铁炉堡和联盟效力。他听命于协会领袖和国王麦格尼·铜须，致力于在卡兹莫丹各地发掘先祖留下的泰坦传说与古代遗物，以造福矮人族人。",al={"铁环的阵营","铁环为谁效力","铁环与联盟"}}},fp="19,416,19.576.0,17.487.0,27.256.0,37.159.0,46.173.0,56.233.0,50.180.0,50.186.0"}
P.entries["npc:prospector-remtravel"] = {n="勘察员雷姆塔维尔",s="勘察员雷姆塔维尔是一位隶属于探险者协会的矮人考古学家，驻扎在黑海岸阴暗的丛林深处。他负责管理一处发掘远古遗物的考古点，但他常常心不在焉，且身处险境，因此总是需要旁人的帮助。",h="勘察员雷姆塔维尔是一位隶属于探险者协会的矮人考古学家，驻扎在黑海岸阴暗的丛林深处。他负责管理一处发掘远古遗物的考古点，但他常常心不在焉，且身处险境，因此总是需要旁人的帮助。",kw={"心不在焉的勘察员","黑海岸","探险者协会","化石","铁炉堡","勘察员雷姆塔维尔","雷姆塔维尔","雷姆塔维尔的挖掘"},ang={["race:Dwarf"]="雷姆塔维尔代表了探险者协会拼凑矮人起源的不懈决心，即便这意味着要在卡利姆多阴冷潮湿的树林里搭帐篷。",["race:NightElf"]="虽然暗夜精灵容忍友好的联盟客人，但协会嘈杂的挖掘和对古老土地的扰动，往往在考验着当地哨兵和德鲁伊的耐心。"},sec={{t="精灵土地上的矮人挖掘",b="受探险者协会之命，勘察员雷姆塔维尔远渡重洋，在黑海岸的南部边缘建立了自己的挖掘点。虽然暗夜精灵通常会保护他们的祖传领地，但协会对于揭开艾泽拉斯起源的无尽渴求，推动着勘察员们深入每一个被遗忘的角落。雷姆塔维尔的工作挖掘出了化石历史和古老的石碑，但好斗的本土野生动物和当地的敌对势力，让这个心不在焉的矮人几乎无法独自应付这项边境发掘工作。"},{t="心不在焉的学者",b="正如他的名声所传，雷姆塔维尔很容易沉浸在自己的思绪和研究笔记中。为了寻找化石或失落的文物而冒险远离营地，往往会导致灾难，使他被掠食者或敌对生物困住。那些在野外遇到他的人，通常不得不承担起守护他那脆弱发现的任务，并在黑海岸的危险结束他的使命之前，先救出这位勘察员。"}},faq={{q="勘察员雷姆塔维尔是谁？",a="他是一位来自铁炉堡的考古学家和测量员，代表着探险者协会。他在黑海岸南部建立了一个小型挖掘营地，旨在发掘远古遗物和化石。",al={"雷姆塔维尔是谁","雷姆塔维尔背景故事","黑海岸的矮人是谁"}},{q="为什么铁炉堡的矮人会在黑海岸挖掘？",a="探险者协会正在搜寻世界各地，寻找泰坦文物、失落的历史和古老的化石。黑海岸是一片与遥远的过去有着深厚联系的古老废墟之地，是矮人进行考古调查的首选地点。",al={"为什么矮人在黑海岸","探险者协会在黑海岸做什么","为什么在这里挖掘"}},{q="为什么说他心不在焉？",a="雷姆塔维尔在专注于学术研究时，往往会忽略周围的环境和自己的装备。他经常在没有意识到掠食者和野兽正在逼近的情况下，误入危险的领地。",al={"为什么心不在焉","雷姆塔维尔疯了吗","雷姆塔维尔发生了什么"}},{q="勘察员雷姆塔维尔与协会中的任何人有关系吗？",a="据信他就是卡娜·雷姆塔维尔所提到的那位富有冒险精神的叔叔。卡娜·雷姆塔维尔也是一位探险家，她将自己对探索和广阔世界的激情归功于她叔叔的启发。",al={"雷姆塔维尔的家人","卡娜·雷姆塔维尔的叔叔","卡娜·雷姆塔维尔是谁"}}},fx={a4e27c5f={q="勘察员雷姆塔维尔支持哪一方？",a="勘察员雷姆塔维尔是铁炉堡的忠诚臣民，也是矮人探险者协会的成员。由于铁炉堡与达纳苏斯同属联盟，他得以在暗夜精灵领地公开活动，依靠友善的旅人协助研究，并抵御当地的危险。",al={"勘察员雷姆塔维尔的阵营","雷姆塔维尔侍奉谁","雷姆塔维尔与联盟"}},a325ae20={q="勘察员雷姆塔维尔想要什么？",a="和探险者协会的许多成员一样，雷姆塔维尔在陌生的土地上寻找埋藏的古代遗物与地质奇观。他决心揭开黑海岸地表下的历史，不过他常常专注于发现，以至于忽视了在挖掘地点附近徘徊的眼前危险。",al={"雷姆塔维尔在寻找什么","雷姆塔维尔的目标","雷姆塔维尔为什么挖掘"}}},fp="20,292,28.532.0,25.452.1,28.190.0,47.243.0,31.230.0,56.168.0"}
P.entries["npc:prospector-ryedol"] = {n="勘察员雷杜尔",s="勘察员雷杜尔是探险者协会的一名测量员，驻扎在俯瞰东部荒芜之地的一处尘土飞扬的小高地上。他守望着下方危机四伏的挖掘场，努力寻找失落的矮人遗物，并在这片被穴居人和野兽肆虐的荒原上维持着希望。",h="勘察员雷杜尔是探险者协会的一名测量员，驻扎在俯瞰东部荒芜之地的一处尘土飞扬的小高地上。他守望着下方危机四伏的挖掘场，努力寻找失落的矮人遗物，并在这片被穴居人和野兽肆虐的荒原上维持着希望。",kw={"荒芜之地","挖掘场","探险者协会","铁趾","铁炉堡","勘察员雷杜尔","雷杜尔"},ang={["faction:Alliance"]="对于穿越荒芜之地危险荒野的联盟冒险者来说，雷杜尔提供了一个友好的面孔，并分派了一些紧急的任务以支持探险者协会。",["race:Dwarf"]="即使是在卡兹莫丹最严酷的地区进行挖掘，雷杜尔也代表了铁炉堡发掘矮人种族起源的不屈动力。"},sec={{t="守望挖掘场",b="勘察员雷杜尔栖身于铁趾挖掘场南侧的一座崎岖山丘上，代表铁炉堡探险者协会在荒芜之地开展持续的努力。这片干旱的峡谷蕴藏着丰富的古代泰坦秘密和土灵遗产，但实地考察队常年遭受野蛮的穴居人、贪婪的土狼和领地意识极强的幼龙的骚扰。雷杜尔负责协调被黑铁矮人偷走的矮人装备的回收工作，并在废弃的前哨站中寻找希望的迹象，决心不让探险者协会在荒野中的牺牲白费。"}},faq={{q="勘察员雷杜尔是谁？",a="雷杜尔是一名隶属于探险者协会的矮人实地研究员。他在荒芜之地东部俯瞰铁趾挖掘场的一座高地上建立了营地，协助指导打捞和回收任务。",al={"雷杜尔","雷杜尔是谁","勘察员雷杜尔的位置"}},{q="雷杜尔在荒芜之地做什么？",a="他驻扎在荒芜之地以支持探险者协会的考古事业。由于附近的一些挖掘场遭到黑铁矮人和穴居人的破坏或占领，他与旅行者合作以确保回收遗物，追踪丢失的工具，并核实他同胞矮人的下落。",al={"雷杜尔在做什么","雷杜尔的任务","雷杜尔为什么在这里"}},{q="什么是雷杜尔的铁锤？",a="雷杜尔的铁锤是因找回他被攻击铁趾挖掘场的黑铁矮人抢走的幸运镐而给予的奖励。被偷的东西是他的鹤嘴锄，而不是作为奖励的铁锤。",al={"雷杜尔的铁锤","矮人和他的工具"}}},fp="17,268,22.553.0,25.209.0,37.289.0,24.170.0"}
P.entries["npc:prospector-stormpike"] = {n="勘察员塔伯斯·雷矛",s="勘察员塔伯斯·雷矛是一位言语生硬、脾气暴躁的矮人，常驻于铁炉堡的探险者大厅图书馆内。作为著名的雷矛部族的一员，他负责监督遥远考古挖掘点的后勤补给，并以其敏锐的头脑协助破译加密密信。",h="勘察员塔伯斯·雷矛是一位言语生硬、脾气暴躁的矮人，常驻于铁炉堡的探险者大厅图书馆内。作为著名的雷矛部族的一员，他负责监督遥远考古挖掘点的后勤补给，并以其敏锐的头脑协助破译加密密信。",kw={"阿古斯觉醒","探险者协会","hall of explorers","铁炉堡","乔伦·铁环","图书馆","勘察员塔伯斯·雷矛","雷矛部族"},ang={["faction:Alliance"]="除了挖掘工作外，雷矛的密码学专长还协助联盟在北方对抗像阿古斯觉醒这样的阴暗人类教派的行动。",["race:Dwarf"]="雷矛体现了探险者协会那种干练、务实且严谨的精神，他将古代研究和后勤工作视为矮人至高无上的荣耀。"},sec={{t="探险者大厅学者",b="勘察员塔伯斯·雷矛躲在探险者大厅高耸的书架之间，负责协调整个卡兹莫丹及其他地区的挖掘工作。尽管他态度粗鲁，且对闲聊毫无耐心，但他却对发掘矮人历史有着极深的执着，并坚持为远方的挖掘点提供炸药等必需品。在他粗犷的外表下，隐藏着一颗精于破解复杂密码的敏锐分析头脑，这使他成为联盟侦察兵应对隐秘威胁时不可或缺的资产。"}},faq={{q="勘察员塔伯斯·雷矛是谁？",a="他是属于著名的雷矛部族的一名考古学家兼后勤协调员，常驻于铁炉堡探险者大厅的图书馆区。",al={"谁是雷矛","勘察员塔伯斯·雷矛背景故事","雷矛npc"}},{q="在哪里可以找到勘察员塔伯斯·雷矛？",a="他位于铁炉堡东侧的探险者大厅内，守在图书馆里。",al={"雷矛位置","勘察员塔伯斯·雷矛在哪里"}},{q="他从事什么样的工作？",a="雷矛负责处理考古挖掘的补给线和报告——例如向洛克莫丹的勘察员基恩萨·铁环等前线勘察员输送炸药——并协助破译侦察兵带回的复杂加密信息。",al={"雷矛任务","雷矛做什么"}},{q="为什么南海镇需要他的帮助？",a="南海镇的联盟当局依靠他的密码学专长，来破译由神秘的阿古斯觉醒教派成员所编写的截获信件。",al={"阿古斯觉醒密码","南海镇雷矛"}}},fx={["676ebbc6"]={q="勘察员塔伯斯·雷矛效忠于哪一方？",a="勘察员塔伯斯·雷矛忠于铁炉堡王国和联盟。作为矮人探险者协会的一名成员，他在外执行任务和进行考古研究，都是为了服务国王麦格尼·铜须和矮人王国的利益。",al={"雷矛阵营","勘察员塔伯斯·雷矛与联盟","雷矛效忠于谁"}},b4a2ac01={q="勘察员塔伯斯·雷矛想要什么？",a="勘察员塔伯斯·雷矛希望破译重要情报，并在不受无谓干扰的情况下协调考古远征。他负责监督诸如洛克莫丹的铁环挖掘场等挖掘点的研究，还运用密码分析专长破解编码信息。他要求全神贯注，对无所事事的干扰毫无耐心。",al={"雷矛需要什么","勘察员塔伯斯·雷矛的目标","雷矛的动机"}},["1b565b81"]={q="勘察员塔伯斯·雷矛为什么在铁炉堡？",a="你可以在铁炉堡的探险者大厅图书馆找到勘察员塔伯斯·雷矛，因为那里是探险者协会的行动中枢。他在此审阅外勤报告、翻译寻获的遗物，并破译需要学者研究的截获信件。",al={"雷矛为什么在这里","勘察员塔伯斯·雷矛与图书馆","雷矛为什么在探险者大厅"}},dbd365e1={q="勘察员塔伯斯·雷矛与哪些人有联系？",a="他是颇具影响力的雷矛氏族成员，这一备受尊崇的矮人家族在卡兹莫丹享有盛名。除了氏族关系，他还与勘察员基恩萨·铁环等外勤勘察员直接合作，并通过破解敌方密码协助南海镇的联盟领袖。",al={"雷矛氏族关系","勘察员塔伯斯·雷矛的盟友","雷矛与探险者协会的关系"}},d5ca9c54={q="勘察员塔伯斯·雷矛为何闻名或令人畏惧？",a="勘察员塔伯斯·雷矛以出色地破译复杂加密文书而闻名，同时也以脾气暴烈著称。很少有学者能像他一样，既拥有敏锐的密码分析头脑，又对任何浪费他时间的人毫无耐心。",al={"雷矛的声望","勘察员塔伯斯·雷矛为何闻名","雷矛的暴脾气"}}},fp="20,286,32.511.0,28.152.0,38.118.0,29.253.0,34.141.0"}
P.entries["npc:prospector-whelgar"] = {n="勘察员维尔加",s="勘察员维尔加是一位矮人考古学家，驻扎在米奈希尔港以东湿地的一处挖掘场。由于凶猛的迅猛龙占领了挖掘场，他挖掘泰坦遗物的任务被迫停滞。他现在正寻找勇敢的冒险者，希望能对付这些野兽，并找回古代文物。",h="勘察员维尔加是一位矮人考古学家，驻扎在米奈希尔港以东湿地的一处挖掘场。由于凶猛的迅猛龙占领了挖掘场，他挖掘泰坦遗物的任务被迫停滞。他现在正寻找勇敢的冒险者，希望能对付这些野兽，并找回古代文物。",kw={"矮人","挖掘场","探险者协会","戈阿兹之石","勘察员维尔加","发掘过去","湿地","维尔加"},ang={["profession:Mining"]="维尔加挖掘场周围嶙峋的山脊蕴含着丰富的矿脉，不过勘察员们必须应对同样困扰着维尔加团队的迅猛龙。",["race:Dwarf"]="维尔加的任务直接服务于探险者协会以及国王麦格尼·铜须对矮人泰坦起源的持续探索。"},sec={{t="被围困的挖掘场",b="勘察员维尔加被派往湿地的沼泽荒野中，旨在发掘矮人种族的历史，并建立了被称为维尔加挖掘场的考古营地。山谷曾经拥有丰富的古代石制遗物，但当地的迅猛龙迅速占领了领地，迫使他的团队躲藏起来。尽管危险重重，维尔加拒绝放弃他的职责。他仍然专注于回收珍贵的文物——包括神秘的戈阿兹之石——以防野生掠食者或敌对的恶棍彻底摧毁该遗址。"}},faq={{q="勘察员维尔加是谁？",a="勘察员维尔加是一位铁炉堡矮人考古学家，受命在湿地领导一支探险队。他负责监督米奈希尔港以东的挖掘场，研究矮人历史黎明时期的遗物。",al={"维尔加","维尔加是谁","勘察员维尔加背景故事"}},{q="我在哪里可以找到勘察员维尔加？",a="他避难于俯瞰维尔加挖掘场的一处山脊上，位于湿地米奈希尔港以东、丹莫德西南方。",al={"维尔加位置","维尔加在哪里","维尔加湿地地图"}},{q="为什么维尔加在挖掘场遇到麻烦？",a="凶猛的本地迅猛龙已经完全占领了挖掘场，杀死了或驱散了他的船员，迫使维尔加进入防御状态。没有外界的保护，他无法继续发掘遗物。",al={"迅猛龙挖掘场","维尔加挖掘场发生了什么","维尔加挖掘场迅猛龙"}},{q="什么是戈阿兹之石？",a="戈阿兹之石是在挖掘场遗迹中发现的一件古代文物。维尔加致力于翻译其碑文，以更好地了解矮人种族被遗忘的起源和古代历史。",al={"戈阿兹之石","什么是戈阿兹之石","发掘过去遗物"}}},fx={["430ccc65"]={q="勘察员维尔加效忠于哪一方？",a="勘察员维尔加坚定地效忠于铁炉堡和联盟。和其他矮人勘察员一样，他进行远征是为了矮人的遗产和探险者协会，代表族人发掘古老历史。",al={"维尔加的阵营","维尔加属于联盟吗","维尔加效忠于谁"}},["3be180e4"]={q="勘察员维尔加想要什么？",a="维尔加希望安全地进行挖掘，并发掘过去的遗物，尤其是弄清戈阿兹之石这类古代遗物的奥秘。然而，当地威胁不断阻碍他的考古工作，例如肆虐挖掘场的迅猛龙。",al={"维尔加需要什么","维尔加的目标","维尔加的目的"}},["3a0c9faf"]={q="勘察员维尔加为什么在湿地？",a="他来到湿地，负责挖掘该地区的古代遗迹。他在此建立了挖掘场，以发掘矮人古代文明的遗物，但凶猛的野生动物和当地的险境严重阻碍了他的远征。",al={"维尔加为什么在湿地","维尔加挖掘的目的"}},bbf3af84={q="勘察员维尔加与哪些人有联系？",a="维尔加与铁炉堡的矮人考古计划有联系，与其他矮人勘察员和研究人员并肩合作，在卡兹莫丹及更远的地方调查泰坦遗迹和古代泰坦造物遗迹。",al={"维尔加所属组织","维尔加的隶属关系","维尔加向谁汇报"}}},fp="18,294,17.523.0,26.205.0,36.128.0,46.200.0,23.217.0"}
P.entries["npc:quartermaster-lewis"] = {n="军需官刘易斯",s="军需官刘易斯是一位驻扎在西部荒野哨兵岭的人类物资商人。他服务于当地的人民军，为那些试图在边境抵抗迪菲亚潜行者的旅行者和守卫者提供口粮、弹药和日常补给。",h="军需官刘易斯是一位驻扎在西部荒野哨兵岭的人类物资商人。他服务于当地的人民军，为那些试图在边境抵抗迪菲亚潜行者的旅行者和守卫者提供口粮、弹药和日常补给。",kw={"刘易斯","人民军","军需官刘易斯","哨兵岭","sentinel tower","商人","西部荒野"},ang={["class:Hunter"]="刘易斯是西部荒野中部重要的射击补给前线联络人，为远程守卫者储备了基础的弹丸和箭矢。",["faction:Alliance"]="对于冒险进入西部荒野的联盟新兵来说，刘易斯在这一敌对领土上提供了一个必要的补给点，这里的官方王室资源极其匮乏。"},sec={{t="哨塔物资守护者",b="军需官刘易斯驻扎在Sentinel Tower内，管理着西部荒野民兵那微薄的后勤补给线。由于暴风城的皇室高层几乎没有给这个贫困地区提供什么援助，哨兵岭只能依靠当地的志愿者以及他们能收集到的任何补给。刘易斯负责分发标准的野战必需品，从干粮和淡水到箭矢、弹丸和投掷武器，确保守卫战斗的人员拥有在迪菲亚潜行者突袭下生存的基本物资。"}},faq={{q="军需官刘易斯是谁？",a="他是驻扎在西部荒野Sentinel Tower的军需官。刘易斯负责为人民军以及任何协助他们防御的冒险者处理日常补给、口粮和武器装备。",al={"军需官刘易斯背景故事","刘易斯是谁","哨兵岭军需官"}},{q="军需官刘易斯出售什么？",a="他担任综合商品商人，提供基本的生存物品，如面包、牛奶、水、背包、燧石，以及各种远程弹药，如箭矢、子弹和投掷匕首。",al={"刘易斯出售什么","刘易斯库存","西部荒野商人商品"}},{q="他在地区任务中扮演什么角色？",a="由于暴风城几乎没有直接提供援助，刘易斯会让冒险者通过狮鹫管理员索尔前往暴风城的Old Town，将一封信交给他的护甲供应商奥斯瑞克·斯图恩，并将奥斯瑞克的箱子运回哨兵岭。",al={"刘易斯任务","迅捷的信件","返回刘易斯处"}},{q="刘易斯属于暴风城军队吗？",a="和哨兵岭的大多数守卫者一样，刘易斯服务于人民军，而非暴风城王室派出的正式分遣队。该地区基本上只能依靠自己来抵御迪菲亚潜行者。",al={"刘易斯是军队人员吗","暴风城卫兵刘易斯","人民军刘易斯"}}},fx={f4ce3c2d={q="军需官刘易斯为什么驻扎在这里？",a="军需官刘易斯驻扎在西部荒野的哨兵岭，为人民军和途经此地的联盟冒险者提供补给。西部荒野大部分地区已被王室弃置，又遭迪菲亚潜行者横行，驻守塔楼的守军依靠刘易斯提供重要的口粮、弹药和生存物资。",al={"刘易斯为什么在这里","军需官刘易斯为何在西部荒野","军需官刘易斯为何在哨兵塔"}}},fp="19,270,28.480.0,27.189.0,35.199.0,36.245.0,36.217.0"}
P.entries["npc:quinn-yorick"] = {n="奎恩·尤瑞克",s="奎恩·尤瑞克是一名受伤的被遗忘者侦察兵，他躲在伊瓦农场一间破败农舍的楼上。在与被称为“污秽者”伊瓦的食尸鬼遭遇后，他侥幸活了下来，如今只能依靠路过的盟友来帮助他保住性命。",h="奎恩·尤瑞克是一名受伤的被遗忘者侦察兵，他躲在伊瓦农场一间破败农舍的楼上。在与被称为“污秽者”伊瓦的食尸鬼遭遇后，他侥幸活了下来，如今只能依靠路过的盟友来帮助他保住性命。",kw={"被遗忘者侦察兵","食尸鬼","伊瓦农场","污秽者伊瓦","奎恩·尤瑞克","银松森林"},ang={["race:Undead"]="奎恩的困境凸显了该地区的食尸鬼和野兽对试图控制银松森林北部的被遗忘者部队所造成的长期威胁。"},sec={{t="危险的避难所",b="奎恩·尤瑞克躲在伊瓦农场的一间废弃房屋里，身受重伤，躺在楼上。他的伤势源于与“污秽者”伊瓦的恶战，那是一只潜伏在银松森林北部农场谷仓里的食尸鬼。奎恩此前受命与他的妹妹兰妮一起前往银松森林进行侦察并向高级执行官哈德瑞克汇报，但他现在无法独自完成任务或安全撤离，只能躲藏起来，等待为被遗忘者效力的旅人们为他带来治疗，并解决那个差点杀掉他的生物。"}},faq={{q="奎恩·尤瑞克在哪里？",a="奎恩·尤瑞克躲在伊瓦农场的一间破旧农舍楼上，该农场位于瑟伯切尔北部的银松森林。",al={"奎恩·尤瑞克位置","奎恩在哪里","奎恩·尤瑞克的屋子"}},{q="是谁伤了奎恩·尤瑞克？",a="他是被“污秽者”伊瓦打成重伤的，那是一只潜伏在农场谷仓里的凶残食尸鬼。",al={"谁攻击了奎恩","奎恩·尤瑞克发生了什么","奎恩受伤"}},{q="奎恩为部落冒险者扮演什么角色？",a="奎恩的妹妹，死亡猎手兰妮·尤瑞克会派遣冒险者带给他治疗药水。在他服下药水后，她会要求冒险者杀死“污秽者”伊瓦，以便让奎恩有时间恢复。",al={"奎恩·尤瑞克任务","奎恩任务发布者"}}},fx={["63631c13"]={q="奎恩·尤瑞克是谁？",a="奎恩·尤瑞克是一名被遗忘者死亡猎手，躲藏在伊瓦农场一栋破败农舍的楼上。他与姐姐Rane在银松森林侦察时被食尸鬼Ivar the Foul重伤，便藏身于阴影之中，依靠前来此地的部落旅人施以援手，等待伤势恢复。",al={"奎恩是谁","奎恩·尤瑞克的背景故事","奎恩·尤瑞克是谁"}},f58f2509={q="奎恩·尤瑞克效忠于哪一方？",a="奎恩效忠于希尔瓦娜斯·风行者女王和被遗忘者，也因此效忠于部落。他欢迎偶然来到这座偏僻农庄的部落勇士，并寻求他们帮助自己对付藏身于避难所外的野蛮威胁。",al={"奎恩·尤瑞克的阵营","奎恩·尤瑞克属于部落吗","奎恩·尤瑞克的效忠对象"}},cd20af14={q="奎恩·尤瑞克为什么在这里？",a="奎恩和他的姐姐Rane奉命前往银松森林侦察，并向高级执行官哈德瑞克汇报，但他们在这座农场遭到了Ivar the Foul袭击，奎恩被严重撕伤。他无法轻易脱身，也不能独自继续前进，于是躲进废弃农舍的二楼求生。",al={"奎恩·尤瑞克为什么在伊瓦农场","奎恩·尤瑞克在这里的目的","奎恩为什么在楼上"}},e4d12614={q="奎恩·尤瑞克想要什么？",a="奎恩身负重伤，只能留在原地养伤。他希望有时间康复，以便再次上路。冒险者带来的治疗药水让他开始恢复，而他的姐姐Rane则请求他们杀死Ivar the Foul，以免这只食尸鬼回来找他。",al={"奎恩想要什么","奎恩·尤瑞克的目标","奎恩·尤瑞克的目的"}}},fp="12,247,19.526.0,30.145.0,25.92.0,49.187.0"}
P.entries["npc:raene-wolfrunner"] = {n="莱恩·狼行者",s="莱恩·狼行者是一位出色的哨兵军官兼猎人，驻扎在灰谷阿斯特兰纳的核心区域。她带着自己忠诚的座狼和刃豹同伴，协调着森林各处的防御工作，抵御部落入侵者和受到腐蚀的熊怪部族。对于那些努力保卫这片神圣荒野的联盟勇士们来说，她是一个至关重要的支柱。",h="莱恩·狼行者是一位出色的哨兵军官兼猎人，驻扎在灰谷阿斯特兰纳的核心区域。她带着自己忠诚的座狼和刃豹同伴，协调着森林各处的防御工作，抵御部落入侵者和受到腐蚀的熊怪部族。对于那些努力保卫这片神圣荒野的联盟勇士们来说，她是一个...",kw={"灰谷","阿斯特兰纳","达格里","达图尔","科拉","莱恩","哨兵","特罗尼斯","蓟皮熊怪","狼行者"},ang={["class:Hunter"]="作为一名既能指挥座狼又能指挥刃豹的资深猎人，莱恩代表了其职业所推崇的荒野掌控力和与野兽之间的深厚羁绊。",["faction:Alliance"]="对于从黑海岸抵达的联盟旅行者来说，莱恩是负责协调灰谷军事与生态防御的主要军官。",["race:NightElf"]="莱恩体现了哨兵对艾露恩和卡利姆多荒野的忠诚，她决不允许灰谷的林地圣所遭到破坏。"},sec={{t="阿斯特兰纳的保卫者",b="莱恩·狼行者与她值得信赖的刃豹科拉和座狼达格里一起在阿斯特兰纳保持警惕。作为哨兵部队中的一名军官，她负责监管整个灰谷的巡逻任务，并协调与灰谷边界之外的情报工作，将像凯拉·影矛这样的斥候派往石爪山脉等邻近地区。"},{t="遏制森林的腐蚀",b="除了与部落之间的紧张关系外，莱恩还非常关注灰谷当地生物所遭受的黑暗腐蚀。她指挥着针对敌对熊怪部族的行动，包括对骚扰旅行者的木喉熊怪营地进行猛烈打击，以及针对日益壮大的蓟皮熊怪首领进行定点清除。她麾下的斥候密切监视着熊怪行为的变化，依靠莱恩稳健的指挥来保护当地定居点和过往的行旅免遭有组织的伏击。"},{t="达图尔的变形杖",b="莱恩最私人的使命与达图尔的变形杖有关，这是一件与熊怪净化相关的古代遗物。她的老友特罗尼斯在寻找这根法杖缺失的宝石时被杀，这促使莱恩下令找回他的遗体，并承诺要完成他的遗愿。她与树妖莎尔蒂恩通力合作，帮助勇士们重组这件遗物，最终使冒险者能够伪装成熊怪，与酋长克罗格进行商谈，并击败被腐蚀的首领兰·血牙，从而清除该地区的威胁。"}},faq={{q="莱恩·狼行者在哪里？",a="莱恩驻扎在灰谷的暗夜精灵中心城镇阿斯特兰纳。她站在户外，随时准备着，身边还有她的两只动物同伴陪伴。",al={"莱恩·狼行者位置","莱恩在哪里","阿斯特兰纳的莱恩"}},{q="站在莱恩身边的动物是什么？",a="它们是她训练有素的狩猎同伴：一只名叫科拉的刃豹和一只名叫达格里的座狼，它们一直陪伴在阿斯特兰纳的她身边。",al={"莱恩·狼行者的宠物","莱恩的狼和猫","莱恩的同伴"}},{q="莱恩在哨兵部队中担任什么角色？",a="她是灰谷中部的一名高级哨兵军官，负责向斥候下达命令、管理哨所，并协调针对当地威胁的战术行动。",al={"莱恩的军衔","莱恩是军官吗","莱恩哨兵职责"}},{q="莱恩的朋友特罗尼斯发生了什么事？",a="特罗尼斯在执行协助哨兵部队的任务时，去寻找达图尔的变形杖所需的一颗宝石。他在野外被杀，莱恩随后找回了他的遗体并完成了他的使命。",al={"谁是特罗尼斯","莱恩的朋友特罗尼斯","特罗尼斯之死"}},{q="为什么莱恩如此专注于对付熊怪？",a="像木喉熊怪和蓟皮熊怪这样受到腐蚀的部族变得越来越具有侵略性，它们伏击森林道路上的旅行者，并威胁着阿斯特兰纳的稳定。",al={"莱恩熊怪任务","为什么要与蓟皮熊怪战斗","灰谷的木喉熊怪问题"}},{q="达图尔的变形杖在她的任务线中有什么作用？",a="重组后的法杖允许冒险者暂时伪装成熊怪，从而能够与克罗格进行沟通，以定位并消灭受到腐蚀的酋长兰·血牙。",al={"达图尔的变形杖用途","达图尔的变形杖有什么用","莱恩的净化之杖"}}},fx={["0f58d83b"]={q="莱恩·狼行者效忠于哪一方？",a="莱恩是暗夜精灵和联盟的坚定守护者。作为哨兵中的一名军官，她在阿斯特兰纳协调巡逻和防御，一心保护族人，将逼近的威胁赶出古老的森林。",al={"莱恩·狼行者的阵营","莱恩属于联盟吗","莱恩为谁而战"}},c8e1b22c={q="莱恩·狼行者想要什么？",a="莱恩希望净化灰谷的腐化，并确保阿斯特兰纳免受周边威胁。她决心完成已故同伴特洛尼斯未竟的工作，清剿凶猛之痕和刺鬃等敌对熊怪部族，并保护荒野圣洁，不让它遭受玷污。",al={"莱恩·狼行者的目标","莱恩想做什么","莱恩·狼行者的目的"}},eb1515b1={q="莱恩·狼行者为什么在灰谷？",a="莱恩驻扎在阿斯特兰纳，希望减轻古老森林中蔓延的腐化。她深切关注灰谷的安危，指挥哨兵斥候、击退遭到腐化的熊怪袭击，并统筹应对荒野中不断涌现的威胁。",al={"莱恩为什么在阿斯特兰纳","莱恩为什么来到灰谷","莱恩·狼行者的背景"}},["86b9293d"]={q="莱恩·狼行者与哪些人有联系？",a="莱恩指挥当地的哨兵和斥候，包括凯拉·影矛和Selarin。她与已故的特洛尼斯情谊深厚，也与树妖莎尔蒂恩保持友好而相互尊重的关系。",al={"莱恩·狼行者的盟友","莱恩的朋友","谁认识莱恩"}}},fp="16,377,21.334.0,32.500.0,12.519.1,36.138.0,43.125.0,42.165.0,40.169.1,49.166.0,53.180.1"}
P.entries["npc:ragnar-thunderbrew"] = {n="拉格纳·雷酒",s="拉格纳·雷酒是卡拉诺斯著名的雷酒酿制厂的矮人酿酒师及合伙人。他因供应家族标志性的啤酒烤猪排而闻名于丹莫罗，始终忙于维持酒馆的供应，让顾客感到满意。",h="拉格纳·雷酒是卡拉诺斯著名的雷酒酿制厂的矮人酿酒师及合伙人。他因供应家族标志性的啤酒烤猪排而闻名于丹莫罗，始终忙于维持酒馆的供应，让顾客感到满意。",kw={"麦酒","啤酒烤猪排","丹莫罗","矮人","葛瑞姆·雷酒","卡拉诺斯","拉格纳·雷酒","雷酒酿制厂"},ang={["profession:Cooking"]="拉格纳以雷酒家族的啤酒烤猪排食谱而闻名，对于想要掌握丰盛矮人酒馆菜肴的厨师来说，他是一位值得结交的对象。",["race:Dwarf"]="对于路过丹莫罗的矮人来说，拉格纳的酒馆就像家一样，展示着这个家族所能提供的最好的麦酒和烤肋排。"},sec={{t="卡拉诺斯好客之柱",b="拉格纳·雷酒身处卡拉诺斯的雷酒酿制厂内，管理着这里的烹饪名声以及家族的酿酒业务。酿酒厂是当地山地猎人、旅行冒险者和从诺莫瑞根逃难而来的侏儒们主要的聚会场所。他职责中最重要的一项便是烹制家族那道远近闻名的啤酒烤猪排，这道丰盛的丹莫罗特色菜是用浓郁的矮人麦酒烹饪而成的。然而，维持稳定的食材供应变得困难重重；他原本的肉类供应商应征加入了国王的军队，这使得拉格纳不得不依靠路过的山地猎人和猎手们来为厨房提供新鲜的岩猪腰肉。"},{t="雷酒的传承",b="在整个铁炉堡领地，雷酒之名就是矮人酒精和酒馆文化的代名词。自他的哥哥葛瑞姆·雷酒几年前在一次醉酒后失踪以来，拉格纳便一直经营着这家家族酿酒厂，捍卫着家族严密守护的酿酒传统，抵抗着像黑铁矮人这样的盗贼，他们曾偷走了雷酒拉格啤酒的配方。在面对躁动不安的顾客、中断的供应线以及吵闹的酒馆纠纷时，拉格纳依然稳稳地把持着酒桶，确保没有旅客会空着杯子或饿着肚子离开卡拉诺斯。"}},faq={{q="拉格纳·雷酒是谁？",a="拉格纳·雷酒是一位矮人酿酒师，也是卡拉诺斯雷酒酿制厂的合伙人。他经营着酒馆，并负责烹制家族那道著名的麦酒烤猪排。",al={"拉格纳是谁","拉格纳·雷酒的角色","拉格纳 卡拉诺斯"}},{q="拉格纳为什么在寻找猪排？",a="拉格纳固定的肉类供应商应征加入了麦格尼国王的军队，导致厨房食材短缺。为了满足饥肠辘辘的顾客，他会向路过的猎人和旅行者购买新鲜的猪肉。",al={"为什么要猪肉","啤酒烤猪排任务","猪排供应"}},{q="拉格纳与葛瑞姆·雷酒是什么关系？",a="葛瑞姆是拉格纳的哥哥。他们的父亲阿基勒斯创立了雷酒酿制厂，自葛瑞姆几年前在一次醉酒后失踪以来，拉格纳便一直经营着酿酒厂。",al={"拉格纳和葛瑞姆","葛瑞姆·雷酒的关系"}},{q="拉格纳·雷酒在哪里？",a="拉格纳位于丹莫罗中部雪山环抱的卡拉诺斯村里的雷酒酿制厂内。",al={"拉格纳位置","哪里可以找到拉格纳·雷酒"}}},fx={a4e8a35c={q="拉格纳·雷酒效忠于哪一方？",a="拉格纳坚定地支持铁炉堡和联盟。他在卡拉诺斯经营，为常来酿酒厂的矮人旅客、登山者和当地巡逻队提供服务。",al={"拉格纳·雷酒的阵营","拉格纳与联盟的关系","拉格纳对联盟友好吗"}},["6e9b3705"]={q="拉格纳·雷酒为什么在卡拉诺斯？",a="拉格纳在卡拉诺斯经营雷酒酿制厂。作为共同所有者，他在当地旅店工作，酿造矮人麦酒、准备丰盛的餐食，并打理家族在丹莫罗繁忙的生意。",al={"拉格纳为什么在卡拉诺斯","拉格纳·雷酒在此地的目的","拉格纳在卡拉诺斯做什么"}},["6804fc69"]={q="拉格纳·雷酒为何出名？",a="拉格纳以掌握家传秘方而闻名，这道秘方用于制作啤酒烤猪排，是丹莫罗最著名、最受喜爱的矮人传统美食之一。",al={"拉格纳为何出名","拉格纳·雷酒的名气","雷酒为何出名"}}},fp="18,264,32.668.0,22.582.0,26.187.0,36.187.0,47.197.0,36.131.0"}
P.entries["npc:rahauro"] = {n="拉哈罗",s="拉哈罗是一位牛头人侍从，常驻于雷霆崖的长者高地，忠诚地侍奉着长者玛加萨·野性图腾。他代表玛加萨招募勇敢的冒险者，前往奥格瑞玛地下的怒焰裂谷。他协调各方力量，以报复充满敌意的穴居人，并找回属于他主子阵亡特工的遗失物品。",h="拉哈罗是一位牛头人侍从，常驻于雷霆崖的长者高地，忠诚地侍奉着长者玛加萨·野性图腾。他代表玛加萨招募勇敢的冒险者，前往奥格瑞玛地下的怒焰裂谷。他协调各方力量，以报复充满敌意的穴居人，并找回属于他主子阵亡特工的遗失物品。",kw={"长者高地","恐怖图腾","玛加萨","玛尔","怒焰裂谷","拉哈罗","书包","雷霆崖","穴居人"},ang={["faction:Horde"]="拉哈罗为雷霆崖的部落成员提供早期的地下城任务，将牛头人领导层的利益与奥格瑞玛兽人主城的防御结合起来。",["race:Tauren"]="对于在雷霆崖高地上漫步的牛头人来说，拉哈罗代表着长者高地深远的影响力，以及玛加萨核心圈子中悄然进行的阴谋。"},sec={{t="长者的心声",b="拉哈罗忠诚地站在长者高地的高台上，侍奉在玛加萨·野性图腾身边，担任她的直接联络人。玛加萨通常通过她信任的下属行事，而不是亲自处理公开招募事宜。当有报告称兽人主城下方涌现出野兽时，正是拉哈罗负责处理后勤细节，派遣部落的佣兵去解决这场动乱。"},{t="怒焰裂谷的麻烦",b="盘踞在怒焰裂谷地底洞穴中的穴居人对外交接触并不领情。玛加萨起初派遣了使者，试图与这些原始野兽达成和平，但穴居人凶残地攻击了代表团并残忍地杀害了他们。拉哈罗认为它们是对部落难以容忍的威胁，因此指引勇士们深入洞穴，屠杀穴居人并评估它们的真实实力。"},{t="阵亡使者的书包",b="在穴居人的袭击中，玛加萨信任的仆从玛尔·恐怖图腾不幸遇难。在命丧火热的深渊之前，玛尔曾发现了一些引人注目的东西，他非常希望能将其展示给他的主子。拉哈罗委托探险者搜寻火山路径，找回玛尔丢失的书包，希望能保住这位阵亡使者留下的重要发现。"}},faq={{q="拉哈罗是谁？",a="拉哈罗是一位常驻于雷霆崖长者高地的牛头人侍从。他担任玛加萨·野性图腾的助手，负责指引旅行者执行为他主子和部落服务的任务。",al={"拉哈罗是谁","拉哈罗背景故事","这个牛头人是谁"}},{q="我在哪里可以找到拉哈罗？",a="你可以在雷霆崖的长者高地上找到拉哈罗，他就站在恐怖图腾族长玛加萨·野性图腾的附近。",al={"拉哈罗位置","拉哈罗在哪里","找到拉哈罗"}},{q="为什么拉哈罗要冒险者去怒焰裂谷？",a="玛加萨·野性图腾曾试图派遣使者与奥格瑞玛下方出现的穴居人进行谈判，但这些野兽杀死了他们。拉哈罗招募冒险者去消灭穴居人的数量，并终结它们对部落造成的威胁。",al={"拉哈罗怒焰裂谷","为什么派往怒焰裂谷","拉哈罗穴居人任务"}},{q="玛尔·恐怖图腾是谁？",a="玛尔·恐怖图腾是玛加萨派遣到怒焰裂谷深处的仆从。他在洞穴中发现了一些值得注意的东西，但在他能够汇报这些发现之前，就被那里的穴居人杀害了。",al={"玛尔·恐怖图腾","玛尔是谁","丢失书包的人"}},{q="拉哈罗要找的遗失书包里有什么？",a="书包里装着玛尔·恐怖图腾在死前所做的一个奇特发现。拉哈罗要求冒险者从穴居人出没的洞穴中将其找回，并安全送回雷霆崖。",al={"丢失书包的内容","书包里有什么","玛尔的书包"}},{q="拉哈罗属于恐怖图腾氏族吗？",a="他是长者高地上玛加萨·野性图腾的直接侍从，负责监督恐怖图腾特工（如玛尔）的相关事务，这使他与玛加萨在雷霆崖的随从紧密结合在一起。",al={"拉哈罗是恐怖图腾吗","拉哈罗氏族","拉哈罗所属派系"}}},fx={["7ce6993c"]={q="拉哈罗为何在长者高地？",a="拉哈罗留在长者高地，亲自侍奉他的主人玛加萨·野性图腾。从雷霆崖的高处，他负责照看她在当地的事务，并招募能干的部落冒险者应对远方的威胁，例如奥格瑞玛怒焰裂谷深处日益猖獗的穴居人祸患。",al={"拉哈罗为何在这里","拉哈罗在长者高地的职责","拉哈罗在雷霆崖做什么"}},ba00cb60={q="拉哈罗与谁有关联？",a="拉哈罗是侍奉长者玛加萨·野性图腾的随从，常驻雷霆崖长者高地。他处理玛加萨的事务，协调应对她的仆从遇难等情况，例如玛尔·恐怖图腾之死，并通过派遣勇士处理威胁部落共同安全的事宜，在更广泛的部落中代表她的利益。",al={"拉哈罗的效忠对象","拉哈罗为谁效力","拉哈罗的关系"}}},fp="7,388,24.407.0,25.418.0,26.392.1,15.201.0,25.117.0,58.244.0,23.206.0,46.192.0,43.196.0"}
P.entries["npc:raleigh-andrean"] = {n="拉林夫·安迪恩",s="拉林夫·安迪恩是幽暗城的一位被遗忘者居民。他的请求显露出他对过去人类生活以及曾经相识之人的冷酷态度。",h="拉林夫·安迪恩是幽暗城的一位被遗忘者居民。他的请求显露出他对过去人类生活以及曾经相识之人的冷酷态度。",kw={"丈夫的复仇","迪莉娅","被遗忘者","拉林夫·安迪恩","蔑视之戒","trade quarter","幽暗城","瓦尔德雷·莫雷"},ang={["race:Undead"]="拉林夫对待他过去人类羁绊的方式，提供了一个被遗忘者对亡灵身份反应的令人不安的例子。"},sec={{t="苦涩的来世",b="在第三次战争摧毁洛丹伦之前，拉林夫·安迪恩过着平凡的人类生活，他与一位名叫迪莉娅的女子结婚，并与他的朋友瓦尔德雷·莫雷交好。像无数其他人一样，他在天灾军团席卷王国时倒下，随后被复活成效忠于巫妖王的无脑奴仆。在耐奥祖的控制减弱以及Sylvanas Windrunner发动起义后，他重获了自由意志，并在幽暗城的被遗忘者中占据了一席之地。"},{t="仇恨胜过悲伤",b="当拉林夫看到他已故妻子的结婚戒指时，表现出了亡灵那种冷酷的情感腐朽。他对迪莉娅没有任何悲伤或留恋的爱，冷漠地打发了她的死讯。相反，他的注意力完全集中在怨恨上：他要求得到瓦尔德雷·莫雷的断手，那个杀害了她、曾经是他朋友的人。拉林夫保留这些令人毛骨悚然的战利品，不是因为对迪莉娅的感情，而是作为背叛的永恒纪念。他会用一枚铸满蔑视的戒指奖励任何帮助他的人。"}},faq={{q="拉林夫·安迪恩在哪里？",a="拉林夫·安迪恩居住在幽暗城熙熙攘攘的Trade Quarter中，站在地下城市的被遗忘者居民之间。",al={"拉林夫·安迪恩位置","拉林夫在哪里","寻找拉林夫·安迪恩"}},{q="拉林夫生前是谁？",a="在生前，拉林夫是洛丹伦王国的一名普通居民。在天灾军团横扫这片土地之前，他与一名叫迪莉娅的女子结婚，并与一个叫瓦尔德雷·莫雷的人是朋友。",al={"拉林夫背景故事","拉林夫是谁","拉林夫·安迪恩传说"}},{q="拉林夫为什么要向瓦尔德雷·莫雷复仇？",a="拉林夫寻求向他过去生活中的某人复仇。带给他的结婚戒指引出了那段冤情的细节。",al={"为什么要杀瓦尔德雷","拉林夫的妻子","瓦尔德雷·莫雷谋杀"}},{q="拉林夫是如何从天灾军团中获得自由的？",a="拉林夫在第三次战争中被杀，并被天灾军团复活为奴仆。当巫妖王的控制在冰封王座受到攻击后减弱时，Sylvanas Windrunner领导了一场起义，解放了拉林夫和其他许多人，组成了被遗忘者。",al={"拉林夫如何成为被遗忘者","拉林夫天灾自由"}}},fx={["1c49ed7c"]={q="拉林夫·安迪恩是谁？",a="拉林夫·安迪恩是一名被遗忘者居民，住在幽暗城的 Trade Quarter。生前，他是洛丹伦的居民，在天灾入侵期间遭到杀害，随后被复活为亡灵。在与希尔瓦娜斯·风行者一同摆脱巫妖王的掌控后，他效忠于被遗忘者，留在首都，心中充满怨恨，并对生前背叛他的人怀着冰冷的复仇之意。",al={"拉林夫·安迪恩是谁","拉林夫是谁","拉林夫·安迪恩的身份"}},c1a05a30={q="拉林夫·安迪恩站在哪一方？",a="拉林夫完全效忠于希尔瓦娜斯·风行者女王和被遗忘者，因此也效忠于部落。在黑暗女王起义后摆脱天灾的控制，他在洛丹伦废墟之下找到了庇护所。尽管他主要沉浸在个人仇怨中，但仍坚定地与幽暗城的亡灵同胞站在一起。",al={"拉林夫·安迪恩的阵营","拉林夫属于部落吗","拉林夫站在哪一方"}},["49f29ff4"]={q="拉林夫·安迪恩想要什么？",a="拉林夫想向昔日好友瓦尔德雷德·莫雷复仇。他对亡妻德莉亚的死毫无感触，但亡者之心中仍燃烧着冰冷的复仇欲望；他想要有人追捕瓦尔德雷德，并把他的双手带回来，作为阴森的战利品。",al={"拉林夫想要什么","拉林夫·安迪恩的目标","拉林夫·安迪恩的复仇"}},["5288ca4a"]={q="拉林夫·安迪恩为何在幽暗城？",a="和许多恢复自由意志的洛丹伦旧民一样，拉林夫在摆脱巫妖王的控制后，避难于幽暗城。如今他留在 Trade Quarter，沉湎于往日的怨恨，并寻找路过的冒险者，愿意帮他向仍活着的仇敌复仇。",al={"拉林夫为何在这里","拉林夫为何在幽暗城","拉林夫·安迪恩与 trade quarter"}},["396cb243"]={q="拉林夫·安迪恩与谁有关联？",a="生前，拉林夫与一名叫德莉亚的女子结为夫妻，并与瓦尔德雷德·莫雷亲密交好。这段友谊如今已化作苦涩而长久的仇恨，甚至延续到了死后。",al={"拉林夫·安迪恩的妻子","拉林夫·安迪恩的关系","拉林夫、瓦尔德雷德与德莉亚"}}},fp="15,148,18.477.0,20.484.1,33.133.0,34.205.0,47.133.0,45.248.0"}
P.entries["npc:randis"] = {n="Randis",s="Randis是一个充满活力的人类小孤儿，目前在Cathedral Square的孤儿院由孤儿监护员奈丁加尔照顾。在儿童周期间，他热切地陪伴愿意带他的冒险者们穿梭于联盟的领地，领略城墙之外的风光。",h="Randis是一个充满活力的人类小孤儿，目前在Cathedral Square的孤儿院由孤儿监护员奈丁加尔照顾。在儿童周期间，他热切地陪伴愿意带他的冒险者们穿梭于联盟的领地，领略城墙之外的风光。",kw={"cathedral square","儿童周","人类孤儿","监护员奈丁加尔","randis","暴风城"},ang={["faction:Alliance"]="在儿童周期间指导Randis，提醒着联盟的勇士们他们战斗的真正目的：保护下一代的平民和梦想家。"},sec={{t="暴风城的被监护人",b="Randis居住在暴风城Cathedral of Light附近的孤儿院，他是王国持续不断的冲突中失去家人的众多儿童之一。每当一年一度的儿童周来临，孤儿监护员奈丁加尔就会把一个哨子交给富有同情心的英雄们，让他们带着Randis去冒险。Randis充满童心，好奇心旺盛，问题总是问个不停，他梦想着去冒险，喜欢出无穷无尽的谜题，还大胆地宣称自己长大后想成为暴风城的国王。"},{t="放眼世界",b="对于一个大部分时间都待在Cathedral Square的孩子来说，离开首都本身就是一场A Grand Adventure。虽然他很快就会指出像铁炉堡这样的地方闻起来很奇怪，但他那无限的惊奇感正是联盟英雄们誓死保护的纯真未来的缩影。"}},faq={{q="Randis是谁？",a="Randis是一个住在暴风城孤儿院的人类小孩，位于Cathedral Square。在儿童周的庆祝活动中，冒险者可以自愿照顾他，并带他去世界各地旅行。",al={"randis npc","谁是人类孤儿","暴风城人类孤儿"}},{q="如何见到Randis？",a="在儿童周期间，位于Cathedral Square的孤儿监护员奈丁加尔会向冒险者提供一个孤儿哨。吹响这个哨子就可以召唤Randis，让他跟随你一起冒险。",al={"如何获得randis","召唤randis","暴风城孤儿哨"}},{q="Randis想去哪些地方？",a="Randis渴望和带他的英雄一起去暴风城城墙之外的任何地方。他以前去过铁炉堡，说那里的气味很奇怪。",al={"randis要去的地方","randis的见闻","儿童周人类孤儿位置"}},{q="为什么Randis住在孤儿院？",a="像奈丁加尔监护员照顾下的许多孩子一样，Randis因为席卷暴风城王国和整个艾泽拉斯大地的持续不断的战争、入侵和苦难而失去了双亲。",al={"randis的父母","为什么randis是孤儿","暴风城孤儿院背景故事"}}},fx={["5920bd8f"]={q="Randis站在哪一方？",a="Randis是一个在暴风城长大的人类男孩，因此完全忠于联盟。他在城里的孤儿院度过童年，仰慕联盟的伟大英雄与领袖，甚至梦想有朝一日长大后成为暴风城国王。",al={"randis的联盟阵营","randis属于联盟吗","randis的阵营"}},ece316b6={q="Randis为何在暴风城？",a="Randis住在暴风城，因为他是孤儿，由 Cathedral Square 当地孤儿院的孤儿监护员奈丁加尔照料。每逢一年一度的儿童周，他都会急切等待响应监护员召唤的旅行冒险者带他出城，让他见识广阔世界的奇妙。",al={"randis为何在这里","randis为何在暴风城","randis在暴风城的位置"}},["33179f48"]={q="Randis与谁有关联？",a="Randis由孤儿监护员奈丁加尔照料，她负责照看住在暴风城 Cathedral Square 的人类孤儿。儿童周期间，他要依靠富有同情心的联盟冒险者带他一同踏上旅途，走出城墙。",al={"谁照料randis","randis的关系","randis与谁有关"}}},fp="6,267,19.485.0,17.278.0,14.208.0,23.189.0,38.163.0,37.196.0"}
P.entries["npc:ranger-glynda-nal-shea"] = {n="Ranger Glynda Nal'Shea",s="哨兵戈琳达·纳希恩是一位经验丰富的暗夜精灵哨兵，驻扎在奥伯丁的沿海城镇。她从城镇守卫附近的哨位出发，指挥整个黑海岸的当地防御工作，派遣旅行者消灭潜伏的威胁并调查奇怪的沿海现象。",h="哨兵戈琳达·纳希恩是一位经验丰富的暗夜精灵哨兵，驻扎在奥伯丁的沿海城镇。她从城镇守卫附近的哨位出发，指挥整个黑海岸的当地防御工作，派遣旅行者消灭潜伏的威胁并调查奇怪的沿海现象。",kw={"奥伯丁","黑海岸","戈琳达","穆尔克深渊","纳希恩","暗夜精灵","游侠","红色水晶","哨兵"},ang={["class:Hunter"]="其他的游侠和追踪者会在戈琳达敏锐的直觉和她消灭野兽与海岸掠食者的直接方式中找到共鸣。",["faction:Alliance"]="戈琳达为从泰达希尔或东部王国乘船抵达的联盟旅行者提供必要的悬赏任务，以确保黑海岸周边地区的安全。",["race:NightElf"]="对于暗夜精灵来说，戈琳达·纳希恩代表着保护卡利姆多神圣海岸免受凶猛野兽和古老腐蚀侵害所需的持续警惕。"},sec={{t="奥伯丁的卫士",b="随着黑海岸不断面临日益严重的腐蚀和敌对势力的入侵，哨兵戈琳达·纳希恩在奥伯丁协调着至关重要的侦察工作。她密切注视着周围的荒野，依靠能干的冒险者来维护周边地区的安全，并保卫雾气缭绕的海岸沿线的暗夜精灵据点。"},{t="海岸沿线的威胁",b="戈琳达敏锐地关注着海岸线上不断增加的危险，尤其是那些在城镇以南聚集、日益嚣张的鱼人。她负责监督针对像“穆尔克深渊”这类臭名昭著的威胁的悬赏任务，并派遣侦察兵去调查奇怪的文物，包括据报道出现在黑海岸东部山脉中的神秘红色水晶。"}},faq={{q="谁是Ranger Glynda Nal'Shea？",a="她是驻扎在奥伯丁的一名暗夜精灵哨兵，负责组织黑海岸各处的侦察巡逻和防御任务。",al={"戈琳达·纳希恩","戈琳达是谁","游侠戈琳达"}},{q="在什么地方可以找到Glynda Nal'Shea？",a="她位于黑海岸的主要联盟定居点——奥伯丁，通常出现在哨兵守卫处和城镇入口附近。",al={"戈琳达位置","戈琳达在哪里","去哪里找戈琳达"}},{q="Ranger Glynda Nal'Shea提供什么任务？",a="她提供处理区域危险的任务，包括像“通缉：穆尔克深渊！”这样的悬赏，以及涉及黑海岸悬崖上神秘红色水晶的调查任务。",al={"戈琳达任务","戈琳达给什么任务"}},{q="为什么戈琳达对穆尔克深渊感到担忧？",a="穆尔克深渊是一个凶残的鱼人首领，应对针对暗夜精灵前哨站和南部海岸旅行者的袭击负责，对奥伯丁的安全构成了持续的威胁。",al={"谁是穆尔克深渊","为什么要杀穆尔克深渊"}},{q="什么是红色水晶任务线？",a="这是一系列由戈琳达发起的侦察调查任务，要求冒险者攀登黑海岸的东部悬崖，检查一块奇怪的、脉动的水晶并取回碎片供研究。",al={"黑海岸红色水晶","红色水晶任务"}},{q="Glynda Nal'Shea为哪个阵营服务？",a="她为达纳苏斯的暗夜精灵服务，并担任黑海岸联盟的军事前哨指挥官。",al={"戈琳达阵营","戈琳达为谁工作"}}},fx={["83e5dc60"]={q="游侠戈琳达·纳希恩为何在黑海岸？",a="哨兵戈琳达·纳希恩驻守奥伯丁，帮助抵御威胁暗夜精灵聚居地的重重危险。海岸边步步逼近的鱼人，以及悬崖上的红色水晶等奇异遗物，都在她的警戒范围内；她会指引能干的冒险者消除这些威胁，以免奥伯丁遭到淹没。",al={"戈琳达为何在这里","游侠戈琳达在黑海岸的职责","戈琳达为何在奥伯丁"}},["0a51f57f"]={q="游侠戈琳达·纳希恩要你做什么？",a="戈琳达希望保障黑海岸的安全，并查明困扰这片地区的异常现象。她会招募你协助猎杀危险目标，例如臭名昭著的鱼人穆克迪普，并调查山腰上那块巨大的红色水晶等神秘遗物。",al={"戈琳达想要什么","戈琳达·纳希恩的任务","游侠戈琳达的目标"}}},fp="22,280,21.316.0,23.337.0,30.116.0,35.131.0,46.176.0,39.179.0,35.192.0,40.111.0"}
P.entries["npc:rau-cliffrunner"] = {n="劳恩·峭壁行者",s="劳恩·峭壁行者是一位牛头人侦察兵兼学者，驻扎在千针石林乱风岗的高处。为了保护族人免受地区威胁，他通过研究加拉克半人马的古代遗物，探寻这个敌对种族的历史和起源。劳恩与雷霆崖的盟友密切合作，协调对峡谷内危险敌方据点的探索。",h="劳恩·峭壁行者是一位牛头人侦察兵兼学者，驻扎在千针石林乱风岗的高处。为了保护族人免受地区威胁，他通过研究加拉克半人马的古代遗物，探寻这个敌对种族的历史和起源。劳恩与雷霆崖的盟友密切合作，协调对峡谷内危险敌方据点的探索。",kw={"裂开的蹄子","乱风岗","加拉克","劳恩·峭壁行者","神圣火焰","裂蹄峭壁","裂蹄堡","千针石林","赞金·石蹄"},ang={["faction:Horde"]="劳恩的努力有助于巩固乱风岗，这是维持贫瘠之地和塔纳利斯之间补给线的关键部落堡垒。",["race:Tauren"]="对于牛头人来说，了解半人马是关乎文化存续的大事；劳恩对半人马起源的研究旨在深入了解那场几乎将舒哈鲁逼向灭绝的祖先冲突。"},sec={{t="峡谷守望者",b="劳恩·峭壁行者栖身于乱风岗险峻的峭壁之上，注视着千针石林那片广阔、被烈日炙烤的大地。这个牛头人哨站是部落在这一充满凶猛掠食者、野猪人和好斗半人马部族领地中的重要避难所。劳恩既是哨站的组织者，也是一位专注的调查员，热衷于在威胁蔓延并压垮脆弱的平顶山定居点之前将其消除。"},{t="加拉克的秘密",b="劳恩的主要研究重点是半人马的起源——这个种族世世代代都在对牛头人发动残酷的战争。在发现当地的加拉克部族守护着一件追溯到他们种族黎明时期的神圣遗物后，劳恩寻求绕过遗物神秘保护的方法。他与雷霆崖的赞金·石蹄联手，从灰谷获得了神圣的月亮井水，用来浇灭裂蹄堡的永恒之火，从而让冒险者能够取回神秘的“裂开的蹄子”供他研究。"}},faq={{q="我在哪里可以找到劳恩·峭壁行者？",a="劳恩·峭壁行者居住在乱风岗顶部，这是位于千针石林中央的显眼平顶山哨站。",al={"劳恩·峭壁行者位置","劳恩在哪里","劳恩·峭壁行者在哪里"}},{q="劳恩·峭壁行者正在调查什么？",a="劳恩正在调查半人马的起源和神秘传统。他正在寻找裂开的蹄子，这是加拉克半人马在裂蹄峭壁中保存的一件古代部族遗物，希望其奇异的能量能揭开牛头人历史宿敌的秘密。",al={"劳恩·峭壁行者的目的","劳恩想要什么","劳恩为什么想要蹄子"}},{q="劳恩为什么需要月亮井水？",a="加拉克半人马将他们的古代遗物保存在永恒的神秘火焰之后。劳恩得知，取自灰谷暗夜精灵月亮井的纯净井水拥有熄灭火盆之火并打破其结界所需的神圣力量。",al={"劳恩的月亮井水","神圣火焰 月亮井","为什么需要月亮井水"}},{q="谁在雷霆崖与劳恩·峭壁行者合作？",a="驻扎在雷霆崖High Rise的赞金·石蹄直接与劳恩合作。赞金负责协调灰谷月亮井水的获取，然后指引值得信赖的部落旅行者前往乱风岗寻找劳恩。",al={"劳恩的盟友","赞金和劳恩","谁派我去找劳恩"}},{q="裂开的蹄子是什么？",a="裂开的蹄子是一件由裂蹄堡的加拉克部族所保存的原始半人马文物。它追溯到半人马种族的诞生，散发着劳恩打算解读的异常能量。",al={"裂开的蹄子遗物","蹄子是什么","千针石林的半人马遗物"}},{q="劳恩·峭壁行者属于某个特定的牛头人部族吗？",a="没有关于劳恩所属部族的具体记录。他是一位驻扎在乱风岗的雷霆崖牛头人战士，没有任何记录将他的姓氏与某个特定的部族联系起来。",al={"劳恩·峭壁行者的部族","劳恩属于什么部族"}}},fx={c4ebc959={q="劳恩·峭壁行者是谁？",a="劳恩·峭壁行者是一名牛头人学者和斥候，驻扎在千针石林峡谷上方的乱风岗。他致力于揭开当地加拉克半人马的历史，与雷霆崖的其他研究者合作，寻找并研究与卡利姆多半人马部族起源有关的古代神器。",al={"劳恩·峭壁行者是谁","劳恩·峭壁行者的背景"}},dfeb320c={q="劳恩·峭壁行者站在哪一方？",a="劳恩坚定地与雷霆崖的牛头人和部落站在一起。他驻扎在乱风岗，与部落的旅人协调行动，守卫台地，并寻找可能揭示部落宿敌半人马重要情报的遗物。",al={"劳恩·峭壁行者的阵营","劳恩属于部落吗","劳恩·峭壁行者的效忠对象"}},["3af393e1"]={q="劳恩·峭壁行者想要什么？",a="劳恩想揭开一种名为裂开的蹄子的古代半人马遗物背后的秘密，据说它自半人马种族诞生以来便保存至今。为了取得它，他需要月亮井水熄灭守护它的圣火，而这圣火位于裂蹄堡。他希望遗物的奇异能量能让他深入了解半人马的历史。",al={"劳恩·峭壁行者的目标","劳恩想要什么","劳恩的动机"}},["66929801"]={q="劳恩·峭壁行者为何在乱风岗？",a="乱风岗是部落在千针石林的核心据点，高踞峡谷之上，毗邻加拉克半人马的聚居地。劳恩留在这里负责监督对裂蹄峭壁的调查，并解读峭壁中保存的古代遗物之谜。",al={"劳恩·峭壁行者为何在这里","劳恩为何在千针石林","劳恩为何在乱风岗"}}},fp="15,375,22.478.0,20.529.1,33.113.0,38.254.0,33.239.0,53.223.0,24.201.0,55.153.0"}
P.entries["npc:razzle-sprysprocket"] = {n="拉兹·滑链",s="拉兹·滑链是一位居住在丹莫罗卡拉诺斯的侏儒工程师。他以与奥齐·电环一起进行技术修补而闻名，并会招募旅者帮助回收散落在雪山丘陵各处的受损侏儒机械和零件。",h="拉兹·滑链是一位居住在丹莫罗卡拉诺斯的侏儒工程师。他以与奥齐·电环一起进行技术修补而闻名，并会招募旅者帮助回收散落在雪山丘陵各处的受损侏儒机械和零件。",kw={"丹莫罗","工程师","卡拉诺斯","奥齐·电环","拉兹","重组","滑链"},ang={["profession:Engineering"]="工程师们会在拉兹身上找到志同道合的伙伴，他的项目凸显了天才的侏儒发明与爆炸性的计算失误之间那微妙的界限。",["race:Gnome"]="对于途经丹莫罗的流亡侏儒来说，拉兹代表了诺莫瑞根陷落后，他们依然顽强存续的创造精神以及重建与恢复的决心。"},sec={{t="卡拉诺斯的修补工作",b="诺莫瑞根的悲剧发生后，拉兹·滑链在丹莫罗的雪堆中找到了避难所，并在卡拉诺斯设立了他的工作室。拉兹擅长处理精密的机械零件，并与同行工程师奥齐·电环共事。他们的工作通常涉及回收在逃离被辐射的故乡时丢失或被劫掠的陀螺机械装置和齿轮组件。"},{t="工作室的防御",b="对于一位侏儒发明家来说，丹莫罗的生活绝不安宁。面对冰封山脊上的野兽和当地霜鬃巨魔的突袭，拉兹的工作从未真正安全过。尽管危险重重，他依然致力于保持侏儒装置的正常运转，并找回诺莫瑞根失落的奇迹。"}},faq={{q="拉兹·滑链是谁？",a="拉兹·滑链是一位古怪的侏儒修补匠，驻扎在丹莫罗的卡拉诺斯，与奥齐·电环一起工作。",al={"拉兹·滑链","拉兹是谁","拉兹 卡拉诺斯"}},{q="拉兹·滑链需要什么帮助？",a="拉兹经常需要冒险者前往丹莫罗各地，收集零散的小发明、齿轮组件和零件，以协助进行侏儒工程项目的重组。",al={"拉兹的任务","重组协助","拉兹想要什么"}},{q="我可以在哪里找到拉兹·滑链？",a="他就在丹莫罗中部，卡拉诺斯旅店和铁匠铺外面的修补匠岗哨附近工作。",al={"拉兹的位置","拉兹在哪里","拉兹·滑链地图"}},{q="拉兹·滑链和其他滑链家族成员有关系吗？",a="拉兹没有任何已知的亲属。他和里兹·滑链拥有相同的姓氏，但两人显然没有亲属关系。",al={"滑链家族","拉兹的亲属"}}},fx={b527298b={q="拉兹·滑链站在哪一方？",a="拉兹·滑链效忠于诺莫瑞根流亡者和联盟。他与同胞难民一起驻扎在卡拉诺斯，与奥齐·电环等侏儒发明家密切合作，帮助丹莫罗的流离失所者。",al={"拉兹·滑链的阵营","拉兹属于联盟吗","拉兹·滑链的效忠对象"}},fcfe3829={q="拉兹·滑链为何在卡拉诺斯？",a="与许多侏儒一样，诺莫瑞根沦陷后，拉兹·滑链逃到了卡拉诺斯避难。他在这座雪镇开设了自己的铺子，继续捣鼓各种发明，并寻找材料支援侏儒持续进行的复兴工作。",al={"拉兹为何在这里","拉兹·滑链为何在卡拉诺斯","是什么让拉兹来到卡拉诺斯"}}},fp="19,243,21.400.0,23.313.0,27.127.0,45.183.0,37.122.0,54.119.0"}
P.entries["npc:red-jack-flint"] = {n="红衣弗林特",s="红衣弗林特是一名经验丰富的人类水手，驻扎在米奈希尔港的米奈希尔城堡内。作为“少女美德号”船员的一员，他为寻求航行或与卡利姆多建立联系的旅客提供接洽服务。",h="红衣弗林特是一名经验丰富的人类水手，驻扎在米奈希尔港的米奈希尔城堡内。作为“少女美德号”船员的一员，他为寻求航行或与卡利姆多建立联系的旅客提供接洽服务。",kw={"菲奥拉·长耳","少女美德号","米奈希尔港","米奈希尔城堡","红衣弗林特","湿地"},ang={["faction:Alliance"]="对于从卡兹莫丹规划海上航线的联盟旅客来说，像红衣弗林特这样的水手提供了连接卡利姆多北海岸前哨的重要纽带。"},sec={{t="米奈希尔城堡的一名水手",b="红衣弗林特位于米奈希尔城堡的石墙内，是一位与港口海运贸易息息相关的资深水手。作为“少女美德号”的一员，他负责在连接卡兹莫丹的沼泽地与远方海岸的危险航线上航行。弗林特并没有局限于常规的航海工作，而是引导有能力的冒险者前往无尽之海彼岸的盟友处，其中包括卡利姆多的接头人，如菲奥拉·长耳。"}},faq={{q="谁是红衣弗林特？",a="红衣弗林特是一名人类水手，也是“少女美德号”的船员。他驻扎在米奈希尔港的米奈希尔城堡内，帮助搭建东部王国与卡利姆多之间的联系。",al={"弗林特是谁","红衣弗林特背景故事","弗林特做什么"}},{q="在哪里可以找到红衣弗林特？",a="他可以在米奈希尔城堡内找到，那是保卫湿地米奈希尔港的主要石制堡垒。",al={"红衣弗林特位置","弗林特在哪里","寻找红衣弗林特"}},{q="红衣弗林特在什么船上工作？",a="他在“少女美德号”上服役，这是一艘以米奈希尔港为基地的商船。",al={"弗林特的船","红衣弗林特在哪艘船上","少女美德号"}},{q="红衣弗林特会将旅客引荐给谁？",a="他引导旅客去联系菲奥拉·长耳，那是他在海的另一边，塞拉摩港的合作伙伴。",al={"弗林特任务","菲奥拉·长耳的关系","弗林特把你送到哪里"}}},fx={["1faeb3cc"]={q="红衣弗林特站在哪一方？",a="红衣弗林特站在联盟一方。他驻守在米奈希尔港的卫兵和水手之间，为往返于东部王国与卡利姆多海岸的联盟旅人提供指引和人脉。",al={"红衣弗林特的阵营","红衣弗林特属于联盟吗","红衣弗林特的效忠对象"}}},fp="14,251,25.430.0,22.196.0,34.115.0,38.89.0,46.110.0"}
P.entries["npc:rejold-barleybrew"] = {n="雷杰德·麦酒",s="雷杰德·麦酒是一位驻扎在丹莫罗西部烈酒村湖畔定居点的大师级矮人酿酒师。他致力于完善浓郁的山地烈酒，经常招募过往的旅行者去搜集区域特有的原料，并在雪山峡谷中测试他的烈性配方。",h="雷杰德·麦酒是一位驻扎在丹莫罗西部烈酒村湖畔定居点的大师级矮人酿酒师。他致力于完善浓郁的山地烈酒，经常招募过往的旅行者去搜集区域特有的原料，并在雪山峡谷中测试他的烈性配方。",kw={"啤酒","麦酒","酿酒师","烈酒村","丹莫罗","雷杰德","微光黑啤酒","黑啤酒"},ang={["faction:Alliance"]="雷杰德供应的黑啤酒有助于鼓舞整个丹莫罗的联盟士气，为那些勇敢面对石腭怪袭击和严酷暴风雪的卫兵和旅行者们补充体力。",["profession:Cooking"]="热爱烹饪的冒险者会赞赏雷杰德对纯净原料和精确配方的追求，他将酿造过程视为一种严谨且受人尊敬的艺术。",["race:Dwarf"]="对于矮人来说，雷杰德代表了那种引以为傲的山地酿造传统，这种烈性啤酒能提供温暖和力量，抵御卡兹莫丹刺骨的严冬寒意。"},sec={{t="酿造大师",b="在丹莫罗，酿酒不仅仅被视为一种交易，更是一种极具代表性的艺术形式。雷杰德·麦酒代表了烈酒村的这一传统，这是一个坐落在冰流河冰冻湖畔的前哨站。雷杰德并不满足于酒馆里的普通劣酒，他不断改良自己的配方，寻找稀有的啤酒花、山地矿物和纯净的冰水，以酿造出能够温暖最强壮的矮人战士的黑啤酒。"},{t="追寻完美的黑啤酒",b="雷杰德对理想口味的追求永不止步，他派遣冒险者穿梭在丹莫罗各地，收集酿造微光黑啤酒等饮品所需的重要原料。无论是与钢架补给站的攻城机师交换人情，还是为口渴的顾客安排送货，他的工作确保了在这条寒冷且饱受石腭怪困扰的丹莫罗之路上，充足的烈性啤酒让人们的生活尚可忍受。"}},faq={{q="雷杰德·麦酒是谁？",a="雷杰德·麦酒是一位居住在丹莫罗烈酒村的矮人酿酒大师。他致力于调制传奇的矮人啤酒，并招募过往的冒险者帮忙获取原料并运送试验性的酿造品。",al={"雷杰德","雷杰德是谁","雷杰德·麦酒信息"}},{q="在哪里可以找到雷杰德·麦酒？",a="雷杰德位于烈酒村，该村庄坐落在丹莫罗西部边缘，紧邻冰流盆地的冰封水域。",al={"雷杰德位置","雷杰德·麦酒在哪里","雷杰德·麦酒烈酒村"}},{q="雷杰德在钻研什么？",a="雷杰德致力于完善强效的山地配方，包括他的招牌微光黑啤酒和新的试验性啤酒，这些都需要在白雪皑皑的山丘上寻找寒冷的山地植物和特殊的酿造原料。",al={"雷杰德任务","完美的黑啤酒任务","雷杰德在酿什么"}},{q="为什么雷杰德会派旅行者去找侏儒？",a="他的差事实际上是让他与同族的矮人而非侏儒联系在一起：钢架补给站的驾驶员贝隆·风箱会派旅行者去找雷杰德索要一批永恒之光，而雷杰德的微光黑啤酒则会送到他的兄弟，巡山人维拉特·麦酒那里。",al={"雷杰德与侏儒","雷杰德永恒之光","贝隆·风箱与雷杰德"}},{q="什么是微光黑啤酒？",a="微光黑啤酒是雷杰德·麦酒酿造的一种知名且强劲的矮人饮品，它使用独特的山地原料酿制而成，在严寒的冬季气候中具有独特的后劲。",al={"什么是微光黑啤酒","微光黑啤酒背景故事"}}},fx={["86e90b5e"]={q="雷杰德·麦酒效忠哪一方？",a="雷杰德是铁炉堡的矮人，以身为联盟一员为傲。他和许多丹莫罗的同族一样，平日致力于精进矮人工艺，并招待途经烈酒村的旅客；他也与钢架补给站的驾驶员贝隆·风箱等矮人保持着友好关系。",al={"雷杰德阵营","雷杰德属于联盟还是部落","雷杰德·麦酒是联盟的吗"}},ede674a2={q="雷杰德·麦酒为什么在烈酒村？",a="雷杰德驻扎在烈酒村，追寻毕生热忱：酿造卡兹莫丹最上乘的麦酒。烈酒村能为他提供新鲜的山泉水和当地食材，用来酿造他那些雄心勃勃的佳酿。",al={"雷杰德为什么在这里","雷杰德为什么在烈酒村","是什么让雷杰德来到烈酒村"}}},fp="17,286,21.423.0,32.395.0,25.223.0,37.131.0,26.212.0,41.231.0,22.187.0"}
P.entries["npc:rema-schneider"] = {n="雷玛·施涅德",s="雷玛·施涅德是一位人类市民，在暴风城的运河裁缝店工作。她的店铺位于主要城区之间静谧的水道旁，她经常协助当地的店主和工匠进行货物配送。",h="雷玛·施涅德是一位人类市民，在暴风城的运河裁缝店工作。她的店铺位于主要城区之间静谧的水道旁，她经常协助当地的店主和工匠进行货物配送。",kw={"运河裁缝","哈兰需要补给","瑟曼的包裹","雷玛·施涅德","暴风城运河"},ang={["faction:Alliance"]="来到暴风城的旅行者和新兵在熟悉首都环境时，经常会为雷玛跑跑简单的腿，完成快递任务。",["profession:Tailoring"]="雷玛在运河裁缝店工作，是暴风城布艺贸易中常见的日常人物。"},sec={{t="运河店主",b="雷玛·施涅德躲在运河裁缝店里，位置就在通往大教堂广场的石桥西侧，她负责打理城市贸易的日常需求。和城中许多熟练的工匠和助手一样，她的工作维持着布料和成衣在当地手艺人之间的流通，并依靠热心的信使在各工坊间运送补给。"}},faq={{q="雷玛·施涅德在哪里？",a="雷玛·施涅德在暴风城的运河裁缝店工作。这家店位于运河边，就在通往大教堂广场的桥西侧。",al={"雷玛·施涅德位置","雷玛在哪里","寻找雷玛·施涅德"}},{q="雷玛在暴风城扮演什么角色？",a="她担任当地贸易差事的联络人兼任务发布者，协助协调城中商人和手艺人之间的补给包裹和补货订单。",al={"雷玛·施涅德是谁","雷玛做什么","雷玛·施涅德用途"}},{q="雷玛会教裁缝吗？",a="不会。虽然她在运河裁缝店工作并处理裁缝货物的运输，但她不是专业训练师，也不是主要商人。",al={"雷玛是裁缝训练师吗","雷玛裁缝训练"}}},fx={["080a82f0"]={q="雷玛·施涅德是谁？",a="雷玛·施涅德是暴风城的一名人类居民兼裁缝。你可以在运河裁缝店找到她，店铺坐落在运河沿岸，位于通往 Cathedral Square 的桥西侧。",al={"雷玛·施涅德是谁","雷玛·施涅德的身份","雷玛·施涅德"}},["37d985b5"]={q="雷玛·施涅德效忠哪一方？",a="雷玛·施涅德是暴风城王国的忠诚臣民，坚定地站在大联盟一边。她在首都经营裁缝生意，并为王国各地的信使和商人提供帮助。",al={"雷玛·施涅德阵营","雷玛·施涅德是联盟的吗","雷玛·施涅德效忠哪一方"}},c7f62ca5={q="雷玛·施涅德想要什么？",a="雷玛一心经营裁缝生意，并维持遍及王国的贸易关系。她依靠途经此地的信使和冒险者运送包裹，为仰赖她提供材料的当地工匠补充货物。",al={"雷玛想要什么","雷玛·施涅德的目标","雷玛·施涅德的任务"}},d4111a95={q="雷玛·施涅德为什么在这里？",a="雷玛是运河裁缝店的常驻裁缝。运河是暴风城各城区之间繁忙的贸易路线，因此这里很适合她管理货物和送货事宜。",al={"雷玛为什么在暴风城","雷玛·施涅德为什么在这里","雷玛·施涅德运河裁缝店"}}},fp="14,240,24.376.0,32.168.0,38.169.0,26.146.0"}
P.entries["npc:remulos"] = {n="Remulos",s="雷姆洛斯守护者是塞纳留斯的半神之子，也是月光林地神圣的保护者。在塞纳留斯陨落且玛法里奥·怒风陷入沉睡的情况下，他与大德鲁伊范达尔·鹿盔以及哈缪尔·符文图腾并肩作战，共同指引着塞纳里奥议会。与鹿盔不同，雷姆洛斯更看重自然的整体平衡，而非暗夜精灵的孤立主义。",h="雷姆洛斯守护者是塞纳留斯的半神之子，也是月光林地神圣的保护者。在塞纳留斯陨落且玛法里奥·怒风陷入沉睡的情况下，他与大德鲁伊范达尔·鹿盔以及哈缪尔·符文图腾并肩作战，共同指引着塞纳里奥议会。与鹿盔不同，雷姆洛斯更看重自然的...",kw={"塞纳里奥议会","塞纳留斯","范达尔·鹿盔","林地","哈缪尔·符文图腾","月光林地","remulos","扎尔塔"},ang={["class:Druid"]="每一位德鲁伊，无论是暗夜精灵还是牛头人，都会前往月光林地，与雷姆洛斯守护者交流，并接受关于掌握动物形态和神圣试炼的指导。",["race:Tauren"]="牛头人德鲁伊非常敬重雷姆洛斯，因为他反抗了范达尔·鹿盔的意志，并允许他们的族人进入塞纳里奥议会，接受完整的德鲁伊教导。"},sec={{t="圣林之主",b="雷姆洛斯守护者是一位永恒的林地守护者，他拥有雄鹿的下半身，躯干上长着古老丛林守护者特有的鹿角。他守护着月光林地，那是艾泽拉斯德鲁伊们位于海加尔山以北的神圣避难所。当玛法里奥·怒风仍被困在翡翠梦境中时，雷姆洛斯为塞纳里奥议会的凡人们提供了神圣的权威和指引。他始终致力于治愈艾泽拉斯的创伤，为那些在月神湖畔进行神圣仪式的德鲁伊提供帮助。"},{t="议会裂痕",b="雷姆洛斯经常与大德鲁伊范达尔·鹿盔在意识形态上产生分歧。鹿盔极力主张暗夜精灵的至高地位，并试图通过泰达希尔来恢复他们失去的永恒寿命，而雷姆洛斯则强烈反对种植这棵新的世界之树，认为那是一种傲慢之举。为了反抗鹿盔的孤立主义派系，雷姆洛斯接纳了哈缪尔·符文图腾和牛头人进入塞纳里奥议会，并与他们这些由萨满转修德鲁伊之道的修行者分享了自然界严密守护的奥秘，以共同恢复大地。"}},faq={{q="雷姆洛斯守护者是谁？",a="他是塞纳留斯的永恒之子，也是已故的扎尔塔的兄弟。雷姆洛斯居住在月光林地的雷姆洛斯神殿中，担任林地守护者，同时也是塞纳里奥议会的一位资深领袖。",al={"雷姆洛斯背景故事","雷姆洛斯是谁","雷姆洛斯守护者背景"}},{q="为什么雷姆洛斯支持牛头人德鲁伊？",a="雷姆洛斯认为自然的平衡超越了凡人种族之间的隔阂。他认识到牛头人与大地母亲之间深厚的羁绊，因此无视了大德鲁伊范达尔·鹿盔的反对，接纳了哈缪尔·符文图腾大德鲁伊及其族人加入塞纳里奥议会。",al={"雷姆洛斯 牛头人","为什么牛头人有德鲁伊","雷姆洛斯 哈缪尔"}},{q="雷姆洛斯对泰达希尔的看法如何？",a="雷姆洛斯强烈反对创造泰达希尔。他认为种植这棵新的世界之树是暗夜精灵为了夺回他们失去的永恒寿命而进行的一项自私举动，而非出于真正治愈艾泽拉斯的目的。",al={"雷姆洛斯 世界之树","雷姆洛斯 范达尔之树"}},{q="雷姆洛斯与玛拉顿有什么关系？",a="他的兄弟扎尔塔曾前往凄凉之地，与瑟莱德丝公主结合，在死前成为了半人马的始祖。雷姆洛斯曾警告过扎尔塔不要进行那次结合，而玛拉顿至今仍保留着他兄弟和半人马的遗迹。",al={"雷姆洛斯 扎尔塔","雷姆洛斯 瑟莱德丝","雷姆洛斯 兄弟"}}},fp="7,351,24.516.0,20.506.0,22.203.0,43.265.0,40.231.0,44.233.1"}
P.entries["npc:remy-two-times"] = {n="雷米",s="雷米是一位目前居住在闪金镇的人类商人。他来自赤脊山，最显著的特征是他有一个奇怪的习惯，即重复自己句子的结尾。他在艾尔文森林各地进行商业活动，买卖货物并向冒险者收购金砂等原材料。",h="雷米是一位目前居住在闪金镇的人类商人。他来自赤脊山，最显著的特征是他有一个奇怪的习惯，即重复自己句子的结尾。他在艾尔文森林各地进行商业活动，买卖货物并向冒险者收购金砂等原材料。",kw={"艾尔文","金砂","闪金镇","商人","鱼人","赤脊","雷米","雷米绰号"},ang={["faction:Alliance"]="对于刚到达闪金镇的联盟新兵来说，雷米提供了一些简单直接的任务，既能帮助清除当地的威胁，又能获得一些快钱。",["profession:Mining"]="在法戈第矿洞和玉石矿洞工作的矿工经常会遇到雷米，他乐于用交易的方式换取从盘踞在那里的狗头人身上收集到的金砂。"},sec={{t="一个有怪癖的商人",b="雷米在闪金镇经营生意，是一位来自赤脊山崎岖之地的进取商人。正如他的绰号一样，雷米有一个独特的口癖：习惯重复句子的最后几个词，通常是两次。尽管他的说话方式有些滑稽，但他依然是一位精明的商人，在艾尔文森林局势日益动荡的情况下寻求盈利，并乐于与路过的冒险者达成交易。"},{t="乱世中的生意",b="随着狗头人占领了当地的金矿，凶猛的鱼人侵扰了河岸，艾尔文森林的正常贸易受到了严重干扰。雷米在他人视为灾难的地方看到了机遇，他委托冒险者从矿坑里的害虫身上收集成袋的金砂，并密切关注水晶湖附近可疑的鱼人动向。"}},faq={{q="为什么他被称为“雷米”？",a="雷米赢得这个绰号是因为他有一种不同寻常的交谈习惯，每当他说话时，都会习惯性地重复句子的最后几个词两次。",al={"雷米名字由来","为什么雷米重复词语","雷米绰号含义"}},{q="雷米原本来自哪里？",a="他从赤脊山来到闪金镇，在艾尔文森林的核心地带进行贸易。",al={"雷米起源","雷米来自哪里"}},{q="雷米用他收购的金砂做什么？",a="作为一名机会主义商人，雷米收集从当地矿坑狗头人身上搜刮来的金砂，以便在当地经济中进行熔炼、交易或转手以赚取可观的利润。",al={"雷米为什么需要金砂","金砂兑换背景"}},{q="在闪金镇哪里可以找到雷米？",a="雷米站在艾尔文森林闪金镇的户外，就在Lion's Pride Inn附近，准备与路过的旅行者进行易货贸易。",al={"雷米在哪里","雷米在闪金镇的位置"}}},fx={["99a83a18"]={q="雷米是谁？",a="雷米是在人类聚居地闪金镇开店的商人。他原本来自赤脊山，在艾尔文森林一带以古怪的口头禅闻名：每句话的最后几个词都会重复两遍。",al={"雷米是谁","雷米的身份"}},e326d54d={q="雷米效忠哪一方？",a="雷米忠于大联盟和暴风城王国。他在闪金镇公开经营生意，与当地官员、居民和途经此地的冒险者和平往来。",al={"雷米的阵营","雷米是联盟的吗","雷米为谁做事"}},["85133ed8"]={q="雷米想要什么？",a="作为一名精明的商人，雷米想要有利可图的货物和当地的安全。他热衷于向旅人收购附近矿井采出的金砂，也急于解决威胁闪金镇贸易的周边险情。",al={"雷米想要什么","雷米的目标","雷米为什么需要冒险者"}},["7f55543c"]={q="雷米为什么在闪金镇？",a="雷米从赤脊山的家乡一路南下，来到闪金镇定居经商。这个繁忙的十字路口村庄有源源不断的矿工、旅客和冒险者，他们愿意买卖货物，也乐于帮忙跑腿。",al={"雷米为什么在闪金镇","雷米为什么离开赤脊山","雷米为什么在这里"}}},fp="16,343,28.449.0,27.381.0,29.153.0,37.104.0,49.158.0,37.118.0"}
P.entries["npc:renato-gallina"] = {n="雷纳多·加林纳",s="雷纳多·加林纳是一位精力充沛的吆喝者，经常在暴风城熙熙攘攘的Trade District招揽生意。作为加林纳酿酒家族的一员，他的工作是招徕顾客，并将口渴的旅人指引到坐落在城市运河边的家族酒庄。",h="雷纳多·加林纳是一位精力充沛的吆喝者，经常在暴风城熙熙攘攘的Trade District招揽生意。作为加林纳酿酒家族的一员，他的工作是招徕顾客，并将口渴的旅人指引到坐落在城市运河边的家族酒庄。",kw={"运河","加林纳酒庄","雷纳多·加林纳","暴风城葡萄酒","trade district","葡萄酒商店广告"},ang={["faction:Alliance"]="对于抵达首都的联盟旅人来说，雷纳多提供了对暴风城当地商业和国内贸易的快速介绍。"},sec={{t="加林纳酒庄的代言人",b="雷纳多·加林纳站在Trade District繁忙的摊位之间，整日向路人吆喝，大胆地宣称他的家族出售着整个暴风城最好的佳酿。他的家族经营着位于附近运河边的加林纳酒庄，而雷纳多担任着家族的公众推广员，他会发放传单，路人可以将传单带到商店交给他的妹妹苏泽塔·加林纳，从而换取一瓶免费的葡萄酒。"}},faq={{q="雷纳多·加林纳是谁？",a="雷纳多是暴风城Trade District的一名人类吆喝者。他属于加林纳家族，花费时间向当地人和来访的冒险者宣传他们家族经营的酒庄。",al={"雷纳多·加林纳","雷纳多是谁","暴风城葡萄酒吆喝者"}},{q="加林纳酒庄在哪里？",a="加林纳酒庄坐落在暴风城的运河边，就隐藏在繁忙的商业区主干道旁。",al={"加林纳酒庄在哪里","暴风城葡萄酒商店位置","加林纳酒庄"}},{q="雷纳多要求冒险者做什么？",a="雷纳多会发放一份关于他家族葡萄酒商店的传单，并请旅人将其带到运河边的酒庄交给他的妹妹苏泽塔·加林纳，在那里他们可以凭传单获得一瓶免费的葡萄酒。",al={"雷纳多·加林纳任务","葡萄酒商店广告任务","雷纳多想要什么"}}},fx={fce75f2a={q="雷纳多·加林纳效忠哪一方？",a="雷纳多是暴风城的忠诚市民，也是联盟的一员。他心系自己的城市、生意，尤其是加林纳家族商业计划的成功。",al={"雷纳多·加林纳的阵营","雷纳多·加林纳效忠哪一方","雷纳多是联盟的吗"}},c03f1140={q="雷纳多·加林纳为什么在贸易区？",a="雷纳多站在繁忙的贸易区广场上，为家族的葡萄酒生意招揽顾客。他不坐在柜台后面，而是每天亲自向途经暴风城的旅客和居民宣传加林纳酒庄。",al={"雷纳多为什么在这里","雷纳多·加林纳与贸易区","雷纳多在这里做什么"}},["9e1708f4"]={q="雷纳多·加林纳与谁有关联？",a="雷纳多与加林纳家族关系密切。该家族是位于暴风城运河沿岸的加林纳酒庄的经营者。他每天全心全意地推广家族的佳酿，并在城中拓展客源。",al={"雷纳多·加林纳的关系","雷纳多·加林纳的家族","雷纳多与谁共事"}}},fp="14,261,27.419.0,22.193.0,36.136.0,39.201.0"}
P.entries["npc:renee-lauer"] = {n="旅店老板瑞尼",s="旅店老板瑞尼经营着位于布瑞尔的恐惧之末旅店，为被遗忘者和途经提瑞斯法林地的部落旅人提供庇护、食物和饮水。",h="旅店老板瑞尼经营着位于布瑞尔的恐惧之末旅店，为被遗忘者和途经提瑞斯法林地的部落旅人提供庇护、食物和饮水。",kw={"布瑞尔","恐惧之末旅店","旅店老板瑞尼","瑞尼·劳尔","血色十字军","提瑞斯法林地"},ang={["race:Undead"]="瑞尼的旅店为提瑞斯法的被遗忘者保留了生者世界中的一些旧日慰藉：炉火、餐点和休息之处。"},sec={{t="恐惧之末的守护者",b="瑞尼经营着位于布瑞尔中心的恐惧之末旅店。她在柜台后售卖食物、饮水和日用品，并欢迎疲惫的来访者在此歇脚，还曾打趣说被遗忘者的胃口确实很大。对于提瑞斯法的不死族来说，她的旅店是一个温馨的小天地，让那些瘟疫的受害者在这里努力立足。"},{t="信件与俘虏",b="瑞尼的旅店往往是新来者在布瑞尔的第一站。丧钟镇的卡尔文·蒙泰古会托付刚踏上冒险旅程的冒险者送去一封笔迹潦草的信件，而她正急切地等待着这封信。在她的地板之下，旅店的地窖里还关押着一名被俘的血色十字军狂热者。"}},faq={{q="谁是旅店老板瑞尼？",a="旅店老板瑞尼是被遗忘者在布瑞尔恐惧之末旅店的旅店老板。她向途经提瑞斯法林地的旅人们出售食物、饮水和通用补给。",al={"瑞尼·劳尔","布瑞尔旅店老板","布瑞尔的旅店老板是谁"}},{q="瑞尼和卡尔文·蒙泰古有什么联系？",a="在“盗贼的交易”这一任务中，为卡尔文·蒙泰古跑腿的冒险者会被派往恐惧之末旅店，直接将一封信交给瑞尼。",al={"盗贼的交易 瑞尼","卡尔文·蒙泰古的信件"}}},fx={["63a8965f"]={q="旅店老板瑞尼效忠哪一方？",a="瑞尼忠于被遗忘者和部落，在布瑞尔经营恐惧之末旅店，为提瑞斯法的亡灵以及途经此地的部落旅客提供照料。",al={"瑞尼·劳尔的阵营","瑞尼·劳尔为谁效力","瑞尼是部落的吗"}},f2640528={q="旅店老板瑞尼为什么在布瑞尔？",a="瑞尼在布瑞尔经营恐惧之末旅店，为被遗忘者居民和穿越提瑞斯法林地的旅客提供住处、补给和休憩之所。",al={"瑞尼·劳尔为什么在这里","瑞尼为什么在布瑞尔","瑞尼·劳尔与恐惧之末"}}},fp="15,160,22.369.0,20.270.0,23.159.0,46.152.0"}
P.entries["npc:renzik-the-shiv"] = {n="“剃刀”雷吉克",s="“剃刀”雷吉克是一位地精特工，也是军情七处的得力副手，常驻在暴风城Old Town的总部内。他忠实地为军情七处大师Mathias Shaw服务，负责接引来自联盟各地的潜行者新兵。",h="“剃刀”雷吉克是一位地精特工，也是军情七处的得力副手，常驻在暴风城Old Town的总部内。他忠实地为军情七处大师Mathias Shaw服务，负责接引来自联盟各地的潜行者新兵。",kw={"地精","卢修斯","mathias shaw","old town","雷吉克","潜行者","军情七处","暴风城","剃刀"},ang={["class:Rogue"]="对于联盟潜行者来说，雷吉克是你从街头小把戏跨入军情七处高风险情报网络的桥梁，他会在将你送往赤脊山的卢修斯处之前，先剔除掉那些鲁莽之徒。",["faction:Alliance"]="尽管是一名地精，雷吉克却是暴风城最有能力的谍报官员之一，在军情七处中的地位仅次于Mathias Shaw。",["race:Human"]="雷吉克站在Old Town的Mathias Shaw大师身边，是该王国军事精英中罕见的地精，证明了在暗影战争中，忠诚与能力远比种族更重要。"},sec={{t="军情七处中的地精",b="雷吉克对自己过去的经历守口如瓶。暴风城的人只知道这名地精设法加入了军情七处，现在已成为军情七处大师Mathias Shaw的副手。他既没有耐心也没有礼貌，欢迎新兵的方式通常是询问他们是准备好干活了，还是想先睡一觉。"},{t="Mathias Shaw的得力助手",b="如今，雷吉克驻扎在Old Town内机密的军情七处要塞中，担任Mathias Shaw的副手。来自联盟各地的潜行者导师，从铁炉堡到达纳苏斯，都会将他们最有前途的特工送往雷吉克处。雷吉克并不会直接把他们送去送死，而是将他们转派给赤脊山的卢修斯等实地教官，以磨练他们的生存技巧。"}},faq={{q="为什么会有地精为暴风城的军情七处工作？",a="雷吉克对自己如何来到暴风城的往事守口如瓶。人们只知道这名地精已经晋升为军情七处中Mathias Shaw的副手。",al={"为什么雷吉克效忠联盟","暴风城里的地精","为什么军情七处有地精"}},{q="为什么他被称为“剃刀”？",a="雷吉克从未向暴风城的人透露过这个绰号背后的故事。这就是Old Town里所有人能得到的关于他的全部信息，对于一名间谍来说，这或许正是他的目的。",al={"为什么叫剃刀","雷吉克绰号","“剃刀”雷吉克含义"}},{q="雷吉克为潜行者玩家提供什么帮助？",a="当联盟的潜行者证明了自己的能力后，他们的训练师会将他们送往暴风城的雷吉克处。他作为他们加入军情七处的接引人，将新兵指派给赤脊山的卢修斯等专业训练师，以确保他们掌握在野外生存的技能。",al={"雷吉克潜行者任务","雷吉克提供什么","与“剃刀”雷吉克交谈"}},{q="雷吉克通常在哪里活动？",a="他常驻在暴风城Old Town的军情七处总部内，联盟的潜行者新兵都在那里向他报到。",al={"雷吉克位置","在哪里找到雷吉克","雷吉克在哪里"}},{q="雷吉克在暴风城之外还有联系吗？",a="是的。铁炉堡和达纳苏斯的潜行者训练师会将他们有前途的学生送往他这里，而他会将新兵转介给赤脊山湖畔镇的军情七处成员卢修斯。",al={"雷吉克的情报网","雷吉克的人脉","雷吉克的盟友"}}},fx={["4d248edd"]={q="“剃刀”雷吉克是谁？",a="“剃刀”雷吉克是一名地精特工，也是暴风城情报组织军情七处的副手，直接听命于马迪亚斯·肖尔。他对自己的过去守口如瓶；暴风城所知的是，他负责审核从联盟各地送来的有潜力的盗贼，再将他们交由他人进行实战训练。",al={"“剃刀”是谁","“剃刀”雷吉克是谁","雷吉克是谁"}},["68226031"]={q="“剃刀”雷吉克想要什么？",a="雷吉克想要能胜任任务并活下来的新成员。作为军情七处马迪亚斯·肖尔的副手，他会评估送到自己面前的盗贼，再把有潜力的人交给湖畔镇的卢修斯进行实战训练，而不是把他们派出去送死。",al={"雷吉克的目标","雷吉克想要什么","雷吉克的动机"}},["0d7f210c"]={q="“剃刀”雷吉克为什么在这里？",a="雷吉克虽然以暴风城旧城区的军情七处总部为据点，但情报工作要求他与联盟各地的特工保持合作关系，其中包括达纳苏斯的隐秘盗贼圈子，以及铁炉堡的隐秘之环。他在远方的秘密据点之间联络，确保秘密通信和行动技巧得到严密协调。",al={"雷吉克为什么在这里","雷吉克为什么在达纳苏斯","雷吉克在达纳苏斯的原因"}},["0f5f7694"]={q="“剃刀”雷吉克为何声名显赫或令人畏惧？",a="雷吉克以军情七处副手、马迪亚斯·肖尔的左右手而闻名，也是王国公务体系中少见的地精。他对自己绰号的由来守口如瓶。",al={"雷吉克为何令人畏惧","雷吉克为何出名","“剃刀”雷吉克的名声"}}},fp="17,264,16.306.0,26.360.0,45.160.0,28.147.0,38.268.0,34.124.0,44.179.0"}
P.entries["npc:rethiel-the-greenwarden"] = {n="绿色守卫者雷希耶尔",s="绿色守卫者雷希耶尔是一个神秘的存在，居住在湿地绿带草地的深处。他与这片沼泽微妙的平衡息息相关，并召集旅人应对扰乱平衡的威胁。",h="绿色守卫者雷希耶尔是一个神秘的存在，居住在湿地绿带草地的深处。他与这片沼泽微妙的平衡息息相关，并召集旅人应对扰乱平衡的威胁。",kw={"沼泽兽","绿色守卫者","苔藓皮","自然","雷希耶尔","湿地"},ang={["class:Druid"]="雷希耶尔代表了艾泽拉斯荒野平衡的一种不寻常的表现形式，就像卡利姆多的远古守护者一样，直接为受创的生态系统发声。",["class:Shaman"]="雷希耶尔与沼泽在元素和物理层面上的失调相感应，当土地在污染和烈火中呻吟时，他发出了与土地共鸣的哀伤。"},sec={{t="抚平伤痕",b="雷希耶尔试图通过派遣同情他的冒险者去对付湿地的主要动乱制造者，从而减轻这片土地的苦难。他敦促访客们猎杀那些摧残野生生物、极具破坏性的苔藓皮豺狼人，夺走他们用来焚烧沼泽中活体树木的粗制燧石，并清理在沼泽水中滋生的病变的沼泽爬行者。通过这些猎杀行动，他希望让这片受创的土地恢复安宁。"},{t="沼泽卫士",b="雷希耶尔伫立在绿带草地潮湿的灌木丛中，是由苔藓、泥炭和原始植物组成的巨大生物。虽然沼泽地中的许多沼泽兽只是漫无目的地游荡，充当着好斗的掠食者，但雷希耶尔拥有罕见的意识和哀伤的声音。他眼中看到的湿地不仅是一片昏暗的土地，更是一个正在承受着外来掠夺和腐化重压而发出哀鸣的生态系统。"}},faq={{q="绿色守卫者雷希耶尔是谁？",a="雷希耶尔是一位居住在湿地绿带草地的拥有感知能力的沼泽兽。与他同类中那些毫无思想的生物不同，他能够与凡人交流，并担任着沼泽守护者的角色。",al={"雷希耶尔是谁","雷希耶尔背景故事","湿地沼泽兽npc"}},{q="我在哪里可以找到雷希耶尔？",a="他位于湿地东部的绿带草地，丹奥加兹的东北方。",al={"雷希耶尔位置","雷希耶尔在哪里"}},{q="为什么雷希耶尔需要旅人们帮助他？",a="雷希耶尔感觉到沼泽正处于深重的苦难之中。他寻求冒险者来清除入侵的威胁——特别是那些具有破坏性的苔藓皮豺狼人团伙、他们用来点燃沼泽树木的粗制燧石，以及病变的沼泽爬行者——从而为这片土地带来慰藉。",al={"雷希耶尔为什么提供任务","雷希耶尔的目标","雷希耶尔想要什么"}},{q="所有的沼泽兽都像雷希耶尔一样有感知能力吗？",a="在艾泽拉斯各地遇到的多数沼泽兽都是依靠原始、敌对的本能行动，缺乏高等智慧。雷希耶尔是一个例外，他与自然的深层调和赋予了他智慧和语言能力。",al={"沼泽兽会说话吗","有智慧的沼泽兽","雷希耶尔为什么能说话"}},{q="雷希耶尔关注哪些威胁？",a="他专注于遏制好斗的苔藓皮豺狼人，夺走他们用来焚烧活木的粗制燧石，并清除在沼泽中滋生的病变的沼泽爬行者。",al={"雷希耶尔任务","雷希耶尔的敌人","湿地的威胁与雷希耶尔"}},{q="雷希耶尔是效忠于联盟还是部落？",a="雷希耶尔对联盟友好，对部落敌对。他关心这片土地的福祉，并恳求愿意修复沼泽的联盟旅人提供帮助。",al={"雷希耶尔是联盟吗","雷希耶尔阵营","部落可以和雷希耶尔交流吗"}}},fx={["1fcd3a41"]={q="绿色守卫者雷希耶尔为什么在湿地？",a="雷希耶尔居住在绿带草地，因为周围的沼泽正饱受折磨。他与自然世界紧密相连，能亲身感受到大地的苦痛，并哀叹它在呼唤怜悯。他留在这里看守遭到污染的沼泽，寻求途经旅人的帮助，以击退腐化势力、平息燃烧的威胁，并抚慰受苦的大地。",al={"雷希耶尔为什么在这里","雷希耶尔为什么在湿地","绿色守卫者雷希耶尔的林地为何在此"}}},fp="23,207,18.425.0,21.432.1,31.188.1,25.82.0,44.264.0,41.195.1,35.174.0,50.165.0"}
P.entries["npc:rezlak"] = {n="雷兹拉克",s="雷兹拉克是一位地精企业家，也是技师工会的成员，驻扎在奥格瑞玛以南杜隆塔尔尘土飞扬的道路旁。他雇佣过往的冒险者来回收他遗失的货物，并清理那些袭击他补给车队的鹰身人。",h="雷兹拉克是一位地精企业家，也是技师工会的成员，驻扎在奥格瑞玛以南杜隆塔尔尘土飞扬的道路旁。他雇佣过往的冒险者来回收他遗失的货物，并清理那些袭击他补给车队的鹰身人。",kw={"杜隆塔尔","尘风鹰身人","雷兹拉克","确保补给线","技师工会","沙漠之风"},ang={["faction:Horde"]="虽然驻扎在奥格瑞玛外，但雷兹拉克代表了中立地精行会与新兴部落之间纯粹的交易关系。",["profession:Engineering"]="作为技师工会的代表，雷兹拉克将机械效率、实用工具和回收的零件视为重中之重。"},sec={{t="一位务实的技师工会特工",b="雷兹拉克身处连接剃刀岭与奥格瑞玛的峡谷道路旁，代表着技师工会——这是一个专注于工程学、补给线和工业实用主义的地精组织。只要生意顺遂，雷兹拉克并不关心卡利姆多的派系斗争。当凶猛的尘风鹰身人袭击了他的货运车队并导致补给路线不再安全时，雷兹拉克依然坚守原地，更愿意将危险的清剿和回收工作承包给任何想赚一笔钱的过路人。"}},faq={{q="雷兹拉克是谁？",a="雷兹拉克是一位隶属于技师工会的地精商人和工程师，也是加兹鲁维派来帮助杜隆塔尔兽人的手下之一。他驻扎在杜隆塔尔通往北方的干道旁，正在招募愿意效劳的雇佣兵来确保他的补给线安全，并从当地害虫手中夺回丢失的装备。",al={"雷兹拉克背景故事","雷兹拉克是谁","杜隆塔尔的雷兹拉克"}},{q="雷兹拉克在杜隆塔尔做什么？",a="雷兹拉克在中央平原通往奥格瑞玛峡谷通道之间的贸易路线上工作。他的补给车队遭到了尘风鹰身人的伏击，货物散落在干旱的峡谷中，补给路线也变得不再安全。",al={"雷兹拉克为何在杜隆塔尔","雷兹拉克的目的","雷兹拉克的任务"}},{q="雷兹拉克提供哪些任务？",a="雷兹拉克提供两项主要任务：“沙漠之风”（要求冒险者找回散落在峡谷底部的遗失货物）和“确保补给线”（要求消灭附近筑巢的凶猛的尘风鹰身人）。",al={"雷兹拉克的任务","雷兹拉克提供什么任务"}},{q="什么是技师工会？",a="技师工会是一个进取的地精贸易组织，负责监管机械师、发明家和物流运作。和许多地精财阀与行会一样，其成员将有利可图的商业活动和实际问题的解决置于政治忠诚之上。",al={"技师工会","雷兹拉克的阵营"}}},fx={["910e2401"]={q="雷兹拉克支持哪一方？",a="雷兹拉克代表的是地精商业利益，而非对某一阵营的忠诚。尽管他驻扎在杜隆塔尔腹地的一条主要道路旁，并与技工工会有关联，但他仍保持着地精一贯的务实中立，将工程委托和回收装备置于阵营政治之上。",al={"雷兹拉克阵营","雷兹拉克是部落的吗","雷兹拉克属于部落还是联盟"}},dba9f262={q="雷兹拉克想要什么？",a="雷兹拉克需要确保他的商队安全。来自烈风峡谷的尘风鹰身人抢走了他最近一批货物，因此他雇佣有本事的冒险者找回丢失的补给袋，并清剿枯水谷中的鹰身人，让商路恢复安全。",al={"雷兹拉克需要什么","雷兹拉克的目标","雷兹拉克的任务目的"}}},fp="6,248,32.515.0,14.286.0,32.242.0,31.255.0,27.261.0"}
P.entries["npc:rhahk-zor"] = {n="拉克佐",s="拉克佐是一个庞大的食人魔，担任死亡矿井的首席工头。他负责监管艾德温·范克里夫的地下施工工程，通过绝对的蛮力和高压手段，强迫迪菲亚潜行者的工人和矿工服从命令。",h="拉克佐是一个庞大的食人魔，担任死亡矿井的首席工头。他负责监管艾德温·范克里夫的地下施工工程，通过绝对的蛮力和高压手段，强迫迪菲亚潜行者的工人和矿工服从命令。",kw={"死亡矿井","迪菲亚","工头","锤子","食人魔","拉克佐","范克里夫"},ang={["class:Warrior"]="面对拉克佐是一场纯粹的前线耐力考验，你要对付的是一个挥舞着大锤、足以粉碎岩石和骨头的巨大食人魔。",["faction:Alliance"]="对于挺进月溪镇的联盟冒险者来说，拉克佐是第一个冷酷的证据，证明迪菲亚潜行者早已不再只是小打小闹的强盗团伙，而是组织成了一支戒备森严的军队。",["profession:Mining"]="拉克佐驱使他的矿工依靠粗暴的手段，而非对金矿脉的尊重，将西部荒野传说中的古老矿井变成了一台仓促运作的工业战争机器。"},sec={{t="深矿工头",b="在西部荒野起伏的丘陵深处，迪菲亚潜行者已将月溪镇废弃的金矿改造成了一座地下堡垒。协调这一庞大的施工工程需要铁腕纪律，而食人魔拉克佐正好填补了这一角色。他被任命为首席工头，负责监管挖掘队伍和劳工，驱使他们开凿隧道，组装范克里夫的秘密项目。"},{t="蛮力督工",b="拉克佐依靠不断的肌肉压迫而非精密的工程技术来维持秩序。他手持一把巨大的石锤，其工作监管理念既直接又不留情面。迪菲亚挖掘工和地精工程师在他面前都得动作利索，因为他们知道，进度落后或表现出反抗只会引来这位高大监工的致命重击。"}},faq={{q="拉克佐是谁？",a="拉克佐是一名食人魔，担任死亡矿井内迪菲亚潜行者的首席工头和执行者。他守卫着最初的挖掘隧道，确保劳工们不断挖掘，且不会越轨。",al={"拉克佐","死亡矿井的食人魔首领是谁","死亡矿井一号首领"}},{q="为什么食人魔会为迪菲亚潜行者工作？",a="艾德温·范克里夫的叛乱依赖于他们所能招募到的任何劳动力和雇佣兵。食人魔提供了无与伦比的物理威慑力，使拉克佐成为驱使矿井繁重挖掘工作的理想监工。",al={"为什么死亡矿井里有食人魔","拉克佐 迪菲亚"}},{q="拉克佐在矿井里的工作是什么？",a="他担任首席施工工头。拉克佐负责监督矿工、地精和迪菲亚建筑工，让他们开凿洞穴、维护设备，并为该组织修建防御工事。",al={"拉克佐做什么","拉克佐职责"}},{q="拉克佐在死亡矿井的什么位置？",a="拉克佐守卫着死亡矿井早期的采石场大厅，位于最初矿工隧道的尽头，在通往矿井深处的第一扇重型大门前。",al={"拉克佐位置","拉克佐在哪里"}},{q="拉克佐与第一次战争中的食人魔有什么联系吗？",a="在第一次战争期间，食人魔曾居住在死亡矿井，后来被黑手的部落歼灭。拉克佐到底是那些早期氏族的残余，还是仅仅是范克里夫雇佣的一个打手，目前尚无定论。",al={"第一次战争食人魔 死亡矿井","食人魔背景故事 死亡矿井"}},{q="击败拉克佐后会发生什么？",a="击败拉克佐将打破迪菲亚潜行者对外围采石场的控制，扫清他所守卫的加固爆破门，使闯入者能够更深入地进入秘密造船厂和工坊。",al={"拉克佐大门","拉克佐之后"}}},fx={["77e4622d"]={q="拉克佐支持哪一方？",a="拉克佐在艾德温·范克里夫麾下为迪菲亚潜行者效力。尽管他是一个食人魔，身边大多是人类盗贼和亡命之徒，但他身居要职，担任总工头，负责监督迪菲亚潜行者的地下挖掘和建筑工程。",al={"拉克佐为谁效力","拉克佐阵营","拉克佐是联盟的吗"}},ff75ed44={q="拉克佐与谁有关联？",a="拉克佐直接听命于迪菲亚潜行者背后的主谋艾德温·范克里夫。反过来，拉克佐指挥着驻扎在死亡矿井上层洞穴各处的迪菲亚矿工、劳工和守卫。",al={"拉克佐的关系","谁领导拉克佐","拉克佐与艾德温·范克里夫"}}},fp="9,243,23.412.0,16.365.0,17.234.0,50.231.0,37.203.0,44.163.0,67.221.0,40.202.0"}
P.entries["npc:rhinag"] = {n="林纳格",s="林纳格是一名饱受折磨的暗矛部族丛林巨魔，躲在杜隆塔尔西北边界附近的岩石中。他被该地区蝎子剧烈的毒液削弱，完全依靠路过的旅行者及时为他提供解药。",h="林纳格是一名饱受折磨的暗矛部族丛林巨魔，躲在杜隆塔尔西北边界附近的岩石中。他被该地区蝎子剧烈的毒液削弱，完全依靠路过的旅行者及时为他提供解药。",kw={"解毒剂","杜隆塔尔","需要治疗","林纳格","毒尾蝎"},ang={["race:Troll"]="在杜隆塔尔的荒原上发现一名被当地野生动物袭击的同胞，这让人深刻地意识到暗矛部族在跟随部落安家落户的过程中所面临的考验。"},sec={{t="剧毒的威胁",b="在穿越杜隆塔尔干旱地形时，林纳格不幸遭到了当地毒尾蝎的毒刺袭击。由于毒性太强，他不堪重负，只能躲在杜隆塔尔西北边界附近的岩石中。他现在身体虚弱且孤立无援，生存希望完全寄托在那些愿意在毒素最终夺去他生命之前弄到毒尾蝎解毒剂的路人身上。"}},faq={{q="林纳格是谁？",a="林纳格是一名丛林巨魔旅行者，在被当地的蝎子蛰伤后，他被困在杜隆塔尔西北边界附近，身体虚弱。",al={"林纳格是谁","林纳格背景故事","石牙农场的巨魔"}},{q="在哪里可以找到林纳格？",a="他正在杜隆塔尔西北边界附近的岩石中休息。",al={"林纳格位置","林纳格在哪里","石牙农场巨魔"}},{q="他发生了什么事？",a="在穿越杜隆塔尔平原时，林纳格被一只危险的毒尾蝎蜇伤。剧毒使他丧失了行动能力，需要解药来中和毒素，否则会有生命危险。",al={"林纳格为什么生病","什么毒害了林纳格","寻求治疗背景故事"}}},fx={["37e11902"]={q="林纳格支持哪一方？",a="林纳格与部落结盟。这名暗矛巨魔身负重伤，倒在杜隆塔尔西北边境附近，只能依靠路过的旅人和部落勇士在他危急时伸出援手。",al={"林纳格阵营","林纳格是部落的吗","林纳格的效忠对象"}},cc642833={q="林纳格想要什么？",a="林纳格急需解毒剂。他被当地一只毒尾蝎蛰伤，必须及时得到治疗，才能避免毒液对身体造成严重伤害。",al={"林纳格任务","林纳格需要什么","帮助林纳格"}},ffa3558a={q="林纳格为何会在这里？",a="林纳格被毒尾蝎蛰伤后，在杜隆塔尔西北边境附近的岩石间寻得庇护。他在那里等待援助，以免毒液彻底侵蚀他的身体。",al={"林纳格为何在这里","林纳格在哪里","是什么让林纳格来到这里"}}},fp="6,247,16.375.0,14.165.0,26.70.0,21.204.0"}
P.entries["npc:ringo"] = {n="林格",s="林格是一位不幸的地精探险家，他冒险登上了安戈洛环形山中酷热难耐的火羽山。由于不堪忍受火山令人窒息的高温和有毒的蒸汽，他倒在了一个洞穴里，迫切需要有人能帮他走下山。他的好友斯普拉格·弗罗克正在马绍尔营地焦急万分地等待着。",h="林格是一位不幸的地精探险家，他冒险登上了安戈洛环形山中酷热难耐的火羽山。由于不堪忍受火山令人窒息的高温和有毒的蒸汽，他倒在了一个洞穴里，迫切需要有人能帮他走下山。他的好友斯普拉格·弗罗克正在马绍尔营地焦急万分地等待着。",kw={"火羽山","地精","热衰竭","马绍尔营地","林格","斯普拉格·弗罗克","安戈洛环形山"},sec={{t="离火焰太近的冒险",b="虽然地精以敢于为了财富或奇珍异宝而在危险环境中冒险而闻名，但火羽山即使对他们来说也显得太过严酷。这座活火山高耸在安戈洛环形山的中心地带，不断喷发着火山灰、岩浆和沸腾的蒸汽。林格在爬到南坡半山腰时，终于因无法承受那种令人窒息的高温而倒下。他把行李散落在洞外，随后爬进一个洞穴躲避酷热，因严重的热衰竭而彻底失去了行动能力。"},{t="下山路上的艰难跋涉",b="把林格带下山本身就是一种折磨。由于脱水和中暑，这个地精身体虚弱，在下山途中多次昏倒。让他保持清醒需要不断地用水壶里的水泼他，或者偶尔给他一个响亮的耳光来让他清醒。在将他送回马绍尔营地的安全地带之前，必须时刻保持警惕，保护他避开山上暴躁的元素生物和掠食者，直到他能与他的朋友斯普拉格团聚。"}},faq={{q="林格是谁？",a="林格是安戈洛环形山的一位地精探险家，他爬上了火羽山的火山坡，结果因承受不住强烈的热衰竭而倒在了一个洞穴里。",al={"林格","林格是谁","地精林格"}},{q="林格在哪里？",a="他位于安戈洛环形山中心的火羽山，在南坡半山腰的一个洞穴里休息。",al={"林格位置","林格在哪里","找到林格"}},{q="谁在寻找林格？",a="他的好友斯普拉格·弗罗克，目前驻扎在北安戈洛的马绍尔营地，他非常担心林格的失踪。",al={"斯普拉格是谁","林格的朋友","斯普拉格·弗罗克"}},{q="为什么他在下山时总是昏倒？",a="林格因为火羽山活跃的火山热浪和烟雾导致了严重的热衰竭和脱水。每当他昏倒时，都需要用斯普拉格的水壶来唤醒他。",al={"为什么林格会昏倒","林格失去知觉","林格倒下"}},{q="林格的背包是什么？",a="这是林格的个人背包，他在因高温倒下并退入洞穴之前，将其扔在了洞口外。",al={"林格的背包","林格的包","林格丢失的包"}},{q="林格需要去哪里？",a="他需要有人安全护送他离开火山，穿过环形山地带回到马绍尔营地，他的朋友斯普拉格·弗罗克正在那里等他。",al={"我应该带林格去哪里","林格的目的地","林格护送任务终点"}}},fp="5,332,32.512.0,31.488.1,13.158.0,23.134.0,25.138.0,35.196.0,21.138.0,28.131.0"}
P.entries["npc:rivern-frostwind"] = {n="雷沃·霜翼",s="雷沃·霜翼是一位暗夜精灵骑术训练师，驻扎在冬泉谷北部的霜刀石高处。在他的霜刃豹同伴格雷希尔的陪伴下，他守护着当地的冬刃豹，并训练那些被他的组织认为有资格的骑手。只有联盟最尽职的勇士才能获得骑乘他那珍贵坐骑的殊荣。",h="雷沃·霜翼是一位暗夜精灵骑术训练师，驻扎在冬泉谷北部的霜刀石高处。在他的霜刃豹同伴格雷希尔的陪伴下，他守护着当地的冬刃豹，并训练那些被他的组织认为有资格的骑手。只有联盟最尽职的勇士才能获得骑乘他那珍贵坐骑的殊荣。",kw={"霜刀石","格雷希尔","坐骑训练师","雷沃·霜翼","冬刃豹训练师","冬泉霜刃豹"},ang={["faction:Alliance"]="对于联盟来说，雷沃·霜翼是稀有的冬泉霜刃豹的唯一提供者，让达纳苏斯之外的骑手们能通过持之以恒的努力驯服卡利姆多最凶猛的野兽之一。",["race:NightElf"]="虽然夜刃豹与艾露恩姐妹会和卡利姆多的哨兵部队有着深厚的渊源，但雷沃的霜刃豹代表了一个专门为了适应冬泉谷严酷雪景而繁育的、独特的孤立血统。"},sec={{t="霜刃豹训练大师",b="雷沃·霜翼栖身于霜刀石的冰冷岩岬之上，监管着传奇的冬泉霜刃豹的繁育与照料。虽然夜刃豹在泰达希尔和灰谷的茂密森林中游荡，但它们的亚北极表亲却是为了忍受卡利姆多北部严寒而繁育的。雷沃是这些威猛掠食者的守护者。他要求外来者证明他们保护这些野兽的决心——通过从冻原上收集新鲜的肉、清除冬泉熊怪以及击退暴走的冰霜巨人——之后，他才会考虑将一只霜刃豹托付给他们。"}},faq={{q="雷沃·霜翼是谁？",a="雷沃·霜翼是一位暗夜精灵骑术大师，同时也是冬刃豹训练师阵营的负责人，位于冬泉谷北部的霜刀石。他与忠诚的霜刃豹格雷希尔形影不离，确保这些强大的本土大型猫科动物得到保护和妥善的培育。",al={"雷沃·霜翼背景故事","霜刃豹训练师","雷沃是谁"}},{q="他为什么在冬泉谷？",a="他居住在霜刀石，旨在训练和守护该地区稀有的白色霜刃豹。这些掠食者面临着好战的冬泉熊怪、入侵的巨人和恶劣环境的持续威胁，因此雷沃在此维持秩序并照料它们的安危。",al={"雷沃为什么在这里","霜刀石的作用"}},{q="部落玩家可以与雷沃合作吗？",a="不可以。雷沃·霜翼对暗夜精灵和联盟绝对忠诚。接近霜刀石的部落旅行者会发现他完全不愿与他们打交道，他只将信任和坐骑训练留给联盟的勇士。",al={"部落可以获得冬刃豹吗","雷沃对部落友好吗"}},{q="他身边的霜刃豹是谁？",a="在雷沃身边休憩的霜刃豹是格雷希尔，它是雷沃的私人伙伴，也是冬泉谷冻原上那些耐寒猫科动物中的极品。",al={"格雷希尔是谁","雷沃·霜翼的霜刃豹"}}},fp="16,355,25.612.0,24.265.0,26.262.0,35.248.0,28.150.0"}
P.entries["npc:roetten-stonehammer"] = {n="罗顿·石锤",s="罗顿·石锤是一位富有进取心的矮人，经常在铁炉堡Hall of Explorers的图书馆里徘徊。他代表“回收者公司”的利益，负责组织探险队并招募冒险者，以处理诸如凄凉之地等偏远地区的回收工作。",h="罗顿·石锤是一位富有进取心的矮人，经常在铁炉堡Hall of Explorers的图书馆里徘徊。他代表“回收者公司”的利益，负责组织探险队并招募冒险者，以处理诸如凄凉之地等偏远地区的回收工作。",kw={"凄凉之地","hall of explorers","铁炉堡","图书馆","回收者公司","罗顿·石锤","回收"},ang={["faction:Alliance"]="罗顿是联盟在铁炉堡的关键联络人，负责组织跨海前往卡利姆多凄凉之地那片充满争议的荒芜野外的探险活动。",["race:Dwarf"]="对于在铁炉堡宏伟档案馆中浏览的矮人们来说，罗顿证明了考古好奇心往往与精明的商业回收相辅相成。"},sec={{t="图书馆里的生意",b="在Hall of Explorers图书馆那堆积着古老书籍和灰尘的环境中，罗顿·石锤始终关注着实际的回收事务。他代表“回收者公司”行事，将大胆的雇佣兵与遍布卡利姆多的高收益回收合同联系起来。他的同僚们并非仅仅出于历史好奇心而挖掘，而是着眼于从凄凉之地那崎岖荒野般危险的前线区域中回收有价值的货物、残骸和稀有试剂。"}},faq={{q="罗顿·石锤是谁？",a="罗顿·石锤是一位位于铁炉堡Hall of Explorers图书馆的矮人任务发布者。他为“回收者公司”协调行动并寻找人才，引导冒险者前往海外执行高风险的回收合同。",al={"罗顿是谁","罗顿·石锤是谁","罗顿·石锤背景故事"}},{q="什么是“回收者公司”？",a="“回收者公司”是一家致力于回收丢失货物、收集稀有试剂，以及调查危险且未开化领地（例如凄凉之地的海岸和废墟）中有价值残骸的企业。",al={"什么是回收者公司","回收者公司","回收者业务"}},{q="罗顿将冒险者派往何处？",a="罗顿指引有能力的旅行者跨海前往卡利姆多西部的凄凉之地，他的合伙人正在那里的崎岖海岸线和荒凉的原野上进行沉船回收和试剂收集工作。",al={"罗顿·石锤任务","罗顿把你派往哪里","回收者在凄凉之地的业务"}}},fx={c52b1d4d={q="罗顿·石锤支持哪一方？",a="罗顿·石锤与铁炉堡和联盟结盟，公开在探险者大厅活动。他的商业活动，尤其是代表拓荒者公司开展的业务，通过雇佣可靠的旅人去遥远而险恶的土地上找回失物和补给，为联盟利益效力。",al={"罗顿·石锤属于联盟还是部落","罗顿·石锤为谁效力","罗顿·石锤阵营"}},["4b23d3f4"]={q="罗顿·石锤想要什么？",a="罗顿正在寻找能干的冒险者，协助拓荒者公司开展海外打捞和寻回行动。他派遣受雇者前往凄凉之地这样荒凉危险的地方，打捞失踪货物，并收集同伴工作所需的奇异试剂。",al={"罗顿·石锤在寻找什么","罗顿·石锤的目的","罗顿·石锤为何需要帮助"}},f41f4afa={q="罗顿·石锤为何会在这里？",a="你可以在铁炉堡探险者大厅宏伟的图书馆里找到四处走动的罗顿。他以此为据点，查阅古代档案，与同为学者和勘探者的伙伴保持密切联系，并招募途经矮人首都的大胆探险者。",al={"罗顿为何在铁炉堡","罗顿在探险者大厅做什么","罗顿·石锤与图书馆"}}},fp="19,264,23.448.0,27.237.0,24.204.0,36.201.0"}
P.entries["npc:rorian-the-dayseeker"] = {n="Rorian the Dayseeker",s="Rorian the Dayseeker是一位年长的Skyborne人物，位于泽风岛上的森达尔村。他负责监督年轻雏鹰们发现自己天赋、步入成熟并与故乡的自然元素建立联系的过程。在他的严密引导下，新人们学习生存、传统以及为社区服务的基础知识。",h="Rorian the...",kw={"dayseeker","雏鹰","导师","rorian","skyborne","森达尔","泽风"},ang={["class:Mage"]="初出茅庐的奥术使用者会在Rorian那里找到一位善解人意的向导，他会将这些奥术学徒引导至能够磨练他们原始魔法潜力的老师那里。",["class:Shaman"]="Rorian非常强调岛屿的和谐，他派遣雏鹰们去安抚躁动的元素并与祖先的传统建立联系。",["class:Warrior"]="Rorian认可那些志向远大的战士所付出的身体上的努力，将这些渴望成为战士的人指引给那些教授战场纪律的导师。",["race:Skyborne"]="对于每一位Skyborne雏鹰来说，Rorian the Dayseeker代表了职责与传统的第一道门槛，引导你在森达尔村完成向成年的转变。"},sec={{t="森达尔村长者",b="在泽风岛上静谧的森达尔村中，Rorian the Dayseeker是Skyborne雏鹰们的主要导师之一。Rorian因其丰富的经验和沉稳的智慧而备受尊崇，他指引着年轻人在步入成年的关键时期前行。正是在他的指导下，初学者们将进行传统的成人礼，这标志着他们已准备好保卫并支持他们岛上的家园。"},{t="引导新的使命",b="除了基础试炼之外，Rorian还会根据天赋为有潜力的初学者指出专业的道路。无论是怀揣抱负的战士、猎人、潜行者、法师、萨满还是德鲁伊，雏鹰们都会被Rorian引导至岛上各处的专职训练师处。他还会提醒他们注意破坏岛屿和谐的元素骚乱，并灌输一种在疾风高地上维护平衡的永恒职责。"}},faq={{q="谁是Rorian the Dayseeker？",a="Rorian the Dayseeker是一位年长的Skyborne领袖，可以在泽风岛上的森达尔村找到。他担任新手冒险者和踏上初期试炼的Skyborne雏鹰们的主要导师。",al={"rorian是谁","rorian的角色","rorian做什么"}},{q="在哪里可以找到Rorian the Dayseeker？",a="他位于森达尔村，这是Skyborne在泽风岛上的起始定居点。",al={"rorian在哪里","rorian的位置","找到rorian"}},{q="Rorian在Skyborne的成人礼中扮演什么角色？",a="Rorian负责监督标志着雏鹰向成年转变的初始成人礼。在引导他们外出为更广泛的定居点服务之前，他会测试他们的勇气以及对岛屿生活的适应能力。",al={"rorian成人礼","skyborne试炼导师"}},{q="Rorian如何将新学员引导至他们的职业？",a="一旦新手证明了自己的价值，Rorian会建议他们去哪里寻求进阶训练，为他们指引战士、猎人、潜行者、法师、萨满或德鲁伊的道路。",al={"rorian职业任务","如何与rorian选择职业"}},{q="为什么Rorian会派遣冒险者去处理元素？",a="泽风岛周围的自然平衡极易受到扰动。Rorian会派遣有能力的初学者去调查并平息Elemental Unrest，以确保森达尔村和周围的荒野地区保持和谐。",al={"rorian与元素骚乱","为什么要对付泽风岛的元素"}},{q="谁是Aetheen of the Gales？",a="Aetheen of the Gales是泽风岛上的一位人物，当雏鹰们在岛上的职责和训练中不断进步时，Rorian会引导他们去向她求教。",al={"aetheen与rorian","aetheen of the gales"}}},fx={["60e564c2"]={q="Rorian the Dayseeker支持哪一方？",a="Rorian为自己的族人——泽风岛的天翔者效力。他驻扎在森达尔村，坚定地忠于岛上的居民，并致力于培养新一代天翔者，让他们走向世界，面对任何威胁家园的危险。",al={"rorian的阵营","rorian为谁效力","rorian的效忠对象"}},ec1df735={q="Rorian the Dayseeker想要什么？",a="Rorian一心引导初出茅庐的天翔者完成传统成年礼。他希望每位年轻学徒都能投身自己的使命——无论是武技、奥术还是自然之道，同时确保村庄免受危险的元素动乱侵扰。",al={"rorian的目标","rorian想做什么","rorian the dayseeker的使命"}},c3a8f075={q="Rorian the Dayseeker为何在森达尔村？",a="Rorian留在森达尔村，负责监督天翔者见习者的成年试炼。他在此处理岛上的事务，引导新手寻找专门的训练师，并在附近出现元素躁动时派遣能干的人手恢复平衡。",al={"rorian为何在这里","rorian为何在森达尔村","rorian为何在此地"}}},fp="20,375,24.414.0,24.408.0,28.201.0,40.91.0,52.208.0,55.181.0,57.219.0,28.156.0"}
P.entries["npc:royal-historian-archesonus"] = {n="皇家历史学家阿克瑟努斯",s="皇家历史学家阿克瑟努斯是一位服务于铁炉堡High Seat中国王麦格尼·铜须的矮人学者。她以记录北方人类王国近期灾难的学术著作而闻名，同时也负责研究古代矮人的悲剧，尤其是黑铁矮人王国的焦土遗迹。",h="皇家历史学家阿克瑟努斯是一位服务于铁炉堡High Seat中国王麦格尼·铜须的矮人学者。她以记录北方人类王国近期灾难的学术著作而闻名，同时也负责研究古代矮人的悲剧，尤其是黑铁矮人王国的焦土遗迹。",kw={"阿克瑟努斯","high seat","历史学家","铁炉堡","洛丹伦","皇家历史学家阿克瑟努斯","索瑞森"},ang={["faction:Alliance"]="她的学术著作保留了洛丹伦陷落的惨痛见证，确保南方盟友能够理解瘟疫的本质以及那些摧毁了人类北方王国的力量。",["race:Dwarf"]="阿克瑟努斯掌管着你们部族的官方记忆，保留了三锤之战中痛苦的教训，以确保铜须部族不会重蹈黑铁部族傲慢自大的覆辙。"},sec={{t="灾难记录者",b="皇家历史学家阿克瑟努斯驻扎在High Seat中距离国王麦格尼·铜须的王座仅几步之遥的地方，代表铁炉堡王室维护着历史记录。她的学术视野远远超出了卡兹莫丹的山脉。她撰写了《洛丹伦的陷落与东威尔的浩劫》以及《论瘟疫、诅咒与凋零》，追踪了人类北方疆域在天灾军团蹂躏下的可怕崩溃。阿克瑟努斯并没有逃避黑暗的历史，而是有条不紊地研究这些灾难，寻求记录下毁灭性魔法与政治崩溃背后的真相。"},{t="索瑞森的余烬",b="除了关于洛丹伦的著作外，阿克瑟努斯还负责监督关于三锤之战以及索瑞森城毁灭性灾难的调查。她从燃烧平原搜寻被遗忘的遗物和焦黑的石板，并招募冒险者前往索瑞森废墟进行探索。对于阿克瑟努斯来说，了解那场烧焦了燃烧平原并将黑铁部族束缚于炎魔之王的灾难是至关重要的国家方针——这能确保铜须部族铭记魔法与绝望究竟会带来何种后果。"}},faq={{q="我能在哪里找到皇家历史学家阿克瑟努斯？",a="皇家历史学家阿克瑟努斯位于铁炉堡的High Seat中，就在国王麦格尼·铜须的王座厅附近。",al={"阿克瑟努斯位置","皇家历史学家阿克瑟努斯在哪里","阿克瑟努斯 铁炉堡"}},{q="皇家历史学家阿克瑟努斯写过哪些书？",a="她是《洛丹伦的陷落与东威尔的浩劫》以及《论瘟疫、诅咒与凋零》的作者，这些著作记录了人类北方王国的灭亡以及天灾军团所散布的亡灵瘟疫。",al={"阿克瑟努斯的书籍","阿克瑟努斯写了什么","阿克瑟努斯传说书籍"}},{q="为什么阿克瑟努斯会对索瑞森废墟感兴趣？",a="她研究古代矮人历史，并派遣侦察兵前往燃烧平原，从索瑞森废墟中回收遗失的文物，拼凑出毁灭这座古老黑铁之都的灾难真相。",al={"阿克瑟努斯 索瑞森任务","为什么她想要索瑞森废墟","索瑞森废墟"}},{q="她在铁炉堡担任什么职务？",a="作为官方的皇家历史学家，她是国王麦格尼·铜须的首席编年史学家和档案管理员，负责汇编关于矮人古代历史以及威胁联盟的广泛世界事件的记录。",al={"阿克瑟努斯的头衔","皇家历史学家是做什么的","阿克瑟努斯是谁"}}},fx={d5335835={q="皇家历史学家阿克瑟努斯支持哪一方？",a="皇家历史学家阿克瑟努斯为国王麦格尼·铜须和铁炉堡王国效力，因此坚定地站在联盟一方。她驻扎在High Seat，凭借学术研究和档案整理，帮助王室了解古代矮人历史、周边土地以及仍威胁着王国的隐患。",al={"阿克瑟努斯的阵营","阿克瑟努斯为谁效力","阿克瑟努斯是联盟的吗"}},["48b31094"]={q="皇家历史学家阿克瑟努斯为何在High Seat？",a="阿克瑟努斯留在High Seat，因为这里是铁炉堡的政务中心，也是国王麦格尼·铜须的王座所在。作为皇家历史学家，她与矮人领袖们一同开展档案研究，可以为王座出谋划策，并委派冒险者发掘遗物和被遗忘的历史。",al={"阿克瑟努斯为何在high seat","阿克瑟努斯为何在此地","皇家历史学家阿克瑟努斯为何在这里"}},["3b340abe"]={q="皇家历史学家阿克瑟努斯与谁有关联？",a="阿克瑟努斯直接隶属于铁炉堡的国王麦格尼·铜须王廷。她的学者身份使她成为国王信任的顾问和记录官，负责记载东部王国发生的重大灾难，并从古代遗迹中寻找实物证据，例如黑铁氏族留下的遗迹。",al={"阿克瑟努斯的关系","阿克瑟努斯为谁工作","阿克瑟努斯的关联"}}},fp="26,318,25.575.0,23.541.0,44.116.0,48.213.0,56.209.0,30.198.0"}
P.entries["npc:ruga-ragetotem"] = {n="鲁迦·狂暴图腾",s="鲁迦·狂暴图腾是一位驻扎在南贫瘠之地陶拉祖营地的资深牛头人战士。作为部落新锐战士的导师，他在将他们引荐去获取定制护甲之前，会先让他们对抗附近出现的异种虫威胁，以考验他们的实力。",h="鲁迦·狂暴图腾是一位驻扎在南贫瘠之地陶拉祖营地的资深牛头人战士。作为部落新锐战士的导师，他在将他们引荐去获取定制护甲之前，会先让他们对抗附近出现的异种虫威胁，以考验他们的实力。",kw={"陶拉祖营地","巨人旷野","鲁迦·狂暴图腾","异种虫","陶拉祖","瑟恩格瑞姆·火眼","战士试炼"},ang={["class:Warrior"]="鲁迦是早期军事训练中不可或缺的里程碑，他会利用异种虫来测试你的战斗本能，随后再指引你前往瑟恩格瑞姆·火眼处获取锻造护甲。",["race:Tauren"]="鲁迦·狂暴图腾驻扎在陶拉祖营地，代表了地母之子守卫南方领土时所展现出的力量与坚韧的警觉。"},sec={{t="陶拉祖营地的导师",b="鲁迦·狂暴图腾在陶拉祖营地守望，帮助训练那些渴望在卡利姆多证明自己实力的年轻战士。由于南方的巨人旷野突然出现了令人不安的异种虫，并开始挖掘巢穴，鲁迦便以此设下考验，让年轻战士去猎杀这些虫子并获取它们的触角。通过试炼的人将赢得他的尊重，并获得前往著名护甲匠人瑟恩格瑞姆·火眼处的引荐。"}},faq={{q="鲁迦·狂暴图腾是谁？",a="鲁迦·狂暴图腾是一位位于南贫瘠之地陶拉祖营地的牛头人战士。他担任着部落后起之秀的教官与试炼大师。",al={"鲁迦是谁","鲁迦·狂暴图腾背景故事","鲁迦 陶拉祖"}},{q="鲁迦给战士们什么样的试炼？",a="鲁迦派遣战士前往南方的巨人旷野，去面对新出现的异种虫。受试者必须击杀这些好斗的虫族并取回它们的触角，以证明自己的勇气与武艺。",al={"鲁迦的试炼","巨人旷野的试炼","鲁迦想要什么"}},{q="鲁迦在试炼后会将你引荐给谁？",a="一旦战士在对抗异种虫的战斗中证明了自己，鲁迦就会指引他们向北寻找兽人护甲匠人瑟恩格瑞姆·火眼，他会为值得的战斗者打造特制护甲。",al={"鲁迦之后去哪里","鲁迦的后续任务","瑟恩格瑞姆与鲁迦"}},{q="鲁迦为什么关注巨人旷野？",a="巨人旷野最近遭到了异种虫的入侵，这是一种令人毛骨悚然的虫族威胁，它们正在大地上挖掘巢穴。鲁迦利用这一近在咫尺的危险作为实战测试，以此考验那些寻求保卫部落的战士。",al={"为什么是巨人旷野","鲁迦与虫子","陶拉祖的异种虫"}}},fx={["561e0961"]={q="鲁迦·狂暴图腾支持哪一方？",a="鲁迦·狂暴图腾坚定地支持部落和他的牛头人同胞。他驻扎在贫瘠之地南部的陶拉祖营地，帮助年轻战士为部落效力、证明自己的实力，并在卡利姆多与新兴威胁交锋，考验他们的勇气。",al={"鲁迦·狂暴图腾阵营","鲁迦为谁而战","鲁迦是部落的吗"}},["97d42651"]={q="鲁迦·狂暴图腾为何在陶拉祖营地？",a="鲁迦在陶拉祖安营扎寨，以监视南贫瘠之地并考验有潜力的部落战士。他从这里留意危险的入侵，比如巨人旷野附近成群出没的异种蝎，并派遣经受考验的战士迎击威胁，然后再让他们继续前行。",al={"鲁迦为何在陶拉祖营地","鲁迦·狂暴图腾为何在此地","鲁迦为何在贫瘠之地"}}},fp="14,262,24.438.0,22.159.0,38.202.0,42.172.0,46.207.0"}
P.entries["npc:rutgar-glyphshaper"] = {n="鲁特加尔·雕石",s="鲁特加尔·雕石是一位矮人考古学家，驻扎在希利苏斯南部的铜须营地。作为布莱恩·铜须探险队的一员，他致力于研究古代其拉虫人的遗物和符文，即便在布莱恩消失在沙漠深处之后，他依然试图解开虫巢之谜。",h="鲁特加尔·雕石是一位矮人考古学家，驻扎在希利苏斯南部的铜须营地。作为布莱恩·铜须探险队的一员，他致力于研究古代其拉虫人的遗物和符文，即便在布莱恩消失在沙漠深处之后，他依然试图解开虫巢之谜。",kw={"布莱恩","铜须","水晶","符文","雕石","玛拉利斯","雷戈","鲁特加尔","希利苏斯"},ang={["faction:Alliance"]="联盟冒险者在这片严酷的南部沙漠中发现了一处罕见的友方前哨站，尽管鲁特加尔的团队并未得到铁炉堡官方的任何支持。",["race:Dwarf"]="矮人们会认同鲁特加尔对探险者协会那执着的奉献精神，为了远古的知识，他甘愿深入充满敌意的虫巢，冒着生命危险。"},sec={{t="铜须探险队",b="鲁特加尔·雕石在布莱恩·铜须的带领下来到希利苏斯，调查广阔的虫巢并挖掘埋藏在沙漠荒原下的失落遗迹。他们在塞纳里奥要塞以南建立了铜须营地，鲁特加尔和他的同伴们经常直接深入虫巢收集碑文石板和符文神器，并常常与塞纳里奥的暗夜精灵研究人员进行合作。"},{t="虫巢中的麻烦",b="在与暗夜精灵女祭司娜塔莉亚·玛拉利斯一起进入雷戈虫巢探险时，探险队发现了一块刻有奇怪符号的水晶。这件遗物对娜塔莉亚施加了一种类似恍惚的控制，迫使矮人们将她抬出并送往塞纳里奥要塞进行治疗。后来她回到矮人营地时处于狂乱状态，要求重返虫巢，鲁特加尔和探险队被迫在激烈的争斗中将她击退，随后她逃回了沙丘之中。"},{t="破译其拉符文",b="随着布莱恩·铜须像往常一样神秘地消失在荒原中，鲁特加尔留守营地继续他们的学术研究。他专注于收集水晶拓片并破译散落在其拉虫巢各处的虫族文字，试图拼凑出虫巢的历史，并追踪布莱恩可能的去向。"}},faq={{q="鲁特加尔·雕石是谁？",a="他是一位探险家兼学者，曾随布莱恩·铜须前往希利苏斯进行考古探险，目前驻扎在铜须营地。",al={"鲁特加尔","谁是鲁特加尔","鲁特加尔·雕石信息"}},{q="布莱恩·铜须在哪里？",a="布莱恩在他惯常的单人侦察任务中独自走进了希利苏斯的荒原，留下了鲁特加尔和其余人员维护营地并研究虫巢。",al={"布莱恩在哪里","布莱恩去了哪里","布莱恩失踪"}},{q="娜塔莉亚·玛拉利斯在营地发生了什么事？",a="在受到雷戈虫巢中一块远古水晶的影响后，娜塔莉亚·玛拉利斯处于狂暴状态回到了铜须营地，在消失回沙漠之前攻击了鲁特加尔、布莱恩和探险队员。",al={"娜塔莉亚发生了什么","娜塔莉亚攻击","女祭司袭击营地"}},{q="鲁特加尔为什么要研究其拉水晶？",a="鲁特加尔试图翻译刻在虫巢水晶上的远古符文，寻求了解其拉虫人的起源，并寻找关于布莱恩下落的线索。",al={"为什么研究符文","鲁特加尔在研究什么","刻印水晶"}},{q="铁炉堡是否为探险队提供了援助？",a="没有。探险队曾向铁炉堡请求军事支援，但该矮人王国拒绝了，称其兵力在防御本国领土时已经捉襟见肘。",al={"铁炉堡增援","铁炉堡军队希利苏斯"}},{q="铜须营地位于哪里？",a="它位于希利苏斯南部，坐落在塞纳里奥要塞以南、雷戈虫巢以西的沙漠沙地中。",al={"铜须营地在哪里","营地位置"}}},fp="18,306,26.434.0,20.478.1,24.352.1,26.155.0,27.186.0,47.223.1,45.186.0,41.167.0,44.116.0"}
P.entries["npc:ruul-eagletalon"] = {n="卢尔·鹰爪",s="卢尔·鹰爪是居住在莫高雷血蹄村的一名牛头人。他驻守在定居点的外围，时刻警惕着当地的野生动物，尤其是那些侵犯牛头人领地的凶猛的风怒鹰身人。",h="卢尔·鹰爪是居住在莫高雷血蹄村的一名牛头人。他驻守在定居点的外围，时刻警惕着当地的野生动物，尤其是那些侵犯牛头人领地的凶猛的风怒鹰身人。",kw={"血蹄村","鹰爪","鹰身人","莫高雷","卢尔","风怒"},ang={["race:Tauren"]="卢尔代表了舒哈鲁所需的务实警惕，确保莫高雷这片新发现的避难所免受领地掠食者和带翼掠夺者的侵害。"},sec={{t="血蹄村的守望者",b="卢尔·鹰爪驻守在血蹄村，随着年轻的勇士从纳拉其营地赶来，他负责维护定居点的安全。虽然与荒芜贫瘠之地相比，莫高雷是一片祥和的家园，但领地掠食者和敌对生物仍不断侵扰着牧场。卢尔关心着在附近平原游荡的威胁，特别是引导有能力的旅行者去对抗那些袭击粗心游牧民和猎物的野蛮的风怒鹰身人。"}},faq={{q="卢尔·鹰爪是谁？",a="卢尔·鹰爪是驻扎在血蹄村的一名牛头人，他通过引导冒险者应对莫高雷各地的威胁来保护定居点。",al={"卢尔是谁","卢尔·鹰爪npc","血蹄村卢尔"}},{q="卢尔·鹰爪要求旅行者处理什么威胁？",a="卢尔警告说，敌对的风怒鹰身人在莫高雷筑巢，并委托有能力的勇士在她们伤害村庄之前削减她们的数量。",al={"卢尔任务","风怒鹰身人的威胁","莫高雷鹰身人任务"}},{q="卢尔·鹰爪在哪里可以找到？",a="他站在血蹄村的土地上，位于莫高雷中部石牛湖的岸边。",al={"卢尔·鹰爪位置","寻找卢尔","卢尔在哪里"}}},fx={["17869be4"]={q="卢尔·鹰爪支持哪一方？",a="卢尔·鹰爪坚定地支持血蹄牛头人和部落。他驻扎在血蹄村，忠于自己的族人，并致力于保护莫高雷的祖传牧场。",al={"卢尔·鹰爪阵营","卢尔是部落的吗","卢尔·鹰爪的效忠对象"}},["5abfc287"]={q="卢尔·鹰爪为何在血蹄村？",a="卢尔留在血蹄村，保护村庄及附近平原免受周边威胁，并招募能干的旅人，清除侵入牛头人领地的凶猛风怒鹰身人。",al={"卢尔为何在这里","卢尔·鹰爪的使命","卢尔在血蹄村做什么"}}},fp="15,235,20.473.0,23.154.0,60.156.0,35.125.0"}
P.entries["npc:ruul-snowhoof"] = {n="鲁尔·雪蹄",s="鲁尔·雪蹄是一名牛头人德鲁伊，被关押在灰谷北部的Thistlefur Hold内。他以熊形态被困在一个简陋的笼子里，依靠部落的冒险者将他救出并引导他前往安全地带。",h="鲁尔·雪蹄是一名牛头人德鲁伊，被关押在灰谷北部的Thistlefur Hold内。他以熊形态被困在一个简陋的笼子里，依靠部落的冒险者将他救出并引导他前往安全地带。",kw={"熊形态","鲁尔的自由","鲁尔·雪蹄","碎木岗哨","thistlefur熊怪","thistlefur hold","雅玛·雪蹄"},ang={["class:Druid"]="发现一名塞纳里奥之路的兄弟以野兽形态被腐化的熊怪囚禁，突显了侵蚀灰谷野生动物和原始部落的蔓延腐化。",["race:Tauren"]="鲁尔属于受人尊敬的雪蹄家族；营救他可以确保你们族人的一员能活着回到碎木岗哨的姐姐雅玛身边。"},sec={{t="笼中的熊",b="鲁尔·雪蹄冒险进入灰谷北部，却落入了被腐化的Thistlefur熊怪手中。在被俘获时，他变身为强大的熊——他的俘获者误以为他是一头真正的野兽。熊怪们没有直接杀掉他，而是将他关在Thistlefur Hold深处的一个木笼子里，让他慢慢饿死。由于变得虚弱且无法安全解除变身或独自杀出重围，鲁尔只能等待部落的盟友来打开锁、击退看守，并清理出一条穿过大兽穴的道路，以便他能回到碎木岗哨，与他的姐姐雅玛·雪蹄团聚。"}},faq={{q="为什么鲁尔·雪蹄以熊形态被关在笼子里？",a="鲁尔是一名牛头人德鲁伊，在面对Thistlefur熊怪时变身为熊形态。他的俘获者将他误认为是真正的野兽，而不是变身的德鲁伊，因此将他关在了他们据点深处的一个笼子里。",al={"为什么鲁尔是熊","鲁尔·雪蹄熊形态","为什么他被关在笼子里"}},{q="为什么熊怪不直接杀了鲁尔？",a="被腐化的Thistlefur熊怪选择将鲁尔以野兽形态囚禁，出于他们自身的残忍或恶意，他们让他在笼中慢慢挨饿，而不是直接杀了他。",al={"为什么要饿死鲁尔","熊怪想对鲁尔做什么"}},{q="鲁尔在逃出Thistlefur Hold后去了哪里？",a="在被护送通过熊怪巡逻队到达Thistlefur Hold外的安全地带后，鲁尔会指引他的救命恩人去向驻扎在碎木岗哨的姐姐雅玛·雪蹄报告他的生还消息。",al={"鲁尔去哪里了","鲁尔·雪蹄的目的地"}},{q="联盟玩家可以与鲁尔·雪蹄互动吗？",a="不能。鲁尔·雪蹄忠于部落，他只会向发现他所在笼子的部落冒险者提供他的逃脱任务和协助。",al={"鲁尔是部落专属吗","联盟与鲁尔·雪蹄"}}},fx={["6802c209"]={q="鲁尔·雪蹄是谁？",a="鲁尔·雪蹄是一名牛头人德鲁伊，被困在灰谷的Thistlefur Hold深处。他变形成熊形态时被敌对的Thistlefur熊怪俘获，之后一直隐瞒自己的真实身份，靠着俘虏们误以为他只是一头普通野兽才得以生存。尽管处境严峻，他依然坚忍不拔，依靠训练和内心的力量支撑下去，等待友善的旅人将他救出牢笼。",al={"鲁尔是谁","鲁尔·雪蹄背景","thistlefur hold里的熊是谁"}},f3e5b1ed={q="鲁尔·雪蹄站在哪一方？",a="鲁尔效忠于部落，也秉承着牛头人深厚的文化传统和德鲁伊传承。被困在Thistlefur Hold时，他将全部希望寄托于部落勇士，盼望他们打开牢笼，护送他躲过熊怪巡逻队，重获自由。联盟冒险者会发现他对他们不予理会，也不愿接见他们。",al={"鲁尔属于部落还是联盟","鲁尔的阵营","鲁尔·雪蹄效忠谁"}},["503a6073"]={q="鲁尔·雪蹄想要什么？",a="鲁尔只想逃出牢笼，活着熬过熊怪对他的慢慢折磨。获救后，他眼下最要紧的是安全地杀出兽穴，并把自己还活着的消息带回族人那里。他会请帮助过他的人把这个好消息带给附近的家人。",al={"鲁尔想要什么","鲁尔·雪蹄的目标","为什么要帮助鲁尔"}},ebe6887d={q="鲁尔·雪蹄和谁有关系？",a="鲁尔是雅玛·雪蹄的兄弟。雅玛目前驻扎在灰谷的碎木岗哨。逃出Thistlefur Hold、脱离险境后，他最挂心的是让她不再担忧，因此会派救援者去告诉她自己已经活着逃出了俘虏之手。",al={"鲁尔·雪蹄的家人","鲁尔的姐妹","鲁尔和谁有亲缘关系"}}},fp="13,209,16.620.0,38.224.0,38.200.0,50.194.0,49.135.0"}
P.entries["npc:rwag"] = {n="鲁瓦格",s="鲁瓦格是常驻在大兽穴的兽人潜行者训练师，大兽穴位于杜隆塔尔的试炼谷内。他在部落的注视下，教导新来的兽人和巨魔学习潜行、诡计和卑鄙战斗的艺术。",h="鲁瓦格是常驻在大兽穴的兽人潜行者训练师，大兽穴位于杜隆塔尔的试炼谷内。他在部落的注视下，教导新来的兽人和巨魔学习潜行、诡计和卑鄙战斗的艺术。",kw={"杜隆塔尔","纳托克","潜行者","鲁瓦格","大兽穴","训练师","试炼谷"},ang={["class:Rogue"]="对于走进试炼谷的年轻兽人和巨魔潜行者来说，鲁瓦格是他们最初的诡诈之道导师，负责教授早期的进攻技巧并解读密文羊皮纸。",["race:Orc"]="鲁瓦格代表了兽人生存中务实、不加修饰的一面，证明了即使在萨尔建立的崇尚荣誉的新部落中，阴影和冷钢依然至关重要。"},sec={{t="试炼谷之影",b="鲁瓦格在大兽穴这个洞穴深处工作，负责训练初出茅庐的潜行者、扒手和窃贼，让他们在踏入杜隆塔尔更广阔的世界之前做好准备。虽然新部落崇尚尚武荣誉和战场勇武，但鲁瓦格深知，在残酷无情的沙漠中，潜行、毒药和一柄放对位置的匕首仍然是不可或缺的生存工具。他密切关注着试炼谷的一举一动，并对同样在大兽穴中避难的黑暗修行者，特别是术士纳托克，抱有极深的怀疑。"}},faq={{q="鲁瓦格是谁？",a="鲁瓦格是一位位于试炼谷大兽穴内的兽人潜行者训练师。他负责教导刚开始在杜隆塔尔进行训练的新手兽人和巨魔潜行者。",al={"鲁瓦格是谁","鲁瓦格 试炼谷","兽人潜行者训练师"}},{q="我在哪里能找到鲁瓦格？",a="鲁瓦格位于大兽穴的深处，那是一个开凿在杜隆塔尔试炼谷岩壁中的洞穴，他与其他几位职业训练师待在一起。",al={"鲁瓦格位置","鲁瓦格在哪里","找到鲁瓦格"}},{q="鲁瓦格对大兽穴里的术士有什么看法？",a="鲁瓦格公开表示不信任与他共享大兽穴的术士，特别是对邪能使用者纳托克保持警惕，并指出黑暗魔法和神秘的邪教徒需要时刻保持警惕。",al={"鲁瓦格 纳托克","为什么鲁瓦格不信任术士","鲁瓦格 密文羊皮纸"}},{q="鲁瓦格训练哪些职业？",a="鲁瓦格只训练潜行者，提供诸如刺骨等技能的早期战斗指导，并应破碎之手的要求，留意新招募的成员，传递任何破碎之手可能需要的情报。",al={"鲁瓦格教什么","鲁瓦格能训练我吗"}}},fx={["864b6a89"]={q="鲁瓦格站在哪一方？",a="鲁瓦格效力于部落，驻扎在试炼谷，负责教导初出茅庐的兽人和巨魔扒手。他更深层的忠诚属于碎手氏族；他相信碎手氏族能让部落恢复昔日的荣光，不受他口中“大酋长的怯懦”所阻。",al={"鲁瓦格的阵营","鲁瓦格属于部落吗","鲁瓦格效力于谁"}},c0621c2a={q="鲁瓦格想要什么？",a="鲁瓦格的目标是磨练那些在试炼谷起步的潜行者的潜行、狡黠和战斗技巧。他要求学徒掌握无声的步法、精准的打击和敏锐的警觉，同时留心附近那些不可信的家伙。",al={"鲁瓦格想要什么","鲁瓦格的目标","鲁瓦格的动机"}},["4b9fa3b0"]={q="鲁瓦格为什么在这里？",a="鲁瓦格驻守在大兽穴内，以便考察并指导渴望踏上暗影之路的新兵。杜隆塔尔和前线战士一样需要斥候与行踪隐秘的利刃，而他会确保那些擅长盗窃和暗中行事的人受到适当的训练。",al={"鲁瓦格为什么在大兽穴","鲁瓦格在试炼谷的职责","鲁瓦格为什么在杜隆塔尔"}},["0a3d842f"]={q="鲁瓦格和谁有关系？",a="鲁瓦格与试炼谷的其他职业导师共事，不过他对术士训练师Nartok始终保持警惕，并公开表示不信任对方。他与部落的潜行者训练网络以及他派往杜隆塔尔各地的年轻斥候关系密切。",al={"鲁瓦格的人际关系","鲁瓦格认识谁","鲁瓦格和nartok"}}},fp="4,229,21.514.0,12.159.0,22.152.0,48.195.0,30.220.0"}
P.entries["npc:saelienne"] = {n="Saelienne",s="旅店老板塞琳尼管理着位于达纳苏斯工匠区的旅店。她为疲惫的旅行者和当地工匠提供食物、饮料，以及在这座暗夜精灵主城中心的一处宁静的炉石休息地。",h="旅店老板塞琳尼管理着位于达纳苏斯工匠区的旅店。她为疲惫的旅行者和当地工匠提供食物、饮料，以及在这座暗夜精灵主城中心的一处宁静的炉石休息地。",kw={"工匠区","达纳苏斯","万圣节","炉石","旅店老板","saelienne","泰达希尔"},ang={["faction:Alliance"]="前往泰达希尔偏远树冠的联盟使者和工匠们依靠塞琳尼提供食物、饮料和温馨的炉石庇护所。",["race:NightElf"]="对于从泰达希尔荒野归来的暗夜精灵冒险者来说，塞琳尼的旅店在达纳苏斯的工匠之中提供了一个熟悉的炉火。"},sec={{t="工匠区的待客之道",b="旅店老板塞琳尼的旅店坐落在达纳苏斯工匠区繁忙的作坊与摊位之间，为当地居民和访客提供了一处宁静的休憩之所。作为炉火的守护者，她接待着来自卡利姆多各地乃至更遥远地区的冒险者，供应暗夜精灵的标准茶点以及运抵港口的货品。她的旅店是那些在锻造炉或织布机前辛苦劳作后的工匠们聚集休息的主要场所。"}},faq={{q="我在哪里可以找到旅店老板塞琳尼？",a="塞琳尼位于达纳苏斯的工匠区，经营着当地的一家旅店，毗邻各专业的训练师和工艺商店。",al={"塞琳尼位置","塞琳尼在哪里","达纳苏斯旅店老板位置","工匠区旅店"}},{q="塞琳尼提供什么服务？",a="她担任旅店老板，允许玩家将炉石绑定在达纳苏斯。她还出售各种适合恢复生命值和法力值的食物和饮料。",al={"塞琳尼做什么","塞琳尼商人","绑定炉石达纳苏斯"}},{q="塞琳尼提供节日任务吗？",a="在万圣节庆典期间，塞琳尼会参与节日庆祝活动，为联盟冒险者提供任务“为杏仁糖起舞”，以换取节日糖果。",al={"塞琳尼任务","万圣节塞琳尼","为杏仁糖起舞"}}},fx={["023ad64a"]={q="Saelienne是谁？",a="Saelienne是一名暗夜精灵旅店老板，居住在达纳苏斯的工匠区。她为旅人和当地居民打理食宿，提供食物、清爽的饮品和安歇之处，让你可以在泰达希尔的树荫下绑定炉石。",al={"saelienne是谁","saelienne的身份","旅店老板塞琳尼"}},bc46f8f9={q="Saelienne站在哪一方？",a="她坚定地支持达纳苏斯和更广大的联盟。作为暗夜精灵首都中心地带的旅店老板，她欢迎所有来到世界之树、需要休息和补给的盟友冒险者。",al={"saelienne的阵营","saelienne属于联盟吗","saelienne效忠谁"}},a41cab7b={q="Saelienne想要什么？",a="Saelienne只想照料好自己的旅店，让到访工匠区的旅人有地方栖身、吃饱喝足，还能睡上一张舒适的床。除了提供食宿和交易之外，她远离政治与纷争。",al={"saelienne想要什么","saelienne的动机","saelienne的目标"}},["28654c22"]={q="Saelienne为什么在达纳苏斯？",a="她靠在工匠区经营旅店谋生，照料往来于此的工匠、商人和旅人。她的岗位正处于泰达希尔繁忙的日常商贸中心。",al={"saelienne为什么在这里","saelienne与工匠区","saelienne为什么在达纳苏斯"}}},fp="9,227,26.471.0,37.135.0,37.166.0,40.177.0"}
P.entries["npc:sally-whitemane"] = {n="大检察官怀特迈恩",s="大检察官怀特迈恩是血色十字军的大检察官，统领着血色修道院的大教堂。作为一名强大的圣光牧师，她对亡灵深入骨髓的仇恨驱使着血色十字军盲目而激进的狂热。她与血色指挥官雷诺·莫格莱尼共同领导着该组织在洛丹伦各地的军事和意识形态行动。",h="大检察官怀特迈恩是血色十字军的大检察官，统领着血色修道院的大教堂。作为一名强大的圣光牧师，她对亡灵深入骨髓的仇恨驱使着血色十字军盲目而激进的狂热。她与血色指挥官雷诺·莫格莱尼共同领导着该组织在洛丹伦各地的军事和意识形态行...",kw={"大教堂","大检察官","虔诚的莱雷恩","雷诺·莫格莱尼","莎丽·怀特迈恩","血色十字军","血色修道院","怀特迈恩"},ang={["class:Paladin"]="对于白银之手骑士团的圣骑士们来说，怀特迈恩的领导正体现了洛丹伦保卫者悲剧性的堕落——他们抛弃了仁慈与正义，转而进行不分青红皂白的清洗。",["class:Priest"]="怀特迈恩展示了当圣光与盲目的狂热融合时所产生的恐怖力量，也作为一种警示，展示了信念如何扭曲成为狂热的冷酷无情。",["faction:Alliance"]="虽然她曾经是洛丹伦的一名联盟公民，但怀特迈恩的血色十字军现在会攻击任何靠近其领地的外来者，这迫使南海镇的忠诚派不得不面对他们曾经的亲人如今已变成怪物的现实。",["race:Undead"]="对于遗忘者而言，怀特迈恩体现了血色十字军拒绝区分无脑天灾军团与有自由意志的亡灵的态度，因此，彻底消灭她对于幽暗城的生存至关重要。"},sec={{t="血色十字军大检察官",b="怀特迈恩在血色十字军的层级中迅速崛起，最终成为了大检察官，并接管了血色修道院宏伟的大教堂。她以对圣光的恐怖掌控力而闻名，凭借其绝对的信念成为了血色十字军最重要的标志之一，将圣光化作无情的武器，对任何被视为不洁之物的事物施加惩戒。"},{t="大教堂的目标",b="截止到25年，怀特迈恩的狂热已经激怒了双方阵营的敌人。在南海镇，虔诚的莱雷恩认为血色十字军已经无可救药地堕落到了腐化与疯狂的深渊，他呼吁消灭怀特迈恩和莫格莱尼，以恢复该组织最初的美德。与此同时，在幽暗城内，恐惧魔王瓦里玛萨斯策划了针对修道院的袭击，旨在粉碎这些就在遗忘者家门口活动的狂热分子。"}},faq={{q="大检察官怀特迈恩是谁？",a="大检察官怀特迈恩是血色十字军的大检察官。她从位于提瑞斯法林地的血色修道院内的大教堂统领着该组织的宗教与审判事务，并与指挥官雷诺·莫格莱尼并肩作战。",al={"怀特迈恩背景故事","谁是大检察官怀特迈恩","血色修道院首领"}},{q="为什么怀特迈恩如此痛恨亡灵？",a="她的仇恨反映了血色十字军的信条。该组织由洛丹伦在亡灵天灾中沦陷后的幸存者建立，并将每一个亡灵，无论是有思维的还是无意识的，都视为必须清除的污秽。怀特迈恩在这场战争中将圣光作为最无情的武器使用。",al={"为什么怀特迈恩痛恨天灾军团","怀特迈恩来历","怀特迈恩家族"}},{q="为什么联盟想要杀死怀特迈恩？",a="虔诚的莱雷恩曾是南海镇的一名十字军成员，他认为血色十字军已经陷入了妄想和疯狂。他请求联盟的勇士消灭怀特迈恩和莫格莱尼，希望该组织能回归其曾经荣耀的初衷。",al={"虔诚的莱雷恩与怀特迈恩","联盟为什么要杀死怀特迈恩","以圣光之名任务"}},{q="为什么部落想要杀死怀特迈恩？",a="瓦里玛萨斯和幽暗城的遗忘者将血色十字军视为就在他们首都之外的一个活跃的敌对势力。这位恐惧魔王下令处决她，旨在粉碎修道院的领导层，并消除对遗忘者领地的直接威胁。",al={"瓦里玛萨斯怀特迈恩任务","进入血色修道院","部落为什么要杀死怀特迈恩"}},{q="怀特迈恩与雷诺·莫格莱尼是什么关系？",a="怀特迈恩与雷诺·莫格莱尼是血色修道院的双领袖。他们在大教堂并肩作战，共享着亲密的纽带，并共同致力于十字军针对亡灵的圣战。",al={"怀特迈恩与莫格莱尼","指挥官莫格莱尼与怀特迈恩"}}},fx={f63bdc05={q="大检察官怀特迈恩站在哪一方？",a="怀特迈恩是血色十字军狂热的领袖，担任大检察官一职。她不效忠于联盟或部落，对外来者抱有极度的猜疑和狂热的敌意。怀特迈恩坚定地信奉十字军的教条，与指挥官雷诺·莫格莱尼并肩作战，肃清所有挡在他们道路上的人。",al={"怀特迈恩的阵营","怀特迈恩为谁而战","怀特迈恩效忠谁"}},["89d62c4b"]={q="大检察官怀特迈恩想要什么？",a="怀特迈恩渴望彻底根除亡灵。和血色十字军的其他成员一样，她把每个亡灵都视为憎恶之物，无论是没有心智的天灾亡灵，还是拥有自由意志的被遗忘者。只有肃清天灾以及她认定受到亡灵污染的人，她才能找到使命。",al={"怀特迈恩的目标","怀特迈恩想要什么","怀特迈恩的动机"}},["04c4cc89"]={q="大检察官怀特迈恩为什么在这里？",a="作为大检察官，怀特迈恩在血色修道院大教堂深处指挥血色十字军的行动。她在那里统领他们对洛丹伦北部庇护所的防御，鼓舞十字军战士，并肃清所有擅闯圣地要塞的人。",al={"怀特迈恩为什么在修道院","怀特迈恩在大教堂的原因","怀特迈恩为什么在这里"}},["7daae460"]={q="大检察官怀特迈恩为何声名远扬或令人畏惧？",a="怀特迈恩因其毫不动摇的狂热信念和强大的神圣魔法造诣而令人畏惧。身为血色十字军的大检察官，她以残酷肃清疑似腐化者而声名可怖，还能在战斗中复活倒下的盟友，包括指挥官莫格莱尼。",al={"怀特迈恩为何令人畏惧","怀特迈恩的名声","怀特迈恩为何声名远扬"}}},fp="25,360,30.360.0,24.444.1,33.232.0,43.291.0,42.246.0,39.253.0,55.207.0"}
P.entries["npc:salma-saldean"] = {n="萨尔玛·萨丁",s="萨尔玛·萨丁是一位坚韧的西部荒野开拓者，她与丈夫农夫萨丁共同经营着萨丁农场。在这个深受暴徒蹂躏且被暴风城遗弃的地区，她敞开大门，用温暖的餐食招待过往的旅人，以换取他们在农场周围提供的些许帮助。",h="萨尔玛·萨丁是一位坚韧的西部荒野开拓者，她与丈夫农夫萨丁共同经营着萨丁农场。在这个深受暴徒蹂躏且被暴风城遗弃的地区，她敞开大门，用温暖的餐食招待过往的旅人，以换取他们在农场周围提供的些许帮助。",kw={"农夫萨丁","血牙野猪的肝馅饼","萨丁农场","萨尔玛·萨丁","炖肉","西部荒野","西部荒野炖肉"},ang={["faction:Alliance"]="萨尔玛体现了联盟开拓者那种顽固的坚毅，尽管被王室忽视，他们依然拒绝放弃自己的生计。",["profession:Cooking"]="萨尔玛·萨丁是穿越西部荒野的厨师们的重要联系人，她提供诸如西部荒野炖肉和血牙野猪的肝馅饼等实用食谱，充分利用了当地的野生动物。",["race:Human"]="对于人类旅人来说，拜访萨尔玛是一个感人的提醒，让他们意识到在王国坚固的首都之外，暴风城的平民们正面临着怎样的困苦。"},sec={{t="困境中的款待",b="尽管邻近的农场已被迪菲亚潜行者洗劫并烧毁，萨丁一家仍设法守住了他们的炉火。萨尔玛总是用热情的态度和炉灶上那锅热气腾腾的食物迎接旅人，并时刻留意着愿意在农场帮把手的能人。"},{t="维持生计",b="在西部荒野求生需要足智多谋。萨尔玛利用这片土地上能找到的一切来养活她的家人和过客，并教导旅人如何制作当地的特色菜肴，如血牙野猪的肝馅饼，以及她那远近闻名的西部荒野炖肉，原料包括野猪、秃鹫、鱼人和野生的秋葵。"}},faq={{q="萨尔玛·萨丁是谁？",a="萨尔玛·萨丁是一位人类农夫，与她的丈夫一起生活在西部荒野中心地带的萨丁农场。她在地区崩溃的困境中努力维持农场运转，并为旅人提供慰藉和食物。",al={"萨尔玛是谁","萨尔玛·萨丁背景故事","萨丁农场妻子"}},{q="萨尔玛·萨丁在哪里？",a="你可以在萨丁农场的农舍外找到她，该农场位于西部荒野中心地带的道路旁，就在通往哨兵岭的十字路口以北。",al={"萨尔玛位置","萨尔玛·萨丁在哪里","萨丁农场在哪里"}},{q="萨尔玛·萨丁教授什么配方？",a="萨尔玛分享了制作当地特色补给的秘诀，其中最著名的就是血牙野猪的肝馅饼和西部荒野炖肉，这些食物使用了从西部荒野各处野生动物身上搜集来的食材。",al={"西部荒野炖肉配方","萨尔玛食物","血牙野猪的肝馅饼"}},{q="为什么萨丁一家很难找到帮手？",a="西部荒野的大多数农夫和劳工因掠夺成性的暴徒、失控的收割机人以及暴风城皇家军队的缺席而弃地逃亡，导致仅存的几户开拓者人手严重不足。",al={"为什么农场被遗弃","为什么萨丁农场需要帮助","西部荒野农场被弃"}},{q="萨丁一家是如何在迪菲亚潜行者的威胁下生存下来的？",a="萨丁一家依靠过往的冒险者和他们自身的韧性来保卫家园。尽管身处险境，他们顽固地拒绝放弃自己的土地和家园。",al={"萨丁与迪菲亚","为什么农场没有被烧毁"}},{q="萨尔玛的丈夫是谁？",a="她是农夫萨丁的妻子，他们一起在农场工作，试图应对故障的收割机人和狂暴的野兽。",al={"萨尔玛丈夫","农夫萨丁"}}},fx={["4311c40a"]={q="萨尔玛·萨丁站在哪一方？",a="萨尔玛坚定地站在西部荒野的诚实居民和艰难度日的农民一边。尽管她在精神上效忠联盟，但暴风城没有伸出援手，她和丈夫只能自力更生，把希望全都寄托在邻近的农户能够互相扶持、行事正直。",al={"萨尔玛·萨丁的阵营","萨尔玛支持谁","萨尔玛·萨丁站在哪一方"}},["31948cda"]={q="萨尔玛·萨丁想要什么？",a="萨尔玛想让家里的农场继续经营下去，也希望路过的人都能吃上一顿热饭、有人倾听。大多数能干活的人都因困苦和匪患离开了，她急需有人帮忙收集野猪人肝脏等材料，好让那些坚守在西部荒野的人继续撑下去。",al={"萨尔玛想要什么","萨尔玛·萨丁的目标","萨尔玛需要什么"}},f65c3c8f={q="萨尔玛·萨丁为什么在这里？",a="萨尔玛留在萨丁农场，因为这里是她的家。即使邻近的定居者因当地日益加剧的动荡和无法无天而逃离，她和丈夫仍拒绝放弃自己的土地，决心耕种田地，并为任何需要庇护的人提供慰藉。",al={"萨尔玛为什么在西部荒野","为什么留在萨丁农场","萨尔玛·萨丁为何在这里"}}},fp="13,281,26.291.0,25.281.0,21.208.0,31.166.0,38.183.0,48.227.0,51.173.0,23.139.0"}
P.entries["npc:sara-balloo"] = {n="萨拉·巴鲁",s="萨拉·巴鲁是一位居住在铁炉堡Military Ward的悲伤的矮人遗孀。她终日沉浸在对亡夫萨利·巴鲁的哀思之中，紧紧抓着他服役最后日子里留下的任何遗物或信息。",h="萨拉·巴鲁是一位居住在铁炉堡Military Ward的悲伤的矮人遗孀。她终日沉浸在对亡夫萨利·巴鲁的哀思之中，紧紧抓着他服役最后日子里留下的任何遗物或信息。",kw={"丹莫罗","铁炉堡","magni bronzebeard","military ward","萨拉·巴鲁","萨利·巴鲁","遗孀"},ang={["faction:Alliance"]="将消息带给萨拉为一名联盟士兵的家庭画上了句号，突显了艾泽拉斯各地战斗背后那些令人心碎的家庭现实。",["race:Dwarf"]="对于路过Military Ward的矮人们来说，萨拉·巴鲁是一个令人心酸的提醒，让人意识到那些亲人奔赴前线保卫卡兹莫丹的家庭所承受的个人代价。"},sec={{t="遗孀的守望",b="萨拉·巴鲁站在铁炉堡繁忙的Military Ward中，她那忧郁的身影与周围喧嚣的兵器撞击声和军事演练形成了鲜明的对比。她的丈夫萨利·巴鲁在远离家乡的战场上阵亡，只留下她独自面对回忆和挥之不去的哀伤。对萨拉而言，只有找回那些只言片语——一封跨越群山，从他牺牲现场寄来的，承载着萨利深情的绝笔信——才能让她得到些许慰藉。"},{t="铭记的呼唤",b="萨拉不愿让她丈夫的牺牲悄无声息地被遗忘，她寻求的不仅仅是安慰。通过诚挚的恳求，她向国王麦格尼·铜须请愿，希望萨利和其他像他一样阵亡的士兵能得到王室的正式表彰与铭记，确保那些普通矮人家庭所付出的代价不被遗忘。"}},faq={{q="萨拉·巴鲁是谁？",a="萨拉·巴鲁是一位居住在铁炉堡Military Ward的矮人女性。她是阵亡矮人战士萨利·巴鲁的遗孀。",al={"萨拉·巴鲁","萨拉·巴鲁是谁","萨拉·巴鲁 铁炉堡"}},{q="我在哪里可以找到萨拉·巴鲁？",a="她可以在铁炉堡山城的Military Ward找到，站在训练场和军营附近。",al={"萨拉·巴鲁在哪里","萨拉·巴鲁位置","寻找萨拉·巴鲁"}},{q="她的丈夫发生了什么事？",a="她的丈夫萨利·巴鲁在服役期间牺牲了。他的遗物和一封被水浸湿的绝笔信一度遗失，直到一位冒险者将它们找回。",al={"萨拉·巴鲁的丈夫","萨利·巴鲁是谁","萨利发生了什么事"}},{q="萨拉对萨利的信做了什么？",a="在读过亡夫那感人至深的遗言后，萨拉写了一份请愿书呈交给国王麦格尼·铜须，请求对萨利的牺牲给予应有的认可与纪念。",al={"萨利·巴鲁的信","萨拉·巴鲁的请愿","萨拉·巴鲁想要什么"}}},fx={["658d468d"]={q="萨拉·巴鲁为什么在军事区？",a="萨拉住在铁炉堡的军事区，生活在王国的士兵和老兵中间。她的丈夫萨利在战争中丧生后，便一直留在这座山城的军政中心附近；这里的人们缅怀那些为保卫王国而牺牲的人。",al={"萨拉·巴鲁为什么在铁炉堡","萨拉·巴鲁为什么在这里","萨拉·巴鲁军事区"}},["736253da"]={q="萨拉·巴鲁站在哪一方？",a="萨拉·巴鲁是铁炉堡的忠实公民，也是联盟的拥护者。她的丈夫萨利·巴鲁已故，他曾为矮人王国效力，驻守萨多尔大桥时战死。如今，她仍留在族人中间，接受国王麦格尼·铜须的统治。",al={"萨拉·巴鲁的阵营","萨拉·巴鲁属于联盟吗","萨拉·巴鲁效忠谁"}}},fp="11,223,15.401.0,21.343.1,19.132.0,29.121.0,29.148.1,38.163.1"}
P.entries["npc:sara-timberlain"] = {n="萨拉·迪博雷恩",s="萨拉·迪博雷恩是一位技术娴熟的裁缝，居住在艾尔文森林东部的东谷伐木场。她以擅长利用回收布料进行缝纫而闻名，并通过为暴风城军队缝制布甲和皮甲装备来支援战争。",h="萨拉·迪博雷恩是一位技术娴熟的裁缝，居住在艾尔文森林东部的东谷伐木场。她以擅长利用回收布料进行缝纫而闻名，并通过为暴风城军队缝制布甲和皮甲装备来支援战争。",kw={"东谷","亚麻布","伐木场","萨拉·迪博雷恩","女裁缝","暴风城军队","裁缝"},ang={["faction:Alliance"]="像东谷这样的边远定居点直接支持着王国的防御，当地的工匠为资源匮乏的暴风城军队提供基础护甲。",["profession:Tailoring"]="萨拉展现了边境裁缝的足智多谋，她将粗糙的亚麻布和强盗布料碎屑制作成军队订购的功能性服装。"},sec={{t="边境的针线活",b="萨拉·迪博雷恩位于东谷伐木场西侧的一间小屋旁，在伐木斧的嘈杂声中不知疲倦地挥舞着针线。尽管东谷位置偏远，且时刻面临潜行的狼群和鱼人的威胁，她依然为旅行者提供热情款待和至关重要的工艺品。她将亚麻布碎屑和回收的头巾制作成耐用装备的天赋让她获得了官方认可，并接到了直接为暴风城军队供应防护性布甲和皮甲装备的订单。"}},faq={{q="萨拉·迪博雷恩是谁？",a="萨拉·迪博雷恩是一位居住在艾尔文森林东谷伐木场的出色裁缝。她以利用回收布料制作实用装备而闻名，并承接了供应暴风城军队的合同。",al={"萨拉·迪博雷恩是谁","萨拉·迪博雷恩","东谷裁缝"}},{q="我在哪里可以找到萨拉·迪博雷恩？",a="她就坐在东谷伐木场西侧的一间屋外，这里位于艾尔文森林的最东端，毗邻通往赤脊山的道路。",al={"萨拉·迪博雷恩位置","萨拉·迪博雷恩在哪里","迪博雷恩的房子"}},{q="萨拉为什么要为军队收集布料？",a="暴风城军队依靠当地的工匠来维持装备储备。萨拉使用回收的布料（例如冒险者收集的亚麻布）为王国的士兵制作结实的服装和护甲衬里。",al={"萨拉为什么需要亚麻布","暴风城军队护甲","布甲和皮甲任务"}}},fx={["693a4fc8"]={q="萨拉·迪博雷恩支持哪一方？",a="萨拉忠于暴风王国和联盟。她驻扎在东谷伐木场，直接为王国的防务出力，承接暴风城军队的裁缝订单，为士兵制作结实的护甲。",al={"萨拉·迪博雷恩阵营","萨拉·迪博雷恩效忠谁","萨拉·迪博雷恩联盟"}},["94680b13"]={q="萨拉·迪博雷恩想要什么？",a="萨拉需要原始制作材料，尤其是从当地土匪手中夺回的亚麻布卷，以便继续从事裁缝工作。她把回收来的布料制成衣物和护甲，为王国的军队提供装备，同时也会酬谢给她带来材料的旅人。",al={"萨拉·迪博雷恩需要什么","萨拉·迪博雷恩材料","萨拉为什么要亚麻布"}},["414da08e"]={q="萨拉·迪博雷恩为什么在伐木场？",a="萨拉住在东谷伐木场西侧，在那里做生意，远离暴风城拥挤的街道。这个边境据点环境清静，适合她穿针引线；同时，她也能接触到聚集在此、为她收集回收材料的旅人和当地供应商。",al={"萨拉为什么在东谷","萨拉·迪博雷恩东谷伐木场","萨拉·迪博雷恩为什么在这里"}},["59756f86"]={q="萨拉·迪博雷恩与谁有关联？",a="萨拉与暴风城军队关系密切，军队正式委托她为士兵制作布甲和皮甲。她也与驻扎在东谷伐木场的当地伐木工和樵夫并肩工作。",al={"萨拉·迪博雷恩的关系","萨拉·迪博雷恩为谁工作","萨拉·迪博雷恩暴风城军队"}},["42dfe0df"]={q="萨拉·迪博雷恩为什么出名？",a="萨拉以精湛的裁缝技艺闻名于当地，尤其擅长把粗糙的回收布料碎片制成精致的衣物和可靠的护甲，足以供王国的正规军使用。",al={"萨拉·迪博雷恩名声","萨拉·迪博雷恩有名吗","萨拉·迪博雷恩以什么出名"}}},fp="15,251,26.559.0,23.216.0,33.171.0,41.222.0"}
P.entries["npc:scarlet-commander-mograine"] = {n="血色十字军指挥官莫格莱尼",s="血色十字军指挥官莫格莱尼是驻扎在血色修道院大教堂的军事领袖。作为一名狂热的血色十字军圣骑士，他与大检察官怀特迈恩并肩守卫着大教堂。部落和联盟都将他作为目标，旨在挫败那些威胁提瑞斯法林地及周边地区的狂热分子。",h="血色十字军指挥官莫格莱尼是驻扎在血色修道院大教堂的军事领袖。作为一名狂热的血色十字军圣骑士，他与大检察官怀特迈恩并肩守卫着大教堂。部落和联盟都将他作为目标，旨在挫败那些威胁提瑞斯法林地及周边地区的狂热分子。",kw={"大教堂","十字军大厅","莫格莱尼","圣骑士","血色十字军指挥官莫格莱尼","血色十字军","血色修道院","怀特迈恩"},ang={["class:Paladin"]="莫格莱尼体现了圣骑士使命的悲剧性腐化，将保护与正义的神圣誓言扭曲成了冷酷、顽固的狂热。",["faction:Alliance"]="虽然血色十字军曾经与联盟有共同立场，但南海镇和暴风城的领袖们已经意识到，像莫格莱尼这样的狂热指挥官已经陷入了暴力的疯狂。",["race:Undead"]="对于被遗忘者来说，指挥官莫格莱尼代表了血色十字军最锋利的刀刃，他的存在直接毗邻幽暗城，威胁着他们在提瑞斯法林地的生存。"},sec={{t="大教堂的守护者",b="血色十字军指挥官莫格莱尼驻扎在血色修道院中心宏伟的十字军大厅内，指挥着血色十字军的常备驻军。他以狂热的奉献精神挥舞着圣骑士的神圣力量，依靠惩戒、圣盾术和制裁之锤，击碎任何被十字军视为腐化或不洁的目标。"},{t="神奇的羁绊",b="莫格莱尼对大教堂的防守与大检察官怀特迈恩有着内在的紧密联系。如果进攻部队将指挥官击倒，怀特迈恩便会从后方的密室现身来扭转局势。她呼唤圣光，瞬间使入侵者瘫痪并让莫格莱尼死而复生，迫使他们的敌人同时面对两位指挥官，进行一场绝望的共同战斗。"}},faq={{q="在哪里可以找到血色十字军指挥官莫格莱尼？",a="他位于提瑞斯法林地东北部的血色修道院大教堂区。你可以在十字军大厅的祭坛前找到他。",al={"莫格莱尼位置","莫格莱尼在哪里","血色修道院莫格莱尼房间"}},{q="莫格莱尼在血色十字军中扮演什么角色？",a="他担任驻扎在修道院的血色十字军部队的军事指挥官，与大检察官怀特迈恩一同领导旗下的圣骑士和士兵。",al={"指挥官莫格莱尼是谁","莫格莱尼军衔","莫格莱尼做什么"}},{q="他如何战斗？",a="莫格莱尼是一名强力的近战圣骑士。他使用制裁之锤击晕对手，发动十字军打击，利用惩戒光环保护自己，并在濒临绝境时依靠圣盾术。",al={"莫格莱尼技能","莫格莱尼战斗","如何对战莫格莱尼"}},{q="为什么大检察官怀特迈恩要复活他？",a="怀特迈恩和莫格莱尼有着深厚的羁绊，作为修道院的领袖并肩作战。当莫格莱尼在战斗中倒下时，怀特迈恩会介入，用魔法使攻击者沉睡，并将莫格莱尼以全盛状态复活。",al={"怀特迈恩复活莫格莱尼","莫格莱尼会复活吗","复活莫格莱尼"}},{q="为什么联盟和部落要与他战斗？",a="血色十字军将所有外来者——无论活人还是亡灵——都视为腐化的携带者。联盟和被遗忘者都会派遣勇士突袭大教堂并处决其领袖，以消除十字军在洛丹伦的狂热势力。",al={"为什么要杀莫格莱尼","血色指挥官任务","以圣光之名"}},{q="莫格莱尼在战斗中会自我治疗吗？",a="是的，在紧要关头会。除了圣盾术和近战攻击外，他还能使用圣疗术将生命值恢复至满，而大检察官怀特迈恩一旦加入战斗，也会提供额外的治疗。",al={"莫格莱尼会治疗吗","莫格莱尼治疗"}}},fx={a3e1ab86={q="血色十字军指挥官莫格莱尼支持哪一方？",a="莫格莱尼指挥官只为血色十字军而战。血色十字军最初由洛丹伦的幸存守军和白银之手骑士团成员组成，如今却已彻底孤立。在莫格莱尼的军事指挥下，他们视所有外人——无论部落还是联盟——为染疫的污秽之物和圣光的敌人。",al={"莫格莱尼为谁而战","血色十字军指挥官莫格莱尼阵营","莫格莱尼是联盟吗"}},["741d495f"]={q="血色十字军指挥官莫格莱尼为什么在修道院？",a="血色修道院是血色十字军在提瑞斯法林地的重要据点之一。莫格莱尼驻守在大教堂内的十字军礼拜堂，与大检察官怀特迈恩一同指挥驻军防务，守卫他们神圣堡垒的核心。",al={"莫格莱尼为什么在血色修道院","莫格莱尼在此的原因","莫格莱尼在这里做什么"}}},fp="26,332,22.349.0,17.393.1,46.170.0,47.169.0,18.212.0,46.244.0,44.249.0,48.203.0"}
P.entries["npc:scooty"] = {n="斯库提",s="斯库提是一名在繁忙的海盗港口藏宝海湾工作的地精工程师。他自称工程学大师，负责维护一套与坠落之城诺莫瑞根内的实验性传送器直接相连的精密地精传送器系统。他的装置为部落特工提供了一条直达丹莫罗腹地的捷径，尽管这条路充满了危险。",h="斯库提是一名在繁忙的海盗港口藏宝海湾工作的地精工程师。他自称工程学大师，负责维护一套与坠落之城诺莫瑞根内的实验性传送器直接相连的精密地精传送器系统。他的装置为部落特工提供了一条直达丹莫罗腹地的捷径，尽管这条路充满了危险。",kw={"藏宝海湾","诺莫瑞根","地精","斯库提","荆棘谷","传送器","地精传送器"},ang={["faction:Horde"]="斯库提为部落提供了一条通往诺莫瑞根不可或缺的捷径，让你的突击小队能够绕过丹莫罗固若金汤的联盟防御。",["profession:Engineering"]="其他修补匠一定会欣赏斯库提对地精传送器物理学的大胆应用，尽管地精对基本安全协议的典型漠视让每一次启动都像是一场赌博。"},sec={{t="藏宝海湾的传送专家",b="斯库提在藏宝海湾的码头和工坊之间忙碌，是热砂港中最具野心的修补匠之一。虽然普通的地精沉迷于火药和炸药，但斯库提却将注意力转向了瞬时分子传输。通过校准复杂的地精传送器系统，他成功建立了一条通往位于诺莫瑞根内部的传送台的直接作业链路。想要突入这座地下侏儒堡垒的部落部队，在很大程度上依赖斯库提的修补技术，从而完全避开危险的联盟领土。"},{t="侏儒装置与地精风险",b="维护实验性的地精传送器绝非无聊之事。在得知诺莫瑞根有新的侏儒钻机后，斯库提和他的搭档Sovik制造了“传送多重器6000型”。据斯库提自己乐呵呵地承认，它不过才爆炸过十几次而已。尽管跨大陆分子解体有着明显的身体风险，但斯库提对自己的天才依然充满自信，将每一次灾难性的机械故障都仅仅视为通往真正创新道路上的一个小障碍。"}},faq={{q="斯库提是谁？",a="斯库提是一名常驻藏宝海湾的地精工程师，自称工程学大师。他维护并校准着地精传送器网络，将藏宝海湾直接与诺莫瑞根深处的一个实验性传送台连接起来。",al={"斯库提是谁","斯库提背景故事","斯库提npc","藏宝海湾的斯库提"}},{q="为什么斯库提会有通往诺莫瑞根的传送器？",a="斯库提与诺莫瑞根内的一个实验性传送台建立了连接，以便直接进入这座侏儒城市。对于部落来说，他的装置提供了一条通往丹莫罗的重要后门，无需穿越防御森严的联盟领土进行战斗。",al={"为什么有诺莫瑞根传送器","斯库提的传送器是如何运作的","斯库提传送至诺莫瑞根"}},{q="斯库提在哪里？",a="斯库提在藏宝海湾工作，这是一座位于荆棘谷南端的中立地精港口城市。",al={"斯库提在哪里","斯库提位置","寻找斯库提"}},{q="使用斯库提的传送器安全吗？",a="地精工程学以不可预测的故障而闻名，斯库提的传送器也不例外。虽然它能成功将冒险者传送到诺莫瑞根，但在信任他那不稳定的技术时，机械故障和地精传送器校准错误始终是一种隐患。",al={"斯库提安全吗","传送器安全吗","传送器风险"}}},fx={["6ce6cf89"]={q="斯库提支持哪一方？",a="斯库提在藏宝海湾活动，是中立地精企业的一员。他为任何愿意做生意的旅人提供工程服务和实验性传送装置，不论对方属于哪个阵营。",al={"斯库提阵营","斯库提是部落还是联盟","斯库提效忠哪一方"}},["04182db4"]={q="斯库提为什么在藏宝海湾？",a="在藏宝海湾活动，让斯库提得以接触独立的贸易网络和好奇的冒险者，远离大陆当局的干涉。在这里，他可以随心所欲地管理自己的信号收发器网络，并摆弄远距离地精传送技术。",al={"斯库提为什么在这里","斯库提为什么在藏宝海湾","是什么让斯库提来到这里"}}},fp="6,370,32.546.0,31.517.0,14.237.0,48.270.0,24.121.0,34.271.0"}
P.entries["npc:scout-riell"] = {n="哨兵瑞尔",s="哨兵瑞尔是一位驻扎在西部荒野哨兵岭瞭望塔顶端的警惕守望者。她效力于当地的人民民兵团，监视着周围平原上的迪菲亚兄弟会活动，并招募冒险者去追捕那些蒙面的亡命之徒。",h="哨兵瑞尔是一位驻扎在西部荒野哨兵岭瞭望塔顶端的警惕守望者。她效力于当地的人民民兵团，监视着周围平原上的迪菲亚兄弟会活动，并招募冒险者去追捕那些蒙面的亡命之徒。",kw={"迪菲亚潜行者","人民民兵团","红色丝绸面罩","瑞尔","哨兵瑞尔","哨兵岭","塔楼","西部荒野"},ang={["faction:Alliance"]="对于联盟的勇士来说，哨兵瑞尔代表了西部荒野严酷的现实：一群被抛弃的民众被迫雇佣佣兵来对抗日益增长的迪菲亚兄弟会威胁。",["profession:Tailoring"]="裁缝们会注意到，迪菲亚标志性的红色面罩是由真丝制成的，对于普通的乡村强盗来说，这是一种极其昂贵的布料。"},sec={{t="西部荒野之眼",b="哨兵瑞尔高踞于哨兵岭之上，注视着这片深受强盗和收割机困扰的土地。由于暴风城的皇家军队缺席，且皇室拒绝提供援助，当地的防务完全落在了人民民兵团的肩上。瑞尔从石塔顶端的瞭望点追踪着迪菲亚兄弟会的猖獗行径，并收集他们犯罪的证据，她号召路过的旅者夺下强盗们标志性的红色丝绸面罩。"}},faq={{q="我在哪里可以找到哨兵瑞尔？",a="哨兵瑞尔位于西部荒野的哨兵岭。沿着楼梯一路向上，来到石制瞭望塔露天的塔顶，她就在那里监视着下方的平原。",al={"瑞尔位置","哨兵瑞尔在哪里","找到瑞尔"}},{q="哨兵瑞尔要求冒险者做什么？",a="瑞尔委托冒险者从游荡在西部荒野并藏匿于死亡矿井中的迪菲亚扒手、强盗和走私贩身上收集红色丝绸面罩，以证明当地的法外之徒已被铲除。",al={"瑞尔的任务","瑞尔给什么任务","红色丝绸面罩任务"}},{q="为什么瑞尔要收集红色丝绸面罩？",a="红色丝绸面罩是迪菲亚兄弟会的统一标志。收集它们可以作为确凿的证据，证明恐吓西部荒野农庄的强盗正在减少，同时也剥夺了这些亡命之徒的统一象征。",al={"为什么要面罩","为什么要红色丝绸面罩","迪菲亚面罩"}},{q="哨兵瑞尔为谁效力？",a="瑞尔效力于人民民兵团，这是一支由格里安·斯托曼组建的志愿防御部队。当暴风城的贵族议会对该地区的困境视而不见时，这支部队挺身而出保护西部荒野。",al={"瑞尔的阵营","瑞尔是暴风城军队吗","瑞尔为谁效力"}}},fx={c25141c7={q="哨兵瑞尔是谁？",a="哨兵瑞尔是一名人类斥候，效力于哨兵岭，负责保卫西部荒野。她驻守在俯瞰当地的高塔上，监视周围的乡野，留意迪菲亚潜行者的动向，并与当地守军协同，击退威胁农田的歹徒。",al={"瑞尔是谁","哨兵瑞尔的背景","哨兵瑞尔是谁"}},["2f6a5f48"]={q="哨兵瑞尔为什么驻扎在这里？",a="瑞尔驻守在哨兵岭高塔顶端，负责瞭望西部荒野。从这个高处，她可以巡视平原上的匪徒活动，追踪迪菲亚潜行者的扩张，并招募路过的冒险者直接向祸害这片行省的盗匪发起进攻。",al={"哨兵瑞尔为什么在这里","瑞尔为什么在西部荒野","瑞尔驻扎此处的目的"}},f57d6b81={q="哨兵瑞尔与谁有关联？",a="瑞尔与格里安·斯托曼以及驻扎在哨兵岭的人民军并肩作战。她和其他斥候、哨兵共同组成了西部荒野艰难支撑的地方防卫力量；在王国军队缺席时，他们依靠民兵志愿者和勇敢的冒险者守护王国边境。",al={"哨兵瑞尔认识谁","瑞尔的阵营关系","瑞尔的盟友"}}},fp="11,241,18.454.0,29.166.0,44.213.1,41.227.0,30.193.0"}
P.entries["npc:scout-thaelrid"] = {n="银月守卫塞尔瑞德",s="银月守卫塞尔瑞德是一名受伤的暗夜精灵斥候，受银色黎明派遣进入了黑暗深渊的淹没遗迹。他被困在Pool of Ask'ar附近，目睹了娜迦和暮光之锤教派之间正在形成的黑暗联盟。",h="银月守卫塞尔瑞德是一名受伤的暗夜精灵斥候，受银色黎明派遣进入了黑暗深渊的淹没遗迹。他被困在Pool of Ask'ar附近，目睹了娜迦和暮光之锤教派之间正在形成的黑暗联盟。",kw={"阿库麦尔","银色黎明","灰谷","黑暗深渊","pool of ask'ar","斥候塞尔瑞德","塞尔瑞德","梦游者克尔里斯"},ang={["faction:Alliance"]="被派往灰谷的联盟斥候追踪着塞尔瑞德的失踪，他们渴望维护佐拉姆海岸的安全，并支持银色黎明的中立工作。",["faction:Horde"]="虽然塞尔瑞德是暗夜精灵，但他效忠于银色黎明，这意味着任何愿意打击暮光之锤并净化洞穴的冒险者都可以帮助他。",["race:NightElf"]="对于暗夜精灵来说，看到像黑暗深渊这样神圣的古代神庙领地被娜迦和末日邪教亵渎是一种痛苦的暴行；塞尔瑞德代表了他们的人民对卡利姆多最深处伤口的守护。"},sec={{t="银色黎明之眼",b="当佐拉姆海岸传出有关深海之下邪恶仪式的离奇报告时，银色黎明对此产生了兴趣。该组织致力于监视艾泽拉斯各地日益增长的邪恶与非自然腐化，于是派遣斥候塞尔瑞德潜入黑暗深渊。他的任务很简单：评估威胁程度，观察这座被淹没的神庙内的动向，并汇报情况，以便黎明决定最迫切需要援助的地方。"},{t="蔓延的黑暗",b="塞尔瑞德很快发现，传闻与恐怖的现实相比简直微不足道。这些地下遗迹里隐藏着野蛮的娜迦和暮光之锤末日狂信徒之间的邪恶契约。在神庙大厅深处，梦游者克尔里斯指挥的教徒们进行血祭以喂养九头蛇阿库麦尔，并与远古恐惧交易以换取黑暗力量。在塞尔瑞德将此警告传达给地面之前，他就受了重伤并被切断了退路，只能困在Pool of Ask'ar附近。"}},faq={{q="银月守卫塞尔瑞德是谁？",a="他是效力于银色黎明的一名暗夜精灵特工。他的任务是潜入灰谷海岸的黑暗深渊，搜集下方聚集的邪恶势力的情报。",al={"塞尔瑞德是谁","塞尔瑞德背景故事","塞尔瑞德背景"}},{q="为什么塞尔瑞德会被困在黑暗深渊里？",a="在侦察这座巨大的神庙时，塞尔瑞德被其中的居民发现并身受重伤。由于无法独自杀出重围返回地面，他在Pool of Ask'ar附近寻求庇护。",al={"他为什么被困住","他是如何受伤的","塞尔瑞德为何濒死"}},{q="塞尔瑞德在深处发现了什么？",a="塞尔瑞德调查了暮光之锤在黑暗深渊的活动，该教派的存在威胁着这座古老的神庙以及进入其中的人们。",al={"塞尔瑞德发现了什么","邪教徒在做什么","黑暗深渊秘密"}},{q="塞尔瑞德为谁工作？",a="他隶属于银色黎明，这是一个致力于对抗整个艾泽拉斯腐化、邪恶和末日威胁的中立组织，不分阵营。",al={"塞尔瑞德阵营","塞尔瑞德是银色黎明的人吗","塞尔瑞德是联盟吗"}},{q="塞尔瑞德请求冒险者做什么？",a="无法离开避难所的塞尔瑞德请求勇敢的冒险者们杀死梦游者克尔里斯以终结这场屠杀，并带回这位邪教领袖的头颅，以此证明威胁已被消除。",al={"塞尔瑞德任务","黑暗深渊罪行任务","他想要什么"}},{q="在哪里可以找到塞尔瑞德？",a="他受伤躺在Pool of Ask'ar附近的一个僻静壁龛里，那是刚穿过黑暗深渊被水淹没的初步洞穴后的一片区域。",al={"塞尔瑞德在哪里","塞尔瑞德位置","pool of ask'ar斥候"}}},fx={["879268fe"]={q="银月守卫塞尔瑞德与谁有关联？",a="银月守卫塞尔瑞德直接听命于银色黎明。为了监视艾泽拉斯各地日益逼近的邪恶势力，这个组织派他潜入黑暗深渊的水下神殿，核实有关暮光之锤教派及其新近结盟的娜迦的惊人传闻。",al={"塞尔瑞德的关系","塞尔瑞德听命于谁","斥候塞尔瑞德银色黎明"}}},fp="21,253,23.463.0,19.517.1,29.189.0,49.205.0,41.153.0,27.168.0,41.192.0,28.134.0"}
P.entries["npc:searn-firewarder"] = {n="希尔恩·火结",s="希尔恩·火结是一位暗矛巨魔萨满祭司训练师，驻扎在奥格瑞玛的Grommash Hold内。他协助部落中成长中的萨满祭司，指引他们完成与火、水和风的元素之灵沟通所需的试炼。",h="希尔恩·火结是一位暗矛巨魔萨满祭司训练师，驻扎在奥格瑞玛的Grommash Hold内。他协助部落中成长中的萨满祭司，指引他们完成与火、水和风的元素之灵沟通所需的试炼。",kw={"call of air","call of fire","call of water","暗矛","grommash hold","奥格瑞玛","希尔恩·火结","萨满祭司训练师"},ang={["class:Shaman"]="希尔恩是成长中部落萨满祭司的重要检查点，指引他们找到将元素绑定到图腾所需的导师和试炼。",["race:Troll"]="作为一名站在Grommash Hold内的暗矛萨满祭司，希尔恩展示了巨魔精神领袖如何与他们的兽人和牛头人盟友一起调整他们古老的纽带。"},sec={{t="元素指南",b="希尔恩·火结站在Grommash Hold的防御墙内，与部落的高层指挥官并肩，担任有志成为萨满祭司者的元素向导。虽然许多暗矛巨魔通过巫医和巫毒仪式与灵魂沟通，但希尔恩代表了巨魔萨满祭司与卡利姆多活生生的元素之间建立的纽带。他充当中间人，指引入门者前往遥远的导师处，并完成获得Call of Fire、Call of Water和Call of Air所需的仪式。"}},faq={{q="希尔恩·火结是谁？",a="希尔恩·火结是一位丛林巨魔萨满祭司训练师，常驻于奥格瑞玛的Grommash Hold内。他指引部落中成长中的萨满祭司完成他们的精神旅程。",al={"希尔恩·火结背景故事","希尔恩是谁","希尔恩 奥格瑞玛"}},{q="希尔恩·火结提供什么任务？",a="希尔恩帮助引导萨满祭司完成他们的元素觉醒任务，包括Call of Fire、Call of Water和Call of Air，并指引他们前往各大陆上遥远的神龛和精神导师处。",al={"希尔恩任务","希尔恩·火结任务线"}},{q="为什么一位巨魔萨满祭司会驻扎在Grommash Hold内？",a="Grommash Hold是奥格瑞玛领导层的核心，接待着部落大酋长萨尔以及各盟友种族的杰出代表。希尔恩的存在反映了兽人与暗矛部族之间的紧密团结，以及萨满教义在新部落中发挥的核心作用。",al={"为什么希尔恩在grommash hold","希尔恩 grommash hold"}}},fx={["9fd5962f"]={q="希尔恩·火结支持哪一方？",a="希尔恩·火结忠于部落，并以暗矛巨魔的一员为荣。他驻扎在Grommash Hold内，靠近酋长萨尔，侍奉新部落的萨满传统，指引踏上元素之路、为族人效力的初阶萨满。",al={"希尔恩·火结阵营","希尔恩效忠谁","希尔恩·火结的归属"}},["7c90517e"]={q="希尔恩·火结想要什么？",a="希尔恩·火结希望考验并指导部落中的新晋萨满。他带领修行者经历元素试炼，例如烈焰召唤、流水召唤和空气召唤，确保那些与灵魂沟通的人证明自己的力量、奉献和均衡，然后才能驾驭更强大的力量。",al={"希尔恩想要什么","希尔恩·火结的目的","为什么要找希尔恩·火结交谈"}}},fp="16,248,23.498.0,24.173.0,40.206.0,53.283.0"}
P.entries["npc:seer-graytongue"] = {n="灰舌先知",s="灰舌先知是一位德高望重的牛头人长者和精神导师，居住在莫高雷的红云台地。他驻扎在纳拉其营地附近，负责考验那些进行早期部落试炼的年轻勇士。通过力量试炼等仪式，他确保年轻人在踏入广阔世界之前能够尊崇大地母亲。",h="灰舌先知是一位德高望重的牛头人长者和精神导师，居住在莫高雷的红云台地。他驻扎在纳拉其营地附近，负责考验那些进行早期部落试炼的年轻勇士。通过力量试炼等仪式，他确保年轻人在踏入广阔世界之前能够尊崇大地母亲。",kw={"纳拉其营地","灰舌先知","莫高雷","红云台地","力量试炼","大地母亲的试炼"},ang={["class:Shaman"]="精神修习者仰望像灰舌先知这样的长者，学习神圣的仪式和试炼如何将战士的肉体力量与先祖的指引联系起来。",["race:Tauren"]="对于牛头人年轻人来说，拜访灰舌先知标志着一种神圣的成人礼，将个人的力量与大地母亲永恒的祝福连接在一起。"},sec={{t="台地上的向导",b="灰舌先知居住在红云台地的顶端，担任着牛头人勇士和施法者学徒的启蒙导师。当年轻的冒险者从纳拉其营地出发时，灰舌先知会监督他们神圣旅程的关键步骤，包括大地母亲的试炼。通过在严酷的平原和危险的莫高雷野兽面前考验他们的决心，他向年轻人灌输了每一位真正的牛头人步入成年时所必须具备的荣誉、耐心和敬畏之心。"}},faq={{q="灰舌先知是谁？",a="灰舌先知是一位住在莫高雷红云台地上一座小屋里的牛头人长者。他指导年轻的英雄完成传统的仪式职责，以证明他们对部落的价值。",al={"灰舌先知","灰舌先知的作用","红云台地上的先知是谁"}},{q="灰舌先知监督哪些试炼？",a="他负责引导年轻人完成大地母亲的试炼中的部分内容，包括力量试炼。这些仪式考验着勇士的毅力以及对平原自然平衡的尊重。",al={"灰舌先知的任务","灰舌先知需要什么","灰舌先知大地母亲的试炼"}},{q="我在哪里可以找到灰舌先知？",a="他住在红云台地边缘的一座简朴的皮质小屋里，就在莫高雷纳拉其营地的中心活动区外。",al={"灰舌先知的位置","灰舌先知在哪里","灰舌先知的小屋"}}},fx={ef1aa2b1={q="灰舌先知支持哪一方？",al={"灰舌先知阵营","灰舌先知是部落吗","灰舌先知的忠诚对象"}},["9354d517"]={q="灰舌先知想要什么？",a="灰舌先知希望引导初出茅庐的牛头人踏上大地母亲的神圣之路。他带领年轻的勇士经历精神与体魄的仪式，确保他们证明自己的决心、尊重灵魂，并成为配得上守护部族的人。",al={"灰舌想要什么","灰舌的目标","灰舌先知的目的"}},ec4e7fed={q="灰舌先知为什么在这里？",a="灰舌先知住在红云台地，为即将成年的年轻人提供重要指引。纳拉其营地是年轻牛头人迈向广阔世界的起点，灰舌先知驻守于此，负责监督他们的传统成人仪式。",al={"灰舌先知为什么在红云台地","灰舌先知在此的原因","灰舌为什么在这里"}}},fp="15,327,19.468.0,23.188.0,41.206.0,33.145.0"}
P.entries["npc:seer-ravenfeather"] = {n="鸦羽先知",s="鸦羽先知是一位驻扎在红云台地纳拉其营地的牛头人萨满祭司导师。她引导羽翼未丰的灵媒通过早期的试炼，帮助他们与灵魂的声音以及莫高雷的大地建立共鸣。",h="鸦羽先知是一位驻扎在红云台地纳拉其营地的牛头人萨满祭司导师。她引导羽翼未丰的灵媒通过早期的试炼，帮助他们与灵魂的声音以及莫高雷的大地建立共鸣。",kw={"call of earth","纳拉其营地","大地圣水","莫高雷","鸦羽先知","红云台地","萨满"},ang={["class:Shaman"]="对于年轻的牛头人萨满来说，鸦羽先知是他们学习与元素沟通、掌握大地力量这一漫长旅程中的第一位向导。",["race:Tauren"]="作为纳拉其营地的先知，她代表了深深扎根于牛头人社会的精神传统，在他们安居于祖先家园之际，为他们指引方向。"},sec={{t="台地向导",b="鸦羽先知站在纳拉其营地安静的住所中，为那些被召唤走上萨满之道的年轻牛头人担任耐心的老师。红云台地是一片神圣的试炼场，鸦羽先知会确保新手们在踏入莫高雷更广阔的天地之前，理解他们肩负的职责。她指导他们掌握与元素力量沟通并尊崇大地母亲所需的基本仪式。"},{t="元素之唤",b="鸦羽先知的主要职责是监督萨满新手的最初修行，指导他们完成名为“Call of Earth”的传统仪式。通过她的指引，新兵们准备仪式用的圣水，并寻求与栖息在台地石层中的大地之灵沟通，从而建立起稳固他们元素魔法的纽带。"}},faq={{q="谁是鸦羽先知？",a="鸦羽先知是一位住在红云台地纳拉其营地的精神导师。她负责训练刚刚踏入这个世界的年轻牛头人萨满。",al={"鸦羽先知背景故事","谁是鸦羽先知","纳拉其营地先知"}},{q="她在萨满训练中扮演什么角色？",a="她引导萨满新手完成最早期的仪式，其中最著名的是为了与大地之灵沟通并回应Call of Earth的任务线。",al={"鸦羽先知萨满任务","call of earth训练师","鸦羽先知教授什么"}},{q="我在哪里可以找到鸦羽先知？",a="你可以在纳拉其营地的帐篷和居所中找到她，营地位于莫高雷西南部的隐蔽红云台地上。",al={"鸦羽先知位置","鸦羽先知在哪里","纳拉其营地位置"}}},fx={["56dac3cc"]={q="鸦羽先知支持哪一方？",a="鸦羽先知忠于牛头人部族和部落。她驻扎在纳拉其营地，通过指引那些立志踏上萨满之道、与大地之灵沟通的年轻牛头人来侍奉族人。",al={"鸦羽先知阵营","鸦羽先知是部落吗","鸦羽先知效忠哪一方"}},d16cefae={q="鸦羽先知想做什么？",a="她的目标是在纳拉其营地教导并培养初学的灵性求道者。她引导年轻的信徒完成神圣仪式，尤其是与大地之灵沟通，帮助他们获得图腾，并维系部族与土地之间的和谐。",al={"鸦羽先知的目标","鸦羽先知想做什么","鸦羽先知的职责"}},f326607e={q="鸦羽先知为什么在纳拉其营地？",a="纳拉其营地是红云台地的年轻牛头人踏上旅途的聚集地。鸦羽先知留在这里照看新兴的灵能者，确保每位信徒从迈出第一步起，就能学习古老的传统、仪式，以及对元素的虔诚联结。",al={"鸦羽先知为何在纳拉其营地","鸦羽先知与红云台地","鸦羽先知为何在这里"}}},fp="17,232,19.436.0,24.353.0,25.158.0,43.156.0,35.124.0"}
P.entries["npc:seereth-stonebreak"] = {n="希雷斯·碎石",s="希雷斯·碎石是一位兽人萨满，她通过监测扰乱这片土地的动荡来为部落服务。她驻扎在石爪山脉与贫瘠之地交界处的巨木谷附近，指引旅行者去解决卡利姆多的环境破坏、失控的机器以及日益加剧的紧张局势。",h="希雷斯·碎石是一位兽人萨满，她通过监测扰乱这片土地的动荡来为部落服务。她驻扎在石爪山脉与贫瘠之地交界处的巨木谷附近，指引旅行者去解决卡利姆多的环境破坏、失控的机器以及日益加剧的紧张局势。",kw={"巫婆","地精","希雷斯","萨满","伐木机","灵魂","碎石","石爪山脉"},ang={["class:Shaman"]="希雷斯对石爪山脉中紊乱的元素和受损自然的关注，反映了任何一位萨满治愈环境创伤和安抚不安灵魂的职责。",["faction:Horde"]="她的命令旨在保护重要的陆路交通要道和资源，以抵御步步紧逼的联盟军队和鲁莽的地精行动。",["race:Orc"]="希雷斯代表了现代兽人回归萨满教义和对自然世界的崇敬，她站在了盲目破坏的对立面。"},sec={{t="一位警觉的萨满",b="希雷斯·碎石是一位致力于元素和谐与保卫部落领土的兽人。在土地的灵魂对地精的掠夺发出哀嚎后，她被派往石爪山脉，并在巨木谷附近扎营，时刻警惕着这片土地。她没有陷入绝望，而是运用自己的灵魂洞察力和对荒野前线的了解，引导冒险者去对抗迫在眉睫的危险。"},{t="石爪山脉的动荡",b="希雷斯对困扰着石爪山脉的动荡感到深切忧虑。由于冷酷的荆棘谷地精的破坏性存在，以及机械伐木机在古老林地中肆意开采，这座山脉的灵魂平衡已被严重破坏。她派遣部落使者去对抗这些鲁莽的入侵者，并向年长的博学者咨询如何治愈这片土地的创伤。"}},faq={{q="希雷斯·碎石是谁？",a="希雷斯·碎石是一位服务于部落的兽人萨满。她为前往石爪山脉的旅行者提供指引和任务，以应对对这片土地和部落领地造成的威胁。",al={"希雷斯","希雷斯是谁","希雷斯·碎石的背景故事"}},{q="希雷斯为什么会关注石爪山脉？",a="石爪山脉正遭受着肆意的森林砍伐、地精伐木机械的强力开采和不断升级的冲突。作为一名萨满，希雷斯感知到了当地灵魂的不安，并致力于阻止这种破坏。",al={"为什么是石爪山脉","希雷斯面临的问题","石爪山脉的动荡"}},{q="她原本的哨位发生了什么？",a="什么都没有发生。希雷斯是被部落派往石爪山脉的，目前仍驻扎在石爪山脉与贫瘠之地交界处的巨木谷附近，可以沿着十字路口以西的道路到达那里。",al={"希雷斯的过去","希雷斯的荣誉立场","希雷斯为何搬迁"}},{q="希雷斯为冒险者提供了哪些任务？",a="她派遣部落冒险者进入石爪山脉，去对付侵入的荆棘谷地精，拆除破坏性的伐木机，与困扰的灵魂沟通，并向玛加萨·野性图腾这样受人尊敬的长者寻求建议。",al={"希雷斯的任务","希雷斯想要什么","希雷斯·碎石的任务"}},{q="她提到的年长巫婆是谁？",a="这位年长巫婆指的是玛加萨·野性图腾，一位居住在雷霆崖长者高地的强大且有影响力的牛头人长者，希雷斯会就深层的灵魂动荡向她寻求指引。",al={"年长巫婆","年长巫婆是谁","巫婆任务"}},{q="为什么她关心地精的行动？",a="肆无忌惮的地精伐木行动依靠机械伐木机来撕裂神圣的森林，污染水道，并激怒希雷斯发誓要安抚的自然之灵。",al={"希雷斯与地精","地精入侵者","为什么仇视地精"}}},fx={b2feb188={q="希雷斯·碎石属于哪一方？",a="希雷斯·碎石坚定地效忠部落。作为一名兽人萨满，她忠于自己的族人及其盟友，并寻求部落勇士帮助守护土地、击退敌人。",al={"希雷斯·碎石的阵营","希雷斯效忠谁","希雷斯是部落成员吗"}},["8beca421"]={q="希雷斯·碎石想做什么？",a="希雷斯希望守护这片土地，并平息威胁该地区的动乱。她驻扎在石爪山脉边境，希望有能干的冒险者听从灵魂的指引，抵御危害部落利益的破坏势力。",al={"希雷斯·碎石的目标","希雷斯想做什么","希雷斯·碎石的动机"}},da23e0a9={q="希雷斯·碎石为何在此？",a="希雷斯受部落派遣，前来监视动荡不安的石爪山脉。她在巨木谷附近扎营，那里位于石爪山脉与贫瘠之地的边界。灵魂正因地精的掠夺而哀号，她则召集部落冒险者回应它们的呼唤。",al={"希雷斯为何在这里","希雷斯为何来到这里","希雷斯·碎石驻扎此地的原因"}},["7cf30712"]={q="希雷斯·碎石与谁有关联？",a="希雷斯是一名效忠部落的兽人萨满，与卡利姆多的灵性人物有所联系，并会为旅人指引一位名为长者克罗恩的睿智牛头人领袖。",al={"希雷斯·碎石的盟友","希雷斯与哪个阵营有关","希雷斯·碎石的关系"}}},fp="18,300,17.432.0,21.415.0,26.199.0,56.226.0,35.215.0,45.224.0,36.203.0,44.180.0"}
P.entries["npc:senani-thunderheart"] = {n="塞娜尼·雷心",s="塞娜尼·雷心是一位驻扎在灰谷碎木岗哨的牛头人女猎手，该岗哨位于贫瘠之地以北。她效力于部落，通过挑战过往的旅人去追捕游荡在古老森林中的凶猛野生掠食者，以此考验他们的实力。通过这些试炼，猎人们既证明了自己的技巧，也清理了潜伏在部落领地附近的致命野兽。",h="塞娜尼·雷心是一位驻扎在灰谷碎木岗哨的牛头人女猎手，该岗哨位于贫瘠之地以北。她效力于部落，通过挑战过往的旅人去追捕游荡在古老森林中的凶猛野生掠食者，以此考验他们的实力。通过这些试炼，猎人们既证明了自己的技巧，也清理了潜伏...",kw={"灰谷","灰谷狩猎","密斯特拉湖","塞娜尼","沙德拉","尖爪","雷心","乌萨诺斯"},ang={["class:Hunter"]="塞娜尼体现了经典的猎人精神，在追踪灰谷难以捉摸的野兽——乌萨诺斯、沙德拉和尖爪——的过程中考验你的追踪技巧。",["faction:Horde"]="碎木岗哨是部落在灰谷的立足点，塞娜尼在这里帮助部落的侦察兵证明他们的价值并保卫荒野。",["race:Tauren"]="对于牛头人旅行者来说，见到塞娜尼会让人想起大地母亲的试炼，即使远离莫高雷，也要铭记猎人与猎物之间古老的平衡。"},sec={{t="狩猎大师",b="塞娜尼·雷心驻扎在碎木岗哨，在灰谷阴影笼罩的树林中代表着牛头人的狩猎传统。她远离莫高雷广阔的平原，指引部落的冒险者在对抗森林中的顶级野兽时磨练自己的追踪和战斗本领。她将狩猎视为一种荣誉的挑战，也是在这一片未经驯化、充满争端的土地上生存的必要仪式。"},{t="灰谷之兽",b="塞娜尼负责监管灰谷的传统狩猎试炼，指引猎人前往追捕三头臭名昭著的掠食者：熊怪乌萨诺斯、猫科动物沙德拉以及角鹰兽尖爪。取回它们的信物——爪子、头颅和利爪——是证明猎人尊重这片土地并能够征服其中最凶猛野兽的成人礼。"}},faq={{q="塞娜尼·雷心是谁？",a="塞娜尼·雷心是一位牛头人女猎手，也是位于灰谷碎木岗哨的任务发布者。她效忠于部落，指引冒险者前去猎杀潜伏在森林中最危险的野生动物。",al={"塞娜尼是谁","塞娜尼·雷心背景故事","银风避难所任务发布者"}},{q="我在哪里可以找到塞娜尼·雷心？",a="塞娜尼驻扎在碎木岗哨，这是部落在灰谷的据点，位于贫瘠之地的正北方。",al={"塞娜尼位置","塞娜尼在哪里","银风避难所在哪里"}},{q="什么是灰谷狩猎？",a="灰谷狩猎是塞娜尼发布的一系列狩猎挑战。猎人们的任务是追踪并击杀三头传说中的森林掠食者：熊怪乌萨诺斯、夜刃豹沙德拉以及角鹰兽尖爪。",al={"灰谷狩猎","塞娜尼想要什么","灰谷狩猎任务"}},{q="塞娜尼需要狩猎的什么战利品？",a="她要求猎人带回乌萨诺斯的爪子、沙德拉的头颅和尖爪的利爪，以证明这三头强大的野兽都已被击败。",al={"狩猎战利品","灰谷狩猎物品","塞娜尼需要什么"}},{q="塞娜尼和该地区的熊怪有什么联系吗？",a="在她的任务中并没有。塞娜尼的任务是灰谷狩猎；邪枝部族和其他熊怪部族只是猎人在森林中面临的众多危险之一。",al={"邪枝任务","邪枝之王","塞娜尼熊怪"}},{q="塞娜尼隶属于塞纳里奥议会吗？",a="不，塞娜尼直接效忠于部落和牛头人部族，她是以传统猎人的视角，而非塞纳里奥德鲁伊守护者的视角来对待这片森林。",al={"塞娜尼是德鲁伊吗","塞娜尼塞纳里奥议会"}}},fx={cd4c9488={q="塞娜尼·雷心为什么在碎木岗哨？",a="塞娜尼·雷心在碎木岗哨扎营，负责监督灰谷的大规模狩猎。作为一名牛头人猎人，她会让部落勇士挑战深林中古老而难以寻觅的野兽，以检验他们的本领，例如乌萨苟斯、萨杜布拉和沙普塔隆。",al={"塞娜尼·雷心为何在灰谷","塞娜尼·雷心在银风避难所的目的","塞娜尼为何在这里"}},["13e7db62"]={q="塞娜尼·雷心想让你做什么？",a="塞娜尼要求部落的猎人证明自己在古老森林中的追踪与战斗本领。她让你追踪并猎杀灰谷最狡猾的掠食者——乌萨苟斯、萨杜布拉和沙普塔隆，并带回它们珍贵的战利品。",al={"塞娜尼想做什么","塞娜尼·雷心的任务","塞娜尼要什么"}}},fp="19,369,22.405.0,23.346.0,27.202.0,37.103.0,27.231.0,48.148.0,60.163.0,46.176.0"}
P.entries["npc:senator-mehr-stonehallow"] = {n="参议员梅尔·圣石",s="参议员梅尔·圣石是一位铁炉堡的政治家，同时也是探险者协会的成员，目前驻扎在丹莫罗的古博拉采掘场。他并没有在首都争论政策，而是亲自前往前线，监督当地石腭怪侵扰的遏制工作。他招募热心的冒险者在这些野兽彻底淹没采掘场之前将它们清除。",h="参议员梅尔·圣石是一位铁炉堡的政治家，同时也是探险者协会的成员，目前驻扎在丹莫罗的古博拉采掘场。他并没有在首都争论政策，而是亲自前往前线，监督当地石腭怪侵扰的遏制工作。他招募热心的冒险者在这些野兽彻底淹没采掘场之前将它们...",kw={"丹莫罗","探险者协会","古博拉","铁炉堡参议院","梅尔","采掘场","石颚","参议员","圣石","石腭怪"},ang={["faction:Alliance"]="圣石让人们能够初步了解矮人领导层的工作方式，为年轻的联盟英雄提供了直截了当的公民义务：杀怪以保护工作的平民。",["race:Dwarf"]="对于矮人来说，看到一位民选参议员站在齐膝深的矿坑泥浆中，而不是在铁炉堡的High Seat里啜饮麦芽酒，这正是矮人坚毅精神的绝佳体现。"},sec={{t="矿坑里的政治家",b="大多数铁炉堡参议院的议员们整日安稳地待在首都宏伟的石厅中，但参议员梅尔·圣石却更倾向于直接采取行动。作为一名既致力于治理国家，又热衷于探险者协会历史探索的矮人，他深知这个王国所面临的现实危险。当凶恶的石颚石腭怪开始从古博拉采掘场的深岩中爬出来时，圣石亲自前往了矿坑。他深信官僚主义的姿态无法拯救矿工，于是他出资悬赏有能力的旅行者，让他们消灭这些好斗的石腭怪，收复采掘场。"}},faq={{q="参议员梅尔·圣石是谁？",a="参议员梅尔·圣石是铁炉堡参议院的一位矮人政治家。与他的许多立法同僚不同，他积极参与边境事务，并且是探险者协会的成员。他目前在古博拉采掘场守卫并组织防御工作。",al={"圣石的作用","参议员是谁","梅尔·圣石"}},{q="为什么一位参议员会驻扎在古博拉采掘场？",a="圣石亲自深入采掘场，以应对那里发生的危机。采掘场突然遭到从地底钻出的石颚石腭怪的入侵，威胁到了矮人矿工和宝贵的挖掘工作，圣石拒绝在等待遥远的官僚机构处理时让问题恶化。",al={"为什么圣石在这里","他为什么在采掘场","丹莫罗的参议员"}},{q="参议员圣石想让冒险者做什么？",a="他雇佣刚到达的冒险者来清除古博拉采掘场内外的石颚石腭怪。通过消灭盘踞在下层的石腭怪，新兵们可以帮助稳固挖掘现场，保障剩余矿工的安全。",al={"公务员任务","圣石的任务","采掘场任务"}},{q="除了参议院之外，圣石还属于什么组织？",a="除了在参议院的立法职责外，梅尔·圣石还是探险者协会的成员。这种背景激发了他对地下挖掘的兴趣，也解释了他为何愿意走出首都的安逸环境，前往远方。",al={"圣石的派系","圣石是探险者协会的吗","圣石的从属"}}},fx={["67284ec7"]={q="参议员梅尔·圣石属于哪一方？",a="参议员梅尔·圣石坚定地效忠铁炉堡王国和大联盟。作为在任的铁炉堡议会成员、探险者协会的活跃成员，他直接效忠国王麦格尼·铜须，并致力于保护矮人故土。",al={"圣石参议员的阵营","圣石效忠谁","圣石是大联盟成员吗"}}},fp="24,376,24.624.0,32.293.0,47.335.0,53.237.0,64.245.0"}
P.entries["npc:senior-surveyor-fizzledowser"] = {n="高级勘探员菲兹杜瑟",s="高级勘探员菲兹杜瑟是一位在地精城市加基森（位于塔纳利斯）工作的地精研究员。他负责调查当地供水系统受到的干扰，并派遣冒险者调查斯克林克的失踪事件。",h="高级勘探员菲兹杜瑟是一位在地精城市加基森（位于塔纳利斯）工作的地精研究员。他负责调查当地供水系统受到的干扰，并派遣冒险者调查斯克林克的失踪事件。",kw={"探水仪","菲兹杜瑟","加基森","大裂口","匹斯特苏格","斯克林克","异种虫","塔纳利斯","水业公司"},ang={["profession:Engineering"]="菲兹杜瑟依靠定制的地精工程探水仪来精确定位流沙之下的隐藏水源。"},sec={{t="寻水之旅出的差错",b="高级勘探员菲兹杜瑟以加基森为基地，主要致力于解决这座沙漠城镇长期存在的资源问题。由于当地的水井和水坑不断被敌对的废土流浪者强盗占据，加基森水业公司必须到更远的地方寻找未开发的蓄水层。为此，菲兹杜瑟派遣配备了探水仪的侦察兵穿越沙丘，前往流沙岗哨等地。然而，他的探测器并没有找到干净的泉水，反而不断探入地下的昆虫巢穴，这不仅没能解决问题，反而引发了一场即将来临的生态灾难。"},{t="发掘异种虫",b="当他的勘探队员开始遭到身披甲壳、擅长掘地的昆虫的毁灭性伏击时，菲兹杜瑟与炼金师匹斯特苏格合作对这些样本进行了检查。后续发生的悲剧——包括初级勘探员斯克林克在大裂口内的失踪——证明这些并非普通的沙漠害虫，而是被称为异种虫的有组织的先遣部队。面对这些预示着足以吞没卡利姆多南部的威胁的调查结果，菲兹杜瑟感到惊恐万分，他抛开了地精的中立立场，向部落和联盟的学者发出了警报。"}},faq={{q="谁是高级勘探员菲兹杜瑟？",a="他是加基森水业公司的一名工程师兼现场主管。他的职责是在塔纳利斯沙漠中寻找可用的水井，以维持加基森的供应。",al={"菲兹杜瑟是谁","菲兹杜瑟 塔纳利斯","加基森勘探员"}},{q="什么是加基森水业公司？",a="这是一家在加基森运营的商业企业，负责在塔纳利斯这片干旱沙漠中获取、处理和分配水源，在这里，水资源是最宝贵的商品。",al={"加基森水业公司","菲兹杜瑟为谁工作"}},{q="初级勘探员斯克林克发生了什么事？",a="斯克林克是一名失踪的探矿员，菲兹杜瑟请求冒险者调查他的失踪事件。",al={"斯克林克在哪里","斯克林克的救赎","斯克林克发生了什么"}},{q="为什么菲兹杜瑟会对沙漠里的昆虫感到担忧？",a="他的调查始于令人不安的昆虫活动以及对加基森供水系统的干扰，这促使他收集证据进行进一步的研究。",al={"为什么要调查虫子","腐化之巢调查","塔纳利斯的异种虫威胁"}}},fp="28,212,29.591.1,23.561.1,36.168.0,36.195.0,44.100.1,55.152.0"}
P.entries["npc:senir-whitebeard"] = {n="森内尔·白须",s="森内尔·白须是一位驻扎在卡拉诺斯雷酒酿制厂外的矮人高官兼现场特工。作为铁炉堡议会的特别使节，他的任务是监视丹莫罗周边日益严重的威胁。他的使命核心是评估霜鬃巨魔的攻势，并将他们的动向直接上报给矮人领导层。",h="森内尔·白须是一位驻扎在卡拉诺斯雷酒酿制厂外的矮人高官兼现场特工。作为铁炉堡议会的特别使节，他的任务是监视丹莫罗周边日益严重的威胁。他的使命核心是评估霜鬃巨魔的攻势，并将他们的动向直接上报给矮人领导层。",kw={"丹莫罗","霜鬃巨魔","铁炉堡","卡拉诺斯","报告","议会","森内尔","白须"},ang={["faction:Alliance"]="经过丹莫罗的联盟新兵帮助森内尔守卫铁炉堡腹地，防止其被当地巨魔的起义切断。",["race:Dwarf"]="对矮人来说，森内尔代表着前线守卫者与铁炉堡管理机构之间官僚化但必不可少的联系。"},sec={{t="议会使节",b="虽然大多数游客来到卡拉诺斯是为了那熙熙攘攘的旅店和著名的烈酒，但森内尔·白须此行却是为了公事。作为铁炉堡议会直接派出的代表，他的出现凸显了高层大厅对丹莫罗动荡局势的重视。他是在雪原前线面临危险的当地侦察兵，与在那座城市石门后争论政策的立法者之间，不可或缺的桥梁。"},{t="关注霜鬃巨魔",b="森内尔最关心的是霜鬃巨魔不断升级的侵略行径。在冰冻的峭壁中流离失所、陷入绝境的巨魔们已经开始危险地逼近矮人的定居点和道路。这位受人尊敬的使节并没有亲自冲锋陷阵，而是收集巨魔位置的侦察情报，特别是他们要塞周围的情况，并编制详尽的报告，以便铁炉堡的军事指挥官能做出果断的打击。"}},faq={{q="森内尔·白须是谁？",a="森内尔·白须是铁炉堡议会派往丹莫罗的使节。他站在卡拉诺斯外，搜集关于区域威胁的情报，特别是当地的霜鬃巨魔部族。",al={"这个矮人是谁","森内尔·白须背景故事","森内尔是谁"}},{q="森内尔在卡拉诺斯做什么？",a="森内尔驻扎在卡拉诺斯，观察巨魔的活动并协调侦察报告。因为卡拉诺斯是丹莫罗的十字路口，它是接收现场情报并将其转达给铁炉堡议会的理想枢纽。",al={"森内尔为什么在这里","森内尔在卡拉诺斯的职责","森内尔做什么"}},{q="为什么铁炉堡议会需要在这里派驻使节？",a="铁炉堡议会需要可靠的第一手现场数据来分配资源和调遣卫兵。森内尔作为一名公正的官员，负责评估霜鬃巨魔的威胁是否值得首都立即采取军事升级行动。",al={"为什么要派使节","铁炉堡议会与卡拉诺斯","议会事务"}},{q="森内尔在丹莫罗最关心什么？",a="他主要关注的是霜鬃巨魔的入侵。巨魔一直在从他们的营地向外大举推进，进入矮人领地，最终对卡拉诺斯等附近的定居点构成了直接威胁。",al={"森内尔的主要问题","森内尔在监视什么威胁","森内尔与巨魔"}},{q="森内尔会亲自与巨魔战斗吗？",a="不会，森内尔的职责是行政管理和情报搜集。他依赖当地的侦察兵、山地探险者和路过的冒险者进入像霜鬃巨魔要塞这样的敌对地点，为他取回关键的侦察情报。",al={"森内尔会战斗吗","森内尔是战士吗","森内尔的战斗"}},{q="森内尔的报告会送往哪里？",a="一旦森内尔编制好关于巨魔位置和兵力的现场记录，完成的报告就会直接沿着山路送往铁炉堡的议会和领导层。",al={"报告去向","森内尔的报告目的地","谁收到报告"}}},fx={["40f66e19"]={q="森内尔·白须属于哪一方？",a="森内尔·白须为铁炉堡王国和大联盟效力。他以铁炉堡议会直接授权的正式使节身份行事，完全效忠矮人政府，并守卫王国的腹地。",al={"森内尔·白须的忠诚归属","森内尔效忠谁","森内尔的阵营"}}},fp="16,377,19.432.0,22.434.0,24.191.0,32.239.0,52.235.0,46.205.0,36.221.0,28.179.0"}
P.entries["npc:sentinel-arynia-cloudsbreak"] = {n="哨兵阿瑞尼亚·碎云",s="哨兵阿瑞尼亚·碎云是一位驻守在泰达希尔神谕林地宁静树丛中的暗夜精灵守护者。她肩负着监测北方枝叶神圣平衡的职责，时刻警惕地守护着林地中受过魔法加持的水域和林中野生生物。",h="哨兵阿瑞尼亚·碎云是一位驻守在泰达希尔神谕林地宁静树丛中的暗夜精灵守护者。她肩负着监测北方枝叶神圣平衡的职责，时刻警惕地守护着林地中受过魔法加持的水域和林中野生生物。",kw={"阿瑞尼亚·碎云","魔法林地","卡多雷","迷雾","暗夜精灵","神谕林地","哨兵","泰达希尔"},ang={["faction:Alliance"]="阿瑞尼亚代表着卡多雷哨兵的警觉，守护着联盟在卡利姆多这片至关重要的林地堡垒。",["race:NightElf"]="对于在泰达希尔完成成人礼的年轻暗夜精灵来说，协助哨兵碎云可以提供保护他们新家园自然平衡的实践经验。"},sec={{t="神谕林地的守望者",b="阿瑞尼亚·碎云在泰达希尔最僻静、最神秘的区域之一——神谕林地，为哨兵部队效力。在古老的树木和灵泉之间，她远离达纳苏斯喧嚣的街道，时刻警惕着，确保这片荒野的神圣不受干扰。"},{t="林地之乱",b="尽管泰达希尔诞生之初十分神圣，但逐渐蔓延的不谐之音已经开始让这里的生物感到不安。阿瑞尼亚依靠路过的冒险者和年轻的暗夜精灵来调查当地的异常状况，例如林地野生生物的异常行为，以及魔法泉水周围出现的神秘现象。"}},faq={{q="哨兵阿瑞尼亚·碎云是谁？",a="她是一位驻守在泰达希尔北部深处神谕林地的暗夜精灵哨兵。她看护着这片神秘的林地，并招募过往的旅人来协助维护此地的自然和谐。",al={"阿瑞尼亚·碎云","阿瑞尼亚是谁","哨兵阿瑞尼亚"}},{q="在哪里可以找到阿瑞尼亚·碎云？",a="阿瑞尼亚驻守在泰达希尔西北部的神谕林地，位于多兰纳尔以北的露天区域。",al={"阿瑞尼亚位置","阿瑞尼亚在哪里","阿瑞尼亚·碎云地图"}},{q="她在哨兵部队中履行什么职责？",a="作为一名驻扎在荒野中的哨兵，她巡视着外围的森林枝叶，监视当地的灵魂、野生生物和自然现象，以防出现任何腐化或失衡的迹象。",al={"阿瑞尼亚的职责","阿瑞尼亚做什么"}},{q="她与泰达希尔上的其他人有亲属关系吗？",a="她与Mavoris Cloudsbreak拥有相同的姓氏，这表明在居住于世界之树上的暗夜精灵之间存在着家族纽带。",al={"阿瑞尼亚家族","mavoris cloudsbreak"}},{q="她会给冒险者布置什么任务？",a="她提供的任务包括调查这座受魔法影响的林地，处理附近的神秘骚乱和游荡的野兽，同时也包括救助陷入困境的生物。",al={"阿瑞尼亚任务","神谕林地任务"}},{q="为什么神谕林地对暗夜精灵很重要？",a="神谕林地是泰达希尔内的一处神圣避难所，以其宁静的水潭和崇高的精神信仰而闻名，由德鲁伊和哨兵负责监管，他们在此寻求自然的指引和启示。",al={"为什么是神谕林地","神谕林地背景故事"}}},fx={["8186bb8d"]={q="哨兵阿瑞尼亚·碎云属于哪一方？",a="阿瑞尼亚效力于哨兵——暗夜精灵著名的军事力量，并坚定效忠达纳苏斯的领导者和大联盟。她驻扎在泰达希尔宁静的林地中，职责是保护家园，确保卡多雷的灵性圣地不受腐化或外来威胁侵扰。",al={"阿瑞尼亚·碎云的阵营","阿瑞尼亚·碎云与大联盟","阿瑞尼亚效忠谁"}},d0964425={q="哨兵阿瑞尼亚·碎云为什么在神谕林地？",a="阿瑞尼亚驻守在神谕林地，守望泰达希尔宁静的北部区域。这片林地对暗夜精灵意义神圣。身为哨兵，她坚守岗位，照看当地野生生物，并处理任何威胁这片魔法森林圣洁的骚动。",al={"阿瑞尼亚·碎云为何在这里","阿瑞尼亚·碎云与神谕林地","哨兵阿瑞尼亚为何在神谕林地"}}},fp="27,268,27.297.0,20.290.0,35.195.0,38.126.0,46.186.0,44.125.0,40.178.0,55.182.0"}
P.entries["npc:sentinel-aynasha"] = {n="哨兵阿娜莎",s="哨兵阿娜莎是活跃在黑海岸荒野边缘的暗夜精灵哨兵部队的一员。她负责侦察敌方动向并传递重要情报，经常面临威胁卡利姆多北部的敌对势力的危险。",h="哨兵阿娜莎是活跃在黑海岸荒野边缘的暗夜精灵哨兵部队的一员。她负责侦察敌方动向并传递重要情报，经常面临威胁卡利姆多北部的敌对势力的危险。",kw={"弓箭手","阿娜莎","黑海岸","卡多雷","暗夜精灵","侦察兵","哨兵"},ang={["faction:Alliance"]="对于在卡利姆多旅行的联盟成员来说，像阿娜莎这样的哨兵侦察兵是危险荒野道路上的重要联络点。",["race:NightElf"]="阿娜莎代表了卡多雷军队的警惕先锋，保卫着古老的森林，抵御外来势力的侵蚀和荒野的腐化。"},sec={{t="在前线",b="作为哨兵部队的侦察兵和弓箭手，阿娜莎被派往暗夜精灵领地与敌对入侵者交锋的危险前沿。她在崎岖的地形中执行潜行任务并传递紧急快报，依靠自己的箭术和生存本能来躲避敌方巡逻队，并在争议领地的深处生存下来。"}},faq={{q="哨兵阿娜莎是谁？",a="阿娜莎是暗夜精灵哨兵部队中活跃的侦察兵和弓箭手，这支部队是保护卡利姆多北部及其边界的主要军事和防御力量。",al={"阿娜莎是谁","阿娜莎的职责","哨兵阿娜莎背景故事"}},{q="她在黑海岸监测哪些威胁？",a="她在黑海岸的边缘地带活动，监视着威胁暗夜精灵荒野的敌对营地、堕落的熊怪部落以及外来入侵者。",al={"阿娜莎的敌人","黑海岸的威胁","她正在与谁战斗"}},{q="她为什么经常独自在路上行动？",a="哨兵经常独自行动或以两人为一组进行侦察，以便在岗哨之间传递紧急情报，同时不会引起敌对势力的不必要注意。",al={"她为什么独自一人","阿娜莎的单人任务","哨兵侦察兵的职责"}}},fp="16,256,18.347.0,24.158.0,43.166.0,38.162.0"}
P.entries["npc:sentinel-elissa-starbreeze"] = {n="哨兵艾莉萨·星风",s="哨兵艾莉萨·星风是一名暗夜精灵守卫，驻扎在黑海岸迷雾笼罩的海岸线上，身处奥伯丁。她在一座横跨桥梁的旅舍二楼执勤，负责监视该地区日益增长的威胁，并引导旅行者前往荒野中亟待解决的事务。",h="哨兵艾莉萨·星风是一名暗夜精灵守卫，驻扎在黑海岸迷雾笼罩的海岸线上，身处奥伯丁。她在一座横跨桥梁的旅舍二楼执勤，负责监视该地区日益增长的威胁，并引导旅行者前往荒野中亟待解决的事务。",kw={"奥萨拉克斯","奥伯丁","黑海岸","艾莉萨·星风","暗夜精灵","哨兵"},ang={["faction:Alliance"]="对于从泰达希尔抵达的联盟旅行者来说，星风是最初的联络人之一，指引他们深入黑海岸那片闹鬼的荒野提供援助。",["race:NightElf"]="哨兵星风代表了哨兵部队为卡利姆多北部前哨站（如奥伯丁）所提供的警觉而严明的保护。"},sec={{t="奥伯丁的警觉之眼",b="虽然许多哨兵直接在雾气缭绕的海岸线和林地中巡逻，但艾莉萨·星风主要在奥伯丁协调防御工作。她驻扎在城镇旅店东北方向过桥后的建筑二楼，时刻警惕着黑海岸的不寻常异动。她的任务经常指引冒险者前往偏远的地点，包括远处北方的奥萨拉克斯之塔，以确保阴影中的入侵不会让这个沿海定居点措手不及。"}},faq={{q="我能在哪里找到哨兵艾莉萨·星风？",a="她位于黑海岸的奥伯丁。穿过城镇旅店东北方的小桥，上到那栋建筑的二楼，就能找到正在值勤的她。",al={"艾莉萨·星风位置","艾莉萨·星风在哪里","奥伯丁 星风"}},{q="她在黑海岸的职责是什么？",a="作为暗夜精灵哨兵的一员，她通过追踪黑海岸各处的潜在危险来协助保卫奥伯丁。她会指引有能力的侦察兵和冒险者去调查遥远的前哨站和奇怪的威胁，例如奥萨拉克斯之塔。",al={"艾莉萨做什么","艾莉萨·星风职责"}},{q="她在暗夜精灵中有亲人吗？",a="关于她的亲属没有任何记录。人们只知道她在奥伯丁履行哨兵职责，守护着城镇，并将旅行者派往奥萨拉克斯之塔。",al={"星风家人","艾莉萨的亲属"}}},fx={eef8e9fa={q="哨兵艾莉萨·星风是谁？",a="哨兵艾莉萨·星风是一名暗夜精灵守卫，在奥伯丁的海滨港口为哨兵效力。她驻守在黑海岸，守望这座聚居地，并引导有能力的旅人处理周边荒野中紧迫的问题，包括调查神秘的奥萨拉克斯之塔附近的情况。",al={"艾莉萨·星风是谁","艾莉萨·星风是暗夜精灵吗","哨兵艾莉萨·星风的身份"}},["73c7acf2"]={q="哨兵艾莉萨·星风属于哪一方？",a="她完全效忠哨兵、达纳苏斯的暗夜精灵以及更广泛的大联盟。她驻守在奥伯丁，致力于守护卡利姆多海岸沿线的暗夜精灵聚居地及其利益。",al={"艾莉萨·星风属于哪个阵营","艾莉萨·星风是大联盟成员吗","艾莉萨·星风效忠谁"}},["650c6447"]={q="哨兵艾莉萨·星风为什么在奥伯丁？",a="艾莉萨在黑海岸驻扎，是守卫奥伯丁的地区哨兵分队的一员。她从村庄上方的哨站协调斥候，并招募冒险者监视沿海地带和内陆遗迹中正在发生的邪恶活动。",al={"艾莉萨·星风为何在奥伯丁","艾莉萨·星风在黑海岸的位置","艾莉萨·星风为何来到这里"}}},fp="26,274,27.507.0,44.168.0,30.245.0,43.167.0"}
P.entries["npc:sentinel-farsong"] = {n="哨兵艾蒂亚·轻歌",s="哨兵艾蒂亚·轻歌是一位驻守在灰谷银翼树林的暗夜精灵哨兵。作为银翼要塞的重要联络人，她负责协调针对战歌峡谷内日益猖獗的战歌氏族的各种情报收集与战斗行动。",h="哨兵艾蒂亚·轻歌是一位驻守在灰谷银翼树林的暗夜精灵哨兵。作为银翼要塞的重要联络人，她负责协调针对战歌峡谷内日益猖獗的战歌氏族的各种情报收集与战斗行动。",kw={"灰谷","哨兵艾蒂亚·轻歌","银翼树林","银翼要塞","战歌峡谷","战歌氏族"},ang={["faction:Alliance"]="哨兵艾蒂亚·轻歌代表了联盟在灰谷的前线动员力量，直接指挥志愿者投身于对抗战歌氏族的斗争之中。",["race:NightElf"]="作为艾露恩神圣森林的保护者，艾蒂亚·轻歌体现了卡多雷将一切亵渎古老森林之徒驱逐出去的坚定决心。"},sec={{t="银翼树林的守护者",b="哨兵艾蒂亚·轻歌在银翼树林内守望，深度参与了灰谷南部的边境防御。鉴于战歌氏族不断地砍伐树木并深入暗夜精灵的祖居地，她动员联盟的勇士们出击对抗战歌氏族，并确保战场前线的报告能够传达给银翼要塞的指挥部。她的职责核心在于召集志愿者以遏制部落的领土扩张，保护这片神圣的森林。"}},faq={{q="哨兵艾蒂亚·轻歌是谁？",a="哨兵艾蒂亚·轻歌是灰谷银翼要塞的一位暗夜精灵哨兵。她驻守在战歌峡谷入口附近的银翼树林，负责招募联盟的冒险者并收集关键的战斗情报。",al={"艾蒂亚·轻歌","哨兵艾蒂亚·轻歌背景故事","艾蒂亚·轻歌是谁"}},{q="她在哪里？",a="她位于灰谷东南部的银翼树林，那是联盟在战歌峡谷持续进行的军事行动的集结地。",al={"哨兵艾蒂亚·轻歌位置","艾蒂亚·轻歌在哪里","艾蒂亚·轻歌灰谷地图"}},{q="她为什么要与战歌氏族作战？",a="战歌氏族正在砍伐木材并亵渎灰谷的神圣森林。艾蒂亚·轻歌统筹防御力量，旨在阻止他们的行动并收复被部落占据的领土。",al={"为何与战歌氏族作战","艾蒂亚·轻歌的动机","灰谷冲突"}}},fx={e9cb1820={q="哨兵艾蒂亚·轻歌属于哪一方？",a="哨兵艾蒂亚·轻歌为达纳苏斯哨兵和银翼要塞效力，代表大联盟作战。她驻扎在灰谷的银翼树林，坚定抵抗部落的入侵，召集暗夜精灵及其盟友守护祖传林地。",al={"艾蒂亚·轻歌的阵营","艾蒂亚效忠谁","哨兵艾蒂亚·轻歌与大联盟"}},a1fa54ea={q="哨兵艾蒂亚·轻歌想做什么？",a="哨兵艾蒂亚·轻歌希望将战歌氏族斥候和部落入侵者彻底逐出灰谷。她整理前线的军情报告、收集资源，并召集大联盟勇士消灭威胁这片圣林的入侵势力。",al={"艾蒂亚需要什么","艾蒂亚的目标","哨兵艾蒂亚·轻歌的任务"}},ffcf1925={q="哨兵艾蒂亚·轻歌为什么在这里？",a="哨兵艾蒂亚·轻歌驻守在银翼树林，负责监督战歌峡谷北部边境的行动。灰谷一直遭受部落围攻，她是协调部队和侦察行动、应对不断逼近的伐木行动的重要联络人。",al={"艾蒂亚为何在灰谷","艾蒂亚与银翼树林","哨兵艾蒂亚为何在这里"}},["31bb4497"]={q="哨兵艾蒂亚·轻歌与谁有关联？",a="哨兵艾蒂亚·轻歌隶属于银翼要塞以及达纳苏斯麾下更广泛的暗夜精灵军队。她与驻扎在银翼树林的大联盟守军并肩行动，并与指挥抵御战歌氏族的将领保持直接联络。",al={"艾蒂亚的盟友","哨兵艾蒂亚·轻歌的关系","艾蒂亚向谁汇报"}}},fp="16,251,28.463.0,24.238.0,23.142.0,42.197.0"}
P.entries["npc:sentinel-onaeya"] = {n="哨兵奥奈雅",s="哨兵奥奈雅是一位驻扎在灰谷西北部迈斯特拉岗哨的暗夜精灵守卫，靠近黑海岸的边界。她的任务是抵御入侵的威胁，并召集有能力的联盟冒险者保护森林并援助其他哨兵同伴。",h="哨兵奥奈雅是一位驻扎在灰谷西北部迈斯特拉岗哨的暗夜精灵守卫，靠近黑海岸的边界。她的任务是抵御入侵的威胁，并召集有能力的联盟冒险者保护森林并援助其他哨兵同伴。",kw={"灰谷","黑海岸","迈斯特拉岗哨","暗夜精灵","奥奈雅","哨兵"},ang={["faction:Alliance"]="奥奈雅为从沿海荒野进入灰谷争夺激烈的森林的联盟旅行者协调必要的防御任务。",["faction:Horde"]="作为一名坚守迈斯特拉岗哨的忠诚哨兵，奥奈雅是一位积极守卫灰谷北部入口的敌对战斗人员。",["race:NightElf"]="对于从黑海岸向南旅行的暗夜精灵来说，奥奈雅代表了防御神圣灰谷林地免受外部威胁的第一道防线。"},sec={{t="边境的守卫",b="迈斯特拉岗哨是从黑海岸通往灰谷茂密、争夺激烈的林冠地带道路上的一个重要中转站。哨兵奥奈雅站在营地主屋之外守卫，时刻警惕着过往的旅人，并协调防御行动。在敌对的野兽、堕落力量和边境局势之间，像奥奈雅这样的哨兵构成了该地区暗夜精灵定居点的第一道防线。"},{t="坚守岗哨",b="奥奈雅收到了关于哨兵阿娜莎的消息，她在穿过黑海岸传递重要信息时遭到了熊怪的袭击。她会奖励那些保护中毒的哨兵直到解毒剂生效的冒险者。"}},faq={{q="哨兵奥奈雅是谁？",a="哨兵奥奈雅是一位驻扎在灰谷西北部迈斯特拉岗哨的暗夜精灵哨兵。她担任任务发布者和前线防御者，指引旅行者协助岗哨。",al={"奥奈雅","哨兵奥奈雅","奥奈雅是谁"}},{q="哨兵奥奈雅在哪里？",a="你可以在迈斯特拉岗哨主建筑外找到她，那里位于灰谷的北部道路旁，紧邻黑海岸边界。",al={"奥奈雅位置","哨兵奥奈雅在哪里","寻找奥奈雅"}},{q="哨兵奥奈雅属于哪个阵营？",a="她是暗夜精灵哨兵的一员，效忠于联盟。部落冒险者见到她时会受到敌对。",al={"奥奈雅阵营","奥奈雅是联盟吗","奥奈雅对部落友好吗"}},{q="奥奈雅和哨兵阿娜莎有什么联系？",a="哨兵阿娜莎请求冒险者在保护她免受熊怪袭击后，向迈斯特拉岗哨的奥奈雅汇报。奥奈雅会奖励他们的英勇行为，并为阿娜莎幸存感到高兴。",al={"奥奈雅 阿娜莎","哨兵阿娜莎奖励"}},{q="哨兵奥奈雅会提供什么样的任务？",a="奥奈雅会奖励那些在黑海岸保护哨兵阿娜莎免受熊怪袭击，并将她平安的消息带到迈斯特拉岗哨的冒险者。",al={"奥奈雅任务","奥奈雅有哪些任务"}},{q="为什么迈斯特拉岗哨对哨兵部队很重要？",a="迈斯特拉岗哨是连接黑海岸补给线与灰谷腹地的关键检查点。坚守此地可以防止敌对势力切断向南行进的暗夜精灵旅行者的去路。",al={"为什么是迈斯特拉岗哨","迈斯特拉岗哨的重要性"}}},fx={e1ad0868={q="哨兵奥奈雅为什么驻扎在迈斯特拉岗哨？",a="哨兵奥奈雅在迈斯特拉岗哨主庇护所外站岗，守望灰谷西北部。作为驻扎在边境的暗夜精灵哨兵，她协助守卫哨站，应对周边威胁，并接收旅人带来的情报，帮助艾娜莎等哨兵同伴。",al={"奥奈雅为何在这里","哨兵奥奈雅驻扎此地的原因","奥奈雅为何在迈斯特拉岗哨"}}},fp="15,274,23.435.0,16.215.0,23.187.0,33.154.0,44.122.0,44.186.0,45.140.0,49.197.0"}
P.entries["npc:sentinel-selarin"] = {n="哨兵塞拉伊",s="哨兵塞拉伊是一位被派往奥伯丁沿海定居点的暗夜精灵斥候。作为灰谷守军的特使，她寻求援军以帮助遏制威胁着这片古老森林的日益严重的危险。",h="哨兵塞拉伊是一位被派往奥伯丁沿海定居点的暗夜精灵斥候。作为灰谷守军的特使，她寻求援军以帮助遏制威胁着这片古老森林的日益严重的危险。",kw={"灰谷","奥伯丁","darkshore","莱恩·狼行者","塞拉伊","哨兵塞拉伊","哨兵部队","特伦希斯"},ang={["faction:Alliance"]="塞拉伊是联盟勇士们从Darkshore前往充满争议的灰谷荒野时的重要桥梁。",["race:NightElf"]="作为哨兵部队的一员，塞拉伊体现了保卫kaldorei祖先领地边境所必需的警惕与团结。"},sec={{t="请求援军",b="随着灰谷各地的紧张局势和黑暗威胁不断升级，当地驻军的资源已捉襟见肘。在莱恩·狼行者的指挥下，哨兵塞拉伊沿着林间道路向北进入了Darkshore。她的任务非常明确：在奥伯丁寻找特伦希斯，并请求驻扎在海岸的哨兵和斥候提供援助。"},{t="召集旅人",b="到达奥伯丁后，塞拉伊发现特伦希斯正忙于当地的事务，无法亲自响应这一号召。塞拉伊没有空手而归，而是决定留在镇上，招募途经Darkshore的有能力的人。她将经过考验的冒险者指引向南方的阿斯特兰纳，敦促他们为莱恩·狼行者那备受困扰的部队贡献他们的利刃与法术。"}},faq={{q="哨兵塞拉伊是谁？",a="哨兵塞拉伊是一位属于哨兵部队的暗夜精灵战士。她担任信使和联络员，从灰谷被派往Darkshore的奥伯丁定居点寻求援助。",al={"塞拉伊背景故事","塞拉伊是谁","哨兵塞拉伊"}},{q="塞拉伊为什么来到奥伯丁？",a="她受莱恩·狼行者之命，前往奥伯丁寻找特伦希斯，并争取援军以应对威胁灰谷荒野的日益严重的危险。",al={"为什么塞拉伊在darkshore","塞拉伊的任务","塞拉伊在做什么"}},{q="为什么特伦希斯没有和她一起去灰谷？",a="特伦希斯忙于处理关键事务并调查Darkshore内部的威胁。因此，塞拉伊决定转而招募独立的联盟旅行者南下。",al={"为什么特伦希斯不帮忙","特伦希斯和塞拉伊","特伦希斯很忙"}},{q="她会把冒险者派往何处？",a="她指引冒险者向南穿越边境进入灰谷，直接向阿斯特兰纳的莱恩·狼行者汇报。",al={"塞拉伊把我派往哪里","塞拉伊的任务目的地","在塞拉伊之后"}}},fx={["5ef6a9e4"]={q="哨兵塞拉伊属于哪一方？",a="哨兵塞拉伊是暗夜精灵哨兵部队的忠诚士兵，为联盟效力，并直接听命于灰谷防卫部队中的上级，例如莱恩·狼行者。",al={"塞拉伊所属阵营","哨兵塞拉伊是否效力联盟","塞拉伊听命于谁"}},bee3573a={q="哨兵塞拉伊想要什么？",a="塞拉伊希望为灰谷日益加剧的动乱争取援军。她最初前来召唤特伦希斯，但意识到他在黑海岸也肩负着重要职责后，便打算集结有能力的冒险者南下，转而援助莱恩·狼行者。",al={"塞拉伊的目标","塞拉伊需要什么","塞拉伊想做什么"}},["8a8a2168"]={q="哨兵塞拉伊与谁有关联？",a="塞拉伊听命于莱恩·狼行者。莱恩驻扎在灰谷，并派她执行任务。她也与奥伯丁的特伦希斯相熟，两人协力争取援助，并将有潜力的新人送往前线。",al={"塞拉伊为谁效力","塞拉伊的人际关系","塞拉伊与莱恩·狼行者"}}},fp="16,230,25.381.0,22.397.0,24.182.0,34.162.0,46.196.0,32.119.0"}
P.entries["npc:sentinel-thenysil"] = {n="哨兵塞恩希尔",s="哨兵塔拉·塞恩希尔是一名驻守在灰谷古老森林中阿斯特兰纳的暗夜精灵哨兵。她时刻警惕着周遭的荒野，密切关注着该地区的军事行动，并负责协调监视邻近领土的侦察兵。她尤其关注向南推进至充满争议的石爪山脉的盟军动向。",h="哨兵塔拉·塞恩希尔是一名驻守在灰谷古老森林中阿斯特兰纳的暗夜精灵哨兵。她时刻警惕着周遭的荒野，密切关注着该地区的军事行动，并负责协调监视邻近领土的侦察兵。她尤其关注向南推进至充满争议的石爪山脉的盟军动向。",kw={"灰谷","阿斯特兰纳","凯拉·影矛","哨兵","石爪山脉","塔拉·塞恩希尔","塞恩希尔","泰兰德·语风"},ang={["faction:Alliance"]="作为灰谷与石爪山脉之间的早期桥梁，塞恩希尔为联盟冒险者提供了直接赢取达纳苏斯领导层青睐的机会。",["race:Gnome"]="塞恩希尔认为将一名联盟侏儒法师部署到石爪山脉是一个不同寻常且令人担忧的迹象，这凸显了暗夜精灵对他们矮小盟友的看法依然充满好奇。",["race:NightElf"]="塞恩希尔代表了哨兵部队的勤勉守望，她们不知疲倦地工作，以保护卡利姆多的神圣树林，并确保盟军特工在边境前线平安无事。"},sec={{t="守望边境",b="哨兵塞恩希尔在阿斯特兰纳的防御据点履行职责，协助保卫灰谷，抵御日益增长的敌意。该地区各处的暗夜精灵据点都面临着无情的侵蚀，因此保持远程哨站之间的通讯至关重要。虽然当地守军的大部分精力都直接集中在保卫森林道路上，但塞恩希尔会将联盟志愿者派往灰谷边境之外，以确保远方的盟友得到持续的支援。"},{t="与石爪山脉的联系",b="塞恩希尔与凯拉·影矛保持着密切的私人和军事友谊，后者是一名被部署到南面石爪山脉崎岖山地的特工。在得知凯拉是与一名古怪的侏儒法师一同被派往那里后，塞恩希尔认为这种不同寻常的搭档组合无疑预示着山峰中正在酝酿重大的麻烦。出于对自己同志可能面临危险的担忧，她招募了有能力的冒险者前往南方，提供支援并汇报任务的进展情况。"},{t="树冠下的召见",b="当侦察兵从石爪山脉带回成功打击荆棘谷地精的捷报时，塞恩希尔确保他们的事迹不会被埋没。她意识到在山中抵御机械化开采能够保护所有邻近荒野的安宁，因此授予可靠的英雄们正式的嘉奖。她没有将功劳据为己有，而是指引他们前往达纳苏斯的Temple of the Moon，在那里接受高阶女祭司泰兰德·语风的亲自接见。"}},faq={{q="去哪里可以找到哨兵塞恩希尔？",a="哨兵塞恩希尔驻守在阿斯特兰纳，这是位于灰谷中心道路沿线的主要暗夜精灵要塞。",al={"塞恩希尔位置","哨兵塞恩希尔在哪里","塞恩希尔 阿斯特兰纳"}},{q="为什么塞恩希尔要派遣旅行者前往石爪山脉？",a="她的朋友凯拉·影矛被部署到了石爪山脉，并与一名侏儒法师同行。塞恩希尔将这种不同寻常的指派视为危险麻烦的征兆，因此派遣可靠的冒险者去支援凯拉的任务。",al={"为什么去石爪山脉","塞恩希尔石爪山脉任务","为什么在石爪山脉守卫"}},{q="凯拉·影矛是谁？",a="凯拉·影矛是一名暗夜精灵侦察兵，也是哨兵塞恩希尔的密友。她目前驻扎在石爪山脉，负责调查对该地区构成的威胁。",al={"凯拉是谁","凯拉·影矛关系","塞恩希尔朋友"}},{q="石爪山脉正在对抗什么样的威胁？",a="除了与当地敌人的小规模冲突外，荆棘谷地精在石爪山脉建立了极具破坏性的工业入侵行动，对当地进行露天采矿和森林砍伐。",al={"石爪山脉威胁","石爪山脉发生了什么","石爪山脉荆棘谷地精"}},{q="为什么塞恩希尔要派遣冒险者去见泰兰德·语风？",a="在冒险者成功协助凯拉·影矛阻止了荆棘谷地精在石爪山脉的阴谋后，塞恩希尔会指引他们前往达纳苏斯，以便高阶女祭司泰兰德·语风能够亲自认可他们为暗夜精灵所做的贡献。",al={"泰兰德的接见","为什么要见泰兰德","塞恩希尔达纳苏斯引荐"}},{q="哨兵塞恩希尔在阿斯特兰纳的角色是什么？",a="她担任阿斯特兰纳的哨兵协调员，负责组织区域情报、监控边境，并派遣可靠的联盟新兵去支援远方的驻军。",al={"塞恩希尔军衔","塞恩希尔做什么","哨兵塞恩希尔职责"}}},fx={cd8ae8e6={q="哨兵塞恩希尔属于哪一方？",a="哨兵塞恩希尔忠于暗夜精灵和联盟。作为驻扎在阿斯特兰纳的哨兵部队现役士兵，她守卫着灰谷边境，并协调对卡利姆多各地暗夜精灵哨站和行动的支援。",al={"哨兵塞恩希尔所属阵营","塞恩希尔听命于谁","塞恩希尔是否效力联盟"}},ad790eb1={q="哨兵塞恩希尔为何在阿斯特兰纳？",a="阿斯特兰纳是灰谷主要的暗夜精灵据点，也是守卫森林的前线指挥所。哨兵塞恩希尔驻扎于此，负责警戒该地区、监视贸易路线，并在邻近土地亟需增援时招募有能力的旅人。",al={"塞恩希尔为何在阿斯特兰纳","塞恩希尔在灰谷的驻地","哨兵塞恩希尔为何在这里"}}},fp="17,379,20.435.0,18.480.0,22.489.1,37.122.0,57.214.0,25.159.0,44.194.0,58.248.1,46.177.0"}
P.entries["npc:sentinel-tysha-moonblade"] = {n="哨兵坦莎·月刃",s="哨兵坦莎·月刃是一名驻扎在黑海岸主路旁的暗夜精灵侦察兵，就在亚米萨兰古代遗迹的西边。她肩负着巡逻这片动荡的沿海荒野的任务，并指引旅者，招募援手去调查那些在附近破碎的精灵聚居地徘徊的躁动灵魂。",h="哨兵坦莎·月刃是一名驻扎在黑海岸主路旁的暗夜精灵侦察兵，就在亚米萨兰古代遗迹的西边。她肩负着巡逻这片动荡的沿海荒野的任务，并指引旅者，招募援手去调查那些在附近破碎的精灵聚居地徘徊的躁动灵魂。",kw={"亚米萨兰","奥伯丁","黑海岸","上层精灵","暗夜精灵","哨兵","坦莎·月刃"},ang={["faction:Alliance"]="对于从奥伯丁出发前往灰谷的联盟旅者来说，在这条充满危险和怪物横行的道路上，坦莎是少数几个友好的前哨之一。",["race:NightElf"]="坦莎代表了那些试图在饱受大分裂创伤的土地上维持和平的哨兵，她请求暗夜精灵同胞让她们被诅咒的祖先安息。"},sec={{t="守望之路",b="哨兵坦莎·月刃站在黑海岸杂草丛生的大道旁，警惕地注视着这片日益动荡的土地。在她的正东方坐落着亚米萨兰那被诅咒的遗迹，受诅咒的上层精灵幽灵和邪恶的女妖徘徊在古老的石柱之间。坦莎意识到奥伯丁在海岸各处的威胁下兵力捉襟见肘，于是征募路过且有能力的冒险者去揭开亚米萨兰悲剧陨落背后的历史，并平息 The Restless Dead。"}},faq={{q="哨兵坦莎·月刃是谁？",a="哨兵坦莎·月刃是一名巡逻黑海岸中部主路的暗夜精灵卫兵，驻扎在亚米萨兰遗迹的西边。她守卫着这条道路，防范游荡的野兽和躁动的幽灵。",al={"坦莎是谁","坦莎·月刃背景故事","哨兵坦莎"}},{q="在哪里可以找到哨兵坦莎·月刃？",a="她驻守在黑海岸南北走向的大道旁，正对着亚米萨兰的古代遗迹群的西侧。",al={"坦莎·月刃位置","坦莎在哪里","哨兵坦莎在哪里"}},{q="她给冒险者什么任务？",a="坦莎指引旅者前往附近的亚米萨兰遗迹，调查摧毁了这座古代暗夜精灵聚居地的悲剧历史，并帮助平息那些在倒塌的石柱间徘徊的受折磨的鬼魂。",al={"坦莎·月刃任务","亚米萨兰的陨落任务发布者","坦莎想要什么"}},{q="她和黑海岸的其他任何人有关系吗？",a="目前没有已知的亲属。坦莎独自一人守卫在亚米萨兰西侧的道路上，监视着那片被诅咒的遗迹。",al={"坦莎·月刃家庭"}}},fx={["73e42ede"]={q="哨兵坦莎·月刃属于哪一方？",a="哨兵坦莎·月刃效力于暗夜精灵的哨兵部队，坚定地与联盟并肩作战。作为卡利姆多神圣荒野的守护者，她巡查黑海岸的道路，保护族人和古老家园免受日益逼近的危险侵扰。",al={"坦莎·月刃所属阵营","坦莎·月刃为谁效力","坦莎·月刃是否效力联盟"}},d8373493={q="哨兵坦莎·月刃为何在这里？",a="哨兵月刃驻扎在亚米萨兰闹鬼废墟以西的道路旁，巡逻这条要道并监视附近的古老遗迹。黑海岸到处都是躁动的灵魂和潜伏的敌人，因此必须保持警惕，确保过往旅人和附近的精灵聚居地安全。",al={"坦莎·月刃为何在黑海岸","坦莎·月刃的驻地","坦莎·月刃为何在亚米萨兰附近"}},d2f2f0b1={q="哨兵坦莎·月刃想要什么？",a="月刃希望招募有能力的联盟冒险者，揭开萦绕在亚米萨兰废墟中的悲惨历史。她派盟友调查破碎的遗物和记述城市陷落的古老文献，希望厘清真相，让徘徊在荒野中的不安灵魂得以安息。",al={"坦莎·月刃需要什么","坦莎·月刃的任务","坦莎为何需要帮助"}}},fp="24,315,19.509.0,32.213.0,42.126.0,40.207.0,43.123.0"}
P.entries["npc:sentinel-velene-starstrike"] = {n="哨兵维尔莉妮·星坠",s="哨兵维尔莉妮·星坠是一位驻守在灰谷中心地带银风避难所的暗夜精灵卫士。她肩负着保卫避难所以及周边水域的重任，专门对抗如狂暴元素和邪恶施法者等不自然的入侵威胁。她的警惕守护着这片古老的林地，防止腐蚀性的魔法干扰。",h="哨兵维尔莉妮·星坠是一位驻守在灰谷中心地带银风避难所的暗夜精灵卫士。她肩负着保卫避难所以及周边水域的重任，专门对抗如狂暴元素和邪恶施法者等不自然的入侵威胁。她的警惕守护着这片古老的林地，防止腐蚀性的魔法干扰。",kw={"灰谷","元素护腕","法师召唤者","密斯特拉湖","哨兵","银风避难所","星坠","维尔莉妮"},ang={["class:Mage"]="维尔莉妮对那些不负责任的施法者几乎没有耐心，他们的鲁莽召唤会激怒当地元素并污染自然水域。",["faction:Alliance"]="银风避难所在危险的道路上提供了安全保障，哨兵维尔莉妮负责协调当地事务，以确保灰谷中心地带的安全。",["race:NightElf"]="哨兵维尔莉妮体现了哨兵们不知疲倦的奉献精神，她是抵御魔法鲁莽行为的壁垒，致力于维护灰谷的自然和谐。"},sec={{t="银风的守护者",b="哨兵维尔莉妮·星坠驻扎在密斯特拉湖清澈的水域旁，在银风避难所时刻保持着警惕。和遍布灰谷各处的许多暗夜精灵哨兵一样，她的首要职责是维护森林的平衡，并击退针对精灵避难所的威胁。这片宁静的树林是穿越森林腹地的旅行者重要的休息站，因此她的存在对于该地区的日常安全至关重要。"},{t="密斯特拉湖的纷扰",b="银风避难所周边的宁静十分脆弱。维尔莉妮密切监视着密斯特拉湖，那里不稳定的元素之灵和鲁莽的法师召唤者正在破坏荒野的自然韵律。通过她的指引，勇士们被派遣去压制狂暴的水元素，并终结那些干扰土地之灵的鲁莽施法者。"}},faq={{q="哨兵维尔莉妮·星坠位于何处？",a="哨兵维尔莉妮·星坠驻守在银风避难所，这是一处位于灰谷中部、密斯特拉湖东南岸附近的联盟哨所。",al={"维尔莉妮·星坠位置","维尔莉妮在哪里","银风避难所任务发布者"}},{q="维尔莉妮分配了哪些任务？",a="维尔莉妮请求冒险者处理密斯特拉湖周围受到惊扰的灵魂和施法者，派遣他们去从焦躁的元素身上收集护腕，并消灭那些扰动水域的狂暴召唤者。",al={"维尔莉妮·星坠任务","维尔莉妮提供什么任务"}},{q="密斯特拉湖有什么威胁？",a="密斯特拉湖的水域一直受到好斗的水元素的侵扰，这些元素被激怒，并被那些不顾森林脆弱和谐、只顾修炼法术的凡人法师召唤者所利用。",al={"密斯特拉湖的问题","为什么密斯特拉湖有元素"}},{q="维尔莉妮和卡利姆多的其他人有亲属关系吗？",a="她与莱奥·星坠（Layo Starstrike）拥有同一个姓氏，后者是一位驻守在遥远南方、荒凉的希利苏斯的暗夜精灵，这暗示他们属于同一个家族或氏族。",al={"星坠家族","莱奥·星坠亲属"}},{q="什么是银风避难所？",a="银风避难所是一处坐落在灰谷密斯特拉湖畔的宁静的暗夜精灵休憩地。它是哨兵和往来荒野深处的友方旅行者的避风港和战术哨所。",al={"什么是银风避难所","银风避难所背景故事"}},{q="为什么哨兵们关注元素活动？",a="暗夜精灵视荒野为神圣的、充满活力的生态系统。狂暴或被腐蚀的元素会破坏当地的野生动物并污染自然水域，迫使哨兵们介入以恢复平衡。",al={"为什么暗夜精灵要对抗元素","哨兵与元素"}}},fx={["8f53b9bb"]={q="哨兵维尔莉妮·星坠是谁？",a="哨兵维尔莉妮·星坠是一名暗夜精灵守护者，隶属哨兵部队，驻扎在灰谷的银风避难所。她与并肩作战的姐妹们一样，致力于保护卡利姆多的神圣森林，使其免遭腐化和敌人侵扰，并警惕地守望着密斯特拉湖等附近区域。",al={"维尔莉妮是谁","维尔莉妮·星坠背景","哨兵维尔莉妮·星坠是谁"}},["2ad68975"]={q="哨兵维尔莉妮·星坠属于哪一方？",a="哨兵维尔莉妮·星坠忠于暗夜精灵的哨兵部队，坚定地与联盟并肩作战。她会向效力于联盟、愿意协助守护灰谷的旅人提供援助、指引和任务。",al={"维尔莉妮·星坠所属阵营","哨兵维尔莉妮是否效力联盟","维尔莉妮·星坠效忠哪一方"}},["33a0de05"]={q="哨兵维尔莉妮·星坠为何在这里？",a="维尔莉妮驻扎在银风避难所，负责监视荒野并协调灰谷中部的哨兵行动。该地区正面临不断加剧的危险：凶猛的野生动物、密斯特拉湖周围躁动不安的元素生物，以及威胁林地圣洁的外来侵扰。",al={"维尔莉妮为何在银风避难所","维尔莉妮·星坠的职责","维尔莉妮·星坠为何在灰谷"}},["9d94d468"]={q="哨兵维尔莉妮·星坠想要什么？",a="维尔莉妮希望恢复周边荒野的和谐与安宁。她招募有能力的联盟勇士，调查密斯特拉湖令人不安的元素动乱，挫败魔法威胁，并击退任何逼近避难所的敌对势力。",al={"维尔莉妮想要什么","维尔莉妮·星坠的目标","维尔莉妮想做什么"}}},fp="26,346,22.440.0,28.360.0,44.156.0,39.211.0,35.212.0,45.180.0,26.232.0,51.213.0"}
P.entries["npc:serge-hinott"] = {n="瑟尔格·希诺特",s="瑟尔格·希诺特是一位驻扎在希尔斯布莱德丘陵塔伦米尔的被遗忘者炼金师。他与药剂师林度恩密切合作，协助皇家药剂师协会调制药剂、解毒剂以及对被遗忘者战争事业至关重要的试剂。",h="瑟尔格·希诺特是一位驻扎在希尔斯布莱德丘陵塔伦米尔的被遗忘者炼金师。他与药剂师林度恩密切合作，协助皇家药剂师协会调制药剂、解毒剂以及对被遗忘者战争事业至关重要的试剂。",kw={"药剂师林度恩","希尔斯布莱德丘陵","希诺特","皇家药剂师协会","瑟尔格·希诺特","塔伦米尔"},ang={["class:Rogue"]="希诺特协助那些寻求治愈致命赞吉尔之触的潜行者，在常规疗法失效时调制必要的解毒剂。",["race:Undead"]="希诺特代表了皇家药剂师协会在希尔斯布莱德的实践部门，直接为前线的被遗忘者部队提供必要的化学混合剂和支持。"},sec={{t="塔伦米尔的药剂师助手",b="瑟尔格·希诺特位于塔伦米尔加固定居点内，紧邻药剂师林度恩，他在被遗忘者于希尔斯布莱德丘陵的行动中扮演着关键的支援角色。虽然林度恩专注于更广泛的化学研究，以及针对南海镇等邻近人类定居点的侵略性瘟疫研究，但希诺特负责管理专门的酿造任务。他的专长包括准备修复药膏以及现场特工和侦察兵在遭遇危险毒素和中毒意外时所必需的关键解毒剂。"}},faq={{q="哪里可以找到瑟尔格·希诺特？",a="瑟尔格·希诺特驻扎在希尔斯布莱德丘陵中北部地区的塔伦米尔。他站在药剂师林度恩身旁的室外，在酿造用品和炼金设备中忙碌着。",al={"瑟尔格·希诺特位置","希诺特在哪里","寻找瑟尔格·希诺特"}},{q="瑟尔格·希诺特担任什么职务？",a="他是一位服务于塔伦米尔被遗忘者的炼金师。除了协助准备当地的药剂和治疗用品外，他还会在现场行动人员和信使有要求时，帮助调制特殊的混合药剂。",al={"希诺特做什么","瑟尔格·希诺特职责"}},{q="希诺特与药剂师林度恩是什么关系？",a="希诺特在塔伦米尔直接与药剂师林度恩共事，尽管他们之间并没有什么交情：希诺特会告诉那些打扰他的访客去找那位“不可一世的先生”而不是他。",al={"希诺特与林度恩","希诺特与谁共事"}}},fx={ed373d2b={q="瑟尔格·希诺特是谁？",a="瑟尔格·希诺特是一名被遗忘者炼金术士，驻扎在希尔斯布莱德丘陵的塔伦米尔。他与药剂师林度恩密切合作，运用自己调配药剂和疗伤的专长为被遗忘者效力，并以精湛的炼金技艺帮助旅人。",al={"希诺特是谁","瑟尔格·希诺特背景","瑟尔格是谁"}},d070d0a8={q="瑟尔格·希诺特属于哪一方？",a="瑟尔格·希诺特忠于被遗忘者和部落。他驻扎在希尔斯布莱德丘陵这片有争议的边境地区，以炼金术工作支持部落在附近威胁面前的驻守与生存。",al={"希诺特所属阵营","瑟尔格·希诺特是否效力部落","希诺特为谁效力"}},["080bb72f"]={q="瑟尔格·希诺特想要什么？",a="希诺特专注于精进技艺、酿制强效药剂，并向援助被遗忘者的人提供炼金术方面的帮助。他会为需要专门药剂和混合物来抵御该地区毒素与疾病的盟友提供援助。",al={"希诺特的目标","希诺特在做什么","希诺特的职责"}},["10d74ddb"]={q="瑟尔格·希诺特为何在希尔斯布莱德丘陵？",a="希诺特驻扎在塔伦米尔，支援被遗忘者位于希尔斯布莱德丘陵的前哨。作为药剂师林度恩的搭档，他协助在希尔斯布莱德激烈边境冲突阴影下行动的部落勇士。",al={"希诺特为何在塔伦米尔","瑟尔格为何在这里","希诺特驻扎此地的原因"}}},fp="12,261,32.511.0,32.212.0,34.211.0,48.187.0"}
P.entries["npc:shadow-priest-allister"] = {n="暗影牧师奥利斯特",s="暗影牧师奥利斯特是一位驻扎在银松森林瑟伯切尔的被遗忘者牧师。他负责监督该地区的侦察和战术行动，协调各项任务以监视达拉然的法师，并为女妖之王守护洛丹伦的边界。",h="暗影牧师奥利斯特是一位驻扎在银松森林瑟伯切尔的被遗忘者牧师。他负责监督该地区的侦察和战术行动，协调各项任务以监视达拉然的法师，并为女妖之王守护洛丹伦的边界。",kw={"奥利斯特","安伯米尔","达拉然","被遗忘者","圣光胡言","瑟伯切尔","暗影牧师","银松森林"},ang={["class:Priest"]="作为《圣光胡言》的作者，奥利斯特代表了被遗忘者牧师对圣光的幻灭。",["faction:Horde"]="奥利斯特致力于守护银松森林，确保部落盟友能够安全往返于提瑞斯法林地和南部的土地之间。",["race:Undead"]="奥利斯特是“被遗忘者”冷酷实用主义的典范，他背弃了过去的圣教教条，以保护他的人民免受生者的侵害。"},sec={{t="瑟伯切尔的守望者",b="暗影牧师奥利斯特以瑟伯切尔为基地，指挥被遗忘者在整个银松森林的侦察活动。从这座位于墓穴之中的定居点出发，他追踪着附近的各种威胁，从人类叛军和野兽入侵，到围绕达拉然展开的奥术阴谋，无所不包。"},{t="紧盯安伯米尔与达拉然",b="奥利斯特主要担心的还是达拉然的幸存法师，尤其是那些占据安伯米尔并越境刺探的法师。他不愿让肯瑞托在被遗忘者的土地上扎根，因此派遣特工拦截达拉然的信使，破解奥术符文，并探明这些法师的长期图谋。"},{t="异端沉思",b="除了作为前线战略家的职责外，奥利斯特还是一位愤世嫉俗的暗影哲学家。他著有《圣光胡言：圣光不会告诉你的事》——这是一篇抨击传统圣光教义的尖刻论文。书中探讨了亡灵状态的残酷现实，以及圣光是如何抛弃那些被生命所遗弃之人的。这部著作不知何故甚至流传到了卡利姆多的厄运之槌废墟中。"}},faq={{q="暗影牧师奥利斯特是谁？",a="他是一位驻扎在银松森林瑟伯切尔的被遗忘者暗影牧师，负责协调监视行动并打击附近的威胁，尤其是达拉然的部队。",al={"奥利斯特","暗影牧师奥利斯特","银松森林的奥利斯特是谁"}},{q="我在哪里能找到暗影牧师奥利斯特？",a="他住在瑟伯切尔，这是位于银松森林主干道旁的主要被遗忘者定居点。",al={"奥利斯特位置","暗影牧师奥利斯特在哪里","找到奥利斯特"}},{q="奥利斯特为何紧盯达拉然和安伯米尔？",a="驻扎在安伯米尔的肯瑞托法师对被遗忘者的领土构成了持续的威胁。奥利斯特试图破译他们的通讯，揭露他们的意图，并将他们的势力控制在一定范围内。",al={"奥利斯特与达拉然","为什么要攻击安伯米尔","达拉然对银松森林的威胁"}},{q="奥利斯特写了什么书？",a="奥利斯特撰写了《圣光胡言：圣光不会告诉你的事》，这是一篇对圣光毫不客气的尖锐批评，甚至跨越重洋传到了厄运之槌的古老图书馆中。",al={"奥利斯特的书","圣光胡言","圣光不会告诉你的事"}},{q="奥利斯特提供哪些任务？",a="他提供多项围绕银松森林的情报收集任务，包括“边境穿越”、“地图与符文”、“安伯米尔的调查”，以及对抗达拉然特工的任务。",al={"奥利斯特的任务","瑟伯切尔暗影牧师任务"}},{q="奥利斯特为什么练习暗影魔法而不是圣光？",a="像许多在死后感到被圣光抛弃的被遗忘者牧师一样，奥利斯特转向了暗影，并在这一拥抱亡灵存在的法术体系中找到了力量和决心。",al={"为什么是暗影牧师","被遗忘者暗影魔法奥利斯特"}}},fx={bfa3e4a4={q="暗影牧师奥利斯特属于哪一方？",a="奥利斯特对被遗忘者和黑暗女王绝对忠诚。他驻扎在瑟伯切尔的地下墓穴中，一心运用黑暗法术和缜密心思，为亡灵夺取洛丹伦，并消除任何威胁他们脆弱新领地的地区隐患。",al={"奥利斯特所属阵营","暗影牧师奥利斯特为谁效力","奥利斯特是否是被遗忘者"}},["9415cd7f"]={q="暗影牧师奥利斯特为何在银松森林？",a="奥利斯特以瑟伯切尔为据点，密切监视徘徊在南部边境的敌对势力。达拉然法师残部盘踞在安伯米尔，附近又有奇异魔法涌动；他的职责是指挥被遗忘者的行动人员探查敌方防御，并查明他们的真实意图。",al={"奥利斯特为何在瑟伯切尔","奥利斯特在银松森林的职责","暗影牧师奥利斯特为何在这里"}}},fp="22,262,24.282.0,29.332.0,17.407.0,30.172.0,40.123.0,49.198.0,29.191.0,32.183.0,66.194.0"}
P.entries["npc:shadow-priest-sarvis"] = {n="暗影牧师萨维斯",s="暗影牧师萨维斯站在丧钟镇那座废弃的教堂内，是新苏醒的被遗忘者的主要向导之一。他向那些新尸体揭示了他们残酷的现实，并指引他们去清除那些无脑的亡灵，收集有关当地威胁的情报。在希尔瓦娜斯女士的旗帜下，萨维斯不知疲倦地工作，将这些困惑的亡灵塑造为被遗忘者纪律严明的仆从。",h="暗影牧师萨维斯站在丧钟镇那座废弃的教堂内，是新苏醒的被遗忘者的主要向导之一。他向那些新尸体揭示了他们残酷的现实，并指引他们去清除那些无脑的亡灵，收集有关当地威胁的情报。在希尔瓦娜斯女士的旗帜下，萨维斯不知疲倦地工作，将这...",kw={"丧钟镇","被遗忘者","新兵艾尔雷斯","萨维斯","暗影牧师萨维斯","提瑞斯法林地"},ang={["class:Priest"]="萨维斯展现了被遗忘者对暗影魔法的拥抱，在这座失去了圣光的教堂里扮演着黑暗导师的角色。",["race:Undead"]="萨维斯是你从坟墓中苏醒后听到的最初声音之一，他引领你踏上侍奉黑暗女王的道路。"},sec={{t="新苏醒者的牧者",b="在丧钟镇阴暗的教堂内，暗影牧师萨维斯静候着那些刚从坟墓中爬出来的人。被遗忘者灵魂的苏醒是令人震惊且恐怖的过程，许多人会因陷入无脑的狂乱或绝望而立即丧失心智。萨维斯就像是一根定海神针，为新复生者赋予了目标。他指派新兵去清理那些在墓园中游荡的蹒跚且无脑的尸体，并指示他们保卫丧钟镇的边界，抵御天灾军团的侵犯。"},{t="保卫丧钟镇",b="除了让新兵适应环境外，萨维斯还负责监管提瑞斯法林地当地的关键防御，以应对徘徊的威胁。他统筹着对试探丧钟镇周边天灾军团势力的遏制工作。通过引导新手去获取关键情报和进行战斗考验，萨维斯确保了这座城镇始终是被遗忘者的一处坚固堡垒。"}},faq={{q="暗影牧师萨维斯是谁？",a="萨维斯是一位驻扎在丧钟镇的被遗忘者暗影牧师。他指引新苏醒的亡灵，下达最初的指令，并帮助保卫城镇以抵御天灾军团。",al={"萨维斯","萨维斯是谁","丧钟镇牧师"}},{q="我在哪里可以找到暗影牧师萨维斯？",a="他位于提瑞斯法林地中被遗忘者新手区，丧钟镇中心那座废弃的教堂内。",al={"萨维斯位置","萨维斯在哪里","寻找萨维斯"}},{q="为什么萨维斯让玩家去杀死那些无脑的僵尸？",a="并非每一具从坟墓中复生的尸体都能保持自由意志和理智。那些陷入疯狂的个体被视为对定居点的威胁，必须在他们危及到其他亡灵之前将其消灭。",al={"为什么要杀死无脑者","无脑者"}}},fp="20,390,30.491.0,19.340.0,28.176.0,38.114.0,51.201.0"}
P.entries["npc:shael-dryn"] = {n="莎尔蒂恩",s="莎尔蒂恩是一位充满好奇心的树妖，居住在灰谷伊瑞斯湖以东的纯净月亮井旁。她是暗夜精灵侦察兵调查森林腐化时的重要联络人。在协助阿斯特兰纳的哨兵净化圣物以对抗在荒野中蔓延的恶魔和污秽影响方面，她扮演着举足轻重的角色。",h="莎尔蒂恩是一位充满好奇心的树妖，居住在灰谷伊瑞斯湖以东的纯净月亮井旁。她是暗夜精灵侦察兵调查森林腐化时的重要联络人。在协助阿斯特兰纳的哨兵净化圣物以对抗在荒野中蔓延的恶魔和污秽影响方面，她扮演着举足轻重的角色。",kw={"灰谷","塞纳留斯","净化","树妖","伊莉亚娜","莱恩","莱恩林地","莎尔蒂恩"},ang={["class:Druid"]="德鲁伊们会赞赏她与卡利姆多自然之灵的联系，以及她对恢复被黑暗力量扭曲的动植物群的洞察力。",["faction:Alliance"]="纯净月亮井是灰谷的一处避难所，莎尔蒂恩在此协助联盟军队抵御腐化和敌对势力。",["race:NightElf"]="对于卡多雷来说，莎尔蒂恩是一位受欢迎的森林姐妹，她与塞纳留斯之间的自然纽带使她在净化被污染的林地圣物时显得不可或缺。"},sec={{t="月亮井守护者",b="莎尔蒂恩驻守在纯净月亮井旁，与守护森林东部入口的暗夜精灵哨兵一同保持警戒。当当地野生动物出现腐化，或被污染的圣物威胁到土地的和谐时，她深厚的自然造诣能引导冒险者完成恢复精神平衡所需的步骤。"},{t="森林净化",b="莎尔蒂恩与阿斯特兰纳的莱恩·狼行者密切配合。当哨兵寻回被污染的文物，如腐化的发光宝石和达图尔的变形魔棒的碎片时，莎尔蒂恩深谙所需的晦涩仪式、月亮井水和自然信物，能将这些黑暗的奇物转化为联盟强大的净化工具。"}},faq={{q="莎尔蒂恩是谁？",a="莎尔蒂恩是一位居住在灰谷纯净月亮井旁的树妖。她以林地传说和自然魔法援助联盟冒险者，同时也沉溺于她对双关语和笑话的喜爱。",al={"她是谁","莎尔蒂恩传说","莎尔蒂恩身份"}},{q="我在哪里可以找到莎尔蒂恩？",a="你可以在灰谷伊瑞斯湖以东的纯净月亮井旁找到她。",al={"莎尔蒂恩位置","莎尔蒂恩在哪里","莱恩林地树妖"}},{q="莎尔蒂恩与莱恩·狼行者有什么联系？",a="莱恩·狼行者会将冒险者指引至莎尔蒂恩处，因为这位树妖拥有调查并净化在森林各处寻回的腐化宝石和圣物所需的精神知识。",al={"莱恩与莎尔蒂恩","莱恩的净化树妖","为什么要派我去找莎尔蒂恩"}},{q="莎尔蒂恩的外观有什么独特之处？",a="莎尔蒂恩和她的树妖同伴伊莉亚娜拥有罕见的肤色，使她们的模型在卡利姆多各地遇到的其他大多数树妖中显得与众不同。",al={"树妖模型","独特皮肤","莎尔蒂恩颜色"}},{q="莎尔蒂恩对部落友好吗？",a="不。由于她驻守在纯净月亮井旁并与阿斯特兰纳哨兵结盟，莎尔蒂恩对部落成员持敌对态度。",al={"部落能和莎尔蒂恩对话吗","部落声望","莎尔蒂恩只属于联盟吗"}}},fx={["70f31310"]={q="莎尔蒂恩想要什么？",a="莎尔蒂恩正努力保护并净化灰谷周围的森林。她会协助莱恩·狼行者等盟友，指引旅人调查威胁、收集古老的森林遗物，并恢复被腐化土地的平衡。",al={"莎尔蒂恩的目标","莎尔蒂恩在做什么","莎尔蒂恩的职责"}},["3c3b07cb"]={q="莎尔蒂恩为何在净化之月井？",a="莎尔蒂恩身为塞纳留斯的女儿，在伊瑞斯湖以东的净化之月井守望着灰谷东部。她从这座月井监视侵蚀森林的腐化，并协助守卫神圣林地的暗夜精灵。",al={"莎尔蒂恩为何在这里","莎尔蒂恩为何在灰谷","莎尔蒂恩与雷伍德"}}},fp="10,340,24.361.0,25.358.1,18.192.0,28.79.0,52.198.0,45.150.0,36.144.0"}
P.entries["npc:shanda"] = {n="珊达",s="珊达是一位暗夜精灵牧师兼导师，位于幽影谷中奥达希尔的空心树干内。她侍奉于The Sisterhood of Elune，负责指导暗夜精灵牧师新手学习月亮女神的基本祷言、结界和仪式。她的指引帮助刚入行的侍僧在月神之光与保卫泰达希尔的职责之间取得平衡。",h="珊达是一位暗夜精灵牧师兼导师，位于幽影谷中奥达希尔的空心树干内。她侍奉于The Sisterhood of...",kw={"奥达希尔","艾露恩","暗夜精灵","牧师训练师","幽影谷","珊达","艾露恩姐妹会","泰达希尔"},ang={["class:Priest"]="对于在幽影谷开始旅程的暗夜精灵牧师来说，珊达是第一位提供神圣教诲和艾露恩恩典指引的导师。",["race:NightElf"]="珊达代表了The Sisterhood of Elune悠久的传统，照料着卡多雷年轻一代在泰达希尔迈出第一步时的精神福祉。"},sec={{t="月之母的侍僧",b="珊达伫立在奥达希尔宁静的圣所之中，作为致力于侍奉艾露恩的年轻暗夜精灵最早的精神导师之一。当德鲁伊们照料着泰达希尔苏醒的根须与枝桠时，像珊达这样的女祭司确保了卡多雷的精神核心始终与白夫人保持着联系。她教导新入门者如何引导月亮恩典来进行治疗和施展防护结界，为他们面对潜入世界之树枝桠的腐蚀做好准备。"},{t="指引新入门者",b="当年轻的牧师在幽影谷觉醒时，他们会被引荐给珊达，以证明他们的虔诚并学习最初的祷言。通过像“艾露恩的眷顾”这样的仪式，她考验着他们的意志，并授予他们受祝福的徽记和基本的咒语。在她的教导下，学生们学会了作为一名卡多雷女祭司，既要成为伤者温柔的慰藉，也要成为抵御阴影的坚定之盾。"}},faq={{q="珊达是谁？",a="珊达是一位暗夜精灵牧师训练师，位于泰达希尔幽影谷的奥达希尔中心空心树定居点内。她指导刚觉醒的暗夜精灵牧师学习The Sisterhood of Elune的教义。",al={"这个npc是谁","珊达背景故事","奥达希尔牧师训练师"}},{q="珊达对新牧师起什么作用？",a="她向牧师新手介绍基本的祷言、治疗法术以及由艾露恩赋予的防护魔法。新牧师会将他们的神圣符记带给她，她会通过“艾露恩的眷顾”指引他们进行下一阶段的训练。",al={"牧师训练师的作用","珊达教什么","珊达做什么"}},{q="我在哪里可以找到珊达？",a="珊达位于泰达希尔幽影谷作为新手中心的巨大树木——奥达希尔内部的地面层。",al={"珊达在哪里","珊达位置","如何找到珊达"}},{q="珊达属于哪个组织？",a="珊达是The Sisterhood of Elune的成员，这是一个古老的暗夜精灵女祭司宗教团体，数千年来一直指引着卡多雷的精神和文化生活。",al={"珊达阵营","艾露恩姐妹会","珊达是月之女祭司吗"}}},fx={["35bebf44"]={q="珊达想做什么？",a="珊达致力于培养新一代暗夜精灵牧师，使他们侍奉月亮女神并保护族人。她希望引导年轻的见习者运用艾露恩的神圣恩泽，教他们治疗伤势、保护盟友，并消灭在幽影谷逐渐蔓延的腐化。",al={"珊达的目标是什么","珊达的动机","牧师训练师珊达想做什么"}},["44a52b27"]={q="珊达为什么在奥达希尔？",a="新近觉醒的守护者聚集在奥达希尔这片圣地，经验丰富的导师需要磨炼他们尚未成熟的天赋。珊达驻守在幽影谷那棵巨树的树根处，照看新晋的牧师见习者，确保他们在深入泰达希尔之前学会艾露恩的仪式与力量。",al={"珊达为什么在这里","珊达为什么在幽影谷","珊达在此处的原因"}}},fp="6,348,26.491.0,21.422.0,14.218.0,43.231.0,24.150.0,40.176.0"}
P.entries["npc:shandris-feathermoon"] = {n="珊蒂斯·羽月",s="珊蒂斯·羽月是哨兵部队的将军，也是泰兰德·语风一万年来最得力的助手。她目前在菲拉斯海岸外的萨尔多岛上的羽月要塞，指挥着整个卡利姆多的暗夜精灵军队。",h="珊蒂斯·羽月是哨兵部队的将军，也是泰兰德·语风一万年来最得力的助手。她目前在菲拉斯海岸外的萨尔多岛上的羽月要塞，指挥着整个卡利姆多的暗夜精灵军队。",kw={"羽月","菲拉斯","将军","卡多雷","萨尔多岛","哨兵","珊蒂斯","泰兰德"},ang={["class:Hunter"]="猎人和游侠们尊崇珊蒂斯，视其为哨兵部队中最优秀的射手之一，也是一位守护暗夜精灵长达一万年的将军。",["faction:Alliance"]="对于冒险进入卡利姆多南部的联盟军队来说，羽月将军提供了至关重要的海军支持、战略领导，以及位于萨尔多岛上戒备森严的避风港。",["faction:Horde"]="部落将羽月将军视为一位危险而狡猾的军事战术家，她那座位于菲拉斯海岸外的要塞威胁着他们在该地区的扩张。",["race:NightElf"]="对卡多雷而言，羽月将军代表了哨兵部队纪律与职责的巅峰，她从漫长守望岁月伊始便守护着她的人民。"},sec={{t="泰兰德的得力助手",b="珊蒂斯·羽月是暗夜精灵最古老的保卫者之一。一万年来，她一直作为高阶祭司的得力助手，与泰兰德·语风并肩奋战在哨兵部队中，度过了天崩地裂之后那漫长的守望岁月。"},{t="哨兵的崛起",b="在天崩地裂和哨兵部队建立后，珊蒂斯成为了暗夜精灵军队中不可或缺的指挥官。"},{t="菲拉斯的堡垒",b="如今，羽月将军担任哨兵部队的最高战地指挥官。她驻扎在萨尔多岛，统领着宏伟的精灵要塞——羽月要塞，监视着菲拉斯原始荒野的动向。从这座岛屿前哨站出发，她时刻防备着野蛮的豺狼人、盘踞的戈杜尼食人魔、充满仇恨的萨特，以及在卡利姆多南部日益扩张的部落势力的威胁。"}},faq={{q="谁是珊蒂斯·羽月？",a="珊蒂斯·羽月是暗夜精灵常备武装力量——哨兵部队的将军。作为一名古老的暗夜精灵，她担任高阶祭司泰兰德·语风的得力助手已有一万年之久，并在菲拉斯的羽月要塞指挥着哨兵部队。",al={"谁是珊蒂斯","珊蒂斯背景故事","菲拉斯的暗夜精灵将军是谁"}},{q="在哪里可以找到珊蒂斯·羽月？",a="她在羽月要塞指挥作战，该要塞位于卡利姆多南部、菲拉斯西海岸外的萨尔多岛上。",al={"珊蒂斯的位置","珊蒂斯·羽月在哪里","羽月要塞的领袖"}},{q="珊蒂斯与泰兰德·语风是什么关系？",a="一万年来，珊蒂斯一直是泰兰德·语风在哨兵部队中最得力的助手。泰兰德在达纳苏斯领导着暗夜精灵，而珊蒂斯则在羽月要塞指挥着哨兵部队在野外作战。",al={"珊蒂斯是泰兰德的女儿吗","泰兰德与珊蒂斯","泰兰德的养女"}},{q="珊蒂斯是否与燃烧军团战斗过？",a="在此处记载的历史中，没有关于她与燃烧军团战斗的记录。众所周知的是，一万年来她一直作为哨兵部队的一员，在泰兰德·语风身边效力，目前在羽月要塞指挥着哨兵部队。",al={"上古之战中的珊蒂斯","珊蒂斯是否与阿克蒙德战斗过"}},{q="她为什么驻扎在菲拉斯而不是泰达希尔？",a="作为哨兵将军，珊蒂斯必须指挥整个卡利姆多的前线军事行动。羽月要塞是联盟在南部荒野森林中的主要集结地和堡垒，监视着敌对的食人魔、萨特以及部落的动向。",al={"为什么珊蒂斯在菲拉斯","为什么羽月要塞"}}},fp="20,251,20.247.0,21.138.0,22.413.0,28.279.0,40.120.0,55.221.0,46.250.0,54.269.0"}
P.entries["npc:shari-stilwell"] = {n="Shari Stilwell",s="Shari Stilwell 是一位驻扎在提瑞斯法林地布瑞尔定居点的被遗忘者圣骑士训练师。她与东部王国中的多位知名人物拥有相同的姓氏，并指导那些承担起圣光战士职责的被遗忘者。她的存在标志着在女妖之王统御下的亡灵中，一种罕见且非传统的修行方式。",h="Shari Stilwell...",kw={"布瑞尔","被遗忘者","圣光","圣骑士","shari","stilwell","提瑞斯法","训练师"},ang={["class:Paladin"]="对于在提瑞斯法林地开启旅程的被遗忘者圣骑士来说，Shari Stilwell 是他们在布瑞尔的主要训练师和导师。",["race:Undead"]="Shari Stilwell 反映了第三次战争所导致的家庭破碎的悲剧，她作为一名亡灵导师，而她潜在的亲人却远在南方忍受着苦难。"},sec={{t="布瑞尔的一盏明灯",b="Shari Stilwell 位于布瑞尔受瘟疫侵蚀的建筑群中，是引领被遗忘者圣骑士的导师。虽然圣光对亡灵来说极为痛苦，但 Shari 引导着那些忍受此般折磨、踏上圣光之路的初生被遗忘者。她为在提瑞斯法林地寻求立足之地的冒险者提供初期训练和适应指导，并为那些希望在被遗忘者王国中寻求一席之地的人提供指引。"},{t="Stilwell 家族的羁绊",b="Shari 与分布在南部王国的多位活人角色共享家族姓氏，其中包括 Daphne、Merissa 以及著名的铁匠乔丹·斯迪威尔。无论是她在洛丹伦陷落时与这些亲人被迫分离，还是仅仅拥有遥远的血缘关系，这都是天灾军团蹂躏下未曾言说的悲剧。"}},faq={{q="Shari Stilwell 是谁？",a="Shari Stilwell 是一位驻扎在提瑞斯法林地布瑞尔的亡灵圣骑士训练师。她协助被遗忘者圣骑士进行早期的武艺和圣光修行，帮助他们学会如何在洛丹伦生存。",al={"shari stilwell 是谁","shari stilwell 传说","布瑞尔圣骑士训练师"}},{q="去哪里可以找到 Shari Stilwell？",a="她位于布瑞尔镇，就在提瑞斯法林地幽暗城和洛丹伦王城废墟的北边。",al={"shari stilwell 位置","shari stilwell 在哪","寻找 shari stilwell"}},{q="Shari 和乔丹·斯迪威尔有亲戚关系吗？",a="她与著名的铁匠乔丹·斯迪威尔，以及 Daphne 和 Merissa Stilwell 拥有相同的姓氏。他们确切的家庭联系尚未得到证实，但很可能已被摧毁洛丹伦的瘟疫所切断。",al={"与乔丹·斯迪威尔的关系","stilwell 家族纽带","shari stilwell 的亲属"}},{q="被遗忘者能作为圣骑士使用圣光吗？",a="引导圣光对亡灵生物来说极其痛苦，会引起强烈的剧痛和灼烧感。然而，像 Shari Stilwell 这样的训练师会指导意志坚定的被遗忘者，帮助他们建立起掌握武技和圣光力量所需的心理韧性和虔诚。",al={"被遗忘者圣骑士","亡灵如何成为圣骑士","亡灵圣骑士传说"}}},fx={["1254553f"]={q="Shari Stilwell效忠哪一方？",a="Shari Stilwell坚定地支持被遗忘者和部落。她驻扎在布瑞尔，为希尔瓦娜斯·风行者女王的国度效力，指导那些在亡灵之躯中踏上艰难而矛盾的圣骑士之路的被遗忘者。",al={"shari stilwell所属阵营","shari为谁效力","shari stilwell是部落成员吗"}},e32993c8={q="Shari Stilwell为什么在布瑞尔？",a="Shari Stilwell驻扎在布瑞尔，担任提瑞斯法林地新近觉醒的亡灵圣骑士训练师。新手们从丧钟镇醒来，寻求庇护或在第二个家园找到目标，她会确保那些选择圣骑士之道的人接受适当的纪律训练。",al={"shari为什么在布瑞尔","shari stilwell的职责","shari stilwell在这里做什么"}}},fp="14,338,17.419.0,25.324.0,22.197.0,34.111.0,36.213.0,41.267.0"}
P.entries["npc:shelene-rhobart"] = {n="舍伦尼·洛巴尔特",s="舍伦尼·洛巴尔特是一名驻扎在提瑞斯法林地路边的被遗忘者制皮训练师。她在死亡卫士哨站工作，提供熟化兽皮和制皮训练，以支持被遗忘者在这片枯萎之地的军事和后勤工作。",h="舍伦尼·洛巴尔特是一名驻扎在提瑞斯法林地路边的被遗忘者制皮训练师。她在死亡卫士哨站工作，提供熟化兽皮和制皮训练，以支持被遗忘者在这片枯萎之地的军事和后勤工作。",kw={"布瑞尔","hides for the forsaken","制皮","舍伦尼·洛巴尔特","提瑞斯法林地"},ang={["race:Undead"]="舍伦尼代表了被遗忘者工业的务实基础，确保当地的守卫者即便在提瑞斯法的腐朽与荒凉中也能获得适当的装备。"},sec={{t="为被遗忘者制作装备",b="舍伦尼·洛巴尔特在死亡卫士哨站经营她的生意，这是一个位于布瑞尔东南方，沿着通往洛丹伦废墟主干道上的前哨站。即使在死亡之后，实用的工艺对于生存和战争仍然至关重要。舍伦尼使用从提瑞斯法四处游荡的野兽身上收集的毛皮，将其加工成护甲、束带和野外装备，为当地与天灾军团和血色十字军交战的被遗忘者巡逻队提供补给。"}},faq={{q="我能在哪里找到舍伦尼·洛巴尔特？",a="舍伦尼·洛巴尔特驻扎在提瑞斯法林地布瑞尔东南方的一个小型被遗忘者哨站，位于通往幽暗城的道路旁。",al={"舍伦尼·洛巴尔特位置","舍伦尼·洛巴尔特在哪里","舍伦尼·洛巴尔特地图"}},{q="舍伦尼·洛巴尔特扮演什么角色？",a="她是一位技术娴熟的制皮训练师。她教导初出茅庐的制皮匠们处理兽皮、缝制服装以及为被遗忘者组装皮革防护装备的基本知识。",al={"舍伦尼·洛巴尔特做什么","舍伦尼·洛巴尔特训练师","舍伦尼专业"}},{q="她为什么需要野兽毛皮？",a="亡灵的皮肤无法愈合，所以当被遗忘者受伤时，他们必须用动物毛皮进行修补。舍伦尼的库存告急，她需要夜行蝙蝠翼膜、恐狼毛皮和邪鳍鱼人皮，因为不同厚度的皮料适合身体的不同部位。",al={"hides for the forsaken任务","为什么在提瑞斯法收集兽皮"}}},fx={["383979a9"]={q="舍伦尼·洛巴尔特是谁？",a="舍伦尼·洛巴尔特是一名亡灵制皮师，在提瑞斯法林地为被遗忘者效力。和许多同族一样，她保留了生前掌握的手艺与技能，如今传授制皮技艺，并为族人制作必需的物资。",al={"舍伦尼·洛巴尔特的背景","舍伦尼是谁","舍伦尼·洛巴尔特的信息"}},ffb69fef={q="舍伦尼·洛巴尔特效忠哪一方？",a="她坚定地效忠被遗忘者、希尔瓦娜斯·风行者女王以及更广泛的部落。她直接为提瑞斯法的守军和商贩提供支持，助他们守护家园。",al={"舍伦尼·洛巴尔特所属阵营","舍伦尼·洛巴尔特为谁效力","舍伦尼·洛巴尔特效忠谁"}},d546cfcf={q="舍伦尼·洛巴尔特想做什么？",a="舍伦尼希望为被遗忘者的战争行动提供物资，并支援在提瑞斯法林地旅行的人。她需要从当地野兽身上获取坚韧的兽皮，以制作护甲、装备和物资，帮助人们抵御这片土地上的敌人。",al={"舍伦尼想做什么","舍伦尼·洛巴尔特的目标","舍伦尼·洛巴尔特的职责"}},e156f5b6={q="舍伦尼·洛巴尔特为什么在这里？",a="舍伦尼驻扎在布瑞尔东南方的一处亡灵卫兵驿站，以维持提瑞斯法林地要道沿线的前哨。从这里，她协助巡逻斥候，并向途经林地的旅人传授制皮技艺。",al={"舍伦尼为什么在死亡哨岗","舍伦尼·洛巴尔特为什么在这里"}}},fp="15,275,25.447.0,33.145.0,37.188.0,30.281.0"}
P.entries["npc:shenthul"] = {n="申苏尔",s="申苏尔是一名丛林巨魔潜行者训练师，常驻于奥格瑞玛暗影裂口阴暗的地下区域。作为破碎之手的特工，他在卡利姆多各地策划间谍行动，并引导新晋的潜行者加入公会的秘密行列。",h="申苏尔是一名丛林巨魔潜行者训练师，常驻于奥格瑞玛暗影裂口阴暗的地下区域。作为破碎之手的特工，他在卡利姆多各地策划间谍行动，并引导新晋的潜行者加入公会的秘密行列。",kw={"cleft of shadow","丛林巨魔","奥格瑞玛","潜行者训练师","破碎之手","申苏尔","荆棘谷地精","狂风峭壁"},ang={["class:Rogue"]="申苏尔是来到奥格瑞玛的部落潜行者的主要导师和联络人，提供技能训练、入会考验和秘密任务。",["faction:Horde"]="申苏尔在首都地下运作，指挥着守护部落免受内部和外部隐形威胁的情报机构。",["race:Troll"]="作为一名深深扎根于传统兽人组织破碎之手的丛林巨魔，申苏尔展示了暗矛巨魔是如何将自己融入部落最高层间谍活动的。"},sec={{t="深渊之眼",b="申苏尔隐匿在暗影裂口阴森的深处，是部落最顶尖的潜行者导师之一。当上方的战士和萨满在杜隆塔尔的红土地上大张旗鼓地行军时，申苏尔则在训练那些偏爱潜行、伏击和诡计的人。在他的指导下，初学者们掌握了必要的野外生存技巧和致命艺术，学会了如何在卡利姆多残酷的政治环境和严苛的荒野中执行任务。"},{t="破碎之手",b="申苏尔代表着破碎之手，这个组织由古老的兽人氏族转型为部落的情报网络和秘密机构。他将该组织视为覆盖卡利姆多的永恒守望之幕——担任着调查者、法官、陪审团和行刑者的角色。申苏尔以极度务实和不受动荡政治局势影响而著称，他曾有名言提醒外人：破碎之手在萨尔大酋长掌权之前就已经存在，而且在他之后也将长久存续。"},{t="秘密外勤",b="除了基础训练，申苏尔还协调前往争议领土的复杂任务。他派出的特工执行着危险的渗透任务，例如对敌对势力进行深度卧底行动，在狂风峭壁周围的荆棘谷地精补给箱上练习开锁，并通过严格的秘密考验来测试新兵。当他的外勤特工中了毒，申苏尔会确保他们能及时获得解药，以免发生致命后果。"}},faq={{q="申苏尔是谁？",a="申苏尔是一名丛林巨魔潜行者训练师，也是常驻于奥格瑞玛下方暗影裂口的破碎之手特工。",al={"申苏尔的角色","申苏尔是谁","奥格瑞玛巨魔潜行者训练师"}},{q="我在哪里可以找到申苏尔？",a="他位于暗影裂口，这是一个通过奥格瑞玛黑暗隧道进入的地下洞穴群。",al={"申苏尔位置","申苏尔在哪里","申苏尔暗影裂口"}},{q="申苏尔与破碎之手有什么联系？",a="申苏尔是破碎之手的一名忠诚特工兼招募员，这是一个在部落内部运作的秘密情报和刺客公会。",al={"破碎之手申苏尔","申苏尔是破碎之手的吗","申苏尔的阵营"}},{q="申苏尔如何看待萨尔大酋长？",a="申苏尔效忠于部落的技艺和安全，但他坚持认为破碎之手在萨尔之前就已存在，并将在他的统治之后继续存在，他视自己的公会为一种永恒的必要存在。",al={"申苏尔对萨尔的看法","申苏尔喜欢萨尔吗","申苏尔的忠诚"}},{q="申苏尔为潜行者提供什么任务？",a="他引导潜行者完成入会考验，派遣他们执行秘密渗透任务，并指引他们去石爪山脉寻找荆棘谷地精的补给箱以提升开锁技能。",al={"申苏尔任务","申苏尔潜行者任务"}},{q="申苏尔会协助处理潜行者的毒药吗？",a="是的，在潜行者面临致命毒素的关键外勤行动中，申苏尔会指引特工寻找希诺特，以确保他们的生存和持续的外勤工作。",al={"申苏尔毒药任务","希诺特申苏尔协助"}}},fx={["1496428e"]={q="申苏尔效忠哪一方？",a="申苏尔将一切置于碎手氏族之下。虽然该组织在部落的旗帜下于奥格瑞玛活动，但他明确表示，公会听命于自己的权威。正如他对访客所说，碎手氏族在大酋长萨尔之前就已存在，也会在他之后长存。",al={"申苏尔的效忠对象","申苏尔为谁效力","申苏尔效忠萨尔吗"}},["6d75b5d2"]={q="申苏尔想做什么？",a="申苏尔希望将碎手氏族的势力扩展到整个卡利姆多。他设想该组织如同一层无所不在的帷幕，在暗处充当保护者、警察、法官、陪审团和行刑者。为此，他训练有潜力的潜行者，考验他们的机敏与纪律，并派他们执行重要的秘密任务。",al={"申苏尔的目标是什么","申苏尔的动机","申苏尔想做什么"}},f56d6f2e={q="申苏尔为什么在这里？",a="申苏尔在大断崖昏暗的洞窟中安家，招募并训练效力于碎手氏族的新潜行者。远离上城区窥探的目光，他负责监督秘密行动，并考验有志成为特工的人，确保他们掌握为组织效力所需的潜行与欺诈技巧。",al={"申苏尔为什么在奥格瑞玛","申苏尔为什么在大断崖","申苏尔在这里做什么"}}},fp="8,270,17.430.0,18.476.0,16.496.1,16.128.0,26.121.0,52.142.0,44.199.0,44.206.0,40.145.0"}
P.entries["npc:shindrell-swiftfire"] = {n="辛德瑞尔·速火",s="辛德瑞尔·速火是一位暗夜精灵哨兵和斥候，驻扎在阿斯特兰纳——灰谷暗夜精灵行动的核心。她敏锐地察觉到卡利姆多西部的局势变化，并将有能力的联盟冒险者指引至海岸线和附近山口的潜在威胁处。她的职责使她成为协调当地防御、应对新出现的海洋和野外威胁的重要枢纽。",h="辛德瑞尔·速火是一位暗夜精灵哨兵和斥候，驻扎在阿斯特兰纳——灰谷暗夜精灵行动的核心。她敏锐地察觉到卡利姆多西部的局势变化，并将有能力的联盟冒险者指引至海岸线和附近山口的潜在威胁处。她的职责使她成为协调当地防御、应对新出现...",kw={"灰谷","阿斯特兰纳","纳迦","凌风翼龙","哨兵","辛德瑞尔","石爪山脉","速火","佐拉姆海岸"},ang={["class:Hunter"]="她涉及追踪凌风翼龙和评估荒野海岸线的任务，引起了擅长在荒野中生存的斥候和游侠们的共鸣。",["faction:Alliance"]="辛德瑞尔在阿斯特兰纳起到了行动枢纽的作用，引导刚抵达的联盟成员深入卡利姆多中部充满争议与危险的地区。",["race:NightElf"]="对于暗夜精灵来说，辛德瑞尔代表了守护灰谷边缘的警惕哨兵，在主力部队对抗部落的同时，防范像纳迦这样的远古宿敌。"},sec={{t="阿斯特兰纳的守望之眼",b="从阿斯特兰纳蜿蜒的走道上，辛德瑞尔·速火时刻观察着灰谷更广阔的边境。尽管森林哨兵们时刻承受着来自东方和南方的部落伐木入侵的压力，但辛德瑞尔的目光始终锁定在森林前线之外的危险上。她是从黑海岸抵达或前往石爪山脉崎岖山脊的旅者之间重要的联络人，确保阿斯特兰纳不会在侧翼遭遇突如其来的威胁，陷入毫无防备的境地。"},{t="海岸威胁",b="辛德瑞尔最关注的问题之一是位于灰谷西北岸的佐拉姆海岸。突然出现的敌对纳迦从深海爬出，对卡多雷定居点构成了巨大的谜团和直接威胁。通过派遣经验丰富的战士调查海岸线并与前线斥候配合，辛德瑞尔致力于在这些蛇形入侵者在古代暗夜精灵领地上稳住阵脚之前将它们遏制住。"}},faq={{q="我可以在哪里找到辛德瑞尔·速火？",a="辛德瑞尔·速火驻扎在阿斯特兰纳，这是灰谷核心的暗夜精灵城镇。你可以在该定居点的木质走道上找到她，她正在那里协调侦察行动并接待来往旅者。",al={"辛德瑞尔·速火 位置","辛德瑞尔在哪里","寻找辛德瑞尔·速火"}},{q="辛德瑞尔在阿斯特兰纳担任什么角色？",a="她是联盟的斥候协调员和任务发布者，指引冒险者前往威胁灰谷的外在危险处，例如西海岸的纳迦和附近山脉中的野兽。",al={"辛德瑞尔做什么","辛德瑞尔·速火是谁","辛德瑞尔的目标"}},{q="她为什么派遣斥候前往佐拉姆海岸？",a="敌对纳迦已经涌入灰谷西海岸，占据了遗迹并威胁着暗夜精灵的边境。辛德瑞尔指引冒险者侦察海滩，并协助前线哨兵遏制这一蛇形威胁。",al={"为什么要去佐拉姆海岸","辛德瑞尔 纳迦任务","佐拉姆海岸任务"}},{q="辛德瑞尔与石爪山脉有什么联系？",a="塞拉摩的秘密消息来源报告称，兽人刺客在石爪山脉的暗色湖附近收集凌风翼龙的毒液，用于针对联盟的秘密突袭。辛德瑞尔派遣冒险者收集毒囊，以阻止部落获得这些毒药。",al={"石爪山脉任务","凌风翼龙任务","为什么是石爪山脉"}},{q="辛德瑞尔与黑暗深渊有关系吗？",a="没有直接关系。她的任务派遣冒险者对抗佐拉姆海岸的怒尾纳迦，虽然那里是黑暗深渊所在的西北海岸，但她并未派遣任何人进入黑暗深渊副本本身。",al={"辛德瑞尔 黑暗深渊","黑暗深渊连接","辛德瑞尔 bfd"}},{q="凯内斯·静风是谁，辛德瑞尔为什么要提到他？",a="凯内斯·静风是灰谷东部林歌神殿的一位德鲁伊。他担心某种腐蚀正在森林中蔓延，因此向辛德瑞尔索要一份关于海岸及阿斯特兰纳周边情况的报告，辛德瑞尔派遣冒险者将这份报告送交给他。",al={"谁是凯内斯","凯内斯·静风任务","凯内斯连接"}}},fx={["2412c5d9"]={q="辛德瑞尔·速火是谁？",a="辛德瑞尔·速火是一名驻扎在阿斯特兰纳的暗夜精灵，负责协调灰谷的防御，并时刻保持警惕。她在定居点的中心追踪森林边境日益增长的威胁，召集联盟冒险者对抗敌对生物、黑暗教派和威胁暗夜精灵领地的入侵势力。",al={"辛德瑞尔是谁","辛德瑞尔·速火的背景","辛德瑞尔·速火是谁"}},["1fb1d96b"]={q="辛德瑞尔·速火效忠哪一方？",a="辛德瑞尔坚定地支持哨兵暗夜精灵和联盟。她驻扎在阿斯特兰纳的庇护所中，一心守护卡利姆多的神圣森林和族人的安全。",al={"辛德瑞尔所属阵营","辛德瑞尔是联盟成员吗","辛德瑞尔·速火属于哪个阵营"}},["00b2b10b"]={q="辛德瑞尔·速火想做什么？",a="辛德瑞尔希望保护灰谷及其周边地区，抵御日益加剧的危险。她派遣旅人将纳迦赶出佐拉姆海岸，阻止兽人获取石爪山脉的棘翼飞龙毒液，并将她的报告送给林歌神殿的德鲁伊凯尼斯·静风。",al={"辛德瑞尔想做什么","辛德瑞尔·速火的目标","辛德瑞尔的动机"}},["4632c876"]={q="辛德瑞尔·速火为什么在这里？",a="阿斯特兰纳是灰谷暗夜精灵的主要防御枢纽。辛德瑞尔留在这里组织侦察行动，收集远方前哨的报告，并招募沿中央道路经过的能干旅人，协助守护森林边境。",al={"辛德瑞尔为什么在阿斯特兰纳","辛德瑞尔·速火为什么在这里","辛德瑞尔在阿斯特兰纳的职责"}}},fp="19,413,27.509.0,23.464.0,37.201.0,38.218.0,45.221.0,48.261.0,46.202.0,61.269.0"}
P.entries["npc:shoni-the-shilent"] = {n="沉默的舒尼",s="沉默的舒尼是一位勤奋的侏儒工程师，驻扎在暴风城繁华的Dwarven District。作为诺莫瑞根地下突击队的指挥官，她指引联盟冒险者前往死亡矿井，打捞地精伐木机的动力核心，为她希望用来打通重返诺莫瑞根之路的机器提供燃料。",h="沉默的舒尼是一位勤奋的侏儒工程师，驻扎在暴风城繁华的Dwarven...",kw={"死亡矿井","dwarven district","挖掘机","侏儒","陀螺钻","沉默的","舒尼","暴风城"},ang={["profession:Engineering"]="工程学玩家能够领略到陀螺钻挖掘机的纯粹机械复杂性，舒尼希望利用从月溪镇地下打捞上来的伐木机核心为它们提供动力。",["race:Gnome"]="对于侏儒英雄来说，协助舒尼能让他们的族人距离重返诺莫瑞根、收复失落家园的目标更近一步。"},sec={{t="深地指挥官",b="沉默的舒尼在Dwarven District烟雾缭绕的车间里工作，代表了远离诺莫瑞根失落大厅的侏儒战略智慧。她的工程计划雄心勃勃。由于诺莫瑞根落入了石鄂怪手中，沉默的舒尼正在组织一次地下突击以夺回它，并派遣特工进入西部荒野地下的隧道，寻找她的队伍所需的零件。"},{t="地下收复",b="沉默的舒尼的计划依赖于侏儒自己的陀螺钻挖掘机，这是一种重型钻孔机器，旨在突破诺莫瑞根岩石般的地下边界，为侏儒的突击开辟道路。它们缺乏足够的动力，所以她需要从死亡矿井深处一台尚能运作的地精伐木机中获取完整的动力供应——小型高能发动机。后来，她还会派遣冒险者进入诺莫瑞根，拆解其中的机器人，以获取维修其机群所需的备用零件。"}},faq={{q="沉默的舒尼是谁？",a="沉默的舒尼是一位位于暴风城Dwarven District的侏儒任务发布者。她担任诺莫瑞根地下突击队的指挥官，并负责协调地下收复任务。",al={"舒尼是谁","舒尼背景故事","沉默的舒尼npc"}},{q="我可以在哪里找到舒尼？",a="她驻扎在暴风城Dwarven District的铁砧和车间旁，靠近锻造和工程区。",al={"舒尼在哪","舒尼位置","寻找舒尼"}},{q="为什么舒尼对死亡矿井感兴趣？",a="死亡矿井深处有一台尚能运作的地精伐木机。舒尼招募冒险者带回其完整的动力供应，即小型高能发动机，以便她的陀螺钻挖掘机能够突破诺莫瑞根的地下边界。",al={"舒尼死亡矿井","为什么派去死亡矿井","陀螺钻挖掘机任务"}},{q="她为什么被称为“沉默的”？",a="舒尼称号的由来尚不可知。她以指挥诺莫瑞根地下突击队而闻名。",al={"舒尼称号","为什么是“沉默的”","沉默的侏儒"}}},fx={["3c03f847"]={q="沉默的舒尼效忠哪一方？",a="舒尼效忠诺莫瑞根和大联盟。她以暴风城的矮人区为据点，担任诺莫瑞根地下突击队的指挥官，为流离失所的族人统筹专业技术工作。",al={"舒尼所属阵营","舒尼为谁效力","沉默的舒尼是联盟成员吗"}},["0ba3c461"]={q="沉默的舒尼为什么在暴风城？",al={"舒尼为什么在暴风城","舒尼在这里做什么","舒尼的职责"}},["076c3e36"]={q="沉默的舒尼与谁有关联？",a="舒尼指挥诺莫瑞根地下突击队，与侏儒的军队和工程部门保持密切联系。她驻扎在暴风城，与联盟的工程师和士兵紧密协作，努力夺回侏儒的科技遗产。",al={"舒尼的关系","舒尼指挥谁","舒尼的盟友"}}},fp="17,338,21.385.0,24.469.0,25.201.0,23.136.0,41.245.0,32.110.0"}
P.entries["npc:sicco-thermaplugg"] = {n="麦克尼尔·瑟玛普拉格",s="麦克尼尔·瑟玛普拉格是诺莫瑞根废墟的自封统治者，也是侏儒历史上最大的叛徒。他曾是大工匠格尔宾·梅卡托克最信任的首席顾问，却为了篡夺权力，策划了那场导致这座地下城市遭到致命辐射污染的灾难。如今，他已经彻底疯癫并变成了麻风侏儒，正坐在一台巨大的机械作战机甲中统治着这片布满辐射的大厅。",h="麦克尼尔·瑟玛普拉格是诺莫瑞根废墟的自封统治者，也是侏儒历史上最大的叛徒。他曾是大工匠格尔宾·梅卡托克最信任的首席顾问，却为了篡夺权力，策划了那场导致这座地下城市遭到致命辐射污染的灾难。如今，他已经彻底疯癫并变成了麻风侏...",kw={"群体打击者","诺莫瑞根","麻风侏儒","梅卡托克","西斯科","瑟玛普拉格","工匠大厅","穴居人"},ang={["faction:Alliance"]="瑟玛普拉格的背叛使诺莫瑞根无法响应第三次战争的征召，在人类最黑暗的时刻，切断了联盟的补给线和工程支持。",["profession:Engineering"]="瑟玛普拉格代表了草率公式与无原则设计的致命危害，他使用危险的步行战争机器和有毒炸弹投掷器攻击任何进入他工坊的人。",["race:Dwarf"]="你在铁炉堡的同胞为逃离瑟玛普拉格毒气的难民提供了庇护，铁炉堡的卫兵也严密监视着丹莫罗的大门，防止他的受辐射流浪者闯入。",["race:Gnome"]="瑟玛普拉格是你族人所哀悼和鄙夷的一切的化身；他的虚荣和背叛让你失去了家园，并将你的同胞变成了患病的怪物。"},sec={{t="毒性的野心",b="麦克尼尔·瑟玛普拉格曾担任大工匠格尔宾·梅卡托克的首席顾问多年，深得后者的完全信任。但与此同时，瑟玛普拉格却在暗中觊觎着大工匠的职位。究竟是什么最终驱使他背叛了这份信任，是权力还是财富，连梅卡托克也无法断言；大工匠只能感叹，假以时日，瑟玛普拉格本可以拥有这一切。"},{t="诺莫瑞根的投毒",b="在第三次战争期间，当地下穴居人蜂拥而至诺莫瑞根时，侏儒们在阴暗的地下与他们展开了激战。为了寻找破局之法，格尔宾向瑟玛普拉格寻求建议。瑟玛普拉格怂恿他向城市中释放放射性气体，并承诺这既能消灭穴居人，又不会伤及侏儒。事实上，瑟玛普拉格只是利用这次危机作为契机，企图扳倒梅卡托克并夺取权力。"},{t="废墟之王",b="瑟玛普拉格的赌博以灾难性的失败告终。放射性尘埃在城市各层间肆虐失控，屠杀了百分之八十的侏儒人口，并将许多幸存者扭曲成了野蛮、患病的麻风侏儒。瑟玛普拉格不仅没能登上繁荣大都市的宝座，反而自己也因为辐射而扭曲变异。在辐射的折磨下，他彻底疯狂，自封为“侏儒之王”，统治着一个由受辐射的机器和变异爪牙组成的停尸房，并不断与穴居人入侵者以及任何试图收复失地的地表侏儒作战。"}},faq={{q="麦克尼尔·瑟玛普拉格是谁？",a="他是大工匠格尔宾·梅卡托克的前首席顾问，在穴居人入侵期间背叛了自己的同胞。为了篡权，他诱导梅卡托克向诺莫瑞根释放了放射性气体，导致了他们种族的几近灭绝，而他自己则作为疯王统治着这片布满辐射的废墟。",al={"瑟玛普拉格是谁","瑟玛普拉格背景故事","诺莫瑞根的头目是谁","瑟玛普拉格的前因后果"}},{q="瑟玛普拉格为什么要背叛格尔宾·梅卡托克？",a="连梅卡托克也无法肯定。这位大工匠曾对他寄予厚望，并不确定这是为了权力还是财富，毕竟这些东西瑟玛普拉格假以时日终会得到。已知的是，瑟玛普拉格长期以来一直暗中觊觎大工匠的职位，他利用穴居人危机为自己夺取了诺莫瑞根。",al={"他为什么背叛诺莫瑞根","瑟玛普拉格的动机","为什么西斯科痛恨格尔宾"}},{q="瑟玛普拉格导致了穴居人入侵吗？",a="穴居人是在从奥达曼的古代泰坦宝库中被挖掘出来后，才突破进入诺莫瑞根下层的。虽然有传言称瑟玛普拉格事先知晓此次地下入侵，甚至是其推动者以制造危机，但梅卡托克从未证实过瑟玛普拉格究竟是发起了这场入侵，还是仅仅利用了它。",al={"他召唤了穴居人吗","西斯科带来了穴居人吗","诺莫瑞根穴居人入侵起源"}},{q="气体释放后，瑟玛普拉格发生了什么？",a="像其他数以千计在灾难中受害的侏儒一样，瑟玛普拉格暴露在致命的辐射剂量中。辐射使他的血肉枯萎，皮肤变成了病态的绿色，精神也随之崩溃。他没有像其他幸存者那样逃往铁炉堡，而是留了下来，以自封的“侏儒之王”身份统治着这片废墟。",al={"瑟玛普拉格是麻风侏儒吗","他如何变成麻风侏儒的","为什么瑟玛普拉格是绿色的"}},{q="什么是群体打击者9-60型？",a="群体打击者9-60型是一台庞大的侏儒战争机器，它依然在诺莫瑞根的Engineering Labs中横冲直撞，是保卫瑟玛普拉格受辐射领地的众多机械守卫之一。",al={"群体打击者起源"}},{q="大工匠梅卡托克希望如何处置瑟玛普拉格？",a="梅卡托克视瑟玛普拉格为他一生最大的失败和他人民最大的叛徒。在铁炉堡的Tinker Town设立临时大厅后，梅卡托克积极委派勇敢的联盟冒险者深入诺莫瑞根被辐射的深处，除掉瑟玛普拉格，为那些逝者伸张正义。",al={"格尔宾瑟玛普拉格任务","击杀瑟玛普拉格任务","梅卡托克想要他死吗"}}},fx={["83ef33e1"]={q="麦克尼尔·瑟玛普拉格效忠哪一方？",a="瑟玛普拉格只效忠自己和他扭曲的野心。他背叛了联盟和自己的族人，将放射性毒气灌入诺莫瑞根，迫使幸存者流亡。如今，他与外界隔绝，受到辐射的彻底腐化，指挥着仍留在废墟中的麻疯侏儒，像疯狂的暴君一样统治他们，同时与入侵的穴居人以及任何胆敢闯入他领地的外来者交战。",al={"瑟玛普拉格所属阵营","瑟玛普拉格为谁效力","西科·瑟玛普拉格的效忠对象"}},["4bd94cd3"]={q="麦克尼尔·瑟玛普拉格想做什么？",a="瑟玛普拉格想保住自己篡夺的王位。他自封为侏儒之王，在废墟首都深处统治，指挥着麻疯侏儒和残存的机器，拒绝放弃统治，尽管米克托克称他为一无所有之王。",al={"瑟玛普拉格的目标","瑟玛普拉格在谋划什么","西科·瑟玛普拉格的动机"}},["7e175e39"]={q="麦克尼尔·瑟玛普拉格为什么会在这里？",a="灾变期间，瑟玛普拉格夺取了沦陷的城市，因此至今仍待在诺莫瑞根深处的工程区。他没有和幸存的侏儒一起逃往铁炉堡，而是留下来占据空荡的大厅，并统领那些与他一同变异的麻风侏儒。他以Tinkers' Court为据点，继续指挥防御工事、机器和扭曲的追随者，就在这场降临于城市的灾难中心。",al={"瑟玛普拉格为什么在诺莫瑞根","瑟玛普拉格为什么留下","瑟玛普拉格为何身在此处"}},cac8a4d9={q="麦克尼尔·瑟玛普拉格为何声名狼藉、令人畏惧？",a="瑟玛普拉格以侏儒历史上最大的叛徒而臭名昭著。他曾是大工匠梅卡托克备受赞誉的首席顾问，却因背叛直接导致诺莫瑞根遭到辐射，绝大多数居民丧生。侏儒对他的背叛深感惊惧，既害怕他指挥的致命机器，也畏惧如今支配其暴虐统治的彻底疯狂。",al={"瑟玛普拉格为何令人畏惧","瑟玛普拉格的名声","侏儒为什么恨瑟玛普拉格"}}},fp="21,423,16.370.0,27.428.1,17.621.1,29.318.0,46.315.0,41.366.0,56.336.0,32.193.0,61.308.0"}
P.entries["npc:sida"] = {n="塞达",s="塞达是一位住在湿地米奈希尔港的矮人居民。她因与埃纳尔·石钳之间疏远的婚姻关系而为人所知，她终日待在这个港口城镇中，同时也常常在周围的沼泽地里处理一些个人遇到的倒霉事。",h="塞达是一位住在湿地米奈希尔港的矮人居民。她因与埃纳尔·石钳之间疏远的婚姻关系而为人所知，她终日待在这个港口城镇中，同时也常常在周围的沼泽地里处理一些个人遇到的倒霉事。",kw={"埃纳尔·石钳","铁须之墓","米奈希尔港","软泥怪","塞达","湿地"},ang={["faction:Alliance"]="对于抵达米奈希尔港码头的联盟旅行者来说，塞达会提供一些当地的差事，让冒险者前往内陆的铁须之墓。",["race:Dwarf"]="塞达代表了米奈希尔港平民的矮人生活，夹在家庭纠纷和城镇大门外危险的荒野之间。"},sec={{t="一名港口居民",b="塞达住在繁忙的联盟港口米奈希尔港，与她的丈夫埃纳尔·石钳分居两地。他们的关系非常紧张，以至于只要塞达还在城里，埃纳尔就断然拒绝前往米奈希尔。尽管塞达通常都待在这个沿海定居点内，但她偶尔也会冒险进入危险的湿地，最近她在前往铁须之墓的一次探险中，不幸丢失了自己的背包。"}},faq={{q="塞达是谁？",a="塞达是一位住在湿地米奈希尔港的矮人女性。她会给经过该港口的冒险者分派任务。",al={"塞达是谁","塞达npc","塞达湿地"}},{q="塞达的背包发生了什么事？",a="塞达在造访铁须之墓时丢失了她的背包，那是一处坐落在湿地中的古老墓地。此后该地区被肮脏的软泥怪占领，吞没了她的物品。",al={"塞达的背包在哪里","丢失的背包","铁须之墓背包"}},{q="为什么埃纳尔·石钳不愿造访米奈希尔港？",a="埃纳尔·石钳是塞达疏远的丈夫。由于他们之间有嫌隙，只要塞达还住在那里，埃纳尔就完全避开米奈希尔港。",al={"埃纳尔和塞达","塞达的丈夫","埃纳尔·石钳的纠葛"}},{q="在哪里可以找到塞达？",a="可以在湿地西海岸米奈希尔港的码头和道路上找到散步的塞达。",al={"塞达位置","塞达在哪里"}}},fx={["46b5f80b"]={q="塞达属于哪一方？",a="塞达是效忠联盟的铁炉堡矮人。和许多居住在港口城镇米奈希尔港的同族一样，周边危险的沼泽一旦出现麻烦，她便指望旅人和联盟的勇士伸出援手。",al={"塞达的阵营","塞达是联盟的吗","塞达听命于谁"}},["62842a43"]={q="塞达为什么在米奈希尔港？",a="塞达住在米奈希尔港，最近曾向东前往沼泽地探访铁须之墓。那次糟糕的远行中，当地的软泥怪吞掉了她的物品；自那以后，她一直留在镇上，希望有冒险者能去沼泽里找回她丢失的包。",al={"塞达为什么在这里","塞达为何在湿地","塞达为什么在米奈希尔港"}}},fp="4,226,17.454.0,12.124.0,28.178.0,48.152.0,24.108.0"}
P.entries["npc:sirra-von-indi"] = {n="希拉·沃宁迪",s="希拉·沃宁迪是夜色镇的驻镇历史学家，他常驻在镇政厅里，周围堆满了被遗忘的记录。他精通古语言和当地历史，协助镇民解读神秘文档，并揭开暮色森林那黑暗的过去。",h="希拉·沃宁迪是夜色镇的驻镇历史学家，他常驻在镇政厅里，周围堆满了被遗忘的记录。他精通古语言和当地历史，协助镇民解读神秘文档，并揭开暮色森林那黑暗的过去。",kw={"亚伯克隆比","夜色镇","暮色森林","历史学家","摩根·拉迪莫尔","希拉","镇政厅","翻译","沃宁迪","风化墓碑"},ang={["class:Mage"]="造访夜色镇的法师通常很欣赏希拉的学术纪律，因为他对古语言和历史研究的专注与肯瑞托所实践的档案研究不谋而合。",["faction:Alliance"]="希拉代表了夜色镇幸存的公民机构，帮助在一个被黑暗吞噬的省份维护暴风城的遗产。"},sec={{t="镇历史学家",b="希拉·沃宁迪是夜色镇的首要学者，他在Darkshire Town Hall内守护着该定居点的档案。当城镇卫兵专注于潜伏在森林中的迫在眉睫的威胁时，希拉则专注于书面文字，翻译隐晦的文本，并在阴影笼罩该地区之前保护Grand Hamlet那正在消逝的历史。"},{t="解读隐士的文字",b="当镇领导层对居住在暮色森林孤寂山丘上的隐士亚伯克隆比产生怀疑时，希拉受命去翻译这位隐士的神秘笔记。他的语言专长使得议会能够读懂那些看似无害的请求背后的深意，从而理清从闹鬼森林传来的离奇询问。"},{t="往日的悲剧",b="除了常规翻译外，希拉在阐明暮色森林悲伤的历史方面也发挥了关键作用。寻求了解镇墓地中那座神秘的风化墓碑的询问者发现，希拉是少数记得圣骑士摩根·拉迪莫尔悲惨陨落的人之一，他为旅行者提供了让不安的灵魂安息所需的背景信息。"}},faq={{q="希拉·沃宁迪是谁？",a="希拉·沃宁迪是一位人类学者，也是夜色镇的官方历史学家。他每天在Darkshire Town Hall内研究古老技艺、翻译晦涩的语言，并保存着城镇的历史记录。",al={"希拉是谁","希拉·沃宁迪背景故事","夜色镇历史学家"}},{q="在哪里可以找到希拉·沃宁迪？",a="他位于暮色森林中部的夜色镇定居点内的Darkshire Town Hall里。他通常站在书桌和书架旁查阅历史文献。",al={"希拉在哪里","希拉·沃宁迪位置","寻找夜色镇的希拉"}},{q="他在处理亚伯克隆比的笔记时扮演什么角色？",a="当隐士亚伯克隆比的一张奇怪字条传到艾尔罗·埃伯洛克公爵手中，而镇政厅里没有人能读懂它时，希拉运用他的语言技能对其进行翻译，帮助议会理解亚伯克隆比那奇怪的要求。",al={"亚伯克隆比书信翻译员","翻译亚伯克隆比笔记","希拉笔记翻译"}},{q="希拉对摩根·拉迪莫尔了解多少？",a="希拉是夜色镇少数了解埋葬在风化墓碑下的堕落圣骑士摩根·拉迪莫尔全部历史的居民之一。他帮助叙述了拉迪莫尔在第三次战争后陷入疯狂和悲剧的过程。",al={"希拉风化墓碑","摩根·拉迪莫尔背景故事希拉","风化墓碑的故事"}},{q="为什么希拉在翻译时让旅行者等待？",a="解读晦涩的方言和古老的手写体是一项细致的工作。希拉经常要求旅行者给他一点时间，以便他交叉参考资料并完成准确的翻译。",al={"为什么希拉很忙","等待希拉完成","希拉翻译等待"}}},fp="14,268,18.377.0,30.346.1,21.377.1,22.221.0,34.189.0,47.224.0,43.225.0,53.190.0"}
P.entries["npc:sister-aquinne"] = {n="艾奎恩妮",s="艾奎恩妮是一位艾露恩的侍僧，居住在达纳苏斯宁静的神殿花园中。作为一名见习女祭司，她正在Temple of the Moon师从艾露恩祭司组织学习。",h="艾奎恩妮是一位艾露恩的侍僧，居住在达纳苏斯宁静的神殿花园中。作为一名见习女祭司，她正在Temple of the Moon师从艾露恩祭司组织学习。",kw={"艾奎恩妮","达纳苏斯","神殿花园","temple of the moon"},ang={["class:Priest"]="圣光与艾露恩的同僚们能够理解艾奎恩妮的虔诚，她正在接受所有服务于Temple of the Moon的侍僧所必需的基础训练。",["race:NightElf"]="对于抵达达纳苏斯的暗夜精灵冒险者来说，艾奎恩妮是神殿花园中一张友好的面孔，也是接触神殿祭司群体威仪的第一道桥梁。"},sec={{t="达纳苏斯的侍僧",b="艾奎恩妮将自己奉献给了这座暗夜精灵首都的艾露恩祭司组织。她驻守在Temple of the Moon阴影下宁静的神殿花园中，在女祭司长和各位年长姐妹的指导下继续她的学业。当一只曾经伟大的森林生物需要帮助时，正是艾奎恩妮指引热心的旅行者前往神殿内寻找女祭司艾茉拉，以了解必须要做的事情。"}},faq={{q="在哪里可以找到艾奎恩妮？",a="艾奎恩妮站在达纳苏斯的神殿花园中，就在宏伟的Temple of the Moon外。",al={"艾奎恩妮位置","艾奎恩妮在哪里","艾奎恩妮坐标"}},{q="艾奎恩妮的背景是什么？",a="她是艾露恩的一名见习女祭司，在达纳苏斯的Temple of the Moon学习。关于她进入神殿服务之前的生活，人们知之甚少。",al={"艾奎恩妮背景故事","谁是艾奎恩妮","艾奎恩妮背景"}}},fx={f961feee={q="艾奎恩妮修女属于哪一方？",a="艾奎恩妮修女侍奉The Sisterhood of Elune，坚定地与达纳苏斯的暗夜精灵及更广泛的联盟站在一起。她虔诚地信奉月亮女神，在高阶女祭司的指导下，于神殿花园中潜心学习。除了她的神圣教团和族人，她不效忠于任何一方。",al={"艾奎恩妮的阵营","艾奎恩妮修女是联盟的吗","艾奎恩妮修女侍奉谁"}},["5bcdc1db"]={q="艾奎恩妮修女想要什么？",a="艾奎恩妮修女专注于在Temple of the Moon接受新晋女祭司的灵修训练。当一只曾经强大的森林生物需要帮助时，她会派愿意帮忙的旅人去神殿内找女祭司艾茉拉。",al={"艾奎恩妮修女的目标","艾奎恩妮想要什么","艾奎恩妮的动机"}},["119c78e2"]={q="艾奎恩妮修女为什么在达纳苏斯？",a="艾奎恩妮来到首都，是为了追寻自己在The Sisterhood of Elune中的使命。她住在神殿花园宁静的池塘旁；新晋女祭司和女祭司们会在那里冥想并研习艾露恩的教诲。",al={"艾奎恩妮修女为什么在这里","艾奎恩妮为什么在达纳苏斯","艾奎恩妮为什么来到达纳苏斯"}}},fp="14,186,20.435.0,34.115.0,36.153.0"}
P.entries["npc:skorn-whitecloud"] = {n="斯考恩·白云",s="斯考恩·白云是一位年迈的牛头人猎人，居住在莫高雷草海平原的血蹄村。他指导年轻的猎人去理解他们与这片土地上捕食者之间的关系，并帮助那些在莫高雷遭遇潜在危险的旅行者。",h="斯考恩·白云是一位年迈的牛头人猎人，居住在莫高雷草海平原的血蹄村。他指导年轻的猎人去理解他们与这片土地上捕食者之间的关系，并帮助那些在莫高雷遭遇潜在危险的旅行者。",kw={"血蹄村","平原捕食者","莫高雷","斯考恩","牛头人","猎人之道","白云"},ang={["class:Hunter"]="对于年轻的牛头人猎人，斯考恩·白云会提供追踪像平原捕食者这样敏捷的猛兽的初步指导，加强狩猎中的精神和谐。",["race:Tauren"]="斯考恩是牛头人长者的典范，他们将狩猎的荣耀以及在平原上漫长岁月积累的实用智慧传授给莫高雷的年轻人。"},sec={{t="金色平原上的向导",b="斯考恩·白云居住在莫高雷的血蹄村，这位年迈的猎人现在担任狩猎之道的导师。他的主要职责是教导人们尊重平原上的野生生物。他会通过测试来考验有抱负的猎人，让他们去收集莫高雷狡猾的平原捕食者的利爪，并带给雷霆崖的梅洛·石蹄查看，以此确保那些拿起弓箭或长矛的人能够理解捕食者与猎物之间的平衡。"},{t="对反常现象保持警惕",b="除了普通的狩猎职责外，斯考恩还时刻留意着稀树草原上出现的异样。当反常的威胁浮现时——例如平原上的野生动物和野兽身上留下的恶魔腐化迹象——斯考恩会帮助拼凑事件经过，确保莫高雷的部族对潜入他们家园的邪恶势力保持警惕。"}},faq={{q="斯考恩·白云在哪里？",a="斯考恩·白云位于莫高雷南部草原的牛头人定居点——血蹄村。",al={"斯考恩·白云位置","斯考恩在哪里","斯考恩·白云地图"}},{q="斯考恩在年轻猎人中扮演什么角色？",a="斯考恩通过被称为“猎人之道”的仪式传授狩猎的核心原则。他会指派有抱负的猎人去挑战平原上狡猾的平原捕食者，以证明他们的追踪和战斗技巧，然后将他们引荐给雷霆崖的梅洛·石蹄。",al={"斯考恩的工作","斯考恩猎人任务","猎人之道"}},{q="斯考恩出售什么商品？",a="他最珍贵的商品是他自己的武器。由于他的狩猎生涯已经结束，所以他会把自己的一件武器——斯考恩的战锤或斯考恩的火枪——赠送给带回巨狼鬼嚎已被击败证明的猎人。",al={"斯考恩商人","斯考恩出售什么","斯考恩武器"}},{q="斯考恩·白云在莫高雷有其他亲属吗？",a="莫高雷并没有提及斯考恩的亲属。他只是被大家视为血蹄村的一位年迈猎人，他的狩猎生涯已经成为过去。",al={"白云家族","斯考恩亲属"}}},fx={c8bc2edc={q="斯考恩·白云是谁？",a="斯考恩·白云是一位年迈的牛头人猎手，居住在莫高雷草海平原上的血蹄村。他是部族中备受敬重的长者猎手，指导新晋勇士在牛头人领地追踪猎物、狩猎，并尊崇狩猎传统。",al={"斯考恩是谁","斯考恩·白云的背景","斯考恩·白云是谁"}},["3da50b72"]={q="斯考恩·白云属于哪一方？",a="斯考恩效忠雷霆崖的牛头人，坚定地与部落站在一起。他在血蹄村欢迎部落的旅人，并向莫高雷中踏上猎手之路的人传授智慧。",al={"斯考恩·白云的阵营","斯考恩·白云属于联盟还是部落","斯考恩站在哪一方"}},c55728a0={q="斯考恩·白云想要什么？",a="斯考恩希望引导年轻的牛头人走上猎手之道，并让他们与莫高雷的掠食者较量，以检验本领。他会派有前途的猎手追踪危险的猎物，包括狡猾的平原潜伏者，确保他们学会自立，并敬重自己猎杀的野兽。",al={"斯考恩想要什么","斯考恩·白云的任务动机","斯考恩·白云的目的"}},["5990a9e1"]={q="斯考恩·白云为什么在这里？",a="斯考恩住在莫高雷腹地的血蹄村。他的狩猎生涯已成过去，但他仍留在猎物丰足的开阔草原附近，让年轻的追踪者前来赢得在族人中的一席之地。",al={"斯考恩为什么在日歌农场","斯考恩·白云为什么在这里","斯考恩·白云在此处的原因"}}},fp="16,259,28.453.0,31.364.1,36.110.0,44.260.0,27.217.0,59.135.0"}
P.entries["npc:skuerto"] = {n="斯奎尔图",s="斯奎尔图是一名驻扎在阿拉希高地避难谷地的矮人侦察兵。他受大法师马林的派遣，与学徒克里汀一同前往该地，并在实地协助联盟，代表马林回收各种魔法圣物。",h="斯奎尔图是一名驻扎在阿拉希高地避难谷地的矮人侦察兵。他受大法师马林的派遣，与学徒克里汀一同前往该地，并在实地协助联盟，代表马林回收各种魔法圣物。",kw={"阿拉希高地","大法师马林","铁炉堡","避难谷地","侦察兵","斯奎尔图","特雷莱恩"},ang={["race:Dwarf"]="斯奎尔图展现了矮人在联盟荒野前线服役时的坚韧性格，尽管他作为侦察兵的自尊心很容易受到伤害。"},sec={{t="高地上的侦察兵",b="斯奎尔图是来自铁炉堡的一名矮人，他在危险的阿拉希高地担任侦察兵。他与学徒克里汀一同驻扎在避难谷地，在大法师马林的指示下工作，负责回收马林的旧主人大法师特雷莱恩曾经拥有的奥术试剂和强力魔法神器。"},{t="骄傲与危险",b="尽管高地条件艰苦，斯奎尔图却对自己的野外侦察工作感到非常自豪，如果有人质疑他的能力，他会表现得很反感。他的工作经常会面临该地区的各种威胁，从敌对的辛迪加和巨石食人魔，到与这片土地有关的危险远古实体，应有尽有。"}},faq={{q="为什么斯奎尔图驻扎在阿拉希，而不是留在铁炉堡？",a="这是大法师马林派他去的。斯奎尔图和学徒克里汀被派往避难谷地，去收集试剂并回收马林的旧主人大法师特雷莱恩留下的物品，特雷莱恩是在激流堡陷落时逃离此地的。",al={"斯奎尔图为什么在这里","斯奎尔图背景故事"}},{q="斯奎尔图在避难谷地的任务是什么？",a="大法师马林派遣斯奎尔图和学徒克里汀前往阿拉希高地，收集奥术试剂并回收马林的前任主人大法师特雷莱恩曾经拥有的强力魔法神器。",al={"斯奎尔图的任务目的","斯奎尔图做什么","斯奎尔图与马林"}},{q="斯奎尔图在该地区的盟友是谁？",a="他与学徒克里汀直接共事，他是斯奎尔图在大法师马林差事中的搭档；此外，他还与坚守避难谷地的联盟守军共同行动。",al={"斯奎尔图的朋友"}}},fx={["9a7bedf3"]={q="斯奎尔图是谁？",a="斯奎尔图是驻扎在阿拉希高地避难谷地的铁炉堡矮人斥候。他以侦察本领为傲，也格外经不起批评；他代表联盟在野外行动，与学徒克里汀并肩工作。",al={"斯奎尔图是谁","斯奎尔图的身份","矮人斯奎尔图是谁"}},["1cc8a254"]={q="斯奎尔图属于哪一方？",a="斯奎尔图坚定地效忠联盟和铁炉堡。他以避难谷地的联盟营地为据点，与达拉然法师及当地联盟部队协同行动，对抗笼罩阿拉希高地的威胁。",al={"斯奎尔图的阵营","斯奎尔图是联盟的吗","斯奎尔图效忠于谁"}},["5f13d7e3"]={q="斯奎尔图想要什么？",a="斯奎尔图想完成大法师马林交给他的任务：获取魔法试剂，并找回曾属于马林昔日导师、大法师特雷兰的强大失落神器，同时维护自己作为能干斥候的声誉。",al={"斯奎尔图想要什么","斯奎尔图的目标","斯奎尔图的动机"}},["44066d31"]={q="斯奎尔图与谁有关联？",a="除了在大法师马林手下、与学徒克里汀并肩工作，斯奎尔图还与驻守阿拉希高地避难谷地的联盟守军站在一起。",al={"斯奎尔图的关系","斯奎尔图的关联","斯奎尔图认识谁"}}},fp="7,220,24.301.0,15.314.0,56.227.0,43.194.0,39.136.0"}
P.entries["npc:smith-argus"] = {n="铁匠阿古斯",s="铁匠阿古斯是常驻在艾尔文森林闪金镇中心的铁匠和训练师。在他的露天锻造台（靠近Lion's Pride Inn）旁，他为旅行者修理装备，教授新手铁匠基本功，并与艾泽拉斯南部的工匠们保持联系。他的业务网络将闪金镇的本地贸易直接与暴风城等物流中心以及赤脊山等边远地区连接起来。",h="铁匠阿古斯是常驻在艾尔文森林闪金镇中心的铁匠和训练师。在他的露天锻造台（靠近Lion's Pride...",kw={"铁匠","艾尔文森林","锻造","闪金镇","马蹄铁","lion's pride inn","铁匠阿古斯","训练师","弗纳·奥斯古"},ang={["profession:Blacksmithing"]="对于在艾尔文森林开始冒险的联盟角色来说，阿古斯通常是锻造的第一位导师，提供粗糙的铜制装备和基本工具的初始配方。",["profession:Mining"]="矿工将金属带到闪金镇的锻造台，阿古斯就在那里教导有志成为铁匠的人将其制成有用的工具。",["race:Human"]="阿古斯代表了那些辛勤工作的工匠，尽管王国在政治上对该地区关注不足且土匪横行，他们依然维持着艾尔文森林的运转。"},sec={{t="闪金镇的铁砧",b="铁匠阿古斯位于Lion's Pride Inn外，维护着艾尔文森林中最繁忙的铁砧之一。尽管闪金镇正面临附近豺狼人、狗头人和迪菲亚盗贼日益增长的威胁，阿古斯仍能确保当地民兵和路过的冒险者装备精良。除了修补凹陷的护甲和锻造坚固的工具外，他还担任锻造训练师，引导初出茅庐的工匠入门铜制品和青铜制品的加工。"},{t="城镇间的贸易与需求",b="阿古斯并非与世隔绝的乡村铁匠；他的工坊是暴风城王国区域供应链中的重要一环。当邻近定居点的工匠需要专业装备或原材料时，他们会寻求闪金镇的中心位置提供帮助。赤脊山的钉蹄师弗纳·奥斯古依靠阿古斯运送制造好的马蹄铁来维持驮兽和骑兵的机动性，而暴风城Dwarven District的金属工匠也经常通过他协调货物配送。"}},faq={{q="我在哪里可以找到铁匠阿古斯？",a="铁匠阿古斯位于艾尔文森林中心的闪金镇。你可以在护甲店后方设置的室外铁砧和锻造台旁找到他，那里靠近Lion's Pride Inn。",al={"阿古斯位置","铁匠阿古斯在哪里","艾尔文森林的阿古斯"}},{q="铁匠阿古斯提供什么服务？",a="阿古斯向新手铁匠传授锻造的基本功。他的经典称号是中级铁匠。",al={"阿古斯教什么","阿古斯训练师","闪金镇铁匠训练师"}},{q="为什么赤脊山的铁匠要让我去找铁匠阿古斯？",a="弗纳·奥斯古是湖畔镇的一位工匠，由于需要应对黑石兽人的威胁，他急需马蹄铁来维持补给车队和坐骑的机动性。他委托闪金镇的阿古斯锻造并供应必要的铁制马蹄。",al={"马蹄铁任务","弗纳的马蹄铁","为什么需要阿古斯的马蹄铁"}},{q="阿古斯与暴风城有什么联系？",a="阿古斯与暴风城的矮人铁匠协调补给运输，例如Dwarven District的格里曼德·艾尔莫。",al={"艾尔莫的任务","暴风城狮鹫阿古斯"}},{q="铁匠阿古斯能提供高级或专家级的锻造训练吗？",a="阿古斯教授的是锻造的初级阶段；高级技术需要更大的定居点中更有经验的大师来传授。",al={"阿古斯专家级铁匠","阿古斯能训练到多少级"}},{q="铁匠阿古斯属于特定的行会吗？",a="阿古斯是暴风城王国的忠诚臣民，也是服务于艾尔文森林联盟的当地工匠社区的一员。",al={"阿古斯阵营","阿古斯行会"}}},fx={["07d5dba5"]={q="铁匠阿古斯是谁？",a="铁匠阿古斯在闪金镇的熔炉里为暴风王国效力。他是艾尔文森林里可靠的常驻铁匠，为当地守军锻造铁器和钢器，同时训练有志成为工匠的人，并与人类领地各处的同行维持补给往来。",al={"阿古斯是谁","铁匠阿古斯的背景","铁匠阿古斯是谁"}},["79448098"]={q="铁匠阿古斯属于哪一方？",a="铁匠阿古斯效忠暴风王国和联盟。他驻守在繁忙的闪金镇十字路口，与当地工匠密切合作，为暴风城外围的定居点提供物资和防御，以应对日益逼近的威胁。",al={"铁匠阿古斯的阵营","阿古斯属于联盟还是部落","阿古斯为谁效力"}},bbf4c38d={q="铁匠阿古斯为什么在这里？",a="阿古斯经营着闪金镇的重要熔炉，地处连接暴风城、赤脊山和西部荒野的贸易路线上。从这里出发，他能及时为地区哨所提供物资、给马匹钉掌，并指导对王国防务至关重要的新晋铁匠。",al={"阿古斯为什么在闪金镇","是什么让铁匠阿古斯来到这里"}},d8765a7e={q="铁匠阿古斯想要什么？",a="铁匠阿古斯希望熔炉顺利运转，并与赤脊山的弗纳·奥斯古等远方同行保持贸易往来。无论是完成马蹄铁的特殊订单，还是交换技术物资，他都致力于确保王国的定居点装备齐全。",al={"阿古斯的动机","阿古斯需要什么","铁匠阿古斯的目标"}}},fp="11,400,22.452.0,28.472.0,29.174.0,39.107.0,57.228.0,45.116.0,55.124.0,48.137.0"}
P.entries["npc:sneed"] = {n="斯尼德",s="斯尼德是迪菲亚潜行者的地精伐木工头，驻扎在死亡矿井深处。他在被称为Mast Room的伐木舱室中进行作业，驾驶着一台他亲手设计的重型伐木机，为艾德温·范克里夫的秘密战舰加工木材。",h="斯尼德是迪菲亚潜行者的地精伐木工头，驻扎在死亡矿井深处。他在被称为Mast Room的伐木舱室中进行作业，驾驶着一台他亲手设计的重型伐木机，为艾德温·范克里夫的秘密战舰加工木材。",kw={"死亡矿井","艾德温·范克里夫","地精","战舰","伐木工头","mast room","伐木机","斯尼德","斯尼德的伐木机"},ang={["faction:Alliance"]="击败斯尼德可以切断运往铁甲湾的木材供应，这对迪菲亚潜行者的造船计划是一个重大的打击。",["profession:Engineering"]="斯尼德的定制伐木机展示了经典的地精工艺：效率惊人、武装沉重，并且为了最大化生产速度，其性能远远超出了标准的安全性极限。",["race:Gnome"]="造访Mast Room的侏儒会发现斯尼德的机器是典型的地精巧思——吵闹、危险，且在建造时完全不考虑操作员的舒适度或结构的耐用性。"},sec={{t="迪菲亚伐木工头",b="虽然迪菲亚潜行者的核心成员大多是走投无路的石匠工会成员和平民劳工，但建造一艘铁甲战舰需要专业的技艺。艾德温·范克里夫专门招募了斯尼德，看中的就是他精湛的工程学知识和地精那种无情的效率。斯尼德驻扎在地下轨道网络旁的Mast Room，监管着为范克里夫那艘巨型无畏舰加工木材框架所需的伐木、切割和塑形工作。"},{t="工业暴力",b="斯尼德最关心的是削减成本和完成定额，至于后果，他根本不在乎。为了加快进度，他坐在装配有超大号圆锯的定制伐木机里指挥现场。这台致命的机器能在几秒钟内将原木变成造船用的木料。如果被入侵者逼入绝境，斯尼德会依靠机甲的装甲来碾压敌人，但如果机器损坏，他也非常乐意爬出残骸，用拳头与敌人肉搏。"}},faq={{q="斯尼德是谁？",a="斯尼德是一位地精工程师兼伐木工头，受雇于艾德温·范克里夫。他的任务是监管死亡矿井内部的木材加工，以建造迪菲亚战舰。",al={"斯尼德是谁","斯尼德背景故事","斯尼德是什么"}},{q="在哪里可以找到斯尼德？",a="斯尼德位于Mast Room，这是一个位于月溪镇下方死亡矿井内部矿道沿线的工业伐木场舱室。",al={"斯尼德位置","哪里可以找到斯尼德","斯尼德房间"}},{q="为什么会有地精为迪菲亚潜行者工作？",a="艾德温·范克里夫需要专业的工业知识和快速产出来建造他的秘密战舰。他雇佣了像斯尼德这样的地精雇佣兵，只要酬劳丰厚，他们根本不在乎政治或道德问题。",al={"为什么斯尼德会加入迪菲亚","死亡矿井里的地精","为什么迪菲亚要雇佣地精"}},{q="斯尼德在战斗中驾驶的是什么？",a="斯尼德驾驶着斯尼德的伐木机，这是一台笨重、装配有锯子的双足机械采伐机，是他自己制造的，用于以惊人的速度采伐和切割木材。",al={"斯尼德的机器人","斯尼德的机甲","斯尼德的伐木机"}},{q="他的伐木机被摧毁后会发生什么？",a="摧毁伐木机并不能结束战斗。斯尼德会从冒烟的机器残骸中弹出，继续在地面上与入侵者正面交战。",al={"斯尼德第二阶段","斯尼德离开伐木机","斯尼德和伐木机会一起死吗"}},{q="斯尼德加工木材是为了什么？",a="在斯尼德的舱室中切割出的木材会被运往铁甲湾，迪菲亚潜行者正在那里组装一艘巨大的战舰，意图向暴风城反击。",al={"为什么斯尼德要砍木头","mast room的用途","死亡矿井的木材"}}},fx={a403ba53={q="斯尼德属于哪一方？",a="斯尼德明确为艾德温·范克里夫和迪菲亚潜行者效力。地精通常是只受利益驱使的中立商人，而斯尼德则是范克里夫麾下专职的伐木主管。他负责监督迪菲亚潜行者在死亡矿井深处秘密进行的工业伐木，并将自己的工程本领和冷酷效率投入到对抗暴风城的行动中。",al={"斯尼德的阵营","斯尼德为谁效力","斯尼德是迪菲亚潜行者吗"}},["9b5b74a3"]={q="斯尼德想要什么？",a="斯尼德的目标很简单：以尽可能低的成本、尽可能快地建造迪菲亚潜行者的巨舰。他因办事冷酷高效而受雇，日夜不停地经营伐木作业，驾驶定制的伐木机采伐木材，确保兄弟会秘密战舰的建造不会延误，也不会造成不必要的浪费。",al={"斯尼德的目标","斯尼德想做什么","斯尼德的动机"}},e888ebfc={q="斯尼德为什么在死亡矿井？",a="斯尼德驻守在死亡矿井的 Mast Room，为迪菲亚潜行者的大型舰船提供所需的重型木材。他在地下伐木场作业，驾驶伐木机清理、加工木料，备好构成巨舰骨架的粗大木梁。",al={"斯尼德为何在死亡矿井","斯尼德在死亡矿井的目的","斯尼德为何在 mast room"}},["5de8a7f0"]={q="斯尼德与谁有关联？",a="斯尼德直接向迪菲亚潜行者的首领艾德温·范克里夫汇报。范克里夫雇用了这名地精工程师，负责监督洞穴系统内的木材作业，并将斯尼德及其机械纳入迪菲亚的整体指挥体系，与拉克佐和基尔尼格等人并肩效力。",al={"斯尼德向谁汇报","斯尼德与艾德温·范克里夫","斯尼德与迪菲亚的关系"}}},fp="5,251,23.454.0,20.486.0,13.178.0,25.141.0,51.212.0,33.153.0,44.154.0,34.178.0"}
P.entries["npc:sneed-s-shredder"] = {n="斯尼德的伐木机",s="斯尼德的伐木机是一台位于死亡矿井深处，令人望而生畏的机械伐木装置。这台致命的机器由地精工头斯尼德驾驶，它既是艾德温·范克里夫的造船工匠们所用的重型工业机械，也是一台恐怖的防御设施。",h="斯尼德的伐木机是一台位于死亡矿井深处，令人望而生畏的机械伐木装置。这台致命的机器由地精工头斯尼德驾驶，它既是艾德温·范克里夫的造船工匠们所用的重型工业机械，也是一台恐怖的防御设施。",kw={"圆锯","死亡矿井","迪菲亚","地精","木材","遥控器","伐木机","斯尼德","范克里夫"},ang={["faction:Alliance"]="除掉斯尼德和他的机器，将重创支持艾德温·范克里夫秘密战争舰队的木材加工行动。",["profession:Engineering"]="这台伐木机是地精机械设计的经典杰作，尽管它仍然容易受到侏儒通用遥控器的干扰。",["race:Gnome"]="诺莫瑞根地下突击队的沉默的舒尼想要这台地精制造的怪物的动力供应装置，来驱动那些能够重新开启通往诺莫瑞根之路的钻头。"},sec={{t="工业恐怖",b="在死亡矿井地精控制的铸造厂内，机械伐木机有着双重用途：加工艾德温·范克里夫那艘秘密巨舰所需的大量木材，并作为抵御入侵者的装甲冲击引擎。负责伐木作业的工头斯尼德亲自操纵着这头改良的机械野兽，将一台超大型圆锯变成了防御的利器。"},{t="致命的驾驶舱",b="击败这台机器并不意味着威胁的终结。斯尼德蜷缩在旋转刀片上方开放式的驾驶舱内，依靠厚重的铁板和令人胆寒的轰鸣声驱散敌人。即使机器发生故障，伐木机在一阵火花中瘫痪，斯尼德也会从冒烟的残骸中跳出来，战斗到最后一刻。"}},faq={{q="斯尼德的伐木机在死亡矿井中有什么用途？",a="迪菲亚潜行者非常依赖地精机械来开凿地下岩石，并加工建造他们秘密巨舰所需的大量木材。斯尼德使用这台伐木机来加工木材，并以残暴的手段管理地下作业。",al={"为什么死亡矿井里有伐木机","死亡矿井伐木机的目的"}},{q="伐木机被摧毁后会发生什么？",a="当伐木机遭受严重的机械故障时，斯尼德本人会从残骸中幸存下来。这位地精驾驶员会直接从损毁的载具中钻出来，挥舞着自己的武器，以极强的韧性攻击入侵者。",al={"斯尼德会随伐木机一起死亡吗","斯尼德的伐木机第二阶段"}},{q="为什么迪菲亚潜行者拥有地精科技？",a="艾德温·范克里夫雇佣了地精工程师、工匠和雇佣劳工，来监管西部荒野地下的复杂机械作业，包括蒸汽动力锻炉、火炮铸造厂和木材加工厂。",al={"迪菲亚地精","为什么地精在死亡矿井"}},{q="工程师可以破解或控制这台伐木机吗？",a="携带侏儒通用遥控器的聪明发明家可以短暂覆盖伐木机的控制系统，暂时从斯尼德手中夺取这台机器的控制权。",al={"控制斯尼德的伐木机","侏儒通用遥控器斯尼德"}},{q="斯尼德的伐木机携带什么贵重物品吗？",a="是的。它那完好无损的动力供应装置——小型高能发动机，是身在暴风城的沉默的舒尼所寻求的，她需要它来驱动侏儒们的钻地挖掘机，以夺回诺莫瑞根。",al={"斯尼德的伐木机任务物品","斯尼德的伐木机掉落什么"}},{q="是谁在驾驶这台伐木机？",a="这台机器由斯尼德指挥，他是一位经验丰富的地精主管，负责指导死亡矿井深处的伐木和木工运作。",al={"谁驾驶斯尼德的伐木机","斯尼德驾驶员"}}},fx={a3f5b00d={q="斯尼德的伐木机属于哪一方？",a="这头机械巨兽为迪菲亚潜行者而战。地精工程师常常为出价最高的人充当中立雇佣兵，但斯尼德和他那台装甲伐木机坚定地效忠于月溪镇地下的艾德温·范克里夫。",al={"斯尼德的伐木机所属阵营","斯尼德效忠于谁","斯尼德的伐木机属于迪菲亚吗"}},b57110af={q="斯尼德想用他的伐木机做什么？",a="斯尼德驾驶着一座装有飞旋锯片的行走伐木场，决意把任何闯入者锯成细碎木片。除了加工木材、守卫地下作业场所，他最想做的就是把打扰迪菲亚据点的你变成新鲜锯末。",al={"斯尼德的目标","斯尼德想要什么","斯尼德的伐木机用途"}},faf23f8c={q="斯尼德的伐木机为什么在死亡矿井？",a="建造地下帝国需要大量工程支援、木材和重型防御力量。斯尼德的伐木机驻扎在死亡矿井堆满木材的洞穴中，为兄弟会的秘密计划采伐木料，并将擅闯的联盟特工碾成碎屑。",al={"斯尼德的伐木机为何在这里","斯尼德为何在死亡矿井","伐木机在死亡矿井的位置"}},["0d282aa3"]={q="斯尼德的伐木机为何令人畏惧？",a="除了巨大的轰鸣锯片，这台机械恐怖造物还会让入侵者惊恐万分。斯尼德常常让它发出骇人的轰隆声和刺耳的金属尖啸，吓得冒险者夺路而逃，径直撞进等候已久的迪菲亚地精手中。",al={"斯尼德的伐木机为何可怕","斯尼德的伐木机名声","斯尼德的伐木机如何吓人"}}},fp="16,266,17.397.0,16.336.0,51.272.0,44.224.0,53.197.0,54.166.0,46.197.0,24.139.0"}
P.entries["npc:solm-hargrin"] = {n="索姆·哈格林",s="索姆·哈格林是驻扎在寒脊山谷安威玛尔的潜行者训练师。作为一名讲求实用的矮人，他崇尚盗贼之间的荣誉，并向矮人和侏儒新兵传授隐秘行事的艺术。他坚信，随着艾泽拉斯各地地缘政治紧张局势的升温，这些隐秘行动者将发挥至关重要的作用。",h="索姆·哈格林是驻扎在寒脊山谷安威玛尔的潜行者训练师。作为一名讲求实用的矮人，他崇尚盗贼之间的荣誉，并向矮人和侏儒新兵传授隐秘行事的艺术。他坚信，随着艾泽拉斯各地地缘政治紧张局势的升温，这些隐秘行动者将发挥至关重要的作用。",kw={"安威玛尔","寒脊山谷","丹莫罗","密文备忘录","密文符文","潜行者训练师","索姆·哈格林"},ang={["class:Rogue"]="对于刚踏入阴影的矮人和侏儒来说，索姆·哈格林提供了基础训练，并负责为你解读最初的公会指令。",["race:Dwarf"]="索姆代表了一条不那么传统的矮人道路，证明了潜行、狡诈和悄无声息的利刃在丹莫罗同样拥有一席之地，与重甲和战斧一样重要。"},sec={{t="暗影中的导师",b="索姆·哈格林藏身于安威玛尔的矮人据点中，以敏锐而精明的目光注视着寒脊山谷的雪径。虽然铁炉堡主要依靠登山者和战士的蛮力，但哈格林深知某些威胁需要更安静、更锋利的手段来解决。他欢迎矮人和侏儒出身的潜行者学徒，为他们解读密文，并教授他们诸如剔骨等基本技巧。最重要的是，哈格林坚持盗贼之间职业忠诚和荣誉的信条，为他的学生们应对这个动荡不安的世界做好准备，在这里，暗藏的匕首往往能左右国家的命运。"}},faq={{q="索姆·哈格林是谁？",a="索姆·哈格林是一位矮人潜行者训练师，位于丹莫罗寒脊山谷的初始哨站安威玛尔。他引导年轻的矮人和侏儒掌握窃贼、潜行和刀剑技巧等隐秘艺术。",al={"索姆是谁","索姆·哈格林背景故事","安威玛尔潜行者训练师"}},{q="索姆·哈格林对潜行者的职业理念是什么？",a="哈格林坚信“盗贼之间的荣誉”。他教导新兵，尽管他们所用的方法可能不光彩，但对职业和同伴的忠诚是至关重要的，尤其是在敌对势力间脆弱的和平岌岌可危的时候。",al={"索姆的信仰","盗贼之间的荣誉","索姆的观点"}},{q="索姆·哈格林提供或接收哪些任务？",a="新手矮人潜行者会带着密文符文去找他，而新入行的侏儒潜行者则会递交一份密文备忘录。一旦他解读了这些入门指令，他就会指派学员在野外磨练进攻战术。",al={"索姆的任务","密文符文 索姆","密文备忘录 索姆"}},{q="索姆·哈格林是否训练除矮人以外的种族？",a="是的。诺莫瑞根陷落后，侏儒难民与矮人们共享寒脊山谷的起始区域。索姆很乐意将侏儒特工收于麾下，与他的矮人同胞一同训练。",al={"侏儒可以在索姆那里训练吗","安威玛尔侏儒潜行者训练师"}}},fx={["3b6a2fc5"]={q="索姆·哈格林属于哪一方？",a="索姆·哈格林效忠于铁炉堡和联盟。他驻守在寒脊山谷，训练新晋行动人员保卫矮人领地，并坚信在政治局势日益动荡之际，暗影技艺是守护王国不可或缺的手段。",al={"索姆·哈格林的阵营","索姆·哈格林效忠谁","索姆·哈格林是联盟成员吗"}},["7da5d6e5"]={q="索姆·哈格林想要什么？",a="哈格林希望教导有前途的新盗贼掌握潜行、精准和个人荣誉的基本准则。眼见世界各地局势日益紧张，他相信精于隐秘技艺的人很快就会发挥重要作用，因此希望自己的学生得到充分磨炼并严守纪律。",al={"索姆·哈格林的目标","索姆·哈格林想要什么","索姆·哈格林的动机"}},d84d95b0={q="索姆·哈格林为什么在寒脊山谷？",a="他驻守在安威玛尔，指导刚抵达并踏上暗影之路的冒险者。作为一名训练师，他会检查秘密联络人送来的加密信件，并引导年轻的矮人和侏儒学习无声战斗的技艺。",al={"索姆·哈格林为何在这里","索姆·哈格林在安威玛尔的职责","索姆·哈格林为何在安威玛尔"}}},fp="12,316,23.652.0,20.211.0,48.247.0,49.235.0,49.194.0"}
P.entries["npc:sprite-darter"] = {n="小精龙",s="小精龙是生活在菲拉斯繁茂树冠中的小型、闪着虹光的精灵龙。它们因其与生俱来的灵性和魔法特质而受到尊崇，在古树之间优雅地飞舞。最近，这些稀有生物成为了当地企图捕捉并利用它们的恐怖图腾牛头人的目标。",h="小精龙是生活在菲拉斯繁茂树冠中的小型、闪着虹光的精灵龙。它们因其与生俱来的灵性和魔法特质而受到尊崇，在古树之间优雅地飞舞。最近，这些稀有生物成为了当地企图捕捉并利用它们的恐怖图腾牛头人的目标。",kw={"精龙的蛋","精灵龙","菲拉斯","恐怖图腾","辛达尔·月纹","穆塞克","小精龙","巫医尤克里"},ang={["class:Druid"]="德鲁伊将精灵龙视为自然之灵的近亲，对其深感敬重，并认为粗鲁的偷猎者对它们的捕捉是对森林平衡的严重破坏。",["faction:Alliance"]="辛达尔·月纹的盟友们在菲拉斯集结起来帮助被俘的幼龙，挫败了充满敌意的恐怖图腾部族不断扩张的魔爪。",["faction:Horde"]="像莫沙彻营地的巫医尤克里这样的巨魔通灵师，将小精龙视为采集精神“穆塞克”并利用菲拉斯古老本质的最佳目标。",["race:NightElf"]="暗夜精灵尊奉神圣的精灵龙为森林的天然守护者，因此将小精龙从恐怖图腾手中解放出来被视为一种生态责任。"},sec={{t="野外精灵龙",b="小精龙是生活在菲拉斯古老森林中的难以捉摸的带翼林地野兽。它们以闪烁着虹光的翅膀和神秘的精神本质为特征，体现了卡利姆多深林中奇幻而狂野的魔法生态。虽然它们通常温顺害羞，但其天生对魔法力量的抗性和自然之力，使得它们在那些与荒野调和的人眼中十分重要。"},{t="恐怖图腾的囚笼",b="最近，隐居的小精龙面临着前所未有的威胁。居住在菲拉斯的极具侵略性的恐怖图腾牛头人部族开始大规模地围捕并囚禁这些稀有生物，目的不明。心忧此事的暗夜精灵，如辛达尔·月纹，正在积极招募盟友去破坏那些笼子，在恐怖图腾将这些幼龙驯服前解放它们。"},{t="精神层面的关注",b="除了暗夜精灵保护它们的努力外，小精龙也引起了研究原始力量的外来者的注意。在莫沙彻营地活动的巨魔通灵师巫医尤克里对小精龙体内蕴含的自然能量和“穆塞克”十分感兴趣，他试图获取它们的本质，以解开在整个菲拉斯繁荣发展的独特魔法之谜。"}},faq={{q="什么是小精龙？",a="小精龙是栖息在菲拉斯荒野中的小型精灵龙。它们以闪烁的翅膀、与自然的联系以及难以捉摸的魔法行为而闻名。",al={"小精龙信息","什么是小精龙","小精龙是龙吗"}},{q="为什么恐怖图腾牛头人要捕捉它们？",a="具体原因尚不清楚，但恐怖图腾部族一直在森林各处用网大量捕获并囚禁小精龙，很可能是为了利用它们稀有的精神和魔法特质。",al={"为什么恐怖图腾要造笼子","恐怖图腾与小精龙","为什么小精龙被关起来"}},{q="谁在试图保护小精龙？",a="生活在菲拉斯的暗夜精灵辛达尔·月纹正在积极保护它们，她派遣富有同情心的冒险者去砸碎恐怖图腾的笼子，营救被俘的小精龙。",al={"谁在保护小精龙","辛达尔·月纹与小精龙","联盟小精龙任务"}},{q="为什么巫医尤克里对小精龙感兴趣？",a="巫医尤克里研究菲拉斯的原始精神力量。他寻找小精龙的本质，即穆塞克，以了解更多关于该地区固有魔法野生动物的信息。",al={"巫医尤克里小精龙","尤克里的小精龙任务"}},{q="可以饲养小精龙吗？",a="那些协助辛达尔·月纹释放被俘幼龙并保卫巢穴的人，最终可能会被托付一枚稀有的精龙的蛋，以供饲养和保护。",al={"精龙的蛋","小精龙宠物","我能获得一只小精龙吗"}},{q="小精龙有敌意吗？",a="野生的小精龙通常对旅行者胆小而温顺，但和所有野生生物一样，如果受到威胁或挑衅，它们会利用爆发出的自然魔法进行自卫。",al={"小精龙危险吗","小精龙会攻击人吗"}}},fp="13,309,26.410.0,19.404.0,18.365.0,24.182.0,44.209.0,44.169.0,56.188.0,30.170.1,27.185.0"}
P.entries["npc:sprite-jumpsprocket"] = {n="斯普莱特",s="斯普莱特是一位侏儒工程学学徒，目前居住在暴风城繁忙的Dwarven District。和许多在诺莫瑞根陷落后寻求庇护的侏儒一样，她与其他的工匠们一起追求技术和创新。她的存在突显了矮人和侏儒工匠们组成的繁荣社区，他们为这座首都城市源源不断地供应着齿轮、小装置和机械专业知识。",h="斯普莱特是一位侏儒工程学学徒，目前居住在暴风城繁忙的Dwarven...",kw={"学徒","dwarven district","工程师","侏儒","斯普莱特","暴风城","工匠"},ang={["faction:Alliance"]="她在Dwarven District的工作展现了人类、矮人和侏儒之间为支持首都基础设施而进行的日常合作。",["profession:Engineering"]="对于初出茅庐的工匠们来说，斯普莱特是暴风城中最具工业气息的区域里，一位钻研齿轮、铜管和易爆混合物的同道学子。",["race:Gnome"]="斯普莱特是诺莫瑞根流亡者坚韧不拔的象征，即使远离失落的家园，也依然延续着他们对工艺和机械造诣的热爱。"},sec={{t="暴风城的工匠",b="在Dwarven District那布满煤灰的街道和熙熙攘攘的工作间里，侏儒和矮人们肩并肩地锻造金属并设计复杂的装置。斯普莱特在这一充满活力的中心担任工程学学徒。融入了王国的首都之后，像斯普莱特这样的学徒工匠们在经验丰富的大师指导下磨练手艺，为联盟的日常机械和科技奇迹贡献着他们富有创造力的头脑。"},{t="流亡中的侏儒创造力",b="在诺莫瑞根遭遇毁灭性的失败后，流离失所的侏儒散布在联盟的各片领土上，带去了他们独有的工匠、化学和机械天赋。在暴风城，侏儒们在Dwarven District找到了一个受欢迎的避难所，那里有着充足的高炉和工作台。斯普莱特代表了这种坚韧、目光长远的品质——尽管族人面临困境，她依然决心掌握复杂的工程学这门学科。"}},faq={{q="谁是斯普莱特？",a="斯普莱特是一位女性侏儒工程学学徒，在暴风城的Dwarven District生活和工作。",al={"斯普莱特","谁是斯普莱特","斯普莱特背景故事"}},{q="我在哪里能找到斯普莱特？",a="她位于暴风城的Dwarven District，周围环绕着各种工作间、铁砧和志同道合的工程学爱好者。",al={"斯普莱特位置","斯普莱特在哪里","找到斯普莱特"}},{q="她在暴风城担任什么角色？",a="斯普莱特是一名工程学学徒。她代表了在联盟首都磨练其创新手艺的侏儒工匠群体。",al={"斯普莱特角色","她做什么的","斯普莱特的目的"}},{q="为什么像斯普莱特这样的侏儒会住在暴风城？",a="在诺莫瑞根遭遇灾难性陷落后，许多侏儒在铁炉堡和各个人类领土，尤其是暴风城向他们的矮人表亲寻求庇护，他们的工业创造力在那里有着巨大的需求。",al={"为什么侏儒在暴风城","dwarven district的侏儒","侏儒难民"}},{q="斯普莱特与任何著名的任务有关联吗？",a="斯普莱特在Dwarven District当地的社区中扮演着微不足道的角色，主要作为该区工程学社区的一员出现。",al={"斯普莱特任务","关于斯普莱特的任务"}},{q="她与西部荒野有联系吗？",a="虽然有时记录会将其归类在南部王国的周边记录中，但斯普莱特稳稳地驻扎在暴风城的Dwarven District，尽管整个地区的工程作品经常采用侏儒设计。",al={"斯普莱特 西部荒野","西部荒野工程师"}}},fx={b9758f03={q="斯普莱特属于哪一方？",a="斯普莱特坚定地支持联盟和诺莫瑞根流亡者。诺莫瑞根陷落后，许多流离失所的侏儒投奔矮人亲族和人类盟友，她也与他们一样，在暴风城繁忙的 Dwarven District 谋生，运用工程技术为王国和联盟同胞效力。",al={"斯普莱特的阵营","斯普莱特属于联盟还是部落","斯普莱特效忠于谁"}}},fp="19,421,21.472.0,26.482.0,27.123.0,37.128.0,38.145.0,47.218.0,50.141.0,32.219.0"}
P.entries["npc:sputtervalve"] = {n="斯布特瓦夫",s="斯布特瓦夫是一位压力巨大的地精工程师，驻扎在棘齿城的港口城镇。他效力于里德沃克斯主管领导下的技师工会，负责监督该地区的伐木机研发工作，并面临着严苛的企业截止日期。为了保住自己的地位，他经常雇佣冒险者对竞争对手荆棘谷地精进行工业间谍活动。",h="斯布特瓦夫是一位压力巨大的地精工程师，驻扎在棘齿城的港口城镇。他效力于里德沃克斯主管领导下的技师工会，负责监督该地区的伐木机研发工作，并面临着严苛的企业截止日期。为了保住自己的地位，他经常雇佣冒险者对竞争对手荆棘谷地精进...",kw={"棘齿城","里德沃克斯","萨莫芬奇","伐木机","淤泥沼泽","斯布特瓦夫","技师工会","荆棘谷地精","维兹尔克朗"},ang={["faction:Horde"]="尽管棘齿城保持中立，但斯布特瓦夫非常依赖穿越贫瘠之地的部落旅行者来破坏荆棘谷地精的行动并走私机械零件。",["profession:Engineering"]="斯布特瓦夫代表了地精工程学冷酷的理念：当创新停滞时，就从最近的竞争对手那里偷窃图纸。"},sec={{t="工业压力",b="斯布特瓦夫在棘齿城工作，听命于技师工会的里德沃克斯主管。他被委派负责伐木机的研发工作，很快就发现要跟上现代机械化的步伐是一项极其艰巨的工作。面对激烈的竞争和毫不留情的最后期限，斯布特瓦夫发现自己几乎拿不出什么可行的原型机。与其向工会承认失败，他转向了地精一贯的解决办法：从那些率先制造出成品的人那里窃取更先进的设计。"},{t="盯上荆棘谷地精",b="斯布特瓦夫的主要目标是荆棘谷地精在西北方向的淤泥沼泽进行的钻探作业。他们最新的伐木机型号拥有可互换的手臂、改良的操纵杆以及像难以捉摸的萨莫芬奇这样的先进内部机械装置。为了破解这些秘密，斯布特瓦夫派遣了他的助手维兹尔克朗深入沼泽进行“实地考察”，结果该特工被困在里面，迫使斯布特瓦夫不得不雇佣游荡的雇佣兵来找回被盗的技术并营救他的同伴。"},{t="棘齿城的中间人",b="除了伐木机的困境之外，斯布特瓦夫还是穿过贫瘠之地的各种奇异物品的联络点。当冒险者从哀嚎洞穴中带出奇怪的、受腐蚀影响的文物（例如发光的碎片）时，斯布特瓦夫对当地的地貌有着足够的了解，可以将他们指引向别处，让他们远离那些小玩意，转而去找驻扎在洞穴上方的那群隐居的德鲁伊。"}},faq={{q="谁是斯布特瓦夫？",a="斯布特瓦夫是一名隶属于棘齿城技师工会的地精工程师。里德沃克斯主管委派他负责伐木机的研发工作，这让他必须在严苛的企业截止日期前拼命拿出成果。",al={"谁是斯布特瓦夫","斯布特瓦夫 棘齿城","斯布特瓦夫背景故事"}},{q="为什么斯布特瓦夫要针对荆棘谷地精？",a="荆棘谷地精在淤泥沼泽开发了尖端的伐木机，具有可互换的手臂和卓越的操纵杆。由于无法通过正当手段超越他们的设计，斯布特瓦夫只能诉诸企业间谍活动来“借用”他们的蓝图和机械装置。",al={"为什么攻击荆棘谷地精","斯布特瓦夫 淤泥沼泽","斯布特瓦夫 荆棘谷地精"}},{q="什么是萨莫芬奇？",a="萨莫芬奇是一种复杂的机械部件，存在于荆棘谷地精的伐木机和控制台内。斯布特瓦夫雇佣冒险者去提取并检查它，希望能借此掌握他们的技术。",al={"什么是萨莫芬奇","萨莫芬奇任务","萨莫芬奇有什么用"}},{q="谁是维兹尔克朗？",a="维兹尔克朗是斯布特瓦夫派往淤泥沼泽去窃取伐木机原型的特工兼助手。当他被困在其中一台机器内时，他的任务就失败了，需要有人护送他出来。",al={"维兹尔克朗","谁是维兹尔克朗","斯布特瓦夫的伙伴"}},{q="为什么斯布特瓦夫关心发光的碎片？",a="他自己并不研究有机奇物，但由于他对贫瘠之地很熟悉，使他成为了一个理想的联系人。当看到从哀嚎洞穴中找回的碎片时，他会指引冒险者前往洞穴上方山丘上的德鲁伊那里。",al={"发光的碎片 斯布特瓦夫","发光的碎片 哀嚎洞穴","碎片任务 棘齿城"}},{q="谁是里德沃克斯主管？",a="里德沃克斯主管是技师工会的高层领导，他任命斯布特瓦夫负责伐木机的创新工作，并要求他遵守严格且毫不留情的生产时间表。",al={"里德沃克斯","里德沃克斯主管","技师工会老板"}}},fx={["8cc08011"]={q="斯布特瓦夫属于哪一方？",a="斯布特瓦夫听命于技师工会，在中立的地精港口棘齿城活动。他对各类旅人都保持中立，但其主要效忠对象和商业利益严格限于地精事业及工会上级，而非部落或联盟。",al={"斯布特瓦夫的阵营","斯布特瓦夫为谁工作","斯布特瓦夫属于部落吗"}},a7196ac5={q="斯布特瓦夫想要什么？",a="斯布特瓦夫急需赶上谜底主管下达的工程期限。他自己的伐木机设计陷入停滞，因此想偷取设计图和零件，尤其是淤泥沼泽荆棘谷地精所用的优良型号，以挽救研究成果并保住工作。",al={"斯布特瓦夫想做什么","斯布特瓦夫的目标","斯布特瓦夫的伐木机计划"}},a4a50e43={q="斯布特瓦夫为什么在棘齿城？",al={"斯布特瓦夫为何在这里","斯布特瓦夫为何在贫瘠之地","斯布特瓦夫在棘齿城的位置"}},dc6c348a={q="斯布特瓦夫与谁有关联？",a="斯布特瓦夫直接向技师工会的谜底主管汇报。在外行动时，他与搭档维兹克兰克密切合作，曾派对方潜入淤泥沼泽窃取荆棘谷地精的原型机；他还依靠愿意帮忙的冒险者联络贫瘠之地的当地线人。",al={"斯布特瓦夫的人脉","斯布特瓦夫认识谁","斯布特瓦夫的搭档"}}},fp="12,348,19.475.0,27.515.0,18.389.0,20.244.0,50.265.0,22.208.0,19.214.1,51.246.0,26.185.0"}
P.entries["npc:sten-stoutarm"] = {n="斯登·粗臂",s="斯登·粗臂是一名务实的矮人装备商兼信使，驻扎在寒脊山谷的安威玛尔外。他负责确保新兵拥有装备并管理当地的派送工作，帮助新晋登山者在恶劣的山区条件下保持温暖、吃饱肚子并获取信息。",h="斯登·粗臂是一名务实的矮人装备商兼信使，驻扎在寒脊山谷的安威玛尔外。他负责确保新兵拥有装备并管理当地的派送工作，帮助新晋登山者在恶劣的山区条件下保持温暖、吃饱肚子并获取信息。",kw={"安威玛尔","寒脊山谷","丹莫罗","邮件","装备商","斯登","粗臂","穴居人"},ang={["faction:Alliance"]="保持通过寒脊山小径的通讯对于铁炉堡的训练场至关重要，而斯登的邮件网络使山谷与更广阔的联盟保持着联系。",["race:Dwarf"]="斯登体现了丹莫罗务实好客的传统，在将族人送入雪地之前，确保他们身上穿着厚皮甲并吃饱了肚子。",["race:Gnome"]="随着侏儒难民在安威玛尔与矮人一同训练，斯登以同样的务实态度对待他们，派遣他们送邮件并为他们配备应对恶劣环境的装备。"},sec={{t="雪中的援“手”",b="斯登·粗臂位于寒脊山谷的中心附近，是新来的矮人和侏儒新兵在安威玛尔旅店外见到的第一张友好面孔。由于山谷被冬季暴风雪和日益逼近的危险所隔绝，斯登主动承担起为绿色学徒提供结实装备的职责，以免他们被冻僵或毫无准备地闯入风雪中。"},{t="保持通讯畅通",b="除了利用当地的狼皮制作冬季装备外，斯登还担任寒脊山谷的非正式邮政管理员。他负责处理通过危险的寒脊山小径传递的信件，并将官方符文、备忘录和命令分发给整个盆地的职业训练师，确保新手战士、牧师和法师们尽管受到封锁隧道的穴居人阻碍，依然能得到他们的指引。"}},faq={{q="斯登·粗臂是谁？",a="斯登·粗臂是一名驻扎在寒脊山谷安威玛尔外的矮人装备商兼信使。他通过提供保暖衣物和委派当地的邮件投递任务来协助新兵。",al={"斯登·粗臂","斯登是谁","安威玛尔邮差"}},{q="他在寒脊山谷扮演什么角色？",a="斯登既是安威玛尔的军需官，也是信使联络人。他收集狼肉和兽皮等当地资源来制作学徒的防护装备，同时还在山谷中分发信件和训练备忘录。",al={"斯登的工作","斯登做什么","斯登的角色"}},{q="为什么斯登需要投递邮件？",a="由于寒脊山小径受到穴居人和冬季天气的威胁，邮件和补给很难流入山谷。一旦信件送达，斯登就会依靠可靠的新手将包裹和信件送给塔林·锐眼等居民。",al={"为什么寒脊山谷需要邮件投递","斯登邮件","寒脊山谷邮件投递"}},{q="斯登对山谷里的穴居人怎么看？",a="斯登对这些肆虐周围山丘的害虫持有一种疲惫且不以为然的态度，他有一句名言：一旦你看过一个穴居人，你就等于看过它们所有人了。",al={"斯登穴居人","穴居人名言","斯登谈论穴居人"}},{q="他为什么要索要硬狼肉？",a="斯登用耐用、保暖的手套与过往的冒险者交换硬狼肉，这不仅有助于维持山谷守卫的体力，还能在面对丹莫罗刺骨严寒时为他们提供装备。",al={"矮人装备商任务","硬狼肉任务","斯登硬狼肉"}},{q="斯登给新冒险者的符文和备忘录是什么？",a="它们是从铁炉堡和丹莫罗各处的上级那里寄来的密封信件和训练凭证，指示年轻学徒向安威玛尔内部各自的职业训练师报到。",al={"神圣符文","简易备忘录","斯登笔记"}}},fx={be997a27={q="斯登·粗臂属于哪一方？",a="斯登·粗臂是铁炉堡忠诚的矮人，坚定地支持联盟。他驻守在寒脊山谷的安威玛尔，协助当地训练场运作，并确保新到的矮人和侏儒新兵获得保卫山谷所需的补给和命令。",al={"斯登·粗臂的阵营","斯登·粗臂效忠于谁","斯登·粗臂与联盟"}},["9084afa8"]={q="斯登·粗臂想要什么？",a="斯登希望在危机四伏的寒脊山谷维持后勤顺畅。山谷正受到穴居人和野兽的侵扰，他需要能干的新兵从山口运送重要邮件、收集狼肉以制作耐用的皮革匠手套，并将书面命令送到各自的职业训练师手中。",al={"斯登想要什么","斯登·粗臂的目标","斯登为何需要帮助"}},d8d60996={q="斯登·粗臂为什么在寒脊山谷？",a="斯登驻守在安威玛尔，担任寒脊山谷的重要协调员和邮差。连接山谷与丹莫罗其他地区的山口危险重重、怪物横行，因此需要有人驻守当地，引导来往信件和传令、为新手守卫配备物资，并将消息转交给安威玛尔的教官。",al={"斯登为何在这里","斯登·粗臂为何在寒脊山谷","斯登·粗臂驻扎此处的原因"}}},fp="13,292,26.364.0,22.403.0,21.189.0,43.240.0,34.244.0,52.160.0,30.185.0,63.192.0"}
P.entries["npc:stitches"] = {n="缝合怪",s="缝合怪是一个巨大的、由尸块拼凑而成的亡灵憎恶，它一直在暮色森林四处游荡，散布恐惧。这个怪物会在暮色森林西部边缘生成，随后沿着大路无情地向夜色镇进发，屠杀毫无防备的旅人，并摧毁守夜人的各个哨点。",h="缝合怪是一个巨大的、由尸块拼凑而成的亡灵憎恶，它一直在暮色森林四处游荡，散布恐惧。这个怪物会在暮色森林西部边缘生成，随后沿着大路无情地向夜色镇进发，屠杀毫无防备的旅人，并摧毁守夜人的各个哨点。",kw={"憎恶","夜色镇","艾尔罗·埃伯洛克","守夜人","乌鸦岭","缝合怪"},ang={["class:Paladin"]="作为死灵法术和亵渎血肉工艺的怪诞产物，缝合怪代表了一切圣光必须净化的邪恶。",["faction:Alliance"]="缝合怪对夜色镇饱受困扰的居民构成了灾难性的威胁，它将暮色森林的大路变成了一道对联盟新兵而言致命的防线。"},sec={{t="大路上的恐怖",b="缝合怪是一个通过收集尸体并施以邪恶巫术而组装起来的亡灵憎恶。这头行动迟缓的怪物出现在乌鸦岭墓地东北方的亚伯克隆比小屋附近，随即沿着道路径直向东方的夜色镇走去。缝合怪拥有强大的力量和无尽的恶意，它会撕碎沿途所有驻扎的守夜人哨点——包括沃古尔食人魔山对面的防御营地，以及烂果园外的哨所——对毫无防备的旅人和城镇守卫展开无情的屠杀。"},{t="缝合师扭曲的复仇",b="缝合怪并非偶然出现在暮色森林，它是被蓄意制造出来的复仇工具。亚伯克隆比在路人眼中只是一个无害的隐士，但他却对夜色镇的镇长艾尔罗·埃伯洛克公爵怀恨在心。他利用不明真相的冒险者，让他们在毫无察觉的情况下收集各种神秘的试剂、工具和材料，最终完成了他那恐怖的造物。他将缝合怪作为一份“礼物”送往夜色镇，意在摧毁该镇的防御并惩罚埃伯洛克公爵。"}},faq={{q="谁制造了缝合怪？",a="缝合怪是暮色森林中死灵法术的产物。查明是谁制造了它，是乌鸦岭附近亡灵谜团的一部分。",al={"缝合怪制造者","谁制造了缝合怪","亚伯克隆比 缝合怪"}},{q="为什么缝合怪要向夜色镇进军？",a="缝合怪沿着暮色森林的大路向城镇推进，攻击守夜人以及沿途的任何目标。他发动攻击背后的原因将在当地的调查中揭晓。",al={"为什么缝合怪要袭击夜色镇","缝合怪的攻击目标","缝合怪行进路线"}},{q="守夜人能独自阻止缝合怪吗？",a="不能。如果放任不管，缝合怪会轻易地压制并屠戮掉沃古尔食人魔山和烂果园外的守夜人哨点，然后抵达夜色镇的大门。必须依靠协同的民兵防御和路过的冒险者才能将其击倒。",al={"守卫对阵缝合怪","守夜人能否击败缝合怪","夜色镇卫兵能杀死缝合怪吗"}},{q="缝合怪在哪里生成？",a="缝合怪在乌鸦岭墓地东北方道路旁的亚伯克隆比小屋后生成，随后开始它漫长而致命的向东进军，横穿整个暮色森林。",al={"缝合怪在哪里生成","缝合怪位置","缝合怪起点"}}},fx={c18e0cb4={q="斯蒂奇想要什么？",a="作为没有心智的亡灵造物，斯蒂奇没有自己的复杂欲望。他服从亚伯克隆比灌注在他重生肉体中的指令：不停地向夜色镇进军，屠杀所有挡路的人，并向镇子复仇，让鲜血偿还血债。",al={"斯蒂奇想要什么","斯蒂奇的目标","斯蒂奇的目的"}},["3c61022e"]={q="斯蒂奇与谁有关？",a="斯蒂奇与殡葬师亚伯克隆比关系密切，是亚伯克隆比将他拼凑起来；他也与艾尔罗·埃伯洛克公爵有关，这头怪物原本是为送给公爵的一份恶意“礼物”。那些在暮色森林中帮亚伯克隆比跑腿、以为事情无害的冒险者，也在不知情的情况下参与了他的创造。",al={"斯蒂奇的关系","斯蒂奇与谁有关","斯蒂奇和亚伯克隆比"}},f85c8148={q="斯蒂奇为何如此令人畏惧？",a="斯蒂奇之所以是可怕的威胁，在于他蛮横而惊人的力量。他比普通人高大得多，也远比暮色森林中游荡的野兽或低阶亡灵强壮，轻易便能击倒奉命在主路上阻拦他的夜色镇守夜人巡逻队。",al={"斯蒂奇为何令人畏惧","斯蒂奇危险吗","斯蒂奇为何闻名"}},["66b85146"]={q="缝合怪是谁？",a="缝合怪是一个庞大而可怖的亡灵憎恶，由隐士巫妖亚伯克隆比用搜集来的尸体部件拼凑而成。他在乌鸦岭附近秘密将其缝合起来，把它打造为复仇的工具，准备让它沿路直扑夜色镇并将那里夷为平地。",al={"缝合怪是谁","缝合怪是什么","缝合怪的背景故事"}},["74b258bc"]={q="缝合怪属于哪一方？",a="缝合怪只听命于创造者亚伯克隆比。它不效忠于天灾军团或任何大型势力，而是完全充当这名疯狂隐士的私人武器，用来向艾尔罗·埃伯洛克公爵和夜色镇居民泄愤。",al={"缝合怪的阵营","缝合怪是天灾军团成员吗","缝合怪效忠于谁"}}},fp="8,273,27.569.0,30.523.1,21.146.2,42.185.2,47.258.0,26.167.1"}
P.entries["npc:strahad-farsan"] = {n="斯坦哈德·法尔杉",s="斯坦哈德·法尔杉是一位人类术士大师，居住在贫瘠之地俯瞰棘齿城的一座隐蔽石塔中。他在各阵营间享有盛誉，游离于联盟和部落的传统政治之外，训练有抱负的召唤者掌握奴役高等恶魔的危险技艺。无论是来自暴风城、奥格瑞玛还是幽暗城的邪能魔法修习者，都会寻求他的严苛指点。",h="斯坦哈德·法尔杉是一位人类术士大师，居住在贫瘠之地俯瞰棘齿城的一座隐蔽石塔中。他在各阵营间享有盛誉，游离于联盟和部落的传统政治之外，训练有抱负的召唤者掌握奴役高等恶魔的危险技艺。无论是来自暴风城、奥格瑞玛还是幽暗城的邪能...",kw={"贫瘠之地","秘教","法尔杉","地狱犬","加科因","棘齿城","斯坦哈德","召唤者","术士"},ang={["class:Warlock"]="斯坦哈德是中级召唤者的关键导师，引导你完成奴役地狱犬和从虚空召唤战马所需的磨难仪式。",["faction:Alliance"]="在Slaughtered Lamb地穴中黑暗缚灵者加科因的指引下，联盟术士们远赴卡利姆多，专门向斯坦哈德求学。",["faction:Horde"]="尽管是联盟出生的人类，但在棘齿城中立的庇护下，斯坦哈德仍乐于与部落的施法者进行交流。",["race:Human"]="斯坦哈德表明，当人类黑暗艺术大师寻求更强大的力量时，他们的活动范围远超暴风城王国。"},sec={{t="棘齿城之上的高塔",b="斯坦哈德·法尔杉的塔楼坐落在地精港口棘齿城上方的峭壁之上，远离下方繁忙的贸易码头。棘齿城的中立地位让斯坦哈德得以自由地进行危险的恶魔召唤仪式，避开了联盟法官或部落萨满的窥探。他在侍从们的簇拥下，在这相对隐秘的地方钻研扭曲虚空的更深层奥秘，而不受琐碎领土纷争的打扰。"},{t="恶魔奴役大师",b="斯坦哈德通过亲身的生死经历赢得了令人敬畏的声望。在第一次奴役地狱犬时，他险些丧命——这段经历使他在对学徒的要求上既极度谨慎又毫不妥协。尽管他拥有人类血统，但他赢得了艾泽拉斯各地暗影人物的尊重，其中包括暴风城的黑暗缚灵者加科因，以及幽暗城和奥格瑞玛的恶魔学者。任何旗帜下想要驾驭地狱犬或烈焰战马这类狂暴生物的术士，最终都会被指引到他的门前。"}},faq={{q="谁是斯坦哈德·法尔杉？",a="斯坦哈德·法尔杉是一位成就卓著的人类术士和大师级训练师，居住在棘齿城上方的一座石塔中。他是著名的暴风城术士黑暗缚灵者加科因核心圈子的一员，但他精湛的恶魔召唤技艺使他成为了受联盟和部落术士共同推崇的权威。",al={"斯坦哈德背景故事","谁是斯坦哈德","斯坦哈德·法尔杉信息"}},{q="为什么一位人类术士会住在贫瘠之地？",a="棘齿城是由热砂港运营的中立港口，为黑暗施法者提供了一个理想的避风港。住在峭壁上让斯坦哈德能够远离联盟的法律限制和部落的严密监视，潜心进行危险的召唤仪式实验。",al={"为什么斯坦哈德在棘齿城","贫瘠之地的人类","斯坦哈德位置"}},{q="为什么部落术士要拜访斯坦哈德？",a="斯坦哈德对恶魔实体的掌控超越了阵营的界限。奥格瑞玛和幽暗城的导师们认可他在奴役复杂恶魔（例如地狱犬）方面的专长，并会将他们最有前途的学生送过海洋，向他直接学习。",al={"部落拜访斯坦哈德","部落能与斯坦哈德交谈吗","为什么兽人去找斯坦哈德"}},{q="斯坦哈德在召唤第一只地狱犬时发生了什么？",a="当斯坦哈德首次尝试奴役地狱犬时，仪式几乎让他丢了性命。他在那次对抗中死里逃生，这次经历让他明白了想要征服这种以魔法为食的掠食者，必须具备冷酷而精确的手段。",al={"斯坦哈德地狱犬遭遇","斯坦哈德地狱犬背景"}},{q="斯坦哈德和高德瑞克·法杉有亲戚关系吗？",a="他们拥有罕见的姓氏法杉，这强烈暗示了他们之间存在家族联系，但斯坦哈德完全专注于他的黑暗技艺，从未透露过任何关于他家族关系的信息。",al={"高德瑞克·法杉联系","高德瑞克·法杉亲戚","斯坦哈德和高德瑞克有关吗"}},{q="在他的塔楼周围有哪些侍从？",a="斯坦哈德监管着几位忠诚的侍从，包括Magaz、Fenrick和Wytula。他们协助他维护防护结界、准备复杂的召唤法阵，并处理塔楼中进行的繁重仪式。",al={"斯坦哈德的侍从","棘齿城塔楼中的侍从"}}},fx={b2638750={q="斯坦哈德·法尔杉站在哪一方？",a="斯坦哈德始终严格中立，不参与联盟与部落的政治纷争。他住在棘齿城的地精港口上方，与两个阵营的施法者一视同仁地打交道。他效忠于黑暗法术及其同道，而非暴风城或奥格瑞玛的旗帜。",al={"斯坦哈德·法尔杉的阵营","斯坦哈德属于联盟还是部落","斯坦哈德的效忠对象"}},["62896d38"]={q="斯坦哈德·法尔杉想要什么？",a="斯坦哈德致力于拓展恶魔召唤的边界，并考验同道的本领。他考验并指导那些想要掌握地狱猎犬等强大存在的野心术士，确保他们有决心和知识去束缚那些曾险些夺走他性命的生物。",al={"斯坦哈德想要什么","斯坦哈德·法尔杉的目标","斯坦哈德的动机"}},a370ddda={q="斯坦哈德·法尔杉与谁有关？",a="斯坦哈德是黑暗缚灵者加科因核心圈子中的重要成员，与世界各地精通暗影之术的同道保持密切联系。在棘齿城上方的高塔里，他照看自己的侍僧——Magaz、Fenrick和Wytula，同时训练由铁炉堡、暴风城、奥格瑞玛和幽暗城的导师送来的有前途的召唤师。",al={"斯坦哈德·法尔杉的人际关系","斯坦哈德与谁共事","斯坦哈德的盟友"}}},fp="14,386,23.432.0,25.558.0,22.316.0,45.274.0,36.264.0,62.229.0,37.187.0,38.235.0"}
P.entries["npc:supervisor-raelen"] = {n="管理员莱琳",s="管理员莱琳在艾尔文森林东侧边缘的东谷伐木场负责监管木材生产工作。她负责管理当地劳工、维持每日伐木配额，并确保采伐的木材能够安全地进入暴风城的供应链。",h="管理员莱琳在艾尔文森林东侧边缘的东谷伐木场负责监管木材生产工作。她负责管理当地劳工、维持每日伐木配额，并确保采伐的木材能够安全地进入暴风城的供应链。",kw={"麻烦的木捆","东谷","东谷伐木场","艾尔文森林","木材","莱琳","管理员莱琳","木材配额"},ang={["faction:Alliance"]="维持王国的木材供应对于确保暴风城的防御和建设资金至关重要，这使得莱琳的木材配额对战争努力至关重要。"},sec={{t="确保营地工作进度",b="Located in the heart of Eastvale Logging Camp near Marshal Patterson and the camp's wood wagons, Supervisor Raelen directs the labor force tasked with harvesting timber for the kingdom. Operating a lumber camp on the border of the Redridge Mountains carries significant logistical challenges, from coordinating weary woodcutters to dealing with wildlife and bandit interference that threatens production quotas. Despite the hazards of the surrounding woods, Raelen focuses squarely on getting timber gathered, processed, and bundled for transport."}},faq={{q="管理员莱琳是谁？",a="管理员莱琳是一位驻扎在艾尔文森林东部东谷伐木场的人类监工。她负责管理营地的伐木队，并确保他们的木材收集配额能够稳定完成。",al={"莱琳是谁","艾尔文森林莱琳","东谷管理员"}},{q="我在哪里可以找到管理员莱琳？",a="她位于艾尔文森林东部的东谷伐木场中心，站在装满木材的运木车旁，和马歇尔·帕特森在一起。",al={"莱琳在哪里","管理员莱琳位置","寻找莱琳"}},{q="为什么管理员莱琳需要冒险者的帮助？",a="在森林边缘采集木材变得愈发危险，当工人们遭遇当地野生动物或其他干扰时，砍伐的木材捆常常被遗弃或散落在树林中。",al={"莱琳任务","麻烦的木捆任务","为什么要帮助莱琳"}},{q="东谷伐木场在艾尔文森林中扮演什么角色？",a="东谷是艾尔文森林东部主要的伐木作业点，为支持暴风城及其邻近定居点的重建和维护工作提供了必要的木材。",al={"什么是东谷","东谷伐木场的作用","为什么东谷很重要"}}},fx={["5e9ae7c9"]={q="管理员莱琳站在哪一方？",a="管理员莱琳效忠于暴风王国和联盟。她代表王国管理东谷伐木场的伐木作业，与暴风城卫兵和工人并肩工作，确保木材源源不断地运往首都。",al={"莱琳的阵营","管理员莱琳效忠于谁","莱琳属于联盟吗"}},["93ff040d"]={q="管理员莱琳为什么在东谷？",a="莱琳负责东谷伐木场的日常伐木工作。她指挥当地工人，监管运木车，并确保木材采集达到暴风城的配额，使作业在周边荒野的威胁下仍能正常进行。",al={"管理员莱琳为何在这里","莱琳在东谷的职责","莱琳在这里做什么"}},e5fd1368={q="管理员莱琳与谁有关？",a="莱琳与驻扎在东谷的暴风城地方当局密切合作，其中尤以负责营地防卫的帕特森元帅为要。她也指挥营地里的本地农民和伐木工人。",al={"莱琳的人际关系","莱琳与谁共事","管理员莱琳的盟友"}}},fp="17,285,28.547.0,25.201.0,35.147.0,54.200.0,63.194.0"}
P.entries["npc:suzetta-gallina"] = {n="苏泽塔·加林纳",s="苏泽塔·加林纳是加林纳家族的一员，该家族在暴风城从事优质葡萄酒的贸易。你可以在运河旁家族的葡萄酒商店里找到她，她负责打理生意，并向城中渴望美酒的顾客推广他们的存货。",h="苏泽塔·加林纳是加林纳家族的一员，该家族在暴风城从事优质葡萄酒的贸易。你可以在运河旁家族的葡萄酒商店里找到她，她负责打理生意，并向城中渴望美酒的顾客推广他们的存货。",kw={"加林纳酒庄","暴风城运河","暴风城葡萄酒","苏泽塔·加林纳","葡萄酒商店广告"},ang={["faction:Alliance"]="对于从艾尔文森林或西部荒野的险境中归来的联盟旅行者来说，在苏泽塔的商店驻足停留，能让人在首都感受到平和、文明生活的温馨提醒。"},sec={{t="运河的滋味",b="加林纳酒庄坐落在暴风城运河区风景优美的水道旁，为寻求王国各地进口或酿造的优质葡萄酒的市民提供服务。苏泽塔·加林纳负责照看酒庄的日常运营，维护家族向酒馆、贵族和平民供应葡萄酒的传统。虽然她不是高层政治中的公众人物，但她的存在代表了在动荡局势中支撑着首都繁荣的日常商业脉搏。"}},faq={{q="苏泽塔·加林纳是谁？",a="苏泽塔·加林纳是暴风城的居民，也是加林纳家族的一员。该家族经营着位于城内运河旁的加林纳酒庄。",al={"苏泽塔·加林纳","苏泽塔是谁","加林纳酒庄的女性"}},{q="我在哪里可以找到苏泽塔·加林纳？",a="她位于暴风城内，在贸易区和教堂广场之间的运河旁的加林纳酒庄里。",al={"苏泽塔·加林纳的位置","苏泽塔在哪里","加林纳酒庄的位置"}},{q="苏泽塔会为旅行者提供工作吗？",a="不会直接提供。她的兄弟雷纳托会分发葡萄酒兑换券，将兑换券带给加林纳酒庄的苏泽塔，就可以获得一瓶免费的家族特酿黑皮诺。",al={"苏泽塔的任务","加林纳葡萄酒任务","葡萄酒商店广告"}}},fx={f0d37e75={q="苏泽塔·加林纳站在哪一方？",a="苏泽塔·加林纳是联盟的忠诚居民。她与家人平静地生活和工作在暴风城中心，为首都的酒馆老板、贵族和平民提供服务。",al={"苏泽塔·加林纳的阵营","苏泽塔·加林纳属于联盟吗","苏泽塔效力于谁"}},["44c42184"]={q="苏泽塔·加林纳想要什么？",a="苏泽塔希望家族的葡萄酒生意兴旺发达。她与亲族一同打理加林纳酒庄，确保自家的酒桶和酒瓶在城中找到热切的买家，并向口渴的旅人宣传家族佳酿。",al={"苏泽塔·加林纳的目标","苏泽塔想要什么","苏泽塔·加林纳在做什么"}},["290e58c2"]={q="苏泽塔·加林纳为什么在暴风城？",a="苏泽塔留在运河区，因为加林纳酒庄就在那里，是家族生意的中心。她在这里协助经营酒庄，也能接近暴风城繁忙的酒馆和商道。",al={"苏泽塔·加林纳为何在这里","苏泽塔为何在运河区","苏泽塔·加林纳的位置背景"}},c1c3d801={q="苏泽塔·加林纳与谁有关？",a="苏泽塔是经营葡萄酒生意的加林纳家族成员，她在家族店铺中与亲族并肩工作，在暴风城各处酿造和售卖佳酿。",al={"苏泽塔·加林纳的家族","苏泽塔与谁有亲属关系","加林纳酒庄家族"}}},fp="15,263,21.478.0,23.143.0,33.134.0,42.171.0"}
P.entries["npc:sven-yorgen"] = {n="斯温·约根",s="斯温·约根是一位悲痛欲绝的农夫，他与同伴拉尔斯一起在暮色森林西部寂静河岸的北缘扎营。在约根农场目睹了家人被残酷屠杀后，斯温一心只想找出是谁毁了他的家园并寻求复仇。",h="斯温·约根是一位悲痛欲绝的农夫，他与同伴拉尔斯一起在暮色森林西部寂静河岸的北缘扎营。在约根农场目睹了家人被残酷屠杀后，斯温一心只想找出是谁毁了他的家园并寻求复仇。",kw={"暗黑骑手","暮色森林","寂静河岸","基特斯","拉尔斯","摩尔班·菲尔","艾露恩之镰","斯温·约根","约根农场"},ang={["class:Paladin"]="斯温的悲痛和对正义的渴望，让圣骑士们有了一种直接的使命，去为无辜的鲜血复仇，并清除在他家土地上四处游荡的亡灵。",["faction:Alliance"]="斯温代表了王国边境地区乡村生活的悲剧性崩溃，在那里，普通的臣民在黑暗魔法和阴影恐怖面前毫无防卫之力。"},sec={{t="破碎的生活",b="斯温出生于第一次战争之前，他记得麦迪文陨落、该地区被阴霾笼罩之前的日子。多年来，他与妻子儿女一起在暮色森林南部的约根农场辛勤劳作。当他外出时，神秘的暗黑骑手袭击了他的农场，残酷地杀害了他的家人，将农场变成了墓地，那种宁静的生活也随之戛然而止，取而代之的是突如其来的暴力。"},{t="来自寂静河岸的复仇",b="无法回到那片家园废墟，斯温与朋友拉尔斯在寂静河岸建立了一个隐蔽的避难所。他对外人充满戒心，在分享自己的心事之前会要求旅行者证明忠诚。斯温发现有一个鬼鬼祟祟的身影潜伏在他那满目疮痍的农场附近，他确信这个入侵者要么是这场屠杀的直接责任人，要么与那些摧毁他世界的邪恶骑手有关。"},{t="揭开真相",b="潜伏在斯温地盘上的那个神秘身影竟是基特斯，一个流浪汉，他的鲁莽举动无意中将正在寻找艾露恩之镰的暗黑骑手引到了暮色森林。虽然基特斯没有亲手下毒手，但他的行为引发了摧毁约根一家的梦魇，这也将斯温的怒火引向了出没在乌鸦岭的黑暗势力以及死灵法师摩尔班·菲尔。"}},faq={{q="斯温·约根是谁？",a="斯温·约根是一位人类农夫，居住在暮色森林寂静河岸北缘的一个小营地。在家人于家中惨遭屠杀后，他将余生都献给了向责任人寻求报复的事业。",al={"斯温·约根","斯温是谁","斯温背景故事"}},{q="斯温的家人发生了什么事？",a="当斯温外出时，被称为暗黑骑手的恐怖黑袍人来到了约根农场。为了寻找一件强大的神器，他们无情地屠杀了斯温的妻子和孩子，并将这片土地变成了亡灵肆虐之地。",al={"约根农场悲剧","斯温家人之死","斯温的农场发生了什么"}},{q="斯温为什么要躲在寂静河岸？",a="屠杀发生后，斯温离开了那片破败的农场。他与拉尔斯在河岸边设立了一个临时营地，以便躲避在暮色森林西部游荡的亡灵，同时计划着他的复仇。",al={"斯温在哪里","斯温的营地","斯温为什么要在外扎营"}},{q="斯温看到的那个神秘身影是谁？",a="斯温不知道。他在自家农场废墟附近发现了一个潜行的人影，并请求值得信赖的旅行者帮他查明那人是谁，以及他们是否与家人的死亡有关。",al={"斯温看到的神秘身影","谁在约根农场","暮色森林的神秘身影"}},{q="暗黑骑手为什么要袭击斯温的农场？",a="暗黑骑手们正在暮色森林中搜寻艾露恩之镰，这是一件拥有巨大力量的古老神器。他们对这件遗物的追寻直接穿过了斯温的土地，并在经过之处留下了死亡。",al={"暗黑骑手为何袭击","暗黑骑手在找什么","艾露恩之镰与斯温"}},{q="斯温在暮色森林住了多久？",a="斯温年纪很大，他还记得暮色森林陷入黑暗之前的样子，这意味着他在第一次战争之前就住在这里，那时森林依然明亮而宁静，夜色镇当时被称为格兰哈姆雷特。",al={"斯温的年龄","斯温多大岁数","黑暗降临前的斯温"}}},fx={be3c9ddb={q="斯温·约根站在哪一方？",a="斯温效忠于联盟，但悲痛与怒火远比对暴风城的誓言更能驱使他。他的家园和家人都葬身于潜伏在暮色森林中的恐怖之物手下，因此他愿与任何可靠、愿意拿起武器对抗森林中黑暗势力的联盟冒险者合作。",al={"斯温·约根的阵营","斯温属于联盟吗","斯温为谁而战"}},d6fc644e={q="斯温·约根想要什么？",a="斯温想要复仇。神秘的黑暗骑士在约根农场屠杀了他的妻儿之后，他发誓要向凶手讨还血债。他试图查明那个徘徊在自家废墟附近的神秘身影的身份，并要求摧毁莫尔本特·费尔等腐化这片土地的死灵威胁。",al={"斯温想要什么","斯温·约根的目标","斯温为何需要帮助"}},["0ba4293f"]={q="斯温·约根与谁有关？",a="斯温的营地由他和拉尔斯共用，拉尔斯是帮助他在荒野中行动的可靠伙伴。他的复仇之路也与基特斯的悲惨谜团紧紧相连——斯温曾看见基特斯在农场附近徘徊；此外，他还直接与死灵法师莫尔本特·费尔以及逆风小径神秘莫测的黑暗骑士为敌。",al={"斯温·约根的盟友","斯温认识谁","斯温的人际关系"}}},fp="11,313,16.415.0,30.428.0,20.410.1,19.230.0,31.245.0,38.201.0,35.192.1,43.198.1,36.209.0"}
P.entries["npc:sylvanas-windrunner"] = {n="Sylvanas Windrunner",s="Sylvanas Windrunner女士是女妖之王，也是Forsaken的至高统治者，在洛丹伦废墟之下的Undercity中坐镇。她曾是Silvermoon勇敢的Ranger-General，后来被Arthas Menethil杀害并复活为亡灵，之后摆脱了Lich King的控制。如今，为了共同的生存，她与Thrall的Horde结盟，并致力于为她那些拥有自由意志的亡灵同胞争取未来，同时向Scourge复仇。",h="Sylvanas Windrunner女士是女妖之王，也是Forsaken的至高统治者，在洛丹伦废墟之下的Undercity中坐镇。她曾是Silvermoon勇敢的Ranger-General，后来被Arthas...",kw={"arthas","女妖之王","黑暗女王","forsaken","lordaeron","ranger-general","sylvanas","undercity","windrunner"},ang={["faction:Horde"]="尽管在大德鲁伊Hamuul Runetotem的倡导和Thrall的同情下被Horde接纳，但许多Orc和Troll仍然以怀疑的眼光看待Sylvanas和她的部下。",["race:Undead"]="对于Forsaken来说，黑暗女王是一位解放者和保护者，是他们拥有自由意志和坚固家园的唯一原因，让他们不必沦为盲目服从Scourge的奴隶。"},sec={{t="Ranger-General的陨落",b="生前，Sylvanas Windrunner女士是Silvermoon著名的Ranger-General，在第三次战争期间指挥Quel'Thalas的防御战。当Arthas Menethil王子率领Scourge进入这个高等精灵王国以抵达Sunwell时，Sylvanas进行了激烈的抵抗以延缓他的推进。面对她的抵抗，Arthas感到恼火，他杀死了她，但并没有让她安然死去。他将她的灵魂从尸体中撕裂，并将她扭曲成一个充满怨恨的女妖，强迫她为Scourge效力，并协助屠杀她自己的人民。"},{t="Forsaken的崛起",b="第三次战争后，当Lich King的魔法控制力减弱时，Sylvanas摆脱了他的统治并重新夺回了自己保存完好的躯体。她聚集了其他恢复了自由意志的亡灵，推翻了占据洛丹伦废墟的恐惧魔王，将她的人民称为Forsaken，并在地下建立了Undercity王国。由于认识到她的人民处于孤立无援的危险境地——不仅受到Scourge残余势力、狂热的血色十字军以及心存怀疑的人类王国的威胁——她与大酋长Thrall和Horde结成了利益联盟。"}},faq={{q="谁是Sylvanas Windrunner？",a="她是被遗忘者的最高领袖，在Undercity的Royal Quarter中坐镇。生前她是Quel'Thalas的精灵Ranger-General，但在被Arthas Menethil杀害并复活后，她脱离了Scourge，带领着那些拥有自由意志的亡灵。",al={"女妖之王","黑暗女王是谁","sylvanas女士","undercity领袖"}},{q="为什么Sylvanas会让Forsaken与Horde结盟？",a="Forsaken受到Alliance各活人种族国家的厌恶，后者只将他们视为怪物。由于在Lordaeron受到Scourge和血色十字军的包围，Sylvanas需要强大的盟友来确保她初建的国家的生存，因此她请求大酋长Thrall准许加入Horde。",al={"亡灵为什么加入horde","forsaken与horde盟约","sylvanas与thrall的协定"}},{q="Sylvanas是如何摆脱Lich King控制的？",a="第三次战争后的余波中，当Lich King的精神力量开始流失时，他对Scourge的铁腕控制出现了裂痕。Sylvanas是第一批恢复自主意识的强大灵魂之一，她立即夺回了自己的凡人躯体，并将怒火倾泻在Arthas身上。",al={"sylvanas如何逃脱arthas","sylvanas的自由意志","lich king的控制"}},{q="Sylvanas的主要目标是什么？",a="最重要的是，Sylvanas寻求对Arthas Menethil和Scourge进行彻底的报复，因为他们摧毁了她的家园并奴役了她的灵魂。同时，她努力加固Undercity，为Forsaken在Lordaeron开辟一个安全、永久的避难所。",al={"sylvanas想要什么","sylvanas的动机","黑暗女王的目标"}}},fx={["830cd396"]={q="Sylvanas Windrunner为什么在幽暗城？",a="Sylvanas在幽暗城深处的Royal Quarter统治被遗忘者。幽暗城是建在洛丹伦首都废墟下方的地下迷宫。她从天灾军团和恐惧魔王手中夺下首都后，将其建成自己那些拥有自由意志的亡灵的据点。从这里，她指挥人们抵御血色十字军和天灾军团残余势力对提瑞斯法林地的进攻，同时努力为自己的人民在东部王国开创稳固的未来。",al={"sylvanas为何在这里","为何sylvanas在幽暗城","sylvanas所在位置的原因"}},de176d94={q="Sylvanas Windrunner与谁结盟？",a="Sylvanas是被遗忘者的最高统治者，并以互利同盟的形式率领他们加入了大酋长萨尔的部落。在她的宫廷中，瓦里玛萨斯等恐惧魔王守护并辅佐她；洛丹伦陷落后，瓦里玛萨斯向她宣誓效忠。在亡灵之国以外，她与兽人和牛头人保持着紧张的地缘政治关系；尽管彼此仍存猜疑，他们还是准许她的人民加入部落。",al={"sylvanas的盟友","sylvanas与谁有关","sylvanas windrunner的人际关系"}},aee4c591={q="Sylvanas Windrunner为何闻名？",a="生前，Sylvanas备受尊崇，是银月城的游侠将军，以英勇抵御天灾军团、保卫奎尔萨拉斯而闻名。如今，艾泽拉斯各地都畏惧她这位女妖之王。她遭到阿尔萨斯王子的处决和女妖折磨，却仍夺回了自己的凡人躯体，并将一个亡灵阵营从巫妖王的精神控制下解放出来。她致命的箭术、女妖尖啸和冷酷狡诈，让生者与死者都对她敬而远之。",al={"为何畏惧sylvanas","女妖之王为何闻名","sylvanas为何闻名"}}},fp="19,463,26.512.0,20.567.0,27.271.0,51.301.0,47.285.0,32.262.0"}
P.entries["npc:syral-bladeleaf"] = {n="塞拉尔·刃叶",s="塞拉尔·刃叶是泰达希尔多兰纳尔的一位暗夜精灵居民，担任森林议会的联络人。她指引从幽影谷而来的年轻冒险者，引导他们前往照顾林地的看守者、草药师和长老，守护这片树冠下娇嫩的枝叶。",h="塞拉尔·刃叶是泰达希尔多兰纳尔的一位暗夜精灵居民，担任森林议会的联络人。她指引从幽影谷而来的年轻冒险者，引导他们前往照顾林地的看守者、草药师和长老，守护这片树冠下娇嫩的枝叶。",kw={"刃叶","森林议会","德纳兰","多兰纳尔","刃叶长老","塞拉尔","泰达希尔"},ang={["profession:Herbalism"]="塞拉尔与当地的自然学家和草药供应链密切合作，指引旅者协助奥拉密斯湖的植物学研究，并确保新鲜的药剂能够送达长老手中。",["race:NightElf"]="对于那些走出幽影谷与世隔绝的洞穴的年轻暗夜精灵来说，塞拉尔·刃叶是他们听到的关于多兰纳尔市政和自然领导层的第一批声音之一。"},sec={{t="多兰纳尔之声",b="塞拉尔·刃叶站在多兰纳尔的中心地带，协助组织泰达希尔树冠阴影下的当地事务。她代表森林议会，引导新到达的暗夜精灵前往村庄及附近荒野的社区领袖和草药师处。通过她的指引，旅者们可以联络奥拉密斯湖的植物学家德纳兰，并为村庄的长老补充物资。"},{t="与村庄的联系",b="塞拉尔代表森林议会在多兰纳尔工作。她的职责专注于社区福利，确保药剂能及时送达有需要的人手中，并确保当地生态系统出现的任何扰动都能得到迅速处理。"}},faq={{q="塞拉尔·刃叶是谁？",a="塞拉尔·刃叶是多兰纳尔的一名暗夜精灵，她代表森林议会传达指令，帮助初来乍到的冒险者协助周围的林地社区。",al={"塞拉尔是谁","塞拉尔·刃叶背景故事","塞拉尔 多兰纳尔"}},{q="在哪里可以找到塞拉尔·刃叶？",a="她位于泰达希尔的中心定居点多兰纳尔，就在幽影谷西南方的主路旁。",al={"塞拉尔·刃叶位置","塞拉尔在哪里","塞拉尔地图"}},{q="她给冒险者分配什么任务？",a="塞拉尔派遣旅者前往奥拉密斯湖协助植物学家德纳兰，组织为长老运送草药药剂，并指引冒险者完成有助于泰达希尔自然平衡的任务。",al={"塞拉尔·刃叶任务","塞拉尔需要什么","塞拉尔任务"}}},fx={["47edbb6a"]={q="塞拉尔·刃叶想做什么？",a="塞拉尔希望森林议会的意志得以贯彻。她向有能力的冒险者传达议会的指令，寻求他们帮助德纳兰等附近的盟友，并努力遏制泰达希尔日益蔓延的腐化。",al={"塞拉尔·刃叶想做什么","塞拉尔·刃叶的目标","塞拉尔·刃叶的动机"}},["7fd35b53"]={q="塞拉尔·刃叶为什么在多兰纳尔？",a="塞拉尔驻扎在多兰纳尔，担任森林议会的重要联络人。她可以从这处中心聚居地轻松招募路过的旅人和年轻暗夜精灵，照料林枝的需求并协助当地的守护者。",al={"塞拉尔·刃叶为何在此","塞拉尔·刃叶在多兰纳尔的原因","塞拉尔为何在多兰纳尔"}},["39456ef3"]={q="塞拉尔·刃叶站在哪一方？",a="塞拉尔效力于达纳苏斯和联盟。她驻扎在多兰纳尔，直接听命于森林议会，帮助保护当地荒野及其守护者，免受泰达希尔日益蔓延的麻烦侵扰。",al={"塞拉尔·刃叶的阵营","塞拉尔·刃叶效力于谁","塞拉尔·刃叶的效忠对象"}}},fp="15,284,19.422.0,19.247.0,23.179.0,35.123.0,42.199.0"}
P.entries["npc:syurna"] = {n="塞尤娜",s="塞尤娜是一位暗夜精灵潜行者训练师，坐落在达纳苏斯塞纳里奥区的丛林之中。她指导卡多雷有抱负的斥候、间谍和秘密行动人员，引导刚受训的潜行者执行考验其潜行技巧与狡诈能力的任务。",h="塞尤娜是一位暗夜精灵潜行者训练师，坐落在达纳苏斯塞纳里奥区的丛林之中。她指导卡多雷有抱负的斥候、间谍和秘密行动人员，引导刚受训的潜行者执行考验其潜行技巧与狡诈能力的任务。",kw={"塞纳里奥区","达纳苏斯","命运的召唤","卡多雷","潜行者训练师","塞尤娜","泰达希尔"},ang={["class:Rogue"]="对于暗夜精灵潜行者来说，塞尤娜是你在达纳苏斯的主要导师之一，当你积累经验时，她会教导你潜行、毒药和武力精准的核心技巧。",["race:NightElf"]="塞尤娜体现了卡多雷斥候静默、掠食者的传统，他们从阴影中保护自己的林地圣所，而不是通过公开的战斗。"},sec={{t="丛林中的斥候",b="虽然达纳苏斯歌颂哨兵部队的公开武力与The Sisterhood of Elune的精神智慧，但卡多雷一直依赖着阴影与潜行。塞尤娜位于塞纳里奥区，为那些行走于隐秘之路的人们担任训练师和导师。她教导潜行者闪避、开锁和致命打击的精妙艺术，确保达纳苏斯拥有敏锐的双眼和沉默的利刃来保卫泰达希尔。"},{t="狡诈的考验",b="塞尤娜不仅仅是在塞纳里奥区的安全地带提供理论建议；她还会考验年轻特工的战备状态。通过诸如指引有前途的初学者进行更深入的实地工作等任务，她会测试这些特工是否具备在世界之树枝叶之外生存并为联盟在危险边境地带效力所需的直觉。"}},faq={{q="塞尤娜是谁？",a="塞尤娜是一位驻扎在达纳苏斯塞纳里奥区的暗夜精灵潜行者训练师。她为效力于联盟的潜行者冒险者提供战斗训练、技能和指导。",al={"塞尤娜 达纳苏斯","塞尤娜是谁","暗夜精灵潜行者训练师"}},{q="我在达纳苏斯哪里可以找到塞尤娜？",a="她位于达纳苏斯的塞纳里奥区，伫立在树木和亭阁之间，身旁还有其他倾向于阴影的导师。",al={"塞尤娜在哪里","塞尤娜位置","达纳苏斯潜行者训练师位置"}},{q="为什么塞纳里奥区会有潜行者训练师？",a="虽然塞纳里奥区主要与德鲁伊教义和自然相关，但暗夜精灵斥候和隐秘的探路者经常在其树木繁茂的边缘地带悄然训练，远离艾露恩神殿或战士区的公共盛会。",al={"为什么塞纳里奥区有潜行者训练师","塞纳里奥区潜行者"}},{q="塞尤娜提供什么任务？",a="塞尤娜参与了潜行者的早期成长，指引那些在幽影谷证明了自己的新手特工前往更广阔的世界磨练天赋，其中包括“命运的召唤”这类任务。",al={"塞尤娜任务","命运的召唤任务"}}},fx={["4fb7093b"]={q="塞尤娜属于哪一方？",a="塞尤娜坚定地支持达纳苏斯和联盟。作为一名在首都活动的暗夜精灵潜行者，她向忠于卡多雷事业的人提供专长，指导有志成为斥候、盗贼和刺客的人磨炼隐秘技艺。",al={"塞尤娜的阵营","塞尤娜效忠于谁","塞尤娜与联盟"}},d409bc2a={q="塞尤娜想做什么？",a="塞尤娜负责教导并引领来到达纳苏斯的潜行者新秀。她留意那些直觉敏锐、擅长潜行的人，指引他们接受训练并执行任务，确保卡利姆多的阴影力量守护暗夜精灵的安全。",al={"塞尤娜的目标","塞尤娜在试图做什么","塞尤娜的职责"}}},fp="6,258,23.448.0,16.357.0,14.182.0,45.134.0,47.244.0,30.202.0"}
P.entries["npc:tabetha"] = {n="塔贝萨",s="塔贝萨是一位隐居且强大的女性类人法师，居住在尘泥沼泽深处、泥潭沼泽中一处偏僻的农场里。她远离了达拉然或塞拉摩的政治纷争，指导着有抱负的施法者，并帮助那些寻求掌握强大奥术和神秘遗物的人。",h="塔贝萨是一位隐居且强大的女性类人法师，居住在尘泥沼泽深处、泥潭沼泽中一处偏僻的农场里。她远离了达拉然或塞拉摩的政治纷争，指导着有抱负的施法者，并帮助那些寻求掌握强大奥术和神秘遗物的人。",kw={"尘泥沼泽","法师任务","梅纳拉·沃伦德","奥拉希尔之珠","泥潭沼泽","塔贝萨","tabetha's farm"},ang={["class:Mage"]="塔贝萨是中等级别法师的重要导师，她会考验你对奥术仪式的掌握程度，并派遣你前往像奥达曼这样危险的地方去磨练你的技艺。",["class:Warlock"]="虽然她修行的是奥术，但塔贝萨对魔法遗物的深刻理解使她在处理如地狱火宝珠和奥拉希尔之珠等危险神器时，成为了一位关键的向导。"},sec={{t="泥潭沼泽的隐士",b="塔贝萨隐居在石槌废墟以北、尘泥沼泽潮湿的荒野中，和她的学徒们一起住在偏僻的棚屋里。她周围摆满了炼金药瓶和古籍，刻意选择了避世，远离东部王国的学术等级制度。尽管她所处位置偏远，但她对奥术的精通程度依然声名远扬，以至于卡利姆多各地的施法者不惜冒着风险穿越野兽出没的沼泽，只为寻求她的指引。"},{t="中立的导师",b="塔贝萨明显置身于阵营敌对之外。虽然她是人类出身，但她既不会拒绝表现出学习意愿的联盟成员，也不会拒绝部落学员。她为法师提供指导，并协助术士完成危险的契约，比如奥拉希尔之珠。她的过去与梅纳拉·沃伦德等人有着联系，揭示了她与超越单纯阵营忠诚的秘法之间有着深厚的渊源。"}},faq={{q="我在哪里可以找到塔贝萨？",a="塔贝萨住在Tabetha's Farm（塔贝萨农场）的一间偏僻棚屋里，位于尘泥沼泽西部的泥潭沼泽深处，就在石槌废墟的北面。",al={"塔贝萨位置","塔贝萨在哪里","塔贝萨农场地图"}},{q="塔贝萨对部落玩家敌对吗？",a="不。尽管塔贝萨是人类，但她是中立的。她不分彼此地指导学徒并帮助部落和联盟的施法者。",al={"塔贝萨是联盟专属吗","部落可以和塔贝萨对话吗","塔贝萨阵营"}},{q="为什么法师和术士要找她？",a="塔贝萨拥有关于奥术仪式、魔法焦点和束缚仪式的稀有知识。法师们会向她咨询技艺的掌握和力量的试炼，而术士们则寻求她的专业知识来净化或束缚如奥拉希尔之珠这样强大的神器。",al={"为什么要拜访塔贝萨","塔贝萨职业任务","奥拉希尔之珠 塔贝萨"}},{q="她与梅纳拉·沃伦德有什么联系？",a="塔贝萨与梅纳拉·沃伦德有着共同的往事。虽然她们的道路各不相同，但她们对强大遗物和束缚魔法的共同理解将她们各自的隐居生活联系在了一起。",al={"塔贝萨与梅纳拉","梅纳拉·沃伦德历史"}}},fp="7,275,22.455.0,16.418.0,25.150.0,36.149.0,39.239.0,44.205.0"}
P.entries["npc:tai-jin"] = {n="泰金",s="泰金是一位驻扎在杜隆塔尔剃刀岭兵营内的暗矛巨魔牧师训练师。她指导部落年轻的牧师，向暗矛新兵传授传统的巨魔仪式，例如虚弱妖术。",h="泰金是一位驻扎在杜隆塔尔剃刀岭兵营内的暗矛巨魔牧师训练师。她指导部落年轻的牧师，向暗矛新兵传授传统的巨魔仪式，例如虚弱妖术。",kw={"暗矛","杜隆塔尔","虚弱妖术","牧师训练师","剃刀岭","泰金"},ang={["class:Priest"]="对于在杜隆塔尔训练的部落牧师来说，在前往奥格瑞玛宏伟的大厅之前，泰金是你的首要导师。",["race:Troll"]="泰金向年轻的暗矛牧师介绍他们文化中独特的法术，例如虚弱妖术。"},sec={{t="剃刀岭女祭司",b="泰金驻扎在坚固的剃刀岭兵营内，为踏入杜隆塔尔的年轻牧师担任精神导师。虽然兽人主要倾向于萨满教或黑暗的术士技艺，但暗矛巨魔为部落带来了他们独特的神灵与洛阿沟通方式。泰金提供牧师的基础教导，确保新入教的信徒既能理解光与影的平衡，也能领悟巨魔文化独有的精神传承。"}},faq={{q="我在哪里可以找到泰金？",a="泰金位于杜隆塔尔中部剃刀岭兵营的一楼，就在其他职业训练师旁边。",al={"泰金位置","泰金在哪里","剃刀岭泰金"}},{q="泰金传授什么技能？",a="作为一名牧师训练师，她随着部落角色经验的提升，教授他们新的牧师法术、等级和技能，包括针对巨魔新兵的早期训练任务。",al={"泰金训练师","泰金教授什么","剃刀岭牧师法术"}},{q="为什么一位巨魔牧师会驻扎在兽人定居点？",a="剃刀岭是所有从试炼谷和森金村走出来的年轻部落冒险者的主要训练中心。由于兽人不修习牧师技艺，泰金便代表了暗矛部族在该定居点的精神传统。",al={"为什么泰金在剃刀岭","剃刀岭兵营中的巨魔"}},{q="泰金为巨魔牧师提供什么特殊仪式？",a="泰金引导暗矛牧师进行入门级的精神仪式，特别传授他们如何通过虚弱妖术来引导祖先的诅咒。",al={"虚弱妖术任务","泰金任务"}}},fx={["5b5c447a"]={q="泰金是谁？",a="泰金是暗矛丛林巨魔牧师训练师，驻扎在剃刀岭的兵营中。她致力于引导那些运用精神与神圣力量的人，教导部落的年轻侍僧——尤其是巨魔和被遗忘者牧师——掌握精神技艺、祷告和传统巨魔仪式。",al={"泰金的身份","泰金是谁","泰金的背景"}},["1746c020"]={q="泰金属于哪一方？",a="泰金忠于暗矛部族和部落。她与兽人战士和萨满一同驻扎在杜隆塔尔，为萨尔大酋长领导的联合力量效力，确保施展精神力量的人做好准备，捍卫部落领土。",al={"泰金的阵营","泰金效忠于谁","泰金的忠诚归属"}},dfe85d14={q="泰金想做什么？",a="泰金希望引导新手牧师认识自己的精神天赋，并加深他们的信仰。她要求年轻侍僧证明自己严守纪律、勤于冥想，并能与精神力量沟通，以便他们能够妥善支援杜隆塔尔及更远地区的盟友。",al={"泰金想做什么","泰金的目标","泰金的职责"}},ab897349={q="泰金与谁有关联？",a="作为剃刀岭的精神导师，泰金与由森金遗志凝聚起来的暗矛巨魔关系密切，也与受奥格瑞玛管辖的当地部落驻军紧密相连。她与杜隆塔尔的其他训练师和守卫并肩协作，培养坚定虔诚的侍僧。",al={"泰金的关系","泰金的关联","泰金与谁结盟"}}},fp="7,230,23.478.0,25.120.0,24.170.0,53.263.0,58.153.0"}
P.entries["npc:taiga-wisemane"] = {n="泰迦·慧鬃",s="泰迦·慧鬃是一位居住在凄凉之地崎岖西海岸葬影村的牛头人长者。他时刻警惕着这片荒芜之地上潜藏的恶魔阴谋，并致力于挫败在该地区根深蒂固的火刃氏族邪教。他指引部落的勇士们去破坏恶魔仪式，并在燃烧军团站稳脚跟之前封印那些开启的传送门。",h="泰迦·慧鬃是一位居住在凄凉之地崎岖西海岸葬影村的牛头人长者。他时刻警惕着这片荒芜之地上潜藏的恶魔阴谋，并致力于挫败在该地区根深蒂固的火刃氏族邪教。他指引部落的勇士们去破坏恶魔仪式，并在燃烧军团站稳脚跟之前封印那些开启的传...",kw={"火刃氏族","恶魔之盒","凄凉之地","伊鲁克索斯之手","玛诺洛克集会所","葬影村","泰迦·慧鬃","雷斧堡垒"},ang={["class:Warlock"]="术士们会发现泰迦对伊鲁克索斯之手的理解十分引人注目，因为他利用这件黑暗圣物本身的共鸣来崩解恶魔传送门，而不是通过圣洁的仪式来驱逐它们。",["faction:Horde"]="泰迦为穿行于凄凉之地的部落勇士提供了至关重要的指导，确保葬影村这个据点免受恶魔侵袭。",["race:Tauren"]="对于牛头人旅者来说，泰迦代表了治愈卡利姆多并保护其免受非自然恶魔枯萎病侵害的职责，他挺身对抗那段曾在凄凉之地留下伤痕的黑暗遗产。"},sec={{t="葬影村的守望之眼",b="尽管葬影村主要是一个依海而建的暗矛巨魔定居点，但泰迦·慧鬃却驻扎于此，监视着凄凉之地各处涌动的黑暗魔法。他敏锐地察觉到精神腐蚀正不断渗入这片土地，并将目光紧紧锁定在东方，那里邪教徒和恶魔残党正盘踞在古代废墟之中。"},{t="遏制恶魔浪潮",b="火刃氏族在雷斧堡垒积极活动，试图利用黑暗神器来扩大他们的影响力。泰迦深知这对凄凉之地所有居民构成的威胁，于是指派能干的冒险者潜入堡垒，夺取恶魔之盒——一个存放着伊鲁克索斯之手的邪恶箱子。通过这致命一击，他旨在夺走邪教徒用来撕裂世界屏障的主要焦点。"},{t="封印玛诺洛克集会所的传送门",b="夺取伊鲁克索斯之手仅仅是泰迦计划的第一步。在南部的玛诺洛克集会所，火刃氏族已经撕开了活跃的恶魔裂隙。泰迦指挥受信任的勇士们将黑暗焦点的力量反过来对准其制造者，将神器的能量直接注入传送门，在燃烧军团将增援部队投入卡利姆多中心地带之前，将这些通道封死。"}},faq={{q="泰迦·慧鬃是谁？",a="泰迦·慧鬃是一位居住在凄凉之地西海岸葬影村的牛头人长者。他作为一名顾问和任务发布者，致力于追踪并反制火刃氏族在整个地区实施的恶魔仪式。",al={"泰迦是谁","泰迦·慧鬃背景","泰迦在葬影村"}},{q="为什么一个牛头人会住在葬影村？",a="虽然葬影村主要是巨魔的定居点，但它也是部落在凄凉之地海岸线上的主要据点。泰迦留在这里是为了守望荒芜之地，并招募路过的部落旅人去消灭附近的恶魔威胁。",al={"为什么泰迦在葬影村","泰迦在巨魔村","牛头人在巨魔小镇"}},{q="火刃氏族在凄凉之地做什么？",a="火刃氏族以雷斧堡垒和玛诺洛克集会所为据点，正在开启恶魔传送门，企图将燃烧军团的势力召唤至卡利姆多。泰迦致力于在荒地彻底沦陷之前破坏他们的企图。",al={"火刃氏族凄凉之地","邪教徒在做什么","雷斧堡垒邪教徒"}},{q="什么是伊鲁克索斯之手？",a="伊鲁克索斯之手是一件锁在雷斧堡垒恶魔之盒中的恶魔神器。火刃氏族打算利用其邪恶能量撬开通往虚空的传送门，但泰迦想出了一个办法，利用这只手本身的魔法反制裂隙，将其封印。",al={"伊鲁克索斯之手","什么是恶魔之盒","恶魔之盒遗物"}},{q="玛诺洛克集会所发生了什么？",a="玛诺洛克集会所是凄凉之地南部的一个邪恶之地，火刃氏族在那里成功建立了恶魔传送门。在泰迦·慧鬃的指导下，冒险者们将伊鲁克索斯之手带到该地点，以强行关闭这些传送门。",al={"玛诺洛克集会所传送门","什么是玛诺洛克集会所","凄凉之地传送门"}},{q="泰迦属于特定的牛头人部族吗？",a="泰迦沿用了慧鬃这个姓氏，反映了他作为一位深切关注精神平衡和恶魔腐蚀的长者的角色，尽管他效力于联合部落旗帜下更广泛的部落阵营。",al={"泰迦部族","慧鬃部族","泰迦是血蹄吗"}}},fp="14,347,28.386.0,25.447.1,27.401.1,22.244.0,45.236.0,44.238.0,27.261.0,31.241.0,45.212.0"}
P.entries["npc:takar-the-seer"] = {n="先知塔卡尔",s="先知塔卡尔是一位行踪诡秘的人类隐士，他居住在贫瘠之地深处，陶拉祖营地以东。尽管他的营地完全处于部落控制的领土内，他却始终效忠于联盟，并为某些旅行者提供晦涩的神秘学知识。",h="先知塔卡尔是一位行踪诡秘的人类隐士，他居住在贫瘠之地深处，陶拉祖营地以东。尽管他的营地完全处于部落控制的领土内，他却始终效忠于联盟，并为某些旅行者提供晦涩的神秘学知识。",kw={"贫瘠之地隐士","陶拉祖营地","灵魂吞噬者","heartswood","魅魔任务","先知塔卡尔"},ang={["class:Warlock"]="对于联盟术士来说，塔卡尔是卡利姆多的一位重要联络人，他指导新手完成危险的仪式，以召唤并奴役魅魔为他们服务。",["faction:Alliance"]="在部落核心领地的深处找到一张友善的人类面孔，这在卡利姆多中部提供了一个罕见但孤独的联络点。"},sec={{t="草原上的隐士",b="先知塔卡尔独自居住在陶拉祖营地以东的一个简陋帐篷下，在贫瘠之地干燥的平原上显得格格不入。周围的土地常有牛头人勇士和兽人巡逻队监视，但塔卡尔在他偏僻的空地上却未受干扰。他对好奇的部落闯入者怀有敌意，但很少主动发起暴力冲突。他密切注视着地平线，更倾向于独处。他与世隔绝的生活表明他是在刻意隐居，远离暴风城熙熙攘攘的政治纷争。"},{t="神秘学顾问",b="虽然离群索居，但塔卡尔并没有完全与大世界脱节。黑暗艺术的研习者——尤其是来自东部王国的联盟术士——在试图束缚危险的异界实体时，会向他寻求神秘的指引。他对不可见力量和灵魂魔法的深刻理解，使得他偏僻的营地成为了那些寻求束缚和奴役恶魔的修行者们一处至关重要却又危险重重的朝圣之地。"}},faq={{q="为什么一位人类先知会独自生活在贫瘠之地？",a="塔卡尔从未说明原因。他在陶拉祖营地以东独自扎营，附近没有任何联盟前哨站。那些寻找他的术士是为了获得他关于恶魔的知识，而不是为了听他的故事。",al={"为什么塔卡尔在贫瘠之地","塔卡尔在这里做什么","塔卡尔背景故事"}},{q="塔卡尔对部落玩家有敌意吗？",a="是的，塔卡尔隶属于联盟，对于部落冒险者来说他是敌对的。然而，他并不是特别好斗，通常不会主动攻击，除非受到挑衅或靠近得太近。",al={"塔卡尔是友好的吗","部落可以和塔卡尔交谈吗","塔卡尔对部落的反应"}},{q="是什么将联盟冒险者带到他的营地？",a="某些寻求帮助的联盟成员，特别是那些追求束缚强大恶魔（如魅魔）仪式的术士，会被指引去找塔卡尔。他会提供神秘的指引，并就获取召唤和奴役这些实体所需的材料提供见解。",al={"塔卡尔任务","为什么要拜访塔卡尔","谁会与塔卡尔交谈"}}},fx={e39a8e5b={q="先知塔卡尔是谁？",a="先知塔卡尔是一位独居的人类秘术师，住在卡利姆多腹地、远离人类聚居地的地方。他在陶拉祖营地以东的干旱荒野扎营，虽身处部落和当地部族声索的土地之中，仍在贫瘠之地静静守望。",al={"塔卡尔是谁","先知塔卡尔是谁","塔卡尔的身份"}},bed67aa2={q="先知塔卡尔属于哪一方？",a="塔卡尔仍忠于联盟。尽管他住在远离友方哨站的地方，深入部落领地，他仍欢迎前来寻找他的联盟旅人，同时对路过的部落勇士抱有冷酷的敌意。",al={"塔卡尔是联盟成员吗","塔卡尔属于联盟还是部落","塔卡尔的阵营"}}},fp="14,258,25.490.0,14.411.0,48.190.0,34.195.0,45.259.0"}
P.entries["npc:takata-steelblade"] = {n="塔卡塔·钢刃",s="塔卡塔·钢刃是一位驻扎在凄凉之地幽灵岗哨的兽人战士。他受奥格瑞玛的科尔丹派遣，与玛乌林·碎骨一同前往，负责领导部落在当地对抗恶魔腐蚀的战役。他的首要目标是铲除该地区与邪恶的火刃氏族勾结的萨特势力。",h="塔卡塔·钢刃是一位驻扎在凄凉之地幽灵岗哨的兽人战士。他受奥格瑞玛的科尔丹派遣，与玛乌林·碎骨一同前往，负责领导部落在当地对抗恶魔腐蚀的战役。他的首要目标是铲除该地区与邪恶的火刃氏族勾结的萨特势力。",kw={"碎骨","火刃氏族","凄凉之地","幽灵岗哨","科尔丹","玛乌林","萨特","钢刃","塔卡塔"},ang={["class:Warrior"]="作为一名剑术大师，塔卡塔的战役强调以果断的武力斩杀恶魔渗透者。",["faction:Horde"]="塔卡塔在凄凉之地协调部落的区域防御，以幽灵岗哨为行动基地清除恶魔渗透者。",["race:Orc"]="奉奥格瑞玛领导层的命令，塔卡塔体现了兽人铲除任何恶魔奴役残余的职责。"},sec={{t="前往凄凉之地",b="塔卡塔·钢刃是在科尔丹的直接命令下从首都前往凄凉之地的。科尔丹是奥格瑞玛的一位有影响力的人物，致力于发掘并清除恶魔的颠覆活动。塔卡塔以偏远的牛头人营地幽灵岗哨为行动基地，协调军事力量，对抗在这一荒芜之地肆虐的军团附属势力。"},{t="萨特的克星",b="当他的同伴玛乌林·碎骨尝试直接追踪并瓦解秘密的火刃氏族邪教徒时，塔卡塔则专注于他们的恶魔盟友：萨特。塔卡塔针对凄凉之地那些被腐蚀的萨特发动了激进的打击，重创了他们的阵线，旨在破坏该邪教在当地的权力结构并阻止其腐蚀的蔓延。"}},faq={{q="塔卡塔·钢刃是谁？",a="塔卡塔·钢刃是一位驻扎在凄凉之地幽灵岗哨的资深兽人战士。他负责指挥针对恶魔势力以及与火刃氏族结盟的萨特的军事行动。",al={"塔卡塔","塔卡塔背景故事","塔卡塔是谁"}},{q="是谁派遣塔卡塔前往凄凉之地的？",a="他是受奥格瑞玛的科尔丹派遣，前往该地区消除火刃氏族及其恶魔盟友所构成的威胁。",al={"谁派遣了塔卡塔","科尔丹的关联","塔卡塔的命令"}},{q="塔卡塔和玛乌林·碎骨是什么关系？",a="他们两人由科尔丹一同派遣。玛乌林负责直接对抗火刃氏族邪教徒，而塔卡塔则将军事打击重点放在了与他们结盟的萨特身上。",al={"塔卡塔与玛乌林","玛乌林·碎骨"}},{q="为什么塔卡塔要猎杀萨特？",a="凄凉之地的萨特正与火刃氏族邪教积极结盟，传播恶魔腐蚀并威胁到部落在该地区的立足点。",al={"为何猎杀萨特","塔卡塔萨特","萨特之腐"}},{q="在哪里可以找到塔卡塔·钢刃？",a="他位于凄凉之地中北部的一个部落营地，幽灵岗哨。",al={"塔卡塔位置","塔卡塔·钢刃在哪里"}}},fx={a8c99361={q="塔卡塔·钢刃属于哪一方？",a="塔卡塔·钢刃忠于部落，听命于奥格瑞玛的科尔丹。他致力于在凄凉之地维护部落的利益，清除威胁卡利姆多的恶魔势力，特别针对那些与他的族人敌对的邪恶教派和恶魔。",al={"塔卡塔·钢刃的阵营","塔卡塔的忠诚归属","塔卡塔是部落成员吗"}},["683721f0"]={q="塔卡塔·钢刃为什么在这里？",a="塔卡塔奉科尔丹之命驻守幽灵岗哨，领导当地对抗恶魔腐化的攻势。他的同伴玛乌林·碎骨专门对付火刃氏族教派，而塔卡塔则将怒火倾泻在此地的萨特身上，发动无情的行动，意图将他们彻底铲除。",al={"塔卡塔为何在凄凉之地","塔卡塔·钢刃的职责","塔卡塔在这里做什么"}},a7138bd5={q="塔卡塔·钢刃为何声名狼藉或令人畏惧？",a="凄凉之地那些邪恶的居民都知道塔卡塔恶名昭著，因为他对当地萨特进行了毁灭性、有计划的大屠杀。他在荒凉的废土上大肆杀戮每一个与火刃氏族有关联的萨特，因此声名骇人。",al={"塔卡塔的名声","塔卡塔为何令人畏惧","塔卡塔的声名"}}},fp="17,323,16.348.0,21.349.0,25.173.0,28.136.0,64.179.0,29.151.0,37.75.0"}
P.entries["npc:tal"] = {n="塔尔",s="塔尔是雷霆崖主要的风骑士训练师，负责照料这座城市位于莫高雷平原高处的航空栖木。他为那些想要横跨卡利姆多广阔地域的部落旅行者提供经验丰富的双足飞龙。",h="塔尔是雷霆崖主要的风骑士训练师，负责照料这座城市位于莫高雷平原高处的航空栖木。他为那些想要横跨卡利姆多广阔地域的部落旅行者提供经验丰富的双足飞龙。",kw={"飞行管理员","莫高雷","栖木","塔尔","雷霆崖","风骑士训练师","双足飞龙"},ang={["faction:Horde"]="塔尔维护着部落在卡利姆多最关键的交通枢纽之一，直接将牛头人首都与十字路口和奥格瑞玛连接起来。",["race:Tauren"]="对于那些走出祖居牧场的牛头人来说，塔尔提供了从他们的高地悬崖进入更广阔世界的最快捷、最安全的通道。"},sec={{t="高处栖木守护者",b="塔尔坐镇于雷霆崖中央的高地上，管理着连接牛头人首都与部落其他地区的重要空中通道。他从自己的栖位出发，照料着忠诚的风骑士（即双足飞龙），确保它们健康、饱食，并为横跨卡利姆多崎岖地貌的长途旅行做好准备。无论是向陶拉祖营地派遣信使，还是向贫瘠之地派遣前往奥格瑞玛的斥候，塔尔都维持着一条不可或缺的生命线，使这座高耸的台地城市能够与盟友保持持续的联系。"}},faq={{q="塔尔在雷霆崖中扮演什么角色？",a="塔尔是雷霆崖的风骑士训练师。他负责管理悬崖顶部的栖木，照料那些带翼的野兽，并为部落成员提供横跨卡利姆多的飞行服务。",al={"塔尔是谁","塔尔飞行管理员","塔尔做什么"}},{q="塔尔将旅行者送往何处？",a="塔尔将雷霆崖与卡利姆多中部和南部的各个地点连接起来，包括陶拉祖营地、十字路口、奥格瑞玛以及遥远的荒野前哨。",al={"塔尔可以飞往哪里","塔尔的目的地","雷霆崖飞行点"}},{q="为什么使用风骑士而不是传统的坐骑？",a="雷霆崖陡峭的悬崖面和极高的海拔使得地面交通缓慢而曲折。像风骑士这样的飞行坐骑可以提供进出这座高耸台地城市的快捷、直达的交通方式，而无需通过升降梯。",al={"为什么使用双足飞龙","雷霆崖飞行兽"}}},fx={["704cf2c5"]={q="塔尔是谁？",a="塔尔是牛头人飞行管理员，驻扎在雷霆崖中央高处的栖巢上。作为飞行管理员，他负责照料、繁育和派遣城中的双翼飞龙，为往来卡利姆多各地的旅人提供重要的空中交通。",al={"塔尔是谁","塔尔的身份","塔尔（非玩家角色）"}},a57be0bc={q="塔尔属于哪一方？",a="塔尔坚定效忠雷霆崖和部落。他只向部落成员及其盟友提供飞行坐骑，确保他们能在莫高雷、贫瘠之地和卡利姆多各处的哨站之间迅速通行，同时拒绝联盟使用。",al={"塔尔的阵营","塔尔是部落成员吗","塔尔的忠诚归属"}},e868146f={q="塔尔想做什么？",a="塔尔致力于维持雷霆崖至关重要的空中交通线。他首要的任务是让飞行坐骑吃饱、安稳并随时待命，同时确保部落信使、斥候和冒险者能够迅速安全地穿越卡利姆多崎岖的广袤土地。",al={"塔尔想做什么","塔尔的动机","塔尔的目标"}},dfa35811={q="塔尔为什么在这里？",a="塔尔照料着雷霆崖顶端的栖巢，因为这座城市高耸的台地非常适合起飞和降落。从这处中央高峰出发，他的飞行坐骑可以乘上高空上升气流，载着乘客飞越莫高雷平原及更远的地方。",al={"塔尔为何在雷霆崖","塔尔的栖巢位置","为何在这里"}}},fp="3,218,24.534.0,41.174.0,30.158.0,55.237.0"}
P.entries["npc:talen"] = {n="塔尔伦",s="塔尔伦是一位暗夜精灵业余考古学家，他在灰谷西北部的佐拉姆海岸附近扎营。尽管附近潜伏着纳迦和部落前哨站带来的持续威胁，他仍致力于发掘埋藏在海岸沿线的古代卡多雷遗物。",h="塔尔伦是一位暗夜精灵业余考古学家，他在灰谷西北部的佐拉姆海岸附近扎营。尽管附近潜伏着纳迦和部落前哨站带来的持续威胁，他仍致力于发掘埋藏在海岸沿线的古代卡多雷遗物。",kw={"古代雕像","考古学家","灰谷","鲁泽尔","塔尔伦","佐拉姆海岸"},ang={["faction:Alliance"]="塔尔伦为联盟旅行者在灰谷北部充满争议的区域提供了一个宝贵的现场联络点，距离迈斯特拉岗哨并不远。",["race:NightElf"]="对于卡多雷而言，佐拉姆海岸是关于大分裂的惨痛记忆；塔尔伦代表了一种渴望，即保护和找回那些在古代沿海庄园滑入无尽之海时遗失的遗产。"},sec={{t="海岸学者",b="塔尔伦在佐拉姆海岸边缘的一个小营地安营扎寨，他每天都在钻研历史古迹，而不是投身战争。尽管灰谷的荒野充满了领土冲突和敌对的海岸居民，但塔尔伦始终专注于从淹没在波涛与沙滩之下的废墟中收集失落已久的财宝。他非常依赖路过的冒险者去对抗凶猛的怒鳍纳迦，并找回难以捉摸的神器——包括完整的古代雕像，以及被纳迦领袖鲁泽尔持有的佐拉姆之戒。"}},faq={{q="塔尔伦是谁？",a="塔尔伦是一位暗夜精灵学者和业余考古学家，住在灰谷佐拉姆海岸附近的一个小营地。他没有担任哨兵或士兵，而是研究埋藏在海岸沿线的古代遗物。",al={"这个暗夜精灵是谁","塔尔伦 灰谷","塔尔伦 佐拉姆海岸"}},{q="为什么塔尔伦在佐拉姆海岸附近露营？",a="他正在考察佐拉姆海岸沉没的废墟和岸边，以发掘古代卡多雷文物。由于海滩上爬满了暴力的纳迦，且毗邻部落的前哨站佐拉姆加，他便留在一个远离主要海岸线的隐蔽小营地里。",al={"为什么塔尔伦在这里","塔尔伦的目的"}},{q="塔尔伦需要什么神器？",a="塔尔伦招募旅行者在海岸线上搜寻被冲上岸的古代雕像，并委托他们猎杀附近离岸岛屿上强大的纳迦鲁泽尔，以取回佐拉姆之戒，这是解开古代雕像锁的关键。",al={"塔尔伦的任务","塔尔伦需要什么","鲁泽尔任务"}},{q="塔尔伦对部落怀有敌意吗？",a="虽然塔尔伦与暗夜精灵结盟，但他主要是一名学者，除非受到挑衅或先被攻击，否则他不会主动攻击部落旅行者。",al={"塔尔伦会攻击部落吗","部落对塔尔伦友好吗"}}},fx={["76deb443"]={q="塔尔伦属于哪一方？",a="塔尔伦是一名驻扎在灰谷的暗夜精灵，立场倾向联盟。虽然他主要专注于学术考古，而非军事行动，但他忠于自己的族人及其盟友。部落旅人若威胁到他，会发现他会奋起自卫；但他真正关心的仍是周围沙地中埋藏的遗物，而非公开交战。",al={"塔尔伦的阵营","塔尔伦是联盟成员吗","塔尔伦的忠诚归属"}}},fp="5,247,20.541.0,13.218.0,43.270.0,31.240.0,30.153.0"}
P.entries["npc:tallonkai-swiftroot"] = {n="塔隆凯·捷根",s="塔隆凯·捷根是居住在泰达希尔多兰纳尔的一名暗夜精灵。他十分担心不断蔓延并侵蚀着巨枝的腐化，因此招募年轻的冒险者去寻回附魔的圣物，并遏制那些蹂躏森林的邪恶势力。",h="塔隆凯·捷根是居住在泰达希尔多兰纳尔的一名暗夜精灵。他十分担心不断蔓延并侵蚀着巨枝的腐化，因此招募年轻的冒险者去寻回附魔的圣物，并遏制那些蹂躏森林的邪恶势力。",kw={"多兰纳尔","摄梦符","ferocitas","塔隆凯·捷根","泰达希尔","twisted hatred"},ang={["class:Druid"]="塔隆凯所关注的是那些将心智安全地与翡翠梦境相连的圣物，这使得他的请求与德鲁伊的精神传统有着深刻的联系。",["race:NightElf"]="塔隆凯·捷根代表了保护泰达希尔脆弱的早年时期所需的警惕，他要求年轻的卡多雷清除在他们新家扎根的腐化。"},sec={{t="多兰纳尔的哨兵",b="塔隆凯·捷根居住在多兰纳尔的林冠定居点，时刻注视着周围的森林。和许多生活在这棵新生的世界之树枝叶下的暗夜精灵一样，他对野生动物的不寻常躁动，以及在定居点边缘聚集的令人不安的阴影感到担忧。"},{t="林冠中的威胁",b="塔隆凯指引冒险者去对抗那些扰乱泰达希尔安宁的邪恶实体。他所关切的事项包括：本为保护沉睡的德鲁伊而制作的翡翠摄梦符受到了腐化；凶残的Gnarlpine熊怪屈服于某种黑暗的疾病；以及由“梦境吞噬者”Ferocitas领导的受腐化的Gnarlpine秘术师。对塔隆凯而言，清除这些动乱对于保卫卡多雷脆弱的家园至关重要。"}},faq={{q="塔隆凯·捷根是谁？",a="塔隆凯·捷根是一位驻扎在泰达希尔枝叶上多兰纳尔的暗夜精灵任务发布者，致力于保护该定居点免受当地威胁的侵害。",al={"塔隆凯是谁","塔隆凯·捷根","多兰纳尔任务发布者"}},{q="我可以在哪里找到塔隆凯·捷根？",a="他位于多兰纳尔镇，那是泰达希尔幽影谷外的一座核心暗夜精灵村庄。",al={"塔隆凯的位置","在哪里找到塔隆凯","寻找塔隆凯·捷根"}},{q="塔隆凯会发布什么任务？",a="他请求旅行者从Gnarlpine熊怪手中取回翡翠摄梦符，击败Gnarlpine熊怪“梦境吞噬者”Ferocitas，并前往Twisted Hatred中地狱石的洞穴里杀死萨特Lord Melenas。",al={"塔隆凯的任务","塔隆凯想要什么"}},{q="他为什么关心这些摄梦符？",a="摄梦符是与翡翠梦境相连的暗夜精灵神圣护身符，用于抵御梦魇和黑暗幻象。它们被敌对生物窃取和腐化，对当地的德鲁伊和泰达希尔的居民构成了精神上的危险。",al={"翡翠摄梦符背景故事","为什么是摄梦符"}},{q="“梦境吞噬者”Ferocitas是谁？",a="“梦境吞噬者”Ferocitas是Starbreeze以北一群受腐化的Gnarlpine秘术师的首领。他从塔隆凯的摄梦符上偷走了翡翠，并将其戴在项链上，在夜色中发出绿色的光芒。",al={"ferocitas是谁","ferocitas背景故事"}},{q="是什么导致了塔隆凯所对抗的动乱？",a="一种日益严重的疾病和非自然的腐化已经渗入了泰达希尔，导致像Gnarlpine熊怪这样原本温顺的生物陷入了暴力的疯狂。",al={"为什么熊怪会发疯","twisted hatred背景故事"}}},fx={cb092b62={q="塔隆凯·捷根属于哪一方？",a="塔隆凯坚定地支持达纳苏斯的暗夜精灵和联盟。他驻扎在多兰纳尔，致力于保护泰达希尔日渐繁荣的聚居地免受腐化侵扰，并对付林枝间受惊扰的野兽。",al={"塔隆凯·捷根的阵营","塔隆凯效忠于谁","塔隆凯·捷根的忠诚归属"}},ea33b78b={q="塔隆凯·捷根想做什么？",a="塔隆凯想守护多兰纳尔，并安抚泰达希尔遭腐化的野生生物。他寻求找回被受污染的粗棘熊怪偷走的神圣翡翠捕梦网，并要求铲除费罗西塔斯·梦魇吞噬者等邪恶威胁，以及那些以仇恨毒害森林的腐化萨特。",al={"塔隆凯想做什么","塔隆凯的目标","塔隆凯的动机"}},bffc0ef8={q="塔隆凯·捷根为什么在多兰纳尔？",a="塔隆凯驻扎在多兰纳尔，监视周边荒野日益加剧的骚乱。随着堕落的熊怪和凶恶的野兽威胁着泰达希尔的道路与聚居地，他留在镇上招募有能力的冒险者，共同打击森林中的祸患。",al={"塔隆凯为什么在这里","塔隆凯·捷根为什么在多兰纳尔","是什么让塔隆凯来到多兰纳尔"}}},fp="19,238,22.323.0,21.396.0,27.158.0,37.113.0,31.214.0,44.242.0,33.210.0,52.159.0"}
P.entries["npc:tallow"] = {n="塔隆",s="Tallow是一名驻扎在希尔斯布莱德丘陵的塔伦米尔加固定居点中的被遗忘者战士。他效忠于黑暗女王和部落，守护着竞争激烈的前线，协助组织对当地联盟威胁的打击。",h="Tallow是一名驻扎在希尔斯布莱德丘陵的塔伦米尔加固定居点中的被遗忘者战士。他效忠于黑暗女王和部落，守护着竞争激烈的前线，协助组织对当地联盟威胁的打击。",kw={"被遗忘者","希尔斯布莱德丘陵","部落战士","tallow","塔伦米尔","落锤之势"},ang={["faction:Horde"]="Tallow为渴望削弱希尔斯布莱德丘陵全境人类势力的部落勇士们提供必要的前线任务。",["race:Undead"]="像塔伦米尔的许多被遗忘者一样，Tallow为了扩大幽暗城在奥特兰克山脉以南的统治权而战斗。"},sec={{t="塔伦米尔之刃",b="Tallow位于塔伦米尔的核心地带，他与其他被遗忘者和部落部队一道，在希尔斯布莱德丘陵坚守阵地。该地区冲突不断，处于附近的南海镇人类、游荡的辛迪加不法之徒以及敌对野生生物的夹缝之中。Tallow负责指引有能力的冒险者进入前线，测试他们对抗阿拉希高地的石拳食人魔的实力，随后派遣他们去支援被围困的落锤镇前哨站。"}},faq={{q="Tallow是谁？",a="Tallow是一名驻扎在希尔斯布莱德丘陵的塔伦米尔的被遗忘者战士，担任该地区部落勇士的组织者和任务发布者。",al={"tallow是谁","tallow背景故事","塔伦米尔的tallow"}},{q="在哪里可以找到Tallow？",a="他位于希尔斯布莱德丘陵北部的被遗忘者控制城镇——塔伦米尔。",al={"tallow在哪里","tallow位置","找到tallow"}},{q="Tallow提供哪些任务？",a="Tallow以指引部落冒险者执行“落锤之势”任务而闻名，他派遣战士们在阿拉希高地证明自己对抗石拳食人魔的实力，然后再向被围困的落锤镇前哨站的杜拉姆法尔报告。",al={"tallow任务","落锤之势任务"}},{q="塔伦米尔在冲突中扮演什么角色？",a="塔伦米尔是希尔斯布莱德丘陵主要的北部部落据点，时刻面临着与南部人类堡垒南海镇的小规模冲突和全面战争。",al={"塔伦米尔为什么重要","塔伦米尔的角色"}}},fx={df176dd7={q="Tallow 属于哪一方？",a="Tallow 为被遗忘者以及更广泛的部落效力。他驻扎在塔伦米尔，与不死族守军并肩作战，在希尔斯布莱德抵御南海镇的敌对人类势力，以及威胁部落南部边境的地区性危险。",al={"tallow 属于哪个阵营","tallow 是部落的吗","tallow 的效忠对象"}},cc135250={q="Tallow 想要什么？",a="作为驻守塔伦米尔前线的战士，Tallow 致力于确保被遗忘者聚居地的安全，并削弱希尔斯布莱德各地的敌人。他指挥有能力的部落勇士打击迫近的威胁，包括派遣冒险者执行“锤子可能会落下”等危险任务，以削弱敌对势力。",al={"tallow 的目标","tallow 在做什么","tallow 的动机"}},b53e5a72={q="Tallow 为什么在塔伦米尔？",a="塔伦米尔是被遗忘者在希尔斯布莱德丘陵的主要据点，始终承受着来自南海镇联盟以及其他敌对势力的压力。Tallow 作为战士驻守于此，负责保卫城镇、协调军事行动，并招募途经的部落战士来加强前线力量。",al={"tallow 为什么在这里","tallow 与塔伦米尔","tallow 在希尔斯布莱德的职责"}}},fp="6,250,22.463.0,14.158.0,24.123.0,30.241.0,43.185.0"}
P.entries["npc:talvash-del-kissel"] = {n="塔瓦斯德·基瑟尔",s="塔瓦斯德·基瑟尔是一位运气不佳的侏儒珠宝匠，他在诺莫瑞根陷落后被迫逃离，现在居住在铁炉堡的秘法区。由于失去了家园，他不仅背负着沉重的债务，还饱受各种流言蜚语的困扰。他正在寻找有能力的冒险者，希望能帮他找回遗失的宝藏并修复破碎的圣物。他那双对珍稀宝石和古代饰品极其敏锐的眼睛，使他成为了那些深入奥达曼探险者的重要联络人。",h="塔瓦斯德·基瑟尔是一位运气不佳的侏儒珠宝匠，他在诺莫瑞根陷落后被迫逃离，现在居住在铁炉堡的秘法区。由于失去了家园，他不仅背负着沉重的债务，还饱受各种流言蜚语的困扰。他正在寻找有能力的冒险者，希望能帮他找回遗失的宝藏并修复...",kw={"基瑟尔","诺莫瑞根","铁炉堡","珠宝匠","mystic ward","破碎的项链","塔瓦斯德","奥达曼"},ang={["faction:Alliance"]="深入奥达曼或诺莫瑞根废墟的联盟冒险者会发现，塔瓦斯德是修复古代珠宝和找回遗失侏儒传家宝的重要联络人。",["race:Gnome"]="塔瓦斯德是一个鲜明的写照，提醒着人们诺莫瑞根的失陷是如何粉碎了普通平民的生活，将一位大师级工匠沦为在铁炉堡勉强度日的流亡者。"},sec={{t="从工匠到流亡负债者",b="塔瓦斯德曾经是诺莫瑞根技术中心一位受人尊敬的珠宝匠，但当穴居人占领了这座地下城市时，他的生计和家园一同化为了乌有。他随着幸存的难民逃到了矮人首都铁炉堡，并在秘法区安了营。不幸的是，移居并未给他带来好运。关于他经营不善和欠债不还的流言接踵而至，使这位工匠陷入了严重的财政危机。由于无法通过常规手段重建生意，塔瓦斯德不得不依靠自由冒险者来帮他找回资产并挽回受损的名声。"},{t="奥达曼的圣物与侏儒工艺",b="尽管遭遇不幸，塔瓦斯德的宝石切割精度和鉴定能力却丝毫未减。当探险者在荒芜之地深入奥达曼的泰坦金库，并发掘出一条破碎的远古项链时，塔瓦斯德被证明是东部王国极少数能够理解其中错综复杂附魔的工匠之一。修复这种力量需要稀有的组件和艰苦的劳动，但塔瓦斯德渴望重操旧业——既是为了还清债务，也是为了证明他那持久不变的技艺。"}},faq={{q="塔瓦斯德·基瑟尔是谁？",a="塔瓦斯德是一位生活在铁炉堡秘法区的流亡侏儒珠宝匠。在诺莫瑞根陷落后，他流离失所，如今正挣扎于沉重的债务和挥之不去的流言之中，雇佣冒险者来帮助修复神器并结清账目。",al={"塔瓦斯德是谁","塔瓦斯德·基瑟尔","塔瓦斯德"}},{q="我在哪里可以找到塔瓦斯德？",a="塔瓦斯德位于铁炉堡的秘法区，就在矮人首都的池塘和魔法商店附近。",al={"塔瓦斯德的位置","塔瓦斯德在哪里","寻找塔瓦斯德·基瑟尔"}},{q="他在诺莫瑞根的生意发生了什么？",a="在诺莫瑞根沦陷前，塔瓦斯德在那里经营珠宝生意。当穴居人入侵导致城市陷落后，他失去了一切。随后的流言蜚语和不幸的遭遇让他背负了巨额债务，困在铁炉堡。",al={"为什么塔瓦斯德破产了","塔瓦斯德的债务","塔瓦斯德发生了什么"}},{q="塔瓦斯德与奥达曼有什么联系？",a="在奥达曼古老挖掘场中找到破碎能量源的探险者会被指引去找塔瓦斯德。他在宝石和附魔方面的专业知识使他能够为那些能够收集到缺失部件的冒险者重建那条破碎的项链。",al={"塔瓦斯德 奥达曼","奥达曼项链","破碎的项链任务"}},{q="塔瓦斯德与诺莫瑞根的任务有关系吗？",a="是的。他参与了从那座废墟之城中收回遗失个人物品的任务，包括在诺莫瑞根撤离期间遗留下来的戒指和装置。",al={"塔瓦斯德 诺莫瑞根","戒指的回归任务"}},{q="他的名字起源于哪里？",a="塔瓦斯德·基瑟尔是暴雪任务设计师肖恩·卡恩斯在加入《魔兽世界》开发团队之前，玩《无尽的任务》时所使用的侏儒法师角色的名字。",al={"塔瓦斯德彩蛋","塔瓦斯德名字起源","肖恩·卡恩斯"}}},fx={["4febcc43"]={q="塔瓦斯德·基瑟尔属于哪一方？",a="塔瓦斯坚定地支持联盟和流离失所的侏儒同胞。尽管他手头拮据，在铁炉堡独自经营，他的交易和忠诚始终完全属于联盟。",al={"塔瓦斯德·基瑟尔属于哪个阵营","塔瓦斯是联盟的吗","塔瓦斯的忠诚归属"}},["3a8c1c09"]={q="塔瓦斯德·基瑟尔想要什么？",a="塔瓦斯急于还清巨额债务，重建自己的声誉。诺莫瑞根陷落后，关于他的生意毁于一旦的传言不断，他如今转而经营稀有珠宝、古代遗物和知识，以挽回失去的财富。",al={"塔瓦斯想要什么","塔瓦斯德·基瑟尔的目标","塔瓦斯的动机"}},["762fb8e0"]={q="塔瓦斯德·基瑟尔为什么在铁炉堡？",a="和许多侏儒一样，诺莫瑞根陷落于穴居人和辐射之手后，塔瓦斯便逃离了家园。他在铁炉堡的 Mystic Ward 避难，和学者及附魔师一起工作，试图凭借自己的手艺和奥术知识进行交易，同时躲避债主。",al={"塔瓦斯为什么在这里","塔瓦斯为什么在 mystic ward","塔瓦斯为什么离开诺莫瑞根"}}},fp="18,412,29.611.0,35.495.0,26.241.0,25.123.0,44.202.0,40.250.0,56.157.0,31.175.0"}
P.entries["npc:tammra-windfield"] = {n="塔姆拉·荒原",s="塔姆拉·荒原是烈日石居的一位牛头人居民，居住在石爪山脉的高处。她深刻理解大地的平衡，引导部落旅行者尊重自然的复兴循环，并在群峰之间点燃希望。她既关心未开化荒野的健康，也关心她族人的安全。",h="塔姆拉·荒原是烈日石居的一位牛头人居民，居住在石爪山脉的高处。她深刻理解大地的平衡，引导部落旅行者尊重自然的复兴循环，并在群峰之间点燃希望。她既关心未开化荒野的健康，也关心她族人的安全。",kw={"重生的循环","卡娅","新生命","石爪山脉","烈日石居","塔姆拉","牛头人","荒原"},ang={["class:Druid"]="她对重生循环和培育新生命的强调反映了德鲁伊教义的核心原则，使她的请求与荒野守护者们产生深刻的共鸣。",["faction:Horde"]="在石爪山脉的争夺领土上，塔姆拉帮助维护烈日石居，使其成为部落旅行者安全且持久的立足点。",["race:Tauren"]="塔姆拉体现了牛头人对大地母亲的承诺，展示了即使远离莫高雷，灵性上的敬畏是如何转化为现实世界的修复工作的。"},sec={{t="烈日石居的守望者",b="烈日石居是石爪山脉崎岖峰峦中部落的一处重要避难所，周围环绕着敌对的鹰身人、荆棘谷地精伐木工以及潜伏的掠食者。塔姆拉·荒原是该定居点的看护者之一，密切注视着山区荒野和穿过此地的旅行者。她温柔的举止之下，隐藏着在这片崎岖土地上维持家园所需的坚定意志。"},{t="培育大地",b="和她的许多族人一样，塔姆拉通过观察自然界中生长与衰败的恒定节律来向大地母亲致敬。通过她托付给旅行者的任务——例如照料重生的循环并带来新的生命——她致力于对抗冲突和剥削给石爪山脉带来的破坏。对塔姆拉来说，保护这片土地需要积极的疗愈，确保生命即使在伤痕累累的山地土壤中也能繁茂生长。"},{t="亲情与警惕",b="除了对周围荒野的灵性职责外，塔姆拉还深切关心着那些在石爪山脉险峻小径上冒险的同伴和族人。当有消息传出旅行者或家人在山崖间失踪时，她总是最早寻求可靠援助的人之一。对塔姆拉来说，烈日石居的延续既依赖于与自然的和谐，也依赖于相互的保护和忠诚。"}},faq={{q="塔姆拉·荒原是谁？",a="塔姆拉·荒原是一位居住在石爪山脉烈日石居的牛头人任务发布者。她致力于维护该定居点的福祉、山地景观的自然循环以及同路旅行者的生存。",al={"塔姆拉是谁","塔姆拉·荒原","烈日石居 塔姆拉"}},{q="我在哪里可以找到塔姆拉·荒原？",a="她位于烈日石居内，这是一个隐藏在石爪山脉西部高地的部落营地，可以通过主山谷道路的一条山路到达。",al={"塔姆拉·荒原位置","塔姆拉在哪里","寻找塔姆拉·荒原"}},{q="塔姆拉提供哪些任务？",a="塔姆拉的任务主要关注复兴和她族人的福祉，包括“重生的循环”和“新生命”，她还会接待在“卡娅还活着”中报告亲人生存情况的旅行者。",al={"塔姆拉任务","塔姆拉·荒原任务列表"}},{q="塔姆拉在烈日石居扮演什么角色？",a="塔姆拉担任社区支柱和灵性照料者，指导冒险者恢复周围荒野的活力，并维护让这个偏远哨所保持安全的纽带。",al={"塔姆拉做什么","塔姆拉角色"}},{q="为什么塔姆拉关心自然循环？",a="在牛头人文化中，维持平衡需要培育大地母亲的死亡与再生循环。由于外部势力和山地野兽威胁着该地区，塔姆拉寻求培育新的生命来治愈这片伤痕累累的荒野。",al={"重生的循环背景","为什么要在石爪山脉重生"}},{q="塔姆拉对联盟玩家友好吗？",a="不友好。烈日石居是专门的部落哨所，塔姆拉隶属于雷霆崖和部落，这使她对联盟入侵者持敌对态度。",al={"塔姆拉是敌对的吗","联盟可以和塔姆拉交谈吗"}}},fx={["590ef84e"]={q="塔姆拉·荒原为什么在烈日石居？",a="塔姆拉居住在烈日石居，照料大地的灵魂，并观察石爪山脉的自然生命循环。她从这座高处的圣所守望着饱受困扰的山崖，并向能够帮助当地在艰难中孕育新生的旅人伸出援手。",al={"塔姆拉为什么在这里","塔姆拉·荒原为什么在烈日石居","塔姆拉为什么在石爪山脉"}}},fp="16,355,20.421.0,18.436.0,21.420.0,24.239.0,34.190.0,30.199.0,42.190.0,45.241.0,39.148.0"}
P.entries["npc:tannok-frosthammer"] = {n="塔诺克·霜锤",s="塔诺克·霜锤是一位居住在丹莫罗卡拉诺斯外雷酒酿制厂的矮人。他是从寒脊山谷运来货物的焦虑接收者，由于穴居人攻击切断了通往安威玛尔的道路，他深感不安。",h="塔诺克·霜锤是一位居住在丹莫罗卡拉诺斯外雷酒酿制厂的矮人。他是从寒脊山谷运来货物的焦虑接收者，由于穴居人攻击切断了通往安威玛尔的道路，他深感不安。",kw={"安威玛尔","寒脊山","酿制厂","霜锤","卡拉诺斯","塔诺克","雷酒","穴居人"},ang={["faction:Alliance"]="塔诺克的受阻货物凸显了即便是像卡拉诺斯这样的核心定居点，也正承受着日益严重的穴居人入侵所带来的压力。",["race:Dwarf"]="对于离开安威玛尔走向广阔世界的矮人来说，为雷酒酿制厂的塔诺克运送补给是他们迈向丹莫罗核心地区的第一步。"},sec={{t="切断的补给线",b="塔诺克·霜锤驻扎在卡拉诺斯的雷酒酿制厂附近，密切关注着来往的货物和当地的消息。突然涌现的穴居人成群结队地占据了寒脊山小径，切断了寒脊山谷的正常交通，导致塔诺克与安威玛尔定居点之间的常规通讯中断。塔诺克依靠像侏儒技师汉兹·跳链这样的信使，通过危险的雪山山口运送重要物资和消息。他的担忧代表了许多铜须矮人的心声，因为地下的威胁正在不断逼近他们的家门口。"}},faq={{q="塔诺克·霜锤在哪里？",a="塔诺克·霜锤位于丹莫罗卡拉诺斯主要十字路口东侧的雷酒酿制厂外。",al={"塔诺克位置","塔诺克在哪里","寻找塔诺克·霜锤"}},{q="为什么塔诺克担心寒脊山谷？",a="塔诺克对肆虐寒脊山小径的穴居人深感忧虑。这条被占领的通道切断了安威玛尔山谷定居点与丹莫罗其他地区之间的正常通讯与贸易。",al={"塔诺克的担忧","为什么塔诺克很担心","寒脊山小径穴居人"}},{q="塔诺克与寒脊山谷里的谁合作？",a="塔诺克接收来自汉兹·跳链的货物，这位侏儒供应商驻扎在寒脊山谷，负责招募路过的旅行者穿过危险的山路运送物资。",al={"塔诺克的供应商","汉兹·跳链的货物","谁给塔诺克供货"}}},fx={["22aa1045"]={q="塔诺克·霜锤是谁？",a="塔诺克·霜锤是居住在卡拉诺斯的铁炉堡矮人，驻扎在雷酒酿制厂。他协助监管丹莫罗当地货物和补给的流通，维系中心城镇与寒脊山谷等偏远哨站之间至关重要的后勤联系。",al={"塔诺克是谁","塔诺克·霜锤的背景","塔诺克的身份"}},["93f9fc20"]={q="塔诺克·霜锤属于哪一方？",a="塔诺克是铁炉堡的忠诚臣民，也是坚定的联盟成员。他最关心的是丹莫罗居民的安全与福祉，并确保他们的贸易路线在雪地威胁日益加剧时仍能畅通。",al={"塔诺克属于哪个阵营","塔诺克是联盟的吗","塔诺克·霜锤的效忠归属"}},eebd916b={q="塔诺克·霜锤为什么在这里？",a="塔诺克在卡拉诺斯的雷酒酿制厂经营事务。他留在这里接收重要货物，并与远方的供应商保持联系；然而，寒脊山小径近期发生的动乱切断了货运，让他焦急地等待消息。",al={"塔诺克为什么在卡拉诺斯","塔诺克为什么在这里","塔诺克·霜锤的职责"}}},fp="18,250,21.582.0,36.138.0,45.209.0,46.180.0"}
P.entries["npc:taragaman-the-hungerer"] = {n="饥饿者塔拉加曼",s="饥饿者塔拉加曼是一个潜伏在奥格瑞玛下方怒焰裂谷熔岩洞穴中的魁梧地狱卫士。尽管他作为灼热利刃邪教背后的恶魔主宰而广受恐惧，但他在这火焰深处的存在其实有着更黑暗、更具欺骗性的目的。部落寻求消灭他，以根除毒害这座城市腹地的恶魔污染。",h="饥饿者塔拉加曼是一个潜伏在奥格瑞玛下方怒焰裂谷熔岩洞穴中的魁梧地狱卫士。尽管他作为灼热利刃邪教背后的恶魔主宰而广受恐惧，但他在这火焰深处的存在其实有着更黑暗、更具欺骗性的目的。部落寻求消灭他，以根除毒害这座城市腹地的恶魔...",kw={"巴扎兰","恶魔","地狱卫士","饥饿者","耶戈什","奥格瑞玛","怒焰裂谷","灼热利刃","塔拉加曼"},ang={["class:Warlock"]="当术士们在上方的大断崖中研习黑暗技艺时，像塔拉加曼这样野蛮且充满敌意的地狱卫士对他们隐秘技艺的保密性和安全性构成了无法控制的危险。",["class:Warrior"]="面对塔拉加曼，需要坚定地抵挡粉碎性的物理打击，并避免被他那残酷的上勾拳击飞到周围的岩浆中。",["faction:Horde"]="对于部落的年轻战士和施法者来说，在奥格瑞玛下方的深处击杀塔拉加曼，是保护其主城免受恶魔腐化的重要试炼。"},sec={{t="下方的野兽",b="饥饿者塔拉加曼在怒焰裂谷的岩浆池中徘徊，对奥格瑞玛的安全构成了直接且可怕的威胁。对于许多被派往黑暗裂谷的斥候和年轻战士来说，这名恶魔地狱卫士看起来就是灼热利刃邪教徒的核心头目，他挥舞着地狱般的力量，屈服意志薄弱者，并腐化萨尔堡垒下方的地下通道。"},{t="致命的诱饵",b="尽管塔拉加曼有着威风凛凛的举止和毁灭性的残暴，但他并非指挥灼热利刃的幕后主使。该邪教真正的领导权掌握在隐于暗处的萨特巴扎兰和术士祈求者耶戈什手中。对于这些工于心计的策划者来说，这名高大的地狱卫士不过是可以牺牲的诱饵——一个旨在将有抱负的部落保卫者引诱至灼热火山深处，以便将其屠戮的怪物幌子。"}},faq={{q="饥饿者塔拉加曼是什么种类的恶魔？",a="塔拉加曼是一名地狱卫士，是燃烧军团中残酷的恶魔突击士兵。他挥舞着沉重的近战打击，并使用火焰魔法在怒焰裂谷的岩浆洞穴中粉碎入侵者。",al={"塔拉加曼的种族","塔拉加曼的恶魔类型","塔拉加曼是恶魔吗"}},{q="饥饿者塔拉加曼是灼热利刃邪教的领袖吗？",a="人们普遍认为他是。塔拉加曼是怒焰裂谷中最令人恐惧的恶魔力量，部落的年轻保卫者们被派去击杀他，视其为该邪教的主宰，尽管这个裂谷所隐藏的秘密远不止一个地狱卫士那么简单。",al={"谁领导灼热利刃","塔拉加曼是首领吗","塔拉加曼邪教领袖"}},{q="为什么部落想要塔拉加曼死？",a="部落绝不允许一股活跃的恶魔势力在他们的主城下方滋生。塔拉加曼的地狱腐化正威胁着从内部毒害奥格瑞玛，消灭他是确保街道下方洞穴通道安全的关键。",al={"为什么要击杀塔拉加曼","击杀野兽任务背景","塔拉加曼对奥格瑞玛的威胁"}},{q="在哪里可以找到塔拉加曼？",a="塔拉加曼栖息在怒焰裂谷深处，位于奥格瑞玛内部大断崖可通往的地下火山隧道中。",al={"塔拉加曼位置","塔拉加曼在哪里","怒焰裂谷的塔拉加曼"}},{q="塔拉加曼的心脏会怎样？",a="胜利的冒险者会挖出饥饿者塔拉加曼的心脏，作为这只野兽死亡的证明，以完成清除奥格瑞玛下方滋生的恶魔先锋的任务。",al={"塔拉加曼的心脏","塔拉加曼之心","击杀野兽心脏"}},{q="塔拉加曼在战斗中如何作战？",a="塔拉加曼依赖毁灭性的物理攻击、能将敌人击飞的强力上勾拳，以及偶尔爆发的、灼烧靠近他的任何人的火焰新星。",al={"塔拉加曼技能","塔拉加曼首领战","塔拉加曼机制"}}},fx={["512c0cfb"]={q="饥饿者塔拉加曼属于哪一方？",a="塔拉加曼与潜伏在奥格瑞玛地下的火刃氏族教徒结盟，从内部威胁着部落。",al={"塔拉加曼属于哪个阵营","塔拉加曼效忠于谁","塔拉加曼是火刃氏族的吗"}},["1dbae35b"]={q="饥饿者塔拉加曼为什么在怒焰裂谷？",a="塔拉加曼居于怒焰裂谷的炽热深处，在奥格瑞玛地下散播恶魔腐化。",al={"塔拉加曼为什么在这里","塔拉加曼在怒焰裂谷做什么","塔拉加曼为什么在奥格瑞玛"}},["376a0125"]={q="饥饿者塔拉加曼与谁有关联？",a="塔拉加曼与怒焰裂谷中的火刃氏族教团有关。要查明是谁在幕后指使其阴谋，就必须深入调查裂谷。",al={"塔拉加曼与谁共事","塔拉加曼的盟友","塔拉加曼与巴扎兰"}},["5af082b3"]={q="饥饿者塔拉加曼为何令人畏惧？",a="塔拉加曼是一头高耸的恶魔恐怖存在，潜伏在部落首都正下方，因此令人畏惧。他的恶魔影响力威胁着要腐化奥格瑞玛的居民，而他残暴的肉体力量也让他在那些奉命进入裂谷将其铲除的年轻守卫中恶名昭彰。",al={"塔拉加曼为何出名","塔拉加曼危险吗","为什么要畏惧塔拉加曼"}}},fp="22,358,15.413.0,12.450.1,45.187.0,63.230.0,39.244.0,29.144.0,34.179.0,35.180.0"}
P.entries["npc:targorr-the-dread"] = {n="可怕的塔格尔",s="可怕的塔格尔是一位臭名昭著的黑石兽人行刑官，被关押在暴风城监狱的深处。他因对俘虏的暴风城士兵实施残忍的拷问而闻名，由于官僚主义的无能与腐败，他的处决被无限期推迟。当暴风城监狱在迪菲亚潜行者的煽动下爆发暴乱时，塔格尔趁机越狱，并与那些骚乱的囚犯结成了同伙。",h="可怕的塔格尔是一位臭名昭著的黑石兽人行刑官，被关押在暴风城监狱的深处。他因对俘虏的暴风城士兵实施残忍的拷问而闻名，由于官僚主义的无能与腐败，他的处决被无限期推迟。当暴风城监狱在迪菲亚潜行者的煽动下爆发暴乱时，塔格尔趁机越...",kw={"伯尔顿","黑石","可怕的","行刑官","加塞尔佐格","湖畔镇","监狱","塔格尔"},ang={["faction:Alliance"]="在暴乱的监狱中解决掉塔格尔，能为湖畔镇那些阵亡的保卫者带来迟到的正义，并有助于遏制首都地下的混乱。",["race:Human"]="对于暴风城的人类——尤其是那些与赤脊山有联系的人来说——塔格尔是王国官僚制度失败所带来的惨痛代价以及黑石兽人持续威胁的化身。"},sec={{t="赤脊山的屠夫",b="在被捕之前，可怕的塔格尔曾在加塞尔佐格督军麾下担任黑石氏族的首席行刑官。他在赤脊山的占领区废墟中活动，即使以黑暗部落那种暴力标准来看，他的残酷手段也显得极其凶残。为了保卫边境而奋战的暴风城卫兵和民兵落入他手中后，都会遭受极其痛苦的折磨并缓慢死去，这使得他的名字成为王国中最令人憎恨的名字之一。"},{t="迟到的正义",b="当联盟部队最终设法活捉了塔格尔时，他被戴上镣铐押往首都，并被关进安保严密的暴风城监狱等待处决。然而，暴风城司法与政治体制内部的腐败阻碍了审判进程。由于受到贪污、无尽的文书工作和玩忽职守的拖累，法庭未能对他下达应有的死刑判决，导致这个嗜血的战争罪犯至今仍被关押在城市地下的牢房里。"},{t="牢狱暴动",b="当迪菲亚潜行者发动那场暴力的越狱行动时，塔格尔看到了机会。他挣脱了牢房，投奔了迪菲亚暴徒，将他所在的牢区变成了屠宰场。随着监狱彻底脱离了典狱官塞尔沃特的控制，诸如湖畔镇之类——依然承受着塔格尔给他们保卫者所带来的痛苦创伤——的城镇开始寻求那些愿意深入暴乱中心，带回这名屠夫首级的冒险者。"}},faq={{q="可怕的塔格尔是谁？",a="可怕的塔格尔是一名黑石兽人，曾任加塞尔佐格督军手下的首席行刑官。他因拷问被俘的暴风城士兵而臭名昭著，后被捕并关押在暴风城监狱中。",al={"塔格尔是谁","塔格尔背景故事","监狱兽人首领"}},{q="为什么塔格尔被捕后没有被处决？",a="尽管塔格尔被捕并被安排接受审判，但暴风城效率低下、机构臃肿且腐败的法律行政体系拖延了整个进程。在监狱暴乱爆发前，他的处决一直被无尽的官僚繁文缛节所耽搁。",al={"为什么他没被杀","为什么塔格尔还活着","暴风城腐败"}},{q="为什么会有兽人与迪菲亚潜行者结盟？",a="塔格尔并不认同迪菲亚潜行者的政治诉求，但在监狱暴乱的混乱中，各色囚犯联合起来对抗狱卒。他与暴徒结盟纯粹是为了确保自己获得自由，并屠杀任何阻挡在他面前的卫兵或冒险者。",al={"迪菲亚为什么和兽人合作","塔格尔迪菲亚盟友","监狱兽人"}},{q="现在是谁想要塔格尔的命？",a="驻扎在赤脊山湖畔镇的卫兵伯尔顿悬赏征集塔格尔的首级。湖畔镇的民众曾饱受塔格尔的残酷迫害，他们迫切希望能看到暴风城法庭未能执行的处决。",al={"谁发布塔格尔任务","卫兵伯尔顿塔格尔","塔格尔悬赏"}},{q="在哪里可以找到塔格尔？",a="塔格尔位于暴风城监狱副本内，与其他的暴乱囚犯一起躲藏在后方的牢区中。",al={"塔格尔在哪里","塔格尔位置","监狱房间"}},{q="塔格尔属于哪个氏族？",a="塔格尔属于黑石兽人，他们是活跃在赤脊山和黑石塔的黑暗部落残党，而非萨尔领导的新部落。",al={"塔格尔氏族","塔格尔是部落吗","黑石塔格尔"}}},fx={eed5e381={q="为什么大家如此畏惧可怕的塔格尔？",a="塔格尔曾是加塞尔佐格将军麾下黑石兽人的最高刽子手，因此声名骇人。他的残忍甚至超出了氏族一贯的野蛮程度。他不让落败的敌人得到光荣的死亡，而是随心所欲地残酷折磨被俘的暴风城守军，因此在赤脊山居民乃至整个王国中臭名远扬。",al={"为什么大家畏惧塔格尔","可怕的塔格尔的名声","塔格尔为何出名"}}},fp="17,376,23.455.0,14.463.0,21.464.0,25.214.0,49.243.0,49.284.0,27.230.0,27.130.0,33.178.0"}
P.entries["npc:tarindrella"] = {n="塔琳德拉",s="塔琳德拉是一位树妖，守护着泰达希尔的幽影谷中那片避风的林地。作为塞纳留斯的女儿，她与暗夜精灵守护者们密切合作，调查侵蚀世界之树野生动物的不自然腐蚀。",h="塔琳德拉是一位树妖，守护着泰达希尔的幽影谷中那片避风的林地。作为塞纳留斯的女儿，她与暗夜精灵守护者们密切合作，调查侵蚀世界之树野生动物的不自然腐蚀。",kw={"奥达希尔","树妖","幽影谷","黑丝","塔琳德拉","泰达希尔","织木"},ang={["class:Druid"]="德鲁伊将树妖视为荒野的同类，对她们推崇备至，因此塔琳德拉关于泰达希尔疾病的指引，是维护平衡的紧急召唤。",["race:NightElf"]="对于在幽影谷开始冒险的年轻暗夜精灵来说，塔琳德拉是他们最早会见到的树妖之一，她体现了卡多雷与塞纳留斯后代之间古老的盟约。"},sec={{t="幽影谷中的塞纳留斯之女",b="树妖是自然的狂热守护者，由半神塞纳留斯所生。虽然许多树妖依然居住在卡利姆多如灰谷等古老的森林深处，但塔琳德拉却栖息在泰达希尔枝干顶端的幽影谷这片受保护的林地中。她充当着荒野之灵与那些刚刚走出奥达希尔、迈出第一步的年轻暗夜精灵保卫者之间的关键桥梁。她最关心的是森林中蔓延的腐化，并委派可靠的冒险者去驱逐当地的害虫，收集有关这场灾难根源的线索。"},{t="调查泰达希尔的腐蚀",b="尽管泰达希尔是暗夜精灵人民的新皇冠，其原始的树林却隐藏着一种意想不到的疾病。曾经平静的熊怪离开了家园，集结成了棘皮熊怪部落；而被邪恶的魔苔所污染的小鬼和鬼卒也出没在幽影谷周围的山丘上。塔琳德拉怀疑这一切变化背后的元凶就是魔苔，于是指引新兵去对抗这些小鬼并带回样本，试图在腐蚀蔓延到年轻树林的避难所之前阻止它。"}},faq={{q="塔琳德拉是谁？",a="塔琳德拉是一位居住在泰达希尔幽影谷的树妖。她协助当地的暗夜精灵监测荒野，并指引年轻的守卫者对抗威胁着世界之树枝干的奇异疾病。",al={"塔琳德拉背景故事","塔琳德拉是谁","幽影谷树妖"}},{q="什么是树妖？",a="树妖是半神塞纳留斯的女儿，也是受过魔法祝福的林地生物。她们拥有暗夜精灵的上半身和小鹿的下半身，作为神圣树林与自然平衡的忠诚守护者，保卫着卡利姆多。",al={"树妖背景故事","什么是树妖","塞纳留斯的女儿"}},{q="为什么塔琳德拉担心幽影谷？",a="即使是在泰达希尔的安全中心，不自然的腐蚀也开始扭曲当地的生物，驱使熊怪集结成敌对的棘皮熊怪部落，并让山丘上充满了被魔苔污染的小鬼。塔琳德拉试图净化这种腐化，保护这片年轻的树林免受蔓延的衰败侵害。",al={"幽影谷腐蚀","塔琳德拉任务","幽影谷出了什么问题"}},{q="她派遣冒险者面对什么威胁？",a="塔琳德拉寻求帮助，以对抗出没在幽影谷的小鬼和鬼卒，并收集它们携带的邪恶魔苔，以确认这是否是腐蚀的根源。",al={"塔琳德拉蜘蛛","黑丝洞任务"}}},fx={af6c0001={q="塔琳德拉属于哪一方？",a="塔琳德拉与卡多雷和塞纳里奥议会同道，与暗夜精灵并肩守护自然。作为塞纳留斯的女儿，她维护自然平衡，并帮助年轻的暗夜精灵冒险者守护泰达希尔免受侵害。",al={"塔琳德拉属于哪个阵营","塔琳德拉效忠于谁","塔琳德拉属于联盟还是部落"}},d6824959={q="塔琳德拉想要什么？",a="塔琳德拉希望根除并净化侵扰泰达希尔枝杈的异常腐化。她委托你调查幽影谷遭污染的野生生物，并对抗在林地树林与巢穴中蔓延的黑暗祸患。",al={"塔琳德拉想要什么","塔琳德拉的目标","塔琳德拉的职责"}},["05d535f9"]={q="塔琳德拉与谁有关联？",a="作为一名林妖，塔琳德拉是半神塞纳留斯的女儿，与林地守护者以及卡利姆多的其他林地精魂同属一脉。她与暗夜精灵和尊崇其父教诲的德鲁伊有着深厚的联系。",al={"塔琳德拉的家族","塔琳德拉的关系","塔琳德拉与谁有亲缘关系"}}},fp="11,240,36.535.0,37.508.0,19.221.0,16.226.0,46.301.0,47.174.0"}
P.entries["npc:tarrel-rockweaver"] = {n="塔雷尔·石纹",s="塔雷尔·石纹是一位焦急的矮人丈夫，驻守在通往米奈希尔港的桥上。他深切地挂念着他的妻子麦琳，她是一位考古学家，加入了勘察员维尔加的挖掘小队前往内地。他守望着道路，希望能有关于她安全的消息。",h="塔雷尔·石纹是一位焦急的矮人丈夫，驻守在通往米奈希尔港的桥上。他深切地挂念着他的妻子麦琳，她是一位考古学家，加入了勘察员维尔加的挖掘小队前往内地。他守望着道路，希望能有关于她安全的消息。",kw={"矮人","挖掘小队","米奈希尔港","麦琳·石纹","塔雷尔·石纹","湿地"},ang={["faction:Alliance"]="对于抵达米奈希尔港的旅者来说，塔雷尔向他们直观地展示了驻扎在荒蛮沼泽沿岸的联盟公民所面临的艰辛。",["race:Dwarf"]="塔雷尔的担忧突显了探险者协会在卡兹莫丹的荒野边境发掘矮人起源这一不懈行动背后的高昂代价。"},sec={{t="桥上的守望",b="当贸易和军事补给穿梭于米奈希尔港时，塔雷尔·石纹在城镇边缘的桥上焦急地守望着。他的妻子麦琳·石纹加入了勘察员维尔加久负盛名的考古探险队，深入湿地。当凶猛的迅猛龙攻陷了挖掘场并切断了常规通讯后，塔雷尔被困在镇上，请求路过的旅者前往东边的维尔加挖掘场侦察，以确保她在那场灾难中幸存下来。"}},faq={{q="塔雷尔·石纹是谁？",a="塔雷尔是一位铁炉堡矮人，目前徘徊在米奈希尔港的入口桥梁附近。他正绝望地等待着有关他妻子麦琳的消息，她为了内地的发掘工作离开了。",al={"塔雷尔·石纹","这个矮人是谁","米奈希尔桥上的矮人"}},{q="为什么塔雷尔要向旅者寻求帮助？",a="在麦琳的考古小队在挖掘场遭遇危险后，他与妻子失去了联系。由于无法擅离职守，他请求路过的冒险者向东前往维尔加挖掘场寻找她。",al={"塔雷尔的任务","寻找挖掘小队","塔雷尔·石纹的任务"}},{q="麦琳·石纹是谁？",a="麦琳·石纹是塔雷尔的妻子，也是隶属于勘察员维尔加挖掘小队的一名考古学家。她在营地遇袭后幸存下来，并与其他幸存者一起躲进了俯瞰挖掘场的一个洞穴中。",al={"麦琳·石纹","塔雷尔的妻子","麦琳是谁"}},{q="塔雷尔的妻子去了哪里？",a="麦琳向东前往湿地，研究古老的泰坦和矮人遗物。在他们的主要挖掘场遇袭后，她和幸存的挖掘者躲进了俯瞰废弃挖掘场的一个洞穴里。",al={"麦琳在哪里","挖掘小队位置","维尔加的避难所"}}},fx={["017f26af"]={q="塔雷尔·石纹属于哪一方？",a="塔雷尔是铁炉堡忠诚的矮人公民，坚定地支持联盟。他驻扎在米奈希尔港外，依靠路过的联盟旅人帮助照看身处沼泽险境中的族人。",al={"塔雷尔·石纹属于哪个阵营","塔雷尔·石纹是联盟的吗"}},["89989482"]={q="塔雷尔·石纹为什么会在米奈希尔港？",a="塔雷尔在通往米奈希尔港的桥上等候，拦下路过的冒险者。野生迅猛龙、黑铁矮人和敌对的穴居人横行沼泽地，他便留在港口附近，希望招募勇敢的旅人去寻找失踪的妻子。",al={"塔雷尔·石纹为什么在这里","塔雷尔·石纹在哪里，为什么","塔雷尔为什么在桥上"}}},fp="17,257,21.489.0,25.183.0,40.217.0,25.214.1,27.209.1"}
P.entries["npc:tatternack-steelforge"] = {n="塔特纳克·钢炉",s="塔特纳克·钢炉是一位驻扎在贫瘠之地严酷大草原上的兽人铁匠，为那些能够处理粗糙金属和对付危险边境动物的旅行者提供工作。他精通钢铁与火焰之道，致力于研究当地矿石，并为部落部队武装起来，以应对平原上的各种威胁。",h="塔特纳克·钢炉是一位驻扎在贫瘠之地严酷大草原上的兽人铁匠，为那些能够处理粗糙金属和对付危险边境动物的旅行者提供工作。他精通钢铁与火焰之道，致力于研究当地矿石，并为部落部队武装起来，以应对平原上的各种威胁。",kw={"贫瘠之地","铁匠","陶拉祖营地","十字路口","矿石","钢炉","塔特纳克"},ang={["faction:Horde"]="塔特纳克在保持部落部队拥有充足武器和补给，以对抗野猪人和半人马等区域性威胁方面发挥着至关重要的作用。",["profession:Blacksmithing"]="对于穿行在贫瘠之地的铁匠来说，塔特纳克是一位志同道合的朋友，他深知在无法无天的边境地带，对优质矿石和精良钢铁的持续需求。"},sec={{t="熔炉旁的兽人",b="在贫瘠之地干旱的广袤土地上，维持部落前哨站的武装绝非易事。塔特纳克·钢炉将他族人传统的金属加工技艺带到了边境，既为了寻找实用的武器，也为了搜寻罕见的地质样本，以巩固部落在面对野兽、半人马突袭者和敌对野猪人时的立足点。"}},faq={{q="谁是塔特纳克·钢炉？",a="塔特纳克·钢炉是一位驻扎在贫瘠之地的兽人武器匠。他通过检查矿物、研究当地矿石，并将可靠的武器交到附近的勇士手中，来帮助部落的守卫者。",al={"塔特纳克是谁","塔特纳克·钢炉背景故事","塔特纳克做什么"}},{q="在哪里可以找到塔特纳克·钢炉？",a="塔特纳克在贫瘠之地内活动，居住在位于中部大草原小径旁的部落营地中。",al={"塔特纳克在哪里","塔特纳克·钢炉位置","塔特纳克坐标"}},{q="塔特纳克提供什么样的任务？",a="塔特纳克主要请求冒险者回收武器，并从贫瘠之地各地找回新鲜的矿石样本，以协助他的锻造工作。",al={"塔特纳克任务","选择武器任务发布者","矿石样本任务"}}},fp="21,291,19.336.0,29.210.0,41.113.0,41.142.0"}
P.entries["npc:tavernkeep-smitts"] = {n="旅店老板斯密茨",s="旅店老板斯密茨是夜色镇Scarlet Raven Tavern的酒保。作为暮色森林社交中心的核心人物，斯密茨掌握着关于城镇流言和未解当地惨剧的百科全书般的知识。他那超群的记忆力和敏锐的观察力，使他成为任何调查该地区黑暗历史的人不可或缺的联络人。",h="旅店老板斯密茨是夜色镇Scarlet Raven...",kw={"夜色镇","暮色森林","哈格德","基特斯","scarlet raven","斯密茨","斯塔文","旅店老板","僵尸果汁"},ang={["class:Rogue"]="调查旧案和阴影人物的潜行者会发现斯密茨是一位理想的情报员，因为他能注意到顾客写了什么、何时陷入恐慌，以及他们留下了什么东西。",["faction:Alliance"]="对于走出阴影森林的联盟旅行者来说，斯密茨提供的不仅是避难所和饮品，还有关于困扰暮色森林的威胁的重要当地情报。"},sec={{t="夜色镇之心",b="在Scarlet Raven Tavern的吧台后，旅店老板斯密茨为疲惫的旅行者、当地镇民以及在暮色森林险境中担惊受怕的守夜人卫兵提供温暖的炉火和饮品。作为镇上资格最老的公众人物之一，斯密茨听到了所有在阴影中流传的传闻。当其他镇民躲在紧锁的百叶窗后时，斯密茨却用务实而敏锐的目光注视着每一个经过他店门的人，留意着异常的举动、匆忙的离去和古怪的顾客。"},{t="斯塔文的记忆",b="斯密茨多年来一直在默默追踪关于斯塔文·密特曼特的传说。多年前，当一个造访的暴风城贵族家庭惨遭屠杀时，斯密茨曾与哈格德元帅一同检查过屠杀现场。斯密茨从惨案现场找回了残缺、沾满泥污的日记书页，但当时调查人员始终无法正式将字迹与斯塔文联系起来。斯密茨多年来一直保存着这些褪色的碎片，坚信残酷的真相终有一天会大白于天下。"},{t="阴影中的常客",b="斯密茨的警觉也延伸到了当前的威胁上。当惊恐万状的隐士基特斯在Scarlet Raven寻求庇护时，斯密茨目睹了他狂乱地在私人日记上写下东西，随后又陷入盲目的恐慌逃离了旅店。当调查者找回这本被遗弃的日记时，斯密茨一眼就认出了它，并指引追踪者前往乌鸦岭，助力揭开困扰这片森林的诅咒事件。"}},faq={{q="我在哪里可以找到旅店老板斯密茨？",a="斯密茨站在位于夜色镇镇中心广场的Scarlet Raven Tavern一楼的柜台后面。",al={"斯密茨位置","旅店老板斯密茨在哪里","scarlet raven酒保"}},{q="斯密茨对斯塔文·密特曼特了解多少？",a="多年前，斯密茨曾陪同哈格德元帅调查造访贵族被屠杀一案。斯密茨在现场发现了泥泞且残缺的书页，并将它们保存了下来。如果有人提供将斯塔文与该罪行联系起来的新证据，斯密茨会交出沾满泥污的日记书页，以便将其送交指挥官阿尔泰娅·埃伯洛克。",al={"斯密茨斯塔文","斯塔文传说斯密茨","沾满泥污的书页斯塔文"}},{q="斯密茨对基特斯了解多少？",a="基特斯曾在Scarlet Raven Tavern待过一段时间，斯密茨曾观察到他在惊恐中疯狂地在日记上写字。当你把基特斯的日记带回旅店时，斯密茨会辨认出它，并指引你向西前往乌鸦岭去追踪他。",al={"斯密茨基特斯","基特斯日记斯密茨","向旅店询问斯密茨"}},{q="斯密茨酿造或需要什么饮品？",a="斯密茨参与了当地混合酒的原料采购，包括派遣冒险者深入受诅咒的荒野采集腐烂之花，以酿造一种被当地人俗称为“僵尸果汁”的强力混合饮品。",al={"僵尸果汁","斯密茨腐烂之花","斯密茨酿造"}},{q="哈格德元帅是谁，斯密茨又是如何认识他的？",a="哈格德元帅是暴风城卫兵的一位老兵，住在这个山丘上一间与世隔绝的小屋里。多年前，他和斯密茨曾共同调查过那起令人毛骨悚然的贵族谋杀案，并因这起悬案建立了交情。",al={"斯密茨哈格德","哈格德联系"}},{q="斯密茨在夜色镇有已知的亲属吗？",a="没听说过。斯密茨独自经营着Scarlet Raven，在夜色镇没有他已知的亲属。",al={"斯密茨亲属","玛丽斯密茨"}}},fx={["9f4b5837"]={q="旅店老板斯密茨是谁？",a="旅店老板斯密茨是夜色镇 Scarlet Raven Tavern 的老板。除了为顾客斟酒、接待那些想躲避暮色森林阴霾的旅人，他还是镇上的非正式历史学家。多年来，他观察着来往旅人和当地居民，对当地传闻、黑暗的民间故事，以及至今仍笼罩着这片地区的往日悲剧都了如指掌。",al={"斯密茨是谁","旅店老板斯密茨","夜色镇旅店老板"}},["657fa8c4"]={q="旅店老板斯密茨支持哪一方？",a="斯密茨坚定地站在夜色镇居民和联盟一边。威胁出现时，他会与哈加德警长等当地守卫密切合作，并指引冒险者去找指挥官阿尔泰娅·埃伯洛克和守夜人。他竭尽所能，保护饱受周边森林中种种恐怖侵扰的社区。",al={"斯密茨的阵营","斯密茨效忠哪一方","斯密茨是联盟的吗"}},["32ff845a"]={q="旅店老板斯密茨为什么会在这里？",a="斯密茨靠经营 Scarlet Raven Tavern 谋生，这里是夜色镇疲惫居民和过路旅人聚集的中心。经营旅店让他得以接触当地各种传闻，也让他近距离见证困扰暮色森林的种种谜团与悲剧。",al={"斯密茨为什么在夜色镇","斯密茨为什么在旅店"}}},fp="17,318,18.511.0,21.474.1,18.433.1,35.138.0,47.323.1,36.272.1,40.201.0,53.222.0,47.118.0"}
P.entries["npc:telf-joolam"] = {n="泰尔夫·祖拉姆",s="泰尔夫·祖拉姆是一名暗矛巨魔萨满祭司，他守护着眠炎圣殿。他指引部落的初学者通过试炼，以与狂暴的火焰元素沟通并驾驭这种力量。",h="泰尔夫·祖拉姆是一名暗矛巨魔萨满祭司，他守护着眠炎圣殿。他指引部落的初学者通过试炼，以与狂暴的火焰元素沟通并驾驭这种力量。",kw={"贫瘠之地","call of fire","暗矛","杜隆塔尔","火焰灵契","萨满祭司","眠炎圣殿","泰尔夫·祖拉姆"},ang={["class:Shaman"]="泰尔夫·祖拉姆是你精神之路上的一位关键人物，他指引你通过火焰灵契的试炼，从而掌握你的火焰图腾。",["faction:Horde"]="通过守护边境地区各处神圣的元素圣殿，像泰尔夫这样的长者正不断巩固新部落的精神支柱。",["race:Troll"]="看到一位暗矛长者守护者在指引初学者，这展示了巨魔的精神信仰已与部落的萨满复兴运动深深交织在一起。"},sec={{t="火焰守卫者",b="泰尔夫·祖拉姆栖身于俯瞰边境地区的岩架之上，照料着眠炎圣殿。与平静的大地或深邃沉稳的水元素不同，火元素需要敏锐的纪律和坚定的专注力。泰尔夫担任试炼官，帮助年轻的萨满祭司在被野火吞噬之前，证明他们有资格驾驭这些狂野的灰烬。"},{t="火焰之路",b="在泰尔夫的指导下，初学者们酿造并饮用仪式所需的火焰灵契，以使他们凡人的双眼能窥见无形的元素位面。他引导祈求者登上岩石嶙峋的山巅，直面燃烧的灵魂，确保每一位赢得火焰认可的萨满祭司不仅是为了荣耀，更是怀着对火焰那贪婪渴求的敬畏之心。"}},faq={{q="泰尔夫·祖拉姆是谁？",a="泰尔夫·祖拉姆是一名暗矛巨魔萨满祭司，担任眠炎圣殿的守护者。他指导那些寻求与火焰沟通的年轻萨满祭司。",al={"泰尔夫·祖拉姆","泰尔夫是谁","眠炎圣殿巨魔"}},{q="在什么地方能找到泰尔夫·祖拉姆？",a="他居住在眠炎圣殿，位于杜隆塔尔和贫瘠之地之间的高耸岩脊之上。",al={"泰尔夫·祖拉姆位置","泰尔夫在哪里","如何找到泰尔夫·祖拉姆"}},{q="他要求的火焰灵契有什么用？",a="火焰灵契是一种特殊酿造的药剂，可以开启初学者的灵视，让他们能够感知并与凡人感官无法察觉的火焰元素之灵进行交流。",al={"什么是火焰灵契","火焰灵契用途","为什么要喝灵契"}},{q="泰尔夫·祖拉姆教授什么元素？",a="他专精于火焰元素，通过测试确保萨满祭司拥有足够的力量和意志来驾驭火焰，而不被其毁灭性的本质所反噬。",al={"泰尔夫教授什么元素","泰尔夫·祖拉姆元素","火焰图腾任务委托人"}},{q="为什么由一名巨魔来主持这里的萨满祭司仪式？",a="自从加入萨尔的部落以来，许多暗矛巨魔与兽人和牛头人一起接受了萨满祭司这种精神之道，像泰尔夫这样经验丰富的修行者正在指引着新一代的萨满祭司。",al={"为什么是巨魔萨满","暗矛萨满祭司"}},{q="完成泰尔夫·祖拉姆的任务后会发生什么？",a="在附近山峰证明了自己对火元素的掌控力后，初学者们将获得锻造他们专属火焰图腾所需的知识与祝福。",al={"call of fire奖励","泰尔夫给予什么"}}},fx={["6bc0eb27"]={q="泰尔夫·祖拉姆支持哪一方？",a="泰尔夫·祖拉姆自豪地效忠部落和暗矛部族。作为受人敬仰的萨满守护者，他追随萨尔开创的萨满传统，指引踏上元素之道的兽人和巨魔学徒。",al={"泰尔夫·祖拉姆的阵营","泰尔夫·祖拉姆是部落的吗","泰尔夫·祖拉姆效忠哪一方"}},["6f75c3b9"]={q="泰尔夫·祖拉姆想要什么？",a="泰尔夫·祖拉姆想考验那些渴望与火焰沟通的萨满候选者。他要求学徒收集制作火焰灵契的材料，以此证明他们意志坚定、与元素和谐共处，之后才会允许他们与沉睡的元素之火沟通。",al={"泰尔夫·祖拉姆的目标","泰尔夫想要什么","为什么要找泰尔夫·祖拉姆"}},b42da7bb={q="泰尔夫·祖拉姆与谁有关联？",a="泰尔夫·祖拉姆与杜隆塔尔和贫瘠之地各地的萨满训练师协同工作，是“Call of Fire”试炼中的重要一环。他在神殿履行神圣职责，服务于部落更广泛的精神复兴。",al={"泰尔夫·祖拉姆的关联人物","泰尔夫与谁共事","泰尔夫·祖拉姆的盟友"}}},fp="11,212,19.360.0,16.337.0,19.152.0,31.114.0,50.198.0,36.166.0,46.198.0,50.154.0"}
P.entries["npc:tenaron-stormgrip"] = {n="特纳隆·雷拳",s="特纳隆·雷拳是一位在幽影谷中心的奥达希尔高处指引新人的暗夜精灵。他向年轻的卡多雷讲述他们种族近期的历史，并要求他们收集月井之水。",h="特纳隆·雷拳是一位在幽影谷中心的奥达希尔高处指引新人的暗夜精灵。他向年轻的卡多雷讲述他们种族近期的历史，并要求他们收集月井之水。",kw={"奥达希尔","塞纳里奥议会","crown of the earth","月井","幽影谷","雷拳","泰达希尔","特纳隆"},ang={["class:Druid"]="特纳隆的任务突显了监测泰达希尔史无前例的生长并防范潜在腐化所需的德鲁伊式管护工作。",["race:NightElf"]="对于年轻的暗夜精灵来说，特纳隆·雷拳提供了关于维持泰达希尔生命与纯净所需的社区与精神职责的最初引导之一。"},sec={{t="奥达希尔守望者",b="特纳隆·雷拳栖身于奥达希尔蜿蜒的木质平台上，作为年轻暗夜精灵踏出幽影谷枝干后的早期导师。从他的有利位置，他监测着当地林地的健康状况以及维持林地生机的生命之源——月井。他的职责是指导新手理解他们与世界之树之间深厚的精神联系。"},{t="大地的冠冕",b="特纳隆开启了名为“大地的冠冕”的旅程。他派遣初学者从奥达希尔北部的月井中收集一瓶井水，并向他们讲述海加尔山之战后的后续事件。这段旅程将继续穿越泰达希尔，直至达纳苏斯。"}},faq={{q="特纳隆·雷拳位于何处？",a="特纳隆·雷拳站在泰达希尔幽影谷中心那棵巨大的中央树木——奥达希尔的木质坡道结构之上。",al={"特纳隆位置","特纳隆在哪里","特纳隆·雷拳的地点"}},{q="特纳隆·雷拳在幽影谷中扮演什么角色？",a="他指引年轻的暗夜精灵，并通过“大地的冠冕”旅程介绍海加尔山之战后的局势。",al={"特纳隆做什么","特纳隆·雷拳的目的","谁是特纳隆"}},{q="什么是“大地的冠冕”任务？",a="特纳隆要求初学者收集一瓶月井水并交还给他。这段旅程教授了暗夜精灵的近期历史，并延伸至泰达希尔各地。",al={"大地的冠冕背景故事","为什么要携带月井水"}},{q="为什么特纳隆关心泰达希尔的水源？",a="月井是艾露恩恩泽与自然纯净的核心载体。由于泰达希尔尚且年轻，缺乏巨龙军团的全面祝福，因此像特纳隆这样的看护者必须密切监测每一处水源，以防腐化或污染的迹象。",al={"为什么水源珍贵","泰达希尔的水源问题"}},{q="特纳隆会派遣冒险者前往幽影谷之外吗？",a="是的。一旦初学者表现出对圣水的敬畏和处理能力，特纳隆就会指引他们前往更广阔的泰达希尔，将他们派往多兰纳尔继续为卡多雷服务。",al={"特纳隆的下一个任务","特纳隆把你派往哪里"}},{q="特纳隆是德鲁伊还是牧师？",a="相关来源并未设定他的职业。他主要负责教授暗夜精灵的近期历史并解释月井的重要性。",al={"特纳隆·雷拳的职业","特纳隆是德鲁伊吗"}}},fx={["594d14e3"]={q="特纳隆·雷拳支持哪一方？",a="特纳隆全心效忠达纳苏斯的暗夜精灵，并致力于守护泰达希尔。他与照料巨树的德鲁伊和牧师并肩工作，指引从奥达希尔走出的新晋守卫者保护家园、效力于联盟。",al={"特纳隆的阵营","特纳隆是联盟的吗","特纳隆效忠谁"}},["4431413b"]={q="特纳隆·雷拳想要什么？",a="特纳隆希望培育并守护泰达希尔，抵御侵入枝干的腐化。他看守着幽影谷的水源，并委派有潜力的冒险者收集月亮井水，同时让他们了解族群近来的历史，以确保巨树茁壮成长。",al={"特纳隆想要什么","特纳隆的目标","特纳隆·雷拳的任务"}},["62d582e4"]={q="特纳隆·雷拳为什么会在这里？",a="特纳隆驻守在巨树奥达希尔的高处，管理着幽影谷的中心地带。他留在这里评估新晋暗夜精灵学徒，监视滋养树枝的圣水，并安排保护泰达希尔蓬勃生长的初步工作。",al={"特纳隆为什么在奥达希尔","特纳隆为什么在这里","特纳隆在幽影谷的职责"}}},fp="17,198,20.379.0,18.255.0,35.137.0,47.123.0,37.171.0,51.237.0,48.208.0,31.124.0"}
P.entries["npc:terenthis"] = {n="特伦希斯",s="特伦希斯是一位驻扎在奥伯丁沿海定居点的暗夜精灵德鲁伊。作为塞纳里奥议会的代表，他正在调查蔓延于黑海岸和泰达希尔的令人担忧的腐蚀。他招募有能力的旅行者去评估海岸沿线日益增长的威胁，并协助被腐化的野生动物困住的当地盟友。",h="特伦希斯是一位驻扎在奥伯丁沿海定居点的暗夜精灵德鲁伊。作为塞纳里奥议会的代表，他正在调查蔓延于黑海岸和泰达希尔的令人担忧的腐蚀。他招募有能力的旅行者去评估海岸沿线日益增长的威胁，并协助被腐化的野生动物困住的当地盟友。",kw={"奥伯丁","塞纳里奥议会","黑海岸","魔苔","熊怪","格瑞姆爪","特伦希斯","沃科尔"},ang={["class:Druid"]="作为塞纳里奥议会的兄弟，特伦希斯代表了抵御从泰达希尔蔓延至内陆的非自然腐蚀的前线。",["race:NightElf"]="特伦希斯体现了卡多雷净化神圣土地、清除残留邪能污染并保护森林中无辜生命的承诺。"},sec={{t="调查腐蚀",b="特伦希斯由塞纳里奥议会派遣至奥伯丁，致力于追踪魔苔以及其他正从泰达希尔渗入黑海岸的腐蚀力量。暗夜精灵对这种蔓延的枯萎病深感忧虑，担心如果不加以遏制，卡利姆多北部的自然平衡可能会彻底破碎。特伦希斯努力揭开腐烂的根源，并设法在它吞噬森林之前阻止其蔓延。"},{t="来自格瑞姆爪的求助",b="特伦希斯还担任野外紧急情况的联络人。当忠诚的熊格瑞姆爪独自受伤来到奥伯丁时，特伦希斯意识到这只野兽的主人，德鲁伊沃科尔，遇到了大麻烦。由于无法离开岗位，特伦希斯指引过往的冒险者前往荒野寻找沃科尔，他遭到了好斗的熊怪部落的伏击并被困住。"}},faq={{q="特伦希斯是谁？",a="特伦希斯是一位隶属于塞纳里奥议会的暗夜精灵德鲁伊，目前居住在黑海岸的港口城镇奥伯丁。",al={"特伦希斯背景故事","特伦希斯是谁","特伦希斯奥伯丁"}},{q="特伦希斯为什么在奥伯丁？",a="他被派遣来调查魔苔和魔法腐蚀从泰达希尔扩散到黑海岸的范围，并寻求终结这种枯萎病的方法。",al={"特伦希斯在做什么","特伦希斯的目的","特伦希斯为什么在这里"}},{q="特伦希斯旁边的熊在那里做什么？",a="那只熊，格瑞姆爪，在它的主人德鲁伊沃科尔遭到敌对熊怪的攻击并受伤后，来到奥伯丁寻找特伦希斯的帮助。",al={"特伦希斯的熊","格瑞姆爪","为什么奥伯丁有一只熊"}},{q="特伦希斯属于哪个组织？",a="特伦希斯是塞纳里奥议会的成员，这是一个致力于维护平衡并守护卡利姆多自然环境的德鲁伊组织。",al={"特伦希斯的阵营","特伦希斯是塞纳里奥议会的吗"}},{q="特伦希斯最担心哪些威胁？",a="他主要担心影响当地野生动物的魔苔腐蚀，以及威胁到旅行者和德鲁伊的当地熊怪部落日益增长的敌意。",al={"黑海岸腐蚀","魔苔威胁","特伦希斯的忧虑"}},{q="特伦希斯会给冒险者提供任务吗？",a="会。他指引冒险者评估沿海的腐蚀威胁，与桑德里斯·织风者等德鲁伊同僚进行协调，并组织对沃科尔的营救。",al={"特伦希斯的任务","特伦希斯想要什么"}}},fx={ba1c722a={q="特伦希斯想要什么？",a="特伦希斯想查明魔苔腐化侵入黑海岸的严重程度，并弄清泰达希尔及其周边荒野为何正遭受污染。归根结底，他希望根除这股蔓延的疫病，在腐化彻底扎根前恢复森林的平衡。",al={"特伦希斯的目标","特伦希斯想做什么","特伦希斯的动机"}}},fp="9,326,23.437.0,20.412.1,17.132.0,30.162.0,46.144.0,43.136.0,46.181.0,46.160.0"}
P.entries["npc:teronis-corpse"] = {n="泰洛尼斯的尸体",s="泰洛尼斯的尸体位于灰谷西部法拉希姆湖内的一座隐秘岛屿上。在遭遇不幸之前，这位暗夜精灵斥候受命离开阿斯特兰纳，执行一项关键任务，取回达图尔之杖以协助净化森林。",h="泰洛尼斯的尸体位于灰谷西部法拉希姆湖内的一座隐秘岛屿上。在遭遇不幸之前，这位暗夜精灵斥候受命离开阿斯特兰纳，执行一项关键任务，取回达图尔之杖以协助净化森林。",kw={"灰谷","阿斯特兰纳","达图尔之杖","法拉希姆湖","鱼人","莱恩·狼行者","泰洛尼斯","泰洛尼斯的尸体"},ang={["faction:Alliance"]="纪念阿斯特兰纳斥候的牺牲，意味着要继续完成他们未竟的事业，清除大地上潜伏的腐化。",["race:NightElf"]="在荒野中发现泰洛尼斯的遗体，让人清醒地意识到，对于经验丰富的哨兵和斥候来说，灰谷已经变得多么危险。"},sec={{t="斥候的悲惨命运",b="泰洛尼斯受阿斯特兰纳的莱恩·狼行者指派，负责寻回失落的达图尔之杖——这是一件能够净化腐化林地魔法的古老暗夜精灵遗物。他的搜寻将他带到了法拉希姆湖的深处，但当敌对的鱼人蜂拥上岛时，这段旅程变得致命。泰洛尼斯在战斗中倒下，留下了他的日志，而法杖上闪耀的宝石则被这些好斗的湖中两栖生物掠走。"}},faq={{q="泰洛尼斯是谁？",a="泰洛尼斯是一位由哨兵莱恩·狼行者从阿斯特兰纳派遣出来的暗夜精灵斥候。他的任务是取回达图尔之杖，这是一件用于净化渗透进灰谷土壤和水域的恶魔腐化的古老神器。",al={"泰洛尼斯是谁","泰洛尼斯背景故事","泰洛尼斯的身份"}},{q="泰洛尼斯是怎么死的？",a="泰洛尼斯在试图获取法杖组件时，遭到了盘踞在法拉希姆湖岸边和水中的好斗鱼人的伏击并被杀害。",al={"谁杀了泰洛尼斯","泰洛尼斯的死因","他怎么死的"}},{q="他丢失的宝石在哪里？",a="泰洛尼斯遇害后，作为达图尔之杖顶端的那颗发光的宝石被栖息在法拉希姆湖附近的当地鱼人搜刮走了。",al={"宝石在哪里","丢失的宝石","泰洛尼斯的宝石"}},{q="为什么他的任务对阿斯特兰纳如此重要？",a="灰谷的野生动物和林地水池正日益受到邪恶的恶魔和邪能污染的侵害。达图尔之杖蕴含着天生的净化魔法，哨兵们希望借此扭转或遏制这种持续的腐化。",al={"为什么要帮助莱恩","达图尔之杖的用途"}}},fx={["6a989bf2"]={q="泰洛尼斯曾效忠哪一方？",a="泰洛尼斯效力于灰谷的暗夜精灵和联盟。他受莱恩·狼行者派遣，从阿斯特兰纳出发，忠心守护并净化族人的圣林。",al={"泰洛尼斯的阵营","泰洛尼斯的尸体属于哪一方","泰洛尼斯是联盟的吗"}},["7cdf0db0"]={q="泰洛尼斯死前想要什么？",a="泰洛尼斯一直在寻找达托尔之杖遗失的部件，尤其是藏在法拉希姆湖中的一颗宝石。他希望借助宝石的魔力，帮助族人驱除蔓延于灰谷各处的黑暗腐化。",al={"泰洛尼斯的任务","泰洛尼斯的目标","泰洛尼斯当时在做什么"}},["7065b032"]={q="泰洛尼斯的尸体为什么会在法拉希姆湖？",a="寻找达托尔之杖的途中，他来到了法拉希姆湖中的岛屿，相信那里藏着一颗至关重要的宝石。湖中凶恶的鱼人将他团团围住，他还没来得及返回阿斯特兰纳便被杀害。",al={"泰洛尼斯为什么在这里","他的尸体为什么在湖边","泰洛尼斯与法拉希姆湖"}},["2ab2ec0c"]={q="泰洛尼斯与谁有关联？",a="泰洛尼斯直接听命于阿斯特兰纳的莱恩·狼行者。是莱恩派他前往法拉希姆湖寻找达托尔之杖；如今也是她仍未消散的牵挂，促使旅人去寻找他的遗体。",al={"是谁派遣泰洛尼斯","泰洛尼斯与莱恩·狼行者","泰洛尼斯为谁效力"}}},fp="15,240,19.458.0,16.221.0,20.156.0,27.138.0,56.212.0"}
P.entries["npc:thadius-grimshade"] = {n="萨迪斯·格希德",s="萨迪斯·格希德是一位蛮锤矮人占卜师，居住在诅咒之地守望堡的法师塔中。虽然他很久以前就离开了鹰巢山去钻研深奥而黑暗的魔法技艺，但他内心依然忠于自己的族人。",h="萨迪斯·格希德是一位蛮锤矮人占卜师，居住在诅咒之地守望堡的法师塔中。虽然他很久以前就离开了鹰巢山去钻研深奥而黑暗的魔法技艺，但他内心依然忠于自己的族人。",kw={"诅咒之地","占卜师","耐克鲁姆·噬肠者","守望堡","sharpbeak","萨迪斯·格希德","蛮锤"},ang={["class:Mage"]="造访守望堡的法师们会认出萨迪斯是一位罕见且深奥的占卜方法的实践者，他乐于研究巨魔遗物以掌握长寿魔法。",["race:Dwarf"]="其他矮人会觉得萨迪斯在蛮锤族人中是个异类；他没有骑着狮鹫翱翔，而是多年来一直埋头在人类堡垒中钻研奥术。"},sec={{t="荒原上的蛮锤矮人",b="与大多数喜欢辛特兰广阔天空和咆哮狂风的蛮锤矮人不同，萨迪斯·格希德把家安在了守望堡里。出于对奥术占卜和黑暗神秘知识的渴望，他搬到了受到腐蚀的诅咒之地的边缘，以追求他那深奥的研究。尽管他行事沉郁且与族群分离，但他依然对家乡和狮鹫族怀有深厚的感情，并为那些代表鹰巢山前来寻求帮助的人提供他那罕见的占卜才能。"},{t="占卜的代价",b="当狮鹫管理员Talonaxe试图寻找被俘的狮鹫Sharpbeak时，萨迪斯受命利用这头野兽的一根羽毛进行占卜仪式。他的魔法洞察力并非没有代价：萨迪斯要求得到巨魔通灵师耐克鲁姆·噬肠者所佩戴的徽章。为了揭开它那非自然长寿的秘密，同时避免其有害的腐蚀影响，他以刺破辛萨罗的面纱并揭示Sharpbeak被囚禁的位置为交换，索要了这件神器。"}},faq={{q="萨迪斯·格希德是谁？",a="他是一位驻扎在守望堡的古怪蛮锤矮人法师兼占卜师。他离开了自己的山中家园，去遥远的南方钻研更黑暗、非正统的魔法技艺。",al={"萨迪斯·格希德","萨迪斯是谁","萨迪斯npc"}},{q="在哪里可以找到萨迪斯·格希德？",a="他居住在守望堡的高级法师塔内，这是一座位于诅咒之地北部的联盟据点。",al={"萨迪斯位置","萨迪斯·格希德在哪里","萨迪斯诅咒之地"}},{q="他为什么想要耐克鲁姆的徽章？",a="萨迪斯希望研究耐克鲁姆·噬肠者携带的徽章，以破译其魔法力量如何赋予长寿，他希望能获得这种长寿，同时又不屈服于它那邪恶的副作用。",al={"耐克鲁姆的徽章萨迪斯","为什么萨迪斯想要徽章","耐克鲁姆·噬肠者徽章"}},{q="他是如何帮助寻找Sharpbeak的？",a="萨迪斯利用这只失踪的狮鹫掉落的羽毛，并借助耐克鲁姆的徽章提供的力量，进行了一场探知仪式，揭示出Sharpbeak正被囚禁在辛特兰的辛萨罗高地。",al={"萨迪斯sharpbeak","占卜sharpbeak","寻找sharpbeak任务"}}},fp="17,248,26.515.0,23.495.1,25.169.0,37.138.0,36.197.0,32.205.1"}
P.entries["npc:thalia-amberhide"] = {n="萨利亚",s="萨利亚是居住在千针石林崎岖峡谷中乱风岗的一位牛头人。作为族人的忠实朋友，她正怀着愈发沉重的心情，等待着拉克塔·风歌从恐怖图腾氏族的魔爪中安全归来。",h="萨利亚是居住在千针石林崎岖峡谷中乱风岗的一位牛头人。作为族人的忠实朋友，她正怀着愈发沉重的心情，等待着拉克塔·风歌从恐怖图腾氏族的魔爪中安全归来。",kw={"阿纳克·恐怖图腾","乱风岗","恐怖图腾","拉克塔·风歌","萨利亚","千针石林"},ang={["faction:Horde"]="乱风岗是部落在千针石林的一个重要据点，帮助萨利亚有助于保护该定居点免受恐怖图腾的侵扰。",["race:Tauren"]="对于牛头人旅行者而言，援助萨利亚并营救拉克塔是对恐怖图腾部族险恶背叛的直接打击，旨在保卫族人免受氏族纠纷的伤害。"},sec={{t="岗哨之友",b="萨利亚栖身于乱风岗高耸的悬崖之上，在熙熙攘攘的牛头人定居点中是一位安静的存在。她为挚友拉克塔·风歌的安危感到忧心忡忡，因为拉克塔被阿纳克·恐怖图腾和他那些奸诈的族人俘虏了。萨利亚寄希望于路过的部落冒险者，希望他们能深入峡谷，找到拉克塔，解开她的束缚，并将她安全地带回高原上的避风港。"}},faq={{q="萨利亚是谁？",a="萨利亚是一位居住在千针石林乱风岗的牛头人。她是拉克塔·风歌的忠实朋友，而拉克塔是另一位因招惹了奸诈的恐怖图腾氏族而陷入麻烦的牛头人。",al={"萨利亚","萨利亚是谁"}},{q="在哪里可以找到萨利亚？",a="她位于千针石林中心地带的乱风岗高地之上。旅行者必须乘坐从峡谷底部通往该定居点的巨大木制升降梯才能抵达。",al={"萨利亚位置","萨利亚在哪里"}},{q="萨利亚和拉克塔·风歌是什么关系？",a="萨利亚是拉克塔·风歌的挚友。当拉克塔被阿纳克·恐怖图腾俘虏后，萨利亚作为乱风岗的联络人，等待着冒险者成功营救拉克塔归来。",al={"萨利亚和拉克塔","拉克塔·风歌是谁"}}},fx={["29deb6ad"]={q="萨利亚支持哪一方？",a="萨利亚忠于部落和她的牛头人族人。她住在千针石林的乱风岗，欢迎途经风蚀高原的部落冒险者，并坚定地抵御威胁当地部族的敌对势力。",al={"萨利亚的阵营","萨利亚是部落的吗","萨利亚属于部落还是联盟"}},["80c269cc"]={q="萨利亚为什么会在这里？",a="萨利亚住在乱风岗顶上，是这座牛头人高原聚居地的一名安居者。她与族人平静地生活，但峡谷下方的威胁正困扰着她那些朋友，让她忧心忡忡。",al={"萨利亚为什么在乱风岗","萨利亚在哪里，为什么","是什么让萨利亚来到千针石林"}},["211f0475"]={q="萨利亚想要什么？",a="萨利亚非常关心亲密伙伴拉克塔·风歌的安危。她最挂心的是保护自己珍视的人，不让他们遭受蛮锤等敌对部族的侵袭。",al={"萨利亚想要什么","萨利亚的动机","萨利亚的目标"}}},fp="16,235,20.432.0,24.183.0,36.193.0,47.209.0"}
P.entries["npc:tharek-blackstone"] = {n="萨雷克·黑石",s="萨雷克·黑石是一位勤恳的工具铁匠，居住在丹莫罗白雪皑皑的心脏地带——卡拉诺斯。他因向当地工匠供应重型五金件而闻名，其主要客户是钢架补给站的贝尔丁·钢架。尽管他总是忙于打铁，但他也是那些在定居点附近寻找工作的旅行者们可靠的联络人。",h="萨雷克·黑石是一位勤恳的工具铁匠，居住在丹莫罗白雪皑皑的心脏地带——卡拉诺斯。他因向当地工匠供应重型五金件而闻名，其主要客户是钢架补给站的贝尔丁·钢架。尽管他总是忙于打铁，但他也是那些在定居点附近寻找工作的旅行者们可靠的...",kw={"贝尔丁","黑石","丹莫罗","卡拉诺斯","钢架","萨雷克","工具铁匠"},ang={["profession:Blacksmithing"]="对于路过卡拉诺斯的铁匠来说，萨雷克是工具铁匠日常辛勤工作的典范，他不断打造耐用的扳手和铁制配件，以维持矮人机械的运转。",["race:Dwarf"]="萨雷克代表了丹莫罗工人阶级坚韧、自立的精神，通过在铁砧前不断的坚持，帮助维持着当地的工业运转。"},sec={{t="卡拉诺斯忙碌的工具铁匠",b="萨雷克·黑石身处卡拉诺斯寒冷的雪堆之中，忙于打造可靠的矮人工具。在为当地人修理装备和供应大型作业所需之间，他几乎没有片刻休息。他最大的头疼来源——同时也是最可靠的客户——是贝尔丁·钢架。贝尔丁在镇外经营的机械陆行鸟补给站需要源源不断的重型扳手、齿轮和替换配件。为了让他的锻炉持续运转而不耽误交付，萨雷克经常雇佣过往的旅行者，让他们帮忙把刚做好的工具箱运送到补给站。"},{t="一位社区人物",b="除了在铁砧前的本职工作外，萨雷克在丹莫罗的居民中享有相当高的声望。虽然他没有正式的军事头衔，但他在镇上的地位使他成为处理零活、物资补给和协调当地工作时易于接触的联络人。"}},faq={{q="萨雷克·黑石是谁？",a="萨雷克·黑石是一位矮人工具铁匠，常驻于丹莫罗的卡拉诺斯镇。他为当地工人制造并维护重型工具，并经常雇佣路过的冒险者在山谷各地运送物资。",al={"萨雷克·黑石","萨雷克是谁","黑石 丹莫罗"}},{q="他和贝尔丁·钢架是什么关系？",a="贝尔丁·钢架在卡拉诺斯以东经营着钢架补给站，那里负责修理机械陆行鸟和攻城引擎。贝尔丁是萨雷克的主要客户，他订购的铁器数量巨大，以至于萨雷克经常需要依靠冒险者将成品货物运送到补给站。",al={"萨雷克与贝尔丁","钢架工具","为什么要找贝尔丁"}},{q="我在哪里可以找到萨雷克·黑石？",a="他站在丹莫罗卡拉诺斯中心附近的户外，距离当地旅店和锻炉都很近。",al={"萨雷克位置","萨雷克·黑石在哪里","萨雷克·黑石坐标"}},{q="萨雷克在铁炉堡有正式军衔吗？",a="他没有军职，也没有担任任何政治职务。他只是一位忙碌、过度劳累的工具铁匠，会雇佣需要钱的新手来帮他搬运物资。",al={"萨雷克是首领吗","萨雷克的职权","黑石的军衔"}}},fx={cb940f84={q="萨雷克·黑石支持哪一方？",a="萨雷克是铁炉堡忠诚的矮人，坚定地站在联盟一边。他以卡拉诺斯为据点，通过辛勤劳作服务社区，为当地工匠提供装备；丹莫罗一旦有麻烦，他也会帮助旅人和邻居。",al={"萨雷克·黑石的阵营","萨雷克·黑石效忠谁","萨雷克是联盟的吗"}},eaa270fb={q="萨雷克·黑石想要什么？",a="萨雷克主要想应付没完没了的工作。作为一名勤勉的工具匠，他总是被订单淹没，尤其是贝尔丁·钢架这类要求苛刻的客户下的订单。他需要可靠的旅人帮忙送货、承接杂活，好让自己的锻炉顺利运转。",al={"萨雷克想要什么","萨雷克·黑石的动机","萨雷克为什么需要帮助"}},fa8e7e80={q="萨雷克·黑石为什么会在卡拉诺斯？",a="卡拉诺斯是丹莫罗旅行者和商贩往来的中心枢纽，自然适合萨雷克在此开店。他可以从这里为钢架补给站等附近据点提供必需的装备。",al={"萨雷克为什么在卡拉诺斯","萨雷克·黑石 卡拉诺斯"}}},fp="17,351,28.576.0,18.251.0,25.221.0,48.273.0,35.132.0,48.150.0"}
P.entries["npc:tharnariun-treetender"] = {n="萨纳瑞恩·绿树",s="萨纳瑞恩·绿树是一位暗夜精灵博物学家，驻扎在黑海岸的沿海定居点奥伯丁。他致力于守护自然界的微妙平衡，监视着侵蚀当地动植物的腐化现象。途经此港口的旅行者经常发现他呼吁盟友医治患病的野兽，保护自然免受进一步的衰败。",h="萨纳瑞恩·绿树是一位暗夜精灵博物学家，驻扎在黑海岸的沿海定居点奥伯丁。他致力于守护自然界的微妙平衡，监视着侵蚀当地动植物的腐化现象。途经此港口的旅行者经常发现他呼吁盟友医治患病的野兽，保护自然免受进一步的衰败。",kw={"奥伯丁","净化","腐化","黑海岸","受感染","卡多雷","瘟疫之地","萨纳瑞恩","绿树"},ang={["class:Druid"]="德鲁伊会发现萨纳瑞恩对枯萎野生动物的关心与他们恢复腐化土地和谐的神圣使命紧密相连。",["faction:Alliance"]="奥伯丁是联盟在卡利姆多北部的核心沿海门户，这使得萨纳瑞恩对周围森林的防御对该前哨的安全至关重要。",["race:NightElf"]="对于卡多雷来说，萨纳瑞恩的警告与他们守护卡利姆多北部自然平衡的古老职责产生了深刻的共鸣。"},sec={{t="奥伯丁的守护者",b="坐落在黑海岸崎岖的海岸线上，奥伯丁港面临着多方面的威胁，从敌对的萨特到邪恶的海岸冲刷怪。萨纳瑞恩·绿树将精力完全集中在村庄周围的自然世界。他坚信忽视自然只会招致毁灭，因此花费时间观察当地树林的衰败，并寻求方法抵御在森林地面蔓延的疾病。"},{t="医治受难者",b="黑海岸的大部分野生动物都成为了奇怪瘟疫和腐化枯萎病的牺牲品，这使得生物变得疯狂，并将和平的动物变成了狂暴的威胁。萨纳瑞恩并非仅仅出于恐惧而屠杀它们，而是寻求一种补救措施。通过精心调制的净化剂和有针对性地消除最严重的传染源，他努力在林地彻底衰败之前拯救残存的荒野。"}},faq={{q="萨纳瑞恩·绿树是谁？",a="萨纳瑞恩是一位暗夜精灵看护者，驻扎在黑海岸沿岸的奥伯丁。他毕生致力于守护森林，并诊断困扰当地野生动物的非自然疾病。",al={"谁是萨纳瑞恩","萨纳瑞恩背景故事","萨纳瑞恩绿树"}},{q="我在哪里可以找到萨纳瑞恩·绿树？",a="他位于黑海岸荒野西缘的暗夜精灵沿海村庄奥伯丁。",al={"萨纳瑞恩在哪里","萨纳瑞恩绿树位置","萨纳瑞恩地图"}},{q="萨纳瑞恩正在黑海岸调查什么问题？",a="他调查感染了土地及其野生动物的腐化蔓延和邪恶瘟疫，并派遣冒险者去净化受感染的野兽以阻止枯萎病。",al={"萨纳瑞恩想要什么","萨纳瑞恩目的","为什么帮助萨纳瑞恩"}},{q="为什么萨纳瑞恩如此关心患病的动物？",a="作为荒野的守护者，萨纳瑞恩认为暗夜精灵如果忽视自然，必将自食其果。他致力于净化病患生物，而不是任由森林腐化。",al={"为什么拯救野兽","萨纳瑞恩野兽任务"}},{q="萨纳瑞恩·绿树提供什么任务？",a="他指导冒险者完成涉及荒芜之地和野生动物的任务，特别是“Plagued Lands”、“Cleansing of the Infected”和“Tharnariun's Hope”。",al={"萨纳瑞恩任务","萨纳瑞恩绿树职责"}},{q="萨纳瑞恩是德鲁伊吗？",a="资料从未明确称呼他为德鲁伊。虽然他在保护野兽和植物方面拥有与塞纳里奥议会相同的博物学家信念，但他主要担任黑海岸荒野的专注看护者和树木管理员。",al={"萨纳瑞恩是德鲁伊吗","萨纳瑞恩职业"}}},fx={["8905307a"]={q="萨纳瑞恩·绿树站在哪一方？",a="萨纳瑞恩·绿树坚定地站在暗夜精灵和联盟一方。他驻扎在奥伯丁，忠于保护卡利姆多的自然遗产和卡多雷同胞；他欢迎愿意协助抵御蔓延腐化、守护荒野的联盟旅人。",al={"萨纳瑞恩·绿树 阵营","萨纳瑞恩是联盟成员吗","萨纳瑞恩效忠谁"}},["3ad5bd13"]={q="萨纳瑞恩·绿树想要什么？",a="萨纳瑞恩致力于保护并净化黑海岸脆弱的生态环境。当地动物受到奇异的侵扰，变得扭曲不堪，他对此深感忧虑，因此竭力查明腐化的根源，并寻找疗法治愈受感染的野生动物；若无法挽救，便仁慈地将它们除掉，以免自然秩序彻底崩溃。",al={"萨纳瑞恩的目标","萨纳瑞恩在尝试做什么","萨纳瑞恩·绿树的职责"}}},fp="21,382,23.443.0,21.436.1,29.209.0,39.118.0,55.166.0,56.211.0,45.158.0,22.249.0"}
P.entries["npc:the-defias-traitor"] = {n="迪菲亚叛徒",s="迪菲亚叛徒是一名被俘的亡命之徒，被关押在西部荒野哨兵岭岗哨的底部。他被人民军当场抓获，为了保命，他供出了迪菲亚潜行者总部的秘密位置。",h="迪菲亚叛徒是一名被俘的亡命之徒，被关押在西部荒野哨兵岭岗哨的底部。他被人民军当场抓获，为了保命，他供出了迪菲亚潜行者总部的秘密位置。",kw={"defias hideout","迪菲亚叛徒","农夫萨丁","月溪镇","人民军","哨兵岭","西部荒野"},ang={["class:Rogue"]="这是一个鲜明的提醒，展示了犯罪团伙内部脆弱的忠诚：当被法律逼入绝境时，窃贼和强盗很少会犹豫是否要出卖同伙。",["faction:Alliance"]="对于人民军和当地的守卫者来说，这名囚犯代表了在对抗蹂躏西部荒野的歹徒的斗争中，期待已久的转折点。"},sec={{t="前往月溪镇的向导",b="这名变节者被关押在哨兵岭的岗哨下，他的任务简单却充满危险：引导联盟勇士穿过充满敌意的领地，直达月溪镇废墟之下的隐藏入口。尽管他被昔日的同伙憎恨，也被俘虏他的人所鄙视，但他的背叛为人民军提供了打击迪菲亚潜行者核心势力所需的突破口。"},{t="为了生存的交易",b="并非迪菲亚潜行者的每一名成员都对艾德温·范克里夫的理想怀有狂热的忠诚。当这名小偷试图抢劫农夫萨丁的马车而被抓获时，格里安·斯托曼的民兵当场人赃并获。面对绞刑架，这名小偷选择了保命而非兄弟情义，用他们隐藏行动基地的确切位置换取了自己的生命。"}},faq={{q="迪菲亚叛徒是谁？",a="他曾是迪菲亚潜行者的一员，在试图从农夫萨丁那里偷窃马车时被人民军俘虏。为了逃避处决，他同意带领人民军的盟友前往迪菲亚潜行者的秘密巢穴。",al={"他是谁","迪菲亚叛徒身份","哨兵岭的叛徒是谁"}},{q="他为什么站在哨兵岭的塔外？",a="他正被格里安·斯托曼和人民军关押在他们的据点外。他在武装看守下被留在那，直到有志愿者站出来护送他前往Defias Hideout。",al={"叛徒位置","他为什么在哨兵岭","叛徒在哪里"}},{q="他会带你去哪里？",a="他会引导旅行者向西南穿过西部荒野的平原，进入荒废的月溪镇，并指明通往Defias Hideout的隐秘入口。",al={"叛徒去哪里","叛徒护送目的地","defias hideout在哪里"}},{q="他为什么要背叛迪菲亚潜行者？",a="单纯是为了自保。在因偷窃农夫萨丁的财物而被捕并面临处决时，他用迪菲亚潜行者最大的秘密换取了自己的生命。",al={"为什么背叛迪菲亚","叛徒动机","他为什么反水"}}},fx={ad165ef1={q="迪菲亚叛徒站在哪一方？",a="他主要只站在自己一边。他原本是迪菲亚潜行者中的一名盗贼，被人民军抓获后，便背弃了对艾德温·范克里夫的忠诚。如今他在看守之下与我们合作，纯粹是为了免上绞刑架。",al={"迪菲亚叛徒 立场","叛徒效忠谁","迪菲亚叛徒是联盟成员吗"}},["9c073637"]={q="迪菲亚叛徒想要什么？",a="他只想活下去。他在偷窃农夫萨丁的马车时被当场抓获，走投无路之下便与格里安·斯托曼和人民军达成交易：他带你直捣迪菲亚兄弟会的秘密藏身处，以此换取性命和免遭处决。",al={"叛徒想要什么","迪菲亚叛徒的目标","为什么要帮迪菲亚叛徒"}},a1cd0f31={q="迪菲亚叛徒与谁有牵连？",a="他以前听命于艾德温·范克里夫和迪菲亚潜行者，对他们在西部荒野各处的行动了如指掌。目前，他被格里安·斯托曼和哨兵岭的人民军看押，他们依靠他亲身掌握的情报，准备袭击盗贼的总部。",al={"迪菲亚叛徒的关系","叛徒认识谁","迪菲亚叛徒的牵连"}}},fp="18,230,28.392.1,22.396.1,26.219.0,54.201.0,23.155.1,47.174.0"}
P.entries["npc:theldurin-the-lost"] = {n="迷失者塞尔杜林",s="迷失者塞尔杜林是一位隐居的半疯矮人，徘徊在荒芜之地的焦土之上。他曾是阴险的暮光之锤教派的一员，在意识到该教派阴谋的恐怖后，他偷走了他们的圣物并逃离了他们的队伍。",h="迷失者塞尔杜林是一位隐居的半疯矮人，徘徊在荒芜之地的焦土之上。他曾是阴险的暮光之锤教派的一员，在意识到该教派阴谋的恐怖后，他偷走了他们的圣物并逃离了他们的队伍。",kw={"荒芜之地","爆破粉末","密斯莱尔","雷乌纳","密斯莱尔卷轴","塞尔杜林","迷失者塞尔杜林","暮光之锤"},ang={["profession:Engineering"]="塞尔杜林用装满爆破粉末的背包威胁接近的陌生人，表现出对挥发性炸药不可预测的依赖。",["race:Dwarf"]="看到一位铁炉堡同胞在荒原中变得神志不清真是悲剧，但他拒绝向黑暗教派屈服的行为展现了矮人一族顽强的韧性。"},sec={{t="被黑暗撕裂的心智",b="塞尔杜林栖身于荒芜之地贫瘠的山丘中，疯狂而多疑地紧紧抓着几袋炸药。他不仅仅是一个简单的疯癫隐士。他曾是暮光之锤教派的信徒。当这个邪恶的结社企图唤醒被禁锢在大地深处的原始元素力量时，塞尔杜林因恐惧而退缩，拒绝了他们疯狂的教义，并逃进了沙漠。他随身携带了密斯莱尔卷轴，拼命地想要阻止他曾经的主人将远古的恐怖释放到世界上。尽管这次逃亡让他失去了理智，但他的反抗严重打击了该教派的计划。"},{t="孤注一掷的对策",b="在荒野中的生存极其艰苦。愤怒的土元素伏击了塞尔杜林，将他偷走的卷轴撕成了碎片，散落在尘土中。如今，这位疯狂的矮人被偏执所困扰，时常被地底沉睡的末日即将降临的幻象折磨。他正在寻找远古的文本——雷乌纳石板和雅格因的笔记，希望能发掘出被埋藏已久的知识。塞尔杜林不愿让教派在密斯莱尔公主狂怒的巅峰期将其释放，因此他计划强行让其提前被召唤，以便将其击败并再次封印。"}},faq={{q="谁是迷失者塞尔杜林？",a="塞尔杜林是一位隐藏在荒芜之地的疯狂矮人隐士。他曾是暮光之锤教派的成员，偷走了他们的仪式秘密并逃入荒野，以阻止他们释放一股危险的力量。",al={"谁是塞尔杜林","塞尔杜林传说","荒芜之地疯狂矮人"}},{q="为什么塞尔杜林躲在荒芜之地？",a="他正在躲避暮光之锤的追杀。在从该教派偷走密斯莱尔卷轴后，他躲进了荒芜之地偏远且被太阳炙烤的峡谷中，以躲避追捕他的教徒。",al={"为什么塞尔杜林在这里","为什么塞尔杜林躲藏","塞尔杜林荒芜之地"}},{q="什么是密斯莱尔卷轴？",a="这是一份奥术羊皮纸，记载着释放密斯莱尔所需的仪式知识。密斯莱尔是一个被禁锢在阿拉希深处的远古腐化元素实体。塞尔杜林偷走它就是为了防止暮光之锤完成召唤，尽管当地的元素生物后来将这份文件撕成了碎片。",al={"密斯莱尔卷轴","塞尔杜林偷了什么卷轴"}},{q="塞尔杜林想对密斯莱尔做什么？",a="塞尔杜林知道禁锢该生物的枷锁正在减弱，他试图在密斯莱尔恢复全部力量之前将其提前召唤出来。通过强行削弱她的状态，冒险者可以在暮光之锤掌握她的力量之前将其驱逐并再次封印在地下。",al={"塞尔杜林的计划","为什么要召唤密斯莱尔","召唤公主"}}},fp="18,249,28.604.0,26.568.1,26.217.0,40.208.0,30.296.1,44.274.1"}
P.entries["npc:theocritus"] = {n="塞欧克瑞图斯",s="大法师塞欧克瑞图斯是一位古怪的人类法师，居住在艾尔文森林东部的阿祖拉之塔顶端。他的生活非常独立，身边围绕着仆人和各种魔法探知装置。塞欧克瑞图斯从他那高耸的圣所中观察着王国，并致力于对抗他的黑暗宿敌——堕落法师摩根斯。",h="大法师塞欧克瑞图斯是一位古怪的人类法师，居住在艾尔文森林东部的阿祖拉之塔顶端。他的生活非常独立，身边围绕着仆人和各种魔法探知装置。塞欧克瑞图斯从他那高耸的圣所中观察着王国，并致力于对抗他的黑暗宿敌——堕落法师摩根斯。",kw={"大法师","艾尔文森林","阿祖拉之眼","摩根斯","莫利·埃伯莱恩","暗皮","塞欧克瑞图斯","阿祖拉之塔"},ang={["class:Mage"]="塞欧克瑞图斯代表了那种独立于任何组织之外的法师生活，展示了独行的法师大师们如何建立圣所并进行远程探知。",["faction:Alliance"]="尽管古怪且冷漠，塞欧克瑞图斯还是利用他的奥术视野和资源积极保卫艾尔文森林东部和赤脊山，抵御流氓施法者的侵害。",["race:Human"]="塞欧克瑞图斯和摩根斯之间的冲突反映了人类法术的两条道路：致力于防御的严谨学术，与腐化堕落的黑暗野心。"},sec={{t="高塔之主",b="大法师塞欧克瑞图斯在暴风城王国拥有一座独立的要塞。他定居在显眼的阿祖拉之塔，该塔位于通往赤脊山的东部道路附近。塞欧克瑞图斯以其古怪的习惯和舒适的生活方式而闻名，他雇佣了庞大的仆人团队，其中包括许多侏儒侍从以及他专属的服装师莫利·埃伯莱恩。虽然他很大程度上远离当地村民的世俗琐事，但他的存在是艾尔文森林东部一道关键的魔法防线。"},{t="对抗摩根斯的战争",b="塞欧克瑞图斯当前最关心的问题是堕落法师摩根斯，这是一个危险的术士，在附近的赤脊山的伊尔加拉之塔中兴风作浪。塞欧克瑞图斯视摩根斯为个人宿敌，同时也是对暴风城的严重威胁，因此他投入了数月的时间进行奥术研究，试图削弱对方的力量。通过阿祖拉之眼等探知神器，塞欧克瑞图斯监视着这个恶棍的一举一动，并窥探他的思想。他还致力于利用摩根斯创造的造物来反制他，通过研究暗皮豺狼人佩戴的魔法坠饰，希望能传递一道奥术脉冲，从而使整群豺狼人陷入瘫痪。"}},faq={{q="塞欧克瑞图斯是谁？",a="大法师塞欧克瑞图斯是一位独立的人类法师，在艾尔文森林东部的阿祖拉之塔安家。他过着古怪且略显孤立的生活，将精力集中在利用奥术技艺保卫该地区，抵御黑暗魔法的威胁。",al={"塞欧克瑞图斯背景故事","塔里的法师是谁","阿祖拉之塔法师"}},{q="为什么塞欧克瑞图斯住在艾尔文森林？",a="塞欧克瑞图斯是一位独立的法师，在艾尔文森林东部的阿祖拉之塔中拥有自己的圣所。他在那里钻研学问，有仆人伺候，并监视着与赤脊山的边界，他的宿敌摩根斯正是盘踞在赤脊山的伊尔加拉之塔中。",al={"为什么塞欧克瑞图斯在艾尔文"}},{q="塞欧克瑞图斯在与谁作战？",a="他的主要对手是摩根斯，这是一位堕落的人类法师，在赤脊山边界对面的伊尔加拉之塔里修习黑暗魔法。塞欧克瑞图斯认为摩根斯既是他的个人敌人，也是暴风城安全的严峻威胁。",al={"塞欧克瑞图斯的敌人","摩根斯是谁","塞欧克瑞图斯的宿敌"}},{q="什么是阿祖拉之眼？",a="阿祖拉之眼是塞欧克瑞图斯开发并安置在他塔顶的一件强大探知装置。他利用它以魔法窥探远方，追踪威胁，甚至试图读取他的宿敌摩根斯的思想。",al={"阿祖拉之眼背景","塞欧克瑞图斯如何监视","塞欧克瑞图斯的水晶球"}},{q="为什么塞欧克瑞图斯想要暗皮豺狼人的坠饰？",a="暗皮豺狼人效忠于摩根斯，并佩戴着与主人相连的附魔坠饰。塞欧克瑞图斯研究这些饰品是为了了解它们魔法链接的运作方式，希望通过这个网络发动一次奥术攻击，使豺狼人在战斗中瘫痪。",al={"塞欧克瑞图斯的豺狼人坠饰","塞欧克瑞图斯的回收任务","为什么要收集豺狼人坠饰"}},{q="谁在塔中侍奉塞欧克瑞图斯？",a="塞欧克瑞图斯身边围绕着一个不寻常的家仆团队，包括一整队负责他日常事务的侏儒仆人，以及一位打理他衣橱的私人服装师莫利·埃伯莱恩。",al={"阿祖拉之塔员工","谁住在阿祖拉之塔","塞欧克瑞图斯的仆人"}}},fx={ffea707c={q="塞欧克瑞图斯站在哪一方？",a="大法师塞欧克瑞图斯独自行动，专注于自己的奥秘研究。虽然他不参与暴风城和联盟的日常政治，但仍认为自己有责任抵御黑暗魔法。他坚定地反对叛变的巫师摩根斯，以及侵袭艾尔文森林和赤脊山的黑暗势力。",al={"塞欧克瑞图斯属于联盟还是部落","塞欧克瑞图斯效忠谁","塞欧克瑞图斯的阵营"}},["09c566f6"]={q="塞欧克瑞图斯想要什么？",a="塞欧克瑞图斯运用强大的奥术本领，对抗宿敌、堕落法师摩根斯。他借助名为阿祖拉之眼的魔法占卜装置，以及找回的暗皮豺狼人吊坠，试图窥探摩根斯的思想，扰乱这名黑暗巫师对那些在当地肆虐的豺狼人的控制。",al={"塞欧克瑞图斯的目标","塞欧克瑞图斯在尝试做什么","塞欧克瑞图斯的职责"}},a72df9dd={q="塞欧克瑞图斯为什么会在艾尔文森林？",a="塞欧克瑞图斯在艾尔文森林东部的阿祖拉之塔安了家。这座偏僻的高塔为他提供了宁静的隐居之所，让他能在侏儒侍从的陪伴下独自研究，同时监视附近与赤脊山接壤的边境。",al={"塞欧克瑞图斯为什么在艾尔文森林","塞欧克瑞图斯为什么在这里","塞欧克瑞图斯为何在阿祖拉之塔"}},f1864285={q="塞欧克瑞图斯与谁有牵连？",a="塞欧克瑞图斯性情古怪、独来独往，但高塔里有一群忠心的侏儒仆役侍奉他，还有他的私人裁缝莫利·艾伯莱因；与此同时，他与叛变法师摩根斯结下了深仇。",al={"塞欧克瑞图斯的关系","塞欧克瑞图斯的朋友","塞欧克瑞图斯在达拉然的盟友"}}},fp="10,350,19.526.0,24.626.0,18.244.0,42.260.0,35.236.0,25.225.0,51.253.0,35.213.0"}
P.entries["npc:therylune"] = {n="瑟瑞露尼",s="瑟瑞露尼是一位森林女神，她被囚禁在黑海岸南部的主宰之剑。她被占据了这处远古遗迹的邪恶暮光之锤教派成员所俘虏，不得不依靠勇敢的旅行者来帮助她脱困并逃离他们的魔爪。",h="瑟瑞露尼是一位森林女神，她被囚禁在黑海岸南部的主宰之剑。她被占据了这处远古遗迹的邪恶暮光之锤教派成员所俘虏，不得不依靠勇敢的旅行者来帮助她脱困并逃离他们的魔爪。",kw={"塞纳留斯","黑海岸","森林女神","护送","主宰之剑","瑟瑞露尼","瑟瑞希尔","暮光之锤"},ang={["class:Druid"]="作为与塞纳留斯及其族人结盟的自然守护者，德鲁伊会对被邪恶教派俘虏的森林女神产生直接的共鸣，并感到有迫切的责任去营救她。",["race:NightElf"]="暗夜精灵与塞纳留斯的女儿们有着神圣的古老纽带，因此瑟瑞露尼落入暮光之锤之手被视为对卡利姆多平衡的亵渎。"},sec={{t="邪教徒的囚徒",b="森林女神是自然的守护者，也是塞纳留斯的女儿，通常在卡利姆多北部的宁静林地中漫步。然而，瑟瑞露尼冒险过于靠近了黑海岸南部主宰之剑那处不祥的挖掘场，暮光之锤教派成员正聚集在那里。她遭到了邪教徒的伏击并被困住，无法独自杀出重围，需要护送才能逃往安全地带。"}},faq={{q="瑟瑞露尼是谁？",a="瑟瑞露尼是一位森林女神，半神塞纳留斯的林地女儿之一。她被在黑海岸南部主宰之剑活动的暮光之锤教派成员俘虏了。",al={"瑟瑞露尼是谁","瑟瑞露尼背景故事","瑟瑞露尼是什么"}},{q="为什么瑟瑞露尼会被困在主宰之剑？",a="瑟瑞露尼遭到了暮光之锤教派成员的伏击并被困住，这些教派成员在主宰之剑那巨大的石化遗骸周围建立了一个邪恶营地。",al={"她为什么被俘虏","瑟瑞露尼是如何被抓住的","主宰之剑邪教徒"}},{q="瑟瑞露尼有家人吗？",a="有的，瑟瑞露尼是瑟瑞希尔的姐妹，瑟瑞希尔是另一位居住在卡利姆多北部林地中的森林女神。",al={"瑟瑞露尼的姐妹","瑟瑞希尔与瑟瑞露尼","瑟瑞露尼的家人"}},{q="当你帮助她逃脱后会发生什么？",a="当冒险者扫清敌对教派成员的障碍后，瑟瑞露尼会成功逃离主宰之剑并回到周围荒野的安全地带。",al={"瑟瑞露尼的逃脱","任务945","瑟瑞露尼做什么"}}},fx={f442f40d={q="瑟瑞露尼站在哪一方？",a="瑟瑞露尼是暗夜精灵和自然力量的盟友。身为塞纳留斯之女的树妖，她坚定地反对暮光之锤教徒等黑暗势力。她被这些教徒俘虏后，欣然接受友善旅人的帮助，盼望重获自由。",al={"瑟瑞露尼的阵营","瑟瑞露尼是联盟成员吗","瑟瑞露尼友好吗"}},["7872ea33"]={q="瑟瑞露尼想要什么？",a="瑟瑞露尼只想摆脱囚禁她的暮光之锤教徒。她需要一位可靠的保护者护送她安全离开主宰之剑被腐化的土地，好让她与族人团聚。",al={"瑟瑞露尼需要什么","瑟瑞露尼的目标"}}},fp="9,254,19.430.0,17.184.0,48.164.0,31.105.0,38.160.1"}
P.entries["npc:therysil"] = {n="瑟瑞希尔",s="瑟瑞希尔是一位居住在灰谷中心艾森娜神殿的树妖。她深切致力于守护自然，正焦急地等待着关于她妹妹瑟瑞露尼的消息，她的妹妹落入了邪恶教徒的手中。",h="瑟瑞希尔是一位居住在灰谷中心艾森娜神殿的树妖。她深切致力于守护自然，正焦急地等待着关于她妹妹瑟瑞露尼的消息，她的妹妹落入了邪恶教徒的手中。",kw={"灰谷","塞纳留斯","树妖","艾森娜神殿","瑟瑞露尼","瑟瑞希尔","暮光之锤"},ang={["class:Druid"]="作为塞纳留斯之女，瑟瑞希尔代表了塞纳里奥议会与灰谷自然之灵之间的深厚纽带，这使得她的困境对来访的德鲁伊来说显得格外紧迫。",["race:NightElf"]="长期以来，树妖一直是暗夜精灵在守护灰谷圣林（如艾森娜神殿）时的坚定盟友。"},sec={{t="守护者的警觉",b="瑟瑞希尔以艾森娜神殿宁静的水域为家，那是一片位于灰谷古老森林中的圣洁林地。作为塞纳留斯之女，像所有的树妖一样，她肩负着保卫荒野和其中栖息的生灵的职责。然而，她的注意力已从平静的守护转为忧心忡忡。她的妹妹瑟瑞露尼在附近被疯狂的暮光之锤教派俘虏，这让瑟瑞希尔急切地盼望着有路过的盟友能协助营救她的妹妹。"}},faq={{q="瑟瑞希尔是谁？",a="瑟瑞希尔是一位居住在灰谷艾森娜神殿的树妖。她是塞纳留斯之女，也是瑟瑞露尼的姐姐。",al={"瑟瑞希尔是谁","瑟瑞希尔背景故事","艾森娜神殿的树妖"}},{q="瑟瑞希尔在担心什么？",a="她的妹妹瑟瑞露尼在黑海岸南部的主宰之剑遭到了暮光之锤教徒的伏击并被俘。瑟瑞希尔在神殿等待，希望能有冒险者引导她的妹妹安全回家。",al={"瑟瑞希尔在做什么","瑟瑞希尔为什么担心","瑟瑞希尔任务"}},{q="瑟瑞露尼是谁？",a="瑟瑞露尼是瑟瑞希尔的妹妹，也是灰谷的另一位树妖。她被暮光之锤俘虏，需要护送才能逃脱他们的魔掌并与瑟瑞希尔团聚。",al={"瑟瑞露尼","瑟瑞希尔的妹妹","瑟瑞露尼是谁"}},{q="在哪里可以找到瑟瑞希尔？",a="瑟瑞希尔位于艾森娜神殿，这是一个坐落在灰谷中心道路旁的自然圣地。",al={"瑟瑞希尔位置","瑟瑞希尔在哪里","艾森娜神殿树妖"}}},fx={f765b898={q="瑟瑞希尔站在哪一方？",a="瑟瑞希尔是塞纳留斯之女，受到暗夜精灵和荒野之灵的庇护。和大多数树妖一样，她支持灰谷的自然秩序和联盟，坚决反对暮光之锤教徒等玷污古老森林的黑暗入侵者。",al={"瑟瑞希尔的阵营","瑟瑞希尔是联盟成员吗","瑟瑞希尔效忠谁"}},fc91e3f7={q="瑟瑞希尔为什么会在艾森娜神殿？",a="瑟瑞希尔守望着艾森娜神殿。这是一处古老的圣地，供奉着森林之灵。除了照料神殿，她还焦急地等待妹妹瑟瑞露尼的消息。瑟瑞露尼曾前往主宰之剑，落入了潜伏在那里的邪恶教徒手中。",al={"瑟瑞希尔为什么在这里","瑟瑞希尔为什么在艾森娜神殿","瑟瑞希尔在此的职责"}}},fp="8,222,18.489.0,16.132.0,27.217.0,17.176.0,28.112.0"}
P.entries["npc:thor"] = {n="索尔",s="索尔是驻守在西部荒野哨兵岭Gryphon Roost的狮鹫管理员。作为陷入困境的人民民兵与暴风城首都之间的关键空中纽带，他负责指挥信使、侦察兵以及在王国上空传递紧急信息。",h="索尔是驻守在西部荒野哨兵岭Gryphon Roost的狮鹫管理员。作为陷入困境的人民民兵与暴风城首都之间的关键空中纽带，他负责指挥信使、侦察兵以及在王国上空传递紧急信息。",kw={"信使","狮鹫管理员","狮鹫","人民民兵","哨兵岭","索尔","西部荒野"},ang={["faction:Alliance"]="对于协助人民民兵的联盟勇士而言，索尔提供了返回首都以传递战场情报和补充物资的最快路线。"},sec={{t="哨兵岭鹰巢",b="索尔驻守在哨兵岭的狮鹫管理员处，负责管理连接西部荒野前线守军与王国心脏地带的飞行点。当人民民兵在地面上与流窜的强盗、豺狼人以及失控的收割机傀儡苦战时，索尔确保了重要的军事快讯和旅客能够彻底避开危险的道路。通过他驯养的狮鹫，格里安·斯托曼发出的紧急援助请求和报告能比任何地面信使更快地抵达暴风城廷议。"}},faq={{q="索尔是谁？",a="索尔是一名驻守在西部荒野哨兵岭的人类狮鹫管理员。他负责照看那些提供西部荒野与其他联盟定居点（尤其是暴风城）之间空中旅行服务的训练有素的狮鹫。",al={"这家伙是谁","哨兵岭狮鹫管理员","索尔npc"}},{q="他在西部荒野中扮演什么角色？",a="他是哨兵岭的空中生命线。索尔负责协调运送人民民兵与暴风城最高指挥部之间重要军事信件的信使，确保指挥官们尽管受到迪菲亚兄弟会活跃活动的影响，仍能保持信息畅通。",al={"索尔做什么","索尔的目的"}},{q="为什么这里的狮鹫飞行很重要？",a="连接西部荒野与艾尔文森林和暮色森林的道路上充斥着迪菲亚强盗、河爪豺狼人以及危险的野生生物。狮鹫飞行提供了一条安全、快捷的绕行路线，使补给线和通讯线得以保持完整。",al={"为什么在西部荒野飞行","西部荒野飞行点"}}},fx={["5cbb8458"]={q="索尔站在哪一方？",a="索尔忠于联盟，直接与哨兵岭的人民军并肩行动。他受暴风城狮鹫管理员体系的调遣，为王国运送可信赖的信使、士兵和冒险者，飞越联盟领空，确保西部荒野与首都保持重要联系。",al={"索尔的效忠对象","索尔是联盟成员吗","索尔效忠谁"}},a791490a={q="索尔想要什么？",a="索尔的目标是维持哨兵岭与暴风城等友方据点之间的空中交通。他专注于照料狮鹫并确保它们随时待命，让紧急报告和旅人能及时飞越西部荒野道路上盘踞的强盗与野兽。",al={"索尔的动机","索尔在做什么","索尔在西部荒野的职责"}},f6f75bde={q="索尔为什么驻扎在哨兵岭？",a="哨兵岭是人民军抵御迪菲亚潜行者的坚固堡垒。索尔驻扎在这座高地要塞上，因为穿越西部荒野的陆路危机四伏、随时可能遭到伏击；乘坐狮鹫飞行，是返回艾尔文森林和暴风城最快捷、最安全的途径。",al={"索尔为什么在西部荒野","索尔在哨兵岭的位置","索尔为什么在这里"}},["62307107"]={q="索尔与谁有牵连？",a="索尔与暴风城的狮鹫管理员关系密切，并在首都与狮鹫管理员杜加尔·朗德瑞克携手合作。在当地，他与格里安·斯托曼和哨兵岭的守军协作，为他们提供重要的交通和侦察联络，帮助他们了解外界情况。",al={"索尔的关系","索尔与谁共事","索尔的盟友"}}},fp="4,283,26.531.0,12.202.0,35.254.0,37.230.0"}
P.entries["npc:thorgas-grimson"] = {n="索加斯·格瑞姆森",s="索加斯·格瑞姆森是驻扎在寒脊山谷安威玛尔的矮人猎人训练师。作为一名经验丰富的丹莫罗野外生存专家，他坚信在冰天雪地的荒野中亲身磨练，是所有初出茅庐的神射手能得到的最好的老师。",h="索加斯·格瑞姆森是驻扎在寒脊山谷安威玛尔的矮人猎人训练师。作为一名经验丰富的丹莫罗野外生存专家，他坚信在冰天雪地的荒野中亲身磨练，是所有初出茅庐的神射手能得到的最好的老师。",kw={"安威玛尔","寒脊山谷","丹莫罗","矮人猎人","猎人训练师","索加斯·格瑞姆森"},ang={["class:Hunter"]="对于矮人神射手来说，索加斯·格瑞姆森通常是你遇到的第一位导师，他提供关于追踪野兽和在冰封山谷中生存的早期指导。",["race:Dwarf"]="格瑞姆森体现了铁炉堡登山者坚韧、自立的精神，他们巡逻在丹莫罗冰封的峰顶。"},sec={{t="寒冬中的向导",b="索加斯·格瑞姆森驻守在安威玛尔的石厅内，迎接那些刚刚踏入寒脊山谷严酷雪堆中的新手登山者和侦察兵。格瑞姆森并没有用枯燥的理论去拖累年轻的猎人们，而是推崇一种实践哲学：真正的技能是在寒风中磨砺出来的，手持弓弩或火枪，亲身追踪丹莫罗凶猛的野兽。"}},faq={{q="索加斯·格瑞姆森是谁？",a="索加斯·格瑞姆森是一位矮人猎人训练师，位于丹莫罗寒脊山谷的中心哨所安威玛尔。他为开始冒险的新联盟猎人提供初步指导和基础的野外生存技能。",al={"索加斯·格瑞姆森","索加斯是谁","安威玛尔猎人训练师"}},{q="索加斯提供什么训练？",a="他指导新手猎人掌握基础的野外生存技术，例如在雪地上追踪野兽和磨练基本的远程射击技巧，引领他们走上成为真正登山者的道路。",al={"索加斯教什么","安威玛尔猎人技能"}},{q="他的训练哲学是什么？",a="索加斯坚持认为，理论演习远不如原始经验有效。他相信，真正掌握荒野的唯一方法就是走进冰天雪地中，直面丹莫罗的野兽。",al={"索加斯的性格","索加斯如何训练"}},{q="索加斯·格瑞姆森会和非猎人职业交谈吗？",a="虽然足够礼貌，但索加斯会坦率地告诉其他职业的冒险者，他无法协助他们的训练，并建议他们去寻找适合自己所选道路的导师。",al={"其他职业能和索加斯交谈吗","索加斯闲聊"}}},fx={c3cc0970={q="索加斯·格瑞姆森站在哪一方？",a="索加斯坚定地站在铁炉堡矮人和整个联盟一方。他驻扎在寒脊山谷的安威玛尔，运用自己的本领训练初出茅庐的猎人，帮助他们保卫王国，守护矮人领土免受野兽和敌人的侵袭。",al={"索加斯·格瑞姆森的阵营","索加斯·格瑞姆森的效忠对象","索加斯·格瑞姆森效忠谁"}},["8eae34e9"]={q="索加斯·格瑞姆森想要什么？",a="索加斯想把新手训练成独当一面、技艺娴熟的神射手。他认为真正的本领不能只靠空谈传授，因此希望把新猎人送进冰雪荒野，让他们通过实地历练磨炼追踪和战斗本能。",al={"索加斯·格瑞姆森的目标","索加斯想要什么","索加斯·格瑞姆森的职责"}},d81e027b={q="索加斯·格瑞姆森为什么在安威玛尔？",a="他驻扎在安威玛尔，负责引导新招募的猎人踏入寒脊山谷。山谷因恶劣天气而与外界隔绝，又受到穴居人和野兽的威胁，因此需要索加斯这样的资深追踪者，确保新兵学会生存和战斗。",al={"索加斯为什么在安威玛尔","索加斯·格瑞姆森的位置和原因","索加斯·格瑞姆森为什么在这里"}}},fp="15,256,19.390.0,23.226.0,33.214.0,32.213.0,44.195.0"}
P.entries["npc:thorgrum-borrelson"] = {n="索格拉姆·伯雷森",s="索格拉姆·伯雷森是驻扎在洛克莫丹塞尔萨玛上方的矮人狮鹫管理员。从他俯瞰定居点的栖木处，他照料着连接山谷与铁炉堡以及周边山口的空中坐骑。",h="索格拉姆·伯雷森是驻扎在洛克莫丹塞尔萨玛上方的矮人狮鹫管理员。从他俯瞰定居点的栖木处，他照料着连接山谷与铁炉堡以及周边山口的空中坐骑。",kw={"丹莫罗","飞行管理员","狮鹫管理员","铁炉堡","洛克莫丹","塞尔萨玛","索格拉姆·伯雷森"},ang={["faction:Alliance"]="索格拉姆的飞行管理员栖木是一个至关重要的后勤中转站，将矮人王国的中心与湿地和阿拉希高地的前方阵地连接起来。",["race:Dwarf"]="对于卡兹莫丹的登山者和保卫者来说，索格拉姆·伯雷森确保了一条通往铁炉堡高大殿堂的可靠空中生命线。"},sec={{t="塞尔萨玛上方的栖木",b="索格拉姆·伯雷森栖身于塞尔萨玛上方隆起的悬崖上，负责处理联盟在整个洛克莫丹的空中运输。由于穴居人的入侵和豺狼人部族威胁着陆路交通，他训练有素的狮鹫为穿越崎岖的山脊提供了至关重要的交通方式。他维持着频繁往返于南门小径与丹莫罗Great Forge之间的航线，以及通往湿地及更远地区的航线。"}},faq={{q="索格拉姆·伯雷森是谁？",a="索格拉姆·伯雷森是驻扎在塞尔萨玛的联盟狮鹫管理员。他负责监管进出洛克莫丹地区的空中旅行。",al={"索格拉姆","塞尔萨玛飞行管理员","塞尔萨玛的狮鹫管理员是谁"}},{q="索格拉姆可以将旅客送到哪里？",a="索格拉姆负责协调连接塞尔萨玛与各大枢纽的飞行航线，例如矮人主城铁炉堡、湿地的米奈希尔港、阿拉希高地的避难谷地、河林的法霍德要塞，以及周边地区的多个前哨站。",al={"塞尔萨玛飞行路线","我可以从洛克莫丹飞往哪里"}},{q="为什么在洛克莫丹狮鹫旅行很重要？",a="通过洛克莫丹的陆路旅行经常受到敌对的穴居人巢穴、豺狼人以及争夺山口的黑铁侦察兵的威胁。狮鹫使联盟的信使、侦察兵和冒险者能够快速绕过这些危险。",al={"为什么要从洛克莫丹飞行","洛克莫丹交通"}}},fx={["30011ebf"]={q="索格拉姆·伯雷森效忠哪一方？",a="索格拉姆是铁炉堡的忠诚臣民，为联盟效力。作为驻扎在塞尔萨玛正上方的当地飞行管理员，他管理着空中信使与交通网络，将山地王国的首都与周边领土连接起来，确保联盟的信使和旅人能迅速穿行于卡兹莫丹。",al={"索格拉姆·伯雷森所属阵营","索格拉姆为谁效力","索格拉姆属于联盟吗"}},aebc9bb6={q="索格拉姆·伯雷森想要什么？",a="索格拉姆最关心的是确保空域畅通，并维持洛克莫丹与其他联盟据点之间稳定的空中联络。他照料着栖息在塞尔萨玛上方山脊上的狮鹫，并确保信使、冒险者和急件都能及时抵达铁炉堡等目的地。",al={"索格拉姆想要什么","索格拉姆·伯雷森的目标","索格拉姆的职责"}},db7b8a65={q="索格拉姆·伯雷森为什么在这里？",a="索格拉姆驻扎在俯瞰塞尔萨玛的悬崖上，因为这座城镇是洛克莫丹的中心。山间隘道的陆路交通经常受到穴居人、狗头人和敌对野生动物的威胁，设立专门的狮鹫栖木，便能确保山谷聚居地与Great Forge之间的联系畅通无阻。",al={"索格拉姆为什么在洛克莫丹","索格拉姆为什么在塞尔萨玛上方","索格拉姆驻扎此处的目的"}}},fp="18,233,25.427.0,26.145.0,34.275.0,46.236.0"}
P.entries["npc:thork"] = {n="索克",s="索克是一名驻扎在十字路口的兽人战士，负责监管该定居点的当地防御。他肩负着确保贫瘠之地繁忙的十字路口安全的重任，指挥部落的冒险者们击退袭击者并保障重要补给线的安全。",h="索克是一名驻扎在十字路口的兽人战士，负责监管该定居点的当地防御。他肩负着确保贫瘠之地繁忙的十字路口安全的重任，指挥部落的冒险者们击退袭击者并保障重要补给线的安全。",kw={"贫瘠之地","十字路口","卡德拉克","曼科里克","莫尔杉","兽人","补给","索克"},ang={["class:Warrior"]="战士们会赞赏索克务实、直接的战略方针，他专注于补给线的安全、巡逻的完整性，并在威胁突破城镇围墙之前将其消灭。",["faction:Horde"]="对于从杜隆塔尔或莫高雷赶来的部落冒险者来说，向索克报到是确立你作为卡利姆多保护者声望的一个重要里程碑。",["race:Orc"]="索克代表了兽人在保卫新征服的卡利姆多土地、抵御压倒性的区域敌意时所应具备的坚定不移的军事职责。"},sec={{t="十字路口指挥官",b="十字路口是部落在卡利姆多交通往来的核心，连接着杜隆塔尔、莫高雷以及更遥远的荒野。守住这里并非易事。索克肩负着保卫城镇免受持续外部压力的重任。面对野猪人的袭击、半人马的侵略以及鹰身人的劫掠，他的兵力捉襟见肘，迫使他不得不依靠有能力的旅行者和初出茅庐的勇士来处理关键的安全任务。"},{t="保卫边境",b="索克的职责远不止在十字路口的围墙之内。他协调各条重要补给走廊的防御工作，派遣斥候和联络员前往北方的莫尔杉壁垒，直接向卡德拉克汇报。保持这些北部和东部动脉的畅通对于维持部落在贫瘠之地这片严酷且无情的灌木林中的存在至关重要。"},{t="内忧外患",b="索克也会奖赏那些揭露棘鬃野猪人袭击幕后主使的冒险者。被俘的野猪人碎牙通过帮助旅行者打击其领袖，背叛了自己的部落。当他们把 Lok Orcbane 的首级带到十字路口时，索克感谢他们削弱了对部落补给线的攻击。"}},faq={{q="索克是谁？",a="索克是负责贫瘠之地十字路口军事防御的兽人军官。他监管城镇安全，组织针对敌对部落的反击，并确保补给车队安全抵达目的地。",al={"索克背景故事","索克是谁","索克 十字路口"}},{q="索克在哪里？",a="他站在贫瘠之地十字路口定居点的中心外，指挥卫兵并发布防御命令。",al={"索克位置","寻找索克","索克在哪里"}},{q="为什么十字路口如此容易受到攻击？",a="十字路口位于贫瘠之地主要贸易路线的交汇处。由于它缺乏坚固的石质防御工事，且毗邻敌对的棘鬃野猪人、考尔克半人马和联盟斥候控制的领土，因此需要时刻保持警惕来防守。",al={"十字路口遭受攻击","为什么十字路口危险"}},{q="索克与曼科里克是什么关系？",a="当曼科里克恳求军事援助以追捕野猪人并寻找失踪的妻子时，索克因兵力有限且必须优先保卫前哨站及其补给车队的严格规定，拒绝了他的请求。",al={"曼科里克与索克","索克是否帮助了曼科里克"}},{q="索克如何与其他部落哨所协调？",a="索克与北部边境保持定期通讯，派遣信使和战士向莫尔杉壁垒的卡德拉克汇报，以监控灰谷的边界。",al={"索克与卡德拉克","索克 莫尔杉壁垒"}},{q="索克处理哪些威胁？",a="索克处理扰乱贸易并窃取补给箱的野猪人劫掠团。他还奖励那些击败这些袭击幕后头目的冒险者。",al={"十字路口的敌人","索克任务信息"}}},fx={["3a5917fe"]={q="索克效忠哪一方？",a="索克是萨尔麾下部落的一名坚定军官。他驻扎在卡利姆多腹地，指挥十字路口的当地防务，保障重要补给路线，保护抵达的旅人，并守护贫瘠之地中部的兽人和牛头人领地。",al={"索克所属阵营","索克属于部落还是联盟","索克为谁效力"}},["0b2cf0f5"]={q="索克想要什么？",a="索克希望十字路口安稳无虞。他致力于维持秩序，确保补给商队安全穿过干旱平原，并击退威胁聚居地存续的敌对劫掠者。",al={"索克的目标","索克想做什么","索克的目的"}},["56f2bf7a"]={q="索克为什么在这里？",a="十字路口是连接杜隆塔尔、莫高雷和北部边境的重要枢纽。索克受命负责守卫这个易受攻击的据点，协调巡逻、集结抵达的勇士，并确保年轻部落的贸易命脉不会在野外劫掠者的持续袭扰下断绝。",al={"索克为什么在十字路口","索克在贫瘠之地的职责","索克为什么被派驻此地"}}},fp="5,240,27.439.0,20.379.0,22.310.1,13.223.0,23.141.0,46.271.0,42.218.0,49.180.0,34.160.0"}
P.entries["npc:thorvald-deepforge"] = {n="索瓦尔德·深炉",s="索瓦尔德·深炉是一名矮人武器商，驻扎在国王谷的边境山口附近。他协助为往来的旅客和守卫提供武装，确保了丹莫罗和洛克莫丹之间这条关键通道的安全。",h="索瓦尔德·深炉是一名矮人武器商，驻扎在国王谷的边境山口附近。他协助为往来的旅客和守卫提供武装，确保了丹莫罗和洛克莫丹之间这条关键通道的安全。",kw={"深炉","丹莫罗","洛克莫丹","矮人步枪手","索瓦尔德·深炉","国王谷","武器匠"},ang={["profession:Blacksmithing"]="索瓦尔德承袭了著名的深炉家族名号，他所经营的都是矮人铁匠引以为傲的实用且可靠的铁器。",["race:Dwarf"]="站在国王谷祖先巨石下，索瓦尔德代表了那经久不衰的工艺与补给线，正是这些维系着Khaz Modan边境的安全。"},sec={{t="武装东部山口",b="索瓦尔德·深炉坐镇在国王谷高耸的纪念碑内，作为一名值得信赖的武器商为联盟效力。连接Khaz Modan内陆与外围地区的山路常受穴居怪入侵和游荡野生动物的侵扰，因此，对于路上的任何矮人步枪手或新兵来说，精良的钢铁装备都至关重要。索瓦尔德确保那些从丹莫罗抵达或正前往洛克莫丹深处的旅人，都能携带保卫矮人领土所需的刀剑和斧头。"}},faq={{q="谁是索瓦尔德·深炉？",a="索瓦尔德·深炉是一位驻扎在国王谷的矮人商贩，这里是从丹莫罗通往洛克莫丹的必经之路。他为沿线的旅客和守卫提供必要的武器。",al={"谁是索瓦尔德","索瓦尔德·深炉 npc","深炉 洛克莫丹"}},{q="他在该地区的防御中扮演什么角色？",a="他担任穿越山口的旅客的前方军需官和武器商，协助为派往增援洛克莫丹各地哨所的新兵提供武装。",al={"索瓦尔德做什么","索瓦尔德的目的","前线补给"}},{q="他与其他Khaz Modan的深炉家族成员有亲戚关系吗？",a="可能。有几位矮人也叫“深炉”，包括Murgot Deepforge和Bengus Deepforge，但目前没有确认过家族血缘关系。Great Forge的托姆斯·深炉称索瓦尔德为同事。",al={"深炉家族","索瓦尔德·深炉的亲属","murgot deepforge 亲属"}}},fx={["7578ebb9"]={q="索瓦尔德·深炉效忠哪一方？",a="索瓦尔德·深炉是铁炉堡的忠诚矮人，坚定地支持联盟。他驻扎在国王谷，协助巡山人守卫卡兹莫丹，为当地部队提供武器和装备，以对抗穴居人及其他威胁。",al={"索瓦尔德·深炉所属阵营","索瓦尔德·深炉属于联盟吗","索瓦尔德为谁效力"}},["2f5ea740"]={q="索瓦尔德·深炉想要什么？",a="索瓦尔德致力于确保联盟的守军装备精良、随时待命。他驻守在洛克莫丹南部的卫兵塔，为正在与穴居人作战的巡山人提供武器和护甲，也欢迎带来新装备的铁匠。",al={"索瓦尔德·深炉的目标","索瓦尔德·深炉需要什么","索瓦尔德·深炉的动机"}}},fp="18,204,23.487.0,26.202.0,47.175.0,52.195.0"}
P.entries["npc:thotar"] = {n="索塔尔",s="索塔尔是一位经验丰富的兽人猎人训练师，驻扎在杜隆塔尔的剃刀岭定居点。他指导有抱负的部落斥候和神射手学习追踪、射箭以及与野兽结伴的古老传统。对于那些迈出试炼谷第一步的年轻兽人和巨魔来说，他传授的是掌握卡利姆多严酷野生动物群所需的基础仪式。",h="索塔尔是一位经验丰富的兽人猎人训练师，驻扎在杜隆塔尔的剃刀岭定居点。他指导有抱负的部落斥候和神射手学习追踪、射箭以及与野兽结伴的古老传统。对于那些迈出试炼谷第一步的年轻兽人和巨魔来说，他传授的是掌握卡利姆多严酷野生动物群...",kw={"杜隆塔尔","猎人","猎人训练师","卡普拉克","兽人","剃刀岭","taming the beast","索塔尔"},ang={["class:Hunter"]="索塔尔是年轻部落猎人的一个重要里程碑，当新手走出新手谷地时，他会教授至关重要的驯兽和荒野精通仪式。",["faction:Horde"]="作为剃刀岭的一线训练师，索塔尔确保巡逻杜隆塔尔边境的斥候和神射手纪律严明、目光锐利，并与战斗野兽建立了良好的纽带。",["race:Orc"]="索塔尔保护并传承着传统的兽人狩猎习俗，确保卡利姆多的生活始终扎根于对追踪和野兽结伴关系的深厚祖传敬意之中。",["race:Troll"]="对于从森金村出发的暗矛巨魔猎人，索塔尔提供了至关重要的指导，将部落祖传的生存技能与杜隆塔尔的掠食挑战融合在了一起。"},sec={{t="剃刀岭的导师",b="索塔尔身处剃刀岭的防御中心，是部落神射手的资深教官。虽然新兵在试炼谷学习最基础的知识，但当猎人们面对杜隆塔尔更加严酷的野外掠食者时，便由索塔尔来指引他们。他借鉴了兽人无数代人传承下来的传统，不仅教授射击技巧，还教导猎人们如何与卡利姆多最致命的生物共存并驾驭它们，这需要更深层次的尊重。"},{t="驯服荒野",b="索塔尔在向年轻猎人介绍古老的驯兽艺术方面发挥着至关重要的作用。通过一系列试炼，他将新手派往干旱的峡谷，去安抚并与当地野兽沟通，比如毒蝎、装甲冲浪爬行者和狡猾的野猪。通过引导这些年轻斥候完成神圣的驯服仪式，索塔尔确保了部落的追踪者与自然建立起忠诚的纽带，而不是仅仅试图靠武力征服它。"}},faq={{q="谁是索塔尔？",a="索塔尔是一位驻扎在杜隆塔尔剃刀岭的资深兽人猎人训练师。他教导年轻猎人学习传统的荒野知识、射击技巧和驯兽术。",al={"谁是索塔尔","索塔尔背景故事","索塔尔做什么"}},{q="在哪里可以找到索塔尔？",a="他位于杜隆塔尔中部的部落定居点剃刀岭，就在试炼谷的北面。",al={"索塔尔位置","索塔尔在哪里","找到索塔尔"}},{q="索塔尔传授什么传统？",a="索塔尔传授的是兽人世代相传的古老生存和追踪传统。他强调武器掌握、荒野生存，以及通过耐心和仪式学习与动物伙伴建立联系。",al={"索塔尔教授什么","猎人传统","索塔尔训练"}},{q="索塔尔只训练兽人吗？",a="虽然他是深受本族习俗影响的兽人，但索塔尔会指导任何到达剃刀岭的部落猎人，并经常教导暗矛巨魔和途经杜隆塔尔的流浪牛头人。",al={"巨魔可以接受索塔尔的训练吗","索塔尔 牛头人","索塔尔训练谁"}},{q="索塔尔给年轻猎人布置什么任务？",a="索塔尔指导新手猎人完成“Taming the Beast”的仪式，任务是追踪杜隆塔尔当地的野生动物（如野猪、冲浪爬行者和蝎子），并使用驯兽棒来获得它们的信任和服从。",al={"索塔尔任务","taming the beast 索塔尔","索塔尔派你去做什么"}},{q="为什么驯兽在他的训练中如此重要？",a="对于部落猎人来说，野兽同伴是战场和荒野中至关重要的伙伴。索塔尔教导说，与野兽建立适当的纽带能确保双方共同生存，将原始的掠食者转化为部落忠诚的保卫者。",al={"为什么要驯服野兽","猎人宠物背景","驯服野兽的目的"}}},fx={["07bd0b61"]={q="索塔尔效忠哪一方？",a="索塔尔坚定地支持部落。他驻扎在剃刀岭，专心磨练部落的实力，训练新来的兽人、巨魔和牛头人猎人，使他们能够在荒野中生存并守卫自己的土地。",al={"索塔尔所属阵营","索塔尔是部落成员吗","索塔尔的效忠对象"}},["83013f85"]={q="索塔尔想要什么？",a="索塔尔希望将祖先的狩猎传统传承给新一代。他要求有志成为猎人的人掌握追踪、生存和驯服野兽的本领，以此证明他们尊重荒野。",al={"索塔尔想要什么","索塔尔的目标","索塔尔的职责"}},["0fc388b7"]={q="索塔尔为什么在剃刀岭？",a="剃刀岭是年轻冒险者离开试炼谷、踏上征途前的主要集结地。索塔尔和其他训练师一起留在这里，为新一代猎人做好准备，之后他们便会深入杜隆塔尔以及更广阔世界的险境。",al={"索塔尔为什么在这里","索塔尔为什么在剃刀岭","索塔尔和剃刀岭"}}},fp="6,374,22.474.0,16.459.0,14.165.0,26.116.0,34.224.0,28.209.0,45.226.0,49.228.0"}
P.entries["npc:thrall"] = {n="萨尔",s="萨尔是部落大酋长，也是杜隆塔尔的统治者，在奥格瑞玛的智慧谷坐镇。他曾是一名被当作角斗士抚养长大的兽人奴隶，后来他打破了族人的枷锁，重新发现了古老的萨满传统，并带领族人跨越无尽之海，建立了一个新的家园。",h="萨尔是部落大酋长，也是杜隆塔尔的统治者，在奥格瑞玛的智慧谷坐镇。他曾是一名被当作角斗士抚养长大的兽人奴隶，后来他打破了族人的枷锁，重新发现了古老的萨满传统，并带领族人跨越无尽之海，建立了一个新的家园。",kw={"布莱克摩尔","毁灭之锤","杜隆塔尔","古伊尔","奥格瑞玛","萨满","萨尔","大酋长"},ang={["class:Shaman"]="萨尔被尊为新一代兽人中的第一位萨满，在经历了数十年的恶魔腐化后，他恢复了族人与元素之灵之间神圣的交流。",["faction:Alliance"]="联盟领袖将萨尔视为一位危险但务实的领导人，认为他纪律严明的部落比起第一次和第二次战争中嗜血的征服者要好得多。",["faction:Horde"]="萨尔是你们的最高统帅和大酋长，他带领部落摆脱了奴役与毁灭，在卡利姆多开辟了荣耀的未来。",["race:Orc"]="对于兽人来说，萨尔是一位活着的救世主，他打破了人类收容所带来的萎靡，让这个种族重获了祖先的荣誉。"},sec={{t="从奴隶到萨满",b="萨尔原名古伊尔，是霜狼氏族酋长杜隆坦与德拉卡的儿子。他在襁褓中就成了孤儿，父母被古尔丹的刺客杀害。他被人类指挥官埃德拉斯·布莱克摩尔发现，并为他取名“萨尔”——意为奴隶。他在敦霍尔德城堡被当作角斗士抚养长大，并接受了人类战术的教育。在养姐塔蕾莎·福克斯顿的帮助下，萨尔最终逃离了囚禁。在霜狼氏族流放者德雷克塔尔的指引下，他摒弃了恶魔的腐化，掌握了元素之灵的力量，成为了新一代兽人萨满中的第一人。"},{t="大酋长的重任",b="萨尔与传奇人物奥格瑞姆·毁灭之锤联手，解放了在第二次战争后被关押在联盟收容所中、饱受折磨的兽人。当毁灭之锤在战斗中牺牲时，他将自己的黑色板甲和强大的战锤传给了萨尔，并任命他为新任大酋长。在神秘的先知麦迪文传达了预言性的幻象后，萨尔带领族人夺取了人类的船只，横跨无尽之海，航向被遗忘的卡利姆多大陆，逃离了即将降临在东部王国的末日。"},{t="重铸新部落",b="在卡利姆多，萨尔将部落从一个好战的战争机器重塑为一个基于生存与荣誉的联盟。他解救了沃金领导的暗矛巨魔，并与凯恩·血蹄的牛头人结盟，随后率领联军与人类和暗夜精灵军队并肩作战，击败了海加尔山上的燃烧军团。此后，萨尔建立了杜隆塔尔国，并以他父亲和导师的名字命名了首都奥格瑞玛。尽管与吉安娜·普罗德摩尔的塞拉摩维持着脆弱的和平，但萨尔现在必须在他脆弱的国家的防务与充满争议的联盟之间寻求平衡，比如接纳洛丹伦的被遗忘者加入部落。"}},faq={{q="萨尔是谁？",a="萨尔是部落的大酋长，也是兽人人民的领袖。他出生时名为古伊尔，属于霜狼氏族，曾被人类当作角斗士奴役，后来他获得了自由，学会了萨满技艺，并带领兽人前往卡利姆多建立了他们的新首都奥格瑞玛。",al={"谁是大酋长","萨尔背景故事","萨尔是谁"}},{q="萨尔的名字从何而来？",a="他的本名是古伊尔，由他的父母杜隆坦和德拉卡所取。囚禁他的人类埃德拉斯·布莱克摩尔给他取名“萨尔”——这是一个古老的人类词汇，意为奴隶。萨尔保留了这个名字，作为对自己出身的提醒，也时刻提醒着他，他的族人发誓绝不再忍受那样的压迫。",al={"为什么他叫萨尔","萨尔的意思","萨尔真名"}},{q="为什么萨尔穿着黑色盔甲，拿着一把战锤？",a="萨尔穿着黑色板甲，挥舞着从前任大酋长奥格瑞姆·毁灭之锤那里传下来的毁灭之锤。在解放收容所的战斗中身受致命伤时，奥格瑞姆在临终前将武器和大酋长的重任都交给了萨尔。",al={"毁灭之锤","萨尔的武器","黑色盔甲"}},{q="我在游戏里哪里可以找到萨尔？",a="萨尔居住在奥格瑞玛的智慧谷内，那里是部落在杜隆塔尔的首都。他站在格罗玛什要塞内，身边有保镖和顾问相随。",al={"萨尔在哪里","萨尔位置","萨尔的房间"}},{q="萨尔和吉安娜·普罗德摩尔是什么关系？",a="萨尔和吉安娜·普罗德摩尔在第三次战争期间于海加尔山并肩作战时，建立了相互尊重与合作的契约。尽管各自的阵营仍然深存疑虑，但两位领袖都在努力维护奥格瑞玛与塞拉摩之间脆弱的和平。",al={"萨尔和吉安娜","吉安娜联盟","与塞拉摩的和平"}},{q="萨尔为什么允许被遗忘者加入部落？",a="虽然对亡灵持谨慎态度，但萨尔认识到了希尔瓦娜斯·风行者领导的被遗忘者所处的绝望境地，他们已经摆脱了巫妖王的控制。在牛头人外交上的积极劝说下，他们认为被遗忘者可以获得救赎，萨尔授予了他们部落成员资格，以确保在东部王国获得一个战略立足点。",al={"为什么亡灵在部落","被遗忘者联盟","希尔瓦娜斯加入部落"}}},fx={["6dbf9cfd"]={q="萨尔效忠哪一方？",a="萨尔是部落的大酋长。他将这个派系从一群支离破碎的俘虏重建为团结求存的联盟，使自己的兽人与暗矛巨魔、卡利姆多的牛头人，以及近期加入的洛丹伦被遗忘者携手并肩。他对自己的人民忠心耿耿，同时也努力与联盟维持脆弱的和平。",al={"萨尔所属阵营","萨尔领导谁","萨尔属于联盟还是部落"}},["4a2053d7"]={q="萨尔想要什么？",a="萨尔希望部落拥有安全而光荣的未来，远离曾令他的族人走向毁灭的恶魔腐化与嗜血之欲。他努力在杜隆塔尔建立永久的家园，让兽人重拾古老的萨满传统，并与邻人维持脆弱的共存关系，避免卡利姆多再度陷入无休止的杀戮。",al={"萨尔的目标是什么","萨尔的动机","萨尔的目标"}},b797ddf7={q="萨尔为什么在奥格瑞玛？",a="奥格瑞玛是萨尔创建的堡垒之都，其名是为了纪念奥格瑞姆·毁灭之锤。他在Grommash Hold坐镇，统筹杜隆塔尔的防御与发展，处理部落外交，并以大酋长和大师级萨满的身份与灵魂沟通。",al={"萨尔为什么在这里","萨尔为什么在智慧谷","萨尔在奥格瑞玛做什么"}},c1597526={q="为什么萨尔在艾泽拉斯如此有名？",a="萨尔因摧毁联盟的收容营、解放麻木颓废的兽人，并恢复他们失落的精神传承而声名远扬。在第三次战争期间，他率领族人渡过无尽之海，并与人类和暗夜精灵并肩作战，在海加尔山之巅击败燃烧军团，进一步成就了自己的传奇。",al={"为什么人们畏惧萨尔","萨尔有名吗","萨尔的传奇"}}},fp="6,309,20.582.0,26.515.0,21.637.0,14.279.0,35.276.0,52.288.0,36.165.0,52.297.0,49.333.0"}
P.entries["npc:thran-khorman"] = {n="斯兰·库尔曼",s="斯兰·库尔曼是驻扎在安威玛尔的矮人战士训练师，该处坐落于白雪皑皑的寒脊山谷中。他负责监督那些刚踏入丹莫罗的新晋战士的基础战斗训练。",h="斯兰·库尔曼是驻扎在安威玛尔的矮人战士训练师，该处坐落于白雪皑皑的寒脊山谷中。他负责监督那些刚踏入丹莫罗的新晋战士的基础战斗训练。",kw={"安威玛尔","寒脊山小径","丹莫罗","铁炉堡","斯兰·库尔曼","战士训练师"},ang={["class:Warrior"]="对于在寒脊山小径觉醒的矮人和侏儒战士来说，斯兰是第一位考验你勇气的导师，他会交给你初始的符文或命令，并教导你战场生存的基础知识。",["race:Dwarf"]="斯兰是铁炉堡保卫者们那固执、坚定意志的缩影，即使在和平时期也保持警惕，确保王国永远不会措手不及。"},sec={{t="寒脊山谷的教官",b="斯兰·库尔曼站在安威玛尔的训练场旁，负责将初出茅庐的矮人新兵和来访的侏儒训练成纪律严明的战斗人员。对于那些缺乏一线战斗勇气的人，他总是保持着粗暴且毫不妥协的态度。在他看来，尽管第三次战争已经结束，但和平仅仅是一种幻象：穴居人不断侵扰寒脊山小径，而群山之中依然危机四伏。他要求战士们对斧、锤和盾进行刻苦练习，以确保铁炉堡的保卫者们时刻保持锋芒。"}},faq={{q="斯兰·库尔曼是谁？",a="斯兰·库尔曼是驻扎在丹莫罗安威玛尔的矮人战士训练师。他为在寒脊山谷开启冒险旅程的新手战士提供最初的战斗指导与训练。",al={"斯兰·库尔曼职责","斯兰是谁","安威玛尔战士训练师"}},{q="他提供什么样的训练？",a="他指导新手战士掌握武力战斗的基本准则，帮助他们在前往应对山径上的穴居人和野兽之前，磨炼自己的姿态、近战技巧和战场胆识。",al={"斯兰教授什么","战士技能斯兰"}},{q="为什么他对某些旅行者表现得不屑一顾或生硬？",a="斯兰的生活与武道融为一体，对于那些追求奥术、暗影或精巧技艺的人，他没什么耐心。如果你不是一名战士，他会直言不讳地告诉你，你在他的训练体系下连一天都活不下去。",al={"为什么斯兰粗鲁","斯兰闲谈","斯兰非战士对话"}}},fx={["97dd6db6"]={q="斯兰·库尔曼效忠哪一方？",a="斯兰·库尔曼坚定地支持铁炉堡和联盟。他驻扎在寒脊山谷的安威玛尔，专心训练新来的矮人和侏儒新兵，确保丹莫罗能够抵御任何威胁。",al={"斯兰·库尔曼效忠哪一方","斯兰·库尔曼所属阵营","斯兰为谁效力"}},["1baa464c"]={q="斯兰·库尔曼想要什么？",a="他希望有志从军的人认真对待军事纪律，并让战斗技巧时刻保持精湛。即便眼下大战已经停歇，他也不允许任何人懈怠，要求每一位有志成为战士的人全力投入训练。",al={"斯兰·库尔曼的目标","斯兰·库尔曼关心什么","斯兰·库尔曼的动机"}},d4f40481={q="斯兰·库尔曼为什么在这里？",a="斯兰驻扎在安威玛尔，负责将初出茅庐的冒险者锤炼成纪律严明的战士。寒脊山谷是铁炉堡新一代守卫的试炼场，他确保每个人在踏入丹莫罗之前，都懂得如何持剑披甲。",al={"斯兰·库尔曼为什么在安威玛尔","是什么让斯兰来到寒脊山谷","斯兰·库尔曼的职责"}}},fp="13,213,31.528.0,21.197.0,28.221.0,51.239.0"}
P.entries["npc:thunderaan"] = {n="Thunderaan",s="桑德兰王子是古老的风之王子，一位在火与风的远古战争中被击败并遭到背叛的庞大元素生物。拉格纳罗斯这位炎魔之王吞噬了他的一部分，将其残余的精华封印在交给炎魔副官保管的破碎桎梏中。恢复这些圣物的冒险者可以前往希利苏斯寻找德米提恩公爵，再次释放他。",h="桑德兰王子是古老的风之王子，一位在火与风的远古战争中被击败并遭到背叛的庞大元素生物。拉格纳罗斯这位炎魔之王吞噬了他的一部分，将其残余的精华封印在交给炎魔副官保管的破碎桎梏中。恢复这些圣物的冒险者可以前往希利苏斯寻找德米提...",kw={"桎梏","德米提恩","加尔","迦顿","熔火之心","风之王子","拉格纳罗斯","希利苏斯","thunderaan","雷霆之怒","逐风者"},ang={["class:Rogue"]="追求极致速度和闪电般战斗风格的潜行者们，觊觎着风之王子那落入凡间的精华，这些精华被束缚在那把标志性的利刃“雷霆之怒”中。",["class:Shaman"]="作为元素的精神守护者，萨满祭司们公认桑德兰是艾泽拉斯最纯净、最狂怒的风与闪电的化身之一。",["class:Warrior"]="战士们都在寻求“雷霆之怒”的传奇，这把与风之王子相关的风暴之剑。"},sec={{t="元素分裂",b="很久以前，在元素分裂时期——一场发生在艾泽拉斯深处，火元素与风元素势力之间长达五千年的冲突中——拉格纳罗斯试图摧毁并吞噬桑德兰。这位王子遭到了拉格纳罗斯强大的副官加尔和迦顿男爵的伏击与背叛，随后被炎魔之王的锤子萨弗拉斯击败。尽管被打败，但桑德兰的精华力量过于强大，拉格纳罗斯无法将其完全吸收。"},{t="破碎的护符",b="由于无法彻底吞噬这位风之王子，拉格纳罗斯将桑德兰残余的精华封印在了一个元素缚地护符中。为了防止王子复活，炎魔之王将护符粉碎成两块完美的碎片。他将其中一块交给迦顿男爵，另一块交给加尔，并将两者都隐藏在黑石山下的熔火之心中。"},{t="希利苏斯的重生",b="那些胆敢入侵熔火之心的冒险者可以从拉格纳罗斯的副官手中夺取两块桎梏碎片。将这些碎片交给希利苏斯干旱沙丘中，与暮光之锤结盟的古怪隐士德米提恩公爵，便可开启召唤风之王子的仪式。然而，这位新生的元素生物出现时并非怀着感激，而是带着狂暴的飓风怒火，迫使召唤者将其击败，以夺取他的传奇之刃——雷霆之怒，逐风者的祝福之剑。"}},faq={{q="桑德兰是谁？",a="桑德兰是风之王子，一位与风元素相合的高贵而毁灭性的元素领主。很久以前，他被炎魔之王拉格纳罗斯击败，并被封印在元素牢笼中。",al={"桑德兰王子是谁","风之王子","桑德兰背景故事"}},{q="桑德兰最初是如何被打败的？",a="在元素分裂时期，拉格纳罗斯与他的副官迦顿男爵和加尔合谋背叛了这位王子。桑德兰被萨弗拉斯重创，虽然拉格纳罗斯吞噬了他的精华，但无法将其完全消化，迫使他将剩余部分封锁在一个分裂的护符中。",al={"桑德兰怎么死的","拉格纳罗斯对战桑德兰","元素分裂"}},{q="他的桎梏碎片被保存在哪里？",a="桑德兰的桎梏的两块完美碎片分别由加尔和迦顿男爵保管，位于黑石山下的熔火之心中。",al={"逐风者的桎梏在哪里","桑德兰的桎梏位置","加尔和迦顿的桎梏"}},{q="为什么希利苏斯的德米提恩公爵会牵涉其中？",a="德米提恩公爵是居住在希利苏斯的暮光之锤信徒，他掌握着重组破碎护符并将风之王子召唤到艾泽拉斯所需的奥术和元素知识。",al={"德米提恩是谁","德米提恩公爵 桑德兰","如何召唤桑德兰"}},{q="当桑德兰在希利苏斯被召唤时会发生什么？",a="德米提恩可以使用恢复的桎梏进行一场危险的仪式。仪式完成后，你会看到会出现什么。",al={"桑德兰战斗","召唤后发生什么"}},{q="哪把武器与桑德兰有关？",a="雷霆之怒，逐风者的祝福之剑是与风之王子有关的传奇之剑。它的命运将随着德米提恩的仪式而揭晓。",al={"雷霆之怒","逐风者之剑","桑德兰之剑"}}},fp="10,386,23.429.0,22.398.0,19.488.1,18.188.0,39.286.0,41.136.0,47.216.0,53.127.1,34.145.1"}
P.entries["npc:thyn-tel-bladeweaver"] = {n="塞恩提尔·刃纹",s="塞恩提尔·刃纹是一位驻扎在达纳苏斯战士区的暗夜精灵哨兵。她对维琳德·星歌女祭司的失踪深感不安，并派遣受信任的联盟冒险者去寻找有关她下落的线索。通过调查，她试图拼凑出艾露恩之镰背后那未解之谜的真相。",h="塞恩提尔·刃纹是一位驻扎在达纳苏斯战士区的暗夜精灵哨兵。她对维琳德·星歌女祭司的失踪深感不安，并派遣受信任的联盟冒险者去寻找有关她下落的线索。通过调查，她试图拼凑出艾露恩之镰背后那未解之谜的真相。",kw={"刃纹","达纳苏斯","艾露恩之镰","哨兵","星歌","塞恩提尔","维琳德","战士区"},ang={["class:Warrior"]="塞恩提尔位于战士区的训练师中间，对于经过达纳苏斯的联盟战士来说，她是一位熟悉的哨兵面孔。",["faction:Alliance"]="访问战士区的联盟英雄受到塞恩提尔的委托，深入中立和争议领土去揭露真相。",["race:NightElf"]="对于暗夜精灵来说，塞恩提尔的任务触及了他们的切身利益，揭示了一位受人尊敬的女祭司因无法控制的力量而沦为受害者的悲剧。"},sec={{t="哨兵的询问",b="塞恩提尔·刃纹在战士区守护着达纳苏斯，代表着卡多雷警惕的军事力量。当维琳德·星歌女祭司毫无预兆地神秘失踪时，塞恩提尔拒绝让线索中断。她感觉到有严重的势力介入其中，于是主动委托冒险者调查女祭司的私人物品，以揭开她旅程的终点。"},{t="追寻维琳德的足迹",b="塞恩提尔指引调查员检查维琳德留在首都的遗物。发现的线索揭示了一本记录了维琳德与艾露恩交流，以及通过艾露恩之镰召唤恐怖狼人野兽的日志。在塞恩提尔的引导下，旅行者们一路向南，穿过棘齿城港口到达贫瘠之地，试图找到这位绝望的女祭司在彻底消失前所航向的地方。"}},faq={{q="谁是塞恩提尔·刃纹？",a="塞恩提尔·刃纹是一位位于达纳苏斯战士区的暗夜精灵哨兵。她是一位任务发放者，负责启动对维琳德·星歌女祭司失踪事件的调查。",al={"塞恩提尔·刃纹","谁是塞恩提尔","塞恩提尔信息"}},{q="我可以在哪里找到塞恩提尔·刃纹？",a="她站在达纳苏斯，具体驻扎在卡多雷战士和哨兵云集的战士区。",al={"塞恩提尔位置","塞恩提尔·刃纹在哪里","塞恩提尔地图"}},{q="塞恩提尔·刃纹提供什么任务？",a="她是调查维琳德·星歌任务链的主要联系人，提供诸如“维琳德的遗物”、“贫瘠之地港口”等任务，并以“回答问题”作为终结。",al={"塞恩提尔任务","她给予什么任务"}},{q="她为什么对维琳德·星歌感兴趣？",a="维琳德·星歌是一位曾在灰谷服役的女祭司，直到她突然失踪，留下了未完成的工作。塞恩提尔试图查明她的命运，并揭开她离开背后那黑暗的谜团。",al={"为什么要调查维琳德","维琳德发生了什么"}},{q="她的任务链通向哪里？",a="在检查了达纳苏斯的维琳德遗物后，塞恩提尔指引调查员穿过海洋向南前往贫瘠之地的棘齿城，以追踪维琳德航行的航运记录。",al={"维琳德任务路径","任务去往哪里"}},{q="塞恩提尔·刃纹是仅限联盟的联系人吗？",a="是的。塞恩提尔·刃纹驻扎在暗夜精灵首都达纳苏斯，仅向联盟成员提供任务。",al={"部落可以和塞恩提尔交谈吗","她是联盟的吗"}}},fx={["187a5321"]={q="塞恩提尔·刃纹想要什么？",a="塞恩提尔想查明暗夜精灵哨兵维琳德·星歌失踪背后的真相。她委托可靠的冒险者追查维琳德最后的行踪，找回她的私人物品，并沿着她留下的神秘线索，在贫瘠之地及更远的地方继续调查。",al={"塞恩提尔想要什么","塞恩提尔的目标"}},["7964d285"]={q="塞恩提尔·刃纹为什么在这里？",a="塞恩提尔仍驻守于此，负责协调调查并满足暗夜精灵部队的需求。她身处前线，担任联络人，处理远在精灵疆域之外的调查，并指派值得信赖的斥候前往遥远之地，破解威胁族人的未解谜团。",al={"塞恩提尔为什么在这里","塞恩提尔·刃纹的目的"}},["48b9097d"]={q="塞恩提尔·刃纹与谁有关？",a="塞恩提尔与失踪的哨兵维琳德·星歌关系密切，并积极调查她的下落。她的任务直接关系到维琳德远征队的命运；她派遣信使遍及卡利姆多，查明哨兵的遭遇以及她携带的强大圣物的下落。",al={"塞恩提尔·刃纹的关系","塞恩提尔与维琳德·星歌"}},["294bf631"]={q="塞恩提尔·刃纹效忠哪一方？",a="塞恩提尔·刃纹坚定地支持达纳苏斯的暗夜精灵以及更广泛的联盟。她驻扎在族人之中，致力于守卫卡利姆多的哨卫据点，并帮助那些效忠联盟、寻求失踪同伴下落的人。",al={"塞恩提尔·刃纹所属阵营","塞恩提尔属于联盟吗"}}},fp="20,360,20.435.0,23.436.1,28.202.0,38.130.0,44.186.0,42.209.0,32.177.0,49.132.0"}
P.entries["npc:tirion-fordring"] = {n="提里奥·弗丁",s="提里奥·弗丁是一位传奇圣骑士，曾是玛登霍尔德城堡的领主，现在正隐居在东瘟疫之地。作为白银之手骑士团的圣骑士，他因为向一名敌对兽人履行了荣誉誓言而被剥夺了爵位和领地。在索多里尔河畔简朴的小屋里，他注视着洛丹伦发生的悲剧，并为他的儿子感到担忧。",h="提里奥·弗丁是一位传奇圣骑士，曾是玛登霍尔德城堡的领主，现在正隐居在东瘟疫之地。作为白银之手骑士团的圣骑士，他因为向一名敌对兽人履行了荣誉誓言而被剥夺了爵位和领地。在索多里尔河畔简朴的小屋里，他注视着洛丹伦发生的悲剧，并...",kw={"阿隆苏斯·法奥","伊崔格","流放","弗丁","壁炉谷","玛登霍尔德","白银之手","泰兰","索多里尔","提里奥"},ang={["class:Paladin"]="站在提里奥面前，就如同站在你们骑士团活生生的黎明之前；他是第二次战争时期的白银之手骑士，也是一位证明了真正的正义可以超越凡人律法的圣光大师。",["faction:Alliance"]="提里奥体现了联盟创立时的理想，尽管正是这些王国因为他将个人荣誉置于种族仇恨之上而给他打上了叛徒的烙印。",["race:Human"]="提里奥曾是洛丹伦联盟无与伦比的英雄，曾公正地治理壁炉谷，他是那个已经陷入腐朽与疯狂的高贵王国留下的令人心痛的提醒。",["race:Orc"]="尽管曾是联盟的战士并在第二次战争中杀敌无数，但为了信守向兽人伊崔格许下的荣誉誓言，提里奥放弃了一切——他的土地、家庭和姓名。"},sec={{t="一名白银之手骑士",b="在洛丹伦陷落之前，提里奥·弗丁曾是王国最出色的骑士之一。作为第二次战争期间由阿隆苏斯·法奥大主教创立的白银之手骑士团的一员，提里奥曾用他的铠甲、战锤和对圣光的虔诚对抗旧部落。他被尊为圣光坚不可摧的典范。"},{t="荣誉与流放",b="第二次战争后，提里奥与妻子卡兰德拉和幼子泰兰一起，在玛登霍尔德城堡治理壁炉谷地区。他的统治在遇见一位隐居的老兽人战士伊崔格时画上了句号。因为认可了这位老兵深刻的荣誉感，提里奥承诺保护他。当联盟当局发现伊崔格时，提里奥为了信守誓言，向自己的同胞举起了武器。因为这种背叛洛丹伦联盟的行为，提里奥被剥夺了贵族身份，被白银之手除名，并被流放；乌瑟尔免除了他妻子和儿子的连带处罚。"},{t="父亲的折磨",b="由于未被一同流放，他的家人留在了壁炉谷。在第三次战争期间洛丹伦被天灾军团攻陷后，提里奥的儿子泰兰长大成人并加入了血色十字军，最终成为了壁炉谷的大领主。提里奥在远处注视着十字军陷入疯狂，他深感绝望，因为他的儿子已经成了盲目狂热的傀儡。这位索多里尔的隐士依恋着过去美好时光的记忆——比如全家去凯尔达隆游玩——并试图寻找方法提醒他的儿子什么是真正的荣誉。"}},faq={{q="提里奥·弗丁是谁？",a="提里奥·弗丁是一位白银之手骑士团的圣骑士，也是壁炉谷的前任领主。他因为出于荣誉感保护了一名兽人而被同僚流放，现在正隐居在东瘟疫之地西缘的一间僻静小屋里。",al={"提里奥背景故事","老圣骑士是谁","提里奥是谁","隐士圣骑士"}},{q="提里奥为何被洛丹伦流放？",a="提里奥发现了一位名叫伊崔格的老兽人老兵，并了解到他们有着相同的、根深蒂固的战士荣誉感。当联盟部队俘虏伊崔格时，提里奥为了信守保护这位隐士的诺言，袭击了自己的战友。他被视为叛徒，剥夺了爵位并被逐出王国。",al={"提里奥为何被流放","提里奥叛国","为什么提里奥是流亡者"}},{q="提里奥与壁炉谷有何渊源？",a="壁炉谷曾是提里奥的领地。在被流放之前，他一直驻守在玛登霍尔德城堡管理该地区。如今，壁炉谷被血色十字军占据，由他的儿子，大领主泰兰·弗丁指挥。",al={"提里奥壁炉谷","玛登霍尔德城堡提里奥","壁炉谷领主"}},{q="提里奥是否还拥有圣骑士的力量？",a="虽然教会和白银之手正式剥夺了他的军阶，并声称撤销了他与圣光的联系，但提里奥纯粹的信念确保了他与圣光的联系并未断绝。圣光依然像过去一样强烈地响应着他的意志。",al={"提里奥失去了圣光吗","提里奥还是圣骑士吗","提里奥使用圣光吗"}},{q="提里奥对血色十字军有何意图？",a="提里奥并不喜欢血色十字军那种狂热的作风，但他的儿子泰兰是他们在壁炉谷最高指挥官之一。提里奥希望在泰兰的灵魂彻底迷失之前，唤醒他的良知，使他摆脱十字军腐化的控制。",al={"提里奥血色十字军","提里奥与泰兰","为什么提里奥关心十字军"}},{q="其他最初的圣骑士是谁？",a="阿隆苏斯·法奥大主教在第二次战争期间创立了白银之手骑士团，光明使者乌瑟尔是其第一位圣骑士。提里奥的圣骑士兄弟还包括图拉扬和他亲密的朋友赛丹·达索汉。",al={"最初的圣骑士","原始白银之手圣骑士","阿隆苏斯·法奥圣骑士"}}},fp="15,389,27.334.0,27.595.0,18.522.1,23.260.0,37.308.0,42.199.0,42.256.0,47.259.0,36.225.0"}
P.entries["npc:tiza-battleforge"] = {n="蒂萨·热炉",s="蒂萨·热炉是一位资深的矮人圣骑士，隶属于白银之手骑士团，驻扎在铁炉堡的Hall of Mysteries。她以坚定的信仰和洞察力而闻名，引导年轻的矮人圣骑士走上美德、慈善和自我牺牲的道路。通过对神圣典籍的研究和实地考验，她来测试学员是否真正准备好掌握圣光所赐予的复活能力。",h="蒂萨·热炉是一位资深的矮人圣骑士，隶属于白银之手骑士团，驻扎在铁炉堡的Hall of...",kw={"矮人","hall of mysteries","铁炉堡","缪雷登·热炉","mystic ward","圣骑士","救赎","白银之手","蒂萨·热炉","神圣法典"},ang={["class:Paladin"]="对于矮人圣骑士来说，蒂萨·热炉是一位关键的导师，她通过《神圣法典》测试你的资格，并赋予你复活倒下盟友的力量。",["faction:Alliance"]="通过与从暴风城到卡拉诺斯的导师们密切合作，蒂萨确保了白银之手在整个联盟领地维持统一的美德和战斗准备标准。",["race:Dwarf"]="蒂萨代表了圣光在矮人文化和白银之手中的深度融合，引导卡兹莫丹的保卫者们对抗黑铁氏族等威胁。"},sec={{t="Mystic Ward导师",b="在铁炉堡Hall of Mysteries宁静的殿堂中，蒂萨·热炉作为白银之手骑士团中最受尊敬的矮人圣骑士之一而立身于此。联盟各地的学员——在铁炉堡的布兰度尔·铁锤、丹莫罗的阿扎尔·战锤以及暴风城的格雷森·沙东布瑞克公爵等导师的指导下——都被引荐给她以提升他们的精神修行。蒂萨认为，圣光需要的不仅仅是武艺，还需要谦卑的服务、怜悯，以及面对天灾军团和其他威胁时坚定不移的刚毅。"},{t="神圣的试炼",b="当年轻的圣骑士前来寻求更深奥的奥秘时，蒂萨会交给他们一本《神圣法典》。研读过这本法典后，她会派遣他们去执行具体的无私慈善行为，首先从帮助像John Turner这样有卑微需求的人开始。然后，她会挑战学员们投入他们的信仰和英勇，去协助她的丈夫缪雷登·热炉对抗地区性的黑铁矮人威胁。那些征服了这些考验并用生命符记复活倒下盟友的人，才被蒂萨视为有资格掌握神圣的复活艺术。"}},faq={{q="蒂萨·热炉是谁？",a="蒂萨·热炉是一位受人尊敬的矮人圣骑士，属于白银之手骑士团。她位于铁炉堡的Hall of Mysteries内，负责测试和指导那些寻求加深与圣光纽带的矮人圣骑士。",al={"蒂萨是谁","蒂萨·热炉背景故事","圣骑士训练师蒂萨"}},{q="我在哪里可以找到蒂萨·热炉？",a="她位于Hall of Mysteries，这是铁炉堡Mystic Ward内精神和奥术学习的中心。",al={"蒂萨位置","蒂萨·热炉在哪里","hall of mysteries圣骑士训练师"}},{q="她给圣骑士的《神圣法典》是什么？",a="《神圣法典》是一本神圣的指导书籍，包含了圣光的核心美德和教义。蒂萨将其交给圣骑士，让他们在开始慈善、勇气和怜悯的实际试炼之前学习其中的课程。",al={"蒂萨神圣法典","蒂萨书籍任务","什么是神圣法典"}},{q="为什么蒂萨派圣骑士去帮助她的丈夫缪雷登？",a="她的丈夫缪雷登·热炉在试图帮助他的同伴Narm Faulk时面临黑铁矮人的敌对威胁。蒂萨利用这次危机来测试学员的战斗勇气，以及他们准备好使用生命符记将倒下的战友从死亡边缘拉回来的能力。",al={"蒂萨丈夫任务","缪雷登·热炉关联","为什么帮助缪雷登"}},{q="蒂萨向合格的圣骑士教授什么技能？",a="在完成她的慈善试炼并救出缪雷登倒下的战友后，蒂萨会授予学员救赎的力量，这是圣骑士神圣的复活仪式。",al={"蒂萨圣骑士法术","蒂萨教授什么法术","铁炉堡复活圣骑士训练师"}},{q="她和布兰度尔·铁锤有什么关系？",a="布兰度尔·铁锤是一位与她一起驻扎在铁炉堡Hall of Mysteries的矮人圣骑士训练师。蒂萨曾坦率地向布兰度尔指出，他的嫉妒是一种精神弱点，这促使他向她发誓，他会努力克服这一弱点。",al={"蒂萨和布兰度尔","布兰度尔·铁锤蒂萨","布兰度尔嫉妒"}}},fx={["28fe0e8a"]={q="蒂萨·热炉站在哪一方？",a="蒂萨坚定地支持联盟、铁炉堡王国以及银色之手骑士团。作为一名虔诚的圣骑士，她最终效忠于圣光，致力于保卫艾泽拉斯，抵御天灾军团和背信弃义的黑铁矮人等邪恶势力。",al={"蒂萨·热炉的阵营","蒂萨效忠于谁","蒂萨·热炉与联盟"}},["5d20b420"]={q="蒂萨·热炉想要什么？",a="蒂萨希望在新晋圣骑士身上培养真正的美德、仁慈和坚定的信仰。除了通过神圣试炼考验他们的武艺与虔诚，她还收集当地威胁的情报，例如黑铁矮人的侵扰，以便警告城市议会，确保铁炉堡的安全。",al={"蒂萨·热炉的目标","蒂萨想要什么","蒂萨的动机"}},["075b45b0"]={q="蒂萨·热炉为什么在秘法大厅？",a="她居住在铁炉堡秘法区内的秘法大厅，指导有志成为圣骑士的矮人。她身处城市神圣教团的核心，指导由联盟指挥官派来的新兵，考验他们的无私精神和对银色之手的忠诚，再引领他们探究圣光更深奥的奥秘。",al={"蒂萨为什么在铁炉堡","蒂萨·热炉在此的原因","蒂萨为什么在这里"}},["90c1fa9e"]={q="为什么蒂萨·热炉在矮人中备受尊敬？",a="蒂萨被誉为铁炉堡最受尊敬的圣骑士之一。联盟各地的资深老兵，从暴风城的格雷森·沙东布瑞克公爵到本地的圣骑士训练师，都十分敬重她的智慧，并完全信任她判断新兵品格的能力。",al={"蒂萨·热炉的声望","蒂萨·热炉有名吗","蒂萨备受尊敬"}}},fp="16,411,25.594.0,22.569.1,24.240.0,34.126.0,51.237.0,57.292.0,45.170.0,45.265.0"}
P.entries["npc:tommy-joe-stonefield"] = {n="托米·乔·斯通菲尔德",s="托米·乔·斯通菲尔德是一位生活在艾尔文森林中心的年轻农夫，身陷于一场痛苦的家族世仇之中。他深深爱着梅贝尔·马科伦，不得不依靠安静的河岸和秘密传信来向他们争斗的亲人隐瞒这段恋情。",h="托米·乔·斯通菲尔德是一位生活在艾尔文森林中心的年轻农夫，身陷于一场痛苦的家族世仇之中。他深深爱着梅贝尔·马科伦，不得不依靠安静的河岸和秘密传信来向他们争斗的亲人隐瞒这段恋情。",kw={"艾尔文森林","米莱德·斯通菲尔德","梅贝尔·马科伦","斯通菲尔德农场","托米·乔·斯通菲尔德","年轻恋人"},ang={["faction:Alliance"]="对于探索艾尔文森林南部的联盟冒险者来说，托米·乔的秘密恋情是一个朴实的提醒，让人想起在区域内的强盗活动和政治动荡阴影下，依然有人在过着平静的个人生活。"},sec={{t="苦命的世仇",b="托米·乔·斯通菲尔德站在斯通菲尔德农场以西的河岸边，每天望着水对岸的马科伦农场。斯通菲尔德家族和马科伦家族多年来积怨已深，双方因为土地、尊严和琐碎的农活争吵不休。尽管长辈们宣扬着敌意，托米·乔还是深深地爱上了梅贝尔·马科伦。由于无法在不激怒双方家庭的情况下公开见面，他只能依靠值得信赖的中间人和他富有同情心的祖母米莱德·斯通菲尔德来交换秘密便条和定情信物。"}},faq={{q="托米·乔·斯通菲尔德是谁？",a="他是一位居住在艾尔文森林斯通菲尔德农场的人类青年。他暗恋着马科伦家族的女儿梅贝尔·马科伦，而该家族是他家不共戴天的死对头。",al={"托米·乔","托米·乔是谁","斯通菲尔德之子"}},{q="我在哪里可以找到托米·乔·斯通菲尔德？",a="托米·乔站在斯通菲尔德农场西侧的河岸边，注视着水对岸梅贝尔居住的马科伦农场。",al={"托米·乔的位置","托米·乔在哪里","寻找托米·乔"}},{q="斯通菲尔德家族和马科伦家族为什么要争斗？",a="没人知道争斗是怎么开始的。这两个农户家庭一直维持着长期且痛苦的世仇，双方都不希望自家的年轻人与对方来往。",al={"家族世仇","他们为什么互相憎恨","斯通菲尔德与马科伦的世仇"}},{q="谁在帮助托米·乔和梅贝尔见面？",a="米莱德·斯通菲尔德知道他们的恋情，并通过外来的旅行者在托米·乔和梅贝尔之间传递秘密信息，以此帮助他们进行秘密交往。",al={"米莱德·斯通菲尔德的帮助","秘密恋人的帮助","谁在帮助这对恋人"}}},fx={["3c95bb6e"]={q="托米·乔·斯通菲尔德站在哪一方？",a="他属于斯通菲尔德家族，但他的心并未卷入家族间的激烈争斗。虽然他住在斯通菲尔德农场，但他在亲族与自己对梅贝尔·马科伦的爱意之间左右为难；梅贝尔属于他们不共戴天的对头家族。",al={"托米·乔的效忠对象","托米·乔属于哪个家族","斯通菲尔德还是马科伦"}},["8a9aad66"]={q="托米·乔·斯通菲尔德想要什么？",a="托米·乔最渴望的就是和梅贝尔·马科伦在一起。斯通菲尔德家族与马科伦家族积怨已久，使他们无法相守；因此，他渴望找到办法与她秘密会面，让这段爱情在家族纷争中延续下去。",al={"托米·乔想要什么","托米·乔的目标","托米·乔的愿望"}},["96565570"]={q="托米·乔·斯通菲尔德为什么在这里？",a="托米·乔静静地等在自家农庄附近的河岸边。这里远离旁人的视线，是一处僻静之地，他可以暂时躲开家务，盼望有机会避开交恶的亲族，与梅贝尔幽会。",al={"托米·乔为什么在河边","托米·乔在这里做什么","托米·乔·斯通菲尔德为何在此"}},b663afb0={q="托米·乔·斯通菲尔德与谁有关？",a="他是斯通菲尔德家族的一员，祖母米莱德·斯通菲尔德也一直在积极帮助他。不过，他最重要的关系是与梅贝尔·马科伦的爱情。梅贝尔是他家族宿敌的女儿，而他深爱着她。",al={"托米·乔的关系","托米·乔的家族","托米·乔与谁有亲属关系"}}},fp="20,246,19.588.0,28.156.0,38.139.0,46.160.0,37.172.0"}
P.entries["npc:tonga-runetotem"] = {n="图加·符文图腾",s="图加·符文图腾是一位知识渊博的牛头人德鲁伊，驻扎在贫瘠之地十字路口的旅店外。他受雷霆崖的派遣，正在调查渗入该地区稀疏绿洲并导致当地野生动物生病的非自然腐蚀。他的研究旨在追溯这种精神扰动的源头，以免脆弱的生态系统彻底崩溃。",h="图加·符文图腾是一位知识渊博的牛头人德鲁伊，驻扎在贫瘠之地十字路口的旅店外。他受雷霆崖的派遣，正在调查渗入该地区稀疏绿洲并导致当地野生动物生病的非自然腐蚀。他的研究旨在追溯这种精神扰动的源头，以免脆弱的生态系统彻底崩溃。",kw={"贫瘠之地","十字路口","德鲁伊","遗忘之池","绿洲","符文图腾","死水绿洲","图加","哀嚎洞穴"},ang={["class:Druid"]="对于学习技艺的牛头人德鲁伊来说，图加代表了塞纳里奥教义的实践应用，展示了如何在远离月光林地的地方诊断并净化遭受破坏的生态系统。",["faction:Horde"]="部落依赖图加的生态调查，以确保他们穿过贫瘠之地的主要通道保持适宜居住，并免受地底魔法威胁的影响。",["race:Tauren"]="图加展现了牛头人对大地母亲的奉献精神，勤恳地工作以保护那些维持干旱平原上生命的脆弱水源。"},sec={{t="十字路口的守望者",b="在十字路口的尘土与喧嚣交易中，图加·符文图腾保持着静默的守望。他被雷霆崖的长者们从莫高雷的高原上派下来，对这片干旱的草原有着深刻的了解。当别人只看到贫瘠的灌木和掠食野兽时，他却能读懂这片土地健康的微妙动向。近来，这些动向发生了剧烈的恶化，迫使他招募有能力的旅者来调查这片草原生命的中心：那些与世隔绝的绿洲。"},{t="受污染的水源与畸变的野兽",b="The Barrens depends entirely on its scattered water sources, but the waters of the Forgotten Pools and the Stagnant Oasis have turned volatile. Strange bubbles of magical vapor rise to the surface, and the creatures drinking from them have begun mutating into aberrant, aggressive forms. Tonga works tirelessly to collect plant and creature samples, seeking to understand whether this malady is natural rot or the work of an intrusive power. His findings increasingly point toward deep subterranean fissures, connecting the poisoned pools directly to the subterranean labyrinths of the Wailing Caverns."},{t="符文图腾血脉",b="身为符文图腾氏族的一员，图加肩负着大德鲁伊哈缪尔·符文图腾所倡导的沉重的德鲁伊传承。虽然大德鲁伊哈缪尔负责维持与塞纳里奥议会的关系，并于月光林地的圣林中进行研习，但像图加这样的侦察兵则是前线的耳目与双手。图加利用月光林地的传统草药智慧来配制治疗药膏和解毒剂，确保年轻的牛头人德鲁伊传统向初创的部落证明其至关重要的价值。"}},faq={{q="图加·符文图腾是谁？",a="图加是一位驻扎在贫瘠之地十字路口旅店附近的牛头人德鲁伊。他受雷霆崖长者的派遣，作为调查员研究蔓延在草原上的奇异自然腐蚀。",al={"图加·符文图腾","图加是谁","十字路口德鲁伊"}},{q="图加在贫瘠之地调查什么？",a="他正在调查贫瘠之地绿洲内出现的奇异蒸汽、变异野兽和受污染水源的非自然现象，包括遗忘之池和死水绿洲。",al={"图加在做什么","图加的任务目标","为什么调查绿洲"}},{q="图加认为腐蚀来自哪里？",a="通过研究变异生物和水源裂隙，图加推断出感染绿洲的魔法污染源于地下的哀嚎洞穴深处。",al={"绿洲腐蚀的源头","污染来自哪里","哀嚎洞穴的联系"}},{q="图加与哈缪尔·符文图腾有亲属关系吗？",a="他们都姓符文图腾，且图加会将贫瘠之地的麻烦传达给雷霆崖长者高地上的大德鲁伊哈缪尔·符文图腾，但没有任何文献记载他们是否具有亲属关系。",al={"他和哈缪尔有关系吗","符文图腾家族","与哈缪尔的关系"}},{q="图加如何帮助中毒的野生动物？",a="图加结合月光林地的教导与当地的试剂，配制治疗药膏来医治中毒的瞪羚，并抵消从鬼雾峰等源头流出的毒素。",al={"瞪羚治疗","图加治疗病患","鬼雾峰毒素"}},{q="为什么图加驻扎在十字路口，而不是陶拉祖营地或雷霆崖？",a="十字路口是北贫瘠之地的中心枢纽，使图加能靠近受影响的绿洲，同时也方便接触到能替他深入危险地区的冒险者。",al={"为什么在十字路口","图加为什么在这里"}}},fx={["5ac3f48e"]={q="图加·符文图腾站在哪一方？",a="图加坚定地支持部落和雷霆崖的牛头人同胞。他奉族中领袖之命前来，致力于治愈这片土地，并保护途经十字路口的旅人；他还与来自月光林地的德鲁伊盟友密切合作，守护卡利姆多的自然平衡。",al={"图加·符文图腾的阵营","图加效忠于谁","图加·符文图腾是部落成员吗"}},["8af7bcfa"]={q="图加·符文图腾想要什么？",a="图加希望查明并清除正在污染贫瘠之地水源的异常毒素。他招募能干的冒险者检查当地绿洲，采集变异动植物的样本，并为中毒的野生动物施用药剂，力求在腐化彻底摧毁周边地区之前将其遏止。",al={"图加想要什么","图加·符文图腾的目标","图加·符文图腾的目的"}}},fp="15,374,25.507.0,32.602.1,21.498.0,23.213.0,43.177.0,55.167.1,37.199.0,45.178.0,82.214.0"}
P.entries["npc:tormus-deepforge"] = {n="托姆斯·深炉",s="托姆斯·深炉是铁炉堡大熔炉中心的一位矮人铁匠。作为一名可靠的工匠，他负责协调铁矿石的运输，并为卡兹莫丹及其他地区的联盟防御力量提供军备。",h="托姆斯·深炉是铁炉堡大熔炉中心的一位矮人铁匠。作为一名可靠的工匠，他负责协调铁矿石的运输，并为卡兹莫丹及其他地区的联盟防御力量提供军备。",kw={"锻造","深炉","矮人","great forge","铁炉堡","洛辛维尔","托姆斯"},ang={["profession:Blacksmithing"]="对于在大熔炉从事交易的铁匠来说，托姆斯代表了原材料库存和前线军事装备之间的重要纽带。",["race:Dwarf"]="作为山脉王国的一位自豪的工匠，托姆斯展示了每当大联盟的盟友呼唤援助时，铁炉堡都随时准备冶炼并交付武器。"},sec={{t="大熔炉大师",b="托姆斯·深炉驻守在大熔炉的熊熊烈火旁，代表铜须氏族监督着重大的金属加工任务。除了亲自锻造钢铁，托姆斯还悼念着他的导师斯特吉·铁环。斯特吉在丹莫罗东部盔枕湖以南的铁环营地在运抵一批奇怪的暗影矿石后，被黑铁矮人占领了。"}},faq={{q="我能在哪里找到托姆斯·深炉？",a="托姆斯站在环绕铁炉堡中心枢纽——大熔炉熔岩池的环形步道上。",al={"托姆斯位置","托姆斯在哪里","托姆斯·深炉地图"}},{q="托姆斯在联盟的战争行动中扮演什么角色？",a="托姆斯为被派往大熔炉的年轻战士们锻造武器。作为回报，他请求他们为他的导师斯特吉·铁环报仇，前往丹莫罗的铁环营地，夺回黑铁矮人为了抢夺它而大开杀戒的暗影矿石，随后他会将这些矿石加工成新的灰铁武器。",al={"托姆斯的作用","托姆斯的目的","为什么要找托姆斯"}},{q="还有其他的深炉氏族成员吗？",a="有几位矮人共享深炉这个姓氏，包括本古斯、穆戈特和凯塔·深炉，以及托姆斯在洛克莫丹的同事索瓦尔德，但他们是否有关联从未得到证实。",al={"深炉氏族","深炉家族","托姆斯和穆戈特有关系吗"}}},fx={["7c43f5fd"]={q="托姆斯·深炉是谁？",a="托姆斯·深炉是一位矮人大师级铁匠，在铁炉堡的Great Forge工作。他以锻造铁器和钢铁的技艺闻名，在打造装备、管理运往东部王国各地的军备运输方面发挥着关键作用，以支援盟军。",al={"托姆斯是谁","托姆斯·深炉的背景","深炉是谁"}},["43326af9"]={q="托姆斯·深炉站在哪一方？",a="托姆斯对国王麦格尼·铜须和联盟忠心耿耿。他驻守在矮人首都的核心地带，专心打造武器，确保联盟士兵和远方据点获得对抗敌人所需的武器与补给。",al={"托姆斯·深炉的阵营","托姆斯效忠于谁","托姆斯是联盟成员吗"}},["6189f272"]={q="托姆斯·深炉想要什么？",a="托姆斯想锻造精良的武器，也想为自己的导师斯图吉·铁环报仇。丹莫罗的铁环营地收到一批奇异的暗影矿石后，黑铁矮人屠杀了那里的所有人。托姆斯请求冒险者反击，并带回那些矿石，让他研究其性质。",al={"托姆斯想要什么","托姆斯的目标","托姆斯·深炉的任务"}},["14a6c7e2"]={q="托姆斯·深炉为什么在铁炉堡？",a="他在Great Forge施展自己的技艺。这里是卡兹莫丹的工业中心，他与铁炉堡最出色的铠甲匠和武器匠并肩工作，掌管锻造王国军备所需的巨大炉火和铁砧。",al={"托姆斯为什么在铁炉堡","托姆斯为什么在这里","托姆斯在great forge"}}},fp="16,227,25.382.0,34.112.0,54.292.0,29.197.0"}
P.entries["npc:torwa-pathfinder"] = {n="托尔瓦·寻路者",s="托尔瓦·寻路者是一位牛头人猎人和追踪者，独自一人在安戈洛环形山入口处扎营，就在从塔纳利斯向下延伸的坡道下方。他观察着盆地中的原始野生动物，研究着统治丛林地面的危险掠食者。想要在环形山的传奇野兽面前证明自己的冒险者们经常会寻求他的指引。",h="托尔瓦·寻路者是一位牛头人猎人和追踪者，独自一人在安戈洛环形山入口处扎营，就在从塔纳利斯向下延伸的坡道下方。他观察着盆地中的原始野生动物，研究着统治丛林地面的危险掠食者。想要在环形山的传奇野兽面前证明自己的冒险者们经常会...",kw={"血瓣花","拉尔科维","寻路者","迅猛龙","塔纳利斯","托尔瓦","乌卡","安戈洛"},ang={["class:Hunter"]="托尔瓦体现了一位追踪大师的耐心和技艺，他证明了引诱顶级掠食者需要了解其饮食、气味和领地习惯，而不是依靠蛮力。",["race:Tauren"]="对于四处游历的牛头人来说，在环形山边缘找到托尔瓦是一种令人安心的提醒，让他们想起族人对自然的敬畏，即使是在安戈洛史前的混乱之中。"},sec={{t="门槛上的守望者",b="托尔瓦·寻路者驻扎在环形山东部的底部，那里塔纳利斯的沙漠沙砾被潮湿的丛林水汽所取代，他充当了新来者的非正式守卫。他尊重安戈洛的原始力量，明白粗心的漫游者很快就会成为当地动物的口粮。在旅行者深入闷热的腹地之前，他的营地提供了一处难得的休憩之所。"},{t="猎杀拉尔科维",b="托尔瓦的大部分注意力都放在了拉尔科维身上，这是一种极其狡猾且凶猛的迅猛龙，游荡在环形山的北部区域。托尔瓦明白，仅凭蛮力是无法击倒这种顶级掠食者的。相反，他指导猎人们研究它的进食习惯，利用新鲜的尸体肉块和腺体制作出足够强力的诱饵，将其引诱到空旷地带。"},{t="原始毒素与野兽",b="除了猎杀环形山的顶级迅猛龙之外，托尔瓦对栖息在盆地中的有毒植物群和好斗的猿猴族群也保持着浓厚的兴趣。他指引旅行者从不稳定的血瓣花身上采集毒液，并观察像强大的大猩猩乌卡这样的统治级野兽的力量，不断分析大自然最致命的适应性如何在孤立环境中发挥作用。"}},faq={{q="我在哪里可以找到托尔瓦·寻路者？",a="托尔瓦在安戈洛环形山东缘附近扎营，就在通往塔纳利斯沙漠的蜿蜒坡道底部附近。",al={"托尔瓦位置","托尔瓦在哪里","寻找托尔瓦·寻路者"}},{q="什么是拉尔科维？",a="拉尔科维是一只潜伏在安戈洛环形山的传奇且难以捉摸的迅猛龙。它以凶猛和狡猾著称，无法通过常规手段轻易追踪，必须使用特殊的诱饵将其引出。",al={"拉尔科维","拉尔科维是谁","什么是拉尔科维"}},{q="托尔瓦只给部落玩家提供任务吗？",a="不。尽管是牛头人，托尔瓦·寻路者在荒野中是独立行动的。他向联盟和部落的有能之士提供他的追踪智慧和狩猎挑战。",al={"托尔瓦是部落专属吗","联盟可以与托尔瓦交谈吗","托尔瓦阵营"}},{q="为什么托尔瓦对血瓣花感兴趣？",a="托尔瓦对安戈洛本土植物的致命防御手段很着迷。他要求冒险者采集好斗的血瓣花的分泌物，以了解并测试其天然毒素的效力。",al={"血瓣花任务","为什么是血瓣花","托尔瓦毒素"}},{q="乌卡是谁？",a="乌卡是一只居住在安戈洛洞穴和猿猴领地中极其强大的大猩猩。托尔瓦挑战猎人们去击败乌卡，以证明他们在面对盆地中最强野兽时的实力。",al={"强大的乌卡","安戈洛大猩猩首领","乌卡任务"}}},fp="16,349,24.386.0,22.382.0,25.370.0,34.139.0,18.197.0,46.194.0,39.200.0,13.198.0"}
P.entries["npc:treshala-fallowbrook"] = {n="塔莎拉·静水",s="塔莎拉·静水是一名居住在达纳苏斯贸易区上层的暗夜精灵。她是赫尔拉斯·静水的妻子，赫尔拉斯为了工作远离家乡，深入贫瘠之地那荆棘丛生的剃刀沼泽。",h="塔莎拉·静水是一名居住在达纳苏斯贸易区上层的暗夜精灵。她是赫尔拉斯·静水的妻子，赫尔拉斯为了工作远离家乡，深入贫瘠之地那荆棘丛生的剃刀沼泽。",kw={"达纳苏斯","静水","不再永恒","暗夜精灵","剃刀沼泽","贸易区","塔莎拉"},ang={["faction:Alliance"]="塔莎拉在达纳苏斯担任联盟的联络点，接待那些从贫瘠之地深处针对野猪人荆棘巢穴的艰苦探险中归来的勇士。",["race:NightElf"]="对于暗夜精灵来说，塔莎拉为她丈夫进行的静默守望提醒着他们，自海加尔山之战以来，他们的人民不再拥有无尽的等待时间了。"},sec={{t="平台上的守望者",b="塔莎拉·静水在达纳苏斯贸易区的一间工坊二楼默默守望。她的丈夫赫尔拉斯前往了贫瘠之地那荆棘密布的剃刀沼泽，她在家中等待他的消息。他们两人佩戴着一枚连心坠，那是他们婚姻的信物，赫尔拉斯把它带进了野猪人的巢穴。"}},faq={{q="我在哪里可以找到塔莎拉·静水？",a="她位于达纳苏斯贸易区一间工坊的二楼。你可以通过武器店内的木制坡道上到她的房间。",al={"塔莎拉位置","静水在哪里","如何找到塔莎拉"}},{q="塔莎拉在研究什么？",a="她自己并不是研究员。这项工作属于她的丈夫赫尔拉斯·静水，他的旅程将他带进了剃刀沼泽；塔莎拉在达纳苏斯等待着关于他以及他带走的那枚连心坠的消息。",al={"塔莎拉任务","不再永恒传说","塔莎拉想要什么"}},{q="她为什么关注剃刀沼泽？",a="她的丈夫赫尔拉斯冒险进入了位于贫瘠之地的野猪人要塞——剃刀沼泽，从那以后她就再也没有收到过他的消息。",al={"为什么是剃刀沼泽","静水剃刀沼泽","与剃刀沼泽的联系"}},{q="她是店主还是工匠？",a="不，塔莎拉既不是商人也不是工匠。她只是把家安在贸易区繁忙的手工艺摊位上方。",al={"塔莎拉是商人吗","她卖什么"}}},fx={["145b1f19"]={q="塔莎拉·静水是谁？",a="塔莎拉·静水是一名居住在达纳苏斯贸易区的暗夜精灵。她的丈夫赫尔拉斯·静水去了剃刀沼泽，而她正在等待他的消息。",al={"塔莎拉是谁","塔莎拉·静水的背景","塔莎拉的身份"}},["308e08c8"]={q="塔莎拉·静水站在哪一方？",a="塔莎拉效忠于达纳苏斯和联盟。她住在暗夜精灵的首都，而她的丈夫赫尔拉斯此时正在剃刀沼泽。",al={"塔莎拉·静水的阵营","塔莎拉是联盟成员吗","塔莎拉的效忠对象"}},["5c8a152e"]={q="塔莎拉·静水想要什么？",a="塔莎拉牵挂的是她的丈夫赫尔拉斯·静水，以及他带入剃刀沼泽的缔合吊坠。旅人若有他的消息，应当带来告诉她。",al={"塔莎拉想要什么","塔莎拉·静水的任务","塔莎拉为什么想要刺脊野猪人的物品"}}},fp="20,249,24.373.0,38.180.0,29.230.0,41.137.0,37.133.0"}
P.entries["npc:tsunaman"] = {n="苏纳曼",s="苏纳曼是一位有感知的水元素，驻扎在石爪山脉的烈日石居。作为潮汐法庭的代理人，他监视着卡利姆多的元素流动，并召集部落的冒险者去对抗那些腐化的力量。",h="苏纳曼是一位有感知的水元素，驻扎在石爪山脉的烈日石居。作为潮汐法庭的代理人，他监视着卡利姆多的元素流动，并召集部落的冒险者去对抗那些腐化的力量。",kw={"焦炭谷","耐普图隆","石爪山脉","烈日石居","潮汐法庭","深渊中的麻烦","苏纳曼","水元素"},ang={["class:Shaman"]="对于那些致力于理解并与元素沟通的萨满祭司来说，苏纳曼提供了一个直接与猎潮者法庭特使交流的难得机会。",["faction:Horde"]="苏纳曼将烈日石居的部落视为对抗卡利姆多水域中元素失衡和教徒入侵的便利盟友。"},sec={{t="潮汐代理人",b="苏纳曼栖息在从烈日石居通往焦炭谷的小路附近，他服务于潮汐法庭——这是一群追随猎潮者耐普图隆的高阶仆从。他并不会对凡人旅行者表现出盲目的敌意，而是与部落合作，监视整个卡利姆多的Elemental Unrest，特别是那些从黑暗深渊的淹没洞穴中散发出的动荡。"},{t="对火焰的憎恨",b="秉承他身为元素的天性，苏纳曼对各种形式的火焰都怀有本能的、深入骨髓的憎恨。他一直对附近焦炭谷那燃烧的土地和火元素的入侵感到愤怒。在营地里，他的敌意表现得既刻薄又不妥协，他经常会走到附近的烹饪火堆和营火旁，仅仅为了用沉重的水拳将其击灭。"}},faq={{q="谁是苏纳曼？",a="苏纳曼是一位位于石爪山脉烈日石居的水元素。他担任潮汐法庭的特使，监视卡利姆多的元素冲突，并寻求帮助以对抗非自然的动荡。",al={"谁是苏纳曼","苏纳曼背景故事","苏纳曼是什么"}},{q="为什么苏纳曼会攻击篝火？",a="苏纳曼厌恶火元素和火焰本身。出于元素间的敌对关系，他会定期走到旅行者在烈日石居点燃的篝火旁，用水属性的打击将其熄灭。",al={"苏纳曼击打火焰","为什么苏纳曼要攻击火焰","水元素 篝火"}},{q="什么是潮汐法庭？",a="潮汐法庭是一个由强大的元素副官组成的组织，服务于水元素领主——猎潮者耐普图隆。他们监管着水域，并会对世界水域中的破坏行为做出反应。",al={"潮汐法庭","苏纳曼服务于谁"}},{q="为什么苏纳曼会对黑暗深渊感兴趣？",a="黑暗深渊已经被暮光教徒和腐化本土水灵的黑暗力量所污染。苏纳曼会招募部落的冒险者进入沉没的神庙，平息那些扰乱水域的混乱。",al={"苏纳曼 黑暗深渊","深渊中的麻烦"}}},fx={["83418127"]={q="苏纳曼效忠哪一方？",a="苏纳曼不听命于部落或联盟的凡人种族。他侍奉水元素之力，具体而言，是潮汐议会——这群人是潮汐猎手耐普图隆麾下的高级副官。尽管他容许访客出入烈日石居，也会招募冒险者对付共同的敌人，但他真正的忠诚完全属于水下深处和他的元素同胞。",al={"苏纳曼的阵营","苏纳曼侍奉谁","苏纳曼的效忠对象"}},d98f482b={q="苏纳曼想要什么？",a="苏纳曼受古老的元素之争驱使。他寻求消灭敌对的火元素，憎恶一切形式的火焰，甚至经常对普通的营火出手。此外，他还致力于推进潮汐议会的利益，招募有能力的凡人，处理黑暗深渊等水下圣所中的邪恶异动。",al={"苏纳曼的目标","苏纳曼想做什么","苏纳曼的愿望"}},["37c31a70"]={q="苏纳曼为什么在烈日石居？",al={"苏纳曼为何在石爪山脉","苏纳曼在烈日石居的缘由","苏纳曼为何来到这里"}}},fp="8,258,18.412.0,15.377.0,16.232.0,38.218.0,34.210.0,48.221.0"}
P.entries["npc:turak-runetotem"] = {n="图拉克·符文图腾",s="图拉克·符文图腾是一位备受尊敬的牛头人德鲁伊训练师，居住在雷霆崖长者高地的长者大厅中。作为大德鲁伊哈缪尔·符文图腾的得力助手，他引导初出茅庐的牛头人走上自然与平衡的神圣道路。通过图拉克，年轻的德鲁伊们可以进行基础试炼，与灵魂沟通并掌握动物形态。",h="图拉克·符文图腾是一位备受尊敬的牛头人德鲁伊训练师，居住在雷霆崖长者高地的长者大厅中。作为大德鲁伊哈缪尔·符文图腾的得力助手，他引导初出茅庐的牛头人走上自然与平衡的神圣道路。通过图拉克，年轻的德鲁伊们可以进行基础试炼，与...",kw={"水栖形态","熊形态","德迪利特·星焰","德鲁伊","长者高地","长者大厅","哈缪尔","月爪","月光林地","符文图腾","雷霆崖","图拉克"},ang={["class:Druid"]="对于牛头人德鲁伊来说，图拉克·符文图腾是早期训练的基石，他赋予了他们传送至月光林地的能力，并考验着每一位寻求进步的学徒，直到他们获得熊形态和水栖形态。",["faction:Horde"]="图拉克在巩固部落内的自然魔法方面发挥了至关重要的作用，他训练出的守护者有能力对抗枯萎、环境腐化以及卡利姆多大地上残留的创伤。",["race:Tauren"]="作为符文图腾部族的一员，图拉克体现了第三次战争后牛头人德鲁伊习俗的复兴，帮助他的人民恢复与大地之母的古老和谐。"},sec={{t="大地之母的呼唤",b="在长者大厅宁静的氛围中，图拉克·符文图腾是部落最重要的德鲁伊导师之一。他以极大的耐心和平衡的处世态度而闻名，协助大德鲁伊哈缪尔·符文图腾在牛头人族群中复兴古老的德鲁伊技艺。图拉克确保每一位有抱负的德鲁伊都遵从大地之母的意志，教导他们身体的力量必须始终建立在对精神的尊重和与自然的和谐之上。"},{t="利爪之路",b="当年轻的德鲁伊准备好掌握动物形态时，图拉克会指引他们走向更广阔的世界。他会开启他们与塞纳里奥议会的沟通，传授跨越卡利姆多传送至圣地月光林地的技巧。回想起自己年轻时觐见巨熊之灵时的困惑与震撼，图拉克通过派遣学生去面对月爪来考验他们的勇气，并以此获得行走利爪之路所需的身体与心灵的力量。"},{t="平衡的守护者",b="图拉克的指引不仅限于原始的战斗形态，还包括对环境的保护。他将弟子们派往德迪利特·星焰处学习关于毒素的知识，而德迪利特则指引他们去处理十字路口附近频发的动物中毒事件，这种情况连图拉克都感到惊讶。通过这些试炼，以及在潮汐之下唤醒水栖形态的艰苦仪式，图拉克将新人们塑造成能够治愈艾泽拉斯最深重创伤的持久守护者。"}},faq={{q="我可以在哪里找到图拉克·符文图腾？",a="图拉克·符文图腾位于雷霆崖的长者高地，驻守在长者大厅的帐篷里，与大德鲁伊哈缪尔·符文图腾在一起。",al={"图拉克位置","图拉克·符文图腾在哪里","图拉克·符文图腾雷霆崖"}},{q="图拉克对于新德鲁伊扮演什么角色？",a="他是年轻牛头人德鲁伊的主要任务发布者和导师。他教导他们与月光林地沟通，通过神圣的试炼解锁他们的熊形态和水栖形态，并指导他们如何治愈自然毒素。",al={"图拉克教授什么","图拉克德鲁伊训练师","图拉克角色"}},{q="图拉克与月光林地有什么联系？",a="图拉克教授新手德鲁伊直接传送至月光林地圣地的法术，并将他们引荐给塞纳里奥议会的代表德迪利特·星焰，以获得更高深的灵性指引。",al={"图拉克月光林地","图拉克如何认识德迪利特","传送月光林地图拉克"}},{q="图拉克与大德鲁伊哈缪尔·符文图腾是什么关系？",a="他们都属于古老的符文图腾部族。图拉克在大德鲁伊哈缪尔的直接领导下，作为他最信任的助手和长者大厅的导师之一工作。",al={"图拉克和哈缪尔有关系吗","哈缪尔和图拉克"}},{q="为什么图拉克会派遣德鲁伊前往十字路口？",a="图拉克将学生派往月光林地的德迪利特·星焰处学习毒素知识，而德迪利特则派遣他们去帮助处理十字路口周围发生的动物中毒事件。当他们返回时，图拉克会奖励他们永久治愈毒素的能力。",al={"图拉克十字路口","图拉克毒素任务","解除毒素的能力"}},{q="图拉克对于巨熊之灵的个人经历是怎样的？",a="图拉克坦言，当他最初踏上成为利爪德鲁伊的道路时，他与巨熊之灵的沟通既令人困惑又极其深刻，这段经历加深了他对这种形态的敬畏。",al={"图拉克巨熊之灵","图拉克利爪之路"}}},fx={fcca94f0={q="图拉克·符文图腾是谁？",a="图拉克·符文图腾是一位睿智而耐心的牛头人德鲁伊训练师，居住在雷霆崖长者高地的长者大厅。他是大德鲁伊哈缪尔·符文图腾值得信赖的助手，在自然的怀抱中保持着深厚的平衡。图拉克致力于引导年轻的部落德鲁伊完成最初的试炼，帮助他们与荒野之灵建立共鸣，并掌握塞纳里奥议会的古老教义。",al={"图拉克是谁","图拉克·符文图腾的背景","图拉克的身份"}},d36f6346={q="图拉克·符文图腾效忠哪一方？",a="图拉克既忠于部落中的雷霆崖牛头人，也忠于塞纳里奥议会。他代表着牛头人与暗夜精灵之间日益紧密的德鲁伊纽带，在部落的传统忠诚与治愈并守护艾泽拉斯自然平衡的神圣、中立职责之间搭起桥梁。",al={"图拉克的阵营","图拉克侍奉谁","图拉克的忠诚对象"}},b696f0bb={q="图拉克·符文图腾想要什么？",a="图拉克希望培育新一代牛头人德鲁伊，并守护大地免遭腐化。他希望新晋学徒理解自然之力的真正本质，敦促他们与巨熊等灵魂沟通，克服身心的考验，并运用自身天赋净化毒素，让卡利姆多重归和谐。",al={"图拉克的目标","图拉克的职责是什么","图拉克的动机"}},["83600788"]={q="图拉克·符文图腾为什么在这里？",a="图拉克驻守在长者高地的长者大厅，与大德鲁伊哈缪尔·符文图腾并肩效力。哈缪尔负责监督所有牛头人的德鲁伊沟通仪式，图拉克则在高耸的崖地担任他的主要导师，亲自指导初学德鲁伊，再送他们前往月光林地，并承担起在贫瘠之地各处更广泛的职责。",al={"图拉克为何在雷霆崖","图拉克为何在长者高地","图拉克在雷霆崖的职责"}}},fp="15,354,24.449.0,20.481.0,20.464.0,33.144.0,41.225.0,40.201.0,51.164.0,45.251.0,64.222.0"}
P.entries["npc:twilight-lord-kelris"] = {n="梦游者克尔里斯",s="梦游者克尔里斯是一位兽人术士，也是暮光之锤教派内位居高层的领导者，在黑暗深渊深处活动。他坐镇Moonshrine Sanctum，主持崇拜原始九头蛇阿库麦尔的黑暗仪式，企图引发一场宇宙级的混乱统治。",h="梦游者克尔里斯是一位兽人术士，也是暮光之锤教派内位居高层的领导者，在黑暗深渊深处活动。他坐镇Moonshrine Sanctum，主持崇拜原始九头蛇阿库麦尔的黑暗仪式，企图引发一场宇宙级的混乱统治。",kw={"阿库麦尔","银色黎明","黑暗深渊","克尔里斯","moonshrine sanctum","上古之神","梦游者","暮光之锤"},ang={["class:Warlock"]="虽然典型的术士通过与燃烧军团的恶魔交易来获得力量，但克尔里斯所展现的是因屈服于上古之神的低语而产生的黑暗、迷幻般的暗影魔法。",["faction:Alliance"]="以达纳苏斯为基地的银色黎明致力于终结克尔里斯那令人难以捉摸的生涯，他一直在卡利姆多北部煽动邪教和制造恐怖。",["faction:Horde"]="长者和萨满祭司将克尔里斯视为一个引以为戒的畸形怪物——一个抛弃了元素与先祖之灵，而去向古老宇宙恐怖卑躬屈膝的兽人。",["race:NightElf"]="克尔里斯那亵渎性的仪式正在积极地破坏神圣的Moonshrine Sanctum，玷污这座献给艾露恩的古代精灵神庙。"},sec={{t="虚空先驱",b="梦游者克尔里斯指挥着占据了黑暗深渊沉没废墟的暮光之锤教徒。多年来，克尔里斯一直从达纳苏斯的监视中溜走，逃避银色黎明的追捕，并由此获得了一个阴森的名声：每当卡利姆多出现古老的邪恶波动，人们就会怀疑是克尔里斯在背后操纵。这名兽人并没有效忠于任何军阀或氏族，而是将自己完全献给了上古之神，试图毁灭凡人的文明，让艾泽拉斯回归到绝对的、原始的混乱状态。"},{t="巨兽守护者",b="在Moonshrine Sanctum内，克尔里斯负责监管教派对阿库麦尔的崇拜，这头凶残的三头九头蛇是上古之神的仆从。暮光之锤与娜迦结盟，占据了这座淹没的神庙，而克尔里斯主持着教派的仪式，通过向阿库麦尔献祭无辜者来获取力量。"},{t="黑暗迷梦与沉睡",b="克尔里斯掌握着强大的暗影魔法，能够控制心智，使入侵者陷入深沉且非自然的沉睡。他在一座被腐蚀的祭坛前不停祈祷，祭坛周围的蜡烛引导着黑暗能量。那些试图击败克尔里斯的人，不仅要打败这位教派领袖，还必须应对他那仪式性的守夜被打断后所苏醒的潜伏恐怖。"}},faq={{q="梦游者克尔里斯是谁？",a="梦游者克尔里斯是一位兽人术士，统领着暮光之锤在黑暗深渊的势力。他协调着整个沉没神庙中的邪教活动，并且对上古之神有着深沉的奉献。",al={"克尔里斯背景故事","克尔里斯是谁","克尔里斯背景"}},{q="为什么银色黎明要追捕克尔里斯？",a="银色黎明认为克尔里斯是卡利姆多各地邪恶事件背后难以捉摸的煽动者。虽然他曾被认为已经死亡或失踪，但人们发现他在整个大陆的无数阴谋背后都有所作为，这使得消灭他成为了当务之急。",al={"银色黎明与克尔里斯","为什么要击杀克尔里斯","黑暗深渊邪恶缘由"}},{q="克尔里斯在利用九头蛇阿库麦尔做什么？",a="克尔里斯和他的暮光之锤教徒崇拜着阿库麦尔，这是一头三头九头蛇，也是上古之神的仆从，它栖息在沉没神庙的最深处。",al={"克尔里斯与阿库麦尔","克尔里斯为什么要供奉阿库麦尔"}},{q="克尔里斯被击败后会发生什么？",a="克尔里斯身后有一座放着四支仪式蜡烛的祭坛。点燃这些蜡烛会解除密室的保护结界，召唤出一波又一波阿库麦尔的仆从，并打开通往巨兽巢穴的封印之门。",al={"克尔里斯的蜡烛","克尔里斯的祭坛","月神殿蜡烛"}},{q="克尔里斯在战斗中使用什么力量？",a="克尔里斯施展强大的暗影法术、精神控制，以及一种魔法沉睡，可以在他的黑暗仪式持续期间使敌人丧失战斗力。",al={"克尔里斯的能力","克尔里斯的法术"}},{q="巴珊娜·符文图腾是谁？",a="巴珊娜·符文图腾是一位正在调查黑暗深渊腐化现象的盟友，她向冒险者警告了克尔里斯对上古之神崇拜的执迷，以及他试图让世界陷入原始混乱的野心。",al={"巴珊娜·符文图腾与克尔里斯","牛头人猎手与克尔里斯"}}},fx={e447f79b={q="梦游者克尔里斯效忠哪一方？",a="克尔里斯领导着暮光之锤教派在当地的秘密组织。他既不为部落效力，也不为联盟效力，而是将一生完全奉献给对古神的崇拜与侍奉，并致力于让原始混乱重返艾泽拉斯。",al={"克尔里斯的阵营","克尔里斯侍奉谁","梦游者克尔里斯的效忠对象"}},["710418bf"]={q="梦游者克尔里斯为什么在黑暗深渊？",a="克尔里斯在沉没的废墟中领导暮光之锤。教派成员在那里与古神沟通，并崇拜古神的仆从、九头蛇阿库麦尔。他在月神圣所主持教派仪式，远离窥探的目光。",al={"克尔里斯为何在黑暗深渊","克尔里斯在黑暗深渊的目的","克尔里斯为何来到这里"}},["7c0659ed"]={q="梦游者克尔里斯与谁有关联？",a="除了指挥洞穴中潜伏的暮光之锤教徒，克尔里斯还主持教派对可怖九头蛇阿库麦尔的崇拜。他也与自己崇拜的古神保持联系，在卡利姆多各地执行他们的黑暗计划。",al={"克尔里斯的盟友","克尔里斯与谁共事","克尔里斯的关系网"}}},fp="20,289,18.530.0,19.293.0,23.377.1,28.202.0,38.237.0,44.160.0,38.207.1,38.141.0,25.204.0"}
P.entries["npc:tyrande-whisperwind"] = {n="泰兰德·语风",s="泰兰德·语风是艾露恩的大祭司，也是暗夜精灵的最高领袖。在她的挚爱，大德鲁伊玛法里奥·怒风的陪伴下，她引领族人度过了灾难性的上古之战，并度过了长达一万年的长夜守望。如今，她坐镇泰达希尔的神圣枝桠，统领着The Sisterhood of Elune，并指挥哨兵部队守卫卡利姆多的神圣荒野。",h="泰兰德·语风是艾露恩的大祭司，也是暗夜精灵的最高领袖。在她的挚爱，大德鲁伊玛法里奥·怒风的陪伴下，她引领族人度过了灾难性的上古之战，并度过了长达一万年的长夜守望。如今，她坐镇泰达希尔的神圣枝桠，统领着The...",kw={"达纳苏斯","艾露恩","卡多雷","玛法里奥","祭司","哨兵部队","泰达希尔","泰兰德","语风"},ang={["class:Druid"]="当玛法里奥在翡翠梦境中沉睡时，泰兰德与塞纳里奥议会密切合作，以保护神圣林地并培育泰达希尔。",["class:Priest"]="作为艾露恩神圣眷顾的活体容器，泰兰德体现了卡多雷祭司的巅峰，她能召唤月光星辰并以纯粹的信仰治愈伤口。",["faction:Alliance"]="尽管历史上一直避世且极其独立，但泰兰德率领暗夜精灵加入了联盟，以确保共同防御卡利姆多日益增长的危险。",["faction:Horde"]="对于部落来说，泰兰德是一位令人生畏且毫不妥协的对手，她指挥哨兵部队暴力反抗在整个灰谷的资源开采活动。",["race:NightElf"]="泰兰德是你们的最高领袖和大祭司。一万多年来，她一直守护着你们的种族，在每一次考验中捍卫着月神之光。"},sec={{t="月神选民",b="泰兰德出生于古老的卡多雷帝国，与玛法里奥·怒风和伊利丹·怒风这对孪生兄弟一同长大。当兄弟俩分别钻研德鲁伊教义和魔法时，泰兰德作为一名祭司加入了艾露恩的侍奉行列。在上古之战期间，当恶魔燃烧军团首次入侵艾泽拉斯时，她站在玛法里奥身边与其对抗。受到月神的直接眷顾，泰兰德将姐妹会改造成了一支光辉的战斗力量，运用神圣的恢复能力和炽热的月火之力，将她的族人从彻底毁灭的边缘拯救出来。"},{t="长夜守望与哨兵部队",b="大分裂和永恒之井的封印之后，玛法里奥和德鲁伊们进入了翡翠梦境进行深度且漫长的休眠。泰兰德独自承担起了保卫他们正在复苏的领地的重任。她组织了哨兵部队——这是一支由精英女战士组成的队伍，她们在卡利姆多的森林中巡逻了一万年。在整个长夜守望期间，她时刻警惕着古老的邪恶和残留的恶魔余孽，对艾露恩保持着坚定不移的信仰，同时在与玛法里奥短暂重逢的间隙中等待了数个世纪。"},{t="第三次战争与新的避难所",b="当燃烧军团在第三次战争中卷土重来时，泰兰德果断采取行动，唤醒了沉睡的德鲁伊们以面对这场灾难性的威胁。她克服了对新到的兽人和人类的强烈不信任，帮助促成了海加尔山的孤注一掷的联盟，并在诺达希尔之巅牺牲了暗夜精灵的永恒生命以击碎阿克蒙德。随着海加尔山满目疮痍，玛法里奥再次致力于守护翡翠梦境，泰兰德在达纳苏斯雄伟的Temple of the Moon治理着卡多雷，谨慎地注视着部落的入侵以及她的人民在联盟中的新地位。"}},faq={{q="谁是泰兰德·语风？",a="泰兰德·语风是艾露恩的大祭司，也是暗夜精灵的最高精神与政治领袖。从上古之战到第三次战争，她引领族人走过了超过一万年的岁月，目前在达纳苏斯的Temple of the Moon领导着卡多雷。",al={"泰兰德是谁","泰兰德·语风背景故事","暗夜精灵领袖"}},{q="泰兰德目前居住在哪里？",a="泰兰德居住在首都达纳苏斯，位于世界之树泰达希尔的枝桠高处。她坐镇在Temple of the Moon的上层圣殿，周围环绕着艾露恩的祭司和哨兵守卫。",al={"泰兰德在哪里","泰兰德位置","哪里可以找到泰兰德"}},{q="泰兰德和玛法里奥是什么关系？",a="泰兰德和玛法里奥·怒风是终身的伴侣，他们共同引领暗夜精灵文明走过了万年岁月。尽管玛法里奥和他的孪生兄弟伊利丹在年轻时都曾追求过她，但泰兰德选择了玛法里奥，因为他对平衡与自然的深厚热爱，正如她对艾露恩的信仰一般。",al={"泰兰德与玛法里奥","泰兰德结婚了吗","泰兰德与伊利丹"}},{q="The Sisterhood of Elune是什么？",a="The Sisterhood of Elune是一个古老的暗夜精灵祭司宗教组织，致力于崇拜月亮女神。在身为大祭司的泰兰德的领导下，姐妹们不仅担任治疗者和精神向导，还是凶猛的军事指挥官和战斗人员。",al={"the sisterhood of elune","艾露恩祭司","泰兰德祭司"}},{q="泰兰德在长夜守望中扮演了什么角色？",a="在大分裂之后的一万年里，当玛法里奥和男性德鲁伊们在翡翠梦境中沉睡时，泰兰德建立并指挥了哨兵部队。她巡逻卡利姆多的荒野，猎杀残余的萨特和恶魔，并确保了族人在孤立状态下的安全。",al={"什么是长夜守望","泰兰德长夜守望","哨兵领袖"}},{q="为什么泰兰德对部落持谨慎态度？",a="在第三次战争期间，兽人进入了灰谷并开始大肆砍伐神圣森林，在恶魔之血的影响下杀害了半神塞纳留斯。虽然在海加尔山达成了不安的休战，但部落在灰谷持续进行的伐木作业，让泰兰德不得不让她的哨兵部队保持高度警惕。",al={"泰兰德与部落","泰兰德为何憎恨兽人","暗夜精灵与部落"}}},fx={["0754c2cc"]={q="泰兰德·语风效忠哪一方？",a="泰兰德是暗夜精灵的最高领袖，也是联盟的核心支柱。她领导艾露恩姐妹会，并在达纳苏斯的月神殿引领族人，全心致力于保护卡利姆多和族人免受外来威胁。",al={"泰兰德属于哪个阵营","泰兰德属于联盟吗","泰兰德的忠诚对象"}},["68f13d2e"]={q="泰兰德·语风想要什么？",a="她首要的职责是保护卡多雷和卡利姆多的神圣森林免受腐化势力侵害，无论是恶魔残党还是外来入侵者。玛法里奥沉睡于翡翠梦境期间，她还肩负起引领并守卫族人在泰达希尔新建家园的重担。",al={"泰兰德的目标是什么","泰兰德的动机","泰兰德想做什么"}},ade9ee47={q="泰兰德·语风为何闻名？",a="泰兰德被尊为艾露恩选中的高阶女祭司；一万年前，她曾在上古之战中助力击败燃烧军团。在长达数千年的漫长守望期间，她指挥哨兵守卫卡利姆多，后来又在海加尔山之战中与凡人种族并肩奋战。",al={"泰兰德为何受人敬仰","泰兰德的传说","泰兰德的声望"}}},fp="19,417,26.576.0,32.561.0,29.611.0,27.298.0,36.234.0,55.303.0,32.281.0,45.279.0,33.304.0"}
P.entries["npc:tyrion"] = {n="泰里恩",s="泰里恩是一名驻扎在Stormwind Keep内部的侏儒特工。他与埃林·提亚斯等密友一起在暗处行动，协助冒险者发掘敏感情报并打击针对王国的阴谋。",h="泰里恩是一名驻扎在Stormwind Keep内部的侏儒特工。他与埃林·提亚斯等密友一起在暗处行动，协助冒险者发掘敏感情报并打击针对王国的阴谋。",kw={"埃林·提亚斯","侏儒","潜入城堡","重要的物品","间谍","stormwind keep","袭击","泰里恩"},ang={["class:Rogue"]="对于处理埃林·提亚斯秘密行动的潜行者来说，泰里恩是Stormwind Keep内至关重要的内部接头人。",["faction:Alliance"]="泰里恩的情报工作对于保护王室免受王国首都内部酝酿的秘密威胁至关重要。",["race:Gnome"]="泰里恩体现了侏儒为高风险的联盟间谍活动所带来的微妙和智慧，在傲慢的人类贵族眼皮底下开展行动。"},sec={{t="要塞中的静默身影",b="在Stormwind Keep的宏伟殿堂中，泰里恩保持着低调。当贵族廷臣和皇家卫兵在走廊里来来往往时，这名聪明的侏儒在暗处行动，监视着宫殿的一举一动，并与那些在官方监管之外行动的外部联络人保持联系。"},{t="阴影与间谍活动",b="泰里恩是埃林·提亚斯的密友，后者是Trade District著名的奶酪商，经营着一个隐秘的情报网。当出现需要绕过贵族议会官方官僚机构的敏感事项时，埃林·提亚斯会直接将可靠的特工引向城堡内的泰里恩。"},{t="揭露威胁",b="泰里恩协助调查员执行关键的渗透任务，并确保城内敏感物品的安全。他的努力最终揭露了王国皇家核心内部迫在眉睫的危险，在有组织的袭击破坏暴风城的领导层之前向盟友发出了警告。"}},faq={{q="泰里恩是谁？",a="泰里恩是一名足智多谋的侏儒特工，驻扎在Stormwind Keep内。他与秘密盟友并肩工作，负责处理绕过正规皇家渠道的秘密任务和情报收集。",al={"这个侏儒是谁","泰里恩的身份","泰里恩做什么"}},{q="在哪里可以找到泰里恩？",a="泰里恩位于暴风城的Stormwind Keep内，负责警戒并协助那些带着他信任的联络人消息前来的人员。",al={"泰里恩的位置","泰里恩在哪里","寻找泰里恩"}},{q="他与埃林·提亚斯有什么关系？",a="泰里恩和埃林·提亚斯是多年的朋友和合作者。埃林·提亚斯利用他的贸易关系收集整个王国的流言，当需要在Stormwind Keep内部采取秘密行动时，他会派可靠的冒险者去联系泰里恩。",al={"泰里恩和埃林·提亚斯","泰里恩认识埃林·提亚斯吗","埃林·提亚斯的关系"}},{q="泰里恩提供什么任务？",a="泰里恩参与了多项秘密行动，包括“潜入城堡”、“重要的物品”以及在“袭击！”期间向盟友发出警告。",al={"泰里恩的任务","他提供什么任务"}},{q="为什么一个侏儒会在人类宫廷处理秘密行动？",a="侏儒是联盟的关键盟友，而像泰里恩这样的人提供了人类当局往往会忽视的敏锐智慧、隐秘手段和技术能力。",al={"为什么一个侏儒在stormwind keep","要塞的侏儒特工"}},{q="泰里恩正在调查的阴谋性质是什么？",a="泰里恩协助追踪被窃取的情报和在皇家宫廷眼皮底下运作的隐藏阴谋，最终揭露了城内武装伏击的企图。",al={"泰里恩的阴谋","泰里恩在调查什么"}}},fx={f469be85={q="泰里恩效忠哪一方？",a="泰里恩与老友埃林·提亚斯——一位精通奶酪贸易的大师级商人兼秘密线人——在暴风城要塞内低调行事。尽管他通过暗影、密谈和秘密谍报活动行事，他仍忠于暴风城和联盟的安危，暗中防范威胁王国安全的隐患。",al={"泰里恩忠于暴风城吗","泰里恩的阵营","泰里恩为谁效力"}}},fp="6,248,28.275.0,21.321.0,21.283.1,14.198.0,24.141.0,39.226.0,30.146.0,61.169.0,55.168.1"}
P.entries["npc:ukor"] = {n="乌克尔",s="乌克尔是一个兽人苦工，在杜隆塔尔试炼谷外东侧的小路旁休息。为了帮助他的族人，他从剃刀岭大老远地运送补给过来，却发现训练场里已经有充足的物资了。",h="乌克尔是一个兽人苦工，在杜隆塔尔试炼谷外东侧的小路旁休息。为了帮助他的族人，他从剃刀岭大老远地运送补给过来，却发现训练场里已经有充足的物资了。",kw={"苦工的负担","杜隆塔尔","格罗斯克","苦工","剃刀岭","乌克尔","试炼谷"},ang={["faction:Horde"]="对于刚完成试炼的新兵来说，帮助乌克尔是他们最初支持部落定居点之间日常后勤工作的机会之一。",["race:Orc"]="兽人苦工承担着建设新部落的艰苦体力劳动，而乌克尔的事迹表明，即使是卑微的劳工也拥有支持杜隆塔尔战士们的强烈愿望。"},sec={{t="苦工的差事",b="虽然许多兽人苦工一辈子都在严厉的监工注视下伐木或搬运岩石，但乌克尔却试图主动承担一项服务。他受命或出于自愿，将食物从剃刀岭运到在试炼谷受训的新兵那里，为此他穿越了杜隆塔尔那充满危险的红色平原，避开了潜伏的蝎毒虫和野猪。抵达目的地后，他发现试炼谷物资充沛，根本不需要他的这批补给。在路边精疲力竭且有些沮丧的他，只能指望路过的年轻冒险者帮忙把这些未使用的补给送回北边的旅店老板格罗斯克那里。"}},faq={{q="乌克尔是谁？",a="乌克尔是一名勤恳的兽人苦工，驻扎在杜隆塔尔南部通往试炼谷东侧的道路旁。",al={"乌克尔背景故事","乌克尔是谁","乌克尔做了什么"}},{q="乌克尔为什么要带着一袋食物站在路边？",a="乌克尔从剃刀岭背了一大袋口粮下来，想给在试炼谷受训的年轻战士们补充给养。当他赶到时，发现那里并不缺物资，这让他带着多余的食物进退两难。",al={"为什么乌克尔在这里","乌克尔的任务原因","乌克尔的食物包裹"}},{q="乌克尔要求路过的旅行者做什么？",a="因为太害怕路上的野兽，不敢亲自把包裹运回去，乌克尔请求那些前往北边剃刀岭的新手冒险者帮忙把包裹交还给旅店老板格罗斯克。",al={"乌克尔的任务","乌克尔想要什么","苦工的负担任务"}}},fx={["5f505ef5"]={q="乌克尔效忠哪一方？",a="乌克尔是部落忠诚的苦工。他谦逊尽责，为杜隆塔尔和族人搬运补给，并在剃刀岭与试炼谷等定居点之间奔走办事，面对野兽也毫无怨言。",al={"乌克尔的阵营","乌克尔属于部落吗","乌克尔侍奉谁"}},["2e03bca7"]={q="乌克尔与谁有关联？",a="乌克尔听命于剃刀岭的旅店老板格罗斯克。他代表格罗斯克前往试炼谷送交新鲜补给，并依靠路过的冒险者把多余的货物送回旅店老板那里。",al={"乌克尔的盟友","乌克尔认识谁","乌克尔与旅店老板格罗斯克"}}},fp="4,233,15.612.0,12.114.0,53.223.0,43.176.0"}
P.entries["npc:ula-elek"] = {n="尤拉莱克",s="尤拉莱克是一位居住在杜隆塔尔南海岸森金村的暗矛巨魔铁匠。他与老练的兽人铁匠森戈·火眼通力合作，为那些努力证明自己价值的部落战士锻造特制的护甲。他的作品将传统的巨魔工艺与从卡利姆多各地收集的奇异战利品结合在一起。",h="尤拉莱克是一位居住在杜隆塔尔南海岸森金村的暗矛巨魔铁匠。他与老练的兽人铁匠森戈·火眼通力合作，为那些努力证明自己价值的部落战士锻造特制的护甲。他的作品将传统的巨魔工艺与从卡利姆多各地收集的奇异战利品结合在一起。",kw={"残暴护手","暗矛","杜隆塔尔","萨特蹄","森金村","铁匠","森戈·火眼","尤拉莱克"},ang={["class:Warrior"]="尤拉莱克在收集残暴护甲套装的过程中扮演着关键角色，他遵照森戈·火眼的指示，将辛苦得来的萨特蹄塑造成坚固的护手。",["profession:Blacksmithing"]="他将野兽和恶魔战利品融入战士护甲的做法，凸显了部落锻造业在传统铸造厂之外那种务实且足智多谋的特质。",["race:Troll"]="尤拉莱克代表了暗矛铁匠在羽翼未丰的部落中所占据的关键地位，直接在森金村开放的海滨锻造前线装备。"},sec={{t="暗矛之匠",b="尤拉莱克在森金村的茅屋与火盆之间从事着他的技艺，作为一名技艺精湛的护甲匠为暗矛部族服务。在这个不断受到附近敌对野猪人和海爬虫威胁的沿海定居点，保持兵刃锋利、护甲坚固对部族的生存至关重要。不过，尤拉莱克的名声早已超出了当地防御的范围，吸引了整个部落各地久经沙场的战士的目光。"},{t="锻造残暴护甲",b="当年轻的战士们前往贫瘠之地的瞭望台拜访森戈·火眼时，这位老兵会指引他们向南前往森金村寻找尤拉莱克。森戈信任这位巨魔铁匠，委托他制作残暴护手，这是一件配得上历经战火考验的前线战士的威武装备。尤拉莱克完成这项任务需要稀有的材料，尤其是那些在灰谷东北部汲取森林魔力的萨特的肿胀未裂蹄。"}},faq={{q="尤拉莱克是谁？",a="尤拉莱克是一位居住在杜隆塔尔森金村的暗矛巨魔护甲匠。他深得部落老兵的信任，负责为崭露头角的前线战士锻造坚固耐用的特制护甲。",al={"尤拉莱克是谁","尤拉莱克背景故事","尤拉莱克背景"}},{q="在哪里可以找到尤拉莱克？",a="他位于森金村，这是一个坐落在杜隆塔尔东南海岸、剃刀岭南部的暗矛定居点。",al={"尤拉莱克位置","尤拉莱克在哪里","寻找尤拉莱克"}},{q="为什么森戈·火眼要派战士去找尤拉莱克？",a="森戈·火眼认可尤拉莱克出众的铁匠技艺，并委托他为那些赢得了这位老兵尊重的部落战士制作残暴护手。",al={"森戈和尤拉莱克","为什么找尤拉莱克"}},{q="尤拉莱克制作护手需要什么材料？",a="为了制作残暴护手，尤拉莱克要求战士们猎杀灰谷东北部的萨特，并收集它们肿胀的未裂蹄作为核心锻造材料。",al={"尤拉莱克材料","残暴护手原料"}},{q="尤拉莱克制作什么样的装备？",a="他擅长锻造重型战斗护甲，特别是残暴护手，这是为部落中有前途的战士锻造的传统残暴护甲套装的一部分。",al={"尤拉莱克制作什么","尤拉莱克奖励"}},{q="为什么护手需要萨特蹄？",a="灰谷东北部的萨特以森林的纯净为食，而那些汲取了最多魔力的萨特拥有肿胀的未裂蹄。尤拉莱克将那些蹄子中蕴含的力量汲取出来，并将其注入到护手中。",al={"为什么要萨特蹄","护手用的蹄子"}}},fx={["3fd6027c"]={q="尤拉莱克效忠哪一方？",a="尤拉莱克是一名效忠部落的暗矛巨魔。他以杜隆塔尔海岸边的森金村为据点，为部落勇士效力，并与萨尔格里姆·火眼等兽人铁匠合作，为守卫共同领土的战士打造坚固的护甲。",al={"尤拉莱克的阵营","尤拉莱克属于部落吗","尤拉莱克的效忠对象"}},c0ac20d7={q="尤拉莱克想要什么？",a="尤拉莱克需要合用的材料来磨炼技艺、打造坚固的护甲。萨尔格里姆召唤他时，他会让崭露头角的战士收集异域材料，例如萨特的蹄子，以便打造出配得上身经百战之士的凶悍护手。",al={"尤拉莱克的目标","尤拉莱克需要什么","尤拉莱克想要什么"}},a7c1ab84={q="尤拉莱克为什么在森金村？",a="尤拉莱克居住在森金村，作为护甲匠为自己的部族和部落效力。他在杜隆塔尔海岸边工作，既与暗矛族人近邻，也利用自己的熔炉训练并装备部落的前线战士。",al={"尤拉莱克为何在森金村","尤拉莱克所在位置的原因","尤拉莱克为何在这里"}},e890a681={q="尤拉莱克与谁有关联？",a="尤拉莱克与一位驻守在贫瘠之地、技艺高超的兽人护甲匠萨尔格里姆·火眼关系密切。萨尔格里姆信任尤拉莱克的手艺，会直接派有前途的战士前往森金村的铁砧旁，让他为他们打造护手。",al={"尤拉莱克的人际关系","尤拉莱克认识谁","尤拉莱克的盟友"}}},fp="8,345,22.413.0,24.450.0,16.184.0,28.127.0,54.178.0,56.182.0,38.171.0,42.220.0"}
P.entries["npc:umpi"] = {n="乌比",s="乌比是一只栖息在塔伦米尔的青蛙，它是药剂师林度恩无意中选中的实验室助手。它被关在皇家药剂师学会的工作间里，成为了实验性毒素和瘟疫药剂反复试验的测试对象。",h="乌比是一只栖息在塔伦米尔的青蛙，它是药剂师林度恩无意中选中的实验室助手。它被关在皇家药剂师学会的工作间里，成为了实验性毒素和瘟疫药剂反复试验的测试对象。",kw={"药剂师林度恩","痛苦药剂","受难药剂","青蛙","希尔斯布莱德丘陵","塔伦米尔","乌比"},ang={["race:Undead"]="乌比体现了皇家药剂师学会无情且务实的研究方法，在这里，生死仅仅是完善被遗忘者军火库过程中的变量。"},sec={{t="永无止境的试验生涯",b="在塔伦米尔阴暗的实验室里，被遗忘者们夜以继日地调制着死亡与痛苦的药剂。对药剂师林度恩来说，严谨的科学研究需要活体组织来测试配方，而乌比则承受了这些试验带来的大部分痛苦。林度恩经常将致命的药剂——例如受难药剂和痛苦药剂——直接用于它身上。一旦毒药造成了不可避免的死亡，药剂师就会将这只两栖动物复活，确保它随时准备为皇家药剂师学会的荣耀再次承受致命剂量的药剂。"}},faq={{q="乌比是谁？",a="乌比是药剂师林度恩在塔伦米尔饲养的一只青蛙。它既是助手，也是林度恩那些有害炼金实验的首要测试对象。",al={"乌比是谁","乌比是什么","塔伦米尔的青蛙"}},{q="为什么药剂师林度恩要不断杀害乌比？",a="药剂师林度恩利用乌比来评估他新调制出的毒素的效力。在给它喂食受难药剂等致命药剂后，他会将其复活，以便在未来的试验中让它再次被毒害。",al={"为什么要杀乌比","乌比中毒","林度恩的青蛙"}},{q="乌比是活着的还是亡灵？",a="从生物学上讲，它游走于两者之间。虽然从技术上讲它表现为一只野兽，但药剂师林度恩公开承认，每次致命的毒药试验后，他都会将其从死亡中复活。",al={"乌比是亡灵吗","乌比僵尸","亡灵青蛙"}},{q="在哪里可以找到乌比？",a="乌比位于希尔斯布莱德丘陵的塔伦米尔药剂师工作间内，就在药剂师林度恩的工作台旁边。",al={"乌比在哪里","乌比的位置"}}},fx={["3625273f"]={q="乌比效忠于哪一方？",a="乌比本质上是药剂师林度恩和皇家药剂师协会的囚禁助手兼试验对象。她对被遗忘者或部落并无政治忠诚，只能忍受林度恩决定灌进她喉咙里的各种药剂。",al={"乌比阵营","乌比是部落的吗","乌比效忠于谁"}},d54b4816={q="乌比与谁有联系？",a="乌比直接受药剂师林度恩控制，在塔伦米尔充当他不情愿的实验室助手。她的全部生活都围绕着测试林度恩的致命药剂、死于药剂的毒性，并被从死亡边缘拖回来后再次接受试验。",al={"乌比 药剂师林度恩","谁控制着乌比","乌比的主人"}}},fp="4,237,27.552.0,12.147.0,44.216.0,24.188.0,24.136.0"}
P.entries["npc:undertaker-mordo"] = {n="管理员摩尔多",s="管理员摩尔多是丧钟镇墓穴的看守者，也是新觉醒的被遗忘者睁开眼后见到的第一个人。他告诉那些苏醒者，他们不再是巫妖王的奴隶，并指引他们投身于被遗忘者的大业；至于那些从未苏醒的尸体，则会被投入火中。",h="管理员摩尔多是丧钟镇墓穴的看守者，也是新觉醒的被遗忘者睁开眼后见到的第一个人。他告诉那些苏醒者，他们不再是巫妖王的奴隶，并指引他们投身于被遗忘者的大业；至于那些从未苏醒的尸体，则会被投入火中。",kw={"丧钟镇","冷酷的觉醒","灰影墓穴","提瑞斯法林地","管理员摩尔多"},ang={["race:Undead"]="管理员摩尔多是你死后睁开双眼时交谈的第一人，指引你迈出为Sylvanas Windrunner女王效力的最初几步。"},sec={{t="丧钟镇的觉醒",b="管理员摩尔多在提瑞斯法林地的丧钟镇看守着墓穴，注视着一具具尸体挣脱天灾军团的束缚。对于每一位在冰冷的墓穴中苏醒、重获自由的被遗忘者，摩尔多都会为他们在这个陌生的第二人生中提供最初的指引。他评估他们的神智，告知他们当前的处境，并立即指引他们去为Sylvanas Windrunner女王效力。"},{t="那些无法苏醒的灵魂",b="并不是每一具被送到墓穴的尸体都能苏醒。摩尔多不会等待太久：静止不动的尸体会直接被投入火中，而对于那些苏醒的人，他则以冷淡且毫无仪式感的方式予以迎接。任何神智清醒的复生者都会被指引着走上台阶，沿着道路前往礼拜堂找暗影牧师萨维斯，由他来解释他们新的存在状态。肆虐村庄北部的无脑僵尸是萨维斯负责的事，而不是摩尔多的；暗影牧师会派遣新生的复生者去消灭它们。"}},faq={{q="管理员摩尔多是谁？",a="管理员摩尔多是位于提瑞斯法林地丧钟镇墓穴的被遗忘者看守人。他迎接刚复生的亡灵，并指引他们服役。",al={"摩尔多是谁","管理员摩尔多背景故事","丧钟镇摩尔多"}},{q="他为什么待在墓地里？",a="摩尔多是丧钟镇墓穴的看守者，刚摆脱巫妖王控制的亡灵们会在那里苏醒。他守在那里，以便在他们醒来的那一刻迎接他们。",al={"为什么摩尔多在墓地","摩尔多做什么","摩尔多的工作"}},{q="那些醒来后失去神智的亡灵会怎样？",a="从未苏醒的尸体会直接被投入火中。在丧钟镇北部徘徊的无脑僵尸并非由摩尔多负责：暗影牧师萨维斯会派遣新生的复生者去消灭他们，无论他们是否曾是自己的兄弟姐妹。",al={"那些无法被拯救的人","丧钟镇疯狂的亡灵","丧钟镇野性的亡灵"}},{q="摩尔多将新生的被遗忘者派往何处？",a="在确认刚苏醒的灵魂神智清醒后，摩尔多会让他们走出墓穴，沿着路前往礼拜堂与暗影牧师萨维斯交谈，由他来解释加入被遗忘者阵营的意义。",al={"离开摩尔多后去哪","摩尔多任务指引","摩尔多后的下一步"}}},fx={a2ca27d8={q="管理员摩尔多效忠于哪一方？",a="管理员摩尔多效忠于被遗忘者和黑暗女王希尔瓦娜斯·风行者。他在丧钟镇新近苏醒的亡灵前线工作，确保那些刚被复活且神志清醒的尸体加入被遗忘者，而不是受巫妖王蛊惑或陷入无意识的狂乱。",al={"摩尔多阵营","摩尔多效忠于谁","摩尔多是被遗忘者吗"}},b30fe27a={q="管理员摩尔多想要什么？",a="摩尔多眼下最关心的是管理丧钟镇的墓地。他希望新近复活的被遗忘者恢复神智，向暗影牧师萨维斯等当地领袖报到，并协助清除那些从泥土中爬出、却未能保留神智的无意识亡灵。",al={"摩尔多想做什么","摩尔多的目标","摩尔多的职责"}},["0fa90ad3"]={q="管理员摩尔多与谁有联系？",a="摩尔多看守着丧钟镇的墓穴，并与下方礼拜堂里的暗影牧师萨维斯密切合作。他会把每一名新近苏醒的被遗忘者都送到萨维斯那里，这一切都是为了效忠希尔瓦娜斯女士和被遗忘者。",al={"摩尔多的盟友","摩尔多与谁共事","摩尔多的关系"}}},fp="16,304,27.440.0,21.504.0,24.164.0,34.182.0,60.238.0,43.227.0"}
P.entries["npc:ur-kyo"] = {n="乌尔库",s="乌尔库是一位受人尊敬的丛林巨魔牧师训练师，位于奥格瑞玛的Valley of Spirits。作为暗矛巨魔部族中公认的精神领袖和最伟大的牧师，他在部落的主城里指引着初出茅庐的精神修行者。通过他的教导，牧师们学会了与灵魂沟通，并平衡暗影与圣光的力量。",h="乌尔库是一位受人尊敬的丛林巨魔牧师训练师，位于奥格瑞玛的Valley of...",kw={"暗矛","虚弱诅咒","奥格瑞玛","牧师训练师","暗影守卫","乌尔库","valley of spirits"},ang={["class:Priest"]="乌尔库是穿行于杜隆塔尔的部落牧师的重要导师，他向冒险者们传授信仰的奥秘、暗影仪式和神圣结界的知识。",["faction:Horde"]="乌尔库位于奥格瑞玛Valley of Spirits的中心，为部落的防御体系培养治疗者和暗影施法者，提供了必要的精神支撑。",["race:Troll"]="对于暗矛巨魔而言，乌尔库是奥格瑞玛最重要的精神向导，在回音群岛陷落后，他一直致力于保存部族传统的巫毒和古老的魔法仪式。"},sec={{t="暗矛的精神导师",b="乌尔库居住在Valley of Spirits宁静的水域和茅屋中，是奥格瑞玛中最显赫的精神权威之一。对于那些逃离回音群岛并与萨尔的部落一同在杜隆塔尔建立家园的暗矛巨魔来说，保持神圣的传统至关重要。乌尔库守护着这些祖传的修行方式，不仅为部族的神秘主义者，也为前来求教的修行者提供了精神准则与指引。"},{t="指引与古老仪式",b="踏上信仰之路的牧师们会在乌尔库身上找到一位耐心的导师。他负责监督传统的训练和古老的仪式，包括传授虚弱诅咒和名为暗影守卫的防御结界。乌尔库还担任部落牧师们的联络人，帮助他们理解部落联盟内部多元的精神修行方式，并帮助他们架起沟通巨魔巫毒、祖传之道与外来教派之间的桥梁。"}},faq={{q="乌尔库是谁？",a="乌尔库是一位丛林巨魔，也是奥格瑞玛Valley of Spirits里的首席牧师训练师。他被公认为是暗矛牧师的精神领袖，也是他部族中牧师造诣最高的人。",al={"乌尔库的角色","乌尔库的身份","乌尔库是谁"}},{q="我在哪里可以找到乌尔库？",a="乌尔库居住在奥格瑞玛西侧，巨魔聚居的区域——Valley of Spirits。你可以在水边靠近其他精神导师的训练小屋旁找到他。",al={"乌尔库的位置","乌尔库地图","寻找乌尔库"}},{q="乌尔库会传授哪些技能？",a="作为职业训练师，乌尔库指导牧师学习基础的暗影法术和圣光法术。此外，他还带领暗矛牧师进行其独特的种族仪式，引导他们掌握虚弱诅咒和暗影守卫。",al={"乌尔库的法术","乌尔库的能力","巨魔牧师法术"}},{q="为什么乌尔库在奥格瑞玛修行，而不是在回音群岛？",a="在扎拉赞恩背叛并失去回音群岛后，暗矛部族与兽人一同在杜隆塔尔重新定居。乌尔库在Valley of Spirits扎下根基，以维护部族的神秘传统，并为部落培养新的保卫者。",al={"乌尔库与奥格瑞玛背景","为什么乌尔库在奥格瑞玛"}},{q="乌尔库会指导非巨魔牧师吗？",a="是的。乌尔库会指导所有前来拜访他的部落牧师，作为暗矛巨魔与其他部落成员（包括被遗忘者）之间知识传播的桥梁。",al={"亡灵可以在乌尔库处训练吗","乌尔库部落训练师"}},{q="乌尔库在暗矛牧师中扮演什么角色？",a="乌尔库被公认为是暗矛部族最伟大的牧师，并担任他们的首席精神领袖，确保祖传的习俗、仪式和巫毒修行能够传承给下一代。",al={"乌尔库的地位","部族中最伟大的牧师"}}},fx={["77e8c5e8"]={q="乌尔库效忠于哪一方？",a="乌尔库坚定地支持暗矛部族和部落。他驻守在奥格瑞玛的灵魂谷，在酋长沃金和大酋长萨尔的领导下，担任族人的重要精神导师。他深受丛林巨魔传统的熏陶，也欢迎前来寻求精神指导、学习古老仪式的部落牧师。",al={"乌尔库阵营","乌尔库效忠于谁","乌尔库是部落的吗"}},a5f00a0b={q="乌尔库想要什么？",a="乌尔库致力于保护暗矛部族的精神传统，并指导新一代牧师。他努力维持古老的习俗，引导灵魂的古老力量，并确保踏上牧师之路的人具备保护部族、守护其在部落中地位所需的决心和学识。",al={"乌尔库的目标","乌尔库想做什么","乌尔库的职责"}},fa6f514c={q="乌尔库为何在暗矛部族中享有盛名？",a="乌尔库被尊为暗矛部族最伟大的牧师。他是备受敬仰的至高精神领袖，与灵魂有着深厚的联结，精通巨魔的神圣仪式，因此在卡利姆多的暗矛部族中，他是精神力量与智慧方面的最高权威。",al={"乌尔库有名吗","乌尔库为何受人尊敬","乌尔库的声望"}}},fp="6,376,33.451.0,26.436.0,14.218.0,24.190.0,33.220.0,65.262.0,44.174.0,50.211.0"}
P.entries["npc:uzzek"] = {n="犹塞克",s="犹塞克是一位久经沙场的兽人老兵，驻扎在贫瘠之地的前沿哨所西南方。在卡利姆多的无数次冲突中幸存下来的他，现在致力于评估和磨练那些在干旱平原上历练的部落勇士。",h="犹塞克是一位久经沙场的兽人老兵，驻扎在贫瘠之地的前沿哨所西南方。在卡利姆多的无数次冲突中幸存下来的他，现在致力于评估和磨练那些在干旱平原上历练的部落勇士。",kw={"贫瘠之地","前沿哨所","防御之道","thun'grim firegaze","犹塞克","战士训练师"},ang={["class:Warrior"]="犹塞克是你旅途中一位重要的导师，当你从最初的训练场地走向广阔的贫瘠之地时，他会考验你的意志和防御技巧。",["faction:Horde"]="犹塞克驻扎在前沿哨所附近，是守卫杜隆塔尔与未驯服草原之间脆弱边界的资深防卫者之一。"},sec={{t="平原老兵",b="犹塞克位于前沿哨所西南方，地处贫瘠之地的东部边界，代表了部落前线战士坚韧不拔的精神。在近期的战争中历经残酷战斗后，他担任起了一位教官和试炼发起者，指导那些寻求掌握防御之道的年轻战士。想要得到犹塞克的认可，必须证明自己有能力对抗那些在荒野干道上肆虐的野兽和劫掠者。"}},faq={{q="犹塞克是谁？",a="犹塞克是一位驻扎在贫瘠之地东部、前沿哨所西南方的资深兽人战士。他负责引导那些正在学习防御战斗基础知识的部落勇士。",al={"犹塞克是谁","犹塞克背景故事","犹塞克npc"}},{q="我在哪里可以找到犹塞克？",a="他位于前沿哨所西南方的悬崖边，俯瞰着从杜隆塔尔进入贫瘠之地的道路。",al={"犹塞克位置","犹塞克在哪里","寻找犹塞克"}},{q="犹塞克对部落战士有什么作用？",a="犹塞克通过耐力和坚守阵地的能力来考验年轻战士，并委派他们完成诸如“防御之道”之类的试炼，随后指引他们前往寻找像Thun'grim Firegaze这样的老练大师。",al={"犹塞克战士任务","防御之道犹塞克"}}},fx={a0e5656a={q="犹塞克效忠于哪一方？",a="犹塞克忠于部落。他是一名兽人老兵，在贫瘠之地与杜隆塔尔边境的前沿哨所附近站岗，守护着萨尔建立的新兴国家，并考验和指导那些有望保卫部落领土的勇士。",al={"犹塞克是部落的吗","犹塞克阵营","犹塞克效忠于谁"}},["6cff12ed"]={q="犹塞克想要什么？",a="犹塞克希望考验有志成为部落勇士的人，检验他们对纪律和防御基本原则的掌握。他亲历过无数战斗，确保年轻战士懂得坚韧、生存之道和战术运用，然后才让他们接受更深入的训练。",al={"犹塞克需要什么","犹塞克的职责","犹塞克要求什么"}},f99df2aa={q="犹塞克为何驻守在前沿哨所附近？",a="犹塞克在前沿哨所西南方的崎岖地带巡逻，那里正好位于杜隆塔尔与贫瘠之地的交界处。他驻守边境，可以拦下并考察踏入广阔世界的部落勇士，为他们迎接更残酷的冲突做好准备。",al={"犹塞克为何在这里","犹塞克为何在贫瘠之地","犹塞克驻守此地的原因"}}},fp="5,250,21.440.0,13.188.0,23.124.0,45.200.0"}
P.entries["npc:valstag-ironjaw"] = {n="瓦斯塔格·铁腭",s="瓦斯塔格·铁腭是一名驻扎在湿地沿海沼泽米奈希尔城堡内的铁炉堡矮人战士。面对困扰着连接洛克莫丹与海岸贸易通道的紧迫危险，他协助保障地区路线的安全，并将当地的威胁通报给港口的驻军。",h="瓦斯塔格·铁腭是一名驻扎在湿地沿海沼泽米奈希尔城堡内的铁炉堡矮人战士。面对困扰着连接洛克莫丹与海岸贸易通道的紧迫危险，他协助保障地区路线的安全，并将当地的威胁通报给港口的驻军。",kw={"奥加兹大门","斯托菲队长","洛克莫丹","米奈希尔港","米奈希尔城堡","瓦斯塔格·铁腭","湿地"},ang={["faction:Alliance"]="瓦斯塔格协助维持米奈希尔港与卡兹莫丹群山之间关键补给动脉的畅通，这对联盟的贸易和旅行至关重要。",["race:Dwarf"]="对于从铁炉堡或洛克莫丹南下的矮人冒险者来说，瓦斯塔格代表了守卫这片重要且多雨的西海岸的前沿驻军。"},sec={{t="城堡守卫",b="瓦斯塔格·铁腭位于米奈希尔港的米奈希尔城堡内，是守卫低地的矮人驻军的一员。周围的沼泽充满危险，从敌对的龙喉兽人到贪婪的野兽，使得通讯和补给线的维护变得困难重重。瓦斯塔格协助协调主要通道的防御工作，特别是穿过丹奥加兹通往洛克莫丹的险峻道路。"},{t="守卫通道",b="随着险恶的奥加兹大门被敌对势力封锁，往返于米奈希尔港和洛克莫丹之间的旅行者和补给车队时刻面临着威胁。瓦斯塔格指挥有能力的冒险者去对抗潜伏在山口中的强盗和兽人，并在前方斥候和斯托菲队长等指挥官之间传递关键的军事情报。"}},faq={{q="我在哪里可以找到瓦斯塔格·铁腭？",a="瓦斯塔格·铁腭位于米奈希尔城堡内，这座石质堡垒坐落在西部湿地的米奈希尔港中。",al={"瓦斯塔格位置","瓦斯塔格·铁腭在哪里","瓦斯塔格·铁腭npc"}},{q="瓦斯塔格在湿地扮演什么角色？",a="他是驻扎在城堡的一名铁炉堡矮人，协助进行防御行动，帮助管理通往矮人腹地的山区道路上的威胁。",al={"瓦斯塔格做什么","瓦斯塔格职责"}},{q="为什么通往洛克莫丹的通道让他如此担忧？",a="奥加兹大门是连接沿海港口米奈希尔港与洛克莫丹和铁炉堡的重要陆路桥梁。封锁山口的敌对势力威胁着粮食、部队调动和补给线的畅通。",al={"为什么奥加兹大门重要","瓦斯塔格洛克莫丹"}},{q="斯托菲队长是谁？",a="斯托菲队长是驻扎在米奈希尔城堡的一名高级军官。瓦斯塔格与他协调工作，以确保军事报告和安全简报能够送达驻军指挥部。",al={"与斯托菲队长的联系","谁是斯托菲队长"}}},fx={bcb025ae={q="瓦斯塔格·铁腭是谁？",a="瓦斯塔格·铁腭是一名身材魁梧的矮人防卫者，驻扎在米奈希尔港内的米奈希尔城堡。他为联盟和矮人同胞效力，协助守卫危险的商路和山道，这些路线连接着湿地的海港与洛克莫丹的高地。",al={"瓦斯塔格是谁","瓦斯塔格·铁腭的背景","瓦斯塔格·铁腭是谁"}},["3e0052ae"]={q="瓦斯塔格·铁腭效忠于哪一方？",a="瓦斯塔格忠于铁炉堡和大联盟。他驻守在米奈希尔港的防卫部队中，与斯托菲队长等矮人军方人员协同作战，保护旅客并抵御当地威胁，确保补给线畅通。",al={"瓦斯塔格·铁腭的阵营","瓦斯塔格效忠于谁","瓦斯塔格是联盟的吗"}}},fp="15,317,16.445.0,17.373.0,33.124.0,44.170.0,53.217.0,25.173.0"}
P.entries["npc:vanndar-stormpike"] = {n="范达尔·雷矛",s="范达尔·雷矛是一位勇猛的矮人山丘之王，他在丹巴达尔的北部要塞指挥着雷矛远征军。他在奥特兰克山谷的冰封山峰中搜寻古代遗物和原始资源，领导着联盟对抗霜狼氏族的坚决战争。",h="范达尔·雷矛是一位勇猛的矮人山丘之王，他在丹巴达尔的北部要塞指挥着雷矛远征军。他在奥特兰克山谷的冰封山峰中搜寻古代遗物和原始资源，领导着联盟对抗霜狼氏族的坚决战争。",kw={"奥特兰克","丹巴达尔","矮人","霜狼","山丘之王","雷矛","范达尔"},ang={["faction:Alliance"]="范达尔是奥特兰克前线的总指挥，负责坚守北部壁垒，并将联盟的领土推进到荒野山脉中。",["race:Dwarf"]="对于铁炉堡的矮人来说，范达尔体现了山丘之王不屈的精神，为夺回古代遗产和尊崇探险者协会而战。"},sec={{t="丹巴达尔领主",b="作为铁炉堡的一名资深山丘之王，范达尔·雷矛带头领导了矮人对奥特兰克山谷的挖掘工作。第三次战争后，他率领雷矛卫队进入北部山脉，寻找隐藏的矿产财富和失落已久的泰坦神器。在丹巴达尔的坚固堡垒中定居后，范达尔将山谷视为祖传权利和理所应当的联盟领土。他以矮人特有的冷酷决心指挥着军事前哨、防御碉堡和前线推进，并誓言在他的监视下绝不撤退。"},{t="冰封山口之战",b="范达尔无情的采矿和勘探活动直接侵犯了霜狼氏族的家园，引发了残酷的山地战争。尽管兽人要求撤离，范达尔拒绝放弃一寸土地，发誓奥特兰克山谷终将属于矮人。在丹巴达尔深处的王座室里，在元帅和护卫的簇拥下，他亲自监督着针对霜狼入侵的防御，同时派遣联盟勇士去突破敌军防线，彻底收复山谷。"}},faq={{q="范达尔·雷矛是谁？",a="范达尔·雷矛是一位矮人山丘之王，也是雷矛远征军的最高指挥官。他驻扎在丹巴达尔，领导着奥特兰克山谷内的联盟战争。",al={"范达尔是谁","范达尔·雷矛背景故事","雷矛领袖"}},{q="范达尔为什么要在奥特兰克山谷作战？",a="范达尔率领雷矛远征军来到奥特兰克山谷，旨在发掘古代遗物并提取自然资源。他拒绝放弃这些主权要求，导致矮人与当地的霜狼兽人陷入了血腥的冲突。",al={"为什么矮人在奥特兰克","范达尔动机","雷矛目标"}},{q="范达尔待在哪里？",a="他在奥特兰克山谷的北部要塞丹巴达尔指挥军队，那里由矮人碉堡、元帅和精英卫队所保护。",al={"范达尔在哪里","范达尔位置","丹巴达尔首领"}},{q="范达尔的主要敌人是谁？",a="他的主要对手是霜狼氏族的首领兼长者萨满德雷克塔尔，后者试图将这些矮人闯入者从他们的祖居地清除出去。",al={"范达尔对手","范达尔和谁作战","霜狼领袖"}}},fx={["3cffa9d0"]={q="范达尔·雷矛效忠于哪一方？",a="范达尔·雷矛是一位骄傲的矮人山地之王，为铁炉堡和大联盟奋勇作战。作为雷矛卫队的最高指挥官和奥特兰克山谷远征军的统帅，他指挥联盟的一切军事行动与挖掘工作，对抗霜狼兽人及其部落盟友。",al={"范达尔·雷矛的阵营","范达尔是联盟的吗","范达尔为谁而战"}},["6ebb293f"]={q="范达尔·雷矛想要什么？",a="范达尔一心要让矮人完全统治奥特兰克山谷。他的远征队前来寻找山中的自然资源、祖先历史和泰坦遗物，但霜狼氏族不肯接受他们的主张，因此他的目标是彻底赶走兽人，为联盟夺取整座山谷。",al={"范达尔·雷矛的目标","范达尔想要什么","范达尔·雷矛的职责"}},["36b37a58"]={q="范达尔·雷矛与谁有联系？",a="范达尔是雷矛远征队的首领，也是雷矛卫队的统帅。这支精锐矮人军队直接听命于国王麦格尼·铜须和铁炉堡王国。",al={"范达尔·雷矛的氏族","范达尔·雷矛与谁有关","范达尔·雷矛的关系"}}},fp="17,279,18.548.0,23.519.0,25.174.0,42.222.0,24.142.0,28.163.0"}
P.entries["npc:varimathras"] = {n="瓦里玛萨斯",s="瓦里玛萨斯是一位纳斯雷兹姆种族的恐惧魔王，担任Sylvanas Windrunner的首席副官和军事顾问。在洛丹伦内战中战败后，他被迫向女妖之王效忠，如今站在幽暗城Royal Quarter她身边的位置。",h="瓦里玛萨斯是一位纳斯雷兹姆种族的恐惧魔王，担任Sylvanas Windrunner的首席副官和军事顾问。在洛丹伦内战中战败后，他被迫向女妖之王效忠，如今站在幽暗城Royal Quarter她身边的位置。",kw={"巴纳扎尔","德赛洛克","恐惧魔王","纳斯雷兹姆","royal quarter","sylvanas","幽暗城","瓦里玛萨斯"},ang={["class:Warlock"]="对于恶魔魔法的修行者来说，一位高级纳斯雷兹姆服务于一位凡人亡灵女王的景象，虽然令人不安，却也是一次令人印象深刻的意志压制展示。",["faction:Horde"]="这位恐惧魔王在幽暗城的出现是与奥格瑞玛产生激烈摩擦的根源，因为部落花费了数十年时间才从瓦里玛萨斯曾服务过的恶魔主人手中挣脱出来。",["race:Undead"]="瓦里玛萨斯代表了被遗忘者实用主义的意愿，即利用压迫者的武器来对抗他们自己，他被驯服地站在那位将洛丹伦从他魔爪中解放出来的黑暗女王身边。"},sec={{t="巫妖王的狱卒",b="在第三次战争前，基尔加丹派遣瓦里玛萨斯和他的恐惧魔王同僚前往艾泽拉斯担任巫妖王的狱卒，以确保耐奥祖的灵魂能够服务于燃烧军团的计划。他与他的兄弟德赛洛克和巴纳扎尔被束缚在一起，在阿克蒙德入侵卡利姆多时，他负责监管洛丹伦的天灾军团。当燃烧军团在海加尔山战败时，这三巨头仍然固守在王城的废墟中，完全不知道他们的主子已经覆灭，直到阿尔萨斯王子返回并将他们赶入藏身处。"},{t="恶魔的投降",b="随着巫妖王对其亡灵部队的控制瓦解，瓦里玛萨斯试图强迫新近获得自由的女妖Sylvanas Windrunner服务于恐惧魔王的新政权。Sylvanas拒绝了，并召集获得解放的亡灵摧毁了瓦里玛萨斯的哨所。面对处决，这位恐惧魔王跪地求饶，用战术机密和他兄弟防御工事的情报换取活命。Sylvanas接受了，将他束缚在自己麾下，作为对付他同族的活体武器。"},{t="兄弟相残",b="为了获得Sylvanas的信任，瓦里玛萨斯在征服王城后被命令杀掉他的恐惧魔王同僚巴纳扎尔。他表面上服从了，但巴纳扎尔在这次欺骗中幸存了下来。随后，瓦里玛萨斯在Sylvanas的命令下处决了人类战争领袖大元帅加里索斯。现在他驻扎在Sylvanas的王座旁，协调着整个洛丹伦的军事行动，尽管许多部落成员对这位恶魔盟友深感不安。"}},faq={{q="为什么一个恶魔会为被遗忘者效力？",a="当Sylvanas Windrunner在洛丹伦内战期间召集她那支新近获得解放的亡灵军队时，她击溃了瓦里玛萨斯的部队。面对即将到来的死亡，这位恐惧魔王乞求怜悯，并提出用他的狡诈、军事知识和效忠来换取自己的生命。Sylvanas饶了他一命，将他用作战术家和执行者。",al={"为什么瓦里玛萨斯在幽暗城","为什么恐惧魔王与sylvanas在一起","瓦里玛萨斯的效忠"}},{q="瓦里玛萨斯是什么生物？",a="瓦里玛萨斯是一名纳斯雷兹姆，通常被称为恐惧魔王。纳斯雷兹姆是一个聪明、善于操纵的恶魔种族，效忠于燃烧军团，擅长精神控制、暗影魔法以及散布瘟疫和混乱。",al={"瓦里玛萨斯的种族","瓦里玛萨斯是吸血鬼吗","瓦里玛萨斯的物种"}},{q="瓦里玛萨斯在幽暗城的什么位置？",a="他可以在幽暗城的Royal Quarter高台上找到，就在Sylvanas Windrunner身边，被被遗忘者皇家卫兵所环绕。",al={"瓦里玛萨斯在哪里","瓦里玛萨斯的位置","寻找瓦里玛萨斯"}},{q="瓦里玛萨斯和巴纳扎尔之间发生了什么？",a="在征服王城之后，Sylvanas命令瓦里玛萨斯杀死他的兄弟巴纳扎尔作为忠诚测试，瓦里玛萨斯遵照她的命令反戈对付了他的恐惧魔王同僚。",al={"瓦里玛萨斯杀了巴纳扎尔吗","瓦里玛萨斯的兄弟","恐惧魔王禁忌"}},{q="瓦里玛萨斯在创造天灾军团的过程中扮演了什么角色？",a="在基尔加丹将兽人萨满耐奥祖的灵魂束缚在冰封王座中并将其作为巫妖王投向艾泽拉斯之后，他派遣瓦里玛萨斯和他的恐惧魔王同僚担任其狱卒，并监视天灾军团在洛丹伦的行动。",al={"瓦里玛萨斯与耐奥祖","瓦里玛萨斯与巫妖王的起源"}},{q="其他部落领袖信任瓦里玛萨斯吗？",a="完全不信任。兽人、巨魔和牛头人深受恶魔腐蚀之苦，视恐惧魔王为邪恶的操纵者。即使在被遗忘者中，许多人也将瓦里玛萨斯视为一件被严密控制的危险武器，而非真正的战友。",al={"部落信任瓦里玛萨斯吗","萨尔与瓦里玛萨斯","瓦里玛萨斯值得信任吗"}}},fx={b37d7c5f={q="瓦里玛萨斯效忠于哪一方？",a="表面上，瓦里玛萨斯效忠于希尔瓦娜斯·风行者女士和被遗忘者。第三次战争后，希尔瓦娜斯击败了他的部队，他便乞求饶命并宣誓效忠，甚至协助推翻了自己的恐惧魔王兄弟。然而，他的本性仍是燃烧军团的纳斯雷兹姆。尽管他担任女妖之王的首席顾问，部落中很少有人相信恶魔的忠诚能够真正信赖。",al={"瓦里玛萨斯忠诚吗","瓦里玛萨斯的效忠对象","瓦里玛萨斯效忠于谁"}},["3e1da8be"]={q="瓦里玛萨斯想要什么？",a="瓦里玛萨斯最想要的是生存和影响力。希尔瓦娜斯将他置于掌控之下时，他为了保全自己，心甘情愿地背叛了其他恐惧魔王。他把自己安插在希尔瓦娜斯身边，成为她在幽暗城的副手，从而在洛丹伦掌握极大的权势，同时继续推动敌人的覆灭——他的敌人主要是天灾军团和血色十字军。",al={"瓦里玛萨斯的目标","瓦里玛萨斯想要什么","瓦里玛萨斯的动机"}},e0cdf0b9={q="瓦里玛萨斯为何在幽暗城？",a="瓦里玛萨斯作为希尔瓦娜斯女士的首席副官和首席战术家，陪伴她驻守在幽暗城的皇家区。希尔瓦娜斯击败他后，他便受缚为她效力；他曾协助她征服洛丹伦首都，推翻自己的恐惧魔王同胞迪瑟洛克和巴纳扎尔。如今，他负责协调军事行动、指挥间谍，并在黑暗女王的密切监督下协助管理被遗忘者王国。",al={"瓦里玛萨斯为何在这里","瓦里玛萨斯为何在幽暗城","瓦里玛萨斯在这里做什么"}},["9df47492"]={q="瓦里玛萨斯为何如此令人畏惧？",a="瓦里玛萨斯是一名恐惧魔王，属于狡诈的纳斯雷兹姆一族。基尔加丹派他们监视巫妖王以及天灾军团对艾泽拉斯造成的浩劫。他以高超的操纵术、精神控制和冷酷狡诈闻名，曾与兄弟们统领洛丹伦各地的亡灵军团。如此强大的恶魔竟被迫服侍他人，既令人恐惧地见证了希尔瓦娜斯的力量，也让任何进入幽暗城的人感到不安。",al={"瓦里玛萨斯为何危险","瓦里玛萨斯的声望","瓦里玛萨斯令人畏惧吗"}}},fp="11,309,23.506.0,19.506.0,23.443.1,36.327.0,37.233.0,46.154.0,48.190.0,55.244.0,45.260.0"}
P.entries["npc:varok-saurfang"] = {n="Varok Saurfang",s="萨鲁法尔大王是一位传奇的兽人战士，也是旧部落战争中的老兵。他担任萨尔大酋长在奥格瑞玛受人信赖的军事指挥官，代表着现代部落那引以为傲的尚武脊梁。",h="萨鲁法尔大王是一位传奇的兽人战士，也是旧部落战争中的老兵。他担任萨尔大酋长在奥格瑞玛受人信赖的军事指挥官，代表着现代部落那引以为傲的尚武脊梁。",kw={"库卡隆","大王","萨鲁法尔","萨尔","varok","战士"},ang={["class:Warrior"]="战士们尊崇萨鲁法尔，认为他是无与伦比的老兵，其斧术、战场战术智慧以及坚定的决心定义了理想战士的典范。",["race:Orc"]="对于兽人而言，萨鲁法尔大王既是武力的终极楷模，也是一个令人警醒的提醒，时刻铭记着恶魔之血诅咒所带来的精神创伤。"},sec={{t="活着的战争传奇",b="很少有活着的战士能在武艺上与萨鲁法尔相提并论。作为旧部落战争的幸存者，他在战场上被视为一股势不可挡的力量。如今，他以大王（High Overlord）的身份坐镇奥格瑞玛，是萨尔重建的部落的一道防线。"},{t="鲜血的重担",b="虽然他是部落中首屈一指的勇士，但萨鲁法尔并非一个被鲁莽嗜血冲动所驱使的人。虽然他会为了抵御任何威胁而不懈地捍卫部落并执行萨尔的统治，但萨鲁法尔对好战行为深恶痛绝，他只为荣誉与生存而战。"}},faq={{q="Varok Saurfang是谁？",a="萨鲁法尔大王是一位享有盛誉的兽人战士，也是服务于部落萨尔大酋长的首席军事指挥官。",al={"varok saurfang背景故事","谁是萨鲁法尔","萨鲁法尔大王"}},{q="萨鲁法尔参加过哪些战争？",a="萨鲁法尔是旧部落对抗联盟战争的老兵。今天，他为萨尔的部落而战。",al={"萨鲁法尔战争历史","萨鲁法尔参加过第一次战争吗","萨鲁法尔战斗"}},{q="萨鲁法尔如何看待部落的过去？",a="萨鲁法尔曾在恶魔之血诅咒时期为旧部落效力。如今，他服务于已经远离那条黑暗道路的萨尔的部落。",al={"萨鲁法尔鲜血诅咒","萨鲁法尔为何对过去感到懊悔"}},{q="萨鲁法尔在当今部落中扮演什么角色？",a="他担任萨尔军队的大王，负责监督军队的战备情况，执行大酋长的命令，并作为经验丰富的导师，教导部落中年轻的战士。",al={"萨鲁法尔现在做什么","萨鲁法尔奥格瑞玛职责"}}},fx={["30353091"]={q="Varok Saurfang站在哪一方？",a="Saurfang对萨尔的部落忠心耿耿。他曾参加旧部落的战争，如今毫无保留地支持新部落。他执行大酋长的意志，并全心全意地保护族人。",al={"saurfang属于哪个阵营","saurfang效忠谁","saurfang的忠诚对象"}},["275ad83b"]={q="Varok Saurfang想要什么？",a="Saurfang希望族人能够拥有荣誉与安定。他将为萨尔的部落战斗至死，并努力避免兽人重蹈旧部落的黑暗覆辙。",al={"saurfang想要什么","saurfang的目标","saurfang的动机"}},d09cd640={q="Varok Saurfang与谁关系密切？",a="他是大酋长萨尔最信任的指挥官之一，在奥格瑞玛担任部落大督军。",al={"saurfang的家人","saurfang的兄弟","saurfang与谁有亲属关系"}},["593a9ba3"]={q="Varok Saurfang为何闻名？",a="Saurfang以战场上势不可挡的力量闻名于艾泽拉斯。他曾参加旧部落的战争，凭借无与伦比的武艺和凶猛的战术赢得了极高声望，令敌友都对他敬畏有加。",al={"saurfang为何令人畏惧","saurfang是否有名","saurfang的声望"}}},fp="14,217,27.242.0,23.294.0,22.121.0,32.103.0,40.146.0,45.182.0"}
P.entries["npc:velarok"] = {n="Velarok",s="Velarok Windblade 是一名孤独的人类剑士，他在灼热峡谷的灰烬中扎营，周围是被肢解的黑铁矮人尸体。他因父亲惨遭杀害而寻求向当地的黑铁矮人复仇，并招募过往的旅人来锻造一把复仇之刃。他那对复仇的执着渴望驱使着他向帮助他的人提出一切要求。",h="Velarok Windblade...",kw={"灼热峡谷","瑟银哨塔","惩戒火炬","velarok","velarok windblade"},ang={["race:Dwarf"]="黑铁矮人是铁炉堡的敌人，一个陌生人对他们发出的复仇誓言可能会在铜须矮人中引起共鸣，尽管灼热峡谷中孕育的邪恶远不止黑铁矮人那么简单。",["race:Human"]="Velarok 关于被谋杀的父亲和儿子复仇的故事，利用了许多人类所珍视的孝道和正义复仇的理想。"},sec={{t="儿子的复仇",b="Velarok Windblade 位于瑟银哨塔的东南方，他自称是一名在灼热峡谷险恶荒原中受困的悲伤人类战士。他的营地周围横陈着死于他剑下的黑铁矮人血淋淋的尸体。据 Velarok 所言，这些矮人部族残忍地杀害了他的父亲。他被仇恨所吞噬，招募过往旅人收集材料，以组装惩戒火炬，这是一种用来向黑铁矮人和拉格纳罗斯的爪牙复仇的附魔武器。"},{t="揭开欺诈者的面纱",b="关于被杀害父亲的故事完全是编造的。一旦惩戒火炬被完全组装并充能，人类的幻象便会破碎，暴露出这名角色的真实身份——欺诈者 Velarok，一条狡诈的黑龙军团幼龙。在操纵凡人削弱黑铁矮人以服务于龙群的阴谋后，Velarok 出于戏谑饶过了这些有用的棋子，并通过他的仆从留下了一些微不足道的小饰品，随后展翅飞往黑石山。"}},faq={{q="Velarok 是谁？",a="最初，Velarok Windblade 看起来是一名在灼热峡谷瑟银哨塔东南方露营的复仇心切的人类剑士，试图为父亲的死向黑铁矮人寻求报复。",al={"velarok windblade是谁","velarok的身份","velarok背景故事"}},{q="为什么 Velarok 的周围有死亡的矮人？",a="散布在他营地周围被肢解的黑铁矮人残骸，就是他所说的为了父亲的死而向该部族发动血腥复仇的冷酷证据。",al={"被肢解的黑铁矮人残骸","velarok身边的死亡矮人","velarok营地的尸体"}},{q="什么是惩戒火炬？",a="这是一把以复仇之名，用在灼热峡谷各处收集的稀有材料组装而成的附魔火炬。Velarok 让他的帮手收集碎片，自己进行组合与附魔，然后将成品火炬绑定在帮助过他的人身上。",al={"惩戒火炬任务","什么是惩戒火炬"}},{q="为什么 Velarok 要伪装成人类？",a="伪装成人类使他能够在不引起怀疑的情况下招募联盟和部落的冒险者。黑龙经常使用凡人的伪装来策划针对其敌人的代理人打击，例如拉格纳罗斯的黑铁仆从。",al={"为什么velarok是人类形态","为什么要欺骗玩家","欺诈者velarok伪装"}},{q="Velarok 在暴露身份后去了哪里？",a="在展露其欺诈者 Velarok 的真龙形态后，他便起飞前往黑石山与他的龙群会合，留下他的凡人仆从去奖励协助他的冒险者。",al={"velarok飞往哪里","velarok结局","velarok最后怎么样了"}},{q="Velarok 在伪装解除时会发动攻击吗？",a="不会。Velarok 认为冒险者们这种无意识的服务很有趣且令人满意。他没有消灭他们，而是饶了他们的性命，并允许他们从他的仆从那里获得一些小饰品。",al={"我会与velarok战斗吗","velarok会变得敌对吗"}}},fp="7,383,17.511.0,21.476.2,15.193.2,42.159.2,33.251.1,45.240.2,46.203.2,44.194.2"}
P.entries["npc:velora-nitely"] = {n="维罗拉·奈特雷",s="维罗拉·奈特雷是一位居住在幽暗城Trade Quarter的亡灵护甲匠。在王国陷落前，她曾是洛丹伦最杰出的铁匠之一，如今她将自己冰冷的技艺贡献给了被遗忘者和部落。尽管存在形式阴郁，但她仍会尝试讲一些干巴巴、面无表情的冷笑话，不过这些笑话很少能起到应有的效果。",h="维罗拉·奈特雷是一位居住在幽暗城Trade...",kw={"护甲匠","野蛮腿甲","龙喉胫骨","洛丹伦","thun'grim firegaze","trade quarter","幽暗城","维罗拉·奈特雷"},ang={["class:Warrior"]="寻求传说中的野蛮护甲的部落勇士会被指引前往北方的幽暗城寻找维罗拉，利用龙喉兽人的骨头来锻造坚固的腿甲。",["profession:Blacksmithing"]="维罗拉代表了洛丹伦传奇护甲锻造传统的延续，即便在成为亡灵后，她依然保持着精湛的冶金技艺。"},sec={{t="洛丹伦的铁匠",b="在第三次战争摧毁北方之前，维罗拉·奈特雷就已是洛丹伦闻名遐迩的顶级护甲匠。虽然亡灵化剥夺了她的生命和体温，但却丝毫未减损她的专业技艺。如今，她驻守在幽暗城Trade Quarter的铁砧旁，与包括贫瘠之地的Thun'grim Firegaze在内的部落工匠跨越大陆进行合作。她的专长包括加固重型战甲，其中最著名的便是利用龙喉氏族的胫骨等坚硬材料锻造的野蛮腿甲。"},{t="面无表情的幽默",b="与许多对自己诅咒般的命运感到郁郁寡欢的被遗忘者同胞不同，维罗拉依然保持着对快乐的追求。不幸的是，死亡似乎彻底毁掉了她的喜剧节奏。她的俏皮话无论对生者还是死者来说都显得平淡、病态且毫无笑点，尽管如此，她在打铁时依然乐此不疲地讲着这些笑话。"}},faq={{q="维罗拉·奈特雷是谁？",a="维罗拉·奈特雷是一位被遗忘者护甲匠，位于幽暗城的Trade Quarter。生前，她就因其卓越的金属锻造技艺而在整个洛丹伦王国享有盛誉。",al={"维罗拉·奈特雷背景故事","维罗拉是谁","维罗拉·奈特雷npc"}},{q="维罗拉·奈特雷在哪里？",a="她位于幽暗城，在繁忙的Trade Quarter里靠近熔炉和护甲架的地方工作。",al={"维罗拉·奈特雷位置","维罗拉·奈特雷在哪里","维罗拉·奈特雷地图"}},{q="她与Thun'grim Firegaze有什么联系？",a="维罗拉是受命协助贫瘠之地的兽人护甲匠Thun'grim Firegaze的专业部落铁匠之一。她为那些带来龙喉氏族胫骨的有潜力的勇士锻造野蛮腿甲。",al={"维罗拉与thun'grim","thun'grim firegaze护甲","野蛮护甲任务线"}},{q="为什么她的笑话那么冷？",a="维罗拉喜欢尝试幽默，但死亡对她的表达能力造成了损害。她在死亡并转生为亡灵时失去了正常的幽默感，导致她的笑话显得尴尬、面无表情，而且很少好笑。",al={"维罗拉的幽默感","维罗拉的笑话","为什么维罗拉讲笑话"}}},fx={af55a704={q="维罗拉·奈特雷站在哪一方？",a="维罗拉效忠被遗忘者与部落。她驻守在幽暗城，运用出众的金属加工技艺为部落战士效力，并与远在海外的部落工匠合作，为部落的勇士锻造强大的装备。",al={"维罗拉·奈特雷属于哪个阵营","维罗拉·奈特雷效忠谁","维罗拉·奈特雷属于部落还是联盟"}},["71b2c071"]={q="维罗拉·奈特雷想要什么？",a="维罗拉在寻找配得上她精湛技艺的稀有材料，尤其是湿地的龙喉胫骨，用以锻造强大的野蛮腿甲。她也喜欢试着给访客讲笑话，尽管亡灵之躯让她讲笑话的方式显得颇为干巴、平淡。",al={"维罗拉想要什么","维罗拉·奈特雷的目标","维罗拉·奈特雷需要什么"}},dd304cfc={q="维罗拉·奈特雷为何身在幽暗城？",a="维罗拉曾是洛丹伦的居民，后来被转化为亡灵，并在Sylvanas Windrunner的被遗忘者中找到了归属。她在幽暗城的Trade Quarter施展技艺，锻造护甲，帮助寻求她传奇锻造技艺的旅人。",al={"维罗拉·奈特雷为何在此","维罗拉为何在幽暗城","维罗拉·奈特雷与trade quarter"}},["97d7ef33"]={q="维罗拉·奈特雷为何闻名？",a="生前，维罗拉就以洛丹伦最优秀的护甲匠之一而闻名。即使成为亡灵，她精制板甲的声誉依旧不减，Thun'grim Firegaze等铁匠也会指引有潜力的勇士前来寻求她的传奇手艺。",al={"维罗拉是否有名","维罗拉·奈特雷的声望","维罗拉·奈特雷为何闻名"}}},fp="13,314,20.520.0,13.346.0,21.188.0,33.108.0,45.205.0,25.196.0"}
P.entries["npc:ventaari-brightwish"] = {n="Ventaari Brightwish",s="Ventaari Brightwish是泽风岛森达尔村的一名天裔居民。她迎接来自艾泽拉斯各地的旅行者，并提供任务“The Gift of Skysight”。",h="Ventaari Brightwish是泽风岛森达尔村的一名天裔居民。她迎接来自艾泽拉斯各地的旅行者，并提供任务“The Gift of Skysight”。",kw={"brightwish","天裔","skysight","森达尔村","ventaari","泽风岛"},ang={["race:Skyborne"]="作为森达尔村天裔的一员，Ventaari Brightwish帮助访客与泽风岛的文化和习俗建立联系。"},sec={{t="森达尔村的居民",b="Ventaari Brightwish居住在泽风岛高耸悬崖上的森达尔村，是当地的天裔之一。虽然她与Belathaan Brightwish同姓，但她的职责主要在于协助来到村庄的新来者，无论联盟还是部落，她都会向他们表示欢迎，并通过像“The Gift of Skysight”这样的任务引导访客了解她族人的传统。"}},faq={{q="Ventaari Brightwish是谁？",a="Ventaari Brightwish是一名驻扎在泽风岛森达尔村的天裔NPC。她与访客互动并提供任务“The Gift of Skysight”。",al={"ventaari","ventaari是谁","ventaari brightwish"}},{q="我在哪里可以找到Ventaari Brightwish？",a="她位于泽风岛上的森达尔村。",al={"ventaari位置","ventaari在哪里","森达尔村 ventaari"}},{q="Ventaari对部落或联盟怀有敌意吗？",a="不。Ventaari Brightwish是中立的，愿意与来自联盟和部落的冒险者交谈。",al={"ventaari阵营","ventaari友好吗","部落可以和ventaari交谈吗"}}},fp="19,162,28.411.0,27.154.0,37.75.0,45.104.0"}
P.entries["npc:verdan-the-everliving"] = {n="永生者沃尔丹",s="永生者沃尔丹是一头潜伏在哀嚎洞穴翠绿隧道深处的巨大沼泽兽。他居住在沉睡的德鲁伊纳拉雷克斯所散发的梦魇之中，与堕落的尖牙德鲁伊为伍，并会暴力攻击任何闯入他那潮湿洞穴的人。",h="永生者沃尔丹是一头潜伏在哀嚎洞穴翠绿隧道深处的巨大沼泽兽。他居住在沉睡的德鲁伊纳拉雷克斯所散发的梦魇之中，与堕落的尖牙德鲁伊为伍，并会暴力攻击任何闯入他那潮湿洞穴的人。",kw={"沼泽兽","尖牙德鲁伊","元素生物","永生者","纳拉雷克斯","梦魇","沃尔丹","哀嚎洞穴"},ang={["class:Druid"]="沃尔丹的巢穴是一个残酷的提醒，展示了当翡翠梦境转变为梦魇时，洞穴中会生长出什么东西。",["class:Shaman"]="作为一种因扭曲而变得狂暴的土水元素之灵，击败沃尔丹是恢复贫瘠之地破碎元素平衡的一种行为。",["faction:Horde"]="由于哀嚎洞穴位于贫瘠之地的中心，击败像沃尔丹这样危险的野兽对于保护附近的十字路口和定居点至关重要。"},sec={{t="茂密深渊之兽",b="沃尔丹是一头庞大的沼泽兽，一种由植被、淤泥和泥沼构成的元素生物，潜伏在哀嚎洞穴杂草丛生的深处。在洞穴陷入堕落之前，关于他的资料一无所知；他仅仅是那些郁郁葱葱、洪水泛滥的洞穴中体型最大、最危险的生物。"},{t="被梦魇扭曲",b="当纳拉雷克斯试图将干旱的贫瘠之地培育为茂密的天堂时，他的仪式在翡翠梦境中破裂，化作了一场生动的梦魇。由此产生的腐蚀透过地下水蔓延开来，污染了洞穴内的一切生物。在那场灾祸中，沃尔丹作为一头巨大而充满敌意的蛮兽，在与疯狂的尖牙德鲁伊共享的深处游荡。"}},faq={{q="沃尔丹是什么生物？",a="沃尔丹是一头巨大的沼泽兽，是由植物、泥炭和地下淤泥构成的元素生物。",al={"沃尔丹怪物类型","沃尔丹是什么","沃尔丹种族"}},{q="为什么沃尔丹对冒险者充满敌意？",a="沃尔丹潜伏在哀嚎洞穴被梦魇污染的深处，沉睡的纳拉雷克斯的梦境让这里的一切都变得充满敌意。他将所有外来的入侵者视为必须粉碎的闯入者。",al={"为什么沃尔丹会攻击","沃尔丹敌对状态","沃尔丹是邪恶的吗"}},{q="沃尔丹与尖牙德鲁伊有什么联系？",a="沃尔丹与疯狂的尖牙德鲁伊共享着这片被梦魇污染的洞穴，他对入侵者同样充满敌意，守护着洞穴更深处的区域。",al={"沃尔丹与尖牙德鲁伊","沃尔丹与尖牙的关系"}},{q="沃尔丹在哀嚎洞穴的什么位置？",a="沃尔丹居住在哀嚎洞穴蜿蜒小径深处的一个布满苔藓的洞穴密室中，穿过几位堕落的尖牙德鲁伊首领即可到达。",al={"沃尔丹在哪里","沃尔丹位置","如何找到沃尔丹"}},{q="沃尔丹可以被治愈或净化吗？",a="目前没有已知的方法可以净化沃尔丹，冒险者别无选择，只能消灭这头庞大的野兽，以确保能安全通过洞穴。",al={"沃尔丹可以被拯救吗","拯救沃尔丹","净化沃尔丹"}},{q="为什么沃尔丹被称为“永生者”？",a="他这个称号的起源不得而知。沃尔丹是哀嚎洞穴郁郁葱葱、杂草丛生的深处的一头沼泽兽。",al={"为什么叫永生者","永生者的含义","沃尔丹名字起源"}}},fx={["429fb6d1"]={q="永生者沃尔丹是谁？",a="永生者沃尔丹是一头庞大的沼泽野兽，由植物与泥沼构成的元素生物，潜伏在哀嚎洞穴杂草丛生的深处。他栖居于沉睡的德鲁伊纳拉雷克斯所散播的噩梦之中，会凶猛地攻击任何闯入其领地的生物。",al={"沃尔丹是谁","永生者沃尔丹","沃尔丹是什么"}},["58b439d8"]={q="永生者沃尔丹站在哪一方？",a="沃尔丹不效忠任何阵营。他潜伏在被噩梦污染的深处，与堕落的尖牙德鲁伊为伍，对任何试图打扰洞穴或唤醒纳拉雷克斯的外来者都怀有同样的敌意。",al={"沃尔丹属于哪个阵营","沃尔丹是否与德鲁伊为伍","沃尔丹效忠谁"}},["06330139"]={q="永生者沃尔丹想要什么？",a="沃尔丹没有宏图大志，只会守卫领地并毁灭入侵者。他在洞穴深处永不停歇地巡守，只想粉碎任何胆敢接近巢穴的闯入者。",al={"沃尔丹的目标","沃尔丹想要什么","沃尔丹的动机"}},b1009155={q="永生者沃尔丹为何身在此处？",a="沃尔丹栖居在哀嚎洞穴葱郁而杂草丛生的深处。沉睡的德鲁伊纳拉雷克斯所带来的噩梦已使洞穴变得危机四伏。关于他在受到腐化之前的经历，一无所知。",al={"沃尔丹为何在哀嚎洞穴","沃尔丹如何来到这里","沃尔丹在此处的起源"}},["357d8159"]={q="永生者沃尔丹为何令人畏惧？",a="沃尔丹是哀嚎洞穴中最为凶残的怪物，令人闻风丧胆。他体型庞大，拥有植物般的强悍力量，几秒之内就能重创并击碎一名身披铠甲的战士。",al={"沃尔丹为何令人畏惧","沃尔丹危险吗","沃尔丹有多强"}}},fp="21,286,24.282.0,24.367.1,32.108.0,37.203.0,54.159.0,47.137.0,32.146.0,39.107.0"}
P.entries["npc:verna-furlbrow"] = {n="弗娜·法布隆",s="弗娜·法布隆是一位被迫流离失所的农夫，目前正困在西部荒野北部边界附近的一辆破旧马车旁。在土匪占领了她家的南瓜田后，她和丈夫试图逃往艾尔文森林，却发现自己被困在了危险的荒野大路上。",h="弗娜·法布隆是一位被迫流离失所的农夫，目前正困在西部荒野北部边界附近的一辆破旧马车旁。在土匪占领了她家的南瓜田后，她和丈夫试图逃往艾尔文森林，却发现自己被困在了危险的荒野大路上。",kw={"损坏的马车","法布隆","贾森农场","老blanchy","难民","西奥多·法布隆","弗娜·法布隆","西部荒野炖肉"},ang={["faction:Alliance"]="受困的法布隆一家是暴风城忽视边境所带来的人道代价的缩影，普通的市民被赶出家园，却没有任何皇家士兵前往保护他们。",["profession:Cooking"]="弗娜是标志性菜肴——西部荒野炖肉的创造者，她教会了初出茅庐的边境厨师如何将搜集到的肉类和野生作物变成充饥的佳肴。"},sec={{t="一连串的不幸",b="弗娜和她的丈夫曾经在西部荒野北部经营着自己的南瓜农场，但席卷乡村的日益猖獗的混乱局势将他们赶了出来。当不法之徒占领了他们的土地时，这对夫妇把能带上的财物都堆到了车上，并套上了他们忠实的马儿——老Blanchy，准备逃往安全的艾尔文森林。不幸的是，他们的马车在距离废弃的贾森农场不远的路边抛锚了。由于无法修理车轴或继续前行，弗娜不得不忍受恶劣的天气、土匪的袭击和拾荒者的骚扰，同时还要依靠过往的冒险者来维持生计并保卫家园。"},{t="炉火之心",b="尽管被迫栖身于路边，弗娜依然保持着热情和足智多谋的精神。作为“西部荒野炖肉”的创造者，她名扬四方，经常与有着相同遭遇的流浪者和难民分享食物和温暖的篝火。她依靠路过的游民在野外搜寻食材——比如野猪獠牙、鱼人眼睛、秋葵和多筋的秃鹫肉——来填满她的炖锅，将这严酷边境出产的一切转化为供穷人饱腹的丰盛餐点。"}},faq={{q="为什么弗娜·法布隆在路边露营？",a="在不法之徒占领了西部荒野北部后，弗娜和她的丈夫逃离了他们的南瓜农场。当他们前往艾尔文森林寻求避难时，他们的马车在贾森农场附近抛锚了，导致他们被困在路边。",al={"弗娜·法布隆为什么在这里","弗娜·法布隆位置","弗娜发生了什么事"}},{q="农夫法布隆与她是什么关系？",a="农夫西奥多·法布隆是弗娜的丈夫。他们曾一起经营着西部荒野的家园，直到土匪强迫他们离开了土地。",al={"弗娜·法布隆的丈夫","农夫法布隆是她的丈夫吗"}},{q="什么是西部荒野炖肉？",a="西部荒野炖肉是弗娜发明的一种边境地区特色菜肴。她用野猪獠牙、多筋的秃鹫肉、鱼人眼睛以及从邻近废弃农场收集的秋葵烹制而成，用来维持那些受困难民的生计。",al={"西部荒野炖肉任务","弗娜·法布隆的炖肉","弗娜烹饪什么"}},{q="法布隆一家的农场发生了什么事？",a="法布隆夫妇在西部荒野北部拥有一座南瓜农场，但在王国最近治安恶化的过程中，有组织的土匪将他们赶出了这片土地，迫使他们放弃了家园和农田。",al={"法布隆南瓜农场","法布隆农场发生了什么"}}},fx={c5a3789f={q="弗娜·法布隆是谁？",a="弗娜·法布隆是西部荒野一位朴实的农户，也是农夫西奥多·法布隆的妻子。她以美味的西部荒野炖肉和慷慨热忱闻名乡间。她与丈夫曾在西部荒野北部经营一片南瓜地，直到暴乱摧毁了他们的生计。如今，她流离失所，滞留在路边，尽管厄运接连不断，仍努力让大家打起精神。",al={"弗娜·法布隆是谁","弗娜·法布隆的身份","弗娜·法布隆的故事"}},b45ce146={q="弗娜·法布隆站在哪一方？",a="弗娜忠于暴风城王国，坚定地支持联盟。和西部荒野的许多普通百姓一样，她对那些将这片省份搅得支离破碎的歹徒毫无好感，只盼望和平、安全，以及一个逃离乡间无法无天局面的机会。",al={"弗娜·法布隆属于哪个阵营","弗娜·法布隆是否支持联盟","弗娜·法布隆站在哪一方"}},["0d4268c1"]={q="弗娜·法布隆想要什么？",a="弗娜只想养活家人，并平安离开西部荒野。他们失去了农场后，原本打算前往艾尔文森林避难，但马车损坏，加上马匹饥饿疲惫，让他们寸步难行。眼下，她只想找些补给，比如炖肉的食材和喂给老马Blanchy的燕麦，好在路边撑下去。",al={"弗娜·法布隆想要什么","弗娜·法布隆的目标","为何帮助弗娜·法布隆"}}},fp="14,288,23.640.0,19.534.0,44.223.0,30.132.0,22.216.0,37.200.0"}
P.entries["npc:verner-osgood"] = {n="弗纳·奥斯古",s="弗纳·奥斯古是湖畔镇的常驻铁匠，他的铁匠铺就设在镇外。他需要在满足当地平民贸易需求和暴风城军队沉重物资要求之间寻找平衡，在豺狼人持续不断的袭击中，他不知疲倦地工作，以确保马匹有蹄铁，保卫者有武器。",h="弗纳·奥斯古是湖畔镇的常驻铁匠，他的铁匠铺就设在镇外。他需要在满足当地平民贸易需求和暴风城军队沉重物资要求之间寻找平衡，在豺狼人持续不断的袭击中，他不知疲倦地工作，以确保马匹有蹄铁，保卫者有武器。",kw={"铁匠","豺狼人","马匹","湖畔镇","所罗门镇长","赤脊山","弗纳·奥斯古","咆哮者"},ang={["faction:Alliance"]="像湖畔镇这样的城镇依赖于像弗纳这样的当地工匠才能生存，因为暴风城的军事援助依然受到危险的限制。",["profession:Blacksmithing"]="弗纳体现了农村铁匠业残酷的现实，在平民的钉掌工作与驻军防御要求的严苛配额之间艰难平衡。",["race:Human"]="奥斯古代表了暴风王国普通民众坚韧不拔的精神，在豺狼人和物资短缺的双重压力下坚守阵地。"},sec={{t="湖畔镇的铁砧",b="弗纳·奥斯古站在湖畔镇中心的熔炉旁，代表着赤脊山吃紧的工业支柱。弗纳的任务是制造像当地坐骑用的蹄铁等基本补给品，但他发现自己的存货不断被征用，用于为暴风城卫兵制造武器和盔甲。随着王国边境的吃紧和当地驻军补给的匮乏，像弗纳这样的独立铁匠必须承担起王国防御的后勤重担。"},{t="豺狼人之灾",b="弗纳的麻烦远不止铁料短缺。盘踞在赤脊山丘的豺狼人经常伏击牲畜，只要工作马匹一旦离开镇子边缘，就会被它们抢走。由于生计被毁而感到愤怒，弗纳积极招募路过的冒险者去扑杀那些掠夺成性的豺狼人族群，并猎杀它们凶残的首领——咆哮者。"}},faq={{q="弗纳·奥斯古是谁？",a="弗纳·奥斯古是湖畔镇的当地铁匠，经营着镇上的熔炉。他负责镇上的金属加工和马匹钉掌工作，同时还要试图满足当地驻军沉重的装备需求。",al={"弗纳·奥斯古","湖畔镇铁匠","弗纳是谁"}},{q="为什么弗纳的蹄铁和铁料不足？",a="镇上的铁料储备不断被征用，用于为驻扎在赤脊山的暴风城卫兵锻造武器和盔甲，导致弗纳剩下的金属勉强只够维护当地马匹。",al={"弗纳缺铁","蹄铁价格任务背景","为什么没有蹄铁"}},{q="弗纳和豺狼人有什么问题？",a="豺狼人掠夺小队在湖畔镇附近游荡，一旦弗纳的马匹离开镇子就会被它们抓走。他雇佣冒险者消灭这些野兽，以此寻求报复和安全。",al={"弗纳的豺狼人问题","为什么弗纳痛恨豺狼人"}},{q="咆哮者是谁，为什么弗纳想让他死？",a="咆哮者是山中当地豺狼人族群的威胁性首领。弗纳想要杀掉他，以破坏那些恐吓城镇并屠杀他马匹的掠夺者们的组织能力。",al={"咆哮者是谁","弗纳的咆哮者任务"}},{q="弗纳与所罗门镇长有什么联系？",a="弗纳在湖畔镇所罗门镇长的市政权力下工作，在平民手艺与镇长疲于奔命的行政管理所要求的市政和军事需求之间保持平衡。",al={"弗纳与所罗门镇长","弗纳与镇政府"}},{q="弗纳在暴风城有亲人吗？",a="他与暴风王国的其他几位商人，如多纳尔·奥斯古和巴塞尔·奥斯古有着相同的姓氏，这表明在该地区有一个建立已久的工人阶级人类工匠血统。",al={"弗纳的亲戚","奥斯古家族"}}},fx={["55e99553"]={q="弗纳·奥斯古站在哪一方？",a="弗纳坚定地效忠联盟和湖畔镇。作为镇上的铁匠，他投入大量铁料和心力，为当地驻军打造装备，并为暴风城军队提供补给，即便这导致自家店铺原料短缺也在所不惜。",al={"弗纳是否效忠联盟","弗纳·奥斯古效忠谁","弗纳·奥斯古属于哪个阵营"}},["238f7baf"]={q="弗纳·奥斯古想要什么？",a="弗纳想保护湖畔镇，并维持自己的铁匠铺运转。他眼下最要紧的是确保有足够的铁料为马匹钉蹄铁，补充工坊耗尽的资源，并剿灭周边的豺狼人群，阻止它们屠杀牲畜、威胁镇民。",al={"弗纳·奥斯古的目标","弗纳需要什么","弗纳·奥斯古的动机"}},["2b67bbb2"]={q="弗纳·奥斯古为何身在湖畔镇？",a="弗纳在湖畔镇生活和工作，是镇上的铁匠。他在湖边打理铁匠铺，为当地守军锻造装备、为役畜配备鞍具，并努力维持正常贸易，尽管威胁不断逼近赤脊山。",al={"弗纳为何在此","弗纳·奥斯古的位置","弗纳为何在赤脊山"}}},fp="13,267,22.470.0,18.385.0,21.199.0,41.198.0,46.199.0,48.185.0,50.193.0,37.195.0"}
P.entries["npc:veron-amberstill"] = {n="维隆·冻石",s="维隆·冻石是一位居住在丹莫罗东部冻石农场的矮人公羊饲养员。他照料着那些作为铁炉堡传统坐骑的坚韧山羊，并将它们提供给赢得了他信任的熟练骑手。",h="维隆·冻石是一位居住在丹莫罗东部冻石农场的矮人公羊饲养员。他照料着那些作为铁炉堡传统坐骑的坚韧山羊，并将它们提供给赢得了他信任的熟练骑手。",kw={"冻石农场","丹莫罗","铁炉堡","坐骑商人","山羊","公羊商人","维隆·冻石"},ang={["faction:Alliance"]="铁炉堡的盟友如果想要掌握骑乘山羊的技巧，必须首先证明自己对矮人王国的贡献，以赢得维隆的尊重。",["race:Dwarf"]="维隆代表了你们种族与山地野兽的深厚渊源，他提供的普通和迅捷山羊是每位矮人冒险者在卡兹莫丹旅行时的可靠伙伴。"},sec={{t="坐骑大师",b="维隆·冻石隐居在丹莫罗东部白雪皑皑的山丘之中，照料着冻石农场声名远扬的牲畜。山羊非常适合卡兹莫丹险峻的山坡，它们脚步稳健，皮毛厚实，足以抵御山地暴风雪的侵袭。维隆负责饲养和训练这些野兽，供矮人侦察兵、山地探险者和旅行冒险者骑乘。虽然他很乐意为矮人同胞提供普通和迅捷的坐骑，但外族人必须先证明自己对铁炉堡王权的坚定忠诚，他才会舍得割爱出让他珍视的畜群。"}},faq={{q="维隆·冻石是谁？",a="维隆·冻石是一位矮人坐骑饲养员和商人，位于丹莫罗的冻石农场。他为铁炉堡王国培育健壮的山羊，并将其出售给有资格的骑手。",al={"维隆·冻石","维隆是谁","冻石农场公羊商人"}},{q="非矮人种族可以从维隆那里购买山羊吗？",a="可以，但前提是他们必须在铁炉堡获得崇拜声望。矮人可以直接购买他的山羊，但外族人必须证明自己是这座山中王国的坚定捍卫者，维隆才会将他的坐骑托付给他们。",al={"人类可以买山羊吗","非矮人公羊坐骑","铁炉堡声望坐骑"}},{q="维隆·冻石在哪里？",a="你可以在丹莫罗东部的山丘中，即古博拉采掘场北面的冻石农场外找到他。",al={"维隆位置","维隆在哪里","去哪里找维隆·冻石"}},{q="为什么矮人骑山羊而不是马？",a="山羊拥有厚实的皮毛、健壮的骨骼和超凡的平衡感，比起普通的马匹，它们远更适合在丹莫罗及其周边山峰那凛冽的寒风和陡峭的岩石崖壁上行走。",al={"为什么矮人骑山羊","矮人坐骑背景故事","山羊坐骑背景故事"}}},fx={["601a0646"]={q="维隆·冻石站在哪一方？",a="维隆·冻石坚定地效忠矮人王国铁炉堡和大联盟。他照料着山羊——矮人引以为傲的坐骑——并为族人以及在铁炉堡声望崇高、值得信赖的联盟盟友提供可靠的坐骑。",al={"维隆·冻石属于哪个阵营","维隆·冻石是否支持联盟","维隆·冻石效忠谁"}},b4666b3f={q="维隆·冻石为什么在这里？",a="维隆·冻石管理着坐落于丹莫罗凛冽山丘中的冻石农场。寒冷多岩的地形为饲养强壮坚韧的山羊提供了理想条件，使农场成为繁育和训练这些标志性矮人坐骑的中心。",al={"维隆·冻石为什么在丹莫罗","维隆·冻石所在位置的原因","冻石农场的用途"}},["8bafbe3f"]={q="维隆·冻石想要什么？",a="维隆·冻石想保护自己的生计，并维持农场珍贵的山羊群。他专注于繁育、饲养和保护羊群，使其免受丹莫罗雪岭上潜伏的危险侵扰，并为值得信赖的骑手提供坚实可靠的坐骑。",al={"维隆·冻石的目标","维隆想要什么","维隆·冻石的目的"}},["921d6dac"]={q="维隆·冻石与谁有关？",a="维隆与冻石家族以及以其家族命名的农场关系密切。他和农场里的亲族共同管理山羊的照料与繁育；数代以来，这些山羊一直为丹莫罗的矮人效力。",al={"维隆·冻石的家族","维隆与谁有亲缘关系","冻石家族"}}},fp="16,241,20.563.0,24.193.0,41.228.0,34.139.0,43.213.0"}
P.entries["npc:veronica-nials"] = {n="Veronica Nials",s="尼艾丝队长是驻扎在阿拉希高地避难谷地的激流堡军队的一名军官。在王国分崩离析之际，她负责协调针对占领了这座陷落首都的辛迪加和食人魔的防御行动。",h="尼艾丝队长是驻扎在阿拉希高地避难谷地的激流堡军队的一名军官。在王国分崩离析之际，她负责协调针对占领了这座陷落首都的辛迪加和食人魔的防御行动。",kw={"阿拉希高地","法尔肯克雷斯特","玛雷兹·考尔","避难谷地","激流堡","辛迪加","萨多尔大桥","veronica nials"},ang={["faction:Alliance"]="尼艾丝队长代表了北方联盟悲剧性的现实：支离破碎、孤立无援的王国为了基本的生存而挣扎，无法为邻近的盟友提供有效的援助。",["race:Human"]="对于人类而言，尼艾丝是激流堡不屈尚武精神的象征，即使面对毁灭性的劣势，也拒绝放弃阿拉索的祖地。"},sec={{t="破碎王国的捍卫者",b="第三次战争后，人类王国激流堡四分五裂，残部在巨石食人魔的入侵和辛迪加的背叛中挣扎求生。尼艾丝队长是避难谷地幸存的激流堡守军的核心指挥官之一。她肩负着坚守防线的重任，指挥联盟勇士对抗包括法尔肯克雷斯特领主和术士玛雷兹·考尔在内的辛迪加关键首领，同时也努力寻回阵亡士兵的徽章，以便给悲痛的家属一个交代。"},{t="被拒绝的请求",b="尼艾丝队长的忠诚仅限于她饱经风霜的祖国。当拉格·加玛森和丹莫德的矮人守军在黑铁矮人破坏了萨多尔大桥后恳求激流堡的援助时，尼艾丝被迫拒绝了他们。受荣誉和职责所限，在他们自己的祖国依然被占领的情况下，她的部队无法向阿拉希高地之外派出哪怕一兵一卒。"}},faq={{q="尼艾丝是谁？",a="尼艾丝是激流堡军队的一名人类队长。她驻扎在避难谷地，指挥针对占领阿拉希高地的辛迪加渗透者和食人魔的军事抵抗。",al={"尼艾丝是谁","尼艾丝队长","避难谷地队长"}},{q="为什么尼艾丝队长不帮助丹莫德和萨多尔大桥？",a="尽管坚守萨多尔大桥的矮人们急需援军来对抗黑铁氏族，但尼艾丝抽不出任何士兵。激流堡正处于彻底毁灭的边缘，职责要求她的部队必须全神贯注于收复他们自己沦陷的王国。",al={"萨多尔大桥的请求","为何不帮助矮人","向联盟求援任务"}},{q="尼艾丝如何处理激流堡徽章？",a="辛迪加会对从被屠杀的士兵身上搜刮来的激流堡徽章进行悬赏。尼艾丝请求联盟冒险者从辛迪加恶棍手中取回这些被窃的徽章，以便她确认死者身份并通知阵亡守军的家属。",al={"激流堡徽章","为何收集徽章","徽章任务"}}},fx={c41e517e={q="Veronica Nials站在哪一方？",a="尼艾丝队长坚定地支持激流堡王国和联盟。作为激流堡军队的一名军官，她首先效忠于自己的人民和祖先的故土，在避难谷地坚守阵地，抵御不断涌入阿拉希高地的众多敌人。",al={"veronica nials的阵营","veronica nials效忠于谁","尼艾丝的忠诚对象"}},["558769df"]={q="尼艾丝队长想要什么？",a="尼艾丝队长致力于从占据激流堡的敌对势力手中收复这座沦陷的王国。她指挥军事行动，对抗夺取首都的石拳食人魔和迪菲亚兄弟会的盗匪，同时收集阵亡激流堡民兵的徽章，以便通知他们悲痛的家人。",al={"veronica nials的目标","尼艾丝队长想要什么","尼艾丝的目标"}}},fp="14,246,26.543.0,13.396.0,22.199.0,59.284.0,42.247.0"}
P.entries["npc:vesprystus"] = {n="维斯派塔斯",s="维斯派塔斯是驻扎在泰达希尔底部的鲁瑟兰村码头的暗夜精灵飞行管理员。他负责管理一群训练有素的角鹰兽，这些角鹰兽负责运送旅客往返于伟大的世界之树和卡利姆多大陆之间。",h="维斯派塔斯是驻扎在泰达希尔底部的鲁瑟兰村码头的暗夜精灵飞行管理员。他负责管理一群训练有素的角鹰兽，这些角鹰兽负责运送旅客往返于伟大的世界之树和卡利姆多大陆之间。",kw={"奥伯丁","黑海岸","飞行管理员","角鹰兽管理员","鲁瑟兰村","泰达希尔","维斯派塔斯"},ang={["faction:Alliance"]="维斯派塔斯是任何抵达泰达希尔码头并需要快速前往黑海岸的联盟旅行者的重要交通枢纽。",["race:NightElf"]="对于第一次离开泰达希尔的年轻暗夜精灵冒险者来说，维斯派塔斯通常就是那个送他们翱翔天际，让他们第一次瞥见卡利姆多大陆风貌的驯兽师。"},sec={{t="鲁瑟兰栖息地守护者",b="维斯派塔斯盘踞在泰达希尔南部的鲁瑟兰村，照料着那些将与世隔绝的精灵枝桠与世界其他地方连接起来的角鹰兽。虽然一个魔法传送门直接将鲁瑟兰与上方的树冠之城达纳苏斯相连，但角鹰兽飞行提供了前往黑海岸和大陆的快捷通道。维斯派塔斯与海峡对岸奥伯丁的飞行管理员协同工作，确保哨兵、特使和前往卡利姆多的冒险者能够安全通行。"}},faq={{q="维斯派塔斯将旅客带往何处？",a="维斯派塔斯将鲁瑟兰村与海峡对岸的黑海岸港口奥伯丁直接相连。从奥伯丁出发，旅客可以搭乘连接的角鹰兽航线向南前往灰谷以及卡利姆多各地的其他暗夜精灵飞地。",al={"他能带我去哪里","维斯派塔斯的飞行路径","鲁瑟兰飞行航线"}},{q="维斯派塔斯照料什么生物？",a="他管理着一群忠诚的暗夜精灵角鹰兽，这是卡利姆多北部特有的古老有翼野兽。暗夜精灵世代饲养并与角鹰兽结下羁绊，利用它们在森林树冠和崎岖的海岸线上穿行。",al={"他有什么坐骑","维斯派塔斯的动物","他驾驶什么飞行"}},{q="从维斯派塔斯所在的位置如何前往达纳苏斯？",a="你不需要搭乘飞行坐骑就能从鲁瑟兰村到达达纳苏斯。维斯派塔斯的栖息地旁边的小径上就矗立着一个闪烁着粉色光芒的传送门，可以将旅客瞬间传送到上方的城市树冠。",al={"如何从维斯派塔斯前往达纳苏斯","维斯派塔斯去达纳苏斯","去达纳苏斯的路径"}}},fx={e8883b50={q="维斯派塔斯是谁？",a="维斯派塔斯是一名暗夜精灵角鹰兽管理员，驻扎在泰达希尔山脚下的鲁瑟兰村。他负责管理栖巢，为往返于上方达纳苏斯的参天树枝与卡利姆多北部沿海定居点的旅客提供可靠的空中运输。",al={"维斯派塔斯是谁","维斯派塔斯暗夜精灵","维斯派塔斯的背景"}},f70b999e={q="维斯派塔斯站在哪一方？",a="他忠于达纳苏斯和联盟。他的栖巢为暗夜精灵哨兵、德鲁伊以及来访的盟友提供服务，帮助他们安全、迅速地进出泰达希尔。",al={"维斯派塔斯与联盟","维斯派塔斯的阵营","维斯派塔斯效忠于谁"}},["433ae265"]={q="维斯派塔斯为什么在这里？",a="鲁瑟兰村是泰达希尔重要的港口和抵达点。由于世界之树从海洋中陡然升起，无法通过陆路前往。维斯派塔斯留在这里照料栖巢，确保角鹰兽随时待命，将信使、补给和旅客渡海送往大陆。",al={"维斯派塔斯为什么在鲁瑟兰","维斯派塔斯在这里的目的","维斯派塔斯为什么在鲁瑟兰村"}},["5aeefd6f"]={q="维斯派塔斯想要什么？",a="他希望自己的角鹰兽得到妥善照料，也希望连接泰达希尔与邻近哨站的航线保持畅通、安全。他会帮助携带重要物资渡海的旅客和信使。",al={"维斯派塔斯需要什么","维斯派塔斯的目标","维斯派塔斯的动机"}}},fp="10,231,30.511.0,36.250.0,36.220.0,56.205.0"}
P.entries["npc:vidra-hearthstove"] = {n="维德拉·壁炉",s="维德拉·壁炉是一位居住在塞尔萨玛烈酒旅店的矮人厨师。她以烹饪当地特色菜而闻名，经常依靠旅行的冒险者收集区域食材来制作她著名的血肠。",h="维德拉·壁炉是一位居住在塞尔萨玛烈酒旅店的矮人厨师。她以烹饪当地特色菜而闻名，经常依靠旅行的冒险者收集区域食材来制作她著名的血肠。",kw={"血肠","矮人厨师","壁炉","洛克莫丹","烈酒旅店","塞尔萨玛","维德拉·壁炉"},ang={["profession:Cooking"]="维德拉代表了卡兹莫丹丰盛而质朴的烹饪传统，将严苛的当地食材转化为供饥饿的冒险者和山地巡逻队享用的滋补餐点。",["race:Dwarf"]="对于路过塞尔萨玛的矮人来说，维德拉的厨房提供了一种令人安心的家乡味道，体现了她在保持城镇士气方面的重要作用。"},sec={{t="烈酒旅店厨房",b="在烈酒旅店熙熙攘攘的温暖之中，维德拉·壁炉照料着厨房，帮助喂饱当地居民和途经洛克莫丹的旅客。她与旅店老板同姓，确保了塞尔萨玛的充足补给。她的招牌菜——塞尔萨玛血肠，是一种丰盛的矮人主食，需要从周围荒野中收集新鲜的猎物肉，包括野猪内脏、蜘蛛体液和熊肉。"}},faq={{q="维德拉·壁炉是谁？",a="维德拉·壁炉是一位住在塞尔萨玛烈酒旅店的矮人。她以烹饪技艺著称，尤其是她为顾客和保卫洛克莫丹的山地巡逻队员们供应的丰盛塞尔萨玛血肠。",al={"维德拉·壁炉背景故事","维德拉是谁","烈酒旅店厨师"}},{q="在哪里可以找到维德拉·壁炉？",a="她就在位于洛克莫丹塞尔萨玛中心的烈酒旅店里。",al={"维德拉位置","维德拉·壁炉在哪里","烈酒旅店维德拉"}},{q="她制作塞尔萨玛血肠使用什么配料？",a="她著名的食谱需要各种粗犷的当地野生动物部位，具体来说包括从洛克莫丹游荡的野兽身上采集的熊肉、野猪肠和蜘蛛体液。",al={"血肠配料","塞尔萨玛血肠里有什么","维德拉食谱"}}},fx={["5e429306"]={q="维德拉·壁炉站在哪一方？",a="维德拉是卡兹莫丹忠诚的矮人居民，坚定地与联盟结盟。她在塞尔萨玛中心生活和工作，为当地居民烹饪，也热情接待长途跋涉穿越洛克莫丹的疲惫旅客。",al={"维德拉·壁炉的阵营","维德拉属于联盟吗","维德拉·壁炉站哪一边"}},e3ca8182={q="维德拉·壁炉想要什么？",a="维德拉专心钻研厨艺，致力于让烈酒旅店的客人吃得饱足。她需要从洛克湖周边的野生动物身上获取新鲜丰盛的食材，尤其是当地野兽的肉和内脏，用来制作她闻名遐迩的塞尔萨玛血肠。",al={"维德拉·壁炉的动机","维德拉想要什么","维德拉·壁炉的食谱"}},["8f91522d"]={q="维德拉·壁炉为什么在塞尔萨玛？",a="维德拉在烈酒旅店谋生，为镇上的居民、工匠和途经的冒险者提供家常菜。塞尔萨玛是洛克莫丹的主要枢纽，她的厨房对于维持当地守军和工人的体力至关重要。",al={"维德拉为什么在烈酒旅店","维德拉·壁炉所在位置的原因","维德拉为什么在这里"}}},fp="17,228,25.429.0,25.212.0,37.93.0,59.176.0"}
P.entries["npc:viktori-prism-antras"] = {n="维克托·安特拉斯",s="维克托·安特拉斯是一位古怪的观星者，住在俯瞰夜色镇的一间小山坡小屋里。当周围的城镇正屈服于恐惧和阴影中时，维克托却专心致志地建造一台望远镜，以便能清晰地观测苍穹。为了实现这一愿景，他依靠冒险者们根据侏儒图纸寻找错综复杂的零件。",h="维克托·安特拉斯是一位古怪的观星者，住在俯瞰夜色镇的一间小山坡小屋里。当周围的城镇正屈服于恐惧和阴影中时，维克托却专心致志地建造一台望远镜，以便能清晰地观测苍穹。为了实现这一愿景，他依靠冒险者们根据侏儒图纸寻找错综复杂的...",kw={"天文学","cog glitzspinner","夜色镇","暮色森林","仰望星空","安特拉斯","观星者","望远镜","维克托"},ang={["faction:Alliance"]="协助维克托能在夜色镇提供一种难得的宁静追求，帮助一位联盟镇民在普遍的悲剧之中寻求奇迹。",["profession:Engineering"]="工匠们会欣赏维克托的努力，因为建造他的精密观测仪器完全依赖于复杂的侏儒图纸。",["race:Gnome"]="维克托的整个计划都建立在侏儒发明家Cog Glitzspinner的聪明才智之上，展示了侏儒工程学即使在最荒凉的人类城镇也能发挥作用。"},sec={{t="仰望星空",b="维克托·安特拉斯栖身于Gryphon Roost外的小山坡上，终日注视着暮色森林那阴郁的天空。在亡灵入侵、食尸蜘蛛和蔓延的阴影中，他的执念却在那令人窒息的树冠之外。他梦想着建造一台宏伟的光学望远镜，让群星在他眼前熠熠生辉，以此作为逃离那笼罩着小镇的恐惧的宁静避风港。"},{t="侏儒图纸与零散部件",b="在这一片被诅咒的森林中，建造这种精密的装置绝非易事。维克托按照他的侏儒朋友Cog Glitzspinner提供的蓝图进行工作。为了完成这个设备，他招募过路人去搜寻稀有的透镜制作材料和机械外壳，从精细切割的玻璃到散落在危险区域的金属透镜，应有尽有。"}},faq={{q="谁是维克托·安特拉斯？",a="维克托是一位居住在夜色镇的古怪人类观星者。他并不关心小镇眼前的政治或超自然威胁，而是专注于建造一台强大的望远镜来研究星空。",al={"谁是维克托","维克托·安特拉斯背景故事","维克托暮色森林"}},{q="我在哪里可以找到夜色镇的维克托？",a="他住在夜色镇Gryphon Roost旁的小山坡上的一间木屋里，当你沿着小路向上走时，它就在你的右侧。",al={"维克托·安特拉斯位置","维克托在哪里","寻找夜色镇维克托"}},{q="维克托试图建造什么？",a="维克托正试图使用他的侏儒同事Cog Glitzspinner所绘制的蓝图建造一台天文望远镜，这需要几个专门的透镜和组件才能组装完成。",al={"维克托望远镜","仰望星空装置","维克托在制造什么"}},{q="他为什么在暮色森林研究星星？",a="尽管暮色森林中弥漫着黑暗和持续的恐怖，维克托仍沉浸在对天体的好奇之中。专注于夜空那纯洁无瑕的壮丽，为他提供了一个理性的避难所，让他得以远离周围腐朽的大地。",al={"为什么在夜色镇建造望远镜","为什么在暮色森林研究星星"}},{q="谁设计了维克托望远镜的图纸？",a="蓝图是由维克托的一位富有创造力的侏儒熟人Cog Glitzspinner设计的，他提供了组装观测装置所需的图纸。",al={"cog glitzspinner","谁制作了望远镜图纸"}},{q="维克托是否协助保卫夜色镇？",a="不。维克托是一位平民学者，而非战士。他将城镇的防御工作留给了指挥官阿尔泰娅·埃伯洛克和守夜人，更愿意将所有的精力投入到他的天文工作中。",al={"维克托是守夜人吗","维克托会战斗吗"}}},fx={["27dfc9ca"]={q="维克托·安特拉斯站在哪一方？",a="维克托是一名爱好和平的人类居民，认同联盟，也与饱受困扰的夜色镇居民同一阵线。尽管城镇在阴影、诅咒和凶兽的威胁下苦苦挣扎，他仍独自生活，避开当地战事，只专注于学术研究和观星。",al={"维克托·安特拉斯的阵营","维克托属于联盟吗","维克托效忠于谁"}}},fp="20,359,21.420.0,38.354.0,28.239.0,38.127.0,32.195.0,43.227.0,47.167.0,35.207.0"}
P.entries["npc:viscous-fallout"] = {n="粘性辐射尘",s="粘性辐射尘是一个游荡在诺莫瑞根辐射走廊里的有毒水元素，它是麦克尼尔·瑟玛普拉格释放毁灭性辐射后，污染了这座城市的毒素的活体集合。",h="粘性辐射尘是一个游荡在诺莫瑞根辐射走廊里的有毒水元素，它是麦克尼尔·瑟玛普拉格释放毁灭性辐射后，污染了这座城市的毒素的活体集合。",kw={"诺莫瑞根","水下呼吸杖","辐射","瑟玛普拉格","tinker town","粘性辐射尘","水元素"},ang={["class:Druid"]="德鲁伊将这个生物视为大自然上的一道活伤口，它展示了鲁莽的工业污染渗入天然地下水所带来的可怕后果。",["class:Shaman"]="萨满祭司会认出这是对元素位面的扭曲，在粘性辐射尘身上看到的是被人工有毒废料玷污的水元素。",["race:Gnome"]="对于侏儒来说，粘性辐射尘是一个悲剧性的提醒，让他们想起麦克尼尔·瑟玛普拉格对他们的家园造成的破坏，那里连水都变得有毒了。"},sec={{t="污染之灵",b="当诺莫瑞根在麦克尼尔·瑟玛普拉格的奸计下，为了消灭入侵的石腭怪而充满辐射时，放射性尘埃让城市的底层充斥着有毒粘液和污染物。粘性辐射尘就是来自那些中毒深处的水元素，其本身就由浓稠的城市有毒废料构成。在沦陷之前它的来源不得而知。"},{t="下水道中的痛苦",b="现在，这个生物不过是一团流动的有毒淤泥，在辐射笼罩的下层通道中飘荡。粘性辐射尘喷射着毒素，攻击它路径上的一切。对于那些为了净化受污染深处而冒险进入诺莫瑞根的人来说，击败它是冷酷的必然。"}},faq={{q="粘性辐射尘是什么？",a="粘性辐射尘是一个位于被摧毁的诺莫瑞根城内的水元素小头目，它被有毒淤泥和放射性尘埃彻底污染了。",al={"粘性辐射尘是谁","粘性辐射尘背景故事","粘性辐射尘是什么类型的生物"}},{q="它为何会腐化？",a="诺莫瑞根在麦克尼尔·瑟玛普拉格的奸计下为了击退石腭怪入侵而充斥了辐射，导致其下层通道充满了有毒废料。这个元素究竟是如何浸透这种剧毒的尚不得而知；它仅仅是这座城市变成的辐射废墟的一部分。",al={"它为什么是绿色的","这个元素为什么有毒","粘性辐射尘是如何产生的"}},{q="它在诺莫瑞根的哪里游荡？",a="粘性辐射尘在诺莫瑞根主入口下方受辐射的下层通道和排水渠中巡逻，经常混迹在那些肆虐该地区的普通变异软泥和有毒废料之中。",al={"粘性辐射尘位置","在哪里可以找到粘性辐射尘","如何找到粘性辐射尘"}},{q="为什么它具有敌意？",a="就像现在困扰着受辐射深处的绝大多数生物一样，这个有毒元素会攻击任何闯入受污染通道的活物。",al={"它为什么会攻击","它能被拯救吗"}},{q="它和铁炉堡有什么联系吗？",a="只有间接联系。逃离诺莫瑞根的侏儒们现在作为难民生活在铁炉堡的Tinker Town，而粘性辐射尘是他们失去的家园中残留的恐怖生物之一。",al={"水下呼吸杖 铁炉堡","侏儒联系"}},{q="这个元素能被净化或治愈吗？",a="目前没有已知治愈该元素的方法。辐射和有毒化学物质已经完全渗透进了它的躯体，摧毁它是唯一的办法。",al={"你能治愈粘性辐射尘吗","净化粘性辐射尘"}}},fx={c0463f1a={q="粘性辐射尘站在哪一方？",a="粘性辐射尘没有主人，也不属于任何阵营。它的有毒状态直接源于麦克尼尔·瑟玛普拉格将放射性尘埃排放到城市各处，但它并不效忠于他、麻风侏儒或穴居人。它只是一个饱受折磨的元素生物，被污染逼得发狂，不分对象地攻击所有挡在它面前的东西。",al={"粘性辐射尘的阵营","粘性辐射尘效忠于谁","粘性辐射尘与瑟玛普拉格是一伙的吗"}},["41523791"]={q="粘性辐射尘想要什么？",a="这个元素生物没有远大的野心，也没有理性的目的。它是污染诺莫瑞根的毒物凝聚而成的一团毒质，在遭受辐射污染的走廊中游荡，攻击任何不幸进入城市水淹通道的生物。",al={"粘性辐射尘的目标","粘性辐射尘会做什么","粘性辐射尘的动机"}},["2b056577"]={q="粘性辐射尘为什么在这里？",a="它在诺莫瑞根遭受辐射污染的深处游荡。麦克尼尔·瑟玛普拉格曾用辐射淹没整座城市，试图驱逐穴居人，留下了遍地毒污。至于这只元素生物在城市沦陷前来自何处，目前无人知晓。",al={"粘性辐射尘为什么在诺莫瑞根","粘性辐射尘是怎么来到这里的","粘性辐射尘所在位置的原因"}}},fp="15,202,17.366.0,19.298.0,24.152.0,28.298.0,35.202.0,18.142.0,41.178.0,39.144.0"}
P.entries["npc:vol-jin"] = {n="沃金",s="沃金是暗矛巨魔的酋长，也是一位强大的暗影猎手。他与萨尔大酋长一同居住在Grommash Hold，作为部落最值得信赖的顾问，致力于为他那流离失所的人民在杜隆塔尔寻找一个永久的家园。",h="沃金是暗矛巨魔的酋长，也是一位强大的暗影猎手。他与萨尔大酋长一同居住在Grommash Hold，作为部落最值得信赖的顾问，致力于为他那流离失所的人民在杜隆塔尔寻找一个永久的家园。",kw={"暗矛","grommash hold","奥格瑞玛","森金","暗影猎手","萨尔","沃金","扎拉赞恩"},ang={["faction:Horde"]="沃金与萨尔并肩作战，作为新部落的支柱，贡献着狡黠的建议以及丛林巨魔的忠诚。",["race:Troll"]="沃金是你的酋长，他凭借着精神智慧和战术决心，带领暗矛巨魔度过了流离失所的艰难岁月。"},sec={{t="暗矛氏族酋长",b="在父亲森金于他们祖辈居住的岛屿上不幸遇难后，沃金接过了暗矛巨魔的领导权。当崇拜海巫的鱼人和人类军队几乎摧毁了这个与世隔绝的部落时，萨尔的兽人伸出了援手，让这两个种族结下了深厚的友谊。在撤离了他们岛屿的废墟后，沃金誓言让他的巨魔加入新部落，并率领他们跨越无尽之海来到卡利姆多。"},{t="智慧之谷议会",b="虽然暗矛巨魔在杜隆塔尔建立了定居点，但内部的背叛——即扎拉赞恩在回音群岛的背信弃义——迫使许多难民逃往大陆上的森金村。沃金大部分时间都在奥格瑞玛的Grommash Hold内，直接为萨尔提供敏锐的战略建议和暗影猎手的战斗技巧。从兽人主城的中心地带，他守护着年轻的部落，同时努力收复他的人民应得的土地。"}},faq={{q="沃金是谁？",a="沃金是暗矛巨魔部落的领袖和酋长。他是一位技艺高超的暗影猎手，代表他的人民参与部落的领导工作，是萨尔大酋长在奥格瑞玛最亲近的顾问之一。",al={"谁是巨魔领袖","沃金背景故事","暗矛领袖"}},{q="沃金住在哪里？",a="沃金位于奥格瑞玛智慧之谷的Grommash Hold，就站在萨尔大酋长身边。",al={"沃金在哪里","沃金位置","找到沃金"}},{q="为什么暗矛巨魔加入了部落？",a="在第三次战争期间，萨尔的舰队被冲上了暗矛群岛。兽人与巨魔结盟，共同对抗敌对的人类和狂热的鱼人军队。森金死后，沃金誓言将他的部落交给萨尔，暗矛巨魔从此跟随部落来到了卡利姆多。",al={"为什么巨魔在部落","暗矛部落历史","萨尔和沃金"}},{q="为什么暗矛巨魔不居住在他们自己的岛屿上？",a="在定居于杜隆塔尔海岸外的回音群岛后，巫医扎拉赞恩因黑魔法而陷入疯狂。扎拉赞恩奴役了他的族人，迫使沃金和幸存的暗矛巨魔逃往大陆上的森金村。",al={"回音群岛发生了什么","为什么巨魔在森金村","扎拉赞恩背叛"}}},fx={["779e986b"]={q="沃金为何声名远扬？",a="沃金既是暗矛部族的酋长，也是一位技艺高超的暗影猎手，与洛阿有着深厚的联系，因此广受赞誉。他带领族人经历了鱼人劫掠、人类入侵和流亡等惨痛磨难，赢得了巨魔永远的尊敬，也在新部落的奠基者中备受推崇。",al={"沃金为何受人敬仰","沃金的声望","沃金是否有名"}},["00b3c7ef"]={q="沃金站在哪一方？",a="沃金一心效忠于部落和遭到流放的暗矛巨魔。自从萨尔和兽人从岛上的故乡将他的部族从屠杀中救出后，沃金便始终恪守父亲立下的效忠誓言。他是萨尔最信任的顾问之一，在奥格瑞玛核心地带为其提供明智的建议和战术指导。",al={"沃金的阵营","沃金效忠于谁","沃金属于部落吗"}},["9b5f7e47"]={q="沃金想要什么？",a="沃金最希望为暗矛部族争取稳定而繁荣的未来，实现父亲森金临终前的愿景。他与萨尔紧密合作，巩固部落在杜隆塔尔的立足之地，努力保护流离失所的族人免遭卡利姆多的敌对势力侵害，并维护他们的祖传传统。",al={"沃金的目标","沃金的动机是什么","沃金寻求什么"}},ee20a7f7={q="沃金为什么在奥格瑞玛？",a="沃金居住在Grommash Hold，与萨尔并肩而立，代表暗矛巨魔参与部落领导层的核心事务。除了引领自己的族人，他还担任酋长大人的首席战略家和精神顾问，统筹部族防御，并巩固巨魔与兽人之间至关重要的联盟。",al={"沃金为什么在奥格瑞玛","沃金为什么在这里","沃金在奥格瑞玛做什么"}},df7c3222={q="沃金与谁关系密切？",a="沃金是备受尊敬的巫医森金之子，也是他的继承者；森金曾以牺牲自己为代价拯救暗矛巨魔。他与酋长萨尔之间有着牢不可破的情谊，每日为其出谋划策；他与洛阿的联系则指引着他成为一名暗影猎手。",al={"沃金的盟友","沃金的关系","沃金与谁有亲缘关系"}}},fp="7,245,26.432.0,31.465.0,15.219.0,24.117.0,37.270.0,53.242.0"}
P.entries["npc:volcor"] = {n="沃科尔",s="沃科尔是一名受伤的暗夜精灵侦察兵，被困在黑木洞穴深处，那是黑海岸南部的一个地方。由于被充满敌意的黑木熊怪困住，他只能依靠他忠实的伙伴格里姆克劳以及奥伯丁守卫者的援助来脱身。",h="沃科尔是一名受伤的暗夜精灵侦察兵，被困在黑木洞穴深处，那是黑海岸南部的一个地方。由于被充满敌意的黑木熊怪困住，他只能依靠他忠实的伙伴格里姆克劳以及奥伯丁守卫者的援助来脱身。",kw={"奥伯丁","黑木洞穴","黑海岸","强攻逃脱","潜行逃脱","熊怪","格里姆克劳","特伦希斯","沃科尔"},ang={["class:Druid"]="沃科尔与格里姆克劳之间的纽带，反映了德鲁伊与自然野兽之间深厚的连接，这使得营救他成为了关乎自然平衡的一件大事。",["class:Rogue"]="沃科尔赞赏战术上的精巧，为潜行者提供了绕过黑木守卫的机会，而不是单纯依赖蛮力。",["race:NightElf"]="沃科尔的困境说明了卡多雷在黑海岸面临的危险日益严峻，曾经和平的熊怪盟友正在不断堕落。"},sec={{t="困在大兽穴中",b="在追踪黑木部族位于地下的巢穴时，沃科尔遭到了伏击并受了重伤。由于无法独自击败那些充满敌意的熊怪并杀出重围，他派出了自己忠诚的熊同伴格里姆克劳，前往黑海岸的荒野寻找奥伯丁定居点的帮助。"},{t="通往自由之路",b="一旦被特伦希斯派出的侦察兵找到，沃科尔会根据救援者的强项提供两种逃生方式。偏好直接行动的人可以从洞穴的守卫中杀出一条血路，而擅长潜行的人则可以利用狡黠的手段和安静的行动悄无声息地溜过守卫。"}},faq={{q="沃科尔在哪里？",a="沃科尔藏在黑木洞穴深处，这是一个位于黑海岸极南端、靠近灰谷边界的熊怪洞穴，距离奥伯丁向南延伸的道路不远。",al={"沃科尔位置","沃科尔在哪里","寻找沃科尔"}},{q="为什么沃科尔会被困在黑木洞穴里？",a="他在侦察黑木熊怪时遭到了攻击并受了伤。他与洞穴入口隔绝，没有援助就无法绕过那些敌对的守卫。",al={"为什么沃科尔在洞穴里","沃科尔发生了什么"}},{q="格里姆克劳是谁？",a="格里姆克劳是沃科尔忠诚的熊伙伴。当沃科尔被困住时，他派格里姆克劳前往奥伯丁求援，这最终惊动了德鲁伊特伦希斯。",al={"那只熊是谁","沃科尔的熊","格里姆克劳背景故事"}},{q="如何帮助沃科尔逃脱？",a="沃科尔让你选择救援方式：你可以选择正面强攻，杀出洞穴守卫熊怪的包围；或者利用潜行溜过它们。",al={"强攻或潜行逃脱","沃科尔护送任务","营救沃科尔"}},{q="是谁派你寻找沃科尔的？",a="特伦希斯，一位驻扎在奥伯丁的暗夜精灵德鲁伊，在发现格里姆克劳独自徘徊后，指引冒险者去寻找沃科尔。",al={"谁发布了沃科尔的任务","特伦希斯的关系"}},{q="是哪个部族的熊怪攻击了他？",a="黑木部族，这是一个黑海岸本土的堕落熊怪部族，已经陷入了疯狂和敌意之中。",al={"哪种熊怪","黑木熊怪"}}},fx={fe864757={q="沃科尔是谁？",a="沃科尔是一名暗夜精灵探险者，常在黑海岸游历。他与忠实的熊伙伴Grimclaw结伴深入森林，却遭遇了敌对的黑木熊怪，身受重伤，困在它们的洞穴中。",al={"沃科尔是谁","沃科尔的身份","沃科尔是暗夜精灵吗"}},["77334435"]={q="沃科尔属于哪一方？",a="沃科尔与达纳苏斯的暗夜精灵以及联盟结盟。他信赖的联系人住在海岸避风港奥伯丁，特伦希斯等朋友会照看他的安危，也欢迎愿意帮助他的旅人。",al={"沃科尔的阵营","沃科尔是否属于联盟","沃科尔效忠哪一方"}},a5845558={q="沃科尔想要什么？",a="沃科尔被困在黑木洞穴深处，身受重伤、虚弱不堪，只想活着逃出去，回到安全的奥伯丁。他已派Grimclaw先行求援，如今只能依靠路过的盟友带他避开敌对的熊怪。",al={"沃科尔想要什么","沃科尔的目标","沃科尔的动机"}}},fp="6,226,18.299.0,16.307.1,24.166.0,39.158.0,16.161.0,31.174.0,28.145.0,36.115.0"}
P.entries["npc:vorn-skyseer"] = {n="沃恩·星眼",s="沃恩·星眼是居住在莫高雷红云台地纳拉其营地里的一位爱好和平的牛头人。他常在营地的帐篷间休憩，迎接开启冒险旅程的年轻冒险者，并向他们介绍当地的生活。",h="沃恩·星眼是居住在莫高雷红云台地纳拉其营地里的一位爱好和平的牛头人。他常在营地的帐篷间休憩，迎接开启冒险旅程的年轻冒险者，并向他们介绍当地的生活。",kw={"纳拉其营地","莫高雷","红云台地","牛头人","沃恩·星眼","欢迎"},ang={["faction:Horde"]="沃恩体现了在凯恩·血蹄领导下聚集起来、建立永久家园的平原部族那冷静沉稳的天性。",["race:Tauren"]="对于红云台地上的年轻牛头人来说，沃恩·星眼往往是他们准备步入莫高雷广阔世界时，见到的第一张熟悉而令人安心的面孔。"},sec={{t="纳拉其营地的友善面孔",b="沃恩·星眼位于红云台地的纳拉其营地，是非正式接待年轻牛头人的向导。当年轻的牛头人在进入莫高雷广阔的山谷前进行试炼仪式时，沃恩会提供善意的鼓励和款待，帮助新来者融入营地。"},{t="超然的观察者",b="沃恩并非战士。他将营地的防卫工作留给勇敢者，自己则过着平静悠闲的生活，满足于守护着家园那宁静的平原。"}},faq={{q="沃恩·星眼是谁？",a="沃恩·星眼是莫高雷纳拉其营地的一位长者。他的主要职责是迎接在红云台地开启入门试炼的年轻牛头人勇士。",al={"沃恩·星眼背景故事","沃恩是谁","沃恩 莫高雷"}},{q="我在哪里可以找到沃恩·星眼？",a="他通常在莫高雷西南部红云台地上的纳拉其营地的帐篷外休息。",al={"沃恩·星眼位置","沃恩在哪里","沃恩 纳拉其营地"}},{q="沃恩提供什么任务？",a="他在“欢迎！”任务中接收血蹄村礼券，问候持券人，并提供一个小型伙伴陪伴他们一同冒险。",al={"沃恩·星眼任务","沃恩 欢迎任务"}}},fx={["786f5f1f"]={q="沃恩·星眼属于哪一方？",a="沃恩·星眼是一名居住在红云台地纳拉其营地的牛头人，坚定地支持莫高雷的部族和部落。他并非战士；他的家园和忠诚都属于自己的族人。",al={"沃恩·星眼的阵营","沃恩效忠谁","沃恩的立场"}},["28d2e499"]={q="沃恩·星眼为何在纳拉其营地？",a="沃恩·星眼住在纳拉其营地，迎接那些在红云台地开启旅程的年轻勇士。他热情款待新来者，给予他们亲切的鼓励，帮助他们融入营地。",al={"沃恩为何在这里","沃恩·星眼在血蹄村的职责","沃恩做什么"}}},fp="12,210,31.291.0,19.159.0,20.166.0,30.110.0,28.154.0"}
P.entries["npc:warcaller-gorlach"] = {n="公告员高拉克",s="公告员高拉克是一位在奥格瑞玛尘土飞扬的街道上游荡的兽人传令官，他呼唤部落的勇士前往遥远的战场。正如他的头衔所暗示的，他集结旅行者和身经百战的战士，让他们去回应卡利姆多及其他地区危险前哨站的命令。",h="公告员高拉克是一位在奥格瑞玛尘土飞扬的街道上游荡的兽人传令官，他呼唤部落的勇士前往遥远的战场。正如他的头衔所暗示的，他集结旅行者和身经百战的战士，让他们去回应卡利姆多及其他地区危险前哨站的命令。",kw={"灰谷狩猎","武装号令","莫沙彻营地","高拉克","传令官","奥格瑞玛","公告员高拉克"},ang={["faction:Horde"]="对于那些想要证明实力或寻求杜隆塔尔之外指引的部落勇士，高拉克为他们提供了通往急需援军的前哨站的清晰方向。"},sec={{t="大酋长的号召之声",b="公告员高拉克在奥格瑞玛的大道上巡逻，担任着部落扩张和战略防御的主要传令官。他没有安坐在要塞的办公桌后，而是在市民中穿行，直接向准备好试炼身手的志愿者发布命令。无论是派遣猎人进入纷争不断的灰谷丛林，指引侦察兵前往菲拉斯的莫沙彻营地，还是为诸如瘟疫之地等遥远的战役发布绝望的武装号令，高拉克都确保了没有一个逗留在首都的战士会在部落面临外敌时无所事事。"}},faq={{q="谁是公告员高拉克？",a="高拉克是奥格瑞玛的一位游荡的兽人传令官，他发布命令并指引充满冒险精神的部落成员前往关键的战斗区域和遥远的边疆。",al={"高拉克","谁是高拉克","公告员"}},{q="公告员高拉克将冒险者派往何处？",a="他指引部落勇士前往各处急需援助的前哨站，包括灰谷的森林、菲拉斯的莫沙彻营地，以及诸如瘟疫之地等遥远的前线。",al={"高拉克的目的地","高拉克把你派往何处","高拉克的任务"}},{q="在哪里可以找到公告员高拉克？",a="他可以在奥格瑞玛的街道和峡谷中游荡时找到，他在首都巡逻时大声呼喊着战斗的号角。",al={"高拉克的位置","高拉克在哪里","找到高拉克"}}},fx={["1e435e0c"]={q="公告员高拉克属于哪一方？",a="公告员高拉克是一名效忠部落的兽人。他驻扎在奥格瑞玛，积极号召战士保卫部落的利益，并支援卡利姆多及更远地区的军事行动。",al={"高拉克的阵营","高拉克属于部落吗","高拉克效力于谁"}},["5b62b1f9"]={q="公告员高拉克想要什么？",a="高拉克正在招募能够响应部落号召的战士。他指引踊跃的冒险者前往争夺激烈的边境和关键据点，为世界各地持续进行的战斗召集新兵。",al={"高拉克想要什么","高拉克的职责","高拉克的任务"}},["662e00c8"]={q="公告员高拉克为何在奥格瑞玛？",a="高拉克以战争召集人的身份在部落首都的街道上巡视，负责招募和传递消息。他巡逻奥格瑞玛，确保新到的勇士得知远方战事急需援助。",al={"高拉克为何在这里","奥格瑞玛的高拉克","高拉克在奥格瑞玛的职责"}}},fp="17,260,28.606.0,25.153.0,46.171.0,37.124.0"}
P.entries["npc:warden-thelwater"] = {n="典狱官塞尔沃特",s="典狱官塞尔沃特是暴风城地下最高安全级别监狱——监狱的看守者，此刻正陷入困境。在迪菲亚囚犯突然发动暴力暴乱时，他被打了个措手不及，现在迫切需要招募有能力的冒险者，在消息传到城内之前平息这场叛乱。",h="典狱官塞尔沃特是暴风城地下最高安全级别监狱——监狱的看守者，此刻正陷入困境。在迪菲亚囚犯突然发动暴力暴乱时，他被打了个措手不及，现在迫切需要招募有能力的冒险者，在消息传到城内之前平息这场叛乱。",kw={"巴基尔·斯瑞德","迪菲亚","监狱","暴乱","暴风城","塞尔沃特","典狱官塞尔沃特"},ang={["class:Paladin"]="对于致力于秩序与正义的圣光战士而言，塞尔沃特为恢复监狱控制权而进行的殊死搏斗，正是将正义的纪律带给暴力罪犯的直接号召。",["class:Rogue"]="潜行者因塞尔沃特而进入监狱，发现自己正深陷于迪菲亚阴谋和地下监狱政治的混乱后果之中。",["faction:Alliance"]="典狱官塞尔沃特代表了暴风城内脆弱的秩序，他依靠忠诚的联盟勇士在监狱哗变威胁到首都市民之前将其镇压。"},sec={{t="运河中的危机",b="Hidden beneath the canals of Stormwind, the Stockade holds the kingdom's most dangerous miscreants, petty thieves, and political conspirators. Warden Thelwater was charged with keeping them securely locked away, but an organized revolt took the guards completely off guard. With the prisoners overwhelming security and taking control of the cells, Thelwater found himself barricaded at the threshold, struggling to contain an armed insurrection right beneath the streets of the capital."},{t="掩盖真相",b="为了不让恐慌蔓延到暴风城的街道上，塞尔沃特决定以绝对低调的方式处理这场暴乱。越狱的幕后主使巴基尔·斯瑞德在被关押的迪菲亚潜行者中拥有巨大的影响力。为了防止暴乱暴露暴风城管理上的广泛漏洞，塞尔沃特依靠外部雇佣兵潜入监区，击败主谋，并悄悄夺回监狱的控制权。"}},faq={{q="典狱官塞尔沃特是谁？",a="典狱官塞尔沃特是驻扎在暴风城监狱入口处的人类官员，负责管理这个高安全级别的监狱设施。",al={"塞尔沃特","监狱典狱官","塞尔沃特是谁"}},{q="监狱发生了什么？",a="囚犯中爆发了一场有预谋的暴动，主要由被关押的迪菲亚潜行者成员推动。囚犯们压制了守卫并接管了监区，使得塞尔沃特和他剩余的手下只能守在入口附近。",al={"监狱暴乱","监狱发生了什么","为什么监狱会崩溃"}},{q="谁在领导监狱暴乱？",a="巴基尔·斯瑞德是策划此次暴动的幕后主使，他潜伏在监狱深处。他指挥着迪菲亚囚犯，并直接发起了针对守卫的突袭。",al={"监狱首领","谁在领导暴动","巴基尔·斯瑞德是谁"}},{q="为什么暴风城卫兵没有大规模介入？",a="塞尔沃特希望能悄悄解决这场灾难。如果大肆宣扬暴风城最坚固的地牢竟然沦陷在囚犯手中，会在全城引发大范围的恐慌，所以他招募谨慎的冒险者来内部清理烂摊子。",al={"为什么没有卫兵","为什么要雇佣冒险者","秘密暴乱"}},{q="这里关押的是什么样的囚犯？",a="该设施关押着小偷小摸的惯犯、盗贼、杀人犯和危险的政治叛乱分子，其中最引人注目的是迪菲亚潜行者的高层成员。",al={"监狱囚犯","监狱里有什么人","罪犯类型"}},{q="在哪里可以找到典狱官塞尔沃特？",a="他驻扎在监狱的入口外，位于暴风城Mage Quarter和Cathedral Square之间的运河附近。",al={"塞尔沃特位置","典狱官在哪里","寻找塞尔沃特"}}},fx={["088280c3"]={q="典狱官塞尔沃特属于哪一方？",a="塞尔沃特效力于暴风王国，听命于其统治者。作为监狱的正式典狱官，他代表城市的刑罚管理机构和王室，竭力维持地下监狱的秩序，防止王国中最凶恶的罪犯逃入首都。",al={"塞尔沃特的阵营","塞尔沃特效力于谁","塞尔沃特属于联盟吗"}},bf0ea06f={q="典狱官塞尔沃特想要什么？",a="塞尔沃特想要无情镇压这场监狱暴动，以免混乱蔓延。迪菲亚暴徒发动骚乱时，他猝不及防；他的首要目标是除掉暴乱的幕后主使巴基尔·斯瑞德，并镇压叛乱头目，尽可能悄无声息地恢复对监狱的全面控制。",al={"塞尔沃特需要什么","塞尔沃特的目标","塞尔沃特为何需要冒险者"}},["4dddd3c5"]={q="典狱官塞尔沃特为何在这里？",a="塞尔沃特驻守在监狱入口，因为囚犯暴动迫使他退到了这里。他剩下的守卫不足以独自平息骚乱，因此他留在运河边的入口处坚守防线，并招募能干的佣兵冲入监狱，夺回牢房。",al={"塞尔沃特为何在监狱","塞尔沃特为何站在外面","塞尔沃特为何在入口附近"}},["479dc467"]={q="典狱官塞尔沃特与谁有关？",a="塞尔沃特隶属暴风城的行政机构，与负责保卫首都的城卫并肩行事。他在这座地下城中最紧迫的关系，是他与囚犯巴基尔·斯瑞德之间的敌对关系；斯瑞德精心策划的暴动威胁着塞尔沃特的地位和王国的安全。",al={"塞尔沃特的盟友","塞尔沃特为谁效力","塞尔沃特的人际关系"}}},fp="16,296,22.486.0,20.477.1,24.164.0,30.250.0,31.166.0,56.235.0,37.149.0,36.147.0"}
P.entries["npc:warlord-goretooth"] = {n="军官高图斯",s="军官高图斯是驻扎在荒芜之地卡加斯的兽人指挥官。从他的瞭望塔上，他协调部落针对邻近黑铁矮人的边境战事，并监视着黑石山的火山威胁。虽然他在军事事务上非常严格，但偶尔也能见到他在营地的篝火旁放松。",h="军官高图斯是驻扎在荒芜之地卡加斯的兽人指挥官。从他的瞭望塔上，他协调部落针对邻近黑铁矮人的边境战事，并监视着黑石山的火山威胁。虽然他在军事事务上非常严格，但偶尔也能见到他在营地的篝火旁放松。",kw={"安格弗将军","荒芜之地","黑石山","黑铁矮人","伊崔格","高图斯","卡加斯","军官高图斯"},ang={["class:Warrior"]="高图斯在黑石山中粗暴直接的军事命令，为勇武的勇士们提供了对抗老练的矮人军团士兵、磨练自身实力的机会。",["faction:Horde"]="军官高图斯是部落在荒芜之地立足的基石，负责指挥针对黑铁矮人的关键行动。"},sec={{t="卡加斯指挥官",b="军官高图斯高踞于卡加斯的瞭望塔之上，指挥着敌对东部边境的部落行动。卡加斯是奥格瑞玛对抗潜伏在黑石山及周边峡谷中威胁的主要集结地。高图斯负责监督巡逻，协调诸如卡加斯远征队之类的侦察部队，并直接下达针对黑铁氏族成员及其领导层的猎杀令。当他从瞭望塔下来时，这位严厉的指挥官会展现出轻松的一面，经常在营地篝火旁取暖，并与营地里的被遗忘者施法者打趣，然后再回到岗位上。"},{t="打击黑铁矮人",b="高图斯认为黑铁矮人对部落在东部王国的利益构成了切实的直接威胁。与其采取防御姿态，他制定了针对盘踞在黑石深渊内的安格弗将军和达格兰·索瑞森大帝部队的积极战争计划。他深知进攻这样一座古老地下堡垒的严重性，因此在批准进一步推进至山中之前，他经常就战略问题请教奥格瑞玛的兽人老兵伊崔格，以寻求丰富的经验指引。"}},faq={{q="军官高图斯是谁？",a="军官高图斯是驻扎在荒芜之地卡加斯的部落高级军事指挥官。他组织部落巡逻队，并指挥针对黑铁矮人的突袭行动。",al={"军官高图斯","高图斯","荒芜之地","卡加斯指挥官"}},{q="他在卡加斯担任什么职责？",a="他指挥着该哨所，定期派遣卡加斯远征队前往野外，并发布针对黑石深渊内黑铁氏族的军事作战命令。",al={"高图斯职责","高图斯的任务","高图斯的哨所"}},{q="为什么高图斯要派遣士兵进攻黑石深渊？",a="黑铁矮人威胁着周边地区，并积极对抗部落在该地区的存在。高图斯针对他们的士兵、高级军官和安格弗将军发布了直接猎杀悬赏，以削弱他们对山脉的控制。",al={"为何打击黑铁矮人","击杀安格弗将军任务","高图斯与黑铁矮人"}},{q="为什么高图斯要咨询伊崔格？",a="伊崔格是一位经验丰富的兽人老兵，他曾在黑石山中生活，比几乎任何人都更了解其内部局势和防御体系。在升级对黑石堡垒的进攻之前，高图斯会派遣冒险者去寻求伊崔格的建议。",al={"高图斯与伊崔格","伊崔格的智慧","为何请教伊崔格"}}},fp="17,370,20.631.0,23.528.0,25.175.0,28.187.0,59.248.0,35.254.0"}
P.entries["npc:warmaster-laggrond"] = {n="拉格隆德",s="拉格隆德是一位经验丰富的兽人指挥官，驻扎在奥特兰克山脉中奥特兰克山谷的部落入口处。他负责招募工作，并确认那些响应号召援助霜狼氏族的战士在前线的表现。通过他的试炼，战士们能够证明自己的勇气，并赢得部落先锋的尊重。",h="拉格隆德是一位经验丰富的兽人指挥官，驻扎在奥特兰克山脉中奥特兰克山谷的部落入口处。他负责招募工作，并确认那些响应号召援助霜狼氏族的战士在前线的表现。通过他的试炼，战士们能够证明自己的勇气，并赢得部落先锋的尊重。",kw={"奥特兰克山脉","奥特兰克山谷","霜狼","拉格隆德","试炼场","pvp","雷矛"},ang={["class:Warrior"]="拉格隆德重视前线的勇气，他会考验未来的勇士，以确保他们能够抵挡住矮人的重甲和先锋冲锋。",["faction:Horde"]="拉格隆德是你进行奥特兰克山谷战争的初始联络点，他代表霜狼氏族认可你在战场上的成就。",["race:Orc"]="对于兽人来说，响应拉格隆德的召唤是传承的一部分，旨在保卫受人尊敬的霜狼氏族免受矮人的侵扰，守护这片 ancestral 避难所。"},sec={{t="前线指挥官",b="拉格隆德在奥特兰克山谷入口的严寒中执勤，组织部落对抗雷矛卫队的战争。他确保只有具备能力的战士才能进入山谷，代表霜狼氏族和整个部落出战。"},{t="荣誉之路",b="拉格隆德在将战士送入激烈的战场前，会通过试炼场对他们进行测试。当战士们在冰封的山峰上洒下热血时，正是拉格隆德在衡量他们的功绩，并为那些在霜狼氏族中获得声望的人授予荣誉。"}},faq={{q="拉格隆德在哪里？",a="拉格隆德驻扎在希尔斯布莱德丘陵北面、奥特兰克山脉积雪高地中的奥特兰克山谷传送门旁的部落营地附近。",al={"拉格隆德位置","拉格隆德在哪里","奥特兰克山谷入口指挥官"}},{q="拉格隆德的职责是什么？",a="他担任部落奥特兰克山谷战争的招募官，通过初步的战斗试炼来评估新兵，并奖励那些获得霜狼氏族声望的人。",al={"拉格隆德做什么","拉格隆德目的","为什么要找拉格隆德"}},{q="什么是试炼场任务？",a="拉格隆德要求未来的新兵从奥特兰克山谷的野爪巢穴中取回一面霜狼军旗。这是在加入战役前证明他们足智多谋的考验。",al={"部落试炼场","拉格隆德初始任务"}},{q="为什么部落要在奥特兰克山谷作战？",a="霜狼氏族在第一次战争期间被流放后，长期以来一直声称该山谷是他们的家园。雷矛卫队是一支联盟矮人探险队，他们为了搜寻文物和领土进入了该地区，从而引发了一场激烈的领土战争。",al={"为什么要去奥特兰克山谷","霜狼战争","奥特兰克山谷冲突"}},{q="联盟玩家可以与拉格隆德互动吗？",a="不能。拉格隆德是部落的忠诚拥护者，会攻击任何接近他在山中岗哨的联盟闯入者。",al={"联盟能和拉格隆德对话吗","拉格隆德敌对"}}},fx={["050e2655"]={q="拉格隆德是谁？",a="拉格隆德是一名兽人军官，驻守在奥特兰克山脉的雪域中、通往奥特兰克山谷的入口处。他为霜狼氏族和部落的整体战事效力，考察前来应召的勇士，并指派能干的战士参加对抗雷矛矮人的战斗。",al={"拉格隆德是谁","拉格隆德的背景","拉格隆德与奥特兰克"}},ccc612bb={q="拉格隆德属于哪一方？",a="拉格隆德坚定地支持部落，具体代表霜狼氏族的利益。他将联盟，尤其是步步进逼的雷矛远征军，视为擅闯霜狼祖传领地的入侵者。",al={"拉格隆德属于部落吗","拉格隆德的阵营","拉格隆德属于联盟还是部落"}},["29764588"]={q="拉格隆德想要什么？",a="拉格隆德正在寻找愿意在奥特兰克山谷的残酷冲突中证明自己的坚定勇士。他希望守住霜狼领地、击溃矮人远征军，并让部落战士通过鲜血与职责赢得氏族的地位和荣誉。",al={"拉格隆德想要什么","拉格隆德的目标","拉格隆德的任务目标"}},b3dc84d2={q="拉格隆德为何在这里？",a="拉格隆德驻守在山谷入口的传送门外，负责把守关口并为前线招募战士。他检查响应霜狼氏族号召的人，确保只有意志坚定的战士才会带着氏族旗帜奔赴战场。",al={"拉格隆德为何在奥特兰克","拉格隆德所在位置的目的","拉格隆德为何在这里"}},["6fc2678d"]={q="拉格隆德与谁有关？",a="拉格隆德听命于霜狼氏族的领袖，代表德雷克塔尔将军以及部落的军队作战，抵御矮人的挖掘和征服企图，守住奥特兰克山谷。",al={"拉格隆德的关系","拉格隆德与霜狼氏族","拉格隆德为谁效力"}}},fp="18,328,19.263.0,17.270.0,36.176.0,34.192.0,34.168.0,44.252.0,54.141.0"}
P.entries["npc:warsong-outrider"] = {n="战歌侦查骑兵",s="战歌侦查骑兵驻扎在从灰谷向东通往艾萨拉的争议道路上，守望着部落的边疆。她担任战歌氏族的前哨侦察兵，监视过往旅人并将关键情报传回他们的前线营地。虽然她全副武装且时刻警惕着暗夜精灵的入侵，但除非受到直接挑衅，否则她会保持被动观察。",h="战歌侦查骑兵驻扎在从灰谷向东通往艾萨拉的争议道路上，守望着部落的边疆。她担任战歌氏族的前哨侦察兵，监视过往旅人并将关键情报传回他们的前线营地。虽然她全副武装且时刻警惕着暗夜精灵的入侵，但除非受到直接挑衅，否则她会保持被动...",kw={"灰谷","艾萨拉","部落侦察兵","侦查骑兵情报","战歌氏族","战歌侦查骑兵"},ang={["faction:Alliance"]="虽然身为敌对战斗人员，但除非受到挑衅，否则这名侦察兵不会向联盟旅人开火，让警惕的冒险者得以平安通过。",["faction:Horde"]="像她一样的侦查骑兵维持着连接灰谷争议伐木区与艾萨拉荒野海岸之间脆弱的补给和侦察路线。"},sec={{t="关注东部边疆",b="灰谷与破碎的艾萨拉废墟之间的边界充满了危险。战歌侦查骑兵远离碎木岗哨或伐木场的坚固防线，在此观察部队动向并巡逻交通要道。她装备着弓箭和剧毒尖刺，时刻准备保卫部落在该地区的领土主张，但为了保存实力，她只会在联盟入侵者主动攻击时才会开火。"}},faq={{q="可以在哪里找到战歌侦查骑兵？",a="她驻扎在灰谷东部通往邻近区域艾萨拉的主要道路上。",al={"侦查骑兵位置","战歌侦查骑兵在哪里","战歌侦查骑兵地图"}},{q="战歌侦查骑兵会主动攻击联盟玩家吗？",a="不会。尽管她被标记为部落PvP战斗单位，但她对路过的联盟玩家保持中立态度，只有在先受到攻击时才会出于自卫进行反击。",al={"她具有攻击性吗","战歌侦查骑兵会攻击联盟吗","战歌侦查骑兵仇恨"}},{q="她在战歌氏族的行动中担任什么角色？",a="她担任前线侦察兵，守望着灰谷与艾萨拉之间的边界，观察威胁并通过侦察兵向氏族领导层提供现场报告。",al={"侦查骑兵职责","战歌侦查骑兵目的","她为什么在这里"}},{q="击败战歌侦查骑兵会有任何奖励吗？",a="不会，击败她没有任何战利品或特殊装备，其作用仅在于清理道路或破坏该地区的部落侦察活动。",al={"战歌侦查骑兵掉落","她会掉落战利品吗","侦查骑兵掉落物品"}}},fx={["472f02e2"]={q="战歌侦查骑兵是谁？",a="她是一名隶属战歌氏族的兽人斥候，驻扎在灰谷最东侧的边境。她配备远程弓箭和致命的毒刺，像她这样的侦查骑兵时刻监视着连接争夺中的森林与远方岩石之地的边界。",al={"战歌侦查骑兵是谁","战歌侦查骑兵的身份","战歌侦查骑兵是什么"}},adb29283={q="战歌侦查骑兵属于哪一方？",a="她直接效忠战歌氏族，忠于部落。虽然她属于部落阵营，但她只是在道路上戒备巡守，除非受到挑衅，否则不会主动追捕路过的旅人。",al={"战歌侦查骑兵的阵营","战歌侦查骑兵属于部落吗","战歌侦查骑兵属于哪一方"}},["0609b6c9"]={q="战歌侦查骑兵为何驻扎在这里？",a="她负责守望连接灰谷东部与艾萨拉的重要通道。她的驻地确保部落信使、伐木车队和旅人能够报告边境局势变化，为地区动向提供至关重要的情报更新。",al={"战歌侦查骑兵为何在这里","战歌侦查骑兵的驻地用途","她为何在路上"}},["38bf0594"]={q="战歌侦查骑兵隶属于谁？",a="她为战歌氏族效力，配合氏族在灰谷开展大规模伐木和军事行动。她的报告让氏族的哨站及时了解领地边缘发生的事情。",al={"战歌侦查骑兵的归属","战歌侦查骑兵为谁效力","战歌侦查骑兵所属氏族"}}},fp="16,394,28.454.0,40.120.0,59.172.0,50.185.0,55.134.0"}
P.entries["npc:watch-captain-parker"] = {n="Watch Captain Parker",s="卫兵帕克是一位警惕的城镇卫兵，驻扎在赤脊山的三角路口哨所。他的职责是巡逻道路并监视具有攻击性的豺狼人族群，作为前往湖畔镇的旅行者的第一道防线。",h="卫兵帕克是一位警惕的城镇卫兵，驻扎在赤脊山的三角路口哨所。他的职责是巡逻道路并监视具有攻击性的豺狼人族群，作为前往湖畔镇的旅行者的第一道防线。",kw={"达希","豺狼人","卫兵帕克","湖畔镇","帕克","赤脊山","三角路口","watch captain parker"},ang={["faction:Alliance"]="帕克代表了一个无力抽调军队保护自身边境的联盟，在困境中孤军奋战的缩影。",["profession:Herbalism"]="帕克为送给达希而寻找新鲜花朵，凸显了赤脊山丘陵间绽放的本地植被那静谧的价值。",["race:Human"]="对于王国的人类来说，帕克提醒着人们，在国家危机期间，正是这些普通的哨兵在竭力维护着王国边远村镇的安宁。"},sec={{t="三角路口的守卫",b="帕克驻守在被称为三角路口的重要路口，时刻监视着连接艾尔文森林、暮色森林和赤脊山的道路。由于暴风城的军事资源捉襟见肘，几乎没有正规的增援部队到达该地区，像帕克这样的孤身守卫承担着确保十字路口不受强盗、潜行野兽和掠夺成性的豺狼人侵扰的重任。"},{t="评估豺狼人威胁",b="帕克目前最关心的是在他哨所北方和东方聚集的豺狼人营地。随着这些族群逐渐向公路逼近，他会派遣身强力壮的旅行者将豺狼人部队集结的消息传达给湖畔镇的菲尔顿副队长。赤脊山族群日益猖獗，对补给车队和寻求前往湖畔镇避难的难民构成了直接威胁。"},{t="一丝温情",b="在偏僻的路边哨所生活可能很凄凉，但小小的善意依然能传达到三角路口。Lakeshire Inn的服务员达希会在帕克巡逻时为他送去一份热腾腾的午餐。帕克深受感动，便请送餐的冒险者去湖畔镇的草药师那里取一束花，作为回礼送给达希，且叮嘱不要告诉草药师这束花是谁要的或送给谁的。"}},faq={{q="卫兵帕克在哪里？",a="帕克驻扎在三角路口，这是一个位于赤脊山西南部，靠近通往暮色森林和艾尔文森林边界的道路交叉口。",al={"帕克位置","帕克在哪里","找到卫兵帕克"}},{q="为什么帕克要孤身一人驻扎在三角路口？",a="他的任务是巡逻南部的道路，并密切监视入侵的豺狼人族群，以确保通往湖畔镇的地区交通和补给路线畅通。",al={"帕克的职责","为什么帕克孤身一人","三角路口守卫"}},{q="帕克在赤脊山监视着哪些威胁？",a="帕克不仅密切关注威胁公路的赤脊山豺狼人族群，还要时刻警惕该地区面临的更广泛的危险，包括石堡的黑石兽人和伊尔加拉之塔附近的影皮豺狼人。",al={"赤脊山威胁","帕克附近的敌人","赤脊山豺狼人威胁"}},{q="帕克和达希是什么关系？",a="达希在Lakeshire Inn工作，她会给驻扎在偏远哨所的帕克送去热午餐。作为回报，帕克请送餐的旅行者从镇上的草药师那里为她取花，以表达他的感激之情和爱慕之意。",al={"达希和帕克","谁是达希","免费的午餐任务剧情"}},{q="为什么帕克得不到来自暴风城的增援？",a="由于瓦里安·乌瑞恩国王失踪，首都陷入内部政治瘫痪，暴风城基本上让赤脊山自生自灭，迫使当地的卫兵和治安官只能依靠四处游历的冒险者。",al={"为什么没有暴风城军队","暴风城对赤脊山的援助","帕克增援"}},{q="卫兵帕克提供哪些任务？",a="帕克会请冒险者向湖畔镇的菲尔顿副队长报告路边集结的豺狼人营地，并协助安排将一束鲜花送回Lakeshire Inn给达希。",al={"帕克任务","来自帕克的任务"}}},fx={bec4d61f={q="Watch Captain Parker 是谁？",a="帕克是湖畔镇卫兵中坚韧可靠的一员，负责守望通往赤脊山的道路。他驻扎在三角路口，那里是连接艾尔文森林、暮色森林和赤脊山的十字路口；他巡逻外围道路，监视敌人动向，并保护前往湖畔镇的旅人。",al={"卫兵帕克是谁","帕克是谁","watch captain parker"}},fd65fed3={q="Watch Captain Parker 属于哪一方？",a="他效忠于暴风王国，作为当地赤脊山卫队的一员为湖畔镇效力。他随时准备协助任何愿意保卫这片饱受战火蹂躏地区、抵御敌对豺狼人和兽人的联盟勇士。",al={"帕克的阵营","帕克是联盟成员吗","帕克为谁效力"}},["39103803"]={q="Watch Captain Parker 想要什么？",a="帕克想阻止步步逼近的豺狼人攻占重要的十字路口，并进一步深入赤脊山。敌军围困之下，他正在寻找有能力的冒险者，让他们侦察周边荒野、清剿豺狼人群，并将情况报告带回湖畔镇的上级那里。",al={"帕克的目标","帕克需要什么","帕克的动机"}}},fp="20,255,25.373.0,26.370.0,17.433.0,30.161.0,57.164.0,46.229.0,41.227.0,57.214.0,36.192.0"}
P.entries["npc:watcher-backus"] = {n="守夜人巴库斯",s="守夜人巴库斯是守夜人的一员，负责在暮色森林阴暗的道路上巡逻。他驻扎在夜色镇与密斯特曼托庄园之间的大道上，时刻警惕着潜伏的亡灵和形迹可疑的旅人。由于他的岗哨位置关键，他也成为了那些调查与暴风城政治阴谋有关的可疑动向的人们的重要联络人。",h="守夜人巴库斯是守夜人的一员，负责在暮色森林阴暗的道路上巡逻。他驻扎在夜色镇与密斯特曼托庄园之间的大道上，时刻警惕着潜伏的亡灵和形迹可疑的旅人。由于他的岗哨位置关键，他也成为了那些调查与暴风城政治阴谋有关的可疑动向的人们的...",kw={"巴库斯","夜色镇","暮色森林","密斯特曼托庄园","守夜人","失踪的外交官","守夜人巴库斯"},ang={["faction:Alliance"]="对于追踪失踪外交官的联盟特工来说，巴库斯是一个至关重要的联系人，他能提供前线的一手情报。",["race:Human"]="巴库斯展现了暮色森林人类守卫的坚韧，尽管被首府抛弃，却依然决心守卫这片土地上的道路。"},sec={{t="阴影中的巡逻",b="和守夜人的其他成员一样，守夜人巴库斯面对的是在这片被诅咒的林地中极为艰难的困境。暮色森林几乎得不到暴风城守军的支持，只能由当地的志愿者独自守护这些雾气弥漫的小径。巴库斯独自一人在通往夜色镇北部的路上巡逻，在经过阴森的密斯特曼托庄园附近时，还要时刻防备野兽和食尸鬼的袭击。"},{t="路上的岗哨",b="由于他的巡逻路线较为偏僻，巴库斯目睹了许多穿行在夜色镇边缘的过往行人。当皇家调查员追查一名失踪的高级外交官到南方时，巴库斯成为了关键的证人，他回想起了腐草农场周围迪菲亚兄弟会的异常活动。"}},faq={{q="守夜人巴库斯是谁？",a="守夜人巴库斯是一名人类卫兵，隶属于守夜人部队。这是一支饱受折磨的城镇民兵，负责保卫夜色镇和暮色森林的道路。",al={"巴库斯是谁","守夜人巴库斯的职责","巴库斯 暮色森林"}},{q="在哪里可以找到守夜人巴库斯？",a="他在暮色森林中，从夜色镇向北延伸至密斯特曼托庄园的主路上巡逻。",al={"巴库斯在哪里","巴库斯的位置","巴库斯的巡逻路线"}},{q="什么是守夜人？",a="守夜人是由暮色森林的公民组成的当地志愿者民兵组织，旨在暴风城撤走其正式驻军后，抵御亡灵、狼人和凶残野兽的威胁。",al={"什么是守夜人","守夜人 暮色森林","夜色镇卫兵"}},{q="巴库斯与“失踪的外交官”任务有什么关系？",a="在调查一名暴风城外交官失踪事件期间，线索将冒险者引向了暮色森林。巴库斯回忆起近期腐草农场附近的迪菲亚活动，并协助查阅了从他们在当地的藏身处找回的文件。",al={"巴库斯 失踪的外交官","失踪的外交官任务 巴库斯"}},{q="守夜人巴库斯有什么城镇八卦吗？",a="在夜色镇，同为守夜人卫兵的守夜人布朗内尔据说对巴库斯有着难以言说的爱慕之情，这为阴郁的暮色森林带来了一丝轻松的城镇趣闻。",al={"巴库斯 布朗内尔","守夜人布朗内尔的爱慕"}},{q="为什么巴库斯要在密斯特曼托庄园附近独自巡逻？",a="守夜人的人手在整个地区捉襟见肘。由于缺乏能够执行任务的守卫，守夜人被迫独自承担漫长且危险的巡逻路线。",al={"为什么独自巡逻","巴库斯的危险"}}},fx={cd7ae440={q="守夜人巴库斯属于哪一方？",a="守夜人巴库斯坚定地与守夜人组织以及身陷困境的夜色镇居民站在一起。作为暮色森林尽职尽责的本地守卫之一，他为联盟效力，听命于镇上的领导者，日夜冒险巡守阴暗的道路，保护旅人和居民免受潜伏在黑暗中的嗜血怪物侵害。",al={"巴库斯的阵营","守夜人巴库斯为谁效力","守夜人巴库斯的效忠对象"}},f48ed911={q="守夜人巴库斯想要什么？",a="巴库斯想要守护暮色森林的道路，并在这片被暴风城军队遗弃的土地上伸张正义。旅人或调查者把麻烦带到他面前时，他会着力清除危险的嫌疑者、确保巡逻路线没有亡灵，并守护夜色镇苦苦支撑的居民。",al={"守夜人巴库斯的目标","巴库斯想做什么","巴库斯的动机"}},["8919f8c2"]={q="守夜人巴库斯与谁有关联？",a="除了并肩巡守阴森树林的守夜人同伴，巴库斯还引起了卫兵同僚守夜人布朗内尔的注意；她对他显然心怀爱慕。他也与调查道路上可疑活动的探员合作，因此直接参与了涉及暴风城的更广泛调查。",al={"守夜人巴库斯的人际关系","谁认识守夜人巴库斯","守夜人巴库斯的关系"}}},fp="14,365,23.382.0,16.278.1,22.153.0,34.90.0,24.187.0,49.224.1,57.162.0,51.178.0"}
P.entries["npc:watcher-dodds"] = {n="守夜人道茨",s="守夜人道茨是一名人类斥候，隶属于驻扎在暮色森林中心十字路口的守夜人。他独自一人驻守在远离夜色镇城墙的路边哨所，监视着步步紧逼的恐怖事物，并委派旅行者清除当地的巨型蜘蛛群体。",h="守夜人道茨是一名人类斥候，隶属于驻扎在暮色森林中心十字路口的守夜人。他独自一人驻守在远离夜色镇城墙的路边哨所，监视着步步紧逼的恐怖事物，并委派旅行者清除当地的巨型蜘蛛群体。",kw={"althea ebonlocke","十字路口","夜色镇","暮色森林","守夜人","蜘蛛","守夜人道茨"},ang={["faction:Alliance"]="对于在暮色森林中穿行的联盟旅行者来说，道茨的营火标志着夜色镇和西部土地之间的黑暗道路上，为数不多的几个可提供友好支持的安全据点之一。"},sec={{t="十字路口哨位",b="守夜人道茨在指挥官阿尔泰娅·埃伯洛克的麾下服役，镇守着连接夜色镇、乌鸦岭和逆风小径的十字路口处的一处暴露哨位。当夜色镇居民蜷缩在围墙内时，像道茨这样的前哨士兵却时刻游走在狼群、贪婪的食尸鬼和巨大的蜘蛛之间，在刀尖上生活。从他的路边营地出发，他时刻注视着逼近的威胁，并招募路过的雇佣兵在蜘蛛彻底淹没这些荒废的道路之前，清除那些从灌木丛中爬出来的蜘蛛。"}},faq={{q="守夜人道茨是谁？",a="他是一名人类守夜人成员，该民兵组织旨在保卫暮色森林，抵御困扰该地区的亡灵和野兽。他驻扎在中心十字路口，而不是夜色镇的安全地带。",al={"守夜人道茨","道茨是谁","暮色森林道茨"}},{q="我在哪里可以找到守夜人道茨？",a="道茨在暮色森林中心的主要十字路口维持着一个小型的路边营地，夜色镇、乌鸦岭和南方关口之间的道路都在那里交汇。",al={"守夜人道茨位置","道茨在哪里","道茨坐标"}},{q="他为什么要杀蜘蛛？",a="巨大的毒蜘蛛侵扰着周围的树林，并以使用道路的流浪者和补给信使为食。道茨依靠过往的冒险者来捕杀毒蛛，以防止道路变得完全无法通行。",al={"八条腿的威胁","道茨蜘蛛任务","为什么要杀蜘蛛"}},{q="守夜人道茨向谁汇报？",a="他向指挥官阿尔泰娅·埃伯洛克汇报，她是守夜人的首领，总部设在夜色镇的市政厅。",al={"道茨指挥官","谁领导守夜人"}}},fx={["06158fc1"]={q="守夜人道茨属于哪一方？",a="守夜人道茨为守夜人组织效力。这支坚毅的民兵守卫着身陷困境的夜色镇和暮色森林的道路。由此，他效忠于暮色森林的居民和大联盟；当暴风城无法抽调正规驻军前来支援时，他仍坚守岗位，对抗阴影中的威胁。",al={"道茨的阵营","守夜人道茨效忠于谁","道茨为谁而战"}},["7998837a"]={q="守夜人道茨为何驻扎在十字路口？",a="守夜人道茨在暮色森林的主要十字路口设立哨站，以确保重要道路畅通。由于缺乏有力增援，他监视荒野，并招募有能力的旅人来遏制掠食性怪物，尤其是巨型蜘蛛和逼近的野兽；这些威胁会袭击任何走出夜色镇近郊的人。",al={"道茨为何在这里","守夜人道茨驻地的原因","道茨为何在这里扎营"}}},fp="13,269,23.549.0,21.215.0,31.161.0,32.233.0,33.116.0"}
P.entries["npc:wilder-thistlenettle"] = {n="维尔德·蓟草",s="维尔德·蓟草是一位矮人矿工，他闷闷不乐地坐在暴风城Dwarven District的一家酒馆里。作为死亡矿井深处一场惨烈矿难的唯一幸存者，他始终被他所在的矿业公司以及他兄弟的悲惨命运所困扰。",h="维尔德·蓟草是一位矮人矿工，他闷闷不乐地坐在暴风城Dwarven District的一家酒馆里。作为死亡矿井深处一场惨烈矿难的唯一幸存者，他始终被他所在的矿业公司以及他兄弟的悲惨命运所困扰。",kw={"兄弟","塌方","死亡矿井","dwarven district","矿工","暴风城","蓟草","维尔德"},ang={["profession:Mining"]="矿工们很容易理解地下深处矿脉的危险，不稳定的地层和被遗忘的黑暗魔法足以掩埋即使是最老练的团队。",["race:Dwarf"]="对于矮人同族来说，维尔德的悲伤引起了强烈的共鸣，这突显了地下挖掘工作中始终存在的危险，以及尊重阵亡公会兄弟的神圣职责。"},sec={{t="苦难的幸存者",b="你可以在Dwarven District东南大门附近的一家酒馆里找到正在借酒消愁的维尔德·蓟草。多年前，他和他的兄弟以及其他同伴一起加入了前往月溪镇死亡矿井深处矿脉的探险队。一场灾难性的塌方将其他人永远封锁在黑暗之中，而维尔德仅仅是勉强逃出生天。"},{t="深渊的亡魂",b="隧道里的灾难并没有随着死亡而平息。维尔德后来得知，他的兄弟和那些失踪的矿工并不仅仅是死于瓦砾之中——黑暗魔法或未竟之事将他们复活成了永不安息的亡灵，没完没了地游荡在这些地下废墟中。在悲痛和幸存者的负罪感折磨下，维尔德希望有勇敢的冒险者愿意深入死亡矿井，找回死难者的遗物，并让他兄弟的灵魂得到最终的安息。"}},faq={{q="我在哪里可以找到维尔德·蓟草？",a="他坐在暴风城Dwarven District内的一家安静酒馆里，就在该区域东南入口右侧。",al={"维尔德·蓟草位置","维尔德在哪里","蓟草暴风城"}},{q="他的兄弟在死亡矿井里发生了什么事？",a="维尔德的兄弟与他们的矿工同伴一起被困在了一次突然的隧道塌方中。维尔德成功逃脱，并一直在寻找那些被困在下面的人的消息。",al={"维尔德兄弟死亡矿井","兄弟发生了什么","蓟草兄弟背景故事"}},{q="维尔德为什么要找冒险者？",a="维尔德请求前往死亡矿井的旅人们从遇难工友身上找回个人矿工工会徽章，并调查他兄弟的遭遇。",al={"维尔德任务","维尔德想要什么","收集记忆任务"}}},fx={["2e3a3cea"]={q="维尔德·蓟草是谁？",a="维尔德·蓟草是一名矮人矿工，目前在暴风城的矮人区借酒消愁。他曾与兄弟一同参加深入死亡矿井的采矿远征，但悲剧在地下深处降临。",al={"维尔德是谁","维尔德·蓟草的背景","关于维尔德·蓟草"}},cb45d77d={q="维尔德·蓟草属于哪一方？",a="维尔德效忠于联盟和自己的矮人同胞。他整日郁郁寡欢地待在暴风城一家空荡荡的酒馆里，寻求值得信赖、敢于进入死亡矿井的联盟冒险者援助。",al={"维尔德·蓟草的阵营","维尔德为谁效力","维尔德是联盟成员吗"}},cf83a843={q="维尔德·蓟草为何来到暴风城？",a="死亡矿井发生灾难性塌方，夺去了他兄弟和同伴的性命；维尔德侥幸逃生后，逃回暴风城寻求庇护。他身心受创、悲痛欲绝，便在矮人区一家安静的酒馆里避难。",al={"维尔德为何在暴风城","维尔德为何在这里","维尔德为何在矮人区"}}},fp="20,236,17.359.0,18.452.1,38.140.0,46.138.0,33.156.0"}
P.entries["npc:wiley-the-black"] = {n="黑衣威利",s="黑衣威利是一名难以捉摸的潜行者，目前躲藏在赤脊山的Lakeshire Inn中。尽管他行踪诡秘且沉默寡言，但他欠格里安·斯托曼一条命，并作为了解迪菲亚潜行者内部情况的重要地下渠道。",h="黑衣威利是一名难以捉摸的潜行者，目前躲藏在赤脊山的Lakeshire Inn中。尽管他行踪诡秘且沉默寡言，但他欠格里安·斯托曼一条命，并作为了解迪菲亚潜行者内部情况的重要地下渠道。",kw={"迪菲亚","格里安·斯托曼","线人","湖畔镇","赤脊山","威利","黑衣威利"},ang={["class:Rogue"]="威利通过间谍技术和情报展示了生存的精妙技艺。对于潜行者来说，他是通过知晓何时交换情报以及偿还谁的恩情来生存的经典案例。",["faction:Alliance"]="由于暴风城的军队不在，联盟依靠像威利这样的非官方资产来拼凑西部荒野中日益恶化的叛乱真相。"},sec={{t="无赖的债务",b="黑衣威利藏身于Lakeshire Inn内，远离西部荒野的公开动乱和赤脊山布满豺狼人的边境，行事十分低调。尽管他本性狡诈、过往可疑，但由于荣誉所系，他必须报答人民军指挥官格里安·斯托曼。斯托曼曾救过威利的命——尽管斯托曼抱怨说当时就该让这个无赖烂掉。当人民军急需了解迪菲亚潜行者阴谋的内幕时，威利就是他们求助的线人，他会不情愿地提供秘密情报以偿还债务。"}},faq={{q="我该在哪里找到黑衣威利？",a="黑衣威利位于赤脊山镇子湖畔镇的Lakeshire Inn内。",al={"威利位置","黑衣威利在哪里","威利赤脊山","湖畔镇旅店威利"}},{q="为什么威利要帮助格里安·斯托曼？",a="格里安·斯托曼过去曾救过威利的命。尽管格里安视他为一个令人恼火的无赖，而威利也不愿冒险，但威利通过传递有关迪菲亚潜行者的重要信息来偿还这份恩情。",al={"为什么帮助格里安","威利与格里安的关系","威利斯托曼债务"}},{q="威利是如何了解迪菲亚潜行者的？",a="威利对地下世界的动向和迪菲亚潜行者的行动有着深入的了解。他通过向格里安·斯托曼披露兄弟会的信息来报恩，但他是否曾经是其成员尚未得到证实。",al={"威利是迪菲亚吗","威利如何得知迪菲亚","威利与迪菲亚的联系"}},{q="他在迪菲亚潜行者的调查中扮演什么角色？",a="当人民军获得指向更大阴谋的神秘线索时，斯托曼会派遣冒险者前往湖畔镇给威利带话。威利会审视局势，并提供一份书面笔记，引导人民军找到策划叛乱的头目。",al={"威利的任务角色","威利做什么","迪菲亚潜行者威利"}}},fx={["03fe7b6d"]={q="黑衣威利是谁？",a="黑衣威利是个行踪诡秘的盗贼，目前住在湖畔镇的旅店里。他是个与非法势力有所勾连的恶棍，却对迪菲亚潜行者及其在各个人类王国境内的秘密行动掌握着出人意料的深入情报。",al={"威利是谁","黑衣威利的背景","关于黑衣威利"}},["7107b7b4"]={q="黑衣威利属于哪一方？",a="威利主要只顾自己，尽量远离联盟的正式政治事务。不过，由于格里安·斯托曼曾救过他的命，威利愿意帮助人民军对付迪菲亚，以偿还这份私人恩情。",al={"威利效忠联盟吗","黑衣威利的阵营","黑衣威利的效忠对象"}},["72fbb4af"]={q="黑衣威利想要什么？",a="威利想还清欠格里安·斯托曼的人情债，并避免惹上麻烦。提供有关迪菲亚潜行者的关键情报，既能让他履行对格里安的承诺，也能偿还这笔债，同时与西部荒野的战事保持安全距离。",al={"威利想要什么","黑衣威利的目标","威利为何提供帮助"}},["9b688ede"]={q="黑衣威利为何在赤脊山？",a="威利住进了湖畔镇旅店楼上的房间，远离西部荒野，也避开暴风城当局的直接管辖。在赤脊山落脚让他能够低调行事，同时留意各方动静。",al={"威利为何在湖畔镇","威利为何在这里","威利在赤脊山"}}},fp="15,232,18.622.0,33.116.0,39.233.0,49.194.0,51.280.0"}
P.entries["npc:willem"] = {n="Willem",s="维里副队长是暴风城军队的一名人类士兵，驻扎在北郡修道院外。他服役于治安官玛克布莱德麾下，担任主要的实地联络员，负责引导新兵处理北郡山谷的当地威胁。他目前的当务之急是压制迪菲亚潜行者日益增长的入侵。",h="维里副队长是暴风城军队的一名人类士兵，驻扎在北郡修道院外。他服役于治安官玛克布莱德麾下，担任主要的实地联络员，负责引导新兵处理北郡山谷的当地威胁。他目前的当务之急是压制迪菲亚潜行者日益增长的入侵。",kw={"迪菲亚潜行者","维里副队长","艾尔文森林","garrick padfoot","治安官玛克布莱德","北郡","北郡修道院","willem"},ang={["class:Warrior"]="战士新兵们会发现维里副队长是一位实用的实地联络员，他引导他们发挥武力清除强盗，恢复王国的秩序。",["faction:Alliance"]="Willem是联盟国内安全最初的接触点，这表明了迪菲亚潜行者的动乱对即使是宁静的艾尔文腹地也构成了多么深远的威胁。",["race:Human"]="对于走出北郡修道院、踏入世界的人类来说，维里副队长往往是迎接他们为暴风城王国效力的第一位军官。"},sec={{t="修道院的守卫",b="维里副队长站在距离北郡修道院大门仅几步之遥的地方，代表着暴风城军队在山谷中的前线力量。由于王国的军队分散在多个领土上，兵力捉襟见肘，当地的安全防卫重任便落在了像玛克布莱德驻军这样的小分队身上。Willem负责评估新来的志愿者，并指派他们执行紧急任务，以协助当地居民并保卫山谷周边地区。"},{t="对抗迪菲亚潜行者",b="Willem最关切的问题是迪菲亚潜行者的猖獗活动。佩戴红色头巾的强盗已经直接闯入北郡，偷窃补给品，恐吓像Milly Osworth这样的当地农民，并在周围的葡萄园和山丘建立据点。Willem协调发布了针对像Garrick Padfoot这样的知名恶棍的赏金任务，试图在他们夺取修道院领地之前瓦解他们的领导层。"}},faq={{q="谁是维里副队长？",a="维里副队长是驻扎在艾尔文森林北郡修道院的暴风城军队军官。他服役于治安官玛克布莱德麾下，负责协调新兵保卫山谷，抵御当地威胁。",al={"willem是谁","维里副队长的职责","willem 北郡"}},{q="维里副队长向谁汇报？",a="他直接向治安官玛克布莱德汇报，后者是负责北郡山谷防务和军事行动的高级指挥官。",al={"willem 指挥官","willem的上司是谁","willem 领导"}},{q="为什么Willem要发布针对迪菲亚潜行者的赏金任务？",a="迪菲亚潜行者已经渗透进北郡山谷，威胁修道院并恐吓当地劳工。Willem招募冒险者来削减他们的数量，并铲除像Garrick Padfoot这样的头目以恢复秩序。",al={"为什么要发布迪菲亚潜行者悬赏","willem 红色头巾","willem 迪菲亚潜行者"}},{q="在哪里可以找到维里副队长？",a="Willem站在艾尔文森林北部北郡修道院的正门外，迎接来到庭院的旅行者和新兵。",al={"willem 位置","维里副队长在哪里","寻找willem"}},{q="Willem如何协助当地工人？",a="Willem指挥身强力壮的战士去协助那些生计受到威胁的居民，派遣新兵去帮助果园主Milly Osworth和剥皮师Eagan等人。",al={"willem milly osworth","willem eagan","willem 任务"}},{q="为什么像Willem这样的部队难以独自维持秩序？",a="暴风城正承受着内部压力、政治紧张局势和远方军事承诺的重负。由于King Varian失踪，像北郡这样的驻军必须依靠未经考验的新兵和志愿者来处理国内的动乱。",al={"为什么暴风城军队很弱","为什么北郡防守空虚","暴风城在北郡的兵力"}}},fx={cea9f32f={q="维里副队长属于哪一方？",a="维里副队长是暴风城军队的忠诚士兵，为联盟效力。他在北郡修道院外站岗，维护王国法律，并指引有能力的新兵前去保卫山谷，抵御强盗和窃贼。",al={"willem 的阵营","维里副队长为谁效力","willem 属于联盟还是部落"}},["29d9c6b5"]={q="维里副队长为何在北郡？",a="维里副队长驻扎在北郡修道院外，负责维护秩序，并指引新兵前往最需要他们的地方。王国的防务捉襟见肘，他便担任主要联络人，统筹山谷应对当地威胁。",al={"willem 为何在北郡","willem 为什么来到这里","维里副队长的职责"}}},fp="6,323,23.420.0,22.420.0,21.200.0,33.138.0,45.225.0,33.155.0,41.185.0,62.222.0"}
P.entries["npc:william-pestle"] = {n="威廉·匹斯特",s="威廉·匹斯特是一位人类炼金师，目前暂住在闪金镇的Lion's Pride Inn。他与兄弟摩根·匹斯特一同经营着位于暴风城贸易区的药剂店。他经常雇佣旅行的冒险者去收集一些奇怪的试剂，比如狗头人蜡烛、鱼人海藻以及草药补给。",h="威廉·匹斯特是一位人类炼金师，目前暂住在闪金镇的Lion's Pride Inn。他与兄弟摩根·匹斯特一同经营着位于暴风城贸易区的药剂店。他经常雇佣旅行的冒险者去收集一些奇怪的试剂，比如狗头人蜡烛、鱼人海藻以及草药补给。",kw={"药剂师","收集海藻","闪金镇","狗头人蜡烛","lion's pride inn","马科伦","摩根·匹斯特","匹斯特","斯通菲尔德","威廉·匹斯特"},ang={["faction:Alliance"]="威廉依靠途径闪金镇的联盟新兵从周边森林获取物资，协助维持暴风城贸易区重要药品和杂货的供应。",["profession:Herbalism"]="对于游历闪金镇的草药师来说，威廉·匹斯特代表了植物采集贸易的实践方面，不断将野外生长的植物和奇特的水生海藻转化为实用的药剂。"},sec={{t="海外药剂师",b="当他的兄弟摩根·匹斯特在暴风城的贸易区打理药剂店的柜台时，威廉则在闪金镇的Lion's Pride Inn开展业务。驻扎在艾尔文森林让他能够与当地的采集者密切合作，并获得城市店铺持续需要的原材料。他定期将物资运回首都，确保暴风城的市民能够获得充足的疗伤药膏、药水和药粉。"},{t="奇特的试剂",b="威廉的工艺往往需要一些不同寻常的成分，不仅仅是简单的田野草药。他经常委托新人们去收集艾尔文森林里泛滥的狗头人所携带的蜡烛，以及从闪金镇东侧水晶湖的鱼人身上取得的水晶海藻。虽然这些调配物在外行人看来很奇怪，但威廉坚称这些奇怪的成分具有强大的炼金功效。"},{t="年轻爱情的调配药",b="除了常规的交易外，威廉还是米尔德·斯通菲尔德的老朋友。当年轻的恋人梅贝尔·马科伦和托米·乔·斯通菲尔德发现自己夹在两个因积怨而争斗不休的农场主家庭之间时，威廉同意为他们调制一种隐形水。通过使用从当地水域收集的海藻，他制作的药水让梅贝尔能够悄悄溜走，去和托米·乔幽会。"}},faq={{q="威廉·匹斯特是谁？",a="威廉·匹斯特是一位生活在闪金镇Lion's Pride Inn的炼金师和药剂师。他与身处暴风城的兄弟摩根一起，为王国收集并准备炼金补给。",al={"威廉·匹斯特","闪金镇炼金师","匹斯特是谁"}},{q="在哪里可以找到威廉·匹斯特？",a="他在位于艾尔文森林闪金镇的Lion's Pride Inn里面。",al={"匹斯特位置","威廉·匹斯特在哪里","威廉·匹斯特 闪金镇"}},{q="威廉用狗头人蜡烛做什么？",a="威廉收集艾尔文森林矿洞里狗头人携带的蜡烛，将它们熔化并提炼出牛脂，用于他的炼金合剂和日常药剂库存。",al={"为什么匹斯特需要蜡烛","狗头人蜡烛的用途"}},{q="为什么威廉需要水晶海藻？",a="威廉使用从艾尔文森林当地湖泊中采集的水晶海藻来配制隐形水，帮助梅贝尔·马科伦溜过家人的视线去见托米·乔·斯通菲尔德。",al={"为什么要收集海藻","鱼人海藻的用途"}},{q="威廉·匹斯特与暴风城有什么联系？",a="威廉和他的兄弟摩根在暴风城的贸易区经营着药剂店。威廉在闪金镇收集原材料，并协调发货回城里的店铺。",al={"匹斯特 暴风城","威廉·匹斯特药剂店"}},{q="威廉与斯通菲尔德和马科伦家族有什么关系？",a="威廉是米尔德·斯通菲尔德的老朋友。他通过调制一种秘密药水来帮助托米·乔·斯通菲尔德和梅贝尔·马科伦，使他们能够绕过各自家庭之间激烈的争斗。",al={"斯通菲尔德 马科伦 匹斯特","威廉·匹斯特爱情任务"}}},fx={["2d067923"]={q="威廉·匹斯特想要什么？",a="威廉在寻找稀有而特别的试剂，用于调制炼金药剂。他常请路过的冒险者大量收集狗头人的蜡烛，以获取蜡料，并从当地湖泊采集水晶海带，再将这些材料用于酿造强效的隐形水等药剂。",al={"威廉·匹斯特需要什么","威廉·匹斯特的目标","威廉·匹斯特的炼金材料"}},["8d6a9bd2"]={q="威廉·匹斯特为什么在闪金镇？",a="威廉和他的兄弟摩根在暴风城的Trade District经营一家药剂店，而威廉住在闪金镇的Lion's Pride Inn，亲自收集乡间试剂，并在艾尔文森林协助米尔德丽德·石田等相识多年的朋友。",al={"威廉·匹斯特为什么在这里","威廉为什么在闪金镇","威廉·匹斯特为什么在lion's pride inn"}},["520b1b0a"]={q="威廉·匹斯特属于哪一方？",a="威廉是暴风王国的忠诚臣民，也是联盟的自豪成员。他以狮王之傲旅店为据点，运用炼金术专长、调制药剂，并帮助当地居民解决日常难题，为社区服务。",al={"威廉·匹斯特的阵营","威廉·匹斯特是联盟成员吗","威廉·匹斯特效忠于谁"}}},fp="14,300,17.463.0,16.405.0,27.380.1,22.199.0,34.82.0,41.174.0,35.175.1,54.180.0,58.173.1"}
P.entries["npc:williden-marshal"] = {n="威利德·马绍尔",s="威利德·马绍尔是马绍尔探险队的雄心勃勃的人类领袖，其基地位于安戈洛环形山北部的马绍尔营地。由于受到稀有植物、神秘水晶和利润丰厚的科学研究的吸引，他带领团队进入了这座环形山，却眼睁睁地看着他们位于低地的营地被盆地内的巨兽所摧毁。",h="威利德·马绍尔是马绍尔探险队的雄心勃勃的人类领袖，其基地位于安戈洛环形山北部的马绍尔营地。由于受到稀有植物、神秘水晶和利润丰厚的科学研究的吸引，他带领团队进入了这座环形山，却眼睁睁地看着他们位于低地的营地被盆地内的巨兽所...",kw={"魔暴龙","马绍尔探险队","马绍尔营地","能量水晶","斯帕克·奈矿工","安戈洛环形山","威利德·马绍尔"},ang={["faction:Alliance"]="尽管由于野外环形山的客观条件，他们被迫保持中立经营，但威利德及其核心团队与联盟腹地有着深厚的文化和贸易联系。",["profession:Herbalism"]="威利德的探险队之所以被安戈洛吸引，很大程度上是因为这里拥有艾泽拉斯其他任何地方都找不到的独特史前植被。",["race:Human"]="威利德代表了人类深远的好奇心和商业野心，他从东部王国一路跋涉，来到了卡利姆多南部的未开化深处。"},sec={{t="岌岌可危的立足点",b="威利德·马绍尔带领一支完整的科学考察队深入安戈洛环形山，寻求财富和发现。出于对外星水晶、未分类植物和未开发资源的传闻的兴趣，他在山谷底部建立了多个前哨营地。然而，原始的荒野很快便与他们为敌。环形山的凶猛野兽拆毁了他们的研究哨所，迫使威利德和幸存者撤退到北部的悬崖上，建立了马绍尔营地。"},{t="挽救梦想",b="尽管被赶到了环形山的山脊边缘，威利德依然拒绝收拾行装放弃他的投资。他利用营地相对安全的地理位置，雇佣路过的冒险者深入危险的低地，回收丢失的食物箱、昂贵的科学仪器以及他个人的探险日志。虽然与他亲密的战友（如斯帕克·奈矿工）常简单地称他为“威尔”，但他对这次冒险非常认真——即便在他们下方的山谷中有泰坦巨兽徘徊，他也坚持要恢复他们的工作。"},{t="家族纽带",b="威利德并不是环形山中唯一的马绍尔：霍兰妮·马绍尔与他同姓，并在马绍尔营地与他并肩工作。他们共同选择了卡利姆多南部的这片原始荒野，而威利德始终坚信，安戈洛的水晶矿藏和古老的奥秘蕴藏着真正的财富。"}},faq={{q="威利德·马绍尔是谁？",a="威利德·马绍尔是一位人类探险家，也是马绍尔探险队的指挥官。他带领一支由研究人员和冒险者组成的队伍进入安戈洛环形山，研究其奇异的水晶和植物，寻求知识与利益。",al={"威利德·马绍尔是谁","威利德·马绍尔背景故事","谁领导马绍尔营地"}},{q="为什么探险队躲在一个洞穴里？",a="探险队最初在安戈洛的低地建立了多个研究基地。然而，探险队低估了安戈洛的凶险，环形山中的巨型捕食者摧毁了这些营地，迫使幸存者逃往马绍尔营地所在的北部岩架。",al={"为什么营地在洞穴里","探险队营地发生了什么","为什么马绍尔撤退"}},{q="威利德要求冒险者做什么？",a="威利德要求有能力的探险者勇敢地前往危险的环形山盆地，从他们破败的营地中回收补给品，包括遗弃的食物储备、精密的科学研究设备以及他丢失的探险日志。",al={"威利德任务","探险队救援","威利德想要什么"}},{q="是什么把威利德带到了安戈洛环形山？",a="他是为了寻找环形山独特的资源而来：稀有的植物、神秘的彩色能量水晶、古老的地质秘密，以及科学发现带回故乡后将产生的巨额经济利润。",al={"为什么来安戈洛","威利德·马绍尔的动机","威利德在研究什么"}},{q="威利德有家人吗？",a="是的。他的妹妹霍兰妮·马绍尔作为马绍尔探险队的一员，在马绍尔营地与他一起工作。",al={"威利德的兄弟","利文斯顿·马绍尔","马绍尔家族"}},{q="威利德·马绍尔是属于联盟还是部落？",a="虽然是人类，但威利德在马绍尔营地经营的是一个中立的科学考察队。他乐意接受联盟和部落冒险者的帮助，只要他们愿意帮他回收补给品并清除环形山中的威胁。",al={"威利德是联盟吗","部落可以和威利德交谈吗","马绍尔营地阵营"}}},fp="16,328,21.492.0,19.517.0,11.313.0,24.215.0,41.292.0,42.207.0,59.215.0,30.111.0,55.224.0"}
P.entries["npc:winna-hazzard"] = {n="温娜·哈萨德",s="温娜·哈萨德是一位古怪的被遗忘者研究员，驻扎在费伍德森林的血毒岗哨。她带着一只猫科动物伙伴，并以那疯狂的笑声而闻名，她研究着这片受到枯萎病影响的生态系统，并利用该地区受腐蚀的动物群进行令人不安的实验。",h="温娜·哈萨德是一位古怪的被遗忘者研究员，驻扎在费伍德森林的血毒岗哨。她带着一只猫科动物伙伴，并以那疯狂的笑声而闻名，她研究着这片受到枯萎病影响的生态系统，并利用该地区受腐蚀的动物群进行令人不安的实验。",kw={"血毒岗哨","费伍德森林","被遗忘者","小猫","温娜·哈萨德"},ang={["faction:Horde"]="温娜安稳地驻扎在血毒岗哨，招募路过的部落旅行者为她搜集用于古怪研究的受腐蚀试剂。",["race:Undead"]="温娜体现了被遗忘者阴暗古怪的一面，对腐蚀表现出鲁莽的好奇心，而不顾及自然和谐。"},sec={{t="一位古怪的研究员",b="温娜·哈萨德代表了被遗忘者对费伍德森林非自然衰败的兴趣。她驻扎在部落据点血毒岗哨，花费大量时间观察当地野生动物，并利用受污染的水源和毒液样本制定实验。她那欢快而狂躁的举止往往掩盖了冷酷的动机，当她利用从土地中提取的受污染液体去腐蚀陪伴在她身边的小猫时，这一点就显而易见了。"}},faq={{q="温娜·哈萨德是谁？",a="温娜·哈萨德是一位被遗忘者任务发布者，位于费伍德森林中北部的血毒岗哨。她调查费伍德森林的腐蚀影响，并指派冒险者从荒野中收集样本。",al={"温娜·哈萨德","温娜是谁","费伍德森林的猫夫人"}},{q="她的小猫发生了什么事？",a="当冒险者带给温娜一瓶装满来自周围森林的受腐蚀液体时，她会直接喂给她的小猫，将这只生物变异为受腐蚀的猫，然后疯狂地大笑。",al={"温娜的小猫","受腐蚀的猫","费伍德森林猫实验"}},{q="温娜·哈萨德在费伍德森林的目标是什么？",a="像许多被遗忘者药剂师和学者一样，温娜试图理解并利用生物枯萎病，利用费伍德森林普遍存在的腐蚀来研究它如何改变和扭曲活着的野兽。",al={"温娜·哈萨德的动机","为什么温娜在费伍德森林"}}},fp="13,270,21.417.0,21.207.0,27.205.1,40.189.0"}
P.entries["npc:winstone-wolfe"] = {n="温斯顿·沃尔菲",s="温斯顿·沃尔菲是隶属于神秘的拉文霍德组织的人类特工，驻扎在坐落于希尔斯布莱德与奥特兰克山脉之间隐秘庄园内。他负责监视庄园的地面及看守人员，是这个隐秘的盗贼与刺客联盟中值得信赖的联络人之一。",h="温斯顿·沃尔菲是隶属于神秘的拉文霍德组织的人类特工，驻扎在坐落于希尔斯布莱德与奥特兰克山脉之间隐秘庄园内。他负责监视庄园的地面及看守人员，是这个隐秘的盗贼与刺客联盟中值得信赖的联络人之一。",kw={"奥特兰克","希尔斯布莱德","拉文霍德","拉文霍德庄园","潜行者","温斯顿·沃尔菲"},ang={["class:Rogue"]="作为拉文霍德庄园的一名特工，对于那些前往群山中向该组织磨练技艺的潜行者们来说，沃尔菲是个熟悉的面孔。"},sec={{t="山中的清道夫",b="温斯顿·沃尔菲隐居在拉文霍德庄园的隐秘山谷中，在乔拉齐·拉文霍德公爵的组织中效力。沃尔菲沉默寡言、警惕且务实，他是处理庄园内外事务的得力助手之一，确保只有那些具备足够谨慎和天赋的人才能在不受打扰的情况下进入此地。"}},faq={{q="温斯顿·沃尔菲是谁？",a="温斯顿·沃尔菲是一名活跃在拉文霍德庄园的人类潜行者。拉文霍德庄园是刺客联盟的秘密总部，隐藏在希尔斯布莱德丘陵和奥特兰克山脉的高处。",al={"沃尔菲是谁","温斯顿·沃尔菲背景故事","拉文霍德沃尔菲"}},{q="在哪里可以找到温斯顿·沃尔菲？",a="他位于拉文霍德庄园，可以通过希尔斯布莱德丘陵的敦霍尔德城堡区域向北延伸穿过山脉的一条秘道抵达。",al={"沃尔菲位置","温斯顿·沃尔菲在哪里","寻找温斯顿·沃尔菲"}},{q="他在拉文霍德的角色是什么？",a="沃尔菲作为庄园的特工和守卫，负责监视庄园区域，并协助该组织处理隐秘的后勤事务。",al={"沃尔菲做什么","沃尔菲的目的"}}},fx={["2ccf77f3"]={q="温斯顿·沃尔菲站在哪一方？",a="温斯顿·沃尔菲效力于拉文霍德——一个以拉文霍德庄园为据点的隐秘盗贼与刺客组织。庄园藏在俯瞰希尔斯布莱德和奥特兰克的山麓之中；他为这个公会效力，而非为联盟或部落效力。",al={"温斯顿·沃尔菲的阵营","温斯顿·沃尔菲为谁效力","温斯顿·沃尔菲是拉文霍德的人吗"}},d63e8a08={q="温斯顿·沃尔菲为什么在这里？",a="沃尔菲以拉文霍德庄园为据点，是这个隐秘山地盗贼组织的一员。无论是巡视庄园，还是协助公会同伴执行任务，他都留在公会处理事务的地方。",al={"温斯顿·沃尔菲为什么在拉文霍德","温斯顿·沃尔菲为什么在拉文霍德庄园"}}},fp="14,329,24.326.0,22.184.0,32.162.0,31.146.0"}
P.entries["npc:witch-doctor-jin-zil"] = {n="巫医金吉尔",s="巫医金吉尔是一位暗矛巨魔神秘家，居住在石爪山脉南部玛拉卡金的一处洞穴中。作为达索克·快刀和暗影猎手Rokhan的多年老友，他利用黑暗巫毒和仪式法术来对抗部落在当地的敌人。",h="巫医金吉尔是一位暗矛巨魔神秘家，居住在石爪山脉南部玛拉卡金的一处洞穴中。作为达索克·快刀和暗影猎手Rokhan的多年老友，他利用黑暗巫毒和仪式法术来对抗部落在当地的敌人。",kw={"达索克","金吉尔","玛拉卡金","rokhan","石爪山脉","巫毒","巫医"},ang={["faction:Horde"]="随着部落巩固了石爪山脉的南部路径，金吉尔在与哨所斥候并肩作战的同时，提供了必要的神秘学防御和情报支持。",["race:Troll"]="金吉尔代表了移植到卡利姆多崎岖荒野中的传统暗矛巫医习俗，并与Rokhan等重要人物保持着深厚的联系。"},sec={{t="玛拉卡金的隐士",b="隐居在玛拉卡金营地上方东侧的洞穴中，金吉尔远离部落的海岸家园，修习着古老的丛林巨魔技艺。在翻腾的大锅和被囚禁的俘虏环绕下，他从石爪山脉的峭壁中收集异域试剂，为保卫部落的山地营地编织强大的祝福与诅咒。"},{t="一位值得信赖的老兵",b="金吉尔并非普通的江湖术士；他与部落的高级斥候有着一段充满传奇色彩的交情，达索克·快刀和著名的暗影猎手Rokhan都是他的老友。当达索克协调针对暗夜精灵和鹰身人的前线冲突时，金吉尔则在精神和炼金层面上进行着战争，利用他的森林魔法和不稳定的巫毒，在威胁抵达营地大门之前就将其削弱。"}},faq={{q="我在哪里可以找到巫医金吉尔？",a="他居住在玛拉卡金东侧的一个洞穴里，玛拉卡金是一个坐落在石爪山脉南部隘口的部落定居点。",al={"金吉尔位置","金吉尔在哪里","金吉尔洞穴"}},{q="金吉尔与Rokhan和达索克·快刀有什么关系？",a="金吉尔是达索克·快刀和暗影猎手Rokhan的老友兼挚友。由于这些长久以来的联系，整个石爪山脉的斥候在应对异常威胁时，都会依赖他的魔法专长。",al={"金吉尔的朋友","达索克和金吉尔","与rokhan的联系"}},{q="为什么金吉尔的洞穴里会有俘虏？",a="金吉尔将俘虏的敌人关押在他的洞穴工坊里。作为一名传统的巫医，他利用俘虏和原始试剂来测试诅咒、占卜征兆，并为定居点制作防御性的巫毒。",al={"金吉尔的俘虏","金吉尔的牢笼","为什么金吉尔有俘虏"}},{q="他会给部落冒险者什么样的任务？",a="他派遣旅行者前往石爪山脉各地收集用于其森林魔法的神秘材料，并利用它们来维持其巫毒仪式。",al={"金吉尔的任务","金吉尔想要什么"}}},fx={["3fda7979"]={q="巫医金吉尔是谁？",a="巫医金吉尔是一名暗矛丛林巨魔秘术师，居住在石爪山脉崎岖的山丘中。他藏身于一处俯瞰玛拉卡金的幽暗洞穴，施行深奥的巫毒仪式，调制强大的森林魔法，并以古老技艺和灵性洞察协助部落在边疆的斗争。",al={"金吉尔是谁","金吉尔的背景","巫医金吉尔的身份"}},["088a369a"]={q="巫医金吉尔站在哪一方？",a="金吉尔坚定地支持部落，尤其与暗矛巨魔同胞以及在卡利姆多开辟据点的盟友关系密切。他运用魔法仪式和战略援助支持当地哨站，也协助奉酋长之命穿行山路的勇士。",al={"金吉尔属于部落吗","巫医金吉尔的阵营","金吉尔效忠谁"}},["6d312970"]={q="巫医金吉尔想要什么？",a="金吉尔需要石爪山脉野生生物和魔法异象所产生的强力试剂，包括野兽身上的材料，用来施展巫毒护符和诅咒。他希望借由调制出的祝福增强部落的势力，守住山口，抵御步步逼近的威胁。",al={"金吉尔想要什么","金吉尔的目标","金吉尔为什么要收集材料"}},["5da55a71"]={q="巫医金吉尔为什么在石爪山脉？",a="他在玛拉卡金建起隐秘的居所，以观察石爪山脉变幻莫测的灵体和原始自然魔法。他从这处岩石哨所施展法术、监视南方道路，为守卫当地的部落斥候提供超自然的洞察和附魔援助。",al={"金吉尔为什么在石爪山脉","金吉尔为什么在玛拉卡金","金吉尔为什么在这里"}}},fp="20,265,24.358.0,17.419.0,38.136.0,62.221.0,44.211.0,53.128.0"}
P.entries["npc:witch-doctor-uzer-i"] = {n="巫医尤克里",s="巫医尤克里是一位丛林巨魔神秘主义者，居住在菲拉斯原始森林中的莫沙彻营地。他致力于提升部落的魔法能力，并研究如何捕获和利用穆塞克——即强大自然生物的精神精华。通过捕获这些古老的森林之魂，尤克里试图将那些暗夜精灵传统上所青睐的原始能量直接引导至附魔武器之中。",h="巫医尤克里是一位丛林巨魔神秘主义者，居住在菲拉斯原始森林中的莫沙彻营地。他致力于提升部落的魔法能力，并研究如何捕获和利用穆塞克——即强大自然生物的精神精华。通过捕获这些古老的森林之魂，尤克里试图将那些暗夜精灵传统上所青睐...",kw={"莫沙彻营地","精龙","菲拉斯","山岭巨人","穆塞克","尼尔鲁·火刃","树人","尤克里","巫医"},ang={["class:Shaman"]="萨满祭司会认同尤克里对与灵魂沟通的执着追求，尽管他对元素和野性精华的强硬收容更倾向于强制性的巫术，而非敬畏的平衡。",["faction:Horde"]="尤克里为部落提供了一条掌握卡利姆多荒野原始魔法的途径，将这片土地的精神力量转而用来对付联盟及其盟友，如暗夜精灵。",["race:NightElf"]="暗夜精灵视尤克里的行为为亵渎，他们惊恐地看着树人、角鹰兽和山岭巨人等神圣生物被屠杀并被束缚在武器之中。",["race:Troll"]="尤克里代表了经典的巨魔精神实践，运用传统的巫医仪式、缩小容器和巫毒术来驾驭原始的生命精华。"},sec={{t="收集穆塞克",b="巫医尤克里扎根于传统的巨魔通灵术，花费了大量心血研究菲拉斯未开化荒野中所蕴含的自然魔法。他认为暗夜精灵千百年来一直利用森林野兽的灵魂，并认为现在是部落攫取这些原始力量的时候了。他的研究核心是穆塞克这一概念：即残留在生物体内的充满活力的精神精华。为了收集它，尤克里制作了特殊的容器，能够在倒下的生物逃逸的灵魂消散之前迅速将其缩小，从而使这种精华得以储存和研究。"},{t="可怕的交易与仪式容器",b="完善这些收纳容器需要尤克里无法在野外独自获取的黑暗且强力的试剂。在杀掉一名游荡在菲拉斯林地的联盟矮人后，尤克里切下了入侵者的头颅，并安排将其交易给居住在奥格瑞玛阴暗的Cleft of Shadow中的术士尼尔鲁·火刃。作为这笔可怕交易的回报，尼尔鲁提供了完成束缚附魔所需的稀有草药。有了这些组件，尤克里成功制作出了第一批容器，为捕获当地枭兽、角鹰兽、精龙、树人和山岭巨人的灵魂铺平了道路。"},{t="锻造灵魂武器",b="提取穆塞克仅仅是尤克里宏大野心的第一阶段。这位巫医从他所捕获灵魂的生物身上收集坚韧的肌腱、附魔矿石和石化的碎木，并将物质材料与受缚的穆塞克融合在一起。通过这些仪式，他学会了将古老的森林之魂永久束缚在武器和装备中，为部落提供了带有魔法力量的武器。除了仪式性的工艺外，尤克里对艾泽拉斯各地隐藏的强大地点保持着浓厚的兴趣，并积极追踪有关古老而沉没的沉没的神庙的传闻。"}},faq={{q="什么是穆塞克？",a="穆塞克是活体生物残留的精神精华。巫医尤克里使用特别附魔的容器来缩小被杀死的野兽和自然守护者的躯体，在它们逃逸的灵魂消散到周围环境中之前将其捕获。",al={"什么是穆塞克","穆塞克的含义","定义穆塞克"}},{q="为什么尤克里要向奥格瑞玛运送矮人的头颅？",a="尤克里需要专门的试剂来准备他的仪式容器。在菲拉斯杀死一名联盟矮人后，他将砍下的头颅送给了奥格瑞玛的尼尔鲁·火刃，以换取束缚穆塞克灵魂所需的稀有草药。",al={"矮人头颅任务","为什么把头颅送给尼尔鲁","尼尔鲁·火刃的交易"}},{q="尤克里以哪些生物为目标？",a="他的目标是那些与自然界有着内在联系并长期与暗夜精灵结盟的生物，包括来自辛特兰的枭兽，以及菲拉斯的角鹰兽、精龙、树人和山岭巨人。",al={"尤克里狩猎什么野兽","尤克里的灵魂目标","哪些动物可以提取穆塞克"}},{q="尤克里如何处理捕获的灵魂？",a="一旦与碎木、肌腱和矿石等原始自然材料收集在一起，尤克里就会将穆塞克永久束缚在武器中，从而使普通武器灌注古老森林守护者的原始神秘力量。",al={"灵魂武器","为什么要收集穆塞克","穆塞克武器奖励"}},{q="巫医尤克里在哪里？",a="巫医尤克里居住在莫沙彻营地，这是位于菲拉斯中部茂密且危险的树冠层中的主要部落定居点。",al={"尤克里的位置","尤克里在哪里","巫医尤克里的地点"}},{q="尤克里对沉没的神庙了解多少？",a="作为一名研究艾泽拉斯各地灵魂和神秘地点的学者，尤克里听闻了被称为沉没的神庙的沉没的阿塔莱圣殿，并指引感兴趣的冒险者去找地精探险家玛尔冯·瑞文斯克进行进一步调查。",al={"尤克里与沉没的神庙","沉没的神庙菲拉斯任务","阿塔哈卡神庙与尤克里"}}},fp="19,441,21.620.0,34.624.1,25.600.0,15.262.0,47.239.0,42.219.0,46.218.0,37.136.0,46.245.0"}
P.entries["npc:wizbang-cranktoggle"] = {n="维兹班恩·曲针",s="维兹班恩·曲针是一位古怪的侏儒工程师，居住在奥伯丁旅店的楼上。尽管远离诺莫瑞根或铁炉堡那些充满齿轮的大厅，他仍将自己的机械天赋用在了黑海岸荒野中建立和维护自动通讯装置上，这些装置被称为“蜂鸣盒”。",h="维兹班恩·曲针是一位古怪的侏儒工程师，居住在奥伯丁旅店的楼上。尽管远离诺莫瑞根或铁炉堡那些充满齿轮的大厅，他仍将自己的机械天赋用在了黑海岸荒野中建立和维护自动通讯装置上，这些装置被称为“蜂鸣盒”。",kw={"奥伯丁","蜂鸣盒","曲针","黑海岸","蓄电装置","工程师","加法接头","侏儒","维兹班恩"},ang={["profession:Engineering"]="维兹班恩对诸如加法接头和蓄电装置等定制工具的依赖，突显了典型的侏儒思维：用机械手段解决未知土地上的后勤问题。",["race:Gnome"]="看到一位侏儒在卡利姆多崎岖的海岸线上操作实验性通讯网络，这不禁让人回想起诺莫瑞根那永不枯竭的创造力。",["race:NightElf"]="虽然精灵哨兵和德鲁伊依靠小精灵、信使和自然纽带，但维兹班恩却给黑海岸的神圣森林带来了嘈杂、旋转的齿轮和金属盒子。"},sec={{t="奥伯丁的工程师",b="虽然奥伯丁的暗夜精灵更喜欢与自然和谐共处，并遵循古老的习俗，但维兹班恩·曲针代表了联盟那种充满好奇心和创造力的特质。维兹班恩栖身于奥伯丁旅店的顶楼，周围堆满了工具和零件。他对卡利姆多的神圣德鲁伊传统并不怎么在意，而是专注于解决现实的机械难题。"},{t="蜂鸣盒网络",b="维兹班恩在黑海岸的主要项目是部署和维护他那独特的发明：蜂鸣盒。这些装置旨在在崎岖漫长的海岸线上建立自动报告和远程通讯系统，但它们经常因海岸气候和当地野生动物的敌意而受损。维兹班恩经常招募旅行者来收集零件、打捞加法接头（gaffer jacks）和回收蓄电装置（electropellers），以维持他机械监控系统的运作。"}},faq={{q="我在哪里可以找到维兹班恩·曲针？",a="维兹班恩位于黑海岸的暗夜精灵定居点奥伯丁，就在旅店的楼上。",al={"维兹班恩位置","维兹班恩在哪","奥伯丁侏儒位置"}},{q="维兹班恩·曲针在黑海岸做什么？",a="他是一位联盟工程师，致力于在黑海岸的荒野中建立和维护一个名为“蜂鸣盒”的自动通讯机器网络。",al={"为什么维兹班恩在奥伯丁","维兹班恩的目标","维兹班恩做什么"}},{q="什么是蜂鸣盒？",a="蜂鸣盒是维兹班恩·曲针发明的一种机械通讯和监控装置，用于在黑海岸各地传递信息，不过它们经常因为野生动物的攻击和恶劣的天气而损坏。",al={"什么是蜂鸣盒","蜂鸣盒背景","蜂鸣盒用途"}},{q="维兹班恩与其他侏儒有亲属关系吗？",a="他和迪尔伯·曲针（Delber Cranktoggle）拥有相同的姓氏，这表明他们可能属于同一个发明家家族。",al={"曲针家族","迪尔伯·曲针是谁","维兹班恩的亲属"}},{q="为什么暗夜精灵会容忍他在奥伯丁进行修理工作？",a="作为大联盟的成员，暗夜精灵为奥伯丁的盟友种族提供食宿和庇护，即便侏儒的装置与精灵传统的和谐风格形成了鲜明对比。",al={"暗夜精灵与侏儒","为什么允许在奥伯丁进行工程学活动"}},{q="维兹班恩会给冒险者布置什么任务？",a="维兹班恩请求冒险者协助修理和调试他的蜂鸣盒机器，这需要他们在海岸线上搜寻诸如蓄电装置和加法接头之类的特殊零件。",al={"维兹班恩任务","维兹班恩提供什么任务"}}},fx={["97312084"]={q="维兹班恩·曲针是谁？",a="维兹班恩·曲针是一名精明能干的侏儒工程师，目前住在奥伯丁旅店的楼上。暗夜精灵通常更亲近自然，而非轰鸣的机器；维兹班恩却在海岸开设了据点，用来部署和维护一套名为蜂鸣器的机械装置网络。",al={"维兹班恩是谁","维兹班恩·曲针的身份","奥伯丁的侏儒是谁"}},a9ee7ecd={q="维兹班恩·曲针站在哪一方？",a="维兹班恩效忠诺莫瑞根和大联盟。他在暗夜精灵的款待下公开驻扎于奥伯丁，为途经黑海岸的联盟旅客提供技术专长和任务。",al={"维兹班恩·曲针的阵营","维兹班恩是联盟的人吗","维兹班恩·曲针效忠谁"}},be17225f={q="维兹班恩·曲针想要什么？",a="维兹班恩想用自己发明的蜂鸣器，在黑海岸建立并维护自动化的监视与通信网络。当地荒野危机四伏，机器也常常故障，所以他需要冒险者收集本地材料、生物部件和机械零件，以维持网络运作。",al={"维兹班恩想要什么","维兹班恩·曲针的目标","维兹班恩为什么需要零件"}}},fp="19,332,24.396.0,19.483.0,37.112.0,47.166.0,19.209.0,39.104.0,59.191.0,44.173.0"}
P.entries["npc:wizlo-bearingshiner"] = {n="维兹罗",s="维兹罗是一位被困在千针石林白沙岗哨的地精技师。作为半人马袭击商队的唯一幸存者，他招募过往的旅人去从残骸中取回一个贵重的超适应齿轮。",h="维兹罗是一位被困在千针石林白沙岗哨的地精技师。作为半人马袭击商队的唯一幸存者，他招募过往的旅人去从残骸中取回一个贵重的超适应齿轮。",kw={"地精工程师","超适应齿轮","千针石林","白沙岗哨","维兹罗"},ang={["faction:Horde"]="在白沙岗哨与当地的牛头人一起露营时，部落的旅行者可以很方便地利用维兹罗的机械专长来获取有用的零件。",["profession:Engineering"]="工程师们或许会同情维兹罗想要取回那个神秘的超适应齿轮并探明其用途的愿望。"},sec={{t="岗哨的技师",b="维兹罗待在白沙岗哨的牛头人身边，滞留在了这条峡谷之路上。半人马袭击了他的商队，使他成了唯一的幸存者。他的客户还在等待他们的货物，他很担心自己无法按时交付。"},{t="搁浅的货物",b="维兹罗最好的小装置挂在白沙岗哨北面他那损毁的商队旁的一只凶猛豹子的脖子上。即使是半人马也会避开那只野兽。维兹罗向旅人提供笼子的钥匙，并以报酬作为交换请他们取回超适应齿轮，尽管他承认自己还没搞清楚这装置到底是干什么用的。"}},faq={{q="维兹罗是谁？",a="维兹罗是一位地精技师，在商队遭遇半人马袭击后，他被困在了千针石林的白沙岗哨。他正在寻求帮助，希望能从一只被关在笼子里的豹子身上取回超适应齿轮。",al={"维兹罗","维兹罗是谁","白沙岗哨的地精"}},{q="我能在哪里找到维兹罗？",a="他位于千针石林的白沙岗哨，那是一个靠近伊索克营地的部落营地。",al={"维兹罗的位置","维兹罗在哪里","寻找维兹罗"}},{q="他在进行什么样的实验？",a="维兹罗正试图取回他的超适应齿轮。他承认自己还需要弄明白它的用途；这个装置的具体功能尚不明确。",al={"维兹罗的任务","维兹罗是做什么的","维兹罗的小装置"}},{q="为什么一个地精会在白沙岗哨与部落合作？",a="对维兹罗来说，白沙岗哨是一个意外的落脚点。附近的半人马袭击了他的商队，当他的客户等待货物时，他被迫困在这里。",al={"为什么维兹罗在这里","维兹罗是部落的吗","白沙岗哨的地精"}},{q="维兹罗属于热砂港吗？",a="目前没有证据表明维兹罗隶属于热砂港。他驻扎在白沙岗哨的部落营地，主要关心的是取回他的货物并交付给客户。",al={"维兹罗的阵营","热砂港的维兹罗","维兹罗与热砂港"}},{q="什么是超适应齿轮？",a="超适应齿轮是一个贵重的装置，被挂在维兹罗损毁商队旁的一只笼中豹身上。它的确切用途未知——甚至连维兹罗本人也说他还没弄明白它是干什么用的。",al={"超适应齿轮","维兹罗的装置","齿轮任务"}}},fx={["7d59faba"]={q="维兹罗想要什么？",a="维兹罗想从看守着他那辆在白沙岗哨以北损毁的篷车的黑豹身上找回超适应齿轮。半人马袭击了篷车，害他困在此地，而他的客户还在等着货物。",al={"维兹罗想要什么","维兹罗的目标","维兹罗的实验"}},["1b304945"]={q="维兹罗为什么在千针石林？",a="半人马袭击了维兹罗附近的篷车，白沙岗哨便成了他意料之外的落脚处。他是唯一的幸存者，还在担心客户们等着收货。",al={"维兹罗为什么在这里","维兹罗为什么在千针石林","维兹罗为什么在白沙岗哨"}}},fp="19,227,23.275.0,19.307.0,27.194.0,37.99.0,37.150.0,58.145.0,45.182.0,33.190.0"}
P.entries["npc:wizzle-brassbolts"] = {n="维兹尔·铜栓",s="维兹尔·铜栓是一位侏儒工程师，驻扎在千针石林盐碱地的沙漠赛道，与他的技师同伴们一起工作。他与沙漠赛道的侏儒赛车队合作，寻求耐用的本地材料来加固他们的实验性火箭车。",h="维兹尔·铜栓是一位侏儒工程师，驻扎在千针石林盐碱地的沙漠赛道，与他的技师同伴们一起工作。他与沙漠赛道的侏儒赛车队合作，寻求耐用的本地材料来加固他们的实验性火箭车。",kw={"铜栓","沙漠赛道","飞行员比罗·长须","火箭车","闪光平原","千针石林","维兹尔"},ang={["profession:Engineering"]="维兹尔体现了侏儒工程学的理念：将高速机器推向极限，并在金属板失效时依靠不同寻常的结构加固手段。",["race:Gnome"]="造访闪光平原的侏儒们会在维兹尔身上找到志同道合的伙伴，他顽固地决心用精湛的工艺击败锈水财阀地精的鲁莽装置。"},sec={{t="在盐碱地上的修补工作",b="在闪光平原滚滚的热浪中，侏儒与地精工程学之间的竞争以高速火箭车比赛的形式展开。维兹尔·铜栓作为侏儒赛道团队的一员，努力使他们的车辆在极高速度和腐蚀性盐分的侵蚀下保持完好。为了加固机器，他招募冒险者去狩猎当地的野生动物——例如在盆地中徘徊的坚硬乌龟——并收集它们坚硬的壳，以制造足以容纳他兄弟所研发的强腐蚀性新型火箭燃料的燃料箱。"},{t="远方的朋友",b="维兹尔与世界各地的朋友保持着密切的联系，其中包括飞行员比罗·长须，他会派信使为兄弟们送来赛车头盔。有了这样的帮助，维兹尔让侏儒车队在闪光平原这个偏远且环境恶劣的测试场上依然能够获得补给。"}},faq={{q="我在哪里可以找到维兹尔·铜栓？",a="维兹尔·铜栓位于千针石林东南部的闪光平原上的沙漠赛道。他站在侏儒维修团队和他们的机械设备中间。",al={"维兹尔位置","维兹尔·铜栓在哪里","维兹尔·铜栓地图"}},{q="维兹尔为什么要收集龟壳？",a="他的兄弟正在设计一种威力极强的新型火箭燃料，这种燃料甚至能腐蚀穿车辆的底盘。维兹尔利用闪光平原上陆龟坚如磐石的壳来制造能够盛放这种燃料的新型燃料箱。",al={"硬化龟壳任务","为什么维兹尔需要龟壳","赛道龟壳"}},{q="铜栓兄弟是谁？",a="铜栓兄弟是指维兹尔和他的兄弟菲兹尔以及里兹尔，他们是侏儒技师，在沙漠赛道经营着侏儒火箭车队，与地精进行竞赛。飞行员比罗·长须是他们的朋友。",al={"铜栓家族","铜栓兄弟","维兹尔的兄弟"}},{q="维兹尔对部落玩家友好吗？",a="是的。沙漠赛道是中立区域，维兹尔的个人任务，例如收集硬化龟壳，对部落和联盟的冒险者都是开放的。",al={"部落可以和维兹尔对话吗","维兹尔·铜栓 部落"}}},fx={ae9cecf8={q="维兹尔·铜栓是谁？",al={"维兹尔是谁","维兹尔·铜栓的背景","维兹尔·铜栓是谁"}},["704bc566"]={q="维兹尔·铜栓想要什么？",a="维兹尔想从各地搜集稀有而坚固的材料，以加固并完善她的工程造物。无论是收集坚硬的龟壳，还是获取尾鳍之类的强大野兽部件，她都要依靠勇敢的旅人带来机械测试所需的奇异材料。",al={"维兹尔想要什么","维兹尔·铜栓的目标","维兹尔·铜栓的任务"}},["96d92e19"]={q="维兹尔·铜栓为什么在这里？",a="维兹尔驻扎在闪光平原的沙漠赛道，支持侏儒工程工作，以及与地精对手之间持续进行的车辆竞赛。广阔平坦的盐碱盆地是测试高速机械和实验性装置的理想场所。",al={"维兹尔为什么在这里","维兹尔为什么在沙漠赛道","维兹尔为什么在千针石林"}}},fp="17,259,27.539.0,25.286.0,35.182.0,39.214.0,32.212.0,36.160.0"}
P.entries["npc:wizzlecrank-s-shredder"] = {n="维兹克兰克的伐木机",s="维兹克兰克的伐木机是一台困在贫瘠之地北部淤泥沼泽污秽深处的荆棘谷地精伐木机。地精飞行员维兹克兰克爬进去想偷走它，但没有钥匙机器就无法移动，它就这样停在充满敌意的荆棘谷地精操作员中间。帮助启动它的引擎是这个被困飞行员进行绝望逃亡的唯一途径。",h="维兹克兰克的伐木机是一台困在贫瘠之地北部淤泥沼泽污秽深处的荆棘谷地精伐木机。地精飞行员维兹克兰克爬进去想偷走它，但没有钥匙机器就无法移动，它就这样停在充满敌意的荆棘谷地精操作员中间。帮助启动它的引擎是这个被困飞行员进行绝...",kw={"贫瘠之地","点火","飞行员维兹克兰克","淤泥沼泽","逃生","荆棘谷地精","维兹克兰克","维兹克兰克的伐木机"},ang={["faction:Horde"]="虽然部落通常鄙视荆棘谷地精在贫瘠之地的滥砍滥伐和有毒开发，但帮助一位误入歧途的飞行员提供了一个绝佳的理由去捣毁他们的钻探行动。",["profession:Engineering"]="地精伐木机是原始蒸汽与活塞技术的奇迹，不过飞行员维兹克兰克的困境也证明了专有点火系统在野外有多么容易出岔子。"},sec={{t="困在淤泥中",b="在油污遍地、污染严重的淤泥沼泽盆地深处，停放着无法动弹的维兹克兰克的伐木机，周围全是充满敌意的荆棘谷地精雇佣兵。里面的地精维兹克兰克跳进这台荆棘谷地精的机器试图偷走它，却发现需要一把钥匙才能解锁它的驱动柱。当另一名伐木机操作员询问是否一切正常时，他惊慌失措地谎称出了机械故障。现在他被困在里面，周围全是敌对的守卫和监工，他希望有人能在荆棘谷地精起疑之前取来钥匙。"},{t="哐当哐当的突围",b="一旦拿到从吊车顶端控制室主管那里取来的打火钥匙，伐木机就会伴随着剧烈的碰撞声重新启动。凭借旋转的叶片和厚重的金属装甲，飞行员维兹克兰克驾驶着这台笨重的机器强行突破了围困的雇佣兵防御，并依靠好心的路人将这台脆弱的机器护送出盆地，抵达安全地带。"}},faq={{q="谁在维兹克兰克的伐木机里？",a="这台机械步行机由飞行员维兹克兰克驾驶，这是一名爬进荆棘谷地精的机器想要偷走它，结果发现自己被困在荆棘谷地精领地中心且没有钥匙的地精。",al={"谁驾驶伐木机","飞行员维兹克兰克","维兹克兰克的伐木机里是谁"}},{q="为什么伐木机会搁浅在淤泥沼泽？",a="维兹克兰克跳进伐木机时并没有意识到他需要钥匙来解锁驱动柱。在被充满敌意的荆棘谷地精劳工、钻探工和守卫包围的情况下，他告诉一名起疑的操作员说机器出了机械故障，现在正躲在里面等待有人从吊车顶端的主管那里取来钥匙。",al={"伐木机为什么被困","维兹克兰克被困","伐木机怎么了"}},{q="为什么伐木机有时会消失？",a="如果伐木机没有出现在淤泥沼泽的北部洼地，说明有其他旅行者刚刚启动了点火程序，正在护送维兹克兰克前往安全地带。护送任务结束后不久，伐木机就会重新出现在起始位置。",al={"伐木机消失了","维兹克兰克的伐木机在哪里","伐木机不见了"}},{q="荆棘谷地精在淤泥沼泽做什么？",a="荆棘谷地精正在疯狂地掠夺贫瘠之地北部，开采原油、焦油和木材，将原本的自然水源变成了一个充斥着雇佣暴徒和工头的有毒油沼。",al={"什么是淤泥沼泽","荆棘谷地精淤泥沼泽"}}},fx={["8b008c47"]={q="维兹尔克兰站在哪一方？",a="飞行员维兹尔克兰并非荆棘谷地精的成员。他与棘齿城的斯布特瓦夫合作，钻进风险投资公司的伐木机里把它偷了出来。他被困在淤泥沼泽腹地的敌对风险投资公司地盘上，只能指望路过的任意阵营冒险者取来钥匙，并护送他安全脱身。",al={"维兹尔克兰的阵营","维兹尔克兰是部落的人吗","维兹尔克兰为谁效力"}},["0d614a8d"]={q="维兹尔克兰想要什么？",a="维兹尔克兰只想发动偷来的伐木机，顺利逃离淤泥沼泽。他被凶恶的风险投资公司工人和致命机械困住，需要有人取来机器钥匙，护送他穿过敌人的防线，安全脱身。",al={"维兹尔克兰需要什么","维兹尔克兰的伐木机目标","维兹尔克兰的动机"}}},fp="22,377,21.553.0,21.397.1,37.206.0,43.317.0,38.258.0,48.210.0"}
P.entries["npc:wrenix-the-wretched"] = {n="卑鄙的维尼克斯",s="卑鄙的维尼克斯是一名地精修理工，驻扎在繁忙的港口城镇棘齿城。他在自己那台奇特的精密装置旁工作，为那些寻求破解坚固锁具并劫掠安全储藏物的人提供专业的协助。",h="卑鄙的维尼克斯是一名地精修理工，驻扎在繁忙的港口城镇棘齿城。他在自己那台奇特的精密装置旁工作，为那些寻求破解坚固锁具并劫掠安全储藏物的人提供专业的协助。",kw={"贫瘠之地","精密装置","地精","开锁","海盗","棘齿城","维尼克斯","卑鄙的"},ang={["class:Rogue"]="对于年轻的潜行者来说，维尼克斯是学习开锁技艺的重要导师，他提供了在南海海盗的宝箱上练习绕过安全装置技术所需的工具和任务。",["profession:Engineering"]="维尼克斯那台古怪的精密装置是热砂港小玩意的典型代表——吵闹、反复无常，但在进行精密工作时却异常有效。"},sec={{t="棘齿城的修理工",b="卑鄙的维尼克斯被发现闲坐在棘齿城地精港口那台古怪的机器旁，他代表了热砂港投机取巧、务实的精神。尽管他的绰号听起来有些落魄，但他拥有关于机械、装置以及开锁和回收工艺的专业知识，这使他成为活跃在海岸线上、渴望成为恶棍和侦察兵的冒险者们不可或缺的联络人。"},{t="精密装置",b="紧挨着维尼克斯摆放的是他引以为傲的精密装置，这台嗡嗡作响的机器是地精独创性的证明。维尼克斯利用这台设备和他自己的机械专业知识，为那些试图在商旅海岸找回被南海海盗窃取的违禁品的行动者们提供专业工具，例如盗贼工具和开锁器。"}},faq={{q="卑鄙的维尼克斯是谁？",a="维尼克斯是一位居住在贫瘠之地棘齿城的地精修理工。他在自己的精密装置旁工作，经营专业的装置和开锁工具。",al={"维尼克斯","维尼克斯是谁","卑鄙的维尼克斯"}},{q="去哪里可以找到维尼克斯？",a="维尼克斯位于贫瘠之地东海岸的棘齿城港口镇，他正站在自己那台大型机械设备旁。",al={"维尼克斯位置","维尼克斯在哪","棘齿城维尼克斯"}},{q="他旁边的精密装置是什么？",a="那是维尼克斯个人设计研发的地精装置，用于修理、诊断工作以及制作精密盗贼工具等专用仪器。",al={"精密装置","维尼克斯的机器","那台机器是什么"}},{q="为什么他要帮助冒险者对抗南海自由海盗？",a="贫瘠之地海岸上的南海海盗将贵重的战利品囤积在带锁的宝箱中。维尼克斯利用他的机械工具帮助足智多谋的潜行者撬开那些宝箱，以实现共同获利。",al={"为什么对抗南海海盗","劫掠者的劫掠传说","维尼克斯与海盗"}}},fx={["6e51c7f3"]={q="卑鄙的维尼克斯站在哪一方？",a="维尼克斯效力于以棘齿城为据点的热砂港。和港口里的大多数地精一样，他最看重的是贸易、务实的生意和自己的性命，而非联盟与部落之间更大的战争。只要愿意做生意或出手解决当地麻烦，他对任何旅人都保持中立。",al={"维尼克斯的阵营","维尼克斯为谁效力","维尼克斯效忠谁"}},eba18045={q="卑鄙的维尼克斯为什么在棘齿城？",a="维尼克斯靠棘齿城繁忙的码头谋生，摆弄着他那套古怪的齿轮装置。棘齿城总有源源不断的轻信冒险者、拾荒者和无赖，是古怪的地精发明家雇人干脏活、守护自己贸易利益免受附近海岸威胁的理想边疆港湾。",al={"维尼克斯为什么在这里","维尼克斯为什么在棘齿城","是什么把维尼克斯带到棘齿城"}}},fp="19,236,19.405.0,25.354.0,27.167.0,26.131.0,46.156.0,63.191.0"}
P.entries["npc:wynne-larson"] = {n="维恩·拉尔森",s="维恩·拉尔森是一位在暴风城法师区经营的人类裁缝兼长袍商人。由于达拉然和奎尔萨拉斯这些历史悠久的奥术纺织中心在第三次战争中被毁，她不得不依靠本地工匠为王国各地的法师供货。她经常指引冒险者施法者去寻找制作强大附魔服饰所需的稀有材料。",h="维恩·拉尔森是一位在暴风城法师区经营的人类裁缝兼长袍商人。由于达拉然和奎尔萨拉斯这些历史悠久的奥术纺织中心在第三次战争中被毁，她不得不依靠本地工匠为王国各地的法师供货。她经常指引冒险者施法者去寻找制作强大附魔服饰所需的稀...",kw={"星纱外衣","达拉然","mage quarter","法力编织长袍","奎尔萨拉斯","长袍商人","暴风城","维恩·拉尔森"},ang={["class:Mage"]="在你的魔法生涯早期，维恩是一位重要的联络人，她会帮助你剪裁标志性的法力编织和星纱外衣。",["faction:Alliance"]="她的店铺展示了暴风城是如何为幸存的联盟种族提供自给自足的奥术工艺品的。",["profession:Tailoring"]="维恩代表了在北方纺织中心崩溃后，裁缝和缝纫师在暴风城所发挥的重要作用。"},sec={{t="新兴的奥术市场",b="第三次战争之前，最精美的织物和附魔服饰都来自达拉然的魔法作坊和高等精灵王国奎尔萨拉斯。这两个北方王国的毁灭摧毁了传统的贸易路线，并使奥术纺织产业遭受重创。像暴风城法师区的维恩·拉尔森这样的商贩不得不做出调整，直接与卢坎·考德尔等本地裁缝和附魔师合作，以满足城市日益增长的长袍和法术编织装备的需求。"},{t="制作法术长袍",b="寻求注入奥术能量服饰的初级和中级法师经常会光顾维恩的店铺。她非常清楚剪裁法力编织长袍或星纱外衣所需的具体材料，常会派遣施法者前往危险地区回收新鲜的蜘蛛丝等奇异试剂。她的努力确保了暴风城的施法者们即便在北方物资短缺的情况下，依然能够有合适的装备。"}},faq={{q="我在哪里可以找到维恩·拉尔森？",a="维恩·拉尔森位于暴风城的法师区，向有志向的施法者出售奥术布甲胸部装备和服饰。",al={"维恩·拉尔森位置","维恩·拉尔森在哪里","暴风城法师长袍商人"}},{q="为什么维恩会提到达拉然和奎尔萨拉斯？",a="从历史上看，达拉然和奎尔萨拉斯是东部王国主要的附魔织物产地。它们在第三次战争中的毁灭切断了进口渠道，迫使暴风城的商人们不得不依靠本地人才和稀有的进口材料。",al={"维恩谈论达拉然","奎尔萨拉斯长袍","为什么长袍很难找"}},{q="哪些任务与维恩·拉尔森有关？",a="维恩协助法师获取定制的奥术服饰，参与的任务线包括收集材料、法力编织长袍、新鲜的蜘蛛丝以及星纱外衣。",al={"维恩·拉尔森任务","暴风城长袍任务","法力编织长袍任务"}},{q="维恩·拉尔森卖什么？",a="她出售一系列基础和中级布质长袍，包括燃烧长袍、多彩长袍、双线长袍和银色长袍。",al={"维恩·拉尔森商品","维恩卖什么长袍"}},{q="维恩在暴风城依靠谁来供应制作材料？",a="维恩提到本地工匠，特别是附魔师卢坎·考德尔和其他城市商人，会介入来编织和附魔她所售卖的商品。",al={"谁制作维恩的长袍","卢坎·考德尔的联系"}},{q="维恩·拉尔森和暴风城的其他拉尔森家族成员有关系吗？",a="她与暴风城的裁缝埃文·拉尔森以及珍妮·拉尔森同姓，这表明这是一个在该市服装行业工作的工匠家族。",al={"暴风城拉尔森家族","埃文·拉尔森","珍妮·拉尔森"}}},fx={["61901341"]={q="维恩·拉尔森是谁？",a="维恩·拉尔森是一位备受尊敬的人类长袍商人，在暴风城的法师区经营生意。她主要服务于施法者和裁缝学徒，出售由当地工匠提供的优质布制衣物和奥术材料。",al={"维恩·拉尔森是谁","维恩·拉尔森身份","维恩是谁"}},f66b818d={q="维恩·拉尔森效忠于哪一方？",a="维恩·拉尔森是暴风城的忠诚市民，也是联盟的一员。她与当地的人类工匠和城中的法师群体密切合作，为联盟施法者供应精美衣物。",al={"维恩·拉尔森所属阵营","维恩·拉尔森效力于谁","维恩·拉尔森与联盟"}},["3ea6d1a4"]={q="维恩·拉尔森为什么在法师区？",a="维恩在法师区开店，因为暴风城的学者、奥术师和附魔师都聚集于此。出售长袍并协助施法学徒，使这片城区成为她开展生意的理想之地。",al={"维恩为什么在这里","维恩为什么在法师区","维恩·拉尔森所在地点及目的"}},d20d9bb4={q="维恩·拉尔森想要什么？",a="达拉然毁灭、奎尔萨拉斯沦陷之后，精良的魔法纺织品变得稀有。维恩希望通过采购新鲜的蜘蛛丝等稀有材料并支持当地工匠，让暴风城的施法者继续穿上上等衣物。",al={"维恩想要什么","维恩·拉尔森的目标","维恩·拉尔森的动机"}}},fp="12,373,19.485.0,24.453.0,30.134.0,47.258.0,33.182.0,28.149.0,58.154.0,54.159.0"}
P.entries["npc:xavathras"] = {n="萨瓦瑟拉斯",s="萨瓦瑟拉斯是一位邪恶的萨特指挥官，居住在费伍德森林克斯特拉斯废墟的营帐中。他率领着一群翡翠之火萨特，并受命于他的主人萨瓦里克，负责腐化一座古老的月亮井。",h="萨瓦瑟拉斯是一位邪恶的萨特指挥官，居住在费伍德森林克斯特拉斯废墟的营帐中。他率领着一群翡翠之火萨特，并受命于他的主人萨瓦里克，负责腐化一座古老的月亮井。",kw={"克斯特拉斯","费伍德森林","翡翠之火","月亮井","萨特","萨瓦里克","萨瓦瑟拉斯"},ang={["class:Druid"]="德鲁伊们试图消除费伍德森林所遭受的恶魔枯萎病，他们认为萨瓦瑟拉斯蓄意毒害纯净水源的行为是对自然的一种冒犯，必须予以制止。",["race:NightElf"]="对于暗夜精灵而言，萨瓦瑟拉斯代表着他们古老的同胞沦为恶魔野兽的悲剧，同时他也是神圣月亮井的亵渎者。"},sec={{t="克斯特拉斯的腐蚀者",b="在费伍德森林被污染的林地中，克斯特拉斯废墟已经落入了翡翠之火萨特的手中。萨瓦瑟拉斯驻扎在这些精灵石建筑群间的营地里，指挥着手下败坏附近的一座月亮井，并以此效忠于另一位残忍的萨特——萨瓦里克。通过用恶魔能量毒害纯净的水源，萨瓦瑟拉斯加深了笼罩着整片森林的腐化。他的存在直接威胁到了任何试图恢复林地的努力，也引来了如艾瑞丹·蓝风这样的暗夜精灵的愤怒，他们誓要将他除掉。"}},faq={{q="萨瓦瑟拉斯是谁？",a="萨瓦瑟拉斯是一位残忍的萨特首领，统领着盘踞在费伍德森林克斯特拉斯废墟中的翡翠之火萨特。他效忠于萨瓦里克，任务是腐化位于废墟中的古老精灵月亮井。",al={"萨瓦瑟拉斯是谁","萨瓦瑟拉斯背景故事","克斯特拉斯的萨特首领是谁"}},{q="在哪里可以找到萨瓦瑟拉斯？",a="萨瓦瑟拉斯将营地设在克斯特拉斯废墟的萨特帐篷中，这是一处位于费伍德森林中南部的古老暗夜精灵遗迹。",al={"萨瓦瑟拉斯位置","萨瓦瑟拉斯在哪里","克斯特拉斯废墟萨特"}},{q="为什么艾瑞丹·蓝风想要除掉萨瓦瑟拉斯？",a="艾瑞丹·蓝风致力于保卫费伍德森林并阻止恶魔污染的蔓延。萨瓦瑟拉斯正在积极腐化一座月亮井，因此对于那些试图净化这片土地的人来说，除掉他已成为当务之急。",al={"为什么要杀萨瓦瑟拉斯"}},{q="萨瓦瑟拉斯为谁效力？",a="萨瓦瑟拉斯为萨瓦里克效力，后者是另一位在费伍德森林活动的残忍且强大的萨特，致力于推进军团在这片受污染森林中残留的控制。",al={"萨瓦瑟拉斯的主人是谁","萨瓦里克 萨瓦瑟拉斯"}}},fp="9,222,23.533.0,17.220.0,29.137.0,45.226.0,29.160.0"}
P.entries["npc:yaw-sharpmane"] = {n="雅文·刺鬃",s="雅文·刺鬃是一位经验丰富的牛头人猎人训练师，驻守在莫高雷的血蹄村。他指导从纳拉其营地出发的年轻猎人，帮助他们驯服祖先领地上的野生野兽。",h="雅文·刺鬃是一位经验丰富的牛头人猎人训练师，驻守在莫高雷的血蹄村。他指导从纳拉其营地出发的年轻猎人，帮助他们驯服祖先领地上的野生野兽。",kw={"野兽","血蹄村","猎人","莫高雷","刺鬃","驯服","牛头人","训练师","雅文"},ang={["class:Hunter"]="对于离开红云台地安全区域的牛头人猎人来说，雅文·刺鬃是一位必不可少的导师，他会引导你与你的第一个野生伙伴建立羁绊。",["race:Tauren"]="雅文代表了舒哈鲁崇尚与自然和谐共处，并尊崇莫高雷野生野兽之灵的传统。"},sec={{t="平原上的向导",b="雅文·刺鬃身处血蹄村的帐篷与篝火之间，作为一名导师，为牛头人同胞传授射击、追踪和生存之道。在红云台地证明了自己的年轻猎人会被指引到雅文这里，在他们踏入莫高雷更广阔的平原时磨练自己的技艺。"},{t="掌握羁绊",b="雅文最重要的职责是引导新手猎人完成驯服野兽的古老仪式。他会要求初学者与莫高雷当地的野兽建立羁绊，在指导他们如何妥善照料和训练永久同伴之前，考验他们的耐心以及对自然平衡的尊重。"}},faq={{q="雅文·刺鬃是谁？",a="雅文·刺鬃是血蹄村的常驻猎人训练师。他指导年轻的牛头人猎人学习射击、野外生存以及驯服动物伙伴的艺术。",al={"雅文·刺鬃","雅文是谁","血蹄村猎人训练师"}},{q="在哪里可以找到雅文·刺鬃？",a="雅文位于血蹄村，坐落在莫高雷中部，石牛湖畔。",al={"雅文·刺鬃位置","雅文在哪里","雅文坐标"}},{q="雅文·刺鬃教猎人什么？",a="他提供标准的猎人训练，出售基础技能的等级提升，并指引有前途的猎人完成驯服和指挥野兽所需的仪式。",al={"雅文教什么","雅文猎人技能","雅文技能"}},{q="雅文提供哪些任务？",a="雅文提供牛头人版本的野兽驯服任务线，从“猎人之道”开始，并进行“驯服野兽”和“训练野兽”。",al={"雅文任务","雅文·刺鬃任务"}},{q="为什么猎人在10级左右需要找他谈话？",a="当猎人达到他们的第十个季节（10级）时，他们会被派往雅文这里，学习从莫高雷荒野中捕获、喂养和指挥永久动物伙伴的神圣方法。",al={"雅文10级","血蹄村驯服野兽"}},{q="雅文·刺鬃会与非猎人职业互动吗？",a="他会礼貌地与来自其他职业的旅行者交谈，但他的专业知识和特定的任务试炼严格保留给猎人。",al={"雅文与非猎人","其他职业可以和雅文交谈吗"}}},fx={ce9d051b={q="雅文·刺鬃效忠于哪一方？",a="雅文·刺鬃坚定地支持血蹄牛头人和部落。他驻扎在血蹄村，帮助确保莫高雷的年轻守卫熟悉祖先传下来的追踪、射术以及驯服家乡野兽的技艺。",al={"雅文·刺鬃所属阵营","雅文·刺鬃是部落成员吗","雅文·刺鬃的效忠对象"}},e7f68d71={q="雅文·刺鬃想要什么？",a="雅文希望教导新手猎人狩猎的核心传统。他引导年轻的牛头人与自然交流，了解莫高雷的生灵，并掌握古老的驯服野兽仪式，使他们能够在荒野中生存并为部族效力。",al={"雅文·刺鬃的目标","雅文·刺鬃的动机","雅文·刺鬃做什么"}},cc781595={q="雅文·刺鬃为什么在血蹄村？",a="血蹄村是离开纳拉其营地训练场的年轻牛头人的主要集结地。雅文·刺鬃在此指导猎人踏上横越莫高雷的第一段重要旅程，教他们与动物伙伴建立羁绊并精进技艺。",al={"雅文·刺鬃为什么在这里","雅文·刺鬃在血蹄村的目的"}}},fp="13,216,21.311.0,18.309.0,21.179.0,31.100.0,38.159.0,27.165.0,52.178.0,45.148.0"}
P.entries["npc:yeh-kinya"] = {n="叶基亚",s="叶基亚是一位居住在塔纳利斯沙漠海岸热砂港的丛林巨魔学者。他声称为了解黑暗力量而寻求古代知识和文物，并派遣乐意效劳的冒险者前往艾泽拉斯各地，收集失落的巨魔遗物。",h="叶基亚是一位居住在塔纳利斯沙漠海岸热砂港的丛林巨魔学者。他声称为了解黑暗力量而寻求古代知识和文物，并派遣乐意效劳的冒险者前往艾泽拉斯各地，收集失落的巨魔遗物。",kw={"哈卡","铁靴","摩沙鲁","剥魂者","热砂港","塔纳利斯","风蛇","叶基亚"},ang={["class:Priest"]="对灵魂精华敏感的牧师可能会对叶基亚随意收集被困的尖啸者灵魂感到深深的不安。",["race:Troll"]="暗矛巨魔深知哈卡复活会带来致命的危险。"},sec={{t="热砂港的学者",b="叶基亚混迹在热砂港的地精和码头工人之间，将自己塑造成一名安静的历史和灵魂学研究者。他招募旅行者追踪分布在卡利姆多和东部王国的晦涩魔法物品，从辛特兰的远古之卵到埋藏在祖尔法拉克废墟中的预言石板。虽然他声称这些差事是为了对古代巨魔历史进行和平的学术研究，但他对血神哈卡的特别关注引起了警觉观察者的怀疑。"},{t="巨蛇的诡计",b="在学者伪装的背后，叶基亚是剥魂者哈卡的狂热信徒。他收集的每一件文物和灵魂精华都经过精心操弄，为这名可怕的血神在艾泽拉斯的肉身重生做准备。一旦他的阴谋被勘探员铁靴拼凑出来并被揭穿，叶基亚便撕下了友好的伪装。他没有为自己的背叛行为负责，而是变成一条绿色风蛇，越过公海向南海飞去，留下被愚弄的英雄们去尤亚姆巴岛向赞达拉求助。"}},faq={{q="叶基亚是谁？",a="叶基亚是一位丛林巨魔，在塔纳利斯的热砂港水边可以看到他。他以一名寻求历史遗物和灵魂研究的学者的身份自居，对巨魔神哈卡有着浓厚的兴趣。",al={"叶基亚背景故事","叶基亚是谁","叶基亚npc"}},{q="为什么叶基亚想要摩沙鲁的预言和远古之卵？",a="叶基亚声称他需要这些文物来研究古代巨魔历史和灵魂。摩沙鲁石板位于祖尔法拉克的废墟中，而远古之卵则在辛特兰，这两者都与他关注的哈卡有关。",al={"为什么需要远古之卵","摩沙鲁的预言 巨魔","叶基亚的目的"}}},fp="9,258,32.506.0,20.540.2,17.214.2,69.225.2"}
P.entries["npc:yvette-farthing"] = {n="伊维特·法席恩",s="伊维特·法席恩是提瑞斯法林地布瑞尔的一位被遗忘者居民，她与她的父亲库勒曼一同居住在恐惧之末旅店中。尽管她看起来和希尔瓦娜斯的所有子民一样坚毅冷漠，但她内心深处仍保留着一段因天灾军团而被迫终结的凡人恋情的余韵。",h="伊维特·法席恩是提瑞斯法林地布瑞尔的一位被遗忘者居民，她与她的父亲库勒曼一同居住在恐惧之末旅店中。尽管她看起来和希尔瓦娜斯的所有子民一样坚毅冷漠，但她内心深处仍保留着一段因天灾军团而被迫终结的凡人恋情的余韵。",kw={"未送达的信","阿加曼德磨坊","布瑞尔","库勒曼·法席恩","恐惧之末旅店","瑟曼·阿加曼德","提瑞斯法林地","伊维特·法席恩"},ang={["race:Undead"]="伊维特代表了许多被遗忘者所承受的深层情感冲突，在挥之不去的凡人爱情记忆与亡灵苦涩、坚硬的现实之间挣扎。"},sec={{t="磨坊的回响",b="在第三次战争将洛丹伦卷入废墟之前，伊维特曾与阿加曼德磨坊的继承人之一瑟曼·阿加曼德相恋。当天灾瘟疫来袭时，伊维特和她的父亲库勒曼恳求瑟曼放弃产业与他们一同逃离。但瑟曼出于对家族遗产的忠诚拒绝了。两人最终都难逃一死并复生为亡灵，但伊维特在布瑞尔的被遗忘者中找到了容身之所，而瑟曼悲剧般的最终结局对她来说始终是个谜。"},{t="最后的告别",b="在磨坊被攻陷前，瑟曼曾写下一封紧急的情书给伊维特，详细描述了他兄弟戴夫林的背叛，并为自己留下的选择感到悔恨。天灾军团截获了这封信，使其遗落在阿加曼德磨坊的废墟中，直到后来被冒险者找回。在读到瑟曼临终前的忏悔时，伊维特短暂地流露出了真实的凡人绝望，随后强迫自己回归冷漠，因为她深知在这种被遗忘者的残酷现实中，过去的牵绊已无立足之地。"}},faq={{q="伊维特·法席恩是谁？",a="伊维特·法席恩是一位居住在布瑞尔恐惧之末旅店的被遗忘者女性。她是库勒曼·法席恩的女儿，在第三次战争摧毁这个王国之前，她曾生活在提瑞斯法林地的农田中。",al={"伊维特·法席恩背景故事","伊维特是谁","布瑞尔 伊维特"}},{q="伊维特与阿加曼德磨坊有什么联系？",a="在生前，伊维特曾与瑟曼·阿加曼德相恋。当瘟疫威胁该地区时，她曾试图说服他与自己一起逃走，但他选择了留下并保卫他家族的产业。",al={"伊维特 阿加曼德","瑟曼·阿加曼德与伊维特","伊维特的恋人"}},{q="当你把瑟曼的信交给她时会发生什么？",a="当冒险者将瑟曼那封遗失已久的信交给伊维特时，她在读到那些关于爱与背叛的临终遗言时，内心会瞬间被悲伤击碎。然而，她很快又恢复了冷硬的态度，宣称自己现在是被遗忘者，凡人的情感毫无用处。",al={"未送达的信任务","瑟曼的信奖励","伊维特信件反应"}},{q="伊维特的父亲是谁？",a="她的父亲是库勒曼·法席恩，同样也是居住在布瑞尔恐惧之末旅店的一位被遗忘者。他们两人最初都设法幸存并一同逃离，但最终都死于瘟疫并成为了被遗忘者。",al={"伊维特的父亲","库勒曼与伊维特","库勒曼·法席恩是谁"}}},fx={["71e9f93d"]={q="伊维特·法席恩效忠于哪一方？",a="伊维特坚定地支持被遗忘者和部落。尽管凡人生活的残余和旧日恋情仍会勾起痛苦的回忆，她已抛却那些人类情感。如今，她接受了自己的身份：一名侍奉希尔瓦娜斯女王、拥有自由意志的亡灵。",al={"伊维特·法席恩所属阵营","伊维特·法席恩效忠哪方","伊维特效力于谁"}},["99950259"]={q="伊维特·法席恩想要什么？",a="伊维特希望从吞噬她昔日生活的悲剧中得到解脱。天灾入侵时，她逃离了阿加曼德磨坊，而她的恋人瑟曼留了下来；她因此一直怀着未曾言说的悲痛。得知他生命最后时刻的消息后，她终于能够对自己凡人的心关上门，接受自己在被遗忘者中冰冷的生活。",al={"伊维特想要什么","伊维特·法席恩的目标","伊维特·法席恩的动机"}},["8e2cc8a4"]={q="伊维特·法席恩为什么在这里——布瑞尔？",a="阿加曼德磨坊遭到毁灭、洛丹伦因瘟疫而沦陷后，伊维特和她的父亲科尔曼在布瑞尔避难。对于亡灵来说，布瑞尔是首都之外主要的被遗忘者城镇，因此自然成为幸存者重返故土的庇护所。",al={"伊维特·法席恩为什么在布瑞尔","伊维特·法席恩所在地点的原因","伊维特为什么在这里"}}},fp="15,285,19.496.0,16.499.1,23.213.0,45.201.0,54.262.1,23.230.0"}
P.entries["npc:zaldimar-wefhellt"] = {n="扎尔迪玛·维夫希尔特",s="扎尔迪玛·维夫希尔特是一位人类法师训练师，驻扎在闪金镇的Lion's Pride Inn二楼。他为路过艾尔文森林的初出茅庐的施法者们提供指导，并在之后将他们引荐给暴风城中更高阶的导师。",h="扎尔迪玛·维夫希尔特是一位人类法师训练师，驻扎在闪金镇的Lion's Pride Inn二楼。他为路过艾尔文森林的初出茅庐的施法者们提供指导，并在之后将他们引荐给暴风城中更高阶的导师。",kw={"艾尔文森林","闪金镇","lion's pride inn","法师训练师","维夫希尔特","扎尔迪玛"},ang={["class:Mage"]="对于离开北郡修道院的年轻人类法师来说，扎尔迪玛是你在更广阔的世界中遇到的第一位训练师，他会教授早期法术，然后指引你前往暴风城的法师区。",["faction:Alliance"]="扎尔迪玛驻扎在繁忙的Lion's Pride Inn内，确保在艾尔文森林巡逻的联盟施法者无需立即跋涉前往暴风城即可获得魔法指导。"},sec={{t="闪金镇的法师",b="虽然闪金镇的Lion's Pride Inn最出名的是接待疲惫的旅人、喧闹的冒险者和传播当地流言，但其二楼的房间里也住着各种职业的导师。扎尔迪玛·维夫希尔特在二楼的一间卧室里指导法师学徒学习奥术、火焰和冰霜的基础技艺。一旦学徒超出了他的初期教导范畴，他就会指引他们前往暴风城的Mage Quarter，师从詹妮亚·坎农。"}},faq={{q="扎尔迪玛·维夫希尔特是谁？",a="扎尔迪玛·维夫希尔特是一位奥术导师，驻扎在闪金镇的Lion's Pride Inn。他帮助联盟的法师新手学习最初的法术，并引导他们前往暴风城接受进阶训练。",al={"扎尔迪玛是谁","扎尔迪玛·维夫希尔特的作用","闪金镇法师训练师"}},{q="我在哪里可以找到扎尔迪玛·维夫希尔特？",a="他位于闪金镇Lion's Pride Inn的二楼，走上楼梯后最左侧的房间内。",al={"扎尔迪玛位置","扎尔迪玛在哪里","如何找到扎尔迪玛"}},{q="扎尔迪玛会将法师新手送到哪里？",a="一旦法师掌握了基本技能，扎尔迪玛就会指引他们前往暴风城的Mage Quarter，在法师区寻求詹妮亚·坎农的进一步训练。",al={"扎尔迪玛任务","扎尔迪玛指引你去见谁","与詹妮亚交谈任务"}},{q="扎尔迪玛与其他法师有亲属关系吗？",a="目前没有发现他的亲属；他专注于在Lion's Pride Inn进行教学。",al={"维夫希尔特家族","扎尔纳·维夫希尔特","扎尔迪玛亲属"}}},fx={["10a0eae6"]={q="扎尔迪玛·维夫希尔特效忠于哪一方？",a="扎尔迪玛是大联盟的忠诚成员，效力于暴风王国。他驻扎在艾尔文森林腹地，致力于运用奥术技艺指导年轻的施法者，帮助他们挺身守卫王国、维护王权。",al={"扎尔迪玛·维夫希尔特所属阵营","扎尔迪玛是联盟成员吗"}},["063cda12"]={q="扎尔迪玛·维夫希尔特想要什么？",a="扎尔迪玛希望引导初出茅庐的法师渡过奥术研习中的险境。学徒在闪金镇掌握施法的基础原理后，他会指引他们前往更高级的导师处，例如暴风城法师区的詹妮亚·坎农，以进一步精进技艺。",al={"扎尔迪玛·维夫希尔特的动机","扎尔迪玛想要什么"}},d06c7379={q="扎尔迪玛·维夫希尔特为什么在闪金镇？",a="扎尔迪玛住在 Lion's Pride Inn 的楼上，担任闪金镇的法师训练师。闪金镇是刚离开北郡山谷的冒险者必经之地，因此适合他在此接引初学魔法的人，并教他们重要的奥术法术。",al={"扎尔迪玛为什么在这里","扎尔迪玛与 lion's pride inn"}}},fp="17,261,21.436.0,25.207.0,35.122.0,38.167.0,39.80.0"}
P.entries["npc:zamja"] = {n="扎姆沙",s="扎姆沙是一位暗矛巨魔烹饪训练师，在奥格瑞玛精神谷忙碌的走廊中工作。她以挥舞切肉刀稳健的手法而闻名，并指导部落的冒险者如何使用卡利姆多的野兽制作丰盛的餐点。",h="扎姆沙是一位暗矛巨魔烹饪训练师，在奥格瑞玛精神谷忙碌的走廊中工作。她以挥舞切肉刀稳健的手法而闻名，并指导部落的冒险者如何使用卡利姆多的野兽制作丰盛的餐点。",kw={"烹饪训练师","暗矛","奥格瑞玛","精神谷","去加基森吧","巨魔","扎姆沙"},ang={["profession:Cooking"]="扎姆沙是造访奥格瑞玛的部落角色主要的烹饪训练师之一，她教授基础食谱，并最终会将经验丰富的厨师指引向南方的塔纳利斯以接受进阶指导。",["race:Troll"]="像许多在大酋长萨尔旗帜下定居奥格瑞玛的暗矛巨魔一样，扎姆沙将巨魔的足智多谋和烹饪技艺带到了部落首都的核心地带。"},sec={{t="精神谷的切肉刀",b="扎姆沙驻扎在精神谷蜿蜒的峡谷小径中，每天都在切割肉块，教导饥肠辘辘的部落旅行者如何维持生计。在杜隆塔尔和贫瘠之地的崎岖地形中，实用的烹饪是一项至关重要的生存技能。扎姆沙确保任何愿意拿起平底锅的人都能学会将生肉变成健康口粮的基础知识。对于已经掌握基本食谱并寻求进一步培训的厨师，她会将他们指引向南方的加基森。"}},faq={{q="扎姆沙是谁？",a="扎姆沙是一位位于奥格瑞玛精神谷的暗矛巨魔烹饪训练师。她向部落成员教授烹饪艺术，并帮助初出茅庐的厨师磨练他们的技艺。",al={"扎姆沙 npc","扎姆沙是谁","扎姆沙 奥格瑞玛"}},{q="我在哪里可以找到扎姆沙？",a="她可以在精神谷找到，那是一条连接奥格瑞玛内力量谷和荣誉谷的阴凉蜿蜒的沟壑。",al={"扎姆沙 位置","扎姆沙在哪里","扎姆沙 训练师地点"}},{q="扎姆沙提供什么培训？",a="扎姆沙提供烹饪培训，并教授食谱，使冒险者能够用在整个卡利姆多收集到的野兽和猎物制作食物。当厨师的水平达到一定程度时，她还会指引他们前往更高级的导师处。",al={"扎姆沙教什么","扎姆沙 烹饪食谱","奥格瑞玛 烹饪训练师"}},{q="扎姆沙会将高级厨师送到哪里去？",a="一旦厨师的技能超出了奥格瑞玛当地培训的水平，扎姆沙就会通过任务“去加基森吧！”将他们指引至塔纳利的加基森，去寻找迪尔格·奎克里弗。",al={"扎姆沙 任务","去加基森吧 任务","专家级烹饪 部落"}}},fx={["85904c39"]={q="扎姆沙效忠于哪一方？",a="扎姆沙忠于部落和暗矛巨魔同胞。她在奥格瑞玛繁华的中心生活和工作，为城中的居民和旅人服务，愿意向任何渴望掌握烹饪技艺的部落成员传授自己的厨艺。",al={"扎姆沙所属阵营","扎姆沙的效忠对象","扎姆沙是部落成员吗"}},ae32e7ed={q="扎姆沙想要什么？",a="扎姆沙全心投入自己的手艺，整日切肉，在奥格瑞玛准备营养充足的食物。她只希望把烹饪知识分享给部落中有志成为厨师的人，确保旅人吃饱，并在学徒技艺超过她的教导后，为他们指引更高深的导师。",al={"扎姆沙的目标","扎姆沙需要什么","扎姆沙的动机"}},["16342b16"]={q="扎姆沙为什么在奥格瑞玛？",a="作为一名技艺娴熟的巨魔厨师，扎姆沙生活在兽人首都奥格瑞玛，在此经营自己的生意并支持部落。在这片严酷干旱、处处需要实用技能才能生存的土地上，她确保冒险者和守卫能够学到恰当的屠宰与烹饪技艺。",al={"扎姆沙为什么在奥格瑞玛","扎姆沙所在地点及目的","扎姆沙为什么在这里"}}},fp="5,241,21.487.0,13.171.0,23.131.0,31.236.0,37.181.0"}
P.entries["npc:zangen-stonehoof"] = {n="赞金·石蹄",s="赞金·石蹄是一位驻守在雷霆崖高位中心的牛头人守护者。他深受同胞敬重，恪尽职守，每晚悉心照料着中央篝火，并协调各方资源以支援远在卡利姆多各处的族人。",h="赞金·石蹄是一位驻守在雷霆崖高位中心的牛头人守护者。他深受同胞敬重，恪尽职守，每晚悉心照料着中央篝火，并协调各方资源以支援远在卡利姆多各处的族人。",kw={"篝火","high rise","月亮井水","劳恩·峭壁行者","神圣之火","雷霆崖","赞金·石蹄"},ang={["faction:Horde"]="对于造访雷霆崖大台地的旅行者来说，赞金提供了一个前往灰谷等争夺地区冒险的联络点。",["race:Tauren"]="赞金体现了各部落间的紧密联系，将莫高雷的行政中心与远在千针石林的峭壁行者等族人直接连接在了一起。"},sec={{t="高位之火守护者",b="赞金·石蹄伫立在雷霆崖的高位之上，照料着俯瞰整座城市最高崖壁的中央公共篝火。每当暮色笼罩莫高雷，赞金便会点燃篝火，为聚集在大酋长凯恩·血蹄麾下的各部落提供温暖与永恒的指引。除了维持火种不灭，他还负责与莫高雷台地之外的盟友保持联络，充当整个卡利姆多大陆精神与仪式活动的联络人。"},{t="援助峭壁行者",b="赞金是驻扎在南方千针石林的同伴劳恩·峭壁行者的中间人。当劳恩需要暗夜精灵月亮井的神圣之水来进行仪式时，赞金便委托可靠的部落冒险者前往危机四伏的灰谷。通过从古老的树林中获取注满水的药瓶并将其送往乱风岗，赞金在保护古老仪式和支援分散的牛头人据点方面发挥了虽然低调但至关重要的作用。"}},faq={{q="赞金·石蹄是谁？",a="赞金·石蹄是雷霆崖的一位牛头人居民，就在高位的大型中央篝火旁。他每晚都会照料篝火，并通过组织援助和跑腿任务来帮助卡利姆多远方的族人。",al={"赞金是谁","赞金·石蹄","赞金做什么"}},{q="赞金如何处理篝火？",a="每晚夜幕降临时，赞金都会点燃他面前位于高位的巨大篝火，为崖顶平台带来光亮与温暖。",al={"为什么赞金在火堆旁","赞金 篝火","点燃火堆"}},{q="赞金为什么需要来自灰谷的月亮井水？",a="赞金是受驻扎在千针石林乱风岗的劳恩·峭壁行者之托。劳恩需要灰谷月亮井的水来进行一场神圣的仪式，赞金便指派有能力的旅行者去获取它，并将水送往南方。",al={"赞金 月亮井任务","神圣之火","为什么需要月亮井水"}},{q="在哪里可以找到赞金·石蹄？",a="他就站在雷霆崖高位的中心，就在上层台地的公共火堆旁边。",al={"赞金位置","寻找赞金·石蹄","赞金在哪里"}}},fx={["44db2024"]={q="赞金·石蹄效忠于哪一方？",a="赞金·石蹄全心效忠于部落和牛头人同胞。他驻守在雷霆崖的 High Rise，与劳恩·峭壁行者等盟友协调，并招募有能力的部落旅人，协助完成卡利姆多各地的神圣任务。",al={"赞金·石蹄所属阵营","赞金是部落成员吗","赞金效力于谁"}},edd8b42e={q="赞金·石蹄与谁有关联？",a="赞金与劳恩·峭壁行者密切合作，后者驻扎在千针石林的严酷荒野中。劳恩需要神圣材料时——例如来自灰谷森林的强效月亮井之水——赞金便会在首都担任联络人，寻找愿意踏上旅程的旅人。",al={"赞金·石蹄的同伴","谁与赞金·石蹄共事","劳恩·峭壁行者与赞金"}}},fp="16,259,29.480.0,23.473.0,24.219.0,37.168.0,51.243.0,36.113.0"}
P.entries["npc:zankaja"] = {n="赞卡沙",s="赞卡沙是一位住在奥格瑞玛的年轻兽人女性，她居住在力量谷和智慧谷之间的道路旁。她焦急地等待着关于她伴侣多格兰的消息，多格兰被指派到贫瘠之地那危险的前线，在十字路口执行任务。",h="赞卡沙是一位住在奥格瑞玛的年轻兽人女性，她居住在力量谷和智慧谷之间的道路旁。她焦急地等待着关于她伴侣多格兰的消息，多格兰被指派到贫瘠之地那危险的前线，在十字路口执行任务。",kw={"贫瘠之地","十字路口","多格兰","加兹罗格","奥格瑞玛","valley of strength","智慧谷","赞卡沙"},ang={["faction:Horde"]="她的恳求提醒了部落的冒险者，坚守像十字路口这样的哨所，需要驻扎在那里的士兵付出真正的鲜血和牺牲。",["race:Orc"]="赞卡沙体现了杜隆塔尔普通家庭所承担的个人代价，在这里，对大酋长新领地的职责常常会将亲人送往未开化且致命的前线。"},sec={{t="警惕之心",b="在这个新兴的部落首都，生活充满了艰辛，但对赞卡沙来说，真正的考验是等待。她的伴侣多格兰获得了一次晋升，被派往南部的贫瘠之地，去支援十字路口的哨所。虽然这对战士来说是一种荣誉，但贫瘠之地是一片遍布着野猪人、半人马和凶猛野兽的残酷旷野。当多格兰未能如期发回消息或回家时，赞卡沙便开始寻找愿意帮她打听他下落的旅者。"},{t="悲惨的消息",b="当在贫瘠之地的打听结果显示多格兰落入了野猪人的魔爪时，赞卡沙最担心的事还是发生了。尽管她在奥格瑞玛的峡谷城墙内仍抱有一丝希望，但那片前线是无情的，冒险者带回的消息描绘出了一幅在部落危险边境上牺牲的残酷景象。"}},faq={{q="我在哪里可以找到赞卡沙？",a="赞卡沙站在奥格瑞玛城中连接力量谷和智慧谷的道路旁。",al={"赞卡沙位置","赞卡沙在哪里","寻找赞卡沙"}},{q="多格兰是谁？",a="多格兰是赞卡沙的伴侣。他是一名兽人战士，最近的晋升让他获得了在贫瘠之地十字路口驻扎的机会。",al={"多格兰是谁","多格兰","赞卡沙的伴侣"}},{q="为什么赞卡沙很担心？",a="多格兰因任务被派往贫瘠之地那严酷的荒野，前往十字路口，但他既没回来也没有发消息回家，这让赞卡沙担心他在前线遭遇了不测。",al={"赞卡沙想要什么","赞卡沙的问题","为什么赞卡沙很伤心"}},{q="赞卡沙请求冒险者做什么？",a="她请求离开奥格瑞玛的路过冒险者去十字路口拜访加兹罗格队长，询问多格兰的下落和安危。",al={"赞卡沙的任务","多格兰的消息任务"}},{q="多格兰在贫瘠之地发生了什么事？",a="对于赞卡沙来说，多格兰的下落尚不明确。她请求旅行者与十字路口的加兹罗格交谈，并从那里寻找线索。",al={"多格兰死了吗","多格兰的命运","多格兰发生了什么"}}},fx={d77e4e41={q="赞卡沙是谁？",a="赞卡沙是一名生活在奥格瑞玛的年轻兽人女性。她整日徘徊在 Valley of Strength 和智慧谷之间，因伴侣多格兰奉命前往贫瘠之地的严酷荒野而忧心不已，沉浸在悲伤和焦虑之中。",al={"赞卡沙是谁","赞卡沙的身份","赞卡沙的背景"}},c2de3af5={q="赞卡沙效忠于哪一方？",a="赞卡沙是生活在部落首都奥格瑞玛的忠诚平民。她关心的是个人和家庭之事，而非政治；她所有的牵挂都围绕着伴侣的安危，以及她在兽人同胞中家园的安全。",al={"赞卡沙所属阵营","赞卡沙是部落成员吗","赞卡沙的效忠对象"}},b4e1ea75={q="赞卡沙为什么在这里？",a="赞卡沙仍留在奥格瑞玛，焦急地等待伴侣多格兰的消息。多格兰被派往南方的十字路口后，她留在首都的安全之中，却发现自己陷入了煎熬的等待，因为他的信件和报告都断了。",al={"赞卡沙为什么在奥格瑞玛","赞卡沙为什么站在这里","赞卡沙所在位置的原因"}}},fp="7,262,16.460.0,14.325.1,25.114.0,14.124.0,23.180.0,40.150.0,39.137.1"}
P.entries["npc:zardeth-of-the-black-claw"] = {n="黑爪加尔德斯",s="黑爪加尔德斯是一位术士，居住在暴风城法师区Slaughtered Lamb下方昏暗的地下室里。他伪装成一位不起眼的常客，暗中协调各种手段，保护城内隐秘的术士结社免受外界审查。每当有好奇的贵族开始深挖他们的活动时，加尔德斯便会确保这些调查被永久终止。",h="黑爪加尔德斯是一位术士，居住在暴风城法师区Slaughtered...",kw={"贵族佳酿","鲍雷斯·维沙克","黑爪","mage quarter","麝鼠根","slaughtered lamb","蒂罗亚之泪","术士","加尔德斯"},ang={["class:Warlock"]="加尔德斯体现了人类术士在联盟中心生存所必需的冷静务实，证明了生存往往取决于先发制人的暗杀。",["faction:Alliance"]="对于联盟忠诚者来说，加尔德斯是一个鲜明的提醒，警示着在暴风城光鲜亮丽的街道下正腐烂滋生着腐败的下腹部。",["profession:Herbalism"]="加尔德斯的阴谋依赖于像蒂罗亚之泪和麝鼠根这样的有毒植物标本，展示了稀有野生植物的致命潜力。"},sec={{t="羔羊之下的阴影",b="当法师区的高耸尖塔在公开研究奥术规则时，Slaughtered Lamb下方的地下隧道却容纳着那些从事黑暗技艺的人。黑爪加尔德斯就在这些墓穴中活动，作为一名警惕的守护者，守护着在城市守卫眼皮底下隐藏的施法者们。由于联盟官方谴责邪能魔法，他们的生存需要严密的秘密，以及在皇家调查员上门前消灭任何威胁的决心。"},{t="让贵族噤声",b="当鲍雷斯·维沙克公爵发现关于隐秘术士集会的传闻时，这位贵族开始游说贵族议会进行立即且全面的调查。加尔德斯意识到这种审查会摧毁他们的地下避难所，于是安排了一项秘密的反制措施。加尔德斯利用这位公爵对美酒的众所周知的沉迷，派遣一名特工前往东部王国各地收集稀有且致命的植物——来自暮色森林的蒂罗亚之泪和巨石水坝下的麝鼠根。"},{t="贵族的佳酿",b="加尔德斯将收集到的试剂与烈性麦芽酒混合，调制出了黑爪烈酒，这是一种伪装成普通奢侈礼物的致命陈酿。当这瓶有毒的酒被送到维沙克公爵的庄园后，它悄无声息地发挥了作用。随着维沙克公爵的死亡以及他在王室干预前竞选活动的熄灭，加尔德斯和他的术士同僚成功保住了Slaughtered Lamb下方的地下飞地。"}},faq={{q="黑爪加尔德斯是谁？",a="加尔德斯是一名人类术士，驻扎在暴风城法师区Slaughtered Lamb酒馆下方的地下墓穴中。他代表隐秘的术士兄弟会行事，以转移怀疑并处理威胁到他们在这个城市中秘密存在的问题。",al={"加尔德斯","谁是加尔德斯","加尔德斯 暴风城"}},{q="我在哪里可以找到加尔德斯？",a="他可以在暴风城法师区南部的Slaughtered Lamb酒馆下方找到。进入酒馆，找到后方的向下通道，顺着蜿蜒的地下墓穴走到底，就是术士的聚集地。",al={"加尔德斯位置","在哪里找到加尔德斯","加尔德斯 slaughtered lamb"}},{q="为什么加尔德斯要杀死维沙克公爵？",a="鲍雷斯·维沙克公爵发现了术士在城下活动的证据，并开始游说暴风城的贵族进行正式调查。如果进行了官方调查，Slaughtered Lamb的集会就会被城防部门连根拔起并处决。",al={"为什么杀维沙克","维沙克公爵目标","贵族酒的原因"}},{q="什么是黑爪烈酒？",a="黑爪烈酒是加尔德斯酿造的一种致命混合酒。它将普通的烈性麦芽酒与两种稀有的毒草结合在一起：来自夜色镇的蒂罗亚之泪和湿地的麝鼠根。它旨在伪装成昂贵的饮品，同时悄悄暗杀维沙克公爵。",al={"黑爪烈酒","什么是这种酒","维沙克毒药"}},{q="什么是黑爪？",a="黑爪指的是加尔德斯在暴风城内暗中活动的术士网络中所持有的阴影从属关系或头衔。他们在暴风城守卫和肯瑞托的雷达下运作，利用致命的谨慎来保护他们的成员。",al={"黑爪含义","谁是黑爪","黑爪术士"}},{q="为什么术士被允许待在暴风城？",a="他们并未被公开容忍。虽然黑暗施法者潜伏在城中，但他们被迫隐藏在Slaughtered Lamb下方的深层地窖中。当局要么因为其实际用途而睁一只眼闭一只眼，要么因为像加尔德斯这样的特工消灭了任何准备揭发他们的人而对此一无所知。",al={"术士合法吗","暴风城术士背景","为什么城里有术士"}}},fx={ec5a54de={q="黑爪加尔德斯支持哪一方？",a="加尔德斯关心的是暴风城隐秘术士的生存，而非王室的律法。他打着联盟的旗号，在Mage Quarter下方行事，但他只忠于藏身于Slaughtered Lamb中的那个术士团体；任何威胁要揭露他们黑暗研究的贵族或官员，他都准备将其除掉。",al={"加尔德斯所属阵营","加尔德斯效忠谁","加尔德斯忠于暴风城吗"}},["212e3858"]={q="黑爪加尔德斯想要什么？",a="加尔德斯想保护自己的术士据点，避免暴风城贵族的审查。维肖克勋爵得知他们在地下建立了据点，并推动正式调查后，加尔德斯立即设法安排这位多管闲事的贵族悄无声息地永远消失。",al={"加尔德斯的目标是什么","加尔德斯的计划","加尔德斯想要什么"}},f970876d={q="黑爪加尔德斯为什么在暴风城？",a="加尔德斯在Slaughtered Lamb的地下墓穴中活动，借酒馆不起眼的外表秘密施展邪能魔法。他时刻戒备着外部威胁，确保聚集在下方的施法者能够不受城中当局干扰，继续钻研禁忌技艺。",al={"加尔德斯为什么在这里","加尔德斯在slaughtered lamb的目的","加尔德斯为什么来到暴风城"}}},fp="25,408,25.498.0,22.517.1,12.434.2,33.257.0,25.245.0,40.280.0,25.274.0,23.259.0,45.305.0"}
P.entries["npc:zargh"] = {n="扎尔夫",s="扎尔夫是一名驻扎在贫瘠之地十字路口的兽人肉商。除了为旅行者提供补给外，他还经常将当地精选的猎物肉块供应给奥格瑞玛的旅店老板格雷什卡。",h="扎尔夫是一名驻扎在贫瘠之地十字路口的兽人肉商。除了为旅行者提供补给外，他还经常将当地精选的猎物肉块供应给奥格瑞玛的旅店老板格雷什卡。",kw={"贫瘠之地","屠夫","十字路口","格雷什卡","烤狮排","肉类","扎尔夫"},ang={["faction:Horde"]="他在十字路口和奥格瑞玛之间的贸易路线教会了年轻的部落信使如何利用杜隆塔尔和贫瘠之地之间的双足飞龙网络。",["profession:Cooking"]="扎尔夫是贫瘠之地为数不多出售烤狮排配方的商人，对于想要利用当地掠食者肉类的厨师来说，这是一份宝贵的烹饪配方。"},sec={{t="十字路口的屠夫",b="在繁忙的十字路口，扎尔夫经营着他的店铺，出售从周围平原获取的各种腌肉、肉腿和猎物。对于深入这片严酷荒野的冒险者来说，他的存货提供了至关重要的营养。除了基本的贸易外，他与部落首都有着密切的联系，经常将精心挑选的肉类经由杜隆塔尔运送给Valley of Strength的旅店老板格雷什卡。"},{t="信使的任务",b="扎尔夫经常招募游荡的信使通过双足飞龙将新鲜的肉类运送给奥格瑞玛的旅店老板格雷什卡，以确保补给在变质前送达。他们的关系似乎不仅仅是工作上的往来：格雷什卡的信件中提到了扎尔夫断掉一根手指的意外事故，而在收到她的回信后，扎尔夫暗示未来可能会给这位旅行者发送婚礼请柬。"}},faq={{q="在哪里可以找到扎尔夫？",a="扎尔夫位于贫瘠之地部落的中心定居点——十字路口。他是营地商贩中的一名肉类供应商。",al={"扎尔夫位置","扎尔夫在哪里","扎尔夫npc"}},{q="扎尔夫与旅店老板格雷什卡有什么关系？",a="扎尔夫为奥格瑞玛的旅店老板格雷什卡供应贫瘠之地的精选肉类。他们的通信表明双方有着温暖的私交；在收到她的来信后，扎尔夫甚至暗示婚礼请柬可能很快就会到来。",al={"扎尔夫格雷什卡","扎尔夫的关系","扎尔夫要和谁结婚"}},{q="扎尔夫的手指怎么了？",a="根据格雷什卡的一封信，扎尔夫过去曾发生过一次屠宰事故，导致他失去了一根手指。这成了他们之间关于肉块来源的一个内部笑话。",al={"扎尔夫断指","扎尔夫事故"}},{q="扎尔夫卖什么？",a="他出售各种食物补给，包括肉腿、腌火腿排、野猪后腿肉，以及一份烤狮排配方。",al={"扎尔夫出售物品","扎尔夫商品"}}},fx={["84a718e2"]={q="扎尔夫是谁？",a="扎尔夫是贫瘠之地十字路口的一名兽人屠夫和肉贩。他为部落领地各处的旅人、守卫和盟友提供补给以及当地猎物的上等肉块。",al={"扎尔夫是谁","扎尔夫的背景","扎尔夫与十字路口"}},["9d177987"]={q="扎尔夫支持哪一方？",a="扎尔夫是部落的忠诚成员，在十字路口这个重要据点开展经营。他经常与部落的各处聚居地协调贸易和送货，包括首都奥格瑞玛。",al={"扎尔夫是部落成员吗","扎尔夫所属阵营","扎尔夫的效忠对象"}},db26839a={q="扎尔夫想要什么？",a="扎尔夫希望屠宰生意顺利经营，确保货物送达目的地。他会雇用可靠的信使，把上等贫瘠之地肉类送给他在奥格瑞玛Valley of Strength的密友旅店老板格雷什卡。",al={"扎尔夫想要什么","扎尔夫任务目标","扎尔夫的动机"}},a9ecc79a={q="扎尔夫为什么在十字路口？",a="十字路口是贫瘠之地重要的贸易和交通枢纽，因此是屠夫理想的落脚之处。周围有丰富的野味，扎尔夫可以轻松加工上等肉类，再运往远方的聚居地。",al={"扎尔夫为什么在这里","扎尔夫为什么在十字路口","扎尔夫所在位置的原因"}}},fp="5,203,25.416.0,18.411.1,23.138.0,48.234.0,32.188.0,21.129.0"}
P.entries["npc:zarlman-two-moons"] = {n="扎尔曼·双月",s="扎尔曼·双月是一位受人尊敬的牛头人神秘主义者，居住在莫高雷中部的血蹄村。当贝恩·血蹄负责处理村庄的日常世俗事务时，扎尔曼则指导着村庄的精神生活并与灵魂进行交流。他在通过神圣的幻象之礼引导年轻牛头人步入成年的过程中发挥着至关重要的作用。",h="扎尔曼·双月是一位受人尊敬的牛头人神秘主义者，居住在莫高雷中部的血蹄村。当贝恩·血蹄负责处理村庄的日常世俗事务时，扎尔曼则指导着村庄的精神生活并与灵魂进行交流。他在通过神圣的幻象之礼引导年轻牛头人步入成年的过程中发挥着至...",kw={"血蹄","莫高雷","仪式","萨满","灵魂","牛头人","双月","村庄","幻象","扎尔曼"},ang={["class:Shaman"]="扎尔曼体现了牛头人萨满教的古典传统，平衡了与灵魂的交流和实际的部落领导。",["faction:Horde"]="驻扎在莫高雷的中心枢纽，扎尔曼向新到达的部落盟友介绍了塑造牛头人文化的深层精神习俗。",["race:Tauren"]="对于牛头人冒险者来说，扎尔曼是一位必不可少的向导，他能帮助你完成你年轻时代的神圣仪式并唤醒你的灵视。"},sec={{t="未见之物的守望者",b="在血蹄村，领导权分为世俗和神秘两个方面。贝恩·血蹄统领定居点的防御和世俗需求，但却是扎尔曼·双月维护着精神世界的和谐。在一个深深植根于对大地母亲和祖先智慧的崇敬的文化中，扎尔曼充当了平原上的日常挣扎与过去永恒声音之间的桥梁。"},{t="幻象之礼",b="扎尔曼对其族人最重要的职责是主持幻象之礼，这是每个成长中的牛头人必须经历的传统试炼。通过指导初试者准备神圣的药剂并仔细聆听祖先的征兆，他帮助年轻的猎人、萨满祭司和战士们发现他们命中注定的道路和灵魂向导。在他的教导下，初试者们明白了在平原上，如果没有精神上的清明，单纯的体能毫无意义。"}},faq={{q="谁是扎尔曼·双月？",a="扎尔曼·双月是一位驻扎在血蹄村的著名牛头人神秘主义者。当贝恩·血蹄处理世俗领导权和城镇的实际防御时，扎尔曼则守护着定居点的精神福祉，并引导年轻的冒险者了解古老的部落传统。",al={"扎尔曼是谁","扎尔曼·双月背景故事","血蹄村的萨满是谁"}},{q="扎尔曼在血蹄村扮演什么角色？",a="扎尔曼负责血蹄村居民的精神事务、祖先交流和文化仪式。他与贝恩·血蹄的世俗领导相辅相成，确保部落与自然之灵及祖先保持平衡。",al={"扎尔曼的工作","扎尔曼的目的","血蹄村神秘主义者"}},{q="什么是幻象之礼？",a="幻象之礼是年轻牛头人在穿过莫高雷时的一种传统成年仪式。在扎尔曼的引导下，初试者喝下一剂仪式药水，开启他们的灵视，使他们能够跟随幻象并接受自然之灵的指引。",al={"幻象之礼任务","什么是幻象仪式","牛头人幻象试炼"}},{q="在哪里可以找到扎尔曼·双月？",a="扎尔曼·双月位于血蹄村，坐落在莫高雷的中心地带，石牛湖的弯道处。",al={"扎尔曼在哪里","扎尔曼位置","如何找到扎尔曼"}},{q="扎尔曼与贝恩·血蹄是什么关系？",a="扎尔曼与贝恩·血蹄作为精神层面的对应者并肩工作。当贝恩在物质和军事事务上领导村庄时，扎尔曼则提供神秘的智慧并守护着部落的精神平衡。",al={"贝恩和扎尔曼","扎尔曼与贝恩的关系"}},{q="为什么幻象之礼对年轻牛头人很重要？",a="幻象之礼对于每个步入成年的牛头人来说都是必不可少的。它标志着从未经考验的青年到部落公认成员的转变，揭示了他们内在的灵魂向导，并巩固了他们与大地母亲之间的联系。",al={"为什么要进行幻象之礼","幻象之礼的重要性"}}},fx={caff3cf9={q="扎尔曼·双月支持哪一方？",a="扎尔曼·双月全心效忠血蹄氏族和部落。他驻守在血蹄村，与贝恩·血蹄密切合作，确保族人在莫高雷面临任何威胁时都能保持精神坚韧。",al={"扎尔曼效忠谁","扎尔曼·双月所属阵营","扎尔曼是部落成员吗"}},["45ee9eb7"]={q="扎尔曼·双月想要什么？",a="扎尔曼致力于守护血蹄村的精神福祉。部族的实际领导由贝恩·血蹄负责，而扎尔曼则引导年轻的冒险者践行视界仪式等古老传统，与灵魂沟通并找到自己的真正道路。",al={"扎尔曼想要什么","扎尔曼的目标","扎尔曼在做什么"}},["1734c724"]={q="扎尔曼·双月为什么在这里？",a="扎尔曼留在血蹄村，担任村中首要的精神守护者。随着部族成员长大成人，他主持与祖灵沟通所需的神圣仪式，并保护祖先的土地免受看不见的灵界威胁。",al={"扎尔曼为什么在血蹄村","扎尔曼为什么在这里"}}},fp="17,328,20.424.0,18.436.0,25.285.0,44.250.0,27.256.0,37.120.0,43.211.0,52.230.0"}
P.entries["npc:zarrin"] = {n="扎瑞恩",s="扎瑞恩是一名暗夜精灵烹饪导师，位于泰达希尔枝头的多兰纳尔。他在村庄旅店后的露天炉火旁照看，教导年轻的暗夜精灵和访客传统的卡多雷烹饪技巧。",h="扎瑞恩是一名暗夜精灵烹饪导师，位于泰达希尔枝头的多兰纳尔。他在村庄旅店后的露天炉火旁照看，教导年轻的暗夜精灵和访客传统的卡多雷烹饪技巧。",kw={"烹饪","多兰纳尔","卡多雷","泰达希尔","训练师","扎瑞恩"},ang={["profession:Cooking"]="对于在泰达希尔开启旅程的冒险者来说，扎瑞恩是学习如何将野兽肉和采集来的食材变成营养餐点的主要导师。",["race:NightElf"]="扎瑞恩维护着日常的卡多雷饮食方式，确保传统口味和烹饪方法在世界之树的树冠下得以延续。"},sec={{t="多兰纳尔的炉火守护者",b="扎瑞恩位于多兰纳尔旅店后，远离主干道，他在那里照看一处露天火堆，分享卡多雷的烹饪艺术。在泰达希尔生存需要利用这棵巨树上的原生动植物，而扎瑞恩正是为那些寻求通过采集和家常烹饪来维持生计的人提供指导。"}},faq={{q="我在哪里可以找到扎瑞恩？",a="扎瑞恩站在泰达希尔多兰纳尔的旅店后面，在路对面的露天院子里忙着烹饪。",al={"扎瑞恩位置","扎瑞恩在哪里","多兰纳尔烹饪训练师"}},{q="扎瑞恩教什么？",a="他是一位烹饪训练师，负责教导新手基本的烹饪准备和传统的暗夜精灵食谱。",al={"扎瑞恩训练师","扎瑞恩教什么"}},{q="扎瑞恩提供什么任务？",a="扎瑞恩会请旅行者帮他准备传统菜肴，并提供任务“卡多雷的食谱”来向新人传授当地的烹饪方法。",al={"扎瑞恩任务","卡多雷的食谱任务"}}},fx={["43472bbf"]={q="扎瑞恩是谁？",a="扎瑞恩是一名暗夜精灵烹饪导师，在多兰纳尔照看自己的炉火。他驻扎在村中旅店的后方，日复一日地守着篝火，教导年轻旅人和当地哨兵卡多雷的传统烹饪技艺。",al={"扎瑞恩是谁","扎瑞恩的背景","扎瑞恩的身份"}},["9b474307"]={q="扎瑞恩支持哪一方？",a="扎瑞恩忠于达纳苏斯和更广大的联盟。他平静地生活在泰达希尔境内，为前来多兰纳尔的友善旅人提供炉火和烹饪知识。",al={"扎瑞恩所属阵营","扎瑞恩与联盟","扎瑞恩效忠谁"}},["08ffbf8a"]={q="扎瑞恩想要什么？",a="扎瑞恩致力于保存并传承卡多雷的传统烹饪技艺。他希望教导新晋冒险者如何利用泰达希尔丰富的野生动植物，烹制营养充足的餐食。",al={"扎瑞恩想要什么","扎瑞恩的目标","扎瑞恩的职责"}},["351be696"]={q="扎瑞恩为什么在多兰纳尔？",a="多兰纳尔是年轻暗夜精灵从幽影谷踏上旅程时经过的主要路口。扎瑞恩把烤架和篝火安置在当地旅店后方，以便在初出茅庐的游荡者深入险境前，及时传授他们重要的生存食谱。",al={"扎瑞恩为什么在多兰纳尔","扎瑞恩为什么在这里","扎瑞恩所在位置的原因"}}},fp="6,221,24.345.0,24.119.0,23.116.0,29.150.0"}
P.entries["npc:zenn-foulhoof"] = {n="赛恩·腐蹄",s="赛恩·腐蹄是一个徘徊在泰达希尔多兰纳尔以东的萨特。他会接近路人并索要森林试剂，而当地的暗夜精灵则对他严加看管。",h="赛恩·腐蹄是一个徘徊在泰达希尔多兰纳尔以东的萨特。他会接近路人并索要森林试剂，而当地的暗夜精灵则对他严加看管。",kw={"腐化松果","多兰纳尔","萨特","寻求救赎","泰达希尔","赛恩·腐蹄"},ang={["class:Druid"]="赛恩篡改野生试剂并蓄意传播腐化毒素的行为，直接冒犯了塞纳里奥教义，该教义旨在保持泰达希尔的纯净。",["race:NightElf"]="萨特代表了对卡多雷传统的终极背叛。看到一个萨特懒散地待在泰达希尔神圣的枝干上，这对艾露恩和荒野之灵来说是一种侮辱。"},sec={{t="林中的阴谋家",b="与大多数效忠于恶魔主子、明目张胆表现出敌意的萨特不同，赛恩·腐蹄不知何故在多兰纳尔外围获得了一种脆弱的容忍。他维持着友好的假象，声称自己已经改过自新，或者只是想交易一些无害的森林试剂，例如夜刃豹獠牙、枭兽羽毛和树林蜘蛛丝。实际上，他是在操纵轻信的年轻人为他搜集邪恶仪式的原料。多兰纳尔的议会拒绝让他肆意妄为；他们没有立即处决他，而是命令冒险者通过喂他吃受腐化的森林果实来羞辱他，将这名阴谋诡计的萨特暂时变成一只无害的青蛙。"}},faq={{q="为什么暗夜精灵没有立即攻击赛恩·腐蹄？",a="赛恩维持着友好的外表，且尚未在世界之树上公然犯下暴行，这使得多兰纳尔议会选择通过公开羞辱和严密监视来惩戒他，而不是直接判处他死刑。",al={"为什么赛恩是友好的","为什么暗夜精灵不杀赛恩","赛恩·腐蹄是邪恶的吗"}},{q="喂给赛恩受腐化的松果和浆果会发生什么？",a="这是多兰纳尔的长者们为赛恩的恶行所下达的惩戒。惩罚的结果会在他吃下腐化果实后显现出来。",al={"寻求救赎任务","赛恩青蛙"}},{q="什么是萨特？",a="萨特是暗夜精灵在流沙之战后，因向燃烧军团效忠而被扭曲成有角、蹄足的恶魔。大多数萨特已经彻底腐化，并对他们未被腐化的同族表现出暴力的敌意。",al={"什么是萨特","萨特背景故事"}}},fx={["1240b4a1"]={q="赛恩·腐蹄是谁？",a="赛恩·腐蹄是一名独居的萨特，潜伏在泰达希尔多兰纳尔以东。萨特是恶魔生物，也是暗夜精灵古老的敌人；但赛恩声称自己只想平静度日，安静地生活在世界之树的枝叶间，而非公开攻击当地居民。",al={"赛恩是谁","赛恩·腐蹄的背景","腐蹄是谁"}},["8f35fa9f"]={q="赛恩·腐蹄支持哪一方？",a="赛恩最终只站在自己一边，将险恶意图伪装在无害、合作的表象之下。尽管他在年轻冒险者面前表现得平和，交往时也没有明显敌意，但他绝非善类，会利用外来者协助自己腐化的计划，同时在多兰纳尔议会的密切监视下谨慎行事。",al={"赛恩是邪恶的吗","赛恩·腐蹄所属阵营","赛恩友好吗"}},["7266a9e7"]={q="赛恩·腐蹄想要什么？",a="赛恩请路过的冒险者收集夜刃豹的獠牙、枭兽的羽毛和树林蜘蛛丝，作为他在森林中秘密生意所需的试剂。",al={"赛恩想要什么","赛恩·腐蹄的动机","赛恩的要求目标"}}},fp="13,183,22.640.1,64.230.0,64.140.1,16.224.0"}
P.entries["npc:zevrost"] = {n="泽弗洛斯特",s="泽弗洛斯特是一名兽人术士训练师，隐居在奥格瑞玛地下的暗影裂口中。他指导部落中初出茅庐的术士，引导他们掌握危险的邪能魔法、召唤仪式以及禁锢黑暗神器的学科。",h="泽弗洛斯特是一名兽人术士训练师，隐居在奥格瑞玛地下的暗影裂口中。他指导部落中初出茅庐的术士，引导他们掌握危险的邪能魔法、召唤仪式以及禁锢黑暗神器的学科。",kw={"cleft of shadow","邪能魔法","邪能战马","奥格瑞玛","训练师","术士","泽弗洛斯特"},ang={["class:Warlock"]="对于部落术士而言，泽弗洛斯特是一位至关重要的导师，他负责解锁高级法术，并派遣初学者去执行获取专用武器、副手物品和烈焰战马的任务。",["race:Orc"]="生活在大部分排斥恶魔魔法的兽人社会中，泽弗洛斯特代表了那些在酋长的严密审查下依然利用黑暗艺术的从业者。"},sec={{t="黑暗艺术大师",b="泽弗洛斯特隐居在暗影裂口的洞穴深处，是居住在萨尔首度中的部落术士的主要导师之一。尽管在经历了过去的恶魔腐蚀后，广大兽人社会对邪能依然保持警惕，但像泽弗洛斯特这样的从业者在严密的监视下是被容许存在的。他向学生灌输驾驭恶魔力量所需的严苛纪律，以确保他们不会屈服于这些力量的腐蚀性本质，并断言邪能只会毁灭那些内心软弱的人。"},{t="指引雄心勃勃者",b="除了教授基础的法术和诅咒外，泽弗洛斯特还是更宏大的黑暗事业的引路人。寻求高级工具（例如奥拉希尔宝珠或召唤烈焰战马的方法）的初学者经常会经过他的指点。他将有抱负的从业者引荐给其他技艺大师，例如贫瘠之地的梅纳拉·沃伦德，以确保那些操纵暗影魔法的人能将自己的能力发挥到极致。"}},faq={{q="泽弗洛斯特是谁？",a="泽弗洛斯特是一位驻扎在奥格瑞玛地下暗影裂口的兽人术士训练师。他教导部落的新手和资深术士新的咒语，并指导他们完成关键的职业仪式。",al={"泽弗洛斯特的角色","泽弗洛斯特是谁","泽弗洛斯特npc"}},{q="泽弗洛斯特在哪里？",a="他居住在被称为暗影裂口的地下洞穴中，位于奥格瑞玛主城区之下。",al={"泽弗洛斯特位置","泽弗洛斯特在哪","寻找泽弗洛斯特"}},{q="为什么像泽弗洛斯特这样的术士被允许待在奥格瑞玛？",a="尽管萨尔的部落因兽人与恶魔之血的历史而严格管制和监控暗黑巫术，但术士们仍被允许在暗影裂口的幽深处进行修行，以便为对抗部落的众多敌人提供宝贵而冷酷的力量。",al={"为什么术士被允许进入奥格瑞玛","术士暗影裂口"}},{q="泽弗洛斯特对恶魔魔法的哲学是什么？",a="泽弗洛斯特认为，黑暗与奥术能量只会腐蚀意志薄弱的人。他敦促他的学生在学习中保持严格的纪律，以免屈服于他们所驾驭的毁灭性力量。",al={"泽弗洛斯特名言","泽弗洛斯特的信仰"}}},fx={a3e2c8b2={q="泽弗洛斯特支持哪一方？",a="泽弗洛斯特在奥格瑞玛担任术士训练师，为部落效力。由于火刃氏族留下的黑暗历史和恶魔腐化，许多兽人不信任术士；泽弗洛斯特则在城下修习自己的技艺，教导忠诚的施法者安全掌握邪能魔法，为部落效力。",al={"泽弗洛斯特所属阵营","泽弗洛斯特忠于萨尔吗","泽弗洛斯特效忠谁"}},["66627367"]={q="泽弗洛斯特想要什么？",a="泽弗洛斯特希望培养出纪律严明的术士，让他们能够驾驭不稳定的魔法而不被其吞噬。他认为奥术与邪能只会腐化意志薄弱者，因此致力于训练能够严格自律的学徒，使他们免于毁灭并有效地为部落效力。",al={"泽弗洛斯特的目标","泽弗洛斯特想要什么","泽弗洛斯特的职责"}}},fp="7,254,23.508.0,21.457.0,15.193.0,27.116.0,53.259.0,46.213.0"}
P.entries["npc:zjolnir"] = {n="祖尼尔",s="祖尼尔是驻扎在杜隆塔尔南海岸森金村的一名暗矛巨魔坐骑饲养员。他为暗矛巨魔和部落值得信赖的勇士提供训练有素的迅猛龙坐骑。对于巨魔骑手来说，他所饲养的那些凶猛而忠诚的野兽是他们深感文化自豪的源泉。",h="祖尼尔是驻扎在杜隆塔尔南海岸森金村的一名暗矛巨魔坐骑饲养员。他为暗矛巨魔和部落值得信赖的勇士提供训练有素的迅猛龙坐骑。对于巨魔骑手来说，他所饲养的那些凶猛而忠诚的野兽是他们深感文化自豪的源泉。",kw={"暗矛","杜隆塔尔","坐骑","迅猛龙","森金村","巨魔坐骑","祖尼尔"},ang={["faction:Horde"]="任何证明了自己对暗矛部族坚定忠诚的部落勇士，都有资格骑乘祖尼尔的迅猛龙奔赴战场。",["race:Troll"]="对于暗矛巨魔而言，祖尼尔提供的这些敏捷而长有利爪的野兽是他们传承与战斗传统的核心。"},sec={{t="暗矛迅猛龙饲养员",b="祖尼尔位于森金村的围栏旁，负责照料那些被暗矛巨魔视为坐骑的凶猛迅猛龙。迅猛龙生性暴躁且具有掠食性，需要专家的悉心照料才能驯化并装备战鞍。祖尼尔向那些已经掌握必要骑术的同族巨魔免费提供这些珍贵的哨声坐骑。至于其他部落成员，则必须先获得暗矛部族崇拜的声望，祖尼尔才会考虑将他的迅猛龙交给他们。"}},faq={{q="在哪里可以找到祖尼尔？",a="祖尼尔位于杜隆塔尔南部沿海的暗矛聚居地——森金村，他就站在村里的迅猛龙围栏旁。",al={"祖尼尔位置","祖尼尔在哪里","迅猛龙商人位置"}},{q="祖尼尔出售什么？",a="祖尼尔出售通过哨声召唤的迅猛龙，这是暗矛巨魔的种族标志性坐骑。他的存货包括各种适合初级骑手和经验丰富的老兵使用的品种与花色。",al={"祖尼尔商人","他卖什么","巨魔坐骑商人"}},{q="非巨魔种族可以向他购买迅猛龙吗？",a="可以，但非巨魔种族必须先在暗矛巨魔处达到崇拜声望，祖尼尔才会向他们出售。巨魔只要具备相应的骑术等级，即可直接购买。",al={"兽人可以买迅猛龙吗","谁能向祖尼尔购买坐骑","部落迅猛龙坐骑"}}},fx={a5db9414={q="祖尼尔是谁？",a="祖尼尔是暗矛丛林巨魔中的驯兽师和繁育者，负责照料部族珍视的迅猛龙。他驻守在杜隆塔尔海岸的森金村，为族人以及忠于部落、并已证明自己对暗矛氏族尽心效力的部落可靠勇士提供强健的迅猛龙坐骑。",al={"祖尼尔是谁","祖尼尔背景","迅猛龙坐骑商人是谁"}},["324eb78a"]={q="祖尼尔效忠于哪一方？",a="他坚定效忠暗矛氏族和部落。他居住在森金村，听命于酋长沃金，只将自己精心训练的野兽提供给族人，以及赢得暗矛氏族崇敬声望的外来者。",al={"祖尼尔所属阵营","祖尼尔效忠于谁","祖尼尔是部落成员吗"}},["58f60087"]={q="祖尼尔为何在此？",a="森金村是暗矛巨魔被逐出回音群岛后主要的海岸避难所。祖尼尔留在此地，繁育、照料并供应部族凶猛的迅猛龙坐骑，供侦察兵、突袭者和骑手使用，以守护他们在杜隆塔尔的新家园。",al={"祖尼尔为何在森金村","祖尼尔在这里做什么"}},["4b978e02"]={q="祖尼尔想要什么？",a="祖尼尔希望暗矛氏族拥有充足的坐骑，变得更加强大。他寻找有能力驾驭部族掠食性迅猛龙的骑手，只把这些致命野兽托付给族人，或是已充分证明自己忠于暗矛氏族、为其效力的盟友。",al={"祖尼尔想要什么","祖尼尔的目标"}},bad296c7={q="祖尼尔与谁有关联？",a="他与暗矛巨魔紧密相连，服务于在森金村建立起来的社群。他的工作直接支持部族的防御与机动能力，帮助酋长沃金领导下的部族以及与萨尔共同建立的广大部落联盟。",al={"祖尼尔的关系","祖尼尔与谁共事"}}},fp="7,289,32.501.0,25.154.0,23.200.0,36.192.0"}
P.entries["npc:zor-lonetree"] = {n="佐尔·孤树",s="佐尔·孤树是一位博学的兽人顾问，位于奥格瑞玛的格罗玛什要塞内。他精通外交事务和联盟政治，通过分析敌方神器并将旅行者指引至卡利姆多的动荡地区来协助部落。",h="佐尔·孤树是一位博学的兽人顾问，位于奥格瑞玛的格罗玛什要塞内。他精通外交事务和联盟政治，通过分析敌方神器并将旅行者指引至卡利姆多的动荡地区来协助部落。",kw={"顾问","联盟政治","grommash hold","奥格瑞玛","石爪山脉","valley of strength","佐尔·孤树"},ang={["class:Shaman"]="响应受扰元素力量召唤的萨满祭司会与佐尔找到共同点，因为他非常关注石爪山脉受苦的灵魂。",["faction:Horde"]="对于在人类聚居地或争议边境地区活动的部落斥候来说，佐尔·孤树是在奥格瑞玛解读敌方意图和遗物的关键联系人。"},sec={{t="格罗玛什要塞的顾问",b="佐尔·孤树驻扎在格罗玛什要塞内，与部落的高层领导在一起。他是一位精明的顾问，密切关注着杜隆塔尔之外的局势发展。他对人类和联盟的政治有着异常敏锐的理解，这使得当外来的奇物或政治威胁到达首都时，他成为了无价的参谋。从检查从人类定居点找回的贵族珠宝，到监测石爪山脉中大地之灵的动荡，孤树确保大酋长的宫廷始终掌握着世俗和神秘事务的信息。"}},faq={{q="佐尔·孤树是谁？",a="佐尔·孤树是一位驻扎在奥格瑞玛格罗玛什要塞内的兽人顾问。他以其智慧、对联盟政治结构的理解以及对卡利姆多精神事务的兴趣而闻名。",al={"佐尔·孤树是谁","佐尔是谁","奥格瑞玛的佐尔"}},{q="我在哪里可以找到佐尔·孤树？",a="你可以在奥格瑞玛中心地带智慧谷的格罗玛什要塞内找到他。",al={"佐尔·孤树位置","佐尔·孤树在哪里","奥格瑞玛的佐尔"}},{q="佐尔·孤树会给冒险者什么任务？",a="佐尔·孤树引导部落勇士去协助石爪峰的灵魂，并派遣旅行者去平息石爪山脉中的元素动荡。他还负责分析斥候带回首都的人类奇特遗物。",al={"佐尔·孤树的任务","石爪山脉之魂佐尔"}},{q="为什么佐尔·孤树对联盟很了解？",a="与许多前线战士不同，佐尔专攻外交事务和治国之道。他研究人类的贵族习俗和联盟的动向，这使他能够解读其他兽人可能会忽略的贵族印戒、徽章和战术意图。",al={"佐尔·孤树联盟背景","为什么佐尔了解联盟政治"}}},fx={["2fe5d96a"]={q="佐尔·孤树效忠于哪一方？",a="佐尔·孤树忠心耿耿地支持部落。他在奥格瑞玛的Grommash Hold办事，紧邻大酋长萨尔的核心幕僚，负责指挥战士和侦察兵，以推进部落在卡利姆多的战略与领土利益。",al={"佐尔·孤树所属阵营","佐尔·孤树是部落成员吗","佐尔效忠于谁"}},["74ebfad4"]={q="佐尔·孤树想要什么？",a="佐尔专注于巩固部落的立足点并守护其领地。他寻求有关外部威胁的情报，包括研究联盟的动向和遗物；同时派遣可靠的勇士安抚动荡的事物，例如石爪山脉躁动的大地与灵魂。",al={"佐尔想要什么","佐尔·孤树的动机","佐尔·孤树的目标"}},["891b1ec8"]={q="佐尔·孤树为何在Grommash Hold？",a="佐尔居住在Grommash Hold，担任部落领导层的顾问和协调者。他对联盟政治了如指掌，因此在大酋长评估外部威胁、外国贵族的阴谋以及卡利姆多各地的灵性动荡时，他的存在至关重要。",al={"佐尔为何在grommash hold","佐尔·孤树为何在奥格瑞玛","佐尔·孤树的职责"}},ebf76354={q="佐尔·孤树与谁有关联？",a="佐尔与部落的重要侦察兵和外勤特工密切合作，其中包括驻扎在尘泥沼泽蕨墙村的纳泽尔·血矛。他分析从边境传回的发现，并向聚集在Grommash Hold的领导层提供建议。",al={"佐尔·孤树的关系","佐尔与谁共事","佐尔·孤树的盟友"}}},fp="12,247,24.574.0,20.200.0,30.106.0,46.232.0,53.246.0"}
P.entries["npc:zureetha-fargaze"] = {n="祖雷萨",s="祖雷萨是一位驻扎在杜隆塔尔试炼谷的兽人导师，她与工头塔兹利尔共事。她对腐化保持着高度警惕，并指导年轻的部落新兵去调查并根除潜伏在山谷中的火刃氏族邪教的黑暗势力。",h="祖雷萨是一位驻扎在杜隆塔尔试炼谷的兽人导师，她与工头塔兹利尔共事。她对腐化保持着高度警惕，并指导年轻的部落新兵去调查并根除潜伏在山谷中的火刃氏族邪教的黑暗势力。",kw={"火刃氏族","火刃奖章","杜隆塔尔","工头塔兹利尔","试炼谷","祖雷萨"},ang={["class:Warlock"]="术士在试炼谷早期就会接触到祖雷萨的任务，处理那些与火刃氏族黑暗召唤相关联的、失控且邪恶的魔仆。",["race:Orc"]="对于迈出世界第一步的年轻兽人而言，祖雷萨代表了那种为了防止过去的恶魔污秽污染他们新家园所必需的警惕。"},sec={{t="谷中的注视",b="当工头塔兹利尔监管着年轻兽人和暗矛巨魔的劳作与纪律时，祖雷萨则在留意更为隐秘、阴险的威胁。火刃氏族邪教已经秘密渗透进试炼谷，腐化了次级恶魔，并在附近的火刃集会所洞穴中积蓄力量。祖雷萨会派那些未经考验的冒险者去回收邪教徒的勋章，以证实他们的存在并瓦解其早期行动，随后她会将经验丰富的新兵派往杜隆塔尔。"}},faq={{q="谁是祖雷萨？",a="祖雷萨是一位驻扎在杜隆塔尔试炼谷的兽人任务发布者。她站在工头塔兹利尔附近，监视着潜入训练场的隐秘威胁。",al={"祖雷萨背景故事","祖雷萨是谁","法戈兹 试炼谷"}},{q="为什么她担心火刃氏族？",a="恶魔般的火刃氏族在附近的一个洞穴中扎根，引来了邪恶的魔仆，并腐化了宁静的试炼场。祖雷萨通过邪教徒勋章寻找他们存在的证据，并派遣新兵去削减他们的数量。",al={"火刃氏族 试炼谷","为什么祖雷萨需要勋章","火刃氏族 杜隆塔尔"}},{q="在完成初步试炼后，她会将新兵派往何处？",a="一旦年轻的兽人和巨魔证明了他们应对当地威胁的能力，祖雷萨就会派遣他们越过东南方的山脊前往森金村，去协助暗矛部族。",al={"祖雷萨之后去哪里","祖雷萨的下一个任务","向森金村报告"}}},fx={b30f15ad={q="祖雷萨效忠于哪一方？",a="祖雷萨坚定地支持萨尔领导的部落。她与工头塔兹利尔一同驻守在试炼谷，负责引导年轻的新兵，并保护训练场免受内部腐化和暗中潜伏的敌人侵害。",al={"祖雷萨所属阵营","祖雷萨效忠于谁","祖雷萨是部落成员吗"}},["497b9432"]={q="祖雷萨为何在试炼谷？",a="她奉命驻守试炼谷，照看刚到此地、开始接受训练的兽人和巨魔。更紧要的是，她时刻警惕着火刃氏族的阴影势力；该邪教已开始渗入山谷附近的洞穴。",al={"祖雷萨为何在试炼谷","祖雷萨在杜隆塔尔的目的","祖雷萨为何在这里"}}},fp="16,268,18.523.0,24.185.0,45.247.0,56.175.0"}
P.entries["quest:10"] = {n="谢申克的救赎",s="在加基森，高级勘探员菲兹杜瑟感到很苦恼：初级勘探员斯克林沙克，也就是派往大裂口（位于镇子东南方的沙漠区域）的首席助手，失踪了。你被要求查明斯克林沙克发生了什么，或者至少找回勘探设备。",h="在加基森，高级勘探员菲兹杜瑟感到很苦恼：初级勘探员斯克林沙克，也就是派往大裂口（位于镇子东南方的沙漠区域）的首席助手，失踪了。你被要求查明斯克林沙克发生了什么，或者至少找回勘探设备。",kw={"菲兹杜瑟","加基森","大裂口","斯克林沙克","勘探","塔纳利斯"},sec={{t="失踪的勘探员",b="高级勘探员菲兹杜瑟感到很苦恼。初级勘探员斯克林沙克进入大裂口后就再也没了消息，而且来自那里的最后一份报告提到了更多那种诡异的虫子。菲兹杜瑟很担心这些虫子现在是不是同时占据了沙漠中两个广大的区域。你被要求前往那里寻找斯克林沙克，如果没能找到，至少也要找回勘探设备，菲兹杜瑟担心那可能已经是斯克林沙克留下的全部东西了。"},{t="菲兹杜瑟的结论",b="按照菲兹杜瑟的说法，斯克林沙克是个优秀的加基森地精，但他没能活下来。考虑到勘探设备所记录的内容，菲兹杜瑟希望这种牺牲是有价值的。这些虫子表现出了一种令人担忧的狡诈，目前的调查表明第三方势力在控制它们，这对加基森乃至整个沙漠来说都是不祥之兆。"}},faq={{q="高级勘探员菲兹杜瑟是谁？",a="菲兹杜瑟是加基森的高级勘探员，一直在调查沙漠中诡异的虫子，也是斯克林沙克的上级。",al={"菲兹杜瑟","谁发布了这个任务","勘探员菲兹杜瑟"}},{q="初级勘探员斯克林沙克是谁？",a="斯克林沙克是菲兹杜瑟的首席助手，在加基森东南方的沙漠中失踪之前被派往那里。",al={"斯克林沙克","斯克林沙克是谁","初级勘探员"}},{q="大裂口在哪里？",a="那是加基森东南方的沙漠区域，被勘探员们称为大裂口。",al={"大裂口位置","大裂口在哪里","裂口位置"}},{q="这一步之前是什么任务？",a="这是腐化之巢调查任务的后续。",al={"前置任务","前提条件","哪个任务在前"}}},fp="25,284,23.422.0,22.325.1,36.131.0,34.110.0,34.89.0,27.42.0"}
P.entries["quest:100"] = {n="水之召唤",s="这一仪式性的步骤标志着萨满在银松森林海岸的永恒之泉火盆处所受考验的终点。萨满用一阵元素光辉粉碎了威胁泉水的堕落灵魂，随后站在纯净的水之幻象前接受它的交流。",h="这一仪式性的步骤标志着萨满在银松森林海岸的永恒之泉火盆处所受考验的终点。萨满用一阵元素光辉粉碎了威胁泉水的堕落灵魂，随后站在纯净的水之幻象前接受它的交流。",kw={"永恒之泉火盆","call of water","元素","水之魂","萨满试炼","银松森林","水之图腾"},ang={["class:Shaman"]="这次交流直接考验了萨满去治愈家乡之外受苦水域的决心，并赢得了与水之灵本身的交流。",["faction:Horde"]="部落的精神领袖必须净化腐化的水道，即使在被遗忘者控制的领土（如银松森林）内，也要维持元素的和谐。"},sec={{t="净化之光爆发",b="在永恒之泉火盆处诵读最后一段咒语时，一道光芒爆发开来，扫除了周围的腐化。被元素之火蒸发出的受污染水滴发出的嘶嘶抗议声逐渐平息，周围的海岸恢复了宁静，邪恶的小型灵魂随之消散。"},{t="水的感激",b="在那些灵魂被消灭后，一个水之魂出现在火盆旁。该灵魂感激萨满的仪式干预，并意识到部落萨满所承担的重任日益沉重：虽然此地的腐化已经消退，但银松森林这片衰败土地上的生命仍在持续枯萎，需要时刻保持警惕来保护。"}},faq={{q="火盆仪式结束后会发生什么？",a="在永恒之泉火盆处完成咒语会释放出一阵耀眼的光芒爆发。这会摧毁周围受腐化的灵魂，并净化附近的元素流。",al={"火盆仪式光芒","永恒之泉爆发"}},{q="水之魂是谁？",a="它是一个由纯净之水构成的小型元素实体，在永恒之泉火盆附近的受腐化元素被消灭后现身。",al={"银松森林水之灵","水之魂"}},{q="水之灵对于银松森林说了什么？",a="水之灵向萨满表达了谢意，指出尽管这种特定的腐化已经消退，但这片土地上的生命仍在持续枯萎，需要持续的守护来保护。",al={"水之灵警告","银松森林腐化"}},{q="这个仪式在哪里举行？",a="仪式在位于银松森林海岸线上的永恒之泉火盆处举行。",al={"火盆位置","call of water位置"}},{q="为什么萨满必须在银松森林进行干预？",a="作为获取水之图腾的元素试炼的一部分，萨满必须通过捍卫遥远且遭受战火蹂躏的自然水域免受枯萎和挥之不去的腐化，以此证明他们对平衡的承诺。",al={"萨满为何在此","银松森林萨满职责"}},{q="试炼的下一步是什么？",a="在与水之魂商谈后，萨满会收到元素残骸或指引，以完成他们的旅程并打造他们的水之图腾。",al={"call of water下一步","水之魂之后"}}},fp="13,307,26.284.0,21.343.0,46.187.0,40.135.0,48.184.0,34.102.0,41.190.0,30.160.0"}
P.entries["quest:1001"] = {n="传声盒411号",s="“嗡鸣盒411号”是一项联盟任务，地点位于黑海岸风声阵阵的海岸线上。醉醺醺的侏儒发明家维兹班恩·曲针通过一个古怪的机械中继网络进行联络，他会请求路过的冒险者收集海岸边蛇颈龙的眼球，以让他的第二台研究机器重新启动。",h="“嗡鸣盒411号”是一项联盟任务，地点位于黑海岸风声阵阵的海岸线上。醉醺醺的侏儒发明家维兹班恩·曲针通过一个古怪的机械中继网络进行联络，他会请求路过的冒险者收集海岸边蛇颈龙的眼球，以让他的第二台研究机器重新启动。",kw={"奥伯丁","嗡鸣盒411号","爬行蟹酒","黑海岸","侏儒","蛇颈龙的眼球","工程技艺","维兹班恩·曲针"},ang={["profession:Engineering"]="使用有机的蛇颈龙眼球来校准机械发射器，体现了那些不走寻常路的技师所推崇的古怪且极具突破性的方法。",["race:Gnome"]="维兹班恩·曲针代表了侏儒在实地工作中的典型方针：大胆的创新、独特的部件选择，以及将危险的游泳任务委派给任何路过的人。",["race:NightElf"]="奥伯丁的哨兵时刻注视着黑海岸的水域，尽管她们通常对海岸线上那些古怪的侏儒装置放任不管。"},sec={{t="静电中的声音",b="在协助修理了更南边的“嗡鸣盒827号”后，侏儒发明家维兹班恩·曲针的声音再次从机械发射器中传了出来，伴随着刺耳的静电声。维兹班恩躲在某个安全且隐蔽的地方，指挥冒险者沿着黑海岸雾气弥漫的沙滩继续向北，去寻找另一台损坏的终端：嗡鸣盒411号。在传话间隙，他时不时打着酒嗝，嘴里还嘟囔着对爬行蟹酒的赞美，他透露说当地的水生掠食者身上有着维持他那台海岸装置正常运行所需的部件。"},{t="潜藏在水下的眼球",b="修复嗡鸣盒411号需要潜入奥伯丁海岸外寒冷且湍急的水域。黑海岸蛇颈龙徘徊在浅滩中，这些具有攻击性的海洋野兽的眼球中蕴含着维兹班恩声称校准设备所需的精准特性。将收集到的蛇颈龙的眼球投入机器的舱口，即可让设备重新运作，任务奖励将发放给信使，并开启下一个更加含糊不清的任务。"}},faq={{q="什么是嗡鸣盒411号？",a="嗡鸣盒411号是一台机械发射装置，位于奥伯丁以北的黑海岸沿岸。它是侏儒工程师维兹班恩·曲针所维护的一个实验性监听与研究网络的一部分。",al={"嗡鸣盒411号","什么是嗡鸣盒411号","嗡鸣盒411号的用途"}},{q="维兹班恩·曲针是谁？",a="维兹班恩·曲针是一位古怪的侏儒技师，通过“嗡鸣盒”网络进行远程通信。他把大部分实地研究时间都花在狂饮爬行蟹酒上，并依靠路过的冒险者来完成收集动物身体部位这种危险的实地工作。",al={"维兹班恩","维兹班恩是谁","谁制造了嗡鸣盒"}},{q="为什么机器需要蛇颈龙的眼球？",a="侏儒工程学经常将奇异的有机物质与机械部件结合起来以执行非常规任务。无论维兹班恩是否真的需要眼球来作为光学传感器，还是仅仅在他喝醉时将其用于生物学研究，他都坚持认为这对修理嗡鸣盒411号至关重要。",al={"为什么需要蛇颈龙的眼球","机器用的蛇颈龙眼球","嗡鸣盒的眼球"}},{q="嗡鸣盒411号在哪里？",a="嗡鸣盒411号就安放在黑海岸的沙滩上，位于暗夜精灵定居点奥伯丁的北面。",al={"嗡鸣盒411号在哪里","嗡鸣盒411号的位置","寻找嗡鸣盒411号"}},{q="我在哪里可以找到黑海岸蛇颈龙？",a="黑海岸蛇颈龙游弋在奥伯丁之外的近海海域以及附近的海岸沿线，只要游过碎浪区就能轻松找到它们。",al={"蛇颈龙在哪里","蛇颈龙眼球的来源","蛇颈龙的位置"}},{q="嗡鸣盒411号修好后会发生什么？",a="一旦嗡鸣盒411号重新轰鸣起来，维兹班恩·曲针会在静电声中向你致谢，然后再灌下一杯酒，并立刻询问你是否愿意修理他的下一台机器：嗡鸣盒323号。",al={"下一个嗡鸣盒","嗡鸣盒411号之后是什么","嗡鸣盒任务链"}}},fx={e6ddd018={q="维兹班恩·曲针为何要修理411号甲虫盒？",a="维兹班恩·曲针正沿着黑海岸修复他的自动通讯设备网络。他远程维护这些机器，同时依靠路过的冒险者提供当地的有机部件，让他能在不耽误营地饮酒的情况下，使荒野各处的装置持续运转。",al={"维兹班恩的动机","为何要修理411号甲虫盒","维兹班恩为何需要这个"}},b4fb6bd9={q="黑海岸的碎浪者是什么？",a="黑海岸碎浪者是掠食性海兽，出没于奥伯丁外寒冷的沿岸水域。它们感官敏锐，拥有多枚适合浑浊深水环境的眼部透镜；其生物部件恰好具有维兹班恩校准411号甲虫盒机械装置所需的特殊光学性质。",al={"黑海岸碎浪者","碎浪者是谁","碎浪者是什么"}},["5ee0d229"]={q="维兹班恩为何需要你帮忙，而不是自己动手？",a="维兹班恩是个古怪的机械师，显然更喜欢待在舒适的工坊里，喝着源源不断的爬行者酒，而不是冒险涉入冰冷的海浪。沿岸水域有危险的碎浪者出没，把狩猎和现场维修交给能干的冒险者，便能让他扩展网络而不必离开自己的座位。",al={"为何让我修理411号甲虫盒","维兹班恩为何不自己动手","维兹班恩为何需要冒险者"}}},fp="11,290,24.527.0,21.473.0,20.227.0,27.259.0,38.285.0,29.111.0,36.138.0,40.182.0"}
P.entries["quest:1002"] = {n="传声盒323号",s="嗡鸣装置323是黑海岸沿岸的一项实地考察任务，是考察链中的第三环，由古怪的侏儒工程师维兹班恩·曲针通过扬声器装置委托。玩家必须从当地的捕食者身上收集月夜猛虎的牙齿，并将它们放入奥伯丁以北那个嗡嗡作响的机器中。",h="嗡鸣装置323是黑海岸沿岸的一项实地考察任务，是考察链中的第三环，由古怪的侏儒工程师维兹班恩·曲针通过扬声器装置委托。玩家必须从当地的捕食者身上收集月夜猛虎的牙齿，并将它们放入奥伯丁以北那个嗡嗡作响的机器中。",kw={"奥伯丁","嗡鸣装置","嗡鸣装置323","曲针","黑海岸","牙齿","月夜猛虎","维兹班恩"},ang={["profession:Engineering"]="嗡鸣装置系列展示了自动化材料处理与远程语音中继相结合的技术，尽管其运行粗糙，但仍是一项令人印象深刻的技术设计。",["race:Gnome"]="维兹班恩的远程声学通信网络展示了典型的侏儒工程天赋——尽管他个人的纪律实在令人不敢恭维。",["race:NightElf"]="虽然当地的暗夜精灵对凶猛的月夜猛虎怀有敬畏和谨慎，但侏儒科学却将它们致命的牙齿变成了粉碎的机器燃料。"},sec={{t="一段含糊不清的传送",b="在操作了更南边的嗡鸣装置411之后，侏儒发明家维兹班恩·曲针的声音通过扬声器传了出来。维兹班恩的声音中夹杂着狂饮和醉话，他指引冒险者前往奥伯丁以北，指向一座道路桥附近的嗡鸣装置323。他的研究需要六颗月夜猛虎的牙齿，这些牙齿必须从漫游在黑海岸阴暗森林中的凶猛猫科猎手身上获取。"},{t="侏儒野外机械",b="接近嗡鸣装置323时，会发现这台机器在维修开始前就伴随着静电干扰和模糊的嘀咕声。一旦将所需的牙齿放入进料斗，机器就会猛烈地颤动并启动，嘈杂地将牙齿粉碎成灰。维兹班恩醉醺醺的声音立刻又通过对讲机传了出来，他在庆祝交付任务后，随即催促旅行者前往他散布在各处的网络中的下一台机器。"}},faq={{q="嗡鸣装置323在哪里？",a="嗡鸣装置323矗立在奥伯丁以北的主路旁，就在黑海岸当地河流的跨河桥附近。",al={"嗡鸣装置323位置","嗡鸣装置323在哪里","寻找嗡鸣装置323"}},{q="是谁在通过嗡鸣装置说话？",a="这个声音属于维兹班恩·曲针，他是一位驻扎在黑海岸其他地方的侏儒发明家，在豪饮麦芽酒的同时通过远程发射器进行交流。",al={"谁在嗡鸣装置里说话","嗡鸣装置侏儒","维兹班恩·曲针"}},{q="嗡鸣装置323如何处理这些牙齿？",a="将月夜猛虎的牙齿放入后，内部齿轮会立即将其磨成细粉，作为维兹班恩自动化生物采样机制的一部分。",al={"牙齿怎么处理","为什么需要月夜猛虎的牙齿","嗡鸣装置粉碎"}},{q="我在哪里可以在黑海岸找到月夜猛虎？",a="月夜猛虎及其幼崽在奥伯丁南北两侧道路旁的阴凉林地和山丘中出没。",al={"月夜猛虎在哪里","月夜猛虎的牙齿刷取","月夜猛虎位置"}},{q="嗡鸣装置323之前和之后的任务是什么？",a="这项任务紧随嗡鸣装置411（需要收集刺喉鱼的眼睛）之后，并直接指向嗡鸣装置525，该任务会让你去收集远在南边沿路上的蓟熊的灰白头皮。",al={"嗡鸣装置任务链","嗡鸣装置323之后是什么","嗡鸣装置顺序"}},{q="为什么维兹班恩听起来语无伦次？",a="维兹班恩在发出指令时喝得酩酊大醉，他会在句子中间停下来寻找麦芽酒，并不时大声吞咽。",al={"为什么维兹班恩喝醉了","嗡鸣装置声音含糊"}}},fx={c1fdd18c={q="维兹班恩为何要把月夜猛虎的獠牙放进323号甲虫盒？",a="维兹班恩·曲针正逐一维护散布在黑海岸的自动甲虫盒采样机器。每台装置都用于处理当地野生动物的部件，而323号甲虫盒需要六颗月夜猛虎獠牙，以校准内部研磨装置并继续其神秘的野外工作。",al={"为何要修理323号甲虫盒","维兹班恩与甲虫盒的目的","为何需要月夜猛虎獠牙"}},["78de9795"]={q="你被派去猎杀的月夜猛虎是什么？",a="月夜猛虎是原生于黑海岸幽暗森林的隐秘剑齿虎。它们在古代遗迹和盘根错节的林地间徘徊，借着永恒的暮色掩护捕猎，也会袭击那些远离奥伯丁守卫道路的旅人。",al={"月夜猛虎是什么","黑海岸月夜猛虎","要猎杀的目标是什么"}}},fp="11,309,22.428.0,23.419.0,29.122.0,36.168.0,40.165.0,43.119.0,46.189.0,37.131.0"}
P.entries["quest:1003"] = {n="传声盒525号",s="嗡嗡机525是分布在黑海岸沿岸的一系列通讯机器中的最后一台。这台装置由古怪的侏儒技师维兹班恩·曲针发明，它需要收集动物残骸来维持运作，并向旅行者索要越来越多的奇特维修材料。",h="嗡嗡机525是分布在黑海岸沿岸的一系列通讯机器中的最后一台。这台装置由古怪的侏儒技师维兹班恩·曲针发明，它需要收集动物残骸来维持运作，并向旅行者索要越来越多的奇特维修材料。",kw={"奥伯丁","嗡嗡机525","黑海岸","灰色头皮","蓟熊","蓟熊啤酒","维兹班恩·曲针"},ang={["race:Gnome"]="维兹班恩的多功能收发器展示了典型的侏儒式雄心，将复杂的工程学与令人质疑的实际优先级结合在了一起。",["race:NightElf"]="黑海岸严谨的托管政策对鲁莽的侏儒式修补几乎没有什么耐心。"},sec={{t="一段含糊的传讯",b="在维护过嗡嗡机323之后，旅行者会收到从机器嘎吱作响的扬声器中直接广播出的含糊指令。维兹班恩·曲针的言语变得越来越含糊不清，充斥着醉酒后的傻笑和漫无边际的指引，这些指引指向黑海岸主路遥远的南方。他指挥助手们去猎杀当地的灰鬃蓟熊，并将四块厚实的头皮放入嗡嗡机525的舱室中。这台机器被小心地隐藏在路边灌木丛的栅栏后。"},{t="蒸馏师的秘密",b="当来到这台隐藏的机器旁时，机器好奇的嗡嗡声被铁皮内传出的吵闹歌声所淹没。当灰鬃熊的头皮被放入接收器时，维兹班恩终于吐露了他这个网络的真相。这些装置远不止是通讯设备：它们同时也是自动化的微型酿酒厂和蒸馏器。因为暗夜精灵并不赞赏他在城镇中进行的酒类贸易，所以这个侏儒把他的装置隐藏在荒野中，利用收集来的动物残骸（如熊头皮）来酿造强劲的“蓟熊啤酒”。"}},faq={{q="嗡嗡机525位于何处？",a="嗡嗡机525位于奥伯丁南下的主路远方。维兹班恩把它藏在路边的一条简陋栅栏线附近，半掩在灌木丛中。",al={"嗡嗡机525位置","嗡嗡机525在哪里","嗡嗡机525寻找"}},{q="为什么维兹班恩想要灰鬃头皮？",a="维兹班恩声称需要这些头皮来维修嗡嗡机525，就像之前的机器需要陆行鸟腿、刺喉鱼眼和月夜枭尖牙一样。从机器中传出的关于蓟熊啤酒的醉酒歌声暗示了它的另一个目的。",al={"为什么需要灰鬃头皮","嗡嗡机熊头皮","头皮有什么用"}},{q="为什么维兹班恩要把嗡嗡机隐藏在荒野中？",a="维兹班恩把这些机器放置在奥伯丁之外，并依靠旅行者来找到它们。最后一台嗡嗡机揭示了他选择这些隐蔽地点的理由。",al={"为什么嗡嗡机被隐藏","为什么要隐藏嗡嗡机","维兹班恩的秘密"}},{q="是谁在通过嗡嗡机说话？",a="这个声音属于维兹班恩·曲针，一位富有进取心的侏儒技师，他在整个黑海岸的嗡嗡机中都安装了语音发射器。",al={"谁在嗡嗡机里说话","嗡嗡机声音","维兹班恩身份"}},{q="维兹班恩可以在没有头皮的情况下通过机器说话吗？",a="可以。在放入头皮之前，维兹班恩就能通过机器说话。关于所需材料的解释会在任务完成后给出。",al={"嗡嗡机坏了吗","维兹班恩撒谎了吗"}},{q="嗡嗡机唱的是什么歌？",a="在你放入头皮之前，扬声器会反复吟唱一段醉酒后的顺口溜：“虽然陆行鸟酒甜美，刺喉鱼麦酒亦精良，月夜枭私酿更是棒。但我最爱蓟熊酒，不日便能装满缸！”",al={"嗡嗡机唱歌","蓟熊啤酒之歌"}}},fx={["7fe06fd4"]={q="你被派去为525号甲虫盒猎取什么？",a="维兹班恩需要粗壮的熊皮头颅来维持甲虫盒运转。",al={"为525号甲虫盒要杀什么","525号甲虫盒的目标","黑海岸粗壮的棘熊"}},["4f91b84e"]={q="维兹班恩为何不让哨兵收集熊头皮，而要找你？",a="维兹班恩依靠能够抵达偏僻装置并收集所需动物部件的旅人。他会在工作完成后解释自己为何选择这些地点。",al={"为何不找哨兵帮忙","维兹班恩为何需要我修理甲虫盒","为何让冒险者修理甲虫盒"}}},fp="11,287,22.492.0,22.580.1,29.164.0,38.233.1,58.145.1,36.144.0,57.148.1,32.255.0"}
P.entries["quest:1007"] = {n="远古雕像",s="塔尔伦，一位在灰谷西北部危险的佐拉姆海岸附近扎营的精灵，正在寻求找回一件遗失的圣物。在遭到凶残的娜迦伏击并搁浅后，他不慎将珍贵的古代雕像掉在了浪潮边，急需一位冒险者从废墟中将其取回。",h="塔尔伦，一位在灰谷西北部危险的佐拉姆海岸附近扎营的精灵，正在寻求找回一件遗失的圣物。在遭到凶残的娜迦伏击并搁浅后，他不慎将珍贵的古代雕像掉在了浪潮边，急需一位冒险者从废墟中将其取回。",kw={"古代雕像","灰谷","娜迦","佐拉姆废墟","鲁泽尔","塔尔伦","佐拉姆海岸"},ang={["faction:Alliance"]="推进灰谷的联盟部队不仅面临来自东部部落哨所的威胁，还面临着盘踞在西部海岸线的敌对娜迦的威胁。",["race:NightElf"]="佐拉姆废墟代表了在大分裂前失落的卡多雷文明，因此保护像古代雕像这样的文物，实际上是在守护祖先的记忆。"},sec={{t="海岸伏击",b="灰谷西北岸边沉没的佐拉姆废墟长期以来一直吸引着那些对古代暗夜精灵历史感到好奇的人们。塔尔伦当时正驾着小船在浅滩航行，突然敌对的娜迦浮出水面，用利爪和三叉戟向他发起猛攻。他设法带着仅存的补给爬上岸，匆忙扎营，但在绝望的逃生过程中，他最珍贵的发现掉进了沙子里。"},{t="古老佐拉姆的秘密",b="被遗弃在沙滩上的一半掩埋在沙中的古代雕像不仅仅是一件简单的纪念品。在塔尔伦看来，这正是他冒险进入这片怪物出没的佐拉姆海岸的全部理由。一旦找回它，他便揭示了这座沉没的城市隐藏着几个世纪以来被遗忘的秘密，而这件精致的雕刻品正是解开潮汐之下隐藏真相的关键。"}},faq={{q="塔尔伦是谁，为什么他独自待在海岸上？",a="塔尔伦是一位在佐拉姆海岸南缘扎营的精灵探险家。出于对历史的好奇，他前来探索佐拉姆的沉没废墟，却在遭到凶残娜迦伏击后搁浅。",al={"塔尔伦是谁","塔尔伦背景故事","塔尔伦灰谷"}},{q="塔尔伦在哪里弄丢了古代雕像？",a="塔尔伦在营地北边的海岸附近弄丢了雕像。它正半掩在沙子里，就在他船只遇袭的浪潮边，靠近一艘倾覆的船和一棵倒下的树。",al={"古代雕像在哪里","雕像位置","寻找古代雕像"}},{q="古代雕像是什么？",a="这是一件从佐拉姆沉没废墟中打捞出来的古代暗夜精灵圣物。据塔尔伦所说，这件雕刻品具有历史和神秘学意义，是揭开这座沉没城市未解之谜的关键钥匙。",al={"什么是古代雕像","雕像的意义"}},{q="为什么佐拉姆海岸会有娜迦？",a="灰谷的海岸线包含着万年前沉入大海的远古大分裂前的精灵遗迹。娜迦已将佐拉姆的沉没建筑据为己有，并积极在海滩上巡逻，抵御外来者。",al={"为什么这里有娜迦","佐拉姆海岸的娜迦","灰谷的娜迦"}},{q="交还雕像后会发生什么？",a="找回古代雕像让塔尔伦能够破译该地区更多的秘密。然而，应对海岸沿线的娜迦威胁需要进一步的行动，他会引导你去对付他们的首领，鲁泽尔。",al={"交还雕像后的后续","任务后续"}},{q="雕像有人看守吗？",a="古代雕像位于水边，那里充斥着敌对的娜迦战士和岸上的潜行野兽，使得单枪匹马的漫游者取回它变得十分危险。",al={"雕像有守卫吗","雕像附近的敌人"}}},fx={["16a428a2"]={q="塔尔伦为何想要取回古代雕像？",a="这尊古代雕像是塔尔伦最珍贵的宝物，也是他冒险前往危险的佐拉姆海岸的全部原因。他相信佐拉姆古代的水下遗迹藏有重大秘密，而这件遗物或许正是揭开秘密的关键。他在遭纳迦伏击后侥幸逃生，却无法忍受把毕生追寻之物留在沙滩上。",al={"塔尔伦为何想要古代雕像","塔尔伦的动机","塔尔伦为何需要古代雕像"}},ceee75b8={q="塔尔伦为何不能亲自取回雕像？",a="塔尔伦在水上的第一次遭遇中险些丧命。纳迦从深处蜂拥而出，用利爪撕碎了他的小船；他只带着少量补给仓皇爬上岸，随后惊恐逃离。他惊魂未定、身负伤势，又没有任何战斗支援，在这片偏远海岸上根本无法对付潜伏在岸边的野兽和凶悍的纳迦，取回自己掉落的东西。",al={"塔尔伦为何不能自己取回","塔尔伦为何需要我帮忙","塔尔伦为何需要帮助"}}},fp="21,275,19.422.0,20.368.0,47.222.0,35.181.0,30.229.0,39.241.0,43.204.1,25.167.0"}
P.entries["quest:1008"] = {n="佐拉姆海岸",s="来自阿斯特兰纳的辛德瑞尔·速火指派联盟勇士去清剿灰谷西北海岸，那里坐落着一座古老的废墟之城。纳迦大举现身于佐拉姆海岸，企图从海上向内陆推进。阻止它们的立足，将保护这片森林免受暗夜精灵遥远过去的阴影侵扰。",h="来自阿斯特兰纳的辛德瑞尔·速火指派联盟勇士去清剿灰谷西北海岸，那里坐落着一座古老的废墟之城。纳迦大举现身于佐拉姆海岸，企图从海上向内陆推进。阻止它们的立足，将保护这片森林免受暗夜精灵遥远过去的阴影侵扰。",kw={"灰谷","阿斯特兰纳","纳迦","辛德瑞尔","海岸","大分裂","速火","怒鳞","佐拉姆"},ang={["class:Hunter"]="饱受风霜的海岸和破败的废墟提供了绝佳的制高点，可以追踪那些从浪潮中涌现的两栖突袭者。",["faction:Alliance"]="保卫灰谷的西翼可以防止阿斯特兰纳陷入海岸入侵者和不断扩张的部落伐木作业之间的夹击。",["race:NightElf"]="在海岸上被杀死的每一只纳迦，都是对艾萨拉的傲慢以及摧毁了古老世界的大分裂的残酷提醒。哨兵们绝不会允许这些扭曲的同族在卡利姆多重新获得立足之地。"},sec={{t="岸边的阴影",b="在阿斯特兰纳的西北方，灰谷浓密的树冠与无尽之海交汇处，有一片被风吹拂的海岸，被称为佐拉姆海岸。这里曾长期静谧，散落着一万年前分崩离析的文明所留下的惨白石块，如今却突然涌现出无数蛇形怪物。怒鳞纳迦从黑暗的潮汐中滑行而出，在暗夜精灵领地的边缘建立起了一个充满敌意的滩头堡。"},{t="佐拉姆的沉没之城",b="在汹涌的波涛之下，沉睡着注定毁灭的佐拉姆城，它在天崩地裂中破碎并沉入海底。长久以来，它只是一处被遗弃的遗迹，几乎被卡多雷遗忘。纳迦在废墟中的突然出现，勾起了阿斯特兰纳守卫者们痛苦的回忆。像辛德瑞尔·速火这样的哨兵认出，这些蛇形入侵者是她们自己古老灾难所衍生的扭曲同族，她们绝不允许深海再次占领这片海岸。"}},faq={{q="佐拉姆海岸是什么？",a="佐拉姆海岸是灰谷崎岖的西北海岸线，面朝无尽之海。这里是古老佐拉姆的所在地，这是一座在一万年前的大分裂中被海洋吞没的卡多雷城市。",al={"佐拉姆海岸","佐拉姆海岸在哪里","什么是佐拉姆"}},{q="纳迦为什么要攻击灰谷的海岸？",a="它们的具体动机对阿斯特兰纳的哨兵来说仍然是个谜。无论是什么将它们从深渊中引出，它们的军事营地和侵略行为都已对森林构成了直接威胁，迫使暗夜精灵不得不先发制人。",al={"为什么纳迦在这里","纳迦在佐拉姆的动机","为什么要对付怒鳞纳迦"}},{q="辛德瑞尔·速火是谁？",a="辛德瑞尔·速火是一位驻扎在阿斯特兰纳中心的暗夜精灵哨兵。她负责监控灰谷地区的威胁，并组织对敌对入侵者的打击，包括海岸上的纳迦。",al={"辛德瑞尔","阿斯特兰纳任务发布者","速火"}},{q="暗夜精灵与纳迦有什么共同的历史？",a="纳迦曾经是效忠于艾萨拉女王的上层精灵。当大分裂期间永恒之井坍塌时，她们被拖入深渊之底并转化为了蛇形生物，这使得现代卡多雷在每次遭遇时都感到无比苦涩。",al={"纳迦与精灵的联系","与纳迦的历史","共同的历史"}},{q="清理完佐拉姆海岸后会发生什么？",a="在削弱了海岸上的纳迦力量后，辛德瑞尔·速火会将联盟防御者调往别处，以处理沿边境出现的其他空中威胁，并派遣侦察兵向南前往石爪山脉，以对付凶猛的傲翼兽。",al={"下一个任务","佐拉姆海岸之后做什么","傲翼兽"}},{q="部落也出现在佐拉姆海岸了吗？",a="是的。当联盟勇士从阿斯特兰纳出发猎杀海岸上的纳迦时，部落在海岸线上维持着一个名为佐拉姆加前哨站的军事据点，争夺该地区并同时与纳迦和联盟交战。",al={"佐拉姆海岸的部落","佐拉姆加","部落在那里吗"}}},fx={a15c1f29={q="辛德瑞尔·速火为什么要杀死纳迦？",a="辛德瑞尔认为，聚集在佐拉姆海岸的纳迦对灰谷西北边境构成了直接威胁。沉没的佐拉姆城遗迹承载着天崩地裂之战的惨痛记忆；无论这些蛇身族为何怀着黑暗目的重返海岸，暗夜精灵都不会任由他们在圣地站稳脚跟。杀死他们并夺取其头颅，旨在挫败他们的推进，将他们赶回深海，以免入侵进一步深入内陆。",al={"为什么要杀死佐拉姆的纳迦","辛德瑞尔·速火的动机","辛德瑞尔为什么要纳迦的头颅"}},["99414e89"]={q="你奉命去佐拉姆海岸猎杀谁？",a="你奉命猎杀从迷雾之海爬上佐拉姆海岸的怒尾纳迦。这些蛇身族已在沉没的精灵遗迹周围建立了敌对营地，威胁着灰谷北部的荒野。辛德瑞尔要求你带回被斩下的头颅作为他们战败的证据，希望在暗夜精灵的宿敌逼近阿斯特兰纳之前，削弱他们的入侵力量。",al={"怒尾纳迦","佐拉姆海岸要杀谁","佐拉姆海岸的目标"}}},fp="16,336,20.424.0,25.483.0,25.210.0,45.244.0,27.208.0,52.267.0,45.220.1,46.228.0"}
P.entries["quest:1009"] = {n="卢泽尔",s="“Ruuzel”是一项联盟任务，由位于灰谷佐拉姆海岸边缘的塔尔伦提供。在从海岸寻回一座古代暗夜精灵雕像后，探险者们被派往从娜迦领袖Ruuzel手中夺取佐拉姆之戒，以解开雕像上封印的秘密。",h="“Ruuzel”是一项联盟任务，由位于灰谷佐拉姆海岸边缘的塔尔伦提供。在从海岸寻回一座古代暗夜精灵雕像后，探险者们被派往从娜迦领袖Ruuzel手中夺取佐拉姆之戒，以解开雕像上封印的秘密。",kw={"灰谷","娜迦","佐拉姆之戒","ruuzel","大分裂","塔尔伦","佐拉姆海岸"},ang={["faction:Alliance"]="通过击杀Ruuzel并帮助塔尔伦，联盟部队削弱了在灰谷北部登陆的娜迦威胁。",["race:NightElf"]="找回佐拉姆之戒，是从亵渎先祖沉没遗迹的娜迦手中夺回的一份祖先遗产。"},sec={{t="佐拉姆之钥",b="在大分裂将卡利姆多撕裂，并将其宏伟的沿海城市沉入海底之前，佐拉姆城由强大的暗夜精灵贵族统治。在他们所有的传家宝中，最重要的是佐拉姆之戒，塔尔伦认为这是解开那座古代雕像锁的关键。大灾变之后，这枚戒指在海潮中失落了数千年，使得沉没遗迹的秘密免受好奇之眼的窥探。"},{t="娜迦的入侵",b="随着娜迦近期抵达佐拉姆海岸，这些蛇形入侵者开始搜寻他们前家园的废墟。Ruuzel是领导当地族群的女族长，她成功发掘了佐拉姆之戒，并将其带到了北边岛屿上的巢穴中。为了解开从浅滩中拖出的雕像，暗夜精灵塔尔伦委托联盟的旅行者去追捕Ruuzel并找回这件古代传家宝。"}},faq={{q="Ruuzel是谁？",a="Ruuzel是占据灰谷西北部佐拉姆海岸的娜迦领袖。她在北边的一座近海岛屿上筑巢，守护着沉没的暗夜精灵文明中打捞出来的宝藏。",al={"ruuzel背景故事","娜迦领袖是谁","ruuzel首领"}},{q="什么是佐拉姆之戒？",a="佐拉姆之戒是大分裂前佐拉姆古代统治者所持有的附魔传家宝。塔尔伦认为它是打开古代雕像锁的关键。",al={"佐拉姆之戒背景故事","戒指的作用","佐拉姆之钥"}},{q="塔尔伦为什么要这枚戒指？",a="塔尔伦试图揭开最近从海岸上找回的一座古代卡多雷雕像中的秘密。这件神器上有一把锁，只有佐拉姆之戒才能打开。",al={"为什么获取佐拉姆之戒","塔尔伦雕像锁"}},{q="佐拉姆城去了哪里？",a="佐拉姆是一座古代卡多雷城市，在一万年前的大分裂中被摧毁。它大部分宏伟的石构建筑都塌陷到了幕帘海中，只剩下分散的海岸遗迹。",al={"佐拉姆发生了什么","佐拉姆遗迹"}},{q="Ruuzel在哪里？",a="Ruuzel居住在佐拉姆海岸北缘外的一座大型岩石岛屿上，周围簇拥着她的蛇形追随者。",al={"ruuzel在哪里","ruuzel岛屿位置"}},{q="找回戒指后会发生什么？",a="将戒指交还给塔尔伦即可完成他在海岸上的调查。感谢你为解开神器秘密提供的帮助，他会给予你奖励并铭记你的贡献。",al={"塔尔伦下一步做什么","ruuzel后续"}}},fp="6,260,16.406.0,18.448.0,14.207.0,26.168.0,29.180.0,31.192.0,24.120.0,39.172.0"}
P.entries["quest:101"] = {n="惩罚图腾",s="夜色镇的伊瓦夫人向途径这片阴影笼罩的森林的旅行者们提供制作一种被称为惩罚图腾的防护结界。通过采集这片区域内潜伏的食尸鬼、骷髅和剧毒蜘蛛的遗骸，她附魔制作出一件能够反击攻击者的护符。这项任务既是一场严酷的生存考验，也是一种针对暮色森林无处不在的黑暗的迷信保障。",h="夜色镇的伊瓦夫人向途径这片阴影笼罩的森林的旅行者们提供制作一种被称为惩罚图腾的防护结界。通过采集这片区域内潜伏的食尸鬼、骷髅和剧毒蜘蛛的遗骸，她附魔制作出一件能够反击攻击者的护符。这项任务既是一场严酷的生存考验，也是一种...",kw={"夜色镇","暮色森林","食尸鬼獠牙","伊瓦夫人","防护结界","骷髅手指","蜘蛛毒液","惩罚图腾"},ang={["class:Paladin"]="圣骑士可能会对用亡灵骨头和蜘蛛毒液组装结界的行为侧目而视，但在暮色森林沉重的阴霾中，即使是圣职战士有时也必须面对务实的民间巫术。",["class:Priest"]="虽然圣光教会的教义强调信仰和虔诚，但像伊瓦夫人这样的民间女巫则是通过触手可及的冷酷护身符来引导精神意志。",["class:Warlock"]="术士们会很容易认出编织在伊瓦防护护符中的反击诅咒原则。",["faction:Alliance"]="在一个与主要军事增援隔绝的边境地区，联盟旅行者经常依赖像伊瓦夫人这样的当地神秘学家的民间护符和结界来忍受森林的恐怖。"},sec={{t="血腥的命运",b="在夜色镇烛光摇曳的住所里，伊瓦夫人透过面纱窥视着那些踏入她门槛的人的命运。她察觉到即将来临的危险和暴力正在地平线上静候，因此她提供的不仅仅是简单的占卜，而是实用的巫术。通过从闹鬼的丛林中收集十颗食尸鬼獠牙、十根骷髅手指和五瓶蜘蛛毒液，冒险者提供了制作防护结界以抵御暮色森林中贪婪掠食者所需的原材料。"},{t="伊瓦的附魔",b="伊瓦夫人通过附魔将浸透了坏死饥渴的食尸鬼獠牙、从不安分的死者身上夺来的手指骨以及强效的蜘蛛毒液编织在一起。当在面临致命危险时紧握此图腾，它会散发出一种旨在反映残酷性的魔法光环，对任何愚蠢到攻击其持有者的人造成精神和肉体上的伤害。"}},faq={{q="伊瓦夫人是谁？",a="伊瓦夫人是一位居住在饱受战火蹂躏的夜色镇的算命师和神秘学家。她为当地人和过往的冒险者解读预兆并酿制防护结界，帮助他们努力在暮色森林超自然的危险中幸存下来。",al={"伊瓦夫人","谁发布了这个任务","伊瓦 夜色镇"}},{q="惩罚图腾的用途是什么？",a="这枚图腾是一件旨在抵御袭击者的附魔护身符。在受到威胁时握住它，其魔法会对那些企图对持有者实施暴力行为的敌对目标进行反击。",al={"惩罚图腾的用途","图腾有什么作用","图腾背景故事"}},{q="为什么伊瓦夫人需要食尸鬼獠牙、骷髅手指和蜘蛛毒液？",a="通过利用森林中最具侵略性的怪物的解剖学武器和遗骸——食尸鬼的噬咬、骷髅的抓握利爪以及蛛形纲生物的毒液，伊瓦制作出了一种防护性的反击附魔。",al={"为什么要蜘蛛毒液","图腾制作材料","为什么要骷髅手指"}},{q="图腾的组件在哪里可以找到？",a="这些组件是从出没在暮色森林的亡灵和野兽身上采集的。骷髅和食尸鬼在整个地区的墓地和闹鬼的果园中徘徊，而大型的剧毒蜘蛛则在整个阴影笼罩的森林中筑巢。",al={"哪里找到獠牙","在哪里获得材料","食尸鬼和蜘蛛在哪里"}},{q="伊瓦夫人预见了什么危险？",a="伊瓦警告说，低语的风声诉说着不久的将来潜伏着的威胁，她特别告知冒险者，她预见到了他们未来的道路上将有大规模的流血事件。",al={"伊瓦的预言","会有什么危险","未来的流血事件"}},{q="制作这种图腾被视为黑魔法吗？",a="虽然用尸体部位和毒液制作物品的做法接近于暗影魔法，但在暮色森林这种绝望的环境中，民间的篱笆巫术和防护护符是被广泛接受的抵御周围恐怖事物的自卫方法。",al={"这是死灵法术吗","伊瓦是邪恶的吗","黑魔法图腾"}}},fx={c4af218f={q="伊瓦夫人为什么想要制作惩罚图腾？",a="伊瓦夫人仔细聆听风中的低语，预见到不久的将来有一场巨大的暴力灾祸正耐心等待着你。弥漫而来的神秘腐化威胁着整个暮色森林，而她提出制作惩罚图腾，正是为了保护你免遭她在你的命运中预见的那场迫近的血腥冲突。",al={"伊瓦夫人的动机","为什么制作惩罚图腾","伊瓦为什么帮助我"}}},fp="23,410,22.481.0,17.348.0,18.228.0,47.173.0,73.214.0,45.220.0,36.181.0,44.237.0"}
P.entries["quest:1010"] = {n="巴斯兰的头发",s="“巴斯兰的头发”是一项由灰谷西部的迈斯特拉岗哨的奥雷迪尔·阔叶提供的联盟任务。由于一位暗夜精灵儿童身患一种超越了肉体层面的神秘疾病，情况危急，奥雷迪尔派遣冒险者前往北部的巴斯兰鬼屋古迹，寻找一种以疗愈精神创伤而闻名的恢复性植物。",h="“巴斯兰的头发”是一项由灰谷西部的迈斯特拉岗哨的奥雷迪尔·阔叶提供的联盟任务。由于一位暗夜精灵儿童身患一种超越了肉体层面的神秘疾病，情况危急，奥雷迪尔派遣冒险者前往北部的巴斯兰鬼屋古迹，寻找一种以疗愈精神创伤而闻名的恢复...",kw={"灰谷","巴斯兰的头发","巴斯兰鬼屋","黑海岸","被遗忘者","迈斯特拉岗哨","奥雷迪尔·阔叶","植物捆"},ang={["faction:Alliance"]="为阿斯特兰纳的孩子获取药物，加强了防守灰谷西部的前线定居点，以抵御敌对部落和被遗忘者的扩张。",["profession:Herbalism"]="散布在巴斯兰鬼屋各处的植物捆可以通过寻找草药技能识别，这使得在废墟中的搜索变得容易得多。",["race:NightElf"]="被遗忘者在巴斯兰鬼屋的入侵对灰谷北部神圣的边界以及当地儿童的福祉构成了严重威胁。"},sec={{t="精神之疾",b="在黑海岸边界以南的迈斯特拉岗哨，暗夜精灵草药师奥雷迪尔·阔叶正面临一场棘手的医疗危机。阿斯特兰纳的一名幼童身患重病，其症状无法用普通的物理疗法缓解。奥雷迪尔确信这不仅仅是肉体上的疾病，而是折磨着孩子的精神，因此他寻求“巴斯兰的头发”，这是一种不常见的恢复性草药，历史上一直生长在北部的古代精灵遗迹中。"},{t="遗迹中的闯入者",b="搜索行动将冒险者引向了巴斯兰鬼屋。那是一处位于通往黑海岸的道路东侧的废墟。收集这些成捆的草药并非易事，因为被遗忘者特工已经渗透进了这座古老的遗迹。将草药带回后，奥雷迪尔能够调制出一剂舒缓的药水，但发现亡灵公然在灰谷北部活动，令这位草药师深感不安。"}},faq={{q="什么是巴斯兰的头发？",a="“巴斯兰的头发”是一种原产于灰谷巴斯兰鬼屋废墟的稀有药用植物。暗夜精灵草药师重视它的强大恢复能力，特别是它能够舒缓和治愈影响精神而非普通肉体创伤的疾病。",al={"巴斯兰的头发植物","什么是巴斯兰的头发","巴斯兰草药"}},{q="迈斯特拉岗哨里谁生病了？",a="岗哨里没有人。患者是阿斯特兰纳的一名暗夜精灵幼童瑞拉拉·怀特姆恩，她是皮尔图拉斯·怀特姆恩的女儿。孩子的病情每况愈下，普通疗法已宣告失败，因为这种疾病似乎源于精神层面，这促使奥雷迪尔·阔叶去寻找古代的植物辅助治疗。",al={"迈斯特拉生病的孩子","奥雷迪尔在治疗谁","谁需要治疗"}},{q="巴斯兰鬼屋在哪里？",a="巴斯兰鬼屋位于灰谷西北部，在迈斯特拉岗哨以北，通往黑海岸边界的主路以东。这些遗迹被怀有敌意的被遗忘者特工所占据。",al={"巴斯兰鬼屋位置","哪里寻找巴斯兰的头发","巴斯兰在哪里"}},{q="为什么巴斯兰鬼屋会有被遗忘者？",a="没人知道他们在图谋什么。奥雷迪尔只有在草药送回后才得知他们的存在。亡灵潜伏在暗夜精灵领地如此深处，这让他感到非常不安。",al={"巴斯兰的亡灵","为什么被遗忘者在灰谷","巴斯兰鬼屋的被遗忘者"}},{q="收集到这种植物后会发生什么？",a="一旦带回五捆草药，奥雷迪尔就会准备一份药剂，并要求你立即将其送到阿斯特兰纳给那个生病的孩子，从而开启后续任务“奥雷迪尔的药剂”。",al={"巴斯兰的头发后续任务","奥雷迪尔如何使用巴斯兰的头发","奥雷迪尔的药剂任务线"}},{q="草药师能更容易地找到植物捆吗？",a="是的。装有采摘植物的植物捆散落在地面上，肉眼可能难以发现，但受过草药学训练的冒险者可以使用寻找草药技能探测到它们。",al={"巴斯兰的头发草药学","追踪巴斯兰的头发","植物捆追踪草药"}}},fx={b8c70a70={q="奥雷迪尔·阔叶为什么想要巴斯兰的头发？",a="阿斯特兰纳有个孩子病得很重，奥雷迪尔·阔叶担心病症伤害的不只是身体。他相信孩子的灵魂本身也受到了侵袭，因此需要巴斯兰的头发来调制一种特殊药剂，在疾病夺去孩子性命之前治愈灵魂的创伤。",al={"奥雷迪尔为什么需要巴斯兰的头发","奥雷迪尔·阔叶的动机","为什么帮助奥雷迪尔"}}},fp="14,355,24.455.0,24.413.1,23.273.0,30.323.0,33.195.0,42.162.0,40.184.1,45.209.0"}
P.entries["quest:1011"] = {n="被遗忘者的病菌",s="在灰谷东部深处，暗夜精灵侦察兵凯内斯·静风满怀忧虑地注视着步步紧逼的被遗忘者。他认为这些亡灵正在酝酿某种瘟疫来蹂躏精灵的神圣土地，于是指引联盟的勇士前往朵丹尼尔兽穴附近的营地，夺取一瓶他们研制的邪恶药剂样本。",h="在灰谷东部深处，暗夜精灵侦察兵凯内斯·静风满怀忧虑地注视着步步紧逼的被遗忘者。他认为这些亡灵正在酝酿某种瘟疫来蹂躏精灵的神圣土地，于是指引联盟的勇士前往朵丹尼尔兽穴附近的营地，夺取一瓶他们研制的邪恶药剂样本。",kw={"药剂师","灰谷","一瓶病菌","朵丹尼尔兽穴","林歌神殿","被遗忘者","被遗忘者的疾病","凯内斯·静风","暗夜精灵"},ang={["class:Druid"]="德鲁伊将兽穴视为与翡翠梦境交流的神圣之地。在朵丹尼尔附近发现瓶装瘟疫，直接触动了塞纳里奥议会的守护底线。",["faction:Alliance"]="部落的被遗忘者盟友将可怕的化学战带到了灰谷，这向联盟领导层证明了森林中的冲突已远非简单的木材边界争端。",["race:NightElf"]="对于卡多雷而言，亡灵在神圣兽穴附近的入侵是一种不可容忍的亵渎。保卫沉睡的德鲁伊和灰谷的纯净，使其免受邪恶毒素的侵害，是关乎生存与荣誉的大事。"},sec={{t="森林之祸",b="灰谷的暗夜精灵长期以来一直与萨特、狂暴的元素以及兽人的伐木队抗争，但被遗忘者的到来标志着局势的进一步恶化。这群部落的亡灵爪牙不仅砍伐树木，还在古老的遗迹和神圣的兽穴附近建立据点。他们的存在不仅带来了战争，还为纯净的卡多雷森林带来了炼金瘟疫这种可怕的阴霾。"},{t="潜入朵丹尼尔",b="在林歌神殿以南，朵丹尼尔兽穴附近，被遗忘者的药剂师和侦察兵建立了一座防御严密的营地。在那里，他们在一口口酿造大锅和肮脏的试剂中装瓶未经过测试的毒药。凯内斯·静风派遣侦察兵潜入营地，取回一瓶完好的“一瓶病菌”，以便在被遗忘者将其在森林中散布之前，分析出其不稳定的成分。"}},faq={{q="凯内斯·静风是谁？",a="凯内斯·静风是一位暗夜精灵，他在灰谷东部的林歌神殿遗迹中驻守。他监视着整个地区的敌对活动，特别关注被遗忘者构成的威胁以及兽穴附近的腐蚀势力。",al={"凯内斯·静风","谁提供被遗忘者的疾病任务","林歌神殿的任务发布者"}},{q="被遗忘者的营地在哪里？",a="被遗忘者的营地位于林歌神殿正南方，朵丹尼尔兽穴附近。亡灵部队聚集在那里，围在酿造台和帐篷周围，调制他们的生物混合物。",al={"营地在哪里","有毒药剂瓶在哪里","朵丹尼尔营地位置"}},{q="为什么被遗忘者会出现在灰谷？",a="虽然兽人进入灰谷主要是为了木材和领土，但被遗忘者的目的却是邪恶的炼金和生物实验。他们在古老的卡多雷兽穴附近活动，收集试剂并酿造有毒化合物，这引起了精灵们的恐慌，担心他们意图感染这片土地本身。",al={"为什么被遗忘者在灰谷","灰谷的亡灵","被遗忘者的动机"}},{q="取回病菌瓶后会发生什么？",a="凯内斯·静风检查了缴获的瓶子以确定其成分。他的调查直接揭示了附近朵丹尼尔兽穴中沉睡的德鲁伊们的困境，从而引出了后续任务“疯狂的德鲁伊”。",al={"接下来做什么","完成被遗忘者的疾病后","任务后续"}},{q="什么是林歌神殿？",a="林歌神殿是一处位于灰谷最东端，靠近艾萨拉边界的古老且几乎废弃的暗夜精灵遗迹。凯内斯·静风是这里唯一的居住者，并在那里指挥着该地区针对被遗忘者的战斗。",al={"林歌神殿前哨站","什么是林歌神殿"}},{q="灰谷的兽穴是什么？",a="兽穴是神圣的地下圣所，暗夜精灵德鲁伊会在其中沉睡，与翡翠梦境进行精神交流。朵丹尼尔兽穴就是其中之一，因此被遗忘者在附近的出现让卡多雷人感到格外担忧。",al={"什么是兽穴","朵丹尼尔的目的","兽穴"}}},fx={["78e58974"]={q="凯尼斯·静风为什么想要一瓶病菌？",a="凯尼斯担心被遗忘者正图谋通过在暗夜精灵的圣地传播邪恶瘟疫来腐化灰谷。他需要他们实验的实物证据，以便亲自检验这种混合物，并确认亡灵们究竟在兽穴附近炼制什么恶毒的疫病。",al={"凯尼斯为什么要这么做","凯尼斯·静风的动机","为什么要拿到一瓶病菌"}},["53e7622a"]={q="一瓶病菌有什么用？",a="瓶中装着被遗忘者药剂师在朵丹尼尔兽穴附近临时营地中调制的剧毒瘟疫混合物。凯尼斯·静风打算分析样本，揭露被遗忘者在灰谷进行生物战的真实目的和规模。",al={"一瓶病菌是什么","一瓶病菌的用途","被遗忘者的一瓶病菌"}},["1459855f"]={q="这次任务要对付谁？",a="你奉命对付一支秘密潜入灰谷的被遗忘者亡灵队伍。他们盘踞在林歌神殿以南、朵丹尼尔兽穴附近，在灰谷炼制异变瘟疫，并在古老的精灵圣地附近进行实验，威胁着森林及其守护者。",al={"我们在和谁作战","灰谷的被遗忘者敌人","营地里有谁"}}},fp="17,317,23.404.0,25.387.0,25.251.0,35.224.0,34.278.0,41.247.1,20.221.0,38.235.0"}
